export interface AtlasCsvDownloaderDependenciesV1 {
  documentRef?: Pick<Document, 'createElement'>;
  URLRef?: Pick<typeof URL, 'createObjectURL' | 'revokeObjectURL'>;
  BlobCtor?: typeof Blob;
  schedule?: typeof setTimeout;
}

/** Keep CSV serialization and browser download behavior in the application program. */
export function createAtlasCsvDownloaderV1(input: AtlasCsvDownloaderDependenciesV1 = {}) {
  const documentRef = input.documentRef ?? globalThis.document;
  const URLRef = input.URLRef ?? globalThis.URL;
  const BlobCtor = input.BlobCtor ?? globalThis.Blob;
  const schedule = input.schedule ?? globalThis.setTimeout.bind(globalThis);
  if (typeof documentRef?.createElement !== 'function' || typeof URLRef?.createObjectURL !== 'function' || !BlobCtor || typeof schedule !== 'function')
    throw new TypeError('CSV download requires document, URL, Blob, and timer services.');

  return (filename: string, columns: readonly unknown[], rows: readonly (readonly unknown[])[]) => {
    const csv = [columns, ...rows]
      .map((row) => row.map((cell) => `"${String(cell ?? '').replaceAll('"', '""')}"`).join(';'))
      .join('\n');
    const url = URLRef.createObjectURL(new BlobCtor([`\ufeff${csv}`], { type: 'text/csv;charset=utf-8' }));
    const link = documentRef.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    schedule(() => URLRef.revokeObjectURL(url), 1000);
  };
}

