export const PROPOSAL_VISION_MIME_TYPES_V1: readonly string[] = Object.freeze([...ATLAS_PROPOSAL_VISION_POLICY_V1.mimeTypes]);
export const PROPOSAL_VISION_PROMPT_V1 = String(ATLAS_PROPOSAL_VISION_POLICY_V1.prompt);

export interface AtlasPublicFieldRecordInferenceV1 {
  category: string;
  progress: number;
  title: string;
  reason: string;
  fields: Array<{ label: string; name: string; value: string }>;
}

interface AtlasPublicFieldRecordPolicyV1 {
  maxImageBytes: number;
  stageIds: Record<string, string>;
  mapNatureToStage: Record<string, string>;
  inferenceCatalog: Record<string, AtlasPublicFieldRecordInferenceV1>;
}

export const ATLAS_PUBLIC_FIELD_RECORD_POLICY_V1 = Object.freeze(publicFieldRecordPolicyData as AtlasPublicFieldRecordPolicyV1);
export const PUBLIC_FIELD_RECORD_MAX_IMAGE_BYTES_V1 = Number(ATLAS_PUBLIC_FIELD_RECORD_POLICY_V1.maxImageBytes);

/** Resolve the existing stage-based evidence suggestion without claiming an AI inference. */
export function projectAtlasPublicFieldRecordInferenceV1(stageName: unknown): AtlasPublicFieldRecordInferenceV1 {
  const key = String(stageName || 'generic');
  const row = ATLAS_PUBLIC_FIELD_RECORD_POLICY_V1.inferenceCatalog[key] || ATLAS_PUBLIC_FIELD_RECORD_POLICY_V1.inferenceCatalog.generic;
  return Object.freeze({ ...row, fields: Object.freeze(row.fields.map(field => Object.freeze({ ...field }))) as unknown as AtlasPublicFieldRecordInferenceV1['fields'] });
}

/** Convert map selection variants to a stable public-record form value. */
export function normalizeAtlasPublicFieldRecordMapAreaV1(value: unknown): (Record<string, unknown> & { partIds: string[] }) | null {
  let source = value;
  if (typeof source === 'string') {
    try { source = source ? JSON.parse(source) : null; } catch { source = null; }
  }
  if (!source || typeof source !== 'object') return null;
  const area = source as Record<string, unknown>;
  const values = Array.isArray(area.partIds) ? area.partIds : area.partId ? [area.partId] : [];
  const partIds = [...new Set(values.map(item => String(item || '').trim()).filter(Boolean))];
  return { ...area, partIds };
}

export interface AtlasPublicFieldRecordSubmissionInputV1 {
  values: Record<string, unknown>;
  selectedArea?: unknown;
  inferredFields?: readonly { label?: unknown; name?: unknown; value?: unknown }[];
  inferenceTitle?: unknown;
  photoDataUrl?: unknown;
}

export interface AtlasPublicFieldRecordDraftInputV1 {
  values: Record<string, unknown>;
  explicitArea?: unknown;
  paintedArea?: unknown;
  inferredFields: readonly { label?: unknown; name?: unknown; value?: unknown }[];
  inferenceTitle?: unknown;
}

export type AtlasPublicFieldRecordDraftResultV1 =
  | { ok: true; draft: Omit<AtlasPublicFieldRecordSubmissionInputV1, 'photoDataUrl'> }
  | { ok: false; error: string };

/** Prepare the public field-record form before image reading and command dispatch. */
export function prepareAtlasPublicFieldRecordDraftV1(input: AtlasPublicFieldRecordDraftInputV1): AtlasPublicFieldRecordDraftResultV1 {
  const values = input.values || {};
  const selectedArea = normalizeAtlasPublicFieldRecordMapAreaV1(input.explicitArea)
    || normalizeAtlasPublicFieldRecordMapAreaV1(input.paintedArea);
  const inferredFields = input.inferredFields.map(field => ({
    label: String(field.label || field.name || ''),
    name: String(field.name || ''),
    value: String(field.value || ''),
  }));
  if (!String(values.activity || '').trim() || !String(values.responsible || '').trim() || !String(values.details || '').trim())
    return { ok: false, error: 'Preencha atividade, responsável e descrição.' };
  return {
    ok: true,
    draft: {
      values,
      selectedArea,
      inferredFields,
      inferenceTitle: String(input.inferenceTitle || ''),
    },
  };
}

export interface AtlasPublicFieldRecordEvidenceContextInputV1 {
  source: 'map' | 'photo';
  nature?: unknown;
  label?: unknown;
  note?: unknown;
  currentActivity?: unknown;
}

/** Resolve the existing map/photo stage and activity suggestions as typed policy. */
export function projectAtlasPublicFieldRecordEvidenceContextV1(input: AtlasPublicFieldRecordEvidenceContextInputV1): {
  stage: string;
  applyStage: boolean;
  activity: string | null;
  evidenceTitle: string;
  evidenceDetail: string;
} {
  if (input.source === 'map') {
    const label = String(input.label || '');
    return {
      stage: ATLAS_PUBLIC_FIELD_RECORD_POLICY_V1.mapNatureToStage[String(input.nature || '')] || 'Terraplanagem',
      applyStage: true,
      activity: `Registro de progresso · ${label}`,
      evidenceTitle: 'Área vinculada',
      evidenceDetail: label || 'Área selecionada',
    };
  }
  const note = String(input.note || '').toLocaleLowerCase('pt-BR');
  const stage = note.includes('dren') ? 'Drenagem Pluvial'
    : note.includes('pav') || note.includes('asfalt') ? 'Pavimentação'
      : note.includes('terra') || note.includes('compact') ? 'Terraplanagem'
        : 'generic';
  return {
    stage,
    applyStage: stage !== 'generic',
    activity: String(input.currentActivity || '').trim() ? null : 'Evidência fotográfica de campo',
    evidenceTitle: 'Fotografia vinculada',
    evidenceDetail: String(input.label || ''),
  };
}

/** Preserve the field-record endpoint contract while normalizing UI-only evidence. */
export function projectAtlasPublicFieldRecordPayloadV1(input: AtlasPublicFieldRecordSubmissionInputV1): Record<string, unknown> {
  const values = input.values || {};
  const stage = String(values.stage || '');
  const activity = String(values.activity || '');
  const details = [
    values.details,
    input.inferenceTitle ? `Inferência: ${String(input.inferenceTitle)}.` : null,
    (input.inferredFields || []).map(field => `${String(field.label || field.name || '')}: ${String(field.value || '')}`).filter(Boolean).join(' · '),
  ].filter(Boolean).join('\n');
  const selectedArea = normalizeAtlasPublicFieldRecordMapAreaV1(input.selectedArea || values.mapArea);
  const partIds = selectedArea?.partIds || normalizeAtlasPublicFieldRecordMapAreaV1(values.partIds)?.partIds ||
    String(values.partIds || '').split(',').map(value => value.trim()).filter(Boolean);
  return {
    obra: 'Aliança Park',
    etapa: stage,
    atividade: activity,
    responsavel: String(values.responsible || ''),
    detalhes: details,
    data: String(values.date || ''),
    hora: String(values.time || ''),
    status: String(values.status || 'Em andamento'),
    evidenceUri: String(values.evidenceUri || ''),
    stageId: ATLAS_PUBLIC_FIELD_RECORD_POLICY_V1.stageIds[stage] || 'earthwork',
    activity,
    responsible: String(values.responsible || ''),
    description: details,
    progress: Number(values.progress) || 0,
    observedAt: `${String(values.date || '')}T${String(values.time || '')}:00`,
    photoDataUrl: String(input.photoDataUrl || ''),
    mapArea: selectedArea ? JSON.stringify({ ...selectedArea, partIds }) : '',
    partIds,
  };
}

export async function createAtlasPublicFieldRecordV1(
  input: AtlasPublicFieldRecordSubmissionInputV1,
  ports: { apiFetch(path: string, init?: RequestInit): Promise<Response> },
): Promise<{ id: string }> {
  const response = await ports.apiFetch('/api/records', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Belavista-Role': 'foreman',
      'X-Belavista-User': 'public-records',
      'X-Belavista-Name': 'Registro de campo',
    },
    body: JSON.stringify(projectAtlasPublicFieldRecordPayloadV1(input)),
  });
  const record = await response.json().catch(() => ({})) as Record<string, unknown>;
  if (!response.ok) throw new Error(String(record.error || 'Não foi possível registrar a evidência operacional.'));
  return { id: String(record.id || '') };
}

export interface AtlasProposalVisionDraftV1 {
  client: string;
  lot: string;
  value: string;
  payment: string;
  quadra: string;
  lotArea: string;
  seller: string;
  confidence: number | null;
}

const proposalVisionTextV1 = (value: unknown, max = 1200): string => String(value ?? '').trim().slice(0, max);

function parseProposalVisionJsonCandidateV1(value: unknown): unknown {
  if (value && typeof value === 'object') return value;
  const raw = proposalVisionTextV1(value, 12_000)
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  if (!raw) return null;
  try { return JSON.parse(raw); } catch {}
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch { return null; }
}

/** Normalize the commercial fields returned by proposal OCR without inferring missing values. */
export function normalizeAtlasProposalVisionDraftV1(value: unknown = {}): AtlasProposalVisionDraftV1 | null {
  const envelope = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, any> : {};
  const source = envelope.proposal && typeof envelope.proposal === 'object'
    ? envelope.proposal
    : envelope.extracted && typeof envelope.extracted === 'object'
      ? envelope.extracted
      : envelope;
  const draft: AtlasProposalVisionDraftV1 = {
    client: proposalVisionTextV1(source.client || source.cliente || source.buyerName),
    lot: proposalVisionTextV1(source.lot || source.lote || source.lotId),
    value: proposalVisionTextV1(source.value || source.valor || source.price),
    payment: proposalVisionTextV1(source.payment || source.paymentCondition || source.condition || source.condicao),
    quadra: proposalVisionTextV1(source.quadra || source.block || source.blockDescription),
    lotArea: proposalVisionTextV1(source.lotArea || source.area || source.areaM2),
    seller: proposalVisionTextV1(source.seller || source.vendedor || source.owner),
    confidence: Number.isFinite(Number(source.confidence))
      ? Math.max(0, Math.min(1, Number(source.confidence)))
      : null,
  };
  return Object.values(draft).some(item => item !== '' && item !== null) ? draft : null;
}

/** Select and normalize the first structured proposal draft in a vision response. */
export function parseAtlasProposalVisionPayloadV1(payload: unknown = {}): AtlasProposalVisionDraftV1 | null {
  const response = payload && typeof payload === 'object' && !Array.isArray(payload) ? payload as Record<string, any> : {};
  const candidates = [response.proposal, response.extracted, response.structured, response.text, response.reply, response.result];
  for (const candidate of candidates) {
    const parsed = parseProposalVisionJsonCandidateV1(candidate);
    const draft = normalizeAtlasProposalVisionDraftV1(parsed || candidate);
    if (draft) return draft;
  }
  return null;
}

export interface AtlasProposalVisionInferenceV1 {
  draft: AtlasProposalVisionDraftV1;
  inference: Record<string, unknown>;
}

/** Run the proposal image inference request and normalize its persisted evidence metadata. */
export async function inferAtlasProposalAttachmentV1(input: {
  file: File;
  readAsDataUrl(file: File): Promise<string>;
  fetcher: typeof fetch;
  now?: Date;
}): Promise<AtlasProposalVisionInferenceV1> {
  const dataUrl = await input.readAsDataUrl(input.file);
  const response = await input.fetcher('/api/ai/vision-reasoning', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      message: PROPOSAL_VISION_PROMPT_V1,
      view: 'contracts',
      context: {
        purpose: 'proposta de reserva de lote',
        fields: ['client', 'lot', 'value', 'payment'],
      },
      attachment: { name: input.file.name, type: input.file.type, dataUrl },
    }),
  });
  const payload = await response.json().catch(() => ({})) as Record<string, unknown>;
  if (!response.ok)
    throw new Error(String(payload.error || `Falha na inferência (${response.status})`));
  const draft = parseAtlasProposalVisionPayloadV1(payload);
  if (!draft) throw new Error('A NVIDIA não retornou campos reconhecíveis.');
  const now = input.now || new Date();
  return Object.freeze({
    draft,
    inference: Object.freeze({
      provider: String(payload.provider || 'nvidia'),
      model: String(payload.model || ''),
      sourceFile: input.file.name,
      confidence: draft.confidence,
      extracted: draft,
      extractedAt: now.toISOString(),
    }),
  });
}

export type AtlasProposalInferenceFieldV1 = 'seller' | 'lot' | 'quadra' | 'lotArea' | 'value' | 'client' | 'payment';

export interface AtlasProposalVisionFormUpdateV1 {
  fields: Array<{ name: AtlasProposalInferenceFieldV1; value: string }>;
  statusMessage: string;
}

/** Project the recognized proposal fields and review status for the attachment form. */
export function projectAtlasProposalVisionFormUpdateV1(
  draft: AtlasProposalVisionDraftV1,
): AtlasProposalVisionFormUpdateV1 {
  const names: AtlasProposalInferenceFieldV1[] = [
    'seller', 'lot', 'quadra', 'lotArea', 'value', 'client', 'payment',
  ];
  const fields = names.flatMap(name => draft[name] ? [{ name, value: draft[name] }] : []);
  const confidence = draft.confidence == null
    ? ''
    : ` Confiança estimada: ${Math.round(draft.confidence * 100)}%.`;
  return Object.freeze({
    fields,
    statusMessage: `Sugestões aplicadas. Revise os campos antes de salvar.${confidence}`,
  });
}

/** Only raster formats supported by the vision endpoint participate in proposal inference. */
export function isAtlasProposalInferenceAttachmentV1(file: Pick<File, 'type'>): boolean {
  return /^image\/(?:png|jpeg|webp)$/i.test(file.type);
}

type AtlasApiClientRuntimeV1 = typeof globalThis & {
  BELAVISTA_API_BASE?: string;
  BELAVISTA_AI_BASE?: string;
  BELAVISTA_CAPACITOR_NATIVE?: boolean;
  BELAVISTA_FCM_VAPID_KEY?: string;
  BELAVISTA_ADMIN_AUTH_REQUIRED?: boolean;
  BELAVISTA_ADMIN_AUTH_READY?: Promise<unknown>;
  BELAVISTA_GET_ID_TOKEN?: () => Promise<string | null> | string | null;
  BELAVISTA_GET_WORKER_ID_TOKEN?: () => Promise<string | null>;
  BELAVISTA_RESET_WORKER_SESSION?: () => void;
  BELAVISTA_ADMIN_AUTH_INVALIDATE?: () => void | Promise<boolean>;
  BELAVISTA_ADMIN_ACTOR?: { role?: string; uid?: string; name?: string; email?: string } | null;
};

export type AtlasStageOverlayKeyV1 =
  | 'terraplanagem'
  | 'drenagem'
  | 'rede-agua'
  | 'rede-eletrica'
  | 'pavimentacao'
  | 'urbanizacao';

type AtlasStageOverlayCatalogV1 = {
  fallbackKey: AtlasStageOverlayKeyV1;
  emptyColor: string;
  rules: Array<{ key: AtlasStageOverlayKeyV1; terms: string[] }>;
  labels: Record<AtlasStageOverlayKeyV1, string>;
  colors: Record<AtlasStageOverlayKeyV1, string>;
};

const stageOverlayCatalogV1 = stageOverlayCatalogData as AtlasStageOverlayCatalogV1;
export const stageOverlayLabels: Readonly<Record<AtlasStageOverlayKeyV1, string>> = stageOverlayCatalogV1.labels;
export const stageOverlayColors: Readonly<Record<AtlasStageOverlayKeyV1, number>> = Object.fromEntries(
  Object.entries(stageOverlayCatalogV1.colors).map(([key, color]) => [key, Number.parseInt(color.slice(1), 16)]),
) as Record<AtlasStageOverlayKeyV1, number>;

export function stageOverlayKey(value: unknown): AtlasStageOverlayKeyV1 {
  const text = String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return stageOverlayCatalogV1.rules.find(rule => rule.terms.some(term => text.includes(term)))?.key
    || stageOverlayCatalogV1.fallbackKey;
}

export function normalizeStageOverlayKeysV1(value: unknown): AtlasStageOverlayKeyV1[] {
  const values: unknown[] = Array.isArray(value)
    ? value
    : String(value ?? '').split(',').map(item => item.trim()).filter(Boolean);
  return [...new Set(values.map(item => {
    const raw = String(item).toLowerCase() as AtlasStageOverlayKeyV1;
    return stageOverlayLabels[raw] ? raw : stageOverlayKey(item);
  }))];
}

export function blendStageOverlayColorV1(value: unknown): number {
  const colors = normalizeStageOverlayKeysV1(value).map(key => stageOverlayColors[key]).filter(Number.isFinite);
  if (!colors.length) return Number.parseInt(stageOverlayCatalogV1.emptyColor.slice(1), 16);
  const channel = (shift: number): number => Math.round(
    colors.reduce((sum, color) => sum + ((color >> shift) & 255), 0) / colors.length,
  );
  return (channel(16) << 16) | (channel(8) << 8) | channel(0);
}

export function stageOverlayLabelV1(value: unknown): string {
  return normalizeStageOverlayKeysV1(value).map(key => stageOverlayLabels[key]).join(' + ') || 'Nenhum highlight';
}

const ATLAS_API_SETTINGS_KEY_V1 = 'belavista.integrations.v1';
const ATLAS_CLOUDFLARE_WORKER_BASE_V1 = 'https://belavista-cloudflare-worker.icaroglaucooliveira.workers.dev';
const atlasApiClientTrimBaseV1 = (value: unknown): string => String(value || '').trim().replace(/\/$/, '');
const atlasApiClientReadSettingsV1 = (): Record<string, unknown> => {
  try {
    const value: unknown = globalThis.localStorage?.getItem(ATLAS_API_SETTINGS_KEY_V1);
    const parsed: unknown = JSON.parse(String(value || '{}'));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch { return {}; }
};
const atlasApiClientCloudflareWorkerBaseV1 = (): string => {
  const runtime = globalThis as AtlasApiClientRuntimeV1;
  const candidates = [
    runtime.BELAVISTA_API_BASE,
    runtime.BELAVISTA_AI_BASE,
    typeof document === 'undefined' ? '' : document.querySelector<HTMLMetaElement>('meta[name="belavista-api-base"]')?.content,
    typeof document === 'undefined' ? '' : document.querySelector<HTMLMetaElement>('meta[name="belavista-ai-base"]')?.content,
  ];
  for (const candidate of candidates) {
    const value = atlasApiClientTrimBaseV1(candidate);
    if (!value) continue;
    try {
      const url = new URL(value);
      if (url.protocol === 'https:' && url.hostname.endsWith('.workers.dev')) return value;
    } catch { /* Ignore malformed or non-Worker API origins. */ }
  }
  return ATLAS_CLOUDFLARE_WORKER_BASE_V1;
};
const atlasApiClientIsAiPathV1 = (path: unknown): boolean =>
  /^\/api\/runtime$|^\/api\/ai(?:$|\/)|^\/api\/inference(?:$|\/)|^\/api\/ai-tools$|^\/api\/ai\/status$|^\/api\/ai\/tools$|^\/api\/gemini(?:$|\/)|^\/api\/media\/attachment(?:$|\/)|^\/api\/public\/lead-chat(?:$|\/)/.test(String(path || ''));

/** Send operational API traffic only to the configured Cloudflare Worker. */
export function apiBase(): string {
  return atlasApiClientCloudflareWorkerBaseV1();
}

/** Route AI and operational requests to the same Cloudflare Worker. */
export function aiBase(): string {
  return atlasApiClientCloudflareWorkerBaseV1();
}

/** Resolve every API path against the Cloudflare Worker origin. */
export function apiUrl(path: unknown = ''): string {
  const target = String(path || '');
  if (/^https?:\/\//i.test(target)) return target;
  const normalized = target.startsWith('/') ? target : `/${target}`;
  const base = atlasApiClientIsAiPathV1(normalized) ? aiBase() : apiBase();
  return base ? `${base}${normalized}` : normalized;
}

/** Attach PTA and local-developer headers, then invalidate only authenticated 401s. */
export async function apiFetch(path: string, init: RequestInit = {}): Promise<Response> {
  const runtime = globalThis as AtlasApiClientRuntimeV1;
  if (runtime.BELAVISTA_ADMIN_AUTH_REQUIRED && String(path) !== '/api/auth/session')
    await runtime.BELAVISTA_ADMIN_AUTH_READY;
  const headers = new Headers(init.headers || {});
  const localHost = typeof location !== 'undefined' && /^(localhost|127\.0\.0\.1|\[::1\])$/i.test(String(location.hostname || ''));
  const aiBaseUrl = atlasApiClientTrimBaseV1(aiBase());
  const apiBaseUrl = atlasApiClientTrimBaseV1(apiBase());
  const remoteWorkerAiRequest = localHost && atlasApiClientIsAiPathV1(path) && Boolean(aiBaseUrl)
    && aiBaseUrl !== apiBaseUrl && typeof runtime.BELAVISTA_GET_WORKER_ID_TOKEN === 'function';
  let token = '';
  try {
    token = String(remoteWorkerAiRequest
      ? await runtime.BELAVISTA_GET_WORKER_ID_TOKEN?.()
      : await runtime.BELAVISTA_GET_ID_TOKEN?.() || '');
    if (token && !headers.has('Authorization')) headers.set('Authorization', `Bearer ${token}`);
  } catch { /* Requests keep the same behavior when the host cannot read its session. */ }
  const actor = runtime.BELAVISTA_ADMIN_ACTOR;
  if (actor?.role === 'developer' && localHost) {
    headers.set('X-Belavista-Role', 'developer');
    headers.set('X-Belavista-User', String(actor.uid || 'local-developer'));
    headers.set('X-Belavista-Name', String(actor.name || actor.email || 'TI · Desenvolvimento'));
  }
  let response = await globalThis.fetch(apiUrl(path), { ...init, headers });
  if (response.status === 401 && remoteWorkerAiRequest) {
    runtime.BELAVISTA_RESET_WORKER_SESSION?.();
    try {
      const refreshedToken = await runtime.BELAVISTA_GET_WORKER_ID_TOKEN?.();
      if (refreshedToken) {
        headers.set('Authorization', `Bearer ${refreshedToken}`);
        response = await globalThis.fetch(apiUrl(path), { ...init, headers });
      }
    } catch { /* Preserve the original 401 when the remote session cannot be renewed. */ }
  }
  if (response.status === 401 && headers.has('Authorization') && String(path) !== '/api/auth/session' && !atlasApiClientIsAiPathV1(path))
    runtime.BELAVISTA_ADMIN_AUTH_INVALIDATE?.();
  return response;
}

/** Read the configured Firebase messaging key without exposing integration secrets. */
export function firebaseMessagingVapidKey(): string {
  const runtime = globalThis as AtlasApiClientRuntimeV1;
  const metaValue = typeof document === 'undefined' ? '' : document.querySelector<HTMLMetaElement>('meta[name="belavista-fcm-vapid-key"]')?.content;
  return String(runtime.BELAVISTA_FCM_VAPID_KEY || metaValue || atlasApiClientReadSettingsV1().firebaseMessagingVapidKey || '').trim();
}

