/** Normalize model-provided tool calls before they enter the operational command pipeline. */
export function normalizeAtlasWorkerContextChatToolCallsV1(value: unknown): AtlasWorkerContextChatToolCallV1[] {
  if (!Array.isArray(value)) return [];
  return value.map(call => {
    const row = mapRecord(call);
    const name = typeof row?.name === 'string' ? row.name : '';
    if (!row || !name) return null;
    const argumentsValue = mapRecord(row.arguments);
    const argsValue = mapRecord(row.args);
    return {
      ...row,
      name,
      ...(argumentsValue ? { arguments: argumentsValue } : {}),
      ...(argsValue ? { args: argsValue } : {}),
    };
  }).filter((call): call is AtlasWorkerContextChatToolCallV1 => call !== null);
}

/** Normalize the untrusted Worker response into the DTO consumed by chat orchestration. */
export function normalizeAtlasWorkerContextChatInferenceResponseV1(value: unknown): AtlasWorkerContextChatInferenceResponseV1 {
  const response = mapRecord(value) || {};
  const ocr = mapRecord(response.recordOcr);
  const attachment = mapRecord(response.attachment);
  return {
    ...response,
    text: String(response.text || ''),
    toolCalls: normalizeAtlasWorkerContextChatToolCallsV1(response.toolCalls),
    recordOcr: ocr as AtlasRecordOcrPayloadV1 | null,
    attachment: attachment as AtlasWorkerContextChatInferenceAttachmentV1 | null,
    vision: Boolean(response.vision),
    reasoning: Boolean(response.reasoning),
    model: String(response.model || ''),
    provider: String(response.provider || ''),
    endpoint: typeof response.endpoint === 'string' ? response.endpoint : null,
    attachmentStorage: typeof response.attachmentStorage === 'string' ? response.attachmentStorage : null,
  };
}

/** Build the canonical Worker chat inference payload and normalize its response. */
export async function requestAtlasWorkerContextChatReplyV1(input: {
  apiFetch: (path: string, init: RequestInit) => Promise<Response>;
  pathname: string;
  message: string;
  attachment?: AtlasWorkerContextChatAttachmentV1 | null;
  options?: AtlasWorkerContextChatRequestOptionsV1 | null;
  applicationState?: Record<string, unknown>;
  context: AtlasWorkerContextChatOperationalContextV1;
  selectedStageKey: string;
  selectedStageName: string;
  mapContext?: { kind: string; label: string } | null;
  recordInterpretation?: unknown;
  agendaInstruction: string;
}): Promise<AtlasWorkerContextChatReplyV1> {
  const contextSummary = projectAtlasWorkerContextChatContextSummaryV1(input.context);
  const appState = input.applicationState || {};
  const instruction = String(input.options?.instruction || ATLAS_WORKER_CONTEXT_CHAT_POLICY_V1.operationalExecutionInstruction);
  const requestContext = input.options?.requestContext && typeof input.options.requestContext === 'object'
    ? input.options.requestContext
    : null;
  const payload: AtlasWorkerContextChatInferenceRequestV1 = {
    message: input.message,
    view: input.pathname.startsWith('/admin') ? String(appState.view || 'control') : 'workers',
    instruction: `${instruction} ${input.agendaInstruction}`,
    requestContext,
    context: {
      ...input.context,
      selectedStageKey: input.selectedStageKey,
      selectedStageName: input.selectedStageName,
      mapContext: input.mapContext || null,
      recordInterpretation: input.recordInterpretation ?? null,
      summary: contextSummary,
      capabilities: ATLAS_WORKER_CONTEXT_CHAT_POLICY_V1.capabilities,
    },
    attachment: input.attachment
      ? { name: input.attachment.name, mimeType: input.attachment.mimeType, dataUrl: input.attachment.dataUrl }
      : null,
  };
  try {
    const endpoint = input.attachment ? '/api/ai/vision-reasoning' : '/api/ai';
    const response = await input.apiFetch(endpoint, {
      method: 'POST',
      cache: 'no-store',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const normalizedResult = normalizeAtlasWorkerContextChatInferenceResponseV1(await response.json());
    return {
      text: String(normalizedResult.text || '').trim() || 'O endpoint de IA retornou uma resposta vazia.',
      toolCalls: normalizedResult.toolCalls,
      recordOcr: normalizedResult.recordOcr,
      attachment: normalizedResult.attachment,
      source: 'endpoint',
      audit: `Endpoint consultado${normalizedResult.vision ? ` · NVIDIA ${String(normalizedResult.model || 'multimodal reasoning')}` : ''} · ${contextSummary}`,
    };
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return {
      text: `Endpoint de IA indisponível · ${detail}`,
      source: 'error',
      audit: `Nenhuma resposta local foi usada · ${contextSummary}`,
    };
  }
}

/** Resolve runtime stage/OCR/agenda context before sending a Worker inference request. */
export function requestAtlasWorkerContextChatWorkspaceReplyV1(input: {
  apiFetch: (path: string, init: RequestInit) => Promise<Response>;
  pathname: string;
  message: string;
  attachment?: AtlasWorkerContextChatAttachmentV1 | null;
  options?: AtlasWorkerContextChatRequestOptionsV1 | null;
  applicationState?: Record<string, unknown>;
  context: AtlasWorkerContextChatOperationalContextV1;
  mapContext?: { kind: string; label: string } | null;
}): Promise<AtlasWorkerContextChatReplyV1> {
  const applicationState = input.applicationState || {};
  const selectedStage = mapRecord(applicationState.selectedStage);
  const selectedStageKey = String(
    applicationState.selectedStageV9 || selectedStage?.key || applicationState.selectedStage || input.context.stage || '',
  ).trim();
  const selectedStageName = String(
    input.context.stages?.find(stage => String(stage.key) === selectedStageKey)?.name || '',
  );
  const recordInterpretation = input.attachment
    ? buildAtlasWorkerContextChatRecordInterpretationV1({
        message: input.message,
        stages: input.context.stages,
        selectedStageKey,
      })
    : null;

  return requestAtlasWorkerContextChatReplyV1({
    ...input,
    applicationState,
    selectedStageKey,
    selectedStageName,
    recordInterpretation,
    agendaInstruction: aiAgendaInstructionV1(applicationState.aiAgendaComprehensionV1),
  });
}

export interface AtlasWorkerContextChatInferenceControllerPortsV1 {
  apiFetch(path: string, init: RequestInit): Promise<Response>;
  pathname(): string;
  getContext(): AtlasWorkerContextChatOperationalContextV1;
  getApplicationState(): Record<string, unknown> | null;
  getMapContext(): { kind: string; label: string } | null;
}

/** Own chat inference request composition while leaving browser reads in component ports. */
export function createAtlasWorkerContextChatInferenceControllerV1(
  ports: AtlasWorkerContextChatInferenceControllerPortsV1,
): {
  ask(input: {
    message: string;
    attachment?: AtlasWorkerContextChatAttachmentV1 | null;
    options?: AtlasWorkerContextChatRequestOptionsV1 | null;
  }): Promise<AtlasWorkerContextChatReplyV1>;
} {
  for (const [name, value] of Object.entries({
    apiFetch: ports?.apiFetch,
    pathname: ports?.pathname,
    getContext: ports?.getContext,
    getApplicationState: ports?.getApplicationState,
    getMapContext: ports?.getMapContext,
  })) if (typeof value !== 'function') throw new TypeError(`Worker chat inference requires ${name}().`);
  const ask = (request: {
    message: string;
    attachment?: AtlasWorkerContextChatAttachmentV1 | null;
    options?: AtlasWorkerContextChatRequestOptionsV1 | null;
  }): Promise<AtlasWorkerContextChatReplyV1> => requestAtlasWorkerContextChatWorkspaceReplyV1({
    apiFetch: ports.apiFetch,
    pathname: ports.pathname(),
    message: request.message,
    attachment: request.attachment || null,
    options: request.options || {},
    applicationState: ports.getApplicationState() || {},
    context: ports.getContext(),
    mapContext: ports.getMapContext(),
  });
  return Object.freeze({ ask });
}

