/** Resolve the activity journaling model from the selected stage and source catalog. */
export function projectAtlasLegacyActivityBlueprintV1(input: {
  state: Record<string, unknown>;
  demoActivities: unknown;
  activityCatalog: unknown;
}): AtlasLegacyActivityBlueprintV1 {
  const state = input.state;
  const rows = (value: unknown): Array<Record<string, unknown>> => Array.isArray(value)
    ? value.filter((row): row is Record<string, unknown> => Boolean(row) && typeof row === 'object')
    : [];
  const activities = rows(input.demoActivities);
  const catalogRows = rows(input.activityCatalog);
  const stage = activities.find(item => item.id === state.selectedStage) || activities[1] || {};
  const name = String(state.selectedActivity || 'Executar atividade principal');
  const stageName = String(stage.name || '');
  const term = stageName.toLocaleLowerCase('pt-BR').split(' ')[0];
  const catalog = catalogRows.find(item => String(item.name || '').toLocaleLowerCase('pt-BR') === name.toLocaleLowerCase('pt-BR'))
    || catalogRows.find(item => String(item.name || '').toLocaleLowerCase('pt-BR').includes(term)
      || String(item.nature || '').toLocaleLowerCase('pt-BR').includes(term));
  const list = (value: unknown, fallback: string[]): string[] => Array.isArray(value) ? value.map(String) : fallback;
  return {
    stage,
    name,
    nature: String(catalog?.nature || stageName),
    initial: list(catalog?.initial, ['Frente de serviço', 'Responsável', 'Data prevista']),
    execution: list(catalog?.execution, ['Avanço executado', 'Medição', 'Comprovante fotográfico', 'Pendências', 'Próximo passo']),
  };
}

export interface AtlasLegacyActivityCommandProgramDependenciesV1 {
  documentRef: Document;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  demoActivities: readonly Record<string, any>[];
  notify(message: string, tone?: string): void;
  DateCtor: DateConstructor;
}

export function installAtlasLegacyActivityCommandProgramV1(
  input: AtlasLegacyActivityCommandProgramDependenciesV1,
): void {
  input.documentRef.addEventListener('atlas:legacy-activity-command', event => {
    const detail = (event as CustomEvent<AtlasLegacyActivityCommandV1>).detail;
    const activeView = input.documentRef.querySelector('view-layer');
    const state = input.appStore.get();
    if (!detail || detail.element !== activeView || event.target !== activeView
      || String(state.view || '') !== 'stages') return;
    if (detail.kind === 'open-activity') {
      const stageId = input.demoActivities.find(item => String(item.name || '') === detail.stageName)?.id;
      input.appStore.set({
        selectedActivity: detail.activityName,
        activityDedicated: true,
        ...(stageId ? { selectedStage: stageId } : {}),
        lastAction: `Abriu atividade ${detail.activityName}`,
      });
      return;
    }
    if (state.activityDedicated !== true) return;
    if (detail.kind === 'return-to-stages') {
      input.appStore.set({
        view: 'stages',
        activityDedicated: false,
        selectedActivity: null,
        lastAction: 'Voltou para as etapas',
      });
      return;
    }
    if (detail.kind === 'save-draft') {
      input.appStore.set({ lastAction: 'Salvou rascunho da atividade' });
      input.notify('Rascunho do journaling salvo localmente.', 'success');
      return;
    }
    if (detail.kind === 'complete-workflow-step') {
      input.appStore.set({ lastAction: `Concluiu ${detail.stepName}` });
      input.notify(`${detail.stepName} concluído. Próximo fluxo liberado.`, 'success');
      return;
    }
    const text = (key: string, fallback = ''): string => String(detail.values[key] || fallback);
    const createdAt = new input.DateCtor();
    const record = {
      id: `REG-${createdAt.getTime()}`,
      obra: 'Aliança Park',
      atividade: detail.activityName,
      etapa: detail.stageName,
      categoria: detail.activityNature,
      responsavel: text('responsavel', detail.stageOwner),
      data: text('data', createdAt.toISOString().slice(0, 10)),
      hora: text('hora', '08:30'),
      detalhes: text('detalhes'),
      evidenceUri: text('evidencias'),
      status: text('status', 'Em andamento'),
      progresso: Number(text('percentual', '0')),
      createdAt: createdAt.toISOString(),
    };
    const records = Array.isArray(state.records) ? state.records : [];
    input.appStore.set({
      records: [record, ...records],
      lastAction: `Registrou journaling de ${detail.activityName}`,
    });
    input.notify('Atualização registrada no diário da atividade.', 'success');
  });
}

