export function installAtlasLegacyLeadProgramV1(input: AtlasLegacyLeadProgramDependenciesV1): void {
  input.documentRef.addEventListener('atlas:legacy-lead-command', event => {
    const detail = (event as CustomEvent<AtlasLegacyLeadCommandV1>).detail;
    const activeView = input.documentRef.querySelector('view-layer');
    if (!detail || detail.element !== activeView || event.target !== activeView) return;
    if (detail.kind === 'select') {
      input.appStore.set({ selectedLead: detail.index });
      return;
    }
    if (detail.kind === 'prepare-whatsapp') {
      const message = `Olá, ${detail.name}! Aqui é da equipe Vista Verde. Recebemos seu interesse no ${detail.lot} e podemos enviar as condições, disponibilidade e próximos passos.`;
      input.windowRef.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank', 'noopener');
      input.notify(`Mensagem de WhatsApp preparada para ${detail.name}.`, 'success');
      input.appStore.set({ lastAction: `Preparou WhatsApp para ${detail.name}` });
      return;
    }
    const lot = input.demoLeads[detail.index]?.lot;
    input.notify(`Reserva preparada para ${lot || 'o lote interessado'}.`, 'success');
    input.appStore.set({ lastAction: `Abriu reserva de ${lot || 'lote'}` });
  });
}

