export function installAtlasLegacyViewActionProgramV1(input: AtlasLegacyViewActionProgramDependenciesV1): void {
  input.documentRef.addEventListener('atlas:legacy-dedicated-stage-open-command', event => {
    const detail = (event as CustomEvent<AtlasLegacyDedicatedStageOpenCommandV1>).detail;
    const activeView = input.documentRef.querySelector('view-layer');
    if (!detail || detail.element !== activeView || event.target !== activeView) return;
    const stageView = activeView as HTMLElement & {
      _dedicated: boolean;
      openDedicatedStage(): void;
      bindDedicatedStageContext(): void;
      bindDedicatedWorkflow(): void;
      bindDedicatedActivityClicks(): void;
      enhanceDedicatedSurface(): void;
      addCatalogPalette(): void;
      bindCatalogButtons(): void;
      addFineDurationControls(): void;
      bindGhostConnections(): void;
      watchSurfaceRelations(): void;
      bindWorkflowFieldTrees(): void;
    };
    stageView._dedicated = true;
    stageView.openDedicatedStage();
    stageView.bindDedicatedStageContext();
    stageView.bindDedicatedWorkflow();
    stageView.bindDedicatedActivityClicks();
    stageView.enhanceDedicatedSurface();
    stageView.addCatalogPalette();
    stageView.bindCatalogButtons();
    stageView.addFineDurationControls();
    stageView.bindGhostConnections();
    stageView.watchSurfaceRelations();
    stageView.bindWorkflowFieldTrees();
    input.appStore.set({ stageSelected: true });
  });
  input.documentRef.addEventListener('atlas:legacy-view-action-command', event => {
    const detail = (event as CustomEvent<AtlasLegacyViewActionCommandV1>).detail;
    const activeView = input.documentRef.querySelector('view-layer');
    if (!detail || detail.element !== activeView || event.target !== activeView) return;
    if (detail.kind === 'open-new-record') {
      input.appStore.set({
        view: 'records',
        activityDedicated: false,
        selectedActivity: null,
        selectedRecordsActivityV5377: null,
        recordsRegistrationRequestedV5377: true,
        editingRecord: null,
        recordContext: null,
        lastAction: 'Abriu novo registro',
      });
      return;
    }
    input.appStore.set({
      selectedStage: detail.index,
      stageSelected: true,
      lastAction: `Abriu a etapa ${detail.stageLabel}`,
    });
  });
}

