export interface AtlasLegacyUtilityProgramDependenciesV1 {
  documentRef: Document;
  windowRef: Window & typeof globalThis;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  notify(message: string, tone?: string): void;
}

export function installAtlasLegacyUtilityProgramV1(input: AtlasLegacyUtilityProgramDependenciesV1): void {
  input.documentRef.addEventListener('atlas:legacy-utility-command', event => {
    const detail = (event as CustomEvent<AtlasLegacyUtilityCommandV1>).detail;
    const activeView = input.documentRef.querySelector('view-layer');
    if (!detail || detail.element !== activeView || event.target !== activeView) return;
    if (detail.kind === 'map-print-open') {
      const map = input.documentRef.querySelector<HTMLElement & { openMapCanvasPrintV1?: () => void }>('map-scene:not([compact])');
      if (map?.openMapCanvasPrintV1) {
        map.openMapCanvasPrintV1();
        return;
      }
      input.appStore.set({ printMode: true, lastAction: 'Abriu relatório executivo do empreendimento' });
      const finishPrint = (): void => {
        if (input.appStore.get().printMode) {
          input.appStore.set({ printMode: false, lastAction: 'Concluiu impressão do relatório executivo' });
        }
      };
      input.windowRef.addEventListener('afterprint', finishPrint, { once: true });
      const started = input.windowRef.performance.now();
      const waitForScene = (): void => {
        const ready = map?.dataset.modelRender === 'webgl-live-glb'
          && map.dataset.mapTexture === 'ready'
          && map.dataset.mapSurfaceVisible === 'true';
        if (ready || input.windowRef.performance.now() - started > 4500) {
          input.windowRef.print();
          return;
        }
        input.windowRef.requestAnimationFrame(waitForScene);
      };
      input.windowRef.requestAnimationFrame(() => input.windowRef.requestAnimationFrame(waitForScene));
      return;
    }
    if (detail.kind === 'map-print-close') {
      input.appStore.set({ printMode: false, lastAction: 'Fechou prévia de impressão' });
      return;
    }
    if (detail.kind === 'map-print-start') {
      input.notify('Abrindo impressão. Escolha "Salvar como PDF" no destino.', 'success');
      input.windowRef.setTimeout(() => input.windowRef.print(), 120);
      return;
    }
    if (detail.kind === 'audit-clear') {
      input.appStore.update(state => ({ ...state, actionAudit: [], lastAction: 'Limpou o histórico de uso da sessão' }));
      input.notify('Histórico de uso desta sessão limpo.', 'success');
      return;
    }
    if (detail.kind === 'audit-export') {
      const state = input.appStore.get();
      const rows: unknown[][] = [
        ['Horário', 'Ação', 'Área', 'Módulo', 'Usuário'],
        ...(state.actionAudit || []).map(item => [
          new Date(item.at).toLocaleString('pt-BR'),
          item.label,
          item.view || 'dashboard',
          item.view || 'dashboard',
          item.actor || 'Warley',
        ]),
      ];
      const csv = rows.map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(';')).join('\n');
      const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
      const link = input.documentRef.createElement('a');
      link.href = url;
      link.download = `auditoria-uso-${String(state.sessionId)}.csv`;
      link.click();
      URL.revokeObjectURL(url);
      input.appStore.set({ lastAction: 'Exportou histórico de uso da sessão' });
      return;
    }
    input.appStore.set({ lastAction: 'Ocultou um card do dashboard' });
  });
}

export interface AtlasLegacyStageContextProgramDependenciesV1 {
  documentRef: Document;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  storage: Storage;
  integrationSettingsKey: string;
  readIntegrationSettings(): Record<string, unknown> | null;
  splitStageConfigList(value: unknown): string[];
  runOperationalLoop(reason: string, options?: { quiet?: boolean }): Promise<void>;
  notify(message: string, tone?: string): void;
}

export function installAtlasLegacyStageContextProgramV1(input: AtlasLegacyStageContextProgramDependenciesV1): void {
  input.documentRef.addEventListener('atlas:legacy-stage-context-save-command', async event => {
    const detail = (event as CustomEvent<AtlasLegacyStageContextSaveCommandV1>).detail;
    const activeView = input.documentRef.querySelector('view-layer');
    if (!detail || detail.element !== activeView || event.target !== activeView) return;
    const settings: Record<string, any> = {
      ...(input.readIntegrationSettings() || {}),
      ...((input.appStore.get() as Record<string, any>).integrationSettings || {}),
    };
    const nextProfile = {
      requirements: input.splitStageConfigList(detail.fields.requirements),
      conditions: input.splitStageConfigList(detail.fields.conditions),
      typicalDescription: detail.fields.typicalDescription,
      requestHints: input.splitStageConfigList(detail.fields.requestHints),
      evidenceFocus: input.splitStageConfigList(detail.fields.evidenceFocus),
      procurementFocus: input.splitStageConfigList(detail.fields.procurementFocus),
      materialsTable: detail.materials,
      notificationTargets: {
        owner: input.splitStageConfigList(detail.fields.notifyOwner),
        admin: input.splitStageConfigList(detail.fields.notifyAdmin),
        foreman: input.splitStageConfigList(detail.fields.notifyForeman),
      },
    };
    const data = { ...settings, stageProfiles: { ...(settings.stageProfiles || {}), [detail.stageKey]: nextProfile } };
    input.storage.setItem(input.integrationSettingsKey, JSON.stringify(data));
    input.appStore.set({ integrationSettings: data, lastAction: `Salvou contexto operacional da etapa ${detail.stageKey}` });
    await input.runOperationalLoop('stage.context.changed', { quiet: true });
    const result: AtlasLegacyStageContextSaveResultV1 = {
      element: detail.element,
      statusText: 'Contexto salvo. O ciclo operacional já recebeu a descrição, os materiais quantificados e os destinos desta etapa.',
    };
    detail.element.dispatchEvent(new CustomEvent<AtlasLegacyStageContextSaveResultV1>('atlas:legacy-stage-context-save-result', {
      bubbles: true,
      detail: result,
    }));
    input.notify('Contexto da etapa salvo e propagado para o agente.', 'success');
  });
}

