export interface AtlasCompactMapMirrorV1 extends HTMLElement {
  _compactVisible?: boolean;
  renderSharedMap?: () => void;
}

export interface AtlasSharedMapSceneV1 extends HTMLElement {
  _modelGpuReady?: boolean;
}

export interface AtlasCompactMapCoordinatorPortsV1 {
  requestAnimationFrame(callback: FrameRequestCallback): number;
}

export interface AtlasCompactMapCoordinatorV1 {
  compactMapMirrors: Set<AtlasCompactMapMirrorV1>;
  getSharedMapScene(): AtlasSharedMapSceneV1 | null;
  publishMapPreview(): void;
  setSharedMapScene(scene: AtlasSharedMapSceneV1 | null): void;
  syncCompactMapMirrors(): void;
}

export interface AtlasMapTileSourceV1 {
  id: string;
  url(z: number, x: number, y: number): string;
}

export interface AtlasMapTileSourceCatalogV1 {
  satellite: AtlasMapTileSourceV1[];
  osm: AtlasMapTileSourceV1[];
  generated: Array<{ id: string; url(): string }>;
}

export interface AtlasMapTileSourceCatalogInputV1 {
  runtimeRouteV1(path: unknown, query?: unknown): string;
  generatedAerialAsset: string;
  generatedAerialVersion: string;
}

interface AtlasMapTileSourceCatalogDataV1 {
  satellite: readonly { id: string; urlTemplate: string }[];
  osm: readonly { id: string; urlTemplate: string }[];
  generated: readonly { id: string; versionQueryKey: string }[];
}

/** Coordinates the persistent MapScene and its visible compact mirrors. */
export function createAtlasCompactMapCoordinatorV1(
  ports: AtlasCompactMapCoordinatorPortsV1,
): AtlasCompactMapCoordinatorV1 {
  if (typeof ports.requestAnimationFrame !== 'function')
    throw new TypeError('Compact map coordinator requires requestAnimationFrame().');

  const compactMapMirrors = new Set<AtlasCompactMapMirrorV1>();
  let sharedMapScene: AtlasSharedMapSceneV1 | null = null;
  let compactMirrorFrame = 0;

  const syncCompactMapMirrors = (): void => {
    if (!sharedMapScene?._modelGpuReady || compactMirrorFrame) return;
    const queue = [...compactMapMirrors].filter(mirror => mirror._compactVisible);
    const step: FrameRequestCallback = () => {
      const mirror = queue.shift();
      if (mirror) mirror.renderSharedMap?.();
      compactMirrorFrame = queue.length ? ports.requestAnimationFrame(step) : 0;
    };
    compactMirrorFrame = ports.requestAnimationFrame(step);
  };

  return {
    compactMapMirrors,
    getSharedMapScene: () => sharedMapScene,
    publishMapPreview: syncCompactMapMirrors,
    setSharedMapScene(scene) { sharedMapScene = scene; },
    syncCompactMapMirrors,
  };
}

/** Build the remote and generated raster tile sources used by MapScene. */
export function createAtlasMapTileSourceCatalogV1(
  input: AtlasMapTileSourceCatalogInputV1,
): AtlasMapTileSourceCatalogV1 {
  const { runtimeRouteV1, generatedAerialAsset, generatedAerialVersion } = input;
  const data = mapTileSourceCatalogData as unknown as AtlasMapTileSourceCatalogDataV1;
  const tileSource = ({ id, urlTemplate }: AtlasMapTileSourceCatalogDataV1['satellite'][number]): AtlasMapTileSourceV1 => ({
    id,
    url: (z, x, y) => urlTemplate
      .replaceAll('{z}', String(z))
      .replaceAll('{x}', String(x))
      .replaceAll('{y}', String(y)),
  });
  return {
    satellite: data.satellite.map(tileSource),
    osm: data.osm.map(tileSource),
    generated: data.generated.map(source => ({
      id: source.id,
      url: () => runtimeRouteV1(generatedAerialAsset, `${source.versionQueryKey}=${generatedAerialVersion}`),
    })),
  };
}

/** Validate geographic coordinates accepted by the shared map scene. */
export function isAtlasMapGeoPointValidV1(point: unknown): boolean {
  if (!point) return false;
  const candidate = point as { lat?: unknown; lng?: unknown };
  return Number.isFinite(Number(candidate.lat))
    && Number.isFinite(Number(candidate.lng))
    && Math.abs(Number(candidate.lat)) <= 90
    && Math.abs(Number(candidate.lng)) <= 180;
}

/** Resolve fixed scene settings from JSON and apply typed URL calibration. */
export function projectAtlasMapScenePresentationConfig(input: { search?: string } = {}): AtlasMapScenePresentationConfig {
  const data = mapScenePresentationData as unknown as AtlasMapScenePresentationStaticConfig;
  const calibrationDefaults: AtlasMapModelCalibration = {
    rotation: { ...data.ADMIN_MODEL_CALIBRATION_DEFAULTS_V1.rotation },
    shift: { ...data.ADMIN_MODEL_CALIBRATION_DEFAULTS_V1.shift },
    scale: data.ADMIN_MODEL_CALIBRATION_DEFAULTS_V1.scale,
  };
  const readAdminModelCalibrationV1 = ({ search }: { search?: string } = {}): AtlasMapModelCalibration => {
    let params: URLSearchParams | null = null;
    try {
      params = new URLSearchParams(search ?? globalThis.location?.search ?? '');
    } catch {
      params = null;
    }
    const number = (names: string[], fallback: number): number => {
      for (const name of names) {
        const raw = params?.get(name);
        if (raw == null || raw.trim() === '') continue;
        const value = Number(raw);
        if (Number.isFinite(value)) return value;
      }
      return fallback;
    };
    const clamp = (value: number, min: number, max: number): number => Math.max(min, Math.min(max, value));
    return {
      rotation: {
        x: clamp(number(['modelRotateX'], calibrationDefaults.rotation.x), -45, 45),
        y: clamp(number(['modelRotateY'], calibrationDefaults.rotation.y), -45, 45),
        z: clamp(number(['modelRotate', 'modelRotateZ'], calibrationDefaults.rotation.z), -180, 180),
      },
      shift: {
        x: clamp(number(['modelShiftX'], calibrationDefaults.shift.x), -500, 500),
        y: clamp(number(['modelShiftY'], calibrationDefaults.shift.y), -500, 500),
        z: clamp(number(['modelShiftZ'], calibrationDefaults.shift.z), -100, 100),
      },
      scale: clamp(number(['modelScale'], calibrationDefaults.scale), 0.5, 1.5),
    };
  };
  const calibration = readAdminModelCalibrationV1({ search: input.search });
  const heading = Math.atan2(data.DWG_PLAN_HEADING_VECTOR.sin, data.DWG_PLAN_HEADING_VECTOR.cos);
  const degreesToRadians = (degrees: number): number => degrees * Math.PI / 180;
  const { DWG_PLAN_HEADING_VECTOR: _headingVector, ...staticValues } = data;
  return Object.freeze({
    ...staticValues,
    ADMIN_MODEL_CALIBRATION_DEFAULTS_V1: calibrationDefaults,
    ADMIN_MODEL_CALIBRATION_V1: calibration,
    ADMIN_MODEL_CALIBRATION_INITIAL_V1: { rotation: { ...calibration.rotation }, shift: { ...calibration.shift }, scale: calibration.scale },
    DWG_PLAN_HEADING_RAD: heading,
    DWG_PLAN_HEADING_DEG: heading * 180 / Math.PI,
    PUBLIC_MODEL_NORTH_ROTATION_RAD: degreesToRadians(data.PUBLIC_MODEL_NORTH_ROTATION_DEG),
    MODEL_EXTRA_Y_ROTATION_RAD: degreesToRadians(data.MODEL_EXTRA_Y_ROTATION_DEG),
    ADMIN_FIXED_MAP_ROTATION_RAD: degreesToRadians(data.ADMIN_FIXED_MAP_ROTATION_DEG),
    ADMIN_PDF_DISPLAY_Y_ROTATION_RAD: degreesToRadians(data.ADMIN_PDF_DISPLAY_Y_ROTATION_DEG),
    ADMIN_STANDALONE_DETILT_ZOOM_FLOOR_DEG_V10: data.MAX_SCENE_TILT * data.ADMIN_STANDALONE_DETILT_ZOOM_FLOOR_RATIO_V10,
    ADMIN_STANDALONE_DETILT_ZOOM_OUT_AUTO_USAGE_V12: 1 - data.ADMIN_STANDALONE_DETILT_ZOOM_OUT_RESERVE_RATIO_V12,
    sceneTiltBoostForView: (view: unknown) => view === 'assistant' ? data.DASHBOARD_TILT_BOOST : data.DEFAULT_TILT_BOOST,
    readAdminModelCalibrationV1,
  });
}

export interface AtlasPublicMapEnvironmentV1 {
  scene: {
    version: string;
    rendererExposure: number;
    backgroundColor: number;
    hemisphereLight: { intensity: number; color: number; groundColor: number };
    directionalLight: { intensity: number; color: number; position: [number, number, number] };
    ambientLightMinimumIntensity: number;
    sun: { name: string; color: number; intensity: number; position: [number, number, number] };
    surface: { color: number; opacity: number; transparent: boolean };
    labels: {
      satellitePalette: string;
      disabledRoadTexture: string;
      removedSyntheticRoadTexture: string;
      preservedSatelliteMaterials: string;
      modelAlignment: string;
      sunnyLighting: string;
      sunnyBackdrop: string;
      greenMeshPolicy: string;
    };
  };
  legacyFallback: {
    palette: {
      grass: number[]; road: number[]; curb: number; line: number; foliage: number[];
      trunk: number; sand: number; clay: number; concrete: number;
    };
    lighting: {
      rendererExposure: number;
      hemisphereLight: { intensity: number; color: number; groundColor: number };
      directionalLight: { intensity: number; color: number };
    };
    materialDefaults: {
      normalize: AtlasPublicMapMaterialProfileV1;
      textured: AtlasPublicMapMaterialProfileV1;
      surfaces: Record<'earth' | 'outline' | 'road' | 'curb' | 'trunk' | 'foliage' | 'leisure' | 'roof' | 'concrete' | 'streetOverlay', AtlasPublicMapMaterialProfileV1>;
    };
    labels: { preservedMaterials: string; naturalPalette: string };
  };
}

export interface AtlasPublicMapMaterialProfileV1 {
  roughness: number;
  emissive?: number;
  emissiveIntensity?: number;
  opacity?: number;
}

/** Validate public-scene colors, vectors, palette and legacy material profiles from JSON. */
export function projectAtlasPublicMapEnvironmentV1(): AtlasPublicMapEnvironmentV1 {
  const record = (value: unknown, path: string): Record<string, unknown> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`Configuração pública inválida: ${path}.`);
    return value as Record<string, unknown>;
  };
  const root = record(publicMapEnvironmentData, 'root');
  const scene = record(root.scene, 'scene');
  const fallback = record(root.legacyFallback, 'legacyFallback');
  const palette = record(fallback.palette, 'legacyFallback.palette');
  const legacyLighting = record(fallback.lighting, 'legacyFallback.lighting');
  const materialDefaults = record(fallback.materialDefaults, 'legacyFallback.materialDefaults');
  const sceneHemisphere = record(scene.hemisphereLight, 'scene.hemisphereLight');
  const sceneDirectional = record(scene.directionalLight, 'scene.directionalLight');
  const sun = record(scene.sun, 'scene.sun');
  const surface = record(scene.surface, 'scene.surface');
  const fallbackHemisphere = record(legacyLighting.hemisphereLight, 'legacyFallback.lighting.hemisphereLight');
  const fallbackDirectional = record(legacyLighting.directionalLight, 'legacyFallback.lighting.directionalLight');
  const sceneLabels = record(scene.labels, 'scene.labels');
  const fallbackLabels = record(fallback.labels, 'legacyFallback.labels');
  const number = (value: unknown, path: string): number => {
    if (typeof value !== 'number' || !Number.isFinite(value)) throw new TypeError(`Número inválido em public-map-environment.json: ${path}.`);
    return value;
  };
  const color = (value: unknown, path: string): number => {
    const result = typeof value === 'number' ? value : typeof value === 'string' && /^0x[\da-f]{6}$/i.test(value) ? Number.parseInt(value.slice(2), 16) : NaN;
    if (!Number.isInteger(result) || result < 0 || result > 0xffffff) throw new TypeError(`Cor hexadecimal inválida em public-map-environment.json: ${path}.`);
    return result;
  };
  const boolean = (value: unknown, path: string): boolean => {
    if (typeof value !== 'boolean') throw new TypeError(`Booleano inválido em public-map-environment.json: ${path}.`);
    return value;
  };
  const text = (value: unknown, path: string): string => {
    if (typeof value !== 'string' || !value.trim()) throw new TypeError(`Texto inválido em public-map-environment.json: ${path}.`);
    return value;
  };
  const vector3 = (value: unknown, path: string): [number, number, number] => {
    if (!Array.isArray(value) || value.length !== 3) throw new TypeError(`Vetor inválido em public-map-environment.json: ${path}.`);
    return [number(value[0], `${path}[0]`), number(value[1], `${path}[1]`), number(value[2], `${path}[2]`)];
  };
  const colorList = (value: unknown, path: string): number[] => {
    if (!Array.isArray(value) || !value.length) throw new TypeError(`Paleta inválida em public-map-environment.json: ${path}.`);
    return value.map((item, index) => color(item, `${path}[${index}]`));
  };
  const profile = (value: unknown, path: string): AtlasPublicMapMaterialProfileV1 => {
    const item = record(value, path);
    return {
      roughness: number(item.roughness, `${path}.roughness`),
      ...(item.emissive === undefined ? {} : { emissive: color(item.emissive, `${path}.emissive`) }),
      ...(item.emissiveIntensity === undefined ? {} : { emissiveIntensity: number(item.emissiveIntensity, `${path}.emissiveIntensity`) }),
      ...(item.opacity === undefined ? {} : { opacity: number(item.opacity, `${path}.opacity`) }),
    };
  };
  const surfaceProfiles = record(materialDefaults.surfaces, 'legacyFallback.materialDefaults.surfaces');
  return {
    scene: {
      version: text(scene.version, 'scene.version'),
      rendererExposure: number(scene.rendererExposure, 'scene.rendererExposure'),
      backgroundColor: color(scene.backgroundColor, 'scene.backgroundColor'),
      hemisphereLight: { intensity: number(sceneHemisphere.intensity, 'scene.hemisphereLight.intensity'), color: color(sceneHemisphere.color, 'scene.hemisphereLight.color'), groundColor: color(sceneHemisphere.groundColor, 'scene.hemisphereLight.groundColor') },
      directionalLight: { intensity: number(sceneDirectional.intensity, 'scene.directionalLight.intensity'), color: color(sceneDirectional.color, 'scene.directionalLight.color'), position: vector3(sceneDirectional.position, 'scene.directionalLight.position') },
      ambientLightMinimumIntensity: number(scene.ambientLightMinimumIntensity, 'scene.ambientLightMinimumIntensity'),
      sun: { name: text(sun.name, 'scene.sun.name'), color: color(sun.color, 'scene.sun.color'), intensity: number(sun.intensity, 'scene.sun.intensity'), position: vector3(sun.position, 'scene.sun.position') },
      surface: { color: color(surface.color, 'scene.surface.color'), opacity: number(surface.opacity, 'scene.surface.opacity'), transparent: boolean(surface.transparent, 'scene.surface.transparent') },
      labels: {
        satellitePalette: text(sceneLabels.satellitePalette, 'scene.labels.satellitePalette'),
        disabledRoadTexture: text(sceneLabels.disabledRoadTexture, 'scene.labels.disabledRoadTexture'),
        removedSyntheticRoadTexture: text(sceneLabels.removedSyntheticRoadTexture, 'scene.labels.removedSyntheticRoadTexture'),
        preservedSatelliteMaterials: text(sceneLabels.preservedSatelliteMaterials, 'scene.labels.preservedSatelliteMaterials'),
        modelAlignment: text(sceneLabels.modelAlignment, 'scene.labels.modelAlignment'),
        sunnyLighting: text(sceneLabels.sunnyLighting, 'scene.labels.sunnyLighting'),
        sunnyBackdrop: text(sceneLabels.sunnyBackdrop, 'scene.labels.sunnyBackdrop'),
        greenMeshPolicy: text(sceneLabels.greenMeshPolicy, 'scene.labels.greenMeshPolicy'),
      },
    },
    legacyFallback: {
      palette: {
        grass: colorList(palette.grass, 'legacyFallback.palette.grass'), road: colorList(palette.road, 'legacyFallback.palette.road'),
        curb: color(palette.curb, 'legacyFallback.palette.curb'), line: color(palette.line, 'legacyFallback.palette.line'),
        foliage: colorList(palette.foliage, 'legacyFallback.palette.foliage'), trunk: color(palette.trunk, 'legacyFallback.palette.trunk'),
        sand: color(palette.sand, 'legacyFallback.palette.sand'), clay: color(palette.clay, 'legacyFallback.palette.clay'), concrete: color(palette.concrete, 'legacyFallback.palette.concrete'),
      },
      lighting: {
        rendererExposure: number(legacyLighting.rendererExposure, 'legacyFallback.lighting.rendererExposure'),
        hemisphereLight: { intensity: number(fallbackHemisphere.intensity, 'legacyFallback.lighting.hemisphereLight.intensity'), color: color(fallbackHemisphere.color, 'legacyFallback.lighting.hemisphereLight.color'), groundColor: color(fallbackHemisphere.groundColor, 'legacyFallback.lighting.hemisphereLight.groundColor') },
        directionalLight: { intensity: number(fallbackDirectional.intensity, 'legacyFallback.lighting.directionalLight.intensity'), color: color(fallbackDirectional.color, 'legacyFallback.lighting.directionalLight.color') },
      },
      materialDefaults: {
        normalize: profile(materialDefaults.normalize, 'legacyFallback.materialDefaults.normalize'),
        textured: profile(materialDefaults.textured, 'legacyFallback.materialDefaults.textured'),
        surfaces: {
          earth: profile(surfaceProfiles.earth, 'legacyFallback.materialDefaults.surfaces.earth'),
          outline: profile(surfaceProfiles.outline, 'legacyFallback.materialDefaults.surfaces.outline'),
          road: profile(surfaceProfiles.road, 'legacyFallback.materialDefaults.surfaces.road'),
          curb: profile(surfaceProfiles.curb, 'legacyFallback.materialDefaults.surfaces.curb'),
          trunk: profile(surfaceProfiles.trunk, 'legacyFallback.materialDefaults.surfaces.trunk'),
          foliage: profile(surfaceProfiles.foliage, 'legacyFallback.materialDefaults.surfaces.foliage'),
          leisure: profile(surfaceProfiles.leisure, 'legacyFallback.materialDefaults.surfaces.leisure'),
          roof: profile(surfaceProfiles.roof, 'legacyFallback.materialDefaults.surfaces.roof'),
          concrete: profile(surfaceProfiles.concrete, 'legacyFallback.materialDefaults.surfaces.concrete'),
          streetOverlay: profile(surfaceProfiles.streetOverlay, 'legacyFallback.materialDefaults.surfaces.streetOverlay'),
        },
      },
      labels: { preservedMaterials: text(fallbackLabels.preservedMaterials, 'legacyFallback.labels.preservedMaterials'), naturalPalette: text(fallbackLabels.naturalPalette, 'legacyFallback.labels.naturalPalette') },
    },
  };
}

export interface AtlasMapSolarGeoPoint {
  lat: number;
  lng: number;
  label?: string;
  timezone?: string;
  timezoneOffset?: number;
  center?: { lat?: number; lng?: number };
}

export interface AtlasMapSolarWindow {
  sunrise: number;
  solarNoon: number;
  sunset: number;
  lat: number;
  lng: number;
  label: string;
}

export interface AtlasMapSolarState extends AtlasMapSolarWindow {
  hour: number;
  progress: number;
  elevation: number;
  azimuth: number;
  daylight: boolean;
}

interface AtlasMapSolarDefaults {
  georeferenceFallback: AtlasMapSolarGeoPoint;
}

/** Fixed site coordinate used by solar calculations before the DWG is available. */
export const MAP_GEOREFERENCE_FALLBACK: Readonly<AtlasMapSolarGeoPoint> = Object.freeze(
  { ...(mapSolarDefaultsData as AtlasMapSolarDefaults).georeferenceFallback },
);

/** Resolve local wall-clock time at the project's configured timezone. */
export function localClockHourForGeo(geo: Partial<AtlasMapSolarGeoPoint> = {}, date = new Date()): number {
  const timezone = geo.timezone || MAP_GEOREFERENCE_FALLBACK.timezone || 'America/Bahia';
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      hour: '2-digit',
      minute: '2-digit',
      hourCycle: 'h23',
    }).formatToParts(date);
    const hour = Number(parts.find(item => item.type === 'hour')?.value);
    const minute = Number(parts.find(item => item.type === 'minute')?.value);
    if (Number.isFinite(hour) && Number.isFinite(minute)) return (((hour + minute / 60) % 24) + 24) % 24;
  } catch {}
  const offset = Number(geo.timezoneOffset ?? MAP_GEOREFERENCE_FALLBACK.timezoneOffset ?? -3);
  const utc = date.getUTCHours() + date.getUTCMinutes() / 60 + date.getUTCSeconds() / 3600;
  return (((utc + offset) % 24) + 24) % 24;
}

function solarDayOfYear(date: Date): number {
  const start = new Date(date.getFullYear(), 0, 0);
  return Math.floor((date.getTime() - start.getTime()) / 86_400_000);
}

/** Compute the sunrise-to-sunset window at the project coordinate. */
export function solarWindowForGeo(geo: Partial<AtlasMapSolarGeoPoint> = {}, date = new Date()): AtlasMapSolarWindow {
  const rawLatitude = Number(geo.lat ?? geo.center?.lat ?? MAP_GEOREFERENCE_FALLBACK.lat);
  const lat = Math.max(-89, Math.min(89, rawLatitude)) * Math.PI / 180;
  const rawLongitude = Number(geo.lng ?? geo.center?.lng ?? MAP_GEOREFERENCE_FALLBACK.lng);
  const lng = rawLongitude || MAP_GEOREFERENCE_FALLBACK.lng;
  const day = solarDayOfYear(date);
  const annualAngle = 2 * Math.PI * (day - 81) / 365;
  const declination = 23.44 * Math.PI / 180 * Math.sin(annualAngle);
  const hourAngle = Math.acos(Math.max(-1, Math.min(1, -Math.tan(lat) * Math.tan(declination))));
  const offset = Number(geo.timezoneOffset ?? MAP_GEOREFERENCE_FALLBACK.timezoneOffset ?? -3);
  const meridian = 15 * offset;
  const equationOfTime = 9.87 * Math.sin(2 * annualAngle) - 7.53 * Math.cos(annualAngle) - 1.5 * Math.sin(annualAngle);
  const noon = 12 - (lng - meridian) / 15 - equationOfTime / 60;
  const halfDay = hourAngle * 12 / Math.PI;
  return {
    sunrise: Math.max(4, noon - halfDay),
    solarNoon: noon,
    sunset: Math.min(21, noon + halfDay),
    lat,
    lng,
    label: geo.label || MAP_GEOREFERENCE_FALLBACK.label || 'Aliança Park · Amargosa, BA',
  };
}

/** Format a fractional solar hour for the map control. */
export function solarHourLabel(hour: number): string {
  const totalMinutes = Math.round(Math.max(0, Number(hour) || 0) * 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
}

/** Project sun progress, direction, and daylight state for a selected hour. */
export function solarStateForHour(hour: number, geo: Partial<AtlasMapSolarGeoPoint> = {}): AtlasMapSolarState {
  const window = solarWindowForGeo(geo);
  const span = Math.max(0.1, window.sunset - window.sunrise);
  const progress = Math.max(0, Math.min(1, (Number(hour) - window.sunrise) / span));
  const elevation = Math.max(0, Math.sin(progress * Math.PI));
  const azimuth = progress * Math.PI * 1.12 - Math.PI * 0.56;
  return { ...window, hour: Number(hour), progress, elevation, azimuth, daylight: elevation > 0.02 };
}

interface AtlasApplicationEventViewLayer extends HTMLElement {
  bind(): void;
  bindCommercialPagesV7(): void;
  runOperationalLoop?(event: string): Promise<unknown>;
  brokers(...args: unknown[]): unknown;
  pert(...args: unknown[]): unknown;
  actions(...args: unknown[]): unknown;
  raci(...args: unknown[]): unknown;
  raid(...args: unknown[]): unknown;
  settings(...args: unknown[]): unknown;
}

interface AtlasApplicationEventViewLayerConstructor {
  prototype: AtlasApplicationEventViewLayer;
}

/** Explicit ports used by the root event composition; route order belongs to TS. */
export interface AtlasApplicationEventCompositionInput {
  ViewLayer: AtlasApplicationEventViewLayerConstructor;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  controlPageCommandsV1: AtlasControlPageCommandsV1;
  brokersControlV8: (this: AtlasApplicationEventViewLayer, ...args: unknown[]) => unknown;
  commissionProfiles: AtlasCommercialWorkspaceEventInput['commissionProfiles'];
  downloadCsv: AtlasCommercialWorkspaceEventInput['downloadCsv'];
  esc(value: unknown): string;
  extensionStage: () => { name?: unknown };
  financeWorkspaceV8: AtlasFinancePageInstallInput['workspace'];
  ico(name: string): string;
  notify(message: string, tone?: string): void;
  reportCatalog: AtlasCommercialWorkspaceEventInput['reportCatalog'];
  syncLiveSystemReportV1: AtlasCommercialWorkspaceEventInput['syncLiveSystemReportV1'];
  apiUrl(path: string): string;
  windowRef: Window;
  documentRef: Document;
  customElementsRef: CustomElementRegistry;
}

/** Install root route events and page overrides in the original bootstrap order. */
export function installAtlasApplicationEventComposition(input: AtlasApplicationEventCompositionInput): void {
  const { ViewLayer } = input;
  installAtlasOperationalIntelligenceEvents({
    ViewLayer,
    readState: () => input.appStore.get(),
    ico: input.ico,
    notify: input.notify,
  });

  const pertStore = input.appStore as AtlasPertStore;
  installAtlasPertWorkspace({
    ViewLayer,
    getSnapshot: () => createAtlasPertWorkspaceSnapshot(
      pertStore.get(),
      String(input.extensionStage()?.name || 'Etapa operacional'),
    ),
    dispatch: (command) => applyAtlasPertCommand(pertStore, command),
    esc: input.esc as (value: unknown) => string,
    ico: input.ico as (name: string) => string,
    notify: input.notify as (message: string, tone?: string) => void,
    documentRef: input.documentRef,
    windowRef: input.windowRef,
  });
  const actionStore = input.appStore as AtlasOperationalActionStore;
  installAtlasActionsWorkspace({
    ViewLayer,
    getSnapshot: () => createAtlasActionsWorkspaceSnapshot(
      actionStore.get(),
      String(input.extensionStage()?.name || 'Etapa operacional'),
    ),
    dispatch: (command) => applyAtlasOperationalActionCommand(actionStore, command),
    esc: input.esc as (value: unknown) => string,
    ico: input.ico as (name: string) => string,
    notify: input.notify as (message: string, tone?: string) => void,
    windowRef: input.windowRef,
  });
  const raciStore = input.appStore as AtlasRaciStore;
  installAtlasRaciWorkspace({
    ViewLayer,
    getSnapshot: () => createAtlasRaciWorkspaceSnapshot(
      raciStore.get(),
      String(input.extensionStage()?.name || 'Etapa operacional'),
    ),
    dispatch: (command) => applyAtlasRaciCommand(raciStore, command),
    esc: input.esc as (value: unknown) => string,
    ico: input.ico as (name: string) => string,
    notify: input.notify as (message: string, tone?: string) => void,
  });
  const raidStore = input.appStore as AtlasRaidStore;
  installAtlasRaidWorkspace({
    ViewLayer,
    getSnapshot: () => createAtlasRaidWorkspaceSnapshot(
      raidStore.get(),
      String(input.extensionStage()?.name || 'Etapa operacional'),
    ),
    dispatch: (command) => applyAtlasRaidCommand(raidStore, command),
    esc: input.esc as (value: unknown) => string,
    ico: input.ico as (name: string) => string,
    notify: input.notify as (message: string, tone?: string) => void,
    windowRef: input.windowRef,
  });
  if (!input.customElementsRef.get('view-layer')) input.customElementsRef.define('view-layer', ViewLayer as unknown as CustomElementConstructor);

  installAtlasCommercialWorkspaceEvents({
    ViewLayer: ViewLayer as Parameters<typeof installAtlasCommercialWorkspaceEvents>[0]['ViewLayer'],
    readState: () => input.appStore.get(),
    onCommand: command => applyAtlasCommercialWorkspaceCommandV1({ command, appStore: input.appStore }),
    downloadCsv: input.downloadCsv,
    commissionProfiles: input.commissionProfiles,
    reportCatalog: input.reportCatalog,
    syncLiveSystemReportV1: input.syncLiveSystemReportV1,
    windowRef: input.windowRef as Parameters<typeof installAtlasCommercialWorkspaceEvents>[0]['windowRef'],
  });

  // Keep the control-page renderer/controller pair after the legacy commercial bindings.
  installAtlasControlPageComponentV1({
    ViewLayer: ViewLayer as unknown as Parameters<typeof installAtlasControlPageComponentV1>[0]['ViewLayer'],
    readState: () => input.appStore.get() as AtlasApplicationStoreState,
    workspace: input.financeWorkspaceV8,
    brokersRenderer: input.brokersControlV8 as unknown as Parameters<typeof installAtlasControlPageComponentV1>[0]['brokersRenderer'],
    commands: input.controlPageCommandsV1,
    apiUrl: input.apiUrl,
    esc: input.esc,
    ico: input.ico,
    windowRef: input.windowRef as Window & { lucide?: { createIcons(): void } },
  });

}

export interface AtlasControlCenterDataStoreV1 {
  get(): Record<string, any>;
  update(updater: (state: Record<string, any>) => Record<string, any>): void;
}

export interface AtlasControlCenterDataInputV1 {
  appStore: AtlasControlCenterDataStoreV1;
  formatBRL(value: unknown): string;
  publishOperationalEvent(event: Record<string, any>): Promise<unknown> | unknown;
  esc(value: unknown): string;
  ico(name: string): string;
  DateCtor?: DateConstructor;
  consoleRef?: Pick<Console, 'info'>;
}

/** Own Control Center filtering, finance rows, local audit, and realtime publication. */
export function createAtlasControlCenterDataV1(input: AtlasControlCenterDataInputV1): Readonly<Record<string, any>> {
  const { appStore, formatBRL, publishOperationalEvent, esc, ico } = input;
  if (!appStore || typeof appStore.get !== 'function' || typeof appStore.update !== 'function')
    throw new TypeError('Control Center data requires appStore.get() and appStore.update().');
  if (typeof formatBRL !== 'function') throw new TypeError('Control Center data requires formatBRL().');
  if (typeof publishOperationalEvent !== 'function') throw new TypeError('Control Center data requires publishOperationalEvent().');
  if (typeof esc !== 'function' || typeof ico !== 'function') throw new TypeError('Control Center data requires esc() and ico().');

  const DateImpl = input.DateCtor || Date;
  const isAssistantVisualAdditionV1 = (item: Record<string, any>): boolean => {
    if (!item || typeof item !== 'object') return false;
    if (item.source === 'chat-visual') return true;
    const properties = Array.isArray(item.properties)
      ? item.properties
      : item.properties && typeof item.properties === 'object'
        ? Object.entries(item.properties).map(([id, value]) => ({ id, value }))
        : [];
    return properties.some((property: Record<string, any>) =>
      property?.id === 'allocation_source' && /assistente operacional|leitura visual|ocr/i.test(String(property.value || '')),
    );
  };
  const controlCenterMaterialRowsV1 = (state: Record<string, any>): Array<Record<string, any>> => {
    const overrides = state.controlMaterialOverrides || {};
    const records = Array.isArray(state.records) ? state.records : [];
    return (Array.isArray(state.materialCatalogAdditions) ? state.materialCatalogAdditions : [])
      .filter(isAssistantVisualAdditionV1)
      .map((item: Record<string, any>) => {
        const sourceRecord = records.find((record: Record<string, any>) => String(record.id) === String(item.sourceRecordId));
        const itemAttachments = item.attachments;
        const hasItemAttachments = Array.isArray(itemAttachments)
          ? itemAttachments.length > 0
          : Boolean(itemAttachments && typeof itemAttachments === 'object' && Object.keys(itemAttachments).length);
        return {
          ...sourceRecord,
          ...item,
          properties: Array.isArray(item.properties) && item.properties.length ? item.properties : sourceRecord?.properties || item.properties || [],
          attachments: hasItemAttachments ? itemAttachments : sourceRecord?.attachments || [],
          files: item.files?.length ? item.files : sourceRecord?.files || [],
          evidencias: item.evidencias?.length ? item.evidencias : sourceRecord?.evidencias || [],
          evidenceUri: item.evidenceUri || sourceRecord?.evidenceUri,
          comprovante: item.comprovante || sourceRecord?.comprovante,
          ...(overrides[item.id] || {}),
        };
      })
      .filter((item: Record<string, any>) => !overrides[item.id]?.deleted);
  };
  const controlCenterFinanceRowsV1 = (state: Record<string, any>): Array<Record<string, any>> => {
    const rows = Array.isArray(state.cashFlowLocal) ? state.cashFlowLocal : [];
    return rows.length ? rows.slice(0, 10) : [{
      id: 'DEMO-CAIXA-01', date: '—', kind: 'Saldo inicial', stage: 'Projeto', amount: 0,
      description: 'Nenhum lançamento local neste dispositivo',
    }];
  };
  const controlCenterMoneyV1 = (value: Record<string, any> | null | undefined): string =>
    formatBRL(Number(value?.amount ?? value?.value ?? 0));
  const controlCenterRecordChangeV1 = (label: string, detail: string, entity: Record<string, any> = {}): Record<string, any> => {
    const at = new DateImpl().toISOString();
    const entry = {
      id: `CTRL-${DateImpl.now().toString(36).toUpperCase()}`,
      label, detail, entity, at,
      actor: appStore.get().currentActor?.name || 'Usuário autorizado',
    };
    appStore.update(state => ({
      ...state,
      controlChangeLog: [entry, ...(state.controlChangeLog || [])].slice(0, 30),
      lastAction: `Central ouviu: ${label}`,
    }));
    return entry;
  };
  const controlCenterPublishV1 = (event: string, entity: string, entityId: string, payload: Record<string, any>): Promise<unknown> =>
    Promise.resolve(publishOperationalEvent({
      actor: appStore.get().currentActor || {},
      type: event,
      entity,
      entityId,
      payload: { ...payload, projectId: 'project-alianca-park' },
    })).catch(error => {
      (input.consoleRef || globalThis.console).info('Evento da Central mantido localmente; RTDB indisponível.', error);
      return undefined;
    });
  const controlCenterMaterialsAccordionMarkupV1 = (materials: Array<Record<string, any>>, stages: Array<Record<string, any>>): string =>
    renderAtlasControlCenterMaterialsAccordionV1({ materials, stages, esc, ico });

  return Object.freeze({
    isAssistantVisualAdditionV1,
    controlCenterMaterialRowsV1,
    controlCenterFinanceRowsV1,
    controlCenterMoneyV1,
    controlCenterRecordChangeV1,
    controlCenterPublishV1,
    controlCenterMaterialsAccordionMarkupV1,
  });
}

export interface AtlasControlStageContextProgramInputV1 {
  readIntegrationSettings(): Record<string, any> | null | undefined;
  normalizeStageMaterialRows(value: unknown, fallback: Array<Record<string, any>>): Array<Record<string, any>>;
  defaultStageMaterialRows(stage: Record<string, any>): Array<Record<string, any>>;
  stageV9LiveFor(stage: Record<string, any>): Record<string, any> | null | undefined;
  stageV9StatusFor(live: Record<string, any>): unknown;
  esc(value: unknown): string;
  ico(name: string): string;
  STAGE_WORKBENCH: ReadonlyArray<AtlasWorkbenchActivityRouteStageV1>;
  workbenchStageFromValueV1(value: unknown): Record<string, any> | null;
  splitStageConfigList(value: unknown): string[];
}

/** Project stage comprehension from persisted app settings and bind typed view owners. */
export function createAtlasControlStageContextV1(input: AtlasControlStageContextProgramInputV1): AtlasControlStageContextViewsV1 & {
  controlStageProfileV1(stage: Record<string, any>, state: Record<string, any>): Record<string, any>;
  controlStageMaterialRowsV1(stage: Record<string, any>, profile: Record<string, any>): Array<Record<string, any>>;
} {
  const controlStageProfileV1 = (stage: Record<string, any>, state: Record<string, any>): Record<string, any> => {
    const settings = { ...(input.readIntegrationSettings() || {}), ...(state.integrationSettings || {}) };
    return { ...(stage?.executionProfile || {}), ...(settings.stageProfiles?.[stage?.key] || {}) };
  };
  const controlStageMaterialRowsV1 = (stage: Record<string, any>, profile: Record<string, any>): Array<Record<string, any>> =>
    input.normalizeStageMaterialRows(profile?.materialsTable, input.defaultStageMaterialRows(stage || {}));
  const views = createAtlasControlStageContextViewsV1({
    controlStageProfileV1,
    controlStageMaterialRowsV1,
    stageV9LiveFor: stage => input.stageV9LiveFor(stage) || {},
    stageV9StatusFor: input.stageV9StatusFor,
    esc: input.esc,
    ico: input.ico,
    STAGE_WORKBENCH: input.STAGE_WORKBENCH,
    workbenchStageFromValueV1: input.workbenchStageFromValueV1,
    splitStageConfigList: input.splitStageConfigList,
  });
  return Object.freeze({ ...views, controlStageProfileV1, controlStageMaterialRowsV1 });
}

export interface AtlasControlStageInlineRecordDraftV1 {
  stageKey: string;
  stageName: string;
  values: Record<string, unknown>;
}

export function buildAtlasControlStageInlineRecordSubmissionV1(
  input: AtlasControlStageInlineRecordDraftV1 & { now?: Date },
): Record<string, unknown> {
  const values = input.values;
  const now = input.now || new Date();
  const pad = (value: number): string => String(value).padStart(2, '0');
  const category = String(values.category || 'execucao');
  const progress = Number(values.progress || 0);
  const details = String(values.details || '').trim();
  return {
    obra: 'Aliança Park',
    etapa: input.stageName,
    categoria: category,
    tipo: category,
    atividade: String(values.activity || input.stageName).trim() || input.stageName,
    data: String(values.date || `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`),
    hora: String(values.time || `${pad(now.getHours())}:${pad(now.getMinutes())}`),
    responsavel: String(values.responsible || '').trim(),
    detalhes: `${details}\nAvanço confirmado: ${progress}%`,
    progresso: progress,
    evidenceUri: String(values.evidenceUri || '') || undefined,
    status: String(values.status || 'Pendente'),
  };
}

export async function createAtlasControlStageInlineRecordV1(input: AtlasControlStageInlineRecordDraftV1 & {
  appStore: { get(): Record<string, any>; update(updater: (state: Record<string, any>) => Record<string, any>): unknown };
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
  operationalHeaders(headers?: Record<string, string>): HeadersInit;
}): Promise<Record<string, any>> {
  const payload = buildAtlasControlStageInlineRecordSubmissionV1(input);
  const response = await input.apiFetch('/api/records', {
    method: 'POST',
    headers: input.operationalHeaders({ 'Content-Type': 'application/json' }),
    body: JSON.stringify(payload),
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const record = await response.json() as Record<string, any>;
  input.appStore.update(current => ({
    ...current,
    records: [record, ...(current.records || [])],
    selectedPlanningStage: input.stageKey || current.selectedPlanningStage,
    lastAction: `Criou registro de ${String(input.values.activity || input.stageName)} destinado à etapa ${input.stageName}`,
  }));
  return record;
}

