/** Preserve the original registration order while keeping finance composition in the TypeScript program. */
export async function installAtlasFinanceApplicationCompositionV1(input: AtlasFinanceApplicationCompositionInput): Promise<Readonly<AtlasFinanceApplicationCompositionOutputV1>> {
  const {
    ViewLayer, appStore, demoData, executionModel, commissionProfiles, commissionDeals,
    publishOperationalEvent, esc, ico, notify, apiFetch, apiUrl, downloadCsv,
    stageOverlayLabels,
    stageOverlayKey, stagePlanning, stageRecordReaders, reportCatalog, globalRef,
    documentRef, windowRef, confirmRef, EventCtor, FormDataCtor,
  } = input;
  const brlToNumber = (value: unknown): number =>
    Number(String(value || "").replace(/[^\d,]/g, "").replace(",", ".")) || 0;
  const formatBRL = (value: unknown): string =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(value) || 0);
  const commercialScopeV1 = createAtlasCommercialScopeV1({
    appStore: appStore as AtlasCommercialScopeStoreV1,
    commissionProfiles: commissionProfiles as AtlasCommissionProfileCatalogEntry[],
    commissionDeals: commissionDeals as AtlasCommissionDealV1[],
  });
  const controlCenter = createAtlasControlCenterDataV1({
    appStore: appStore as AtlasControlCenterDataStoreV1,
    formatBRL,
    publishOperationalEvent: publishOperationalEvent as AtlasControlCenterDataInputV1['publishOperationalEvent'],
    esc: esc as (value: unknown) => string,
    ico: ico as (name: string) => string,
    DateCtor: globalRef.Date,
    consoleRef: globalRef.console,
  });

  installAtlasStagesMapRuntimeGuardV1(ViewLayer as unknown as Parameters<typeof installAtlasStagesMapRuntimeGuardV1>[0], { readState: () => appStore.get(), documentRef });
  const operationalHeaders = createOperationalHeadersV1({ appStore: appStore as Parameters<typeof createOperationalHeadersV1>[0]['appStore'] });
  const viewLayerBindWithCommissions = ViewLayer.prototype.bind;
  installAtlasCommissionProfileBindingV1(ViewLayer as unknown as Parameters<typeof installAtlasCommissionProfileBindingV1>[0], {
    viewLayerBindWithCommissions, readState: () => appStore.get(), commissionDeals, commissionProfiles, notify, documentRef, windowRef,
    onAction: (action: AtlasCommissionProfileActionV1) => {
      const store = appStore as { get(): Record<string, any>; set(patch: Record<string, unknown>): void };
      const notifyAction = notify as (message: string, tone?: string) => void;
      const result = createAtlasCommissionProfileActionResultV1({
        action,
        deals: commissionDeals as AtlasCommissionDealV1[],
        profiles: commissionProfiles as AtlasCommissionProfileCatalogEntry[],
      });
      if (!result) return;
      if (result.patch) store.set(result.patch);
      if (result.notification) notifyAction(result.notification.message, result.notification.tone);
      if (result.openExternalUrl) windowRef.open(result.openExternalUrl, '_blank', 'noopener');
    },
  } as Parameters<typeof installAtlasCommissionProfileBindingV1>[1]);

  const brokersControlV8 = createAtlasBrokerControlPageV1({
    readState: () => appStore.get(), commissionDeals, commissionProfiles,
    brokerReasonsV9: (state: Record<string, unknown>) => projectAtlasBrokerCommissionReasonsV1(state as AtlasBrokerCommissionReportStateV1),
    brlToNumber, formatBRL, esc, ico,
    queueMicrotaskFn: globalRef.queueMicrotask.bind(globalRef),
  } as Parameters<typeof createAtlasBrokerControlPageV1>[0]);
  const financeWorkspaceV8 = createAtlasFinanceWorkspace({
    readState: () => appStore.get(), executionModel, esc, ico, formatBRL,
    queueMicrotaskFn: globalRef.queueMicrotask.bind(globalRef), DateCtor: globalRef.Date,
  });
  const cashRecordLauncherMarkupV1 = financeWorkspaceV8.cashRecordLauncherMarkupV1;
  const controlPageCommandsV1 = createAtlasControlPageCommandsV1({ appStore, apiFetch, operationalHeaders, notify, FileReaderCtor: globalRef.FileReader } as AtlasControlPageCommandInputV1);

  installAtlasOperationalViewBindingsV1(ViewLayer as Parameters<typeof installAtlasOperationalViewBindingsV1>[0], {
    readState: () => appStore.get(),
    demoLeads: (demoData.leads || []) as Parameters<typeof installAtlasOperationalViewBindingsV1>[1]['demoLeads'],
    downloadCsv: downloadCsv as Parameters<typeof installAtlasOperationalViewBindingsV1>[1]['downloadCsv'],
    commissionDeals: commissionDeals as unknown as Parameters<typeof installAtlasOperationalViewBindingsV1>[1]['commissionDeals'],
    commissionProfiles: commissionProfiles as Parameters<typeof installAtlasOperationalViewBindingsV1>[1]['commissionProfiles'],
    confirmRef, documentRef, EventCtor, FormDataCtor, ico, notify,
    onAction: (action: AtlasOperationalViewActionV1) => {
      const store = appStore as { set(patch: Record<string, unknown>): void };
      if (action === 'open-cash-record') store.set({ lastAction: 'Abriu o registro de caixa' });
      else if (action === 'open-stage-requirements') store.set({ selectedStageDetailTab: 'requisitos', lastAction: 'Abriu a aba Requisitos da etapa' });
      else if (action === 'open-stage-records') store.set({ view: 'records', activityDedicated: false, lastAction: 'Abriu Andamento nos registros completos' });
    },
    onLeadsCommand: command => applyAtlasLeadsToolbarCommandV1({ command, appStore }),
    onCommissionCommand: command => applyAtlasCommissionWorkspaceCommandV1({
      command,
      appStore,
      commissionDeals: commissionDeals as AtlasCommissionDealV1[],
      DateCtor: globalRef.Date,
      formatBRL,
      brlToNumber,
    }),
  } as Parameters<typeof installAtlasOperationalViewBindingsV1>[1]);
  const selectedPlanningStageV1 = (): AtlasStagePlanningActivityV1 => {
    const selectedId = appStore.get().selectedStage;
    return (
      demoData.activities.find(item => item.id === selectedId) || demoData.activities[0]
    ) as AtlasStagePlanningActivityV1;
  };
  const stagePlanningExtensionsInputV1: Parameters<typeof installAtlasStagePlanningExtensionsV1>[1] = {
    stages: demoData.activities as AtlasStagePlanningActivityV1[],
    ...stagePlanning, selectedStage: selectedPlanningStageV1,
    ico, stageOverlayLabels, esc, documentRef,
    onAction: (action: AtlasStagePlanningExtensionActionV1) => {
      if (action.kind === 'open-dedicated-stage') {
        appStore.set({ activityDedicated: true, lastAction: 'Abriu página dedicada da etapa' });
      } else if (action.kind === 'select-planning-tab') {
        appStore.set({ lastAction: `Abriu ${action.label || 'aba'} do planejamento` });
      } else if (action.kind === 'create-stage-relation') {
        notify('Relação pronta para ser rotulada entre as etapas.', 'success');
      } else if (action.kind === 'add-stage-todo') {
        notify('Novo afazer adicionado à lista da etapa.', 'success');
      } else if (action.kind === 'expand-stage-detail') {
        notify('O destrinchamento permanece visível durante o acompanhamento da etapa.', 'success');
      } else if (action.kind === 'edit-stage-activity') {
        notify('Edição da atividade aberta no painel de propriedades.', 'success');
      } else if (action.kind === 'delete-stage-activity') {
        notify('Atividade marcada para exclusão; confirme no fluxo de execução.', 'warning');
      }
    },
  };
  installAtlasStagePlanningExtensionsV1(ViewLayer as Parameters<typeof installAtlasStagePlanningExtensionsV1>[0], stagePlanningExtensionsInputV1);
  installAtlasCommissionHistoryControlsV1(ViewLayer as unknown as Parameters<typeof installAtlasCommissionHistoryControlsV1>[0], {
    readState: () => appStore.get(), brlToNumber, commissionDeals, commissionProfiles, esc, formatBRL, ico, notify,
    documentRef, windowRef, setTimeoutRef: globalRef.setTimeout,
    onAction: (action: AtlasCommissionHistoryActionV1) => {
      const store = appStore as { get(): Record<string, any>; set(patch: Record<string, unknown>): void };
      const profiles = commissionProfiles as Array<{ id: string; name: string }>;
      const result = createAtlasCommissionHistoryActionResultV1({
        action,
        state: store.get() as AtlasApplicationStoreState,
        profiles,
        brlToNumber,
        formatBRL,
        DateCtor: globalRef.Date,
      });
      if (result.patch) store.set(result.patch);
      if (result.notification) (notify as (message: string, tone?: string) => void)(result.notification.message, result.notification.tone);
    },
  } as Parameters<typeof installAtlasCommissionHistoryControlsV1>[1]);

  const liveReportBuildersV1 = createAtlasLiveReportBuilders({ reportCatalog, formatBRL, ...stageRecordReaders });
  const {
    syncCashEvidenceReportV1, syncConstructionFinanceReportsV1,
    syncServiceCompletionReportV1, syncLiveSystemReportV1,
  } = liveReportBuildersV1;
  const cashEvidenceAttachmentPortsV1 = createAtlasCashEvidenceAttachmentPortsV1({
    appStore,
    apiFetch,
    operationalHeaders,
  });
  const installLegacyReportsWorkspaceV1 = (): void => installAtlasReportsWorkspaceV1(ViewLayer, {
    readState: () => appStore.get(), syncCashEvidenceReportV1, syncConstructionFinanceReportsV1,
    syncServiceCompletionReportV1, syncLiveSystemReportV1, reportCatalog,
    commands: createAtlasReportsWorkspaceCommandsV1({ appStore, reportCatalog }), notify,
    documentRef, FileReaderCtor: globalRef.FileReader,
    attachCashEvidenceV1: cashEvidenceAttachmentPortsV1.attach,
    downloadCashEvidenceFileV1: cashEvidenceAttachmentPortsV1.download,
    URLRef: globalRef.URL, BlobCtor: globalRef.Blob,
    windowRef: globalRef.window, schedule: globalRef.setTimeout.bind(globalRef),
  });
  if (input.deferLegacyReportsWorkspaceV1 !== true) installLegacyReportsWorkspaceV1();

  return Object.freeze({
    brlToNumber, formatBRL, commercialScopeV1, ...controlCenter, operationalHeaders,
    brokersControlV8, financeWorkspaceV8, cashRecordLauncherMarkupV1,
    controlPageCommandsV1, liveReportBuildersV1,
    installLegacyReportsWorkspaceV1,
    syncCashEvidenceReportV1, syncConstructionFinanceReportsV1,
    syncServiceCompletionReportV1, syncLiveSystemReportV1,
  });
}

type AtlasCommissionNegotiationStoreV1 = {
  get(): AtlasCommissionNegotiationStateV1;
  set(patch: Record<string, unknown>): void;
};

/** Own authenticated persistence and app-store commits for negotiation form commands. */
export function installAtlasCommissionNegotiationPersistenceV1(input: {
  documentRef?: Pick<Document, 'addEventListener' | 'removeEventListener'>;
  appStore: AtlasCommissionNegotiationStoreV1;
  commissionDeals: AtlasCommissionNegotiationDealV1[];
  commissionProfiles: AtlasCommissionProfileCatalogEntry[];
  formatBRL: (value: unknown) => string;
  brlToNumber: (value: unknown) => number;
  apiFetch: (path: string, init?: RequestInit) => Promise<Response>;
  operationalHeaders: (headers?: Record<string, string>) => HeadersInit;
  notify: (message: string, tone?: string) => void;
  DateCtor?: DateConstructor;
  logger?: Pick<Console, 'info'>;
}): () => void {
  const {
    documentRef,
    appStore,
    commissionDeals,
    commissionProfiles,
    formatBRL,
    brlToNumber,
    apiFetch,
    operationalHeaders,
    notify,
    DateCtor = Date,
    logger = console,
  } = input;
  if (!documentRef) return () => undefined;
  if (typeof appStore?.get !== 'function' || typeof appStore?.set !== 'function' ||
      typeof apiFetch !== 'function' || typeof operationalHeaders !== 'function' ||
      typeof notify !== 'function')
    throw new TypeError('Commission persistence requires store, API, auth headers, and notifications.');

  const onSave = (event: Event): void => {
    const command = (event as CustomEvent<AtlasCommissionNegotiationSaveCommandV1>).detail;
    if (!command || typeof command.id !== 'string' || !command.fields || !Array.isArray(command.files)) return;
    void (async () => {
      const current = appStore.get();
      const deal = current.commissionEntries?.find(item => item.id === command.id) ||
        commissionDeals.find(item => item.id === command.id);
      if (!deal) {
        notify(`Negociação ${command.id} não encontrada.`, 'error');
        return;
      }

      const fields = command.fields;
      const value = fields.value ?? deal.value;
      const rate = fields.rate ?? deal.rate;
      const profileId = fields.profile ?? deal.profile;
      const profile = commissionProfiles.find(item => item.id === profileId);
      const nextDeal: AtlasCommissionNegotiationDealV1 = {
        ...deal,
        id: command.id,
        profile: profileId,
        client: fields.client ?? deal.client,
        cpf: fields.cpf ?? deal.cpf,
        lot: fields.lot ?? deal.lot,
        quadra: fields.quadra ?? deal.quadra,
        value,
        commission: formatBRL((brlToNumber(value) * brlToNumber(rate)) / 100),
        rate,
        status: fields.status ?? deal.status,
        stage: fields.stage ?? deal.stage,
        date: deal.date || new DateCtor().toLocaleDateString('pt-BR'),
        payment: fields.payment ?? deal.payment,
        purpose: fields.purpose ?? deal.purpose,
        notes: fields.notes ?? deal.notes,
      };
      const previousAttachments = current.commissionDealAttachments?.[command.id] || {};
      let persisted = false;
      try {
        if (command.attachmentReadFailed) throw new Error('Falha ao ler anexo selecionado.');
        const existingResponse = await apiFetch('/api/commercial-sales');
        const existingPayload: unknown = existingResponse.ok
          ? await existingResponse.json()
          : { sales: [] };
        const sales = typeof existingPayload === 'object' && existingPayload !== null &&
          'sales' in existingPayload && Array.isArray(existingPayload.sales)
          ? existingPayload.sales as Array<{ id?: unknown }>
          : [];
        const existing = sales.some(item => item.id === command.id);
        const rawValue = String(value || '').replace(/[^\d,]/g, '').replace(/\./g, '').replace(',', '.');
        const response = await apiFetch(
          existing ? `/api/commercial-sales/${encodeURIComponent(command.id)}` : '/api/commercial-sales',
          {
            method: existing ? 'PUT' : 'POST',
            headers: operationalHeaders({ 'Content-Type': 'application/json' }),
            body: JSON.stringify({
              id: command.id,
              lot: nextDeal.lot,
              client: nextDeal.client,
              broker: profile?.name || '',
              status: nextDeal.status,
              valueCents: Math.round((Number(rawValue) || 0) * 100),
              notes: nextDeal.notes || '',
              files: command.files,
            }),
          },
        );
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        persisted = true;
      } catch (error) {
        logger.info('Negociação e anexos mantidos localmente; serviço comercial indisponível.', error);
      }

      appStore.set({
        commissionEntries: [
          ...(current.commissionEntries || []).filter(item => item.id !== command.id),
          nextDeal,
        ],
        commissionDealAttachments: {
          ...(current.commissionDealAttachments || {}),
          [command.id]: {
            contract: [
              ...(previousAttachments.contract || []),
              ...(command.attachments.contract || []),
            ],
            client: [
              ...(previousAttachments.client || []),
              ...(command.attachments.client || []),
            ],
          },
        },
        view: 'brokers',
        selectedCommissionNegotiation: null,
        lastAction: `Salvou a negociação ${command.id} com anexos vinculados`,
      });
      notify(
        `Negociação ${command.id} salva${persisted ? ' e anexos enviados ao serviço comercial' : ' localmente com anexos vinculados'}.`,
        persisted ? 'success' : 'warning',
      );
    })();
  };

  documentRef.addEventListener('atlas:commission-negotiation-save-v1', onSave);
  return () => documentRef.removeEventListener('atlas:commission-negotiation-save-v1', onSave);
}

type AtlasCommercialViewLayerConstructor = {
  prototype: HTMLElement & Record<string, unknown>;
};

/** MJS service adapters remain injected; TypeScript owns commercial composition order and routes. */
export interface AtlasCommercialApplicationCompositionInput {
  ViewLayer: AtlasCommercialViewLayerConstructor;
  appStore: AtlasCommissionNegotiationStoreV1;
  commissionDeals: AtlasCommissionNegotiationDealV1[];
  commissionProfiles: AtlasCommissionProfileCatalogEntry[];
  repassePriceCatalog: RepassePriceCatalogEntry[];
  esc: (value: unknown) => string;
  ico: (name: string) => string;
  formatBRL: (value: unknown) => string;
  brlToNumber: (value: unknown) => number;
  contractStatusClassV1: (status: unknown) => string;
  apiFetch: (path: string, init?: RequestInit) => Promise<Response>;
  operationalHeaders: (headers?: Record<string, string>) => HeadersInit;
  notify: (message: string, tone?: string) => void;
  globalRef?: typeof globalThis;
  createCommissionNegotiationViewsV1: (
    dependencies: AtlasCommissionNegotiationViewsInputV1,
  ) => AtlasCommissionNegotiationViewsV1;
}

/** Keep the historic commercial registration order while the typed program owns the composition root. */
export function installAtlasCommercialApplicationCompositionV1(
  input: AtlasCommercialApplicationCompositionInput,
): Readonly<AtlasCommissionNegotiationViewsV1 & {
  lotDetailPageV1: {
    downloadBrandedLotExcelV1(options: { lots?: Array<RepassePriceCatalogEntry & Record<string, unknown>>; title?: string; subtitle?: string; filename?: string }): void;
  };
  disposeNegotiationPersistenceV1(): void;
}> {
  const {
    ViewLayer, appStore, commissionDeals, commissionProfiles, repassePriceCatalog,
    esc, ico, formatBRL, brlToNumber, contractStatusClassV1, apiFetch,
    operationalHeaders, notify,
  } = input;
  const globalRef = input.globalRef || globalThis;
  const disposeNegotiationPersistenceV1 = installAtlasCommissionNegotiationPersistenceV1({
    documentRef: globalRef.document,
    appStore,
    commissionDeals,
    commissionProfiles,
    formatBRL,
    brlToNumber,
    apiFetch,
    operationalHeaders,
    notify,
    DateCtor: globalRef.Date,
    logger: globalRef.console,
  });
  const negotiation = input.createCommissionNegotiationViewsV1({
    readState: () => appStore.get(),
    onAction: action => appStore.set(createAtlasCommissionNegotiationPageActionResultV1({
      action,
      state: appStore.get(),
      profiles: commissionProfiles,
      DateCtor: globalRef.Date,
    })),
    commissionDeals, commissionProfiles, esc, ico, formatBRL,
    brlToNumber, contractStatusClassV1, FileReader: globalRef.FileReader,
    Date: globalRef.Date, FormData: globalRef.FormData,
    windowRef: globalRef.window,
  });
  installAtlasCommissionNegotiationComponentControllerV1(ViewLayer, negotiation);

  const lotDetailPageV1 = Object.freeze({
    downloadBrandedLotExcelV1: (options: { lots?: Array<RepassePriceCatalogEntry & Record<string, unknown>>; title?: string; subtitle?: string; filename?: string }) => downloadAtlasBrandedLotExcelV1(options, globalRef),
  });
  return Object.freeze({ ...negotiation, lotDetailPageV1, disposeNegotiationPersistenceV1 });
}

