/** Own the map scene's startup, shared lifecycle, georeference, and presentation setup order. */
export function installAtlasMapSceneFoundationCompositionV1(
  ports: AtlasMapSceneFoundationCompositionPorts,
): void {
  const {
    scene, config, appStore, demoData, viewThemes, compactMapMirrors,
    setSharedMapScene, stageOverlayKey, stageOverlayLabels, validGeoPoint,
    georeference, aerialFrame, solar, services, environment: browser, owners,
  } = ports;
  const install = (owner: AtlasMapSceneInstallerOwners, dependencies: Record<string, unknown> = {}): unknown => {
    const installer = owner.typed;
    if (typeof installer !== 'function') throw new TypeError('Map scene owner is missing its TypeScript installer.');
    return installer(scene, dependencies);
  };
  const windowRef = browser.window as Window;
  const performanceRef = browser.performance as Performance;
  const consoleRef = browser.console as Console;
  const sceneStateCommands = createAtlasMapSceneStateCommandsV1(appStore);

  install(owners.referenceAerialFrame, aerialFrame);
  install(owners.startupReadiness, {
    windowRef,
    performanceRef,
    requestAnimationFrame: windowRef.requestAnimationFrame.bind(windowRef),
    setTimeout: windowRef.setTimeout.bind(windowRef),
    getComputedStyle: browser.getComputedStyle,
    consoleRef,
  });
  install(owners.cleanup, { compactMapMirrors });
  install(owners.connection, {
    ADMIN_FIXED_MAP_ROTATION_DEG: config.ADMIN_FIXED_MAP_ROTATION_DEG,
    ADMIN_REFERENCE_AERIAL_INITIAL_SCENE_ZOOM: config.ADMIN_REFERENCE_AERIAL_INITIAL_SCENE_ZOOM,
    ADMIN_REFERENCE_AERIAL_VIEW_VERSION: config.ADMIN_REFERENCE_AERIAL_VIEW_VERSION,
    DASHBOARD_INITIAL_SCENE_ZOOM: config.DASHBOARD_INITIAL_SCENE_ZOOM,
    INITIAL_SCENE_ZOOM: config.INITIAL_SCENE_ZOOM,
    MAP_SCENE_STATE_VERSION: config.MAP_SCENE_STATE_VERSION,
    MAX_SCENE_ZOOM: config.MAX_SCENE_ZOOM,
    MIN_SCENE_ZOOM: config.MIN_SCENE_ZOOM,
    appStore,
    commands: sceneStateCommands,
    demoData,
    esc: services.esc,
    ico: services.ico,
    performanceRef,
    setSharedMapScene,
    stageOverlayKey,
    stageOverlayLabels,
  });
  install(owners.leaflet, {
    viewThemes,
    mapCameraView: config.MAP_CAMERA_VIEW,
    validGeoPoint,
    appStore,
    commands: sceneStateCommands,
    leaflet: browser.leaflet,
    windowRef,
    performanceRef,
    ResizeObserverImpl: browser.ResizeObserver,
  });
  install(owners.dwgGeoreference, {
    url: georeference.url,
    fallback: georeference.fallback,
    appStore,
    localClockHourForGeo: solar.localClockHourForGeo,
    validGeoPoint,
    fetchRef: windowRef.fetch.bind(windowRef),
    consoleRef,
  });
  install(owners.geometryOverlays, { logger: consoleRef });
  const mapLoadingBootStateGlobal = browser.globalRef as AtlasMapLoadingBootStateGlobalV1;
  if (!mapLoadingBootStateGlobal)
    throw new TypeError('Map loading boot-state program requires the application global.');
  install(owners.loadingScreen, {
    GENERATED_AERIAL_ASSET: config.GENERATED_AERIAL_ASSET,
    browser,
    ...createAtlasMapLoadingBootStateCommandsV1({
      globalRef: mapLoadingBootStateGlobal,
      performanceNow: () => performanceRef.now(),
      writeStorage: (key, value) => mapLoadingBootStateGlobal.localStorage?.setItem(key, value),
      wallClock: () => new mapLoadingBootStateGlobal.Date().toISOString(),
    }),
  });
  install(owners.surfacePolicy, { locationRef: browser.location });
  install(owners.publicLotStatus, { CustomEventImpl: browser.CustomEvent });
  install(owners.solarLighting, {
    appStore,
    commands: sceneStateCommands,
    MAP_GEOREFERENCE_FALLBACK: georeference.fallback,
    localClockHourForGeo: solar.localClockHourForGeo,
    notify: services.notify,
    solarHourLabel: solar.solarHourLabel,
    solarStateForHour: solar.solarStateForHour,
    solarWindowForGeo: solar.solarWindowForGeo,
    windowRef,
  });
}

