/** Apply stage-chrome navigation and selection commands to application state. */
export function applyAtlasStageContextChromeActionV1(input: {
  action: AtlasStageContextChromeActionV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  demoData: { activities: Array<Record<string, any>> };
  executionModel: { stages: Array<Record<string, any>> };
  stageContextV1(state?: Record<string, any>): Record<string, any>;
}): void {
  const { action, appStore, demoData, executionModel, stageContextV1 } = input;
  if (action.type === 'navigate-view') {
    const current = appStore.get(), { model, record: stage } = stageContextV1();
    appStore.set({
      view: action.view,
      selectedStage: stage?.id || current.selectedStage,
      selectedStageV9: model?.key || current.selectedStageV9,
      activityDedicated: false,
      stageActivityDedicatedV9: false,
      selectedActivity: null,
      activityRecordModalOpenV1: false,
      editingRecord: null,
      recordContext: null,
      stageRecordsContext: action.view === 'records',
      recordFilters: action.view === 'records'
        ? { ...(current.recordFilters || {}), stage: stage?.name || '', entity: 'records' }
        : current.recordFilters,
      lastAction: `Abriu ${action.buttonLabel} da etapa ${stage?.name || ''}`,
    });
    return;
  }
  if (action.type === 'select-timeline-stage') {
    const stage = executionModel.stages.find(item => String(item.key) === action.stageKey);
    appStore.set({
      selectedStageV9: action.stageKey,
      stageSelected: true,
      ...(action.source === 'keyboard' ? {} : {
        lastAction: action.source === 'card'
          ? `Selecionou a etapa ${action.stageKey} na timeline`
          : `Selecionou a etapa ${stage?.name || action.stageKey} no menu mobile`,
      }),
    });
    return;
  }
  if (action.type === 'open-timeline-stage') {
    const stage = executionModel.stages.find(item => String(item.key) === action.stageKey);
    if (!stage) return;
    const record = demoData.activities.find(item => String(item.name).toLocaleLowerCase('pt-BR') === String(stage.name || '').toLocaleLowerCase('pt-BR'));
    appStore.set({
      view: 'stages',
      selectedStage: record?.id || stage.key,
      selectedStageV9: action.stageKey,
      activityDedicated: true,
      stageActivityDedicatedV9: false,
      dashboardStageFocus: '',
      lastAction: `Abriu a etapa ${stage.name} pela linha do tempo`,
    });
  }
}

