/** Apply control-center selections to the application state. */
export function applyAtlasControlCenterPageActionV1(input: {
  action: AtlasControlCenterPageActionV1;
  state: Record<string, any>;
}): Record<string, any> {
  const { action, state } = input;
  switch (action.type) {
    case 'select-stage':
      return {
        ...state,
        selectedPlanningStage: action.stageKey,
        lastAction: action.source === 'selector'
          ? `Selecionou compreensão da etapa ${action.stageKey}`
          : action.stageKey
            ? `Abriu o formulário da etapa ${action.stageKey}`
            : 'Abriu a base de todas as frentes',
      };
    default:
      return state;
  }
}

/** Install Central de operação, stage context, stage tabs, and 3D header in source order. */
export function installAtlasControlCenterApplicationCompositionV1(
  input: AtlasControlCenterApplicationCompositionInputV1,
): Readonly<Record<string, any>> {
  const controlStageContextV1 = createAtlasControlStageContextV1({
    readIntegrationSettings: input.readIntegrationSettings,
    ...input.stageContext,
    esc: input.esc,
    ico: input.ico,
  });
  const saveControlStageContextV1: AtlasControlCenterPageDependenciesV1['saveControlStageContextV1'] = async ({ stageKey, payload }) => {
    const currentSettings = {
      ...(input.readIntegrationSettings() || {}),
      ...(input.appStore.get().integrationSettings || {}),
    };
    const previousProfile = currentSettings.stageProfiles?.[stageKey] || {};
    const changedFields = [
      'requirements', 'conditions', 'typicalDescription', 'organizationRequest',
      'organizationContext', 'requestHints', 'evidenceFocus', 'procurementFocus',
      'production', 'materialsTable', 'notificationTargets',
    ].filter(field => JSON.stringify(previousProfile[field] ?? '') !== JSON.stringify(payload[field] ?? ''));
    const nextSettings = {
      ...currentSettings,
      stageProfiles: { ...(currentSettings.stageProfiles || {}), [stageKey]: payload },
    };
    globalThis.localStorage.setItem(input.integrationSettingsKey, JSON.stringify(nextSettings));
    input.appStore.set({
      integrationSettings: nextSettings,
      selectedPlanningStage: stageKey,
      aiComprehensionChanges: { stageKey, fields: changedFields, at: new Date().toISOString() },
      lastAction: `Salvou compreensão operacional da etapa ${stageKey}`,
    });

    const stage = input.executionModel.stages.find(item => item.key === stageKey);
    const dbStage = input.demoData.activities.find(item => item.name === stage?.name);
    const actor = input.appStore.get().currentActor || {};
    try {
      if (dbStage?.id) {
        const response = await input.apiFetch(`/api/stages-admin/${encodeURIComponent(dbStage.id)}/ai`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            'x-belavista-role': actor.role || 'admin',
            'x-belavista-user': actor.uid || 'local-admin',
            'x-belavista-name': actor.name || 'Administrador',
          },
          body: JSON.stringify({
            requirements: payload.requirements,
            conditions: payload.conditions,
            typicalDescription: payload.typicalDescription,
            organizationRequest: payload.organizationRequest,
            organizationContext: payload.organizationContext,
            requestHints: payload.requestHints,
            evidenceFocus: payload.evidenceFocus,
            procurementFocus: payload.procurementFocus,
            notificationTargets: payload.notificationTargets,
            executionProfile: { production: payload.production },
          }),
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
      }
    } catch (error) {
      globalThis.console.info('Persistência central da compreensão indisponível; mantendo edição local.', error);
    }

    const entry = input.controlCenterData.controlCenterRecordChangeV1!(
      'Compreensão da etapa editada',
      `${stageKey} · ${payload.materialsTable.length} materiais · ${payload.requirements.length} requisitos`,
      { entity: 'stageAiConfig', entityId: stageKey },
    );
    input.controlCenterData.controlCenterPublishV1!(
      'control.stage-context.updated', 'stageAiConfig', stageKey, { ...payload, changeId: entry.id },
    );
  };
  const createControlStageInlineRecordV1: AtlasControlCenterPageDependenciesV1['createControlStageInlineRecordV1'] = draft =>
    createAtlasControlStageInlineRecordV1({
      ...draft,
      appStore: input.appStore,
      apiFetch: input.apiFetch,
      operationalHeaders: input.operationalHeaders,
    });
  const applyControlCenterMaterialEditV1: AtlasControlCenterPageDependenciesV1['applyControlCenterMaterialEditV1'] = ({ id, field, value }) => {
    input.appStore.update(state => ({
      ...state,
      controlMaterialOverrides: {
        ...(state.controlMaterialOverrides || {}),
        [id]: { ...(state.controlMaterialOverrides || {})[id], [field]: value },
      },
    }));
    const entry = input.controlCenterData.controlCenterRecordChangeV1!(
      `Material ${field} editado`, `${id} · ${String(value ?? 'medir')}`,
      { entity: 'material', entityId: id },
    );
    input.controlCenterData.controlCenterPublishV1!('control.material.updated', 'material', id, {
      field, value, changeId: entry.id,
    });
  };
  const applyControlCenterCommissionEditV1: AtlasControlCenterPageDependenciesV1['applyControlCenterCommissionEditV1'] = ({ id, field, value }) => {
    input.appStore.update(state => {
      const current = input.brokerReasonsV9(state).find(item => item.id === id) || { id };
      const configured = (state.commissionReasons || []).filter((item: Record<string, any>) => item.id !== id);
      return { ...state, commissionReasons: [...configured, { ...current, [field]: value }] };
    });
    const entry = input.controlCenterData.controlCenterRecordChangeV1!(
      `Regra ${id} editada`, `${field} = ${String(value)}`,
      { entity: 'commissionReason', entityId: id },
    );
    input.controlCenterData.controlCenterPublishV1!('control.commission-rule.updated', 'commissionReason', id, {
      field, value, changeId: entry.id,
    });
  };
  const connectControlCenterRealtimeV1: AtlasControlCenterPageDependenciesV1['connectControlCenterRealtimeV1'] = () =>
    input.subscribeOperationalControlCenter(
      input.appStore.get().currentActor || {},
      payload => input.appStore.set({
        controlRealtime: payload,
        lastAction: `Ouviu ${payload.source || 'evento'} no Firebase`,
      }),
    );
  const controlCenterPageV1: AtlasControlCenterPageV1 = createAtlasControlCenterPageV1({
    readState: () => input.appStore.get(),
    onAction: action => input.appStore.set(applyAtlasControlCenterPageActionV1({ action, state: input.appStore.get() })),
    executionModel: input.executionModel,
    demoData: input.demoData,
    commissionDeals: input.commissionDeals,
    brokerReasonsV9: input.brokerReasonsV9,
    ...input.controlCenterData,
    controlCenterRealtimeLabelV1: controlStageContextV1.controlCenterRealtimeLabelV1,
    controlStageProfileV1: controlStageContextV1.controlStageProfileV1,
    controlStageContextMarkupV1: controlStageContextV1.controlStageContextMarkupV1,
    controlStageUnifiedFormMarkupV1: controlStageContextV1.controlStageUnifiedFormMarkupV1,
    controlStageContextPayloadV1: controlStageContextV1.controlStageContextPayloadV1,
    saveControlStageContextV1,
    createControlStageInlineRecordV1,
    applyControlCenterMaterialEditV1,
    applyControlCenterCommissionEditV1,
    cashRecordLauncherMarkupV1: input.cashRecordLauncherMarkupV1,
    connectControlCenterRealtimeV1,
    stageV9StatusFor: input.stageContext.stageV9StatusFor,
    stageV9LiveFor: input.stageContext.stageV9LiveFor,
    formatBRL: input.formatBRL,
    esc: input.esc,
    ico: input.ico,
    notify: input.notify,
  } as AtlasControlCenterPageDependenciesV1);

  const ViewLayer = input.ViewLayer as any;
  controlCenterPageV1.installRenderer(ViewLayer);
  installAtlasStageStableViewTabsV1(ViewLayer, { stageViewTabs: input.stageViewTabs });
  const stageHeader3DMarkup = installAtlasStageHeader3DControlsV1(ViewLayer, {
    esc: input.esc,
    ico: input.ico,
    stageOverlayKey: input.stageOverlayKey,
    demoData: input.demoData,
    extensionStage: input.extensionStage,
    requestAnimationFrameFn: input.requestAnimationFrameFn,
  });
  controlCenterPageV1.installEvents(ViewLayer);
  return Object.freeze({ controlStageContextV1, controlCenterPageV1, stageHeader3DMarkup, ...controlStageContextV1 });
}

