/** Preserve every planning page registration while moving orchestration into the program monolith. */
export type AtlasPlanningPagesApplicationOutputV1 =
  Omit<Awaited<ReturnType<typeof installAtlasStageApplicationCompositionV1>>, 'extensionStage' | 'operationalActions'>
  & ReturnType<typeof installAtlasStageOperationalPagesCompositionV1>
  & ReturnType<typeof installAtlasControlCenterApplicationCompositionV1>
