/** Apply the selected-stage filter and retain the canonical stage on each activity. */
export function projectAtlasStageActivityAdminRowsV1(
  stages: AtlasStageActivityAdminStageV1[],
  selectedStageId: unknown = 'all',
): AtlasStageActivityAdminRowV1[] {
  const selected = String(selectedStageId || 'all');
  return stages
    .filter(stage => selected === 'all' || String(stage.id) === selected)
    .flatMap(stage => (stage.activities || []).map(activity => ({ ...activity, stage })));
}

