/** Merge persisted session data with the JSON defaults without losing nested fields. */
export function projectAtlasActivityInstallationStateV1(
  defaults: AtlasActivityInstallationDefaultsV1,
  currentValue?: Partial<AtlasActivityInstallationStateV1> | null,
): AtlasActivityInstallationStateV1 {
  const current = currentValue || {};
  return {
    ...structuredClone(defaults),
    ...current,
    draft: { ...structuredClone(defaults.draft), ...(current.draft || {}) },
    rationalization: {
      ...structuredClone(defaults.rationalization),
      ...(current.rationalization || {}),
    },
    materials: Array.isArray(current.materials) ? current.materials : [],
    cards: Array.isArray(current.cards) ? current.cards : [],
    dependencies: Array.isArray(current.dependencies) ? current.dependencies : [],
    assignments: Array.isArray(current.assignments) ? current.assignments : [],
  };
}

/** Read the exact install-session checks before any output reaches the organizer. */
export function projectAtlasActivityInstallationRationalizationV1(
  installation: AtlasActivityInstallationStateV1,
  stage: AtlasActivityInstallationStageV1,
): AtlasActivityInstallationRationalizationV1 {
  const draft = installation.draft || {};
  const materials = installation.materials || [];
  const cards = installation.cards || [];
  const name = String(draft.name || '').toLocaleLowerCase('pt-BR').trim();
  const duplicate = cards.some(card => String(card.name || '').toLocaleLowerCase('pt-BR').trim() === name && Boolean(name));
  const checks: AtlasActivityInstallationCheckV1[] = [
    {
      label: 'Nome e natureza identificam a atividade',
      ok: Boolean(draft.name && draft.nature),
      detail: draft.name && draft.nature ? 'Identificação mínima preenchida.' : 'Informe nome e natureza na entrada.',
    },
    {
      label: 'Etapa e unidade de produção estão definidas',
      ok: Boolean(stage.key && draft.unit),
      detail: draft.unit ? `${stage.name} · unidade ${draft.unit}` : 'Selecione como o avanço será medido.',
    },
    {
      label: 'Responsável operacional está definido',
      ok: Boolean(draft.responsible),
      detail: String(draft.responsible || 'Atribua um encarregado ou responsável.'),
    },
    {
      label: 'Materiais predefinidos foram revisados',
      ok: materials.length > 0,
      detail: materials.length ? `${materials.length} item(ns) selecionado(s) para racionalização.` : 'Selecione pelo menos um item ou confirme uma lista vazia.',
    },
    {
      label: 'Não há duplicação no organizador',
      ok: !duplicate,
      detail: duplicate ? 'Já existe um card com este nome nesta sessão.' : 'Nenhuma atividade duplicada encontrada.',
    },
    {
      label: 'Dependências da etapa foram consideradas',
      ok: Boolean((stage.dependsOn || []).length || installation.dependencies?.length),
      detail: (stage.dependsOn || []).length ? `Herdadas: ${stage.dependsOn!.join(' · ')}` : 'A etapa não possui dependência anterior cadastrada.',
    },
  ];
  const approved = checks.every(item => item.ok);
  return {
    status: approved ? 'approved' : 'attention',
    checks,
    summary: approved
      ? 'Sem conflito estrutural detectado. A atividade pode ser aceita e organizada.'
      : 'A IA encontrou pontos que precisam de confirmação antes da propagação.',
  };
}

/** Apply one typed installation-session command while keeping propagation human-gated. */
export function applyAtlasActivityInstallationCommandV1(
  currentValue: Partial<AtlasActivityInstallationStateV1> | null | undefined,
  defaults: AtlasActivityInstallationDefaultsV1,
  command: AtlasActivityInstallationCommandV1,
): AtlasActivityInstallationStateV1 {
  const current = projectAtlasActivityInstallationStateV1(defaults, currentValue);
  switch (command.type) {
    case 'step':
      return { ...current, step: Math.max(1, Math.min(5, command.step)) };
    case 'patch':
      return { ...current, ...command.patch };
    case 'stage':
      return {
        ...current,
        stageKey: command.stageKey,
        materials: [],
        rationalization: structuredClone(defaults.rationalization),
      };
    case 'materials':
      return { ...current, materials: [...command.materials] };
    case 'edit':
      return { ...current, draft: { ...command.draft }, materials: [...command.materials], step: 4 };
    case 'rationalize': {
      const result = projectAtlasActivityInstallationRationalizationV1(current, command.stage);
      return { ...current, rationalization: { ...result, at: command.at } };
    }
    case 'accept':
      return current.rationalization.status === 'approved'
        ? { ...current, step: 5 }
        : current;
    case 'finalize':
      return current.step === 5 && current.rationalization.status === 'approved'
        ? { ...current, cards: [...(current.cards || []), command.card], step: 5 }
        : current;
    case 'reset':
      return structuredClone(defaults);
  }
}

/** Validate the minimum fields before the installation session advances. */
export function isAtlasActivityInstallationEntryReadyV1(
  draft: AtlasActivityInstallationDraftV1,
): boolean {
  return Boolean(draft.name && draft.nature && draft.unit && draft.responsible);
}

/** Normalize the activity installation fields collected by the view. */
export function projectAtlasActivityInstallationDraftV1(
  current: AtlasActivityInstallationDraftV1,
  values: Record<string, unknown>,
): AtlasActivityInstallationDraftV1 {
  const text = (key: string, fallback: unknown): string => String(values[key] ?? fallback ?? '').trim();
  return {
    ...current,
    name: text('name', current.name),
    nature: text('nature', current.nature),
    description: text('description', current.description),
    unit: text('unit', current.unit),
    responsible: text('responsible', current.responsible),
    target: text('target', current.target),
    release: text('release', current.release),
    evidence: text('evidence', current.evidence),
  };
}

/** Keep selected preset materials in the catalog's existing order. */
export function projectAtlasActivityInstallationSelectedMaterialsV1(
  catalog: readonly AtlasActivityInstallationMaterialV1[],
  selectedIds: readonly unknown[],
): AtlasActivityInstallationMaterialV1[] {
  const selected = new Set(selectedIds.map(value => String(value || '')));
  return catalog.filter(item => selected.has(item.id));
}

export interface AtlasActivityInstallationMaterialEditV1 {
  id: string;
  quantity?: unknown;
  unit?: unknown;
  status?: unknown;
}

/** Apply the material editor's quantity, unit, and status fields to its session rows. */
export function projectAtlasActivityInstallationEditedMaterialsV1(
  current: readonly AtlasActivityInstallationMaterialV1[],
  edits: readonly AtlasActivityInstallationMaterialEditV1[],
): AtlasActivityInstallationMaterialV1[] {
  const byId = new Map(edits.map(edit => [edit.id, edit]));
  return current.map(item => {
    const edit = byId.get(item.id);
    if (!edit) return item;
    const quantity = edit.quantity;
    return {
      ...item,
      quantity: quantity === '' ? null : Number(quantity),
      unit: String(edit.unit || item.unit || ''),
      status: String(edit.status || item.status || ''),
    };
  });
}

/** Build the organizer card only after the human accepts the rationalization. */
export function projectAtlasActivityInstallationCardV1(input: {
  draft: AtlasActivityInstallationDraftV1;
  stageKey: string;
  stage: AtlasActivityInstallationStageV1;
  materials: readonly AtlasActivityInstallationMaterialV1[];
  now: Date;
}): AtlasActivityInstallationCardV1 {
  const { draft, stage, now } = input;
  return {
    id: `INST-${now.getTime().toString(36).toUpperCase()}`,
    name: String(draft.name || ''),
    nature: String(draft.nature || ''),
    description: String(draft.description || ''),
    stageKey: input.stageKey,
    stageName: String(stage.name || 'Etapa'),
    responsible: String(draft.responsible || ''),
    unit: String(draft.unit || ''),
    target: String(draft.target || ''),
    materials: input.materials.length,
    status: 'Instalada no organizador',
    createdAt: now.toISOString(),
  };
}

export type AtlasActivityInstallationEntrySubmissionV1 =
  | { ready: false; draft: AtlasActivityInstallationDraftV1; command: null; label: string }
  | { ready: true; draft: AtlasActivityInstallationDraftV1; command: Extract<AtlasActivityInstallationCommandV1, { type: 'patch' }>; label: string };

/** Normalize and prepare the first installation step before the view advances. */
export function buildAtlasActivityInstallationEntrySubmissionV1(
  current: AtlasActivityInstallationDraftV1,
  values: Record<string, unknown>,
): AtlasActivityInstallationEntrySubmissionV1 {
  const draft = projectAtlasActivityInstallationDraftV1(current, values);
  if (!isAtlasActivityInstallationEntryReadyV1(draft)) {
    return { ready: false, draft, command: null, label: `Registrou a entrada inicial de ${draft.name}` };
  }
  return {
    ready: true,
    draft,
    command: { type: 'patch', patch: { draft } },
    label: `Registrou a entrada inicial de ${draft.name}`,
  };
}

/** Join edited identity fields and material rows into one installation command. */
export function buildAtlasActivityInstallationEditSubmissionV1(input: {
  current: AtlasActivityInstallationStateV1;
  values: Record<string, unknown>;
  materialEdits: readonly AtlasActivityInstallationMaterialEditV1[];
}): { command: Extract<AtlasActivityInstallationCommandV1, { type: 'edit' }>; label: string } {
  const draft = projectAtlasActivityInstallationDraftV1(input.current.draft, input.values);
  const materials = projectAtlasActivityInstallationEditedMaterialsV1(input.current.materials || [], input.materialEdits);
  return {
    command: { type: 'edit', materials, draft },
    label: `Editou e enviou ${draft.name || 'atividade'} para racionalização`,
  };
}

/** Calculate the review once and prepare the matching command, audit label and notice. */
export function buildAtlasActivityInstallationRationalizationSubmissionV1(input: {
  current: AtlasActivityInstallationStateV1;
  stage: AtlasActivityInstallationStageV1;
  at: string;
}): {
  command: Extract<AtlasActivityInstallationCommandV1, { type: 'rationalize' }>;
  label: string;
  result: AtlasActivityInstallationRationalizationV1;
} {
  const result = projectAtlasActivityInstallationRationalizationV1(input.current, input.stage);
  return {
    command: { type: 'rationalize', stage: input.stage, at: input.at },
    label: result.status === 'approved' ? 'IA aceitou a racionalização da atividade' : 'IA apontou itens para revisão',
    result,
  };
}

/** Build the persisted organizer-card command only when the installation has a name. */
export function buildAtlasActivityInstallationFinalizationCommandV1(input: {
  current: AtlasActivityInstallationStateV1;
  stage: AtlasActivityInstallationStageV1;
  now: Date;
}): { command: Extract<AtlasActivityInstallationCommandV1, { type: 'finalize' }>; label: string } | null {
  const draft = input.current.draft || {};
  if (!draft.name) return null;
  const card = projectAtlasActivityInstallationCardV1({
    draft,
    stageKey: input.current.stageKey,
    stage: input.stage,
    materials: input.current.materials || [],
    now: input.now,
  });
  return { command: { type: 'finalize', card }, label: `Gravou card de ${card.name} no organizador` };
}

export interface AtlasPertNodeDefinition {
  id: string;
  label: string;
  x: number;
  y: number;
  owner: string;
  material: string;
  contract: string;
  progress: number;
}

export type AtlasPertEdge = [from: string, to: string];

export interface AtlasPertGraph {
  nodes: AtlasPertNodeDefinition[];
  edges: AtlasPertEdge[];
}

export interface AtlasPertRelation {
  from: string;
  to: string;
  label: string;
}

export type AtlasPertNodeState = 'done' | 'active' | 'available' | 'locked';

export interface AtlasPertNode extends AtlasPertNodeDefinition {
  state: AtlasPertNodeState;
}

export interface AtlasPertWorkspaceSnapshot {
  stageName: string;
  nodes: AtlasPertNode[];
  edges: AtlasPertEdge[];
  relations: AtlasPertRelation[];
  selectedNodeId: string;
}

export type AtlasPertCommand =
  | { type: 'select'; id: string }
  | { type: 'complete'; id: string }
  | { type: 'move'; id: string; x: number; y: number }
  | { type: 'connect'; from: string; to: string; label: string }
  | { type: 'create-node'; from: string; name: string; owner: string; label: string; x: number; y: number }
  | { type: 'edit-relation'; index: number; label: string };

export interface AtlasPertApplicationState extends AtlasApplicationStoreState {
  selectedPertNode?: string | null;
  pertOverrides?: Record<string, Partial<AtlasPertNodeDefinition>>;
  pertCustomNodes?: AtlasPertNodeDefinition[];
  pertRelations?: AtlasPertRelation[];
}

interface AtlasPertStore {
  get(): AtlasPertApplicationState;
  set(patch: Partial<AtlasPertApplicationState>): void;
}

const atlasPertGraph = atlasPertGraphData as unknown as AtlasPertGraph;

/** Project graph state and dependency readiness without mutating stored data. */
export function projectAtlasPertNodes(
  state: AtlasPertApplicationState,
  graph: AtlasPertGraph = atlasPertGraph,
): AtlasPertNode[] {
  const overrides = state.pertOverrides || {};
  const customNodes = Array.isArray(state.pertCustomNodes) ? state.pertCustomNodes : [];
  const nodes = [...graph.nodes, ...customNodes].map((node) => {
    const override = overrides[node.id] || {};
    const merged = { ...node, ...override };
    return {
      ...merged,
      id: String(merged.id || node.id),
      label: String(merged.label || node.label),
      owner: String(merged.owner || 'A definir'),
      material: String(merged.material || 'A definir'),
      contract: String(merged.contract || 'A definir'),
      x: Number.isFinite(Number(merged.x)) ? Number(merged.x) : node.x,
      y: Number.isFinite(Number(merged.y)) ? Number(merged.y) : node.y,
      progress: Math.max(0, Math.min(100, Number(merged.progress) || 0)),
    };
  });
  const complete = new Set(nodes.filter((node) => node.progress >= 100).map((node) => node.id));
  const relations = Array.isArray(state.pertRelations) ? state.pertRelations : [];
  const edges = [...graph.edges, ...relations.map(({ from, to }) => [from, to] as AtlasPertEdge)];

  return nodes.map((node) => {
    const incoming = edges.filter(([, to]) => to === node.id).map(([from]) => from);
    const unlocked = incoming.length === 0 || incoming.every((id) => complete.has(id));
    const state: AtlasPertNodeState = node.progress >= 100
      ? 'done'
      : node.progress > 0
        ? 'active'
        : unlocked
          ? 'available'
          : 'locked';
    return { ...node, state };
  });
}

/** Build the complete render contract for the PERT component from the app store. */
export function createAtlasPertWorkspaceSnapshot(
  state: AtlasPertApplicationState,
  stageName: string,
  graph: AtlasPertGraph = atlasPertGraph,
): AtlasPertWorkspaceSnapshot {
  const nodes = projectAtlasPertNodes(state, graph);
  const requested = String(state.selectedPertNode || '');
  const selectedNodeId = nodes.some((node) => node.id === requested)
    ? requested
    : nodes.find((node) => node.state === 'active')?.id || nodes[0]?.id || '';
  return {
    stageName,
    nodes,
    edges: graph.edges.map(([from, to]) => [from, to] as AtlasPertEdge),
    relations: Array.isArray(state.pertRelations) ? state.pertRelations.map((relation) => ({ ...relation })) : [],
    selectedNodeId,
  };
}

/** Apply typed commands emitted by the PERT component to the shared app store. */
export function applyAtlasPertCommand(store: AtlasPertStore, command: AtlasPertCommand): void {
  const state = store.get();
  const nodes = projectAtlasPertNodes(state);
  if (command.type === 'select') {
    if (!nodes.some((node) => node.id === command.id)) return;
    store.set({ selectedPertNode: command.id, lastAction: `Selecionou nó PERT ${command.id}` });
    return;
  }
  if (command.type === 'complete') {
    if (!nodes.some((node) => node.id === command.id)) return;
    const overrides = state.pertOverrides || {};
    store.set({
      pertOverrides: { ...overrides, [command.id]: { ...(overrides[command.id] || {}), progress: 100 } },
      selectedPertNode: command.id,
      lastAction: `Concluiu nó PERT ${command.id}`,
    });
    return;
  }
  if (command.type === 'move') {
    if (!nodes.some((node) => node.id === command.id)) return;
    const overrides = state.pertOverrides || {};
    store.set({
      pertOverrides: {
        ...overrides,
        [command.id]: {
          ...(overrides[command.id] || {}),
          x: Math.max(2, Math.min(90, command.x)),
          y: Math.max(5, Math.min(76, command.y)),
        },
      },
      lastAction: `Reposicionou nó PERT ${command.id}`,
    });
    return;
  }
  if (command.type === 'connect') {
    if (command.from === command.to || !nodes.some((node) => node.id === command.from) || !nodes.some((node) => node.id === command.to)) return;
    const relations = (state.pertRelations || []).filter((item) => !(item.from === command.from && item.to === command.to));
    store.set({
      pertRelations: [...relations, { from: command.from, to: command.to, label: command.label.trim() || 'libera' }],
      lastAction: 'Criou relação PERT entre cards',
    });
    return;
  }
  if (command.type === 'create-node') {
    if (!nodes.some((node) => node.id === command.from) || !command.name.trim() || !command.label.trim()) return;
    const id = `pert-${Date.now().toString(36)}`;
    const node: AtlasPertNodeDefinition = {
      id,
      label: command.name.trim(),
      owner: command.owner.trim() || 'A definir',
      progress: 0,
      x: Math.max(2, Math.min(90, command.x)),
      y: Math.max(5, Math.min(76, command.y)),
      material: 'A definir',
      contract: 'A definir',
    };
    store.set({
      pertCustomNodes: [...(state.pertCustomNodes || []), node],
      pertRelations: [...(state.pertRelations || []), { from: command.from, to: id, label: command.label.trim() }],
      selectedPertNode: id,
      lastAction: `Criou card ${node.label} ligado no PERT`,
    });
    return;
  }
  if (command.type === 'edit-relation') {
    const relations = [...(state.pertRelations || [])];
    if (!relations[command.index] || !command.label.trim()) return;
    relations[command.index] = { ...relations[command.index], label: command.label.trim() };
    store.set({ pertRelations: relations, lastAction: 'Editou rótulo da relação PERT' });
  }
}

export interface AtlasOperationalAction {
  id: string;
  label: string;
  impact: number;
  readiness: number;
  phase: number;
  track: string;
  owner: string;
  eta: string;
  blocker: string;
  relation: string;
  referenceDescription?: string;
  requirements?: string[];
  materialRequirements?: string[];
}

export interface AtlasRecordAttachmentPolicyV1 {
  maxBytes: number;
  mimeTypes: readonly string[];
  dropMessage: string;
}

export const ATLAS_RECORD_ATTACHMENT_POLICY_V1: Readonly<AtlasRecordAttachmentPolicyV1> = Object.freeze({
  maxBytes: Number(recordAttachmentPolicyData.maxBytes),
  mimeTypes: Object.freeze([...recordAttachmentPolicyData.mimeTypes]),
  dropMessage: String(recordAttachmentPolicyData.dropMessage),
});

export function isAtlasRecordDropAttachmentAllowedV1(file: { type: string; size: number }): boolean {
  return (ATLAS_RECORD_ATTACHMENT_POLICY_V1.mimeTypes as readonly string[]).includes(file.type)
    && file.size <= ATLAS_RECORD_ATTACHMENT_POLICY_V1.maxBytes;
}

/** Serialize the data-table export with a UTF-8 BOM and semicolon separators. */
export function buildAtlasDataTableCsvV1(matrix: readonly (readonly unknown[])[]): string {
  return "\uFEFF" + matrix.map((record) => record
    .map((value) => `"${String(value || "").replaceAll('"', '""')}"`)
    .join(";"))
    .join("\r\n");
}

/** Build the guided worker-chat request for one operational priority card. */
export function buildAtlasControlCenterPriorityChatRequestV1(
  action?: Partial<AtlasOperationalAction> | null,
): string {
  return [
    `Conduza pelo chat a execução encadeada desta prioridade operacional: ${action?.label || "Ação operacional"}.`,
    `Frente: ${action?.track || "não informada"}.`,
    `Etapa/relação: ${action?.relation || "não informada"}.`,
    `Situação ou bloqueio: ${action?.blocker || "sem bloqueio informado"}.`,
    `Prontidão: ${Number(action?.readiness) || 0}% · impacto: ${Number(action?.impact) || 0}.`,
    `Previsão/referência: ${action?.eta || "a definir"}.`,
    "Siga uma cadeia guiada: confira o estado atual e os pré-requisitos; execute pela API/ferramentas disponíveis as etapas seguras e dependentes; valide o resultado; depois informe o próximo passo concreto.",
    "Se faltarem dados ou documentos, prepare uma pendência no cronograma ou abra o fluxo documental quando aplicável e pergunte somente o que falta. Não declare etapas concluídas sem confirmação da ferramenta.",
    "O tom visual tone-done do card não prova que a ação sugerida já foi executada. Verifique antes; se já estiver concluída, não a repita e guie para o próximo passo ainda pendente da mesma prioridade.",
  ].join("\n");
}

interface AtlasOperationalActionsCatalog {
  phases: string[];
  actions: AtlasOperationalAction[];
  trackSteps: Record<string, string[]>;
}

export interface AtlasOperationalActionState extends AtlasApplicationStoreState {
  view?: string;
  aiActions?: AtlasOperationalAction[];
  selectedAiAction?: string | null;
  aiActionPositionChanges?: Record<string, { at: string; from: { impact: number; readiness: number }; to: { impact: number; readiness: number } }>;
}

export interface AtlasOperationalActionSnapshot {
  view: string;
  stageName: string;
  phases: string[];
  trackSteps: Record<string, string[]>;
  actions: AtlasOperationalAction[];
  selectedActionId: string;
}

export type AtlasOperationalActionCommand =
  | { type: 'select'; id: string }
  | { type: 'move'; id: string; impact: number; readiness: number }
  | { type: 'advance'; id: string };

interface AtlasOperationalActionStore {
  get(): AtlasOperationalActionState;
  set(patch: Partial<AtlasOperationalActionState>): void;
}

const atlasOperationalActionsCatalog = atlasOperationalActionsData as unknown as AtlasOperationalActionsCatalog;

/** Project action readiness from the live agenda or the saved operational catalog. */
export function projectAtlasOperationalActions(state: AtlasOperationalActionState): AtlasOperationalAction[] {
  const agenda = Array.isArray(state.operationalAgenda) ? state.operationalAgenda : [];
  if (agenda.length) {
    const projected = agenda.slice(0, 18).map((item, index) => {
      const blocked = Array.isArray(item.logicalRequirements) ? item.logicalRequirements.filter(Boolean) : [];
      const shortages = Array.isArray(item.materialShortfalls)
        ? item.materialShortfalls.map((entry) => {
          if (!entry || typeof entry !== 'object') return '';
          const value = entry as Record<string, unknown>;
          return String(value.name || value.description || '');
        }).filter(Boolean)
        : [];
      const status = String(item.status || '');
      const ready = !/bloqueado|aguardando/i.test(status);
      const progress = Math.max(0, Math.min(100, Number(item.stageProgress) || 0));
      const properties = item.properties && typeof item.properties === 'object' ? item.properties as Record<string, unknown> : {};
      const kind = String(item.kind || properties.kind || 'execution');
      const requirements = Array.isArray(item.requirements) ? item.requirements.map(String) : [];
      const materialRequirements = Array.isArray(item.materialRequirements) ? item.materialRequirements.map(String) : [];
      return {
        id: String(item.id || `agenda-action-${index + 1}`),
        label: String(item.title || 'Ação operacional'),
        impact: Math.max(35, Math.min(98, 92 - index * 3)),
        readiness: ready
          ? Math.max(55, Math.min(96, 70 + progress * 0.25))
          : Math.max(15, 48 - blocked.length * 8 - shortages.length * 5),
        phase: /governance|evidence/i.test(kind) ? 4 : /planning/i.test(kind) ? 1 : ready ? 3 : 2,
        track: item.decisionBand === 'execute'
          ? 'Frente de execução'
          : item.decisionBand === 'material-block'
            ? 'Suprimento'
            : 'Responsabilidade',
        owner: String(item.owner || 'Responsável a definir'),
        eta: String(item.plannedStart || 'A programar'),
        blocker: blocked.concat(shortages).map(String).join(' · ') || String(item.nextStep || 'Sem bloqueio operacional'),
        relation: String(item.stageName || 'Etapa operacional'),
        referenceDescription: String(item.referenceDescription || ''),
        requirements,
        materialRequirements,
      };
    });
    const savedById = new Map<string, AtlasOperationalAction>(
      (Array.isArray(state.aiActions) ? state.aiActions : []).map((item): [string, AtlasOperationalAction] => [item.id, item]),
    );
    return projected.map((item) => {
      const saved = savedById.get(item.id);
      if (!saved) return item;
      return {
        ...item,
        impact: Number.isFinite(saved.impact) ? saved.impact : item.impact,
        readiness: Number.isFinite(saved.readiness) ? saved.readiness : item.readiness,
        phase: Number.isFinite(saved.phase) ? saved.phase : item.phase,
        blocker: saved.blocker || item.blocker,
      };
    });
  }
  const saved = Array.isArray(state.aiActions) && state.aiActions.length ? state.aiActions : atlasOperationalActionsCatalog.actions;
  return saved.map((item) => ({ ...item }));
}

/** Build the action matrix and selected-item contract from one app state snapshot. */
export function createAtlasActionsWorkspaceSnapshot(state: AtlasOperationalActionState, stageName: string): AtlasOperationalActionSnapshot {
  const actions = projectAtlasOperationalActions(state);
  const requested = String(state.selectedAiAction || '');
  const selectedActionId = actions.some((item) => item.id === requested) ? requested : actions[0]?.id || '';
  return {
    view: String(state.view || ''),
    stageName,
    phases: [...atlasOperationalActionsCatalog.phases],
    trackSteps: structuredClone(atlasOperationalActionsCatalog.trackSteps),
    actions,
    selectedActionId,
  };
}

/** Apply action matrix commands through the shared program store. */
export function applyAtlasOperationalActionCommand(store: AtlasOperationalActionStore, command: AtlasOperationalActionCommand): void {
  const state = store.get();
  const actions = projectAtlasOperationalActions(state);
  const selected = actions.find((item) => item.id === command.id);
  if (!selected) return;
  if (command.type === 'select') {
    store.set({ selectedAiAction: command.id, lastAction: `Selecionou ação IA ${selected.label}` });
    return;
  }
  if (command.type === 'move') {
    const impact = Math.max(4, Math.min(96, Math.round(command.impact)));
    const readiness = Math.max(4, Math.min(96, Math.round(command.readiness)));
    const from = { impact: selected.impact, readiness: selected.readiness };
    const to = { impact, readiness };
    const positionChanges = {
      ...(state.aiActionPositionChanges || {}),
      [command.id]: { at: new Date().toISOString(), from, to },
    };
    store.set({
      aiActions: actions.map((item) => item.id === command.id ? { ...item, ...to } : item),
      aiActionPositionChanges: positionChanges,
      selectedAiAction: command.id,
      lastAction: `Reposicionou ação ${command.id} na matriz`,
    });
    return;
  }
  const nextPhase = Math.min(4, selected.phase + 1);
  store.set({
    aiActions: actions.map((item) => item.id === command.id ? {
      ...item,
      phase: nextPhase,
      readiness: Math.min(100, item.readiness + 8),
      blocker: item.phase >= 2 ? 'Sem bloqueios críticos' : 'Pré-condição atualizada pela IA',
    } : item),
    selectedAiAction: command.id,
    lastAction: `Adiantou atitude ${command.id}`,
  });
}

export type AtlasRaciRole = 'R' | 'A' | 'C' | 'I' | '—';

export interface AtlasRaciActor {
  id: string;
  name: string;
  role: string;
  contract: string;
}

export interface AtlasRaciTask {
  id: string;
  label: string;
}

type AtlasRaciAssignments = Record<string, Record<string, AtlasRaciRole>>;

interface AtlasRaciCatalog {
  actors: AtlasRaciActor[];
  tasks: AtlasRaciTask[];
  defaultAssignments: AtlasRaciAssignments;
  meaning: Record<AtlasRaciRole, string>;
  roleOrder: AtlasRaciRole[];
}

export interface AtlasRaciApplicationState extends AtlasApplicationStoreState {
  view?: string;
  raciAssignments?: AtlasRaciAssignments | null;
  selectedRaciCell?: string | null;
}

export interface AtlasRaciWorkspaceSnapshot {
  stageName: string;
  actors: AtlasRaciActor[];
  tasks: AtlasRaciTask[];
  assignments: AtlasRaciAssignments;
  selectedCell: string;
  selectedActor: AtlasRaciActor;
  selectedTask: AtlasRaciTask;
  selectedRole: AtlasRaciRole;
  meaning: Record<AtlasRaciRole, string>;
  roleOrder: AtlasRaciRole[];
}

export type AtlasRaciCommand =
  | { type: 'select'; key: string }
  | { type: 'cycle'; key: string };

interface AtlasRaciStore {
  get(): AtlasRaciApplicationState;
  set(patch: Partial<AtlasRaciApplicationState>): void;
}

const atlasRaciCatalog = atlasRaciData as unknown as AtlasRaciCatalog;

/** Project the role matrix and inspector selection from local application state. */
export function createAtlasRaciWorkspaceSnapshot(state: AtlasRaciApplicationState, stageName: string): AtlasRaciWorkspaceSnapshot {
  const assignments = state.raciAssignments || structuredClone(atlasRaciCatalog.defaultAssignments);
  const requested = String(state.selectedRaciCell || 't3:carlos');
  const [taskId, actorId] = requested.split(':');
  const selectedTask = atlasRaciCatalog.tasks.find((item) => item.id === taskId) || atlasRaciCatalog.tasks[2];
  const selectedActor = atlasRaciCatalog.actors.find((item) => item.id === actorId) || atlasRaciCatalog.actors[0];
  const selectedCell = `${selectedTask.id}:${selectedActor.id}`;
  const selectedRole = assignments[selectedTask.id]?.[selectedActor.id] || '—';
  return {
    stageName,
    actors: atlasRaciCatalog.actors.map((item) => ({ ...item })),
    tasks: atlasRaciCatalog.tasks.map((item) => ({ ...item })),
    assignments: structuredClone(assignments),
    selectedCell,
    selectedActor: { ...selectedActor },
    selectedTask: { ...selectedTask },
    selectedRole,
    meaning: { ...atlasRaciCatalog.meaning },
    roleOrder: [...atlasRaciCatalog.roleOrder],
  };
}

/** Apply cell selection and R/A/C/I cycling to the shared application state. */
export function applyAtlasRaciCommand(store: AtlasRaciStore, command: AtlasRaciCommand): AtlasRaciRole | void {
  const snapshot = createAtlasRaciWorkspaceSnapshot(store.get(), '');
  const [taskId, actorId] = command.key.split(':');
  if (!atlasRaciCatalog.tasks.some((item) => item.id === taskId) || !atlasRaciCatalog.actors.some((item) => item.id === actorId)) return;
  if (command.type === 'select') {
    store.set({ selectedRaciCell: command.key, lastAction: `Selecionou vínculo RACI ${command.key}` });
    return;
  }
  const assignments = snapshot.assignments;
  const current = assignments[taskId]?.[actorId] || '—';
  const next = atlasRaciCatalog.roleOrder[(atlasRaciCatalog.roleOrder.indexOf(current) + 1) % atlasRaciCatalog.roleOrder.length];
  assignments[taskId] ||= {};
  if (next === '—') delete assignments[taskId][actorId];
  else assignments[taskId][actorId] = next;
  store.set({
    raciAssignments: assignments,
    selectedRaciCell: command.key,
    lastAction: `Alterou RACI ${taskId}/${actorId} para ${next}`,
  });
  return next;
}

