/** Project saved RAID records or the read-only catalog defaults. */
export function projectAtlasRaidItems(state: AtlasRaidApplicationState): AtlasRaidItem[] {
  const items = Array.isArray(state.raidItems) && state.raidItems.length ? state.raidItems : atlasRaidCatalog.items;
  return items.map((item) => ({ ...item }));
}

/** Build the selected RAID card and the target list used by the workspace. */
export function createAtlasRaidWorkspaceSnapshot(state: AtlasRaidApplicationState, stageName: string): AtlasRaidWorkspaceSnapshot {
  const items = projectAtlasRaidItems(state);
  const selected = items.find((item) => item.id === state.selectedRaidItem) || items[0];
  return { stageName, items, selected, targets: [...atlasRaidCatalog.targets] };
}

/** Apply RAID movement, linking, creation, and selection to the app store. */
export function applyAtlasRaidCommand(store: AtlasRaidStore, command: AtlasRaidCommand): void {
  const state = store.get();
  const items = projectAtlasRaidItems(state);
  if (command.type === 'select') {
    if (!items.some((item) => item.id === command.id)) return;
    store.set({ selectedRaidItem: command.id, lastAction: `Selecionou pendência ${command.id}` });
    return;
  }
  if (command.type === 'move') {
    if (!items.some((item) => item.id === command.id)) return;
    store.set({
      raidItems: items.map((item) => item.id === command.id ? { ...item, kind: command.kind } : item),
      selectedRaidItem: command.id,
      lastAction: `Moveu ${command.id} para ${command.kind}`,
    });
    return;
  }
  if (command.type === 'link') {
    if (!items.some((item) => item.id === command.id) || !atlasRaidCatalog.targets.includes(command.target)) return;
    store.set({
      raidItems: items.map((item) => item.id === command.id ? { ...item, linked: command.target } : item),
      selectedRaidItem: command.id,
      lastAction: `Vinculou ${command.id} a ${command.target}`,
    });
    return;
  }
  if (!command.title.trim()) return;
  const item: AtlasRaidItem = {
    id: `RAID-${Date.now().toString(36).toUpperCase()}`,
    kind: command.kind,
    title: command.title.trim(),
    detail: command.detail.trim() || 'Sem descrição adicional.',
    level: 'médio',
    linked: command.stageName,
  };
  store.set({
    raidItems: [...items, item],
    selectedRaidItem: item.id,
    lastAction: `Criou item RAID ${item.title}`,
  });
}

