/** Keep planning consumers on the typed projections that power the active workspaces. */
export function createAtlasOperationalIntelligenceServicesV1(input: {
  appStore: {
    get(): AtlasOperationalActionState & AtlasPertApplicationState & AtlasRaidApplicationState;
  };
}): AtlasOperationalIntelligenceServicesV1 {
  if (typeof input?.appStore?.get !== 'function') {
    throw new TypeError('Operational intelligence services require appStore.get().');
  }
  return Object.freeze({
    operationalActions: () => projectAtlasOperationalActions(input.appStore.get()),
    currentPertNodes: () => projectAtlasPertNodes(input.appStore.get()),
    operationalRaid: () => projectAtlasRaidItems(input.appStore.get()),
  });
}

