/** Generate the compact session ID while allowing the browser crypto source to be injected. */
export function createAtlasSessionId(cryptoProvider: Crypto | undefined = globalThis.crypto): string {
  if (typeof cryptoProvider?.randomUUID === 'function') return cryptoProvider.randomUUID().slice(0, 8).toUpperCase();
  if (typeof cryptoProvider?.getRandomValues === 'function') {
    const bytes = new Uint8Array(4);
    cryptoProvider.getRandomValues(bytes);
    return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('').toUpperCase();
  }
  return `${Date.now().toString(16)}${Math.random().toString(16).slice(2, 6)}`.slice(-8).toUpperCase();
}

/**
 * Create the shared synchronous application store. Preserve structured clone,
 * immediate notification, audit coalescing, and unsubscribe semantics used by
 * the MJS compatibility surface while keeping the state contract typed here.
 */
export function createAtlasApplicationStore<TState extends AtlasApplicationStoreState>(
  initial: TState,
): AtlasApplicationStore<TState> {
  let state = structuredClone(initial);
  const listeners = new Set<(state: TState) => void>();
  const withAudit = (previous: TState, next: TState): TState => {
    const action = String(next.lastAction || '').trim();
    if (!action || action === previous.lastAction) return next;
    const now = new Date().toISOString();
    const entries = Array.isArray(next.actionAudit) ? [...next.actionAudit] : [];
    const last = entries.at(-1);
    if (!last || last.label !== action || Date.parse(now) - Date.parse(last.at) > 750) {
      entries.push({
        id: `ACT-${Date.now().toString(36).toUpperCase()}`,
        label: action,
        at: now,
        actor: next.currentActor?.name || previous.currentActor?.name || 'Warley',
        role: next.currentActor?.label || previous.currentActor?.label || 'Dono',
        view: next.view || previous.view || 'assistant',
      });
    }
    return { ...next, actionAudit: entries.slice(-250) } as TState;
  };
  const emit = (): void => {
    listeners.forEach((listener) => listener(state));
  };
  return {
    get: () => state,
    set(patch) {
      state = withAudit(state, { ...state, ...patch });
      emit();
    },
    update(project) {
      state = withAudit(state, project(state));
      emit();
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

export const ATLAS_UI_MEMORY_KEY = 'belavista.ui-memory.v1';
interface AtlasUiMemoryFieldCatalogV1 {
  version: 1;
  fields: readonly string[];
}
const atlasUiMemoryFieldCatalog = uiMemoryFieldCatalogData as AtlasUiMemoryFieldCatalogV1;

export type AtlasUiMemoryState = Record<string, unknown> & {
  integrationSettings?: unknown;
  foremenContacts?: Array<Record<string, unknown> & { password?: unknown }>;
};

type AtlasUiMemoryStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;

function resolveAtlasUiMemoryStorage(storage?: AtlasUiMemoryStorage): AtlasUiMemoryStorage | null {
  if (storage) return storage;
  return typeof localStorage === 'undefined' ? null : localStorage;
}

/** Restore the versioned, local-only portion of the application UI state. */
export function restoreAtlasUiState(storage?: AtlasUiMemoryStorage): AtlasUiMemoryState {
  try {
    const target = resolveAtlasUiMemoryStorage(storage);
    if (!target) return {};
    const parsed: unknown = JSON.parse(target.getItem(ATLAS_UI_MEMORY_KEY) || '{}');
    if (!parsed || typeof parsed !== 'object') return {};
    const envelope = parsed as { version?: unknown; state?: unknown };
    if (envelope.version !== 1 || !envelope.state || typeof envelope.state !== 'object') return {};
    const safe = { ...(envelope.state as Record<string, unknown>) };
    delete safe.integrationSettings;
    return structuredClone(safe);
  } catch (error) {
    console.warn('Memória local de interface indisponível.', error);
    return {};
  }
}

/** Persist only approved UI fields and strip credentials from contacts. */
export function persistAtlasUiState(state: AtlasUiMemoryState, storage?: AtlasUiMemoryStorage): void {
  try {
    const target = resolveAtlasUiMemoryStorage(storage);
    if (!target) return;
    const fields: readonly string[] = [...atlasUiMemoryFieldCatalog.fields, 'foremenContacts'];
    const snapshot = Object.fromEntries(fields.filter((key) => key in state).map((key) => [key, state[key]]));
    if (Array.isArray(snapshot.foremenContacts)) {
      snapshot.foremenContacts = snapshot.foremenContacts.map((contact) => {
        const { password: _password, ...safeContact } = contact as Record<string, unknown> & { password?: unknown };
        return safeContact;
      });
    }
    target.setItem(ATLAS_UI_MEMORY_KEY, JSON.stringify({ version: 1, savedAt: new Date().toISOString(), state: snapshot }));
  } catch (error) {
    console.warn('Não foi possível salvar a memória local da interface.', error);
  }
}

/** Remove the local UI memory without changing the in-memory application store. */
export function clearAtlasUiState(storage?: AtlasUiMemoryStorage): void {
  try {
    resolveAtlasUiMemoryStorage(storage)?.removeItem(ATLAS_UI_MEMORY_KEY);
  } catch (error) {
    console.warn('Não foi possível limpar a memória local.', error);
  }
}

type AtlasApplicationRuntimeStorageV1 = Pick<Storage, 'getItem' | 'setItem'>;

export interface AtlasApplicationRuntimeGlobalV1 {
  __belavistaAppStore?: AtlasApplicationStore<AtlasApplicationInitialState>;
  __belavistaDemoData?: typeof ATLAS_STATE_CATALOGS_V1.demoData;
  __belavistaExecutionModel?: typeof ATLAS_STATE_CATALOGS_V1.executionModel;
  __belavistaCommissionReasonDefaults?: typeof ATLAS_STATE_CATALOGS_V1.commissionReasonDefaults;
  __belavistaCashFlowSeed?: typeof ATLAS_STATE_CATALOGS_V1.cashFlowSeed;
}

export interface AtlasApplicationRuntimeInputV1 {
  globalRef?: AtlasApplicationRuntimeGlobalV1;
  localStorage?: AtlasUiMemoryStorage | null;
  sessionStorage?: AtlasApplicationRuntimeStorageV1 | null;
}

/** Runtime state owned by the program and injected into the map view composer. */
export interface AtlasMapSceneRuntimeStateV1 {
  appStore: NonNullable<AtlasApplicationRuntimeGlobalV1['__belavistaAppStore']>;
  demoData: typeof ATLAS_STATE_CATALOGS_V1.demoData;
  viewThemes: typeof ATLAS_STATE_CATALOGS_V1.viewThemes;
  activityCatalog: typeof ATLAS_STATE_CATALOGS_V1.activityCatalog;
}

/** Assemble the legacy shell bridge once while keeping state creation and catalog ownership in the program. */
export function initializeAtlasApplicationRuntimeV1(input: AtlasApplicationRuntimeInputV1 = {}): {
  appStore: AtlasApplicationStore<AtlasApplicationInitialState>;
  restoredUiState: AtlasUiMemoryState;
} {
  const globalRef = input.globalRef || globalThis as unknown as AtlasApplicationRuntimeGlobalV1;
  const restoredUiState = restoreAtlasUiState(input.localStorage || undefined);
  let storedSessionId: string | null = null;
  try {
    storedSessionId = input.sessionStorage?.getItem('belavista.session') || null;
  } catch {
    storedSessionId = null;
  }

  const appStore = globalRef.__belavistaAppStore || createAtlasApplicationStore(createAtlasApplicationInitialState({
    sessionId: storedSessionId,
    restoredUiState,
    aiAgendaComprehensionDefaults: AI_AGENDA_COMPREHENSION_DEFAULTS_V1,
    commissionReasonDefaults: ATLAS_STATE_CATALOGS_V1.commissionReasonDefaults,
    personnelModel: ATLAS_STATE_CATALOGS_V1.personnelModel,
    activityInstallationDefaults: ATLAS_STATE_CATALOGS_V1.activityInstallationDefaults,
  }));
  if (appStore.get().dashboardMode !== 'tracking') appStore.set({ dashboardMode: 'tracking' });

  try {
    input.sessionStorage?.setItem('belavista.session', appStore.get().sessionId);
  } catch {
    // The application remains usable when session storage is unavailable.
  }

  globalRef.__belavistaAppStore = appStore;
  globalRef.__belavistaDemoData = ATLAS_STATE_CATALOGS_V1.demoData;
  globalRef.__belavistaExecutionModel = ATLAS_STATE_CATALOGS_V1.executionModel;
  globalRef.__belavistaCommissionReasonDefaults = ATLAS_STATE_CATALOGS_V1.commissionReasonDefaults;
  globalRef.__belavistaCashFlowSeed = ATLAS_STATE_CATALOGS_V1.cashFlowSeed;

  return { appStore, restoredUiState };
}

