/** Join sales, cash receipts and active broker rules for the movement-history route. */
export function projectAtlasSalesHistoryPageV1(input: {
  sales: readonly CommercialSale[];
  entries: readonly CashEntry[];
  rules: readonly BrokerRule[];
  query: string;
  selectedId: string | null;
}): AtlasSalesHistoryPageProjectionV1 {
  const normalizeBroker = (value: string): string => value.trim().toLocaleLowerCase('pt-BR');
  const normalizeLot = (value: string): string => {
    const raw = value.trim().toLocaleUpperCase('pt-BR').replace(/\s+/g, '');
    const match = raw.match(/^([A-Z]+)-?(\d+)$/);
    return match ? `${match[1]}-${Number(match[2])}` : raw;
  };
  const details = input.sales.map<AtlasSalesHistoryDetailProjectionV1>(sale => {
    const receipts = input.entries.filter(entry => entry.saleId === sale.id && entry.kind === 'entrada');
    const rule = input.rules.find(item =>
      item.active &&
      normalizeBroker(item.brokerName) === normalizeBroker(sale.broker) &&
      normalizeLot(item.lotKey) === normalizeLot(sale.lot),
    );
    return {
      sale,
      receipts,
      receiptCount: receipts.length,
      receiptTotalCents: receipts.reduce((sum, entry) => sum + Number(entry.amountCents || 0), 0),
      commissionPercent: rule?.commissionPercent ?? null,
      commissionCents: rule ? Math.round((sale.valueCents * rule.commissionPercent) / 100) : null,
      statusOptions: [...new Set([
        sale.status,
        'Reserva',
        'Em análise',
        'Proposta',
        'Assinado',
        'Compra confirmada',
      ])],
    };
  });
  const selectedDetail = details.find(item => item.sale.id === input.selectedId) || null;
  const query = input.query.trim().toLocaleLowerCase('pt-BR');
  const filteredSales = details
    .filter(({ sale }) => [sale.id, sale.client, sale.lot, sale.broker].some(value =>
      String(value).toLocaleLowerCase('pt-BR').includes(query),
    ))
    .map(({ sale, receiptCount, commissionCents, commissionPercent }) => ({
      sale,
      receiptCount,
      commissionCents,
      commissionPercent,
    }));
  return {
    selectedDetail,
    filteredSales,
    totalValueCents: input.sales.reduce((sum, sale) => sum + Number(sale.valueCents || 0), 0),
    attachmentCount: input.sales.reduce((sum, sale) => sum + sale.files.length, 0),
  };
}

