const workerWorkbenchRecordV1 = (value: unknown): Record<string, unknown> =>
  value && typeof value === 'object' ? value as Record<string, unknown> : {};

const workerWorkbenchTextV1 = (value: unknown): string => String(value ?? '');

export function projectWorkerWorkbenchStageContextV1(
  panoramaValue: unknown,
  monitorValue: unknown,
  definition: WorkerWorkbenchStageV1,
): WorkerWorkbenchStageContextV1 {
  const panorama = workerWorkbenchRecordV1(panoramaValue);
  const monitor = workerWorkbenchRecordV1(monitorValue);
  const operational = workerWorkbenchRecordV1(monitor.operational);
  const aliases = new Set([definition.key, ...(definition.aliases || [])]);
  const findStage = (value: unknown): Record<string, any> => {
    const rows = Array.isArray(value) ? value : [];
    return rows.find(item => aliases.has(String(workerWorkbenchRecordV1(item).key || ''))) || {};
  };
  const live = findStage(panorama.stages);
  const monitorStage = findStage(monitor.stages);
  const operationalStage = findStage(operational.stages);
  const summary = { ...monitorStage, ...operationalStage };
  return {
    live,
    summary,
    automation: workerWorkbenchRecordV1(live.automation),
    progress: Number(live.progress ?? summary.progress) || 0,
    owner: String(live.owner || summary.owner || 'Responsável a definir'),
  };
}

/** Compose a persisted Worker stage snapshot into the editable runtime model. */
export function createWorkerWorkbenchStageRuntimeV1(input: {
  definition: WorkerWorkbenchStageV1;
  panorama: unknown;
  monitor: unknown;
  storedState: unknown;
  today: string;
  createId: (prefix: string) => string;
}): WorkerWorkbenchStageRuntimeV1 {
  const stored = workerWorkbenchRecordV1(input.storedState);
  const context = projectWorkerWorkbenchStageContextV1(input.panorama, input.monitor, input.definition);
  const calendarCandidate = String(stored.calendarDate || context.automation.plannedStart || '');
  const calendarDate = /^\d{4}-\d{2}-\d{2}$/.test(calendarCandidate) ? calendarCandidate : input.today;
  const inputSessions = normalizeWorkerWorkbenchInputSessionsV1(
    input.definition, stored, calendarDate, input.createId,
  );
  const flowActivities = projectWorkerWorkbenchFlowActivitiesV1(input.definition, inputSessions);
  const persistedLayout = workerWorkbenchRecordV1(stored.layout);
  const layout = { ...projectWorkerWorkbenchDefaultLayoutV1(flowActivities), ...persistedLayout };
  const storedLinks = Array.isArray(stored.links) ? stored.links : [];
  const links: WorkerWorkbenchInputRelationLinkV1[] = storedLinks.length
    ? storedLinks.filter(value => {
      const row = workerWorkbenchRecordV1(value);
      return Boolean(row.from && row.to);
    }).map(value => {
      const row = workerWorkbenchRecordV1(value);
      return { ...row, from: String(row.from), to: String(row.to) };
    })
    : projectWorkerWorkbenchDefaultLinksV1(input.definition);
  return {
    definition: input.definition,
    ...context,
    layout,
    links,
    inputSessions,
    flowActivities,
    calendarDate,
    inputTimers: new Map(),
    scheduleContext: projectWorkerWorkbenchScheduleContextV1(context, calendarDate),
  };
}

export type WorkerWorkbenchApiReadV1 = (path: string, init?: RequestInit) => Promise<Record<string, any>>;

export interface WorkerWorkbenchApiActorV1 {
  role?: string;
  uid?: string;
  name?: string;
}

export interface WorkerWorkbenchApiHostV1 {
  fetcher: (path: string, init: RequestInit) => Promise<Response>;
  waitForAuth: () => Promise<unknown>;
  currentActor: () => WorkerWorkbenchApiActorV1 | null | undefined;
  currentIdToken: () => Promise<string | null | undefined> | string | null | undefined;
}

/** Build the worker workbench JSON client from the host's authenticated runtime ports. */
export function createWorkerWorkbenchApiV1(host: WorkerWorkbenchApiHostV1): WorkerWorkbenchApiReadV1 {
  return async (path, options = {}) => {
    await host.waitForAuth();
    const actor = host.currentActor() || {};
    let token = '';
    try {
      token = String(await host.currentIdToken() || '');
    } catch {
      token = '';
    }

    const headers = new Headers({
      'x-belavista-role': actor.role || 'owner',
      'x-belavista-user': actor.uid || 'workbench-local',
      'x-belavista-name': actor.name || 'Operação',
      ...(token ? { authorization: `Bearer ${token}` } : {}),
    });
    new Headers(options.headers).forEach((value, key) => headers.set(key, value));

    const response = await host.fetcher(path, {
      cache: 'no-store',
      ...options,
      headers,
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = payload && typeof payload === 'object' && 'error' in payload
        ? String(payload.error || '')
        : '';
      throw new Error(error || `HTTP ${response.status}`);
    }
    return payload as Record<string, any>;
  };
}

