/** Load stage attachments, optionally scoped to a single activity. */
export async function loadWorkerWorkbenchAttachmentsV1(input: {
  stageKey: string;
  activityId?: string;
  request: WorkerWorkbenchApiReadV1;
}): Promise<Record<string, unknown>[]> {
  const scope = input.activityId ? `&activity=${encodeURIComponent(input.activityId)}` : '';
  const result = await input.request(`/api/workbench/diary?resource=attachments&stage=${encodeURIComponent(input.stageKey)}${scope}`);
  return Array.isArray(result.attachments) ? result.attachments : [];
}

/** Persist an attachment and return the refreshed stage/activity collection. */
export async function saveWorkerWorkbenchAttachmentV1(input: {
  stageKey: string;
  activityId?: string;
  fields: Record<string, string>;
  fileName: string;
  dataUrl: string;
  request: WorkerWorkbenchApiReadV1;
}): Promise<Record<string, unknown>[]> {
  await createWorkerWorkbenchAttachmentV1({
    stageKey: input.stageKey,
    activityId: input.activityId || '',
    fields: input.fields,
    fileName: input.fileName,
    dataUrl: input.dataUrl,
    request: input.request,
  });
  return loadWorkerWorkbenchAttachmentsV1({
    stageKey: input.stageKey,
    activityId: input.activityId,
    request: input.request,
  });
}

type AtlasWorkerAttachmentComponentOwnerV1 = Pick<typeof import('./components.js'),
  | 'renderAtlasWorkerAttachmentPanelV1'
  | 'renderAtlasWorkerAttachmentItemsV1'
  | 'installAtlasWorkerAttachmentEventsV1'>;
type AtlasWorkerAttachmentPanelInputV1 = Parameters<AtlasWorkerAttachmentComponentOwnerV1['renderAtlasWorkerAttachmentPanelV1']>[0];
type AtlasWorkerAttachmentItemsV1 = Parameters<AtlasWorkerAttachmentComponentOwnerV1['renderAtlasWorkerAttachmentItemsV1']>[0];

/** Mount and connect an attachment panel using the typed component and persistence owners. */
export function mountWorkerWorkbenchAttachmentPanelV1(input: {
  main: HTMLElement;
  definition: AtlasWorkerAttachmentPanelInputV1['definition'];
  activity?: AtlasWorkerAttachmentPanelInputV1['activity'];
  attachments: AtlasWorkerAttachmentItemsV1;
  request: WorkerWorkbenchApiReadV1;
  componentsTs: AtlasWorkerAttachmentComponentOwnerV1;
  setSyncState(message: string): void;
}): boolean {
  const template = input.main.ownerDocument.createElement('template');
  template.innerHTML = input.componentsTs.renderAtlasWorkerAttachmentPanelV1({
    definition: input.definition,
    activity: input.activity || null,
  });
  const panel = template.content.firstElementChild as HTMLElement | null;
  const list = panel?.querySelector<HTMLElement>('[data-attachment-list]');
  if (!panel || !list) return false;
  list.innerHTML = input.componentsTs.renderAtlasWorkerAttachmentItemsV1(input.attachments);
  input.main.append(panel);
  const installed = input.componentsTs.installAtlasWorkerAttachmentEventsV1({
    root: panel,
    saveAttachment: ({ fields, fileName, dataUrl }) => saveWorkerWorkbenchAttachmentV1({
      stageKey: input.definition.key,
      activityId: input.activity?.id || '',
      fields,
      fileName,
      dataUrl,
      request: input.request,
    }),
    setSyncState: input.setSyncState,
  });
  if (!installed) {
    panel.remove();
    return false;
  }
  input.main.dataset.attachmentEventsOwnerV1 = 'typescript-components';
  input.main.dataset.attachmentPersistenceOwnerV1 = 'typescript-program';
  return true;
}

export function projectWorkerWorkbenchActivityProgressV1(stageProgress: unknown, index: number, total: number): number {
  const value = ((Number(stageProgress) || 0) / 100 * total - index) * 100;
  return Math.max(0, Math.min(100, value));
}

export function projectWorkerWorkbenchStageWorkspaceV1(input: {
  definition: WorkerWorkbenchStageV1;
  context: WorkerWorkbenchStageContextV1;
  calendarDate: string;
  flowActivities: readonly WorkerWorkbenchFlowActivityV1[];
  layout: Record<string, unknown>;
  generatedAt?: string;
}): WorkerWorkbenchStageWorkspaceProjectionV1 {
  const validDate = (value: unknown, fallback: string): string =>
    /^\d{4}-\d{2}-\d{2}$/.test(String(value || '')) ? String(value) : fallback;
  const today = new Date().toISOString().slice(0, 10);
  const calendarDate = validDate(input.calendarDate, today);
  const automation = input.context.automation;
  const start = validDate(automation.plannedStart, calendarDate);
  const finish = validDate(automation.plannedFinish, start);
  const from = new Date(`${start}T12:00:00`), to = new Date(`${finish}T12:00:00`);
  const span = Math.max(1, Math.round((to.getTime() - from.getTime()) / 86400000));
  const dateCount = Math.min(10, Math.max(6, input.flowActivities.length + 1));
  const dates = Array.from({ length: dateCount }, (_, index) => {
    const date = new Date(from);
    date.setDate(from.getDate() + Math.round(span * index / Math.max(1, dateCount - 1)));
    return date.toISOString().slice(0, 10);
  });
  const total = input.flowActivities.length;
  const blocked = Boolean(input.context.live.blockedBy?.length);
  const flowCards = input.flowActivities.map((item, index) => {
    const stored = workerWorkbenchRecordV1(input.layout[item.id]);
    const defaultX = 58 + index * 246, defaultY = 96 + (index % 2) * 178;
    const x = Number(stored.x), y = Number(stored.y), width = Number(stored.width);
    return {
      item,
      index,
      total,
      position: {
        x: Number.isFinite(x) ? x : defaultX,
        y: Number.isFinite(y) ? y : defaultY,
        ...(Number.isFinite(width) && width > 0 ? { width } : {}),
      },
      progress: projectWorkerWorkbenchActivityProgressV1(input.context.progress, index, total),
      blocked,
    };
  });
  return {
    definition: input.definition,
    context: input.context,
    generatedAt: String(input.generatedAt || ''),
    calendarDate,
    dates,
    canvasWidth: Math.max(1180, total * 246 + 100),
    flowCards,
  };
}

export interface WorkerWorkbenchStageFlowCardRenderInputV1 extends WorkerWorkbenchStageFlowCardProjectionV1 {
  stageKey: string;
  plannedStart: string;
  plannedFinish: string;
  route(path: string, query?: string): string;
}

/** Project typed canvas-card view models from the stage runtime. */
export function projectWorkerWorkbenchStageFlowCardRenderInputsV1(input: {
  runtime: WorkerWorkbenchStageRuntimeV1;
  route(path: string, query?: string): string;
}): WorkerWorkbenchStageFlowCardRenderInputV1[] {
  const { runtime } = input;
  const context = runtime.scheduleContext;
  const projection = projectWorkerWorkbenchStageWorkspaceV1({
    definition: runtime.definition,
    context,
    calendarDate: runtime.calendarDate,
    flowActivities: runtime.flowActivities,
    layout: runtime.layout,
  });
  return projection.flowCards.map(card => ({
    ...card,
    stageKey: runtime.definition.key,
    plannedStart: String(context.automation.plannedStart || runtime.calendarDate),
    plannedFinish: String(context.automation.plannedFinish || context.automation.plannedStart || runtime.calendarDate),
    route: input.route,
  }));
}

/** Compatibility renderer for MJS recovery adapters; TypeScript pages render the list in components.ts. */
export function renderWorkerWorkbenchStageFlowCardsV1(input: {
  runtime: WorkerWorkbenchStageRuntimeV1;
  route(path: string, query?: string): string;
  renderCard(card: WorkerWorkbenchStageFlowCardRenderInputV1): string;
}): string {
  return projectWorkerWorkbenchStageFlowCardRenderInputsV1(input).map(input.renderCard).join('');
}

type AtlasWorkerStageFlowCanvasComponentOwnerV1 = Pick<typeof import('./components.js'),
  'installAtlasWorkerStageFlowCanvasEventsV1'>;

/** Bind the component-owned stage canvas gestures to the typed runtime state. */
export function installWorkerWorkbenchStageFlowCanvasEventsV1(input: {
  runtime: WorkerWorkbenchStageRuntimeV1;
  surface: HTMLElement;
  componentsTs: AtlasWorkerStageFlowCanvasComponentOwnerV1;
  renderConnections(): void;
  saveState(): void;
}): boolean {
  return input.componentsTs.installAtlasWorkerStageFlowCanvasEventsV1({
    surface: input.surface,
    layout: input.runtime.layout,
    setPosition: (id, position) => {
      input.runtime.layout[id] = { ...workerWorkbenchRecordV1(input.runtime.layout[id]), ...position };
    },
    setWidth: (id, width) => {
      input.runtime.layout[id] = { ...workerWorkbenchRecordV1(input.runtime.layout[id]), width };
    },
    renderConnections: input.renderConnections,
    save: input.saveState,
  });
}

type AtlasWorkerStageFlowConnectionsComponentOwnerV1 = Pick<typeof import('./components.js'),
  'renderAtlasWorkerFlowConnectionsV1'>;

/** Render typed stage links and persist edited relationship labels through the runtime. */
export function renderWorkerWorkbenchStageFlowConnectionsV1(input: {
  runtime: WorkerWorkbenchStageRuntimeV1;
  svg: SVGSVGElement;
  labels: HTMLElement;
  componentsTs: AtlasWorkerStageFlowConnectionsComponentOwnerV1;
  saveState(): void;
}): void {
  input.componentsTs.renderAtlasWorkerFlowConnectionsV1({
    svg: input.svg,
    labels: input.labels,
    links: input.runtime.links.map((link): Record<string, unknown> => ({
      from: link.from, to: link.to, label: link.label, source: link.source, sourceId: link.sourceId,
    })),
    layout: input.runtime.layout,
    updateLabel: (index, value) => {
      const link = input.runtime.links[index];
      if (!link) return;
      link.label = String(value || '').trim() || 'depende de';
      input.saveState();
    },
  });
}

type AtlasWorkerStagePageComponentOwnerV1 = AtlasWorkerStageFlowConnectionsComponentOwnerV1
  & AtlasWorkerAttachmentComponentOwnerV1
  & Pick<typeof import('./components.js'),
    | 'renderAtlasWorkerStageWorkspaceV1'
    | 'renderAtlasWorkerFlowCardListV1'
    | 'installAtlasWorkerStageFlowCanvasEventsV1'>;

export interface WorkerWorkbenchStagePageMountV1 {
  definition: WorkerWorkbenchStageV1;
  snapshot: WorkerWorkbenchStageSnapshotV1;
  runtime: WorkerWorkbenchStageRuntimeV1;
  workspace: WorkerWorkbenchStageWorkspaceProjectionV1;
}

/** Load, compose and mount the stage workbench through the TypeScript owners. */
export async function mountWorkerWorkbenchStagePageV1(input: {
  root: HTMLElement;
  stageKey: string;
  request: WorkerWorkbenchApiReadV1;
  todayIso(): string;
  createId(prefix: string): string;
  route(path: string, query?: string): string;
  renderShell(content: string, mode: string): void;
  publishRuntime(runtime: WorkerWorkbenchStageRuntimeV1): void;
  componentsTs: AtlasWorkerStagePageComponentOwnerV1;
}): Promise<WorkerWorkbenchStagePageMountV1 | null> {
  const renderWorkspace = input.componentsTs?.renderAtlasWorkerStageWorkspaceV1;
  const componentOwners = [
    input.componentsTs?.renderAtlasWorkerFlowCardListV1,
    input.componentsTs?.renderAtlasWorkerFlowConnectionsV1,
    input.componentsTs?.installAtlasWorkerStageFlowCanvasEventsV1,
    input.componentsTs?.renderAtlasWorkerAttachmentPanelV1,
    input.componentsTs?.renderAtlasWorkerAttachmentItemsV1,
    input.componentsTs?.installAtlasWorkerAttachmentEventsV1,
  ];
  const programOwners = [
    loadWorkerWorkbenchStageSnapshotV1,
    createWorkerWorkbenchStageRuntimeV1,
    projectWorkerWorkbenchStageWorkspaceV1,
    createWorkerWorkbenchStageStateSaveCoordinatorV1,
    renderWorkerWorkbenchStageFlowCardsV1,
    renderWorkerWorkbenchStageFlowConnectionsV1,
    mountWorkerWorkbenchStageInputEditorV1,
    installWorkerWorkbenchStageFlowCanvasEventsV1,
    mountWorkerWorkbenchAttachmentPanelV1,
  ];
  if (typeof renderWorkspace !== 'function'
    || componentOwners.some(owner => typeof owner !== 'function')
    || programOwners.some(owner => typeof owner !== 'function')) return null;

  const definition = findWorkerWorkbenchStageV1(input.stageKey);
  if (!definition) throw new Error(`Etapa não encontrada: ${input.stageKey}`);
  const snapshot = await loadWorkerWorkbenchStageSnapshotV1({ stageKey: definition.key, request: input.request });
  const runtime = createWorkerWorkbenchStageRuntimeV1({
    definition,
    panorama: snapshot.panorama,
    monitor: snapshot.monitor,
    storedState: snapshot.statePayload.state || {},
    today: input.todayIso(),
    createId: input.createId,
  });
  const workspace = projectWorkerWorkbenchStageWorkspaceV1({
    definition,
    context: runtime.scheduleContext,
    calendarDate: runtime.calendarDate,
    flowActivities: runtime.flowActivities,
    layout: runtime.layout,
    generatedAt: snapshot.panorama.generatedAt,
  });
  input.publishRuntime(runtime);
  input.renderShell(renderWorkspace({
    projection: workspace,
    stages: [...WORKER_STAGE_WORKBENCH_CATALOG_V1],
    attachments: snapshot.attachmentPayload.attachments || [],
    route: input.route,
  }), 'stage');
  const setSyncState = (message: string): void => {
    const status = input.root.querySelector<HTMLElement>('[data-sync-state]');
    if (status) status.textContent = message;
  };
  const saveState = createWorkerWorkbenchStageStateSaveCoordinatorV1({
    getContext: () => runtime,
    request: input.request,
    setStatus: setSyncState,
  });
  const renderConnections = (): void => {
    const svg = input.root.querySelector<SVGSVGElement>('[data-flow-lines]');
    const labels = input.root.querySelector<HTMLElement>('[data-flow-labels]');
    if (!svg || !labels) return;
    renderWorkerWorkbenchStageFlowConnectionsV1({ runtime, svg, labels, componentsTs: input.componentsTs, saveState });
  };
  const bindCanvasEvents = (): void => {
    const surface = input.root.querySelector<HTMLElement>('[data-flow-surface]');
    if (surface && installWorkerWorkbenchStageFlowCanvasEventsV1({
      runtime,
      surface,
      componentsTs: input.componentsTs,
      renderConnections,
      saveState,
    })) input.root.dataset.stageFlowCanvasEventsOwnerV1 = 'typescript-program';
  };
  const renderFlow = (): void => {
    const target = input.root.querySelector<HTMLElement>('[data-flow-cards]');
    if (!target) return;
    input.componentsTs.renderAtlasWorkerFlowCardListV1({
      target,
      cards: projectWorkerWorkbenchStageFlowCardRenderInputsV1({
        runtime,
        route: input.route,
      }),
    });
    bindCanvasEvents();
  };
  const inputPanel = input.root.querySelector<HTMLElement>('.stage-inputs-panel');
  if (!inputPanel || !mountWorkerWorkbenchStageInputEditorV1({
    panel: inputPanel,
    runtime,
    createId: input.createId,
    todayIso: input.todayIso,
    request: input.request,
    saveState,
    renderFlow,
    drawConnections: renderConnections,
  })) throw new Error('Os owners TypeScript não montaram o editor de entrada da etapa.');
  input.root.dataset.stageInputApplicationOwnerV1 = 'typescript-program';
  renderConnections();
  bindCanvasEvents();
  const main = input.root.querySelector<HTMLElement>('.workbench-main');
  if (!main || !mountWorkerWorkbenchAttachmentPanelV1({
    main,
    definition,
    attachments: snapshot.attachmentPayload.attachments || [],
    request: input.request,
    componentsTs: input.componentsTs,
    setSyncState,
  })) throw new Error('Os owners TypeScript não montaram os anexos da etapa.');
  input.root.dataset.stageRuntimeOwnerV1 = 'typescript';
  input.root.dataset.stageWorkspaceOwnerV1 = 'typescript';
  input.root.dataset.stagePageRendererOwnerV1 = 'typescript';
  input.root.dataset.stagePageCompositionOwnerV1 = 'typescript-program';
  input.root.dataset.stageFlowConnectionsOwnerV1 = 'typescript-program';
  return { definition, snapshot, runtime, workspace };
}

export interface WorkerWorkbenchFlowConnectionV1 {
  index: number;
  path: string;
  targetX: number;
  targetY: number;
  label: string;
  labelX: number;
  labelY: number;
}

/** Project the SVG curve and editable label position for each connected flow card. */
export function projectWorkerWorkbenchFlowConnectionsV1(input: {
  links: readonly Record<string, unknown>[];
  layout: Record<string, unknown>;
}): WorkerWorkbenchFlowConnectionV1[] {
  const clamp = (value: number, min: number, max: number): number => Math.max(min, Math.min(max, value));
  return input.links.flatMap((link, index) => {
    const from = workerWorkbenchRecordV1(input.layout[String(link.from || '')]);
    const to = workerWorkbenchRecordV1(input.layout[String(link.to || '')]);
    const x1 = Number(from.x), y1 = Number(from.y), x2 = Number(to.x), y2 = Number(to.y);
    if (![x1, y1, x2, y2].every(Number.isFinite)) return [];
    const cardWidth = clamp(Number(from.width) || 220, 180, 520), startX = x1 + cardWidth, startY = y1 + 71, endY = y2 + 71;
    const curve = Math.max(45, (x2 - startX) * .45);
    return [{
      index,
      path: `M ${startX} ${startY} C ${startX + curve} ${startY}, ${x2 - curve} ${endY}, ${x2} ${endY}`,
      targetX: x2,
      targetY: endY,
      label: String(link.label || ''),
      labelX: (x1 + x2 + 220) / 2 - 72,
      labelY: (y1 + y2) / 2 + 58,
    }];
  });
}

/** Constrain a dragged activity card to the visible canvas bounds. */
export function projectWorkerWorkbenchFlowCardDragV1(input: {
  origin: { x: number; y: number };
  delta: { x: number; y: number };
  surface: { width: number; height: number };
}): { x: number; y: number } {
  const clamp = (value: number, min: number, max: number): number => Math.max(min, Math.min(max, value));
  return {
    x: clamp(input.origin.x + input.delta.x, 16, input.surface.width - 236),
    y: clamp(input.origin.y + input.delta.y, 72, input.surface.height - 170),
  };
}

/** Snap a dropped card to the same horizontal calendar grid as the existing worker flow. */
export function projectWorkerWorkbenchFlowCardSnapV1(position: { x: number; y: number }): { x: number; y: number } {
  return { x: Math.max(16, Math.round((position.x - 6) / 118) * 118 + 6), y: position.y };
}

/** Convert card width into its calendar span and resulting end date. */
export function projectWorkerWorkbenchFlowCardResizeV1(input: { width: number; start: string }): { width: number; days: number; finish: string } {
  const width = Math.max(180, Math.min(520, Math.round(input.width)));
  const days = Math.max(1, Math.round(width / 118));
  const start = new Date(`${input.start}T12:00:00`);
  start.setDate(start.getDate() + days);
  return { width, days, finish: start.toISOString().slice(0, 10) };
}

export function projectWorkerWorkbenchActivityPageV1(input: {
  definition: WorkerWorkbenchStageV1;
  item: Partial<WorkerWorkbenchActivityV1> & Record<string, unknown>;
  context: WorkerWorkbenchStageContextV1;
  today?: string;
}): WorkerWorkbenchActivityPageProjectionV1 {
  const today = /^\d{4}-\d{2}-\d{2}$/.test(String(input.today || ''))
    ? String(input.today) : new Date().toISOString().slice(0, 10);
  const total = Math.max(1, input.definition.activities.length);
  const foundIndex = input.definition.activities.findIndex(activity => String(activity.id) === String(input.item.id || ''));
  const index = Math.max(0, foundIndex);
  const automation = input.context.automation;
  const start = /^\d{4}-\d{2}-\d{2}$/.test(String(automation.plannedStart || '')) ? String(automation.plannedStart) : today;
  const finish = /^\d{4}-\d{2}-\d{2}$/.test(String(automation.plannedFinish || '')) ? String(automation.plannedFinish) : start;
  const startDate = new Date(`${start}T12:00:00`), finishDate = new Date(`${finish}T12:00:00`);
  const span = Math.max(total, (finishDate.getTime() - startDate.getTime()) / 86400000);
  const segment = span / total;
  const activityStart = new Date(startDate), activityEnd = new Date(startDate);
  const segmentOffset = Math.floor(segment * index);
  activityStart.setDate(startDate.getDate() + segmentOffset);
  activityEnd.setDate(startDate.getDate() + Math.max(Math.floor(segment * (index + 1)), segmentOffset + 1));
  const item = input.item as WorkerWorkbenchActivityV1;
  const operation = workerWorkbenchRecordV1(input.item.operational);
  const responsibility = workerWorkbenchRecordV1(operation.responsibility);
  const evidence = Array.isArray(operation.evidence) ? operation.evidence.map(String).join(' · ') : String(operation.evidence || '');
  const stageBudget = Number(input.context.summary.budgetCents) || 0;
  const totalWeight = input.definition.activities.reduce((sum, row) => sum + (Number(row.weight) || 0), 0);
  const weight = Number(input.item.weight) || 0;
  const responsible = String(input.item.responsible || responsibility.primary || input.context.owner || '');
  return {
    definition: input.definition,
    item,
    context: input.context,
    index,
    total: input.definition.activities.length,
    start: activityStart.toISOString().slice(0, 10),
    end: activityEnd.toISOString().slice(0, 10),
    activityBudgetCents: totalWeight ? Math.round(stageBudget * weight / totalWeight) : 0,
    progress: projectWorkerWorkbenchActivityProgressV1(input.context.progress, index, total),
    cashCoverage: Math.max(0, Math.min(100, Number(automation.cashCoverage) || 0)),
    materialCoverage: Math.max(0, Math.min(100, Number(automation.materialCoverage) || 0)),
    blocked: Boolean(input.context.live.blockedBy?.length),
    responsible,
    today,
    editDraft: {
      stageKey: input.definition.key,
      nature: String(operation.nature || 'Execução operacional'),
      name: String(input.item.title || ''),
      description: String(operation.description || ''),
      unit: String(input.item.unit || 'registro'),
      responsible,
      release: String(input.item.release || ''),
      target: '',
      evidence,
    },
  };
}

export interface WorkerWorkbenchActivityWorkspaceV1 {
  definition: WorkerWorkbenchStageV1;
  item: WorkerWorkbenchActivityV1;
  snapshot: WorkerWorkbenchActivitySnapshotV1;
  context: WorkerWorkbenchStageContextV1;
  projection: WorkerWorkbenchActivityPageProjectionV1;
}

/** Load and compose the canonical activity, persisted override, and operational projection. */
export async function loadWorkerWorkbenchActivityWorkspaceV1(input: {
  stageKey: string;
  activityId: string;
  request: WorkerWorkbenchApiReadV1;
  today?: string;
}): Promise<WorkerWorkbenchActivityWorkspaceV1> {
  const activityId = String(input.activityId || '');
  const selected = findWorkerWorkbenchActivityV1(input.stageKey, activityId);
  const definition = selected.stage;
  const baseItem: WorkerWorkbenchActivityV1 = activityId === 'new' ? {
    id: 'new',
    title: 'Nova atividade',
    unit: 'registro',
    release: 'Definir requisito de saída',
    materials: ['A definir após o escopo'],
    weight: 1,
    operational: {
      production: {
        unit: 'registro',
        method: 'Registrar a unidade confirmada por frente, local e data',
        formula: 'quantidade válida = soma das medições confirmadas',
      },
    },
  } : selected.activity;
  const snapshot = await loadWorkerWorkbenchActivitySnapshotV1({
    stageKey: definition.key,
    activityId: baseItem.id,
    request: input.request,
  });
  const storedState = workerWorkbenchRecordV1(snapshot.statePayload.state);
  const sessions = Array.isArray(storedState.inputSessions) ? storedState.inputSessions : [];
  const storedActivity = sessions.find((value: unknown) => {
    const row = workerWorkbenchRecordV1(value);
    return String(row.activityId || row.id || '') === baseItem.id;
  }) as Record<string, any> | undefined;
  const item = {
    ...baseItem,
    ...(storedActivity || {}),
    id: baseItem.id,
    materials: Array.isArray(storedActivity?.materials) ? storedActivity.materials : baseItem.materials,
    operational: storedActivity?.operational || baseItem.operational,
  } as WorkerWorkbenchActivityV1;
  const context = projectWorkerWorkbenchStageContextV1(snapshot.panorama, snapshot.monitor, definition);
  const projection = projectWorkerWorkbenchActivityPageV1({
    definition,
    item,
    context,
    today: input.today,
  });
  return { definition, item, snapshot, context, projection };
}

/** Apply activity edits to the persisted stage session without discarding unrelated stage state. */
export function projectWorkerWorkbenchActivityEditStateV1(input: {
  currentState: unknown;
  activity: WorkerWorkbenchActivityV1;
  values: WorkerWorkbenchActivityEditValuesV1;
}): Record<string, unknown> {
  const current = workerWorkbenchRecordV1(input.currentState);
  const sessions = Array.isArray(current.inputSessions)
    ? current.inputSessions.map(workerWorkbenchRecordV1)
    : [];
  const activityId = String(input.activity.id || '');
  const index = sessions.findIndex(session =>
    String(session.activityId || session.id || '') === activityId);
  const existing = index >= 0 ? sessions[index] : {};
  const operation = workerWorkbenchRecordV1(existing.operational || input.activity.operational);
  const responsibility = workerWorkbenchRecordV1(operation.responsibility);
  const nextOperational = {
    ...operation,
    nature: input.values.nature || operation.nature || 'Execução operacional',
    description: input.values.description,
    target: input.values.target,
    evidence: input.values.evidence,
    responsibility: { ...responsibility, primary: input.values.responsible },
  };
  const nextSession = {
    ...existing,
    id: String(existing.id || `input-${activityId}`),
    activityId,
    title: input.values.name || input.activity.title,
    text: input.values.description,
    unit: input.values.unit || input.activity.unit,
    release: input.values.release || input.activity.release,
    responsible: input.values.responsible,
    target: input.values.target,
    evidence: input.values.evidence,
    nature: input.values.nature,
    materials: existing.materials || input.activity.materials,
    operational: nextOperational,
  };
  const inputSessions = index >= 0
    ? sessions.map((session, sessionIndex) => sessionIndex === index ? nextSession : session)
    : [...sessions, nextSession];
  return {
    ...current,
    layout: workerWorkbenchRecordV1(current.layout),
    links: Array.isArray(current.links) ? current.links : [],
    calendarDate: current.calendarDate || null,
    inputSessions,
  };
}

export interface WorkerWorkbenchActivityRecordPageProjectionV1 {
  stageKey: string;
  stageName: string;
  activityId: string;
  activityName: string;
  unit: string;
  responsible: string;
  release: string;
  state: string;
  backHref: string;
  today: string;
}

/** Project the isolated field-entry route from the activity and live stage context. */
export function projectWorkerWorkbenchActivityRecordPageV1(input: {
  definition: WorkerWorkbenchStageV1;
  item: Partial<WorkerWorkbenchActivityV1> & Record<string, unknown>;
  context: WorkerWorkbenchStageContextV1;
  route: (path: string, query?: string) => string;
  today?: string;
}): WorkerWorkbenchActivityRecordPageProjectionV1 {
  const responsibility = workerWorkbenchRecordV1(workerWorkbenchRecordV1(input.item.operational).responsibility);
  const today = /^\d{4}-\d{2}-\d{2}$/.test(String(input.today || ''))
    ? String(input.today) : new Date().toISOString().slice(0, 10);
  const activityId = String(input.item.id || '');
  return {
    stageKey: input.definition.key,
    stageName: input.definition.title,
    activityId,
    activityName: String(input.item.title || 'Atividade'),
    unit: String(input.item.unit || 'registro'),
    responsible: String(input.item.responsible || responsibility.primary || input.context.owner || ''),
    release: String(input.item.release || 'Aceite a definir'),
    state: input.context.live.blockedBy?.length ? 'BLOQUEADA' : 'EM ACOMPANHAMENTO',
    backHref: input.route('/admin/workers/activity', `stage=${input.definition.key}&activity=${activityId}`),
    today,
  };
}

export interface WorkerWorkbenchActivityRecordWorkspaceV1 {
  definition: WorkerWorkbenchStageV1;
  item: WorkerWorkbenchActivityV1;
  snapshot: Omit<WorkerWorkbenchStageSnapshotV1, 'attachmentPayload'>;
  context: WorkerWorkbenchStageContextV1;
  projection: WorkerWorkbenchActivityRecordPageProjectionV1;
}

/** Load canonical activity data and project the dedicated record page through the authenticated port. */
export async function loadWorkerWorkbenchActivityRecordWorkspaceV1(input: {
  stageKey: string;
  activityId: string;
  request: WorkerWorkbenchApiReadV1;
  route: (path: string, query?: string) => string;
  today?: string;
}): Promise<WorkerWorkbenchActivityRecordWorkspaceV1> {
  const selected = findWorkerWorkbenchActivityV1(input.stageKey, String(input.activityId || ''));
  const definition = selected.stage;
  const snapshot = await loadWorkerWorkbenchActivityRecordSnapshotV1({
    stageKey: definition.key,
    request: input.request,
  });
  const state = workerWorkbenchRecordV1(snapshot.statePayload.state);
  const sessions = Array.isArray(state.inputSessions) ? state.inputSessions : [];
  const stored = sessions.map(workerWorkbenchRecordV1).find(row =>
    String(row.activityId || row.id || '') === selected.activity.id,
  ) || {};
  const baseResponsibility = workerWorkbenchRecordV1(
    workerWorkbenchRecordV1(selected.activity.operational).responsibility,
  );
  const item = {
    ...selected.activity,
    ...stored,
    id: selected.activity.id,
    unit: String(stored.unit || selected.activity.unit),
    release: String(stored.release || selected.activity.release),
    responsible: String(stored.responsible || baseResponsibility.primary || ''),
  } as WorkerWorkbenchActivityV1;
  const context = projectWorkerWorkbenchStageContextV1(snapshot.panorama, snapshot.monitor, definition);
  const projection = projectWorkerWorkbenchActivityRecordPageV1({
    definition,
    item,
    context,
    route: input.route,
    today: input.today,
  });
  return { definition, item, snapshot, context, projection };
}

export interface WorkerWorkbenchActivityRecordPayloadV1 {
  activityId: string;
  recordDate: string;
  responsible: string;
  production: string;
  unit: string;
  status: string;
  notes: string;
}

/** Build the persisted diary payload from the dedicated record form. */
export function projectWorkerWorkbenchActivityRecordPayloadV1(input: {
  values: Record<string, unknown>;
  activityId: string;
}): WorkerWorkbenchActivityRecordPayloadV1 {
  return {
    activityId: input.activityId,
    recordDate: String(input.values.recordDate || ''),
    responsible: String(input.values.responsible || ''),
    production: String(input.values.production || ''),
    unit: String(input.values.unit || 'registro'),
    status: String(input.values.status || 'registrado'),
    notes: String(input.values.notes || ''),
  };
}

function workerWorkbenchMaterialRowsV1(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value)
    ? value.map(item => typeof item === 'string' ? { name: item } : workerWorkbenchRecordV1(item))
      .filter(item => Boolean(String(item.name || item.title || '').trim()))
    : [];
}

function workerWorkbenchMaterialLabelV1(value: unknown): string {
  const item = workerWorkbenchRecordV1(value);
  return [item.name || item.title, item.description, item.usage || item.use]
    .map(part => String(part || '').trim()).filter(Boolean).join(' — ');
}

export function defaultWorkerWorkbenchAutomationV1(): WorkerWorkbenchAutomationV1 {
  return { ...workerWorkbenchProgrammingCatalog.automationDefaults };
}

export function normalizeWorkerWorkbenchAutomationV1(value: unknown): WorkerWorkbenchAutomationV1 {
  const source = workerWorkbenchRecordV1(value);
  return Object.fromEntries(Object.keys(defaultWorkerWorkbenchAutomationV1()).map(key => [key, source[key] !== false])) as unknown as WorkerWorkbenchAutomationV1;
}

export function projectWorkerWorkbenchInputProfileV1(session: Partial<WorkbenchSession>): {
  unit: string; quantified: boolean; physical: boolean; hasMaterials: boolean; hasDependency: boolean;
  productionBasis: string;
} {
  const unit = String(session.unit || '').trim().toLocaleLowerCase('pt-BR');
  const materials = workerWorkbenchMaterialRowsV1(session.materials).map(workerWorkbenchMaterialLabelV1).join(' ');
  const text = `${session.title || ''} ${session.text || ''} ${session.release || ''} ${materials}`.toLocaleLowerCase('pt-BR');
  const rules = workerWorkbenchInputProfileMatchersV1;
  const quantified = rules.quantifiedUnit.test(unit);
  const physical = !rules.nonPhysicalUnit.test(unit) && !rules.nonPhysicalText.test(text);
  const hasMaterials = Boolean(session.materials?.length) || rules.hasMaterials.test(text);
  const hasDependency = Boolean(session.release) || rules.hasDependency.test(text);
  const productionBasis = rules.volumeBasis.test(unit) ? 'volume' : rules.areaBasis.test(unit) ? 'area' : rules.lengthBasis.test(unit) ? 'comprimento'
    : rules.countBasis.test(unit) ? 'contagem' : 'registro';
  return { unit, quantified, physical, hasMaterials, hasDependency, productionBasis };
}

export function defaultWorkerWorkbenchProgrammingV1(session: Partial<WorkbenchSession>): WorkerWorkbenchProgrammingV1 {
  const profile = projectWorkerWorkbenchInputProfileV1(session);
  return {
    scheduleMode: profile.quantified ? 'production' : profile.hasDependency ? 'sequential' : 'parallel',
    productionModeEnabled: profile.quantified, productionBasis: profile.productionBasis,
    mapLocation: profile.physical, requireAcceptance: profile.hasDependency,
  };
}

export function normalizeWorkerWorkbenchProgrammingV1(value: unknown, session: Partial<WorkbenchSession>): WorkerWorkbenchProgrammingV1 {
  const source = workerWorkbenchRecordV1(value), defaults = defaultWorkerWorkbenchProgrammingV1(session);
  const modes = workerWorkbenchProgrammingCatalog.scheduleModes;
  return {
    scheduleMode: modes.includes(String(source.scheduleMode) as WorkerWorkbenchProgrammingV1['scheduleMode']) ? source.scheduleMode as WorkerWorkbenchProgrammingV1['scheduleMode'] : defaults.scheduleMode,
    productionModeEnabled: defaults.productionModeEnabled && source.productionModeEnabled !== false,
    productionBasis: String(source.productionBasis || defaults.productionBasis),
    mapLocation: defaults.mapLocation && source.mapLocation !== false,
    requireAcceptance: defaults.requireAcceptance && source.requireAcceptance !== false,
  };
}

export function projectWorkerWorkbenchProgrammingOptionsV1(session: Partial<WorkbenchSession>): WorkerWorkbenchProgrammingOptionV1[] {
  const profile = projectWorkerWorkbenchInputProfileV1(session);
  const programming = normalizeWorkerWorkbenchProgrammingV1(session.programming, session);
  const automation = normalizeWorkerWorkbenchAutomationV1(session.automation);
  const options: WorkerWorkbenchProgrammingOptionDataV1[] = workerWorkbenchProgrammingCatalog.automationOptions.map(option => ({ ...option }));
  if (profile.hasMaterials) options.push({ ...workerWorkbenchProgrammingCatalog.resourceOption });
  if (profile.quantified) {
    const { labelTemplate, helpTemplate, ...option } = workerWorkbenchProgrammingCatalog.productionOption;
    options.push({
      ...option,
      label: formatWorkerWorkbenchCatalogTextV1(labelTemplate, { unit: session.unit }),
      help: formatWorkerWorkbenchCatalogTextV1(helpTemplate, { productionBasis: profile.productionBasis }),
    });
  }
  if (profile.physical) options.push({ ...workerWorkbenchProgrammingCatalog.mapLocationOption });
  if (profile.hasDependency) options.push({ ...workerWorkbenchProgrammingCatalog.acceptanceOption });
  return options.map(option => ({
    ...option,
    checked: option.storage === 'automation'
      ? automation[option.key] !== false
      : programming[option.key] === true,
  }));
}

export function projectWorkerWorkbenchProductionPreviewV1(session: Partial<WorkbenchSession>): WorkerWorkbenchProductionSpecV1 {
  const profile = projectWorkerWorkbenchInputProfileV1(session);
  const programming = normalizeWorkerWorkbenchProgrammingV1(session.programming, session);
  const unit = String(session.unit || 'registro');
  const basis = programming.productionBasis || profile.productionBasis;
  const labels = workerWorkbenchProgrammingCatalog.basisLabels;
  const referenceRate = formatWorkerWorkbenchCatalogTextV1(workerWorkbenchProgrammingCatalog.referenceRateTemplate, { unit });
  const conditions: WorkerWorkbenchProductionConditionV1[] = workerWorkbenchProgrammingCatalog.baseProductionConditions.map(({ triggerTemplate, ...condition }) => ({
    ...condition,
    trigger: formatWorkerWorkbenchCatalogTextV1(triggerTemplate, { referenceRate }),
  }));
  if (session.release) {
    const { triggerTemplate, ...condition } = workerWorkbenchProgrammingCatalog.releaseCondition;
    conditions.push({ ...condition, trigger: formatWorkerWorkbenchCatalogTextV1(triggerTemplate, { release: session.release }) });
  }
  if (session.materials?.length) {
    const materials = workerWorkbenchMaterialRowsV1(session.materials).map(workerWorkbenchMaterialLabelV1).join(', ');
    const { triggerTemplate, ...condition } = workerWorkbenchProgrammingCatalog.materialsCondition;
    conditions.push({ ...condition, trigger: formatWorkerWorkbenchCatalogTextV1(triggerTemplate, { materials }) });
  }
  return {
    basis, basisLabel: labels[basis] || labels.registro, unit,
    measureForm: formatWorkerWorkbenchCatalogTextV1(workerWorkbenchProgrammingCatalog.measureFormTemplate, { unit }),
    quantityFormula: formatWorkerWorkbenchCatalogTextV1(workerWorkbenchProgrammingCatalog.quantityFormulaTemplate, { unit }),
    durationFormula: formatWorkerWorkbenchCatalogTextV1(workerWorkbenchProgrammingCatalog.durationFormulaTemplate, { unit }),
    referenceRate, totalQuantity: workerWorkbenchProgrammingCatalog.totalQuantityLabel, conditions,
    source: workerWorkbenchProgrammingCatalog.previewSourceLabel,
  };
}

export function projectWorkerWorkbenchProductionDraftV1(session: Partial<WorkbenchSession>): WorkerWorkbenchProductionDraftV1 {
  const preview = projectWorkerWorkbenchProductionPreviewV1(session);
  const inference = workerWorkbenchRecordV1(session.inference);
  const production = workerWorkbenchRecordV1(inference.production);
  const spec = { ...preview, ...production } as WorkerWorkbenchProductionSpecV1;
  const conditions = Array.isArray(inference.conditions)
    ? inference.conditions as WorkerWorkbenchProductionConditionV1[]
    : preview.conditions;
  return { spec, conditions };
}

export function projectWorkerWorkbenchInputCardV1(session: Partial<WorkbenchSession>): WorkerWorkbenchInputCardProjectionV1 {
  const profile = projectWorkerWorkbenchInputProfileV1(session);
  const programming = normalizeWorkerWorkbenchProgrammingV1(session.programming, session);
  const inference = session.inference && typeof session.inference === 'object'
    ? session.inference as Record<string, unknown> : null;
  return {
    programmingOptions: projectWorkerWorkbenchProgrammingOptionsV1(session),
    programmingSettings: {
      unit: String(session.unit || 'registro'),
      scheduleMode: programming.scheduleMode,
      productionBasis: programming.productionBasis,
      bases: profile.quantified ? ['volume', 'area', 'comprimento', 'contagem', 'registro'] : ['registro'],
    },
    productionDraft: projectWorkerWorkbenchProductionDraftV1(session),
    properties: normalizeWorkerWorkbenchPropertiesV1(session.properties, session),
    inference,
  };
}

export function ensureWorkerWorkbenchProductionDraftV1(session: WorkerWorkbenchInputSessionV1): Record<string, unknown> {
  const preview = projectWorkerWorkbenchProductionPreviewV1(session);
  const existing = workerWorkbenchRecordV1(session.inference);
  const production = { ...preview, ...workerWorkbenchRecordV1(existing.production) };
  const conditions = Array.isArray(existing.conditions)
    ? existing.conditions.map(value => Object.assign({}, value as object)) as WorkerWorkbenchProductionConditionV1[]
    : preview.conditions.map(condition => ({ ...condition }));
  const automation = normalizeWorkerWorkbenchAutomationV1(session.automation);
  const inference = {
    ...existing, manual: true, loading: false, confidence: Number(existing.confidence) || 0,
    production, conditions,
    notificationPolicy: existing.notificationPolicy || {
      enabled: automation.notifyWorker, mode: 'pseudo-listener', trigger: 'structured-condition-match',
      primaryRecipient: 'owner', deduplicateBy: 'stage/activity/condition/event', externalMessaging: 'disabled',
    },
  };
  session.inference = inference;
  return inference;
}

export function defaultWorkerWorkbenchPropertiesV1(session: Partial<WorkbenchSession>): WorkerWorkbenchPropertyV1[] {
  const operational = workerWorkbenchRecordV1(session.operational);
  const responsibility = workerWorkbenchRecordV1(operational.responsibility);
  const production = workerWorkbenchRecordV1(operational.production);
  const materials = workerWorkbenchMaterialRowsV1(session.materials || operational.materials || operational.equipment)
    .map(workerWorkbenchMaterialLabelV1).filter(Boolean).join(', ');
  const list = (value: unknown): string[] => Array.isArray(value) ? value.map(String) : [];
  const evidence = operational.evidence || operational.acceptance;
  const id = String(session.id || 'input');
  const property = (key: string, value: unknown): WorkerWorkbenchPropertyV1 => {
    const definition = workerWorkbenchProgrammingCatalog.defaultProperties[key];
    return {
      id: `${id}-${key}`,
      label: definition.label,
      value: String(value || definition.fallback),
    };
  };
  return [
    property('unit', session.unit || production.unit),
    property('materials', materials),
    property('release', session.release),
    property('responsible', responsibility.primary),
    property('support', responsibility.support),
    property('entry', list(operational.entryConditions).join(' · ')),
    property('measure', production.method),
    property('formula', production.formula),
    property('evidence', list(evidence).join(' · ')),
    property('legal', list(operational.legalBasis).join(' · ')),
  ];
}

export function normalizeWorkerWorkbenchPropertiesV1(value: unknown, session: Partial<WorkbenchSession>): WorkerWorkbenchPropertyV1[] {
  const defaults = defaultWorkerWorkbenchPropertiesV1(session);
  const existing = Array.isArray(value) ? value.map(workerWorkbenchRecordV1) : [];
  const source = existing.length
    ? [...existing, ...defaults.filter(item => !existing.some(row => String(row.id || '') === item.id))]
    : defaults;
  return source.slice(0, 30).map((item, index) => ({
    id: String(item.id || `${session.id || 'input'}-property-${index}`),
    label: String(item.label || `Propriedade ${index + 1}`),
    value: String(item.value ?? ''),
  }));
}

