export interface AtlasWorkerContextChatToolCallV1 {
  name: string;
  arguments?: Record<string, unknown>;
  args?: Record<string, unknown>;
}

export interface AtlasWorkerContextChatActionPlanInputV1 {
  message: unknown;
  directOperational?: boolean;
  replyToolCalls?: readonly unknown[];
}

export interface AtlasWorkerContextChatActionPlanV1 {
  localCalls: AtlasWorkerContextChatToolCallV1[];
  actionRequested: boolean;
  proposedCalls: AtlasWorkerContextChatToolCallV1[];
}

interface AtlasWorkerContextChatIntentRuleV1 { key: string; pattern: string }
interface AtlasWorkerContextChatIntentCatalogV1 {
  patterns: Record<string, string>;
  overlays: AtlasWorkerContextChatIntentRuleV1[];
  destinations: AtlasWorkerContextChatIntentRuleV1[];
  reportFamilies: Array<{ family: string; pattern: string }>;
}
const workerContextChatIntentCatalog = workerContextChatIntentsData as AtlasWorkerContextChatIntentCatalogV1;
const workerContextChatIntentPatterns = Object.fromEntries(
  Object.entries(workerContextChatIntentCatalog.patterns).map(([key, pattern]) => [key, new RegExp(pattern)]),
) as Record<string, RegExp>;
const workerContextChatOverlayRules = workerContextChatIntentCatalog.overlays.map(rule => ({ ...rule, expression: new RegExp(rule.pattern) }));
const workerContextChatDestinationRules = workerContextChatIntentCatalog.destinations.map(rule => ({ ...rule, expression: new RegExp(rule.pattern) }));
const workerContextChatReportFamilyRules = workerContextChatIntentCatalog.reportFamilies.map(rule => ({ ...rule, expression: new RegExp(rule.pattern) }));

/** Convert an explicit chat navigation/action request into canonical local commands. */
export function projectAtlasWorkerContextChatUiIntentV1(message: unknown): AtlasWorkerContextChatToolCallV1[] {
  const text = String(message || '').toLocaleLowerCase('pt-BR');
  const patterns = workerContextChatIntentPatterns;
  if (!patterns.actionRequest.test(text)) return [];
  if (patterns.mapKeyword.test(text)) {
    const overlay = workerContextChatOverlayRules.find(rule => rule.expression.test(text))?.key;
    if (overlay && patterns.overlayRequest.test(text))
      return [{ name: 'map.set_overlay', arguments: { category: overlay } }];
    if (patterns.zoomIn.test(text)) return [{ name: 'map.adjust_view', arguments: { zoomDelta: .22 } }];
    if (patterns.zoomOut.test(text)) return [{ name: 'map.adjust_view', arguments: { zoomDelta: -.22 } }];
    if (patterns.rotate.test(text))
      return [{ name: 'map.adjust_view', arguments: { rotationDelta: patterns.rotateLeft.test(text) ? -20 : 20 } }];
  }
  if (patterns.recordKind.test(text) && patterns.recordCreate.test(text))
    return [{ name: 'records.open_form', arguments: {} }];

  const target = workerContextChatDestinationRules.find(rule => rule.expression.test(text))?.key;
  if (!target) return [];
  const create = patterns.create.test(text);
  if (target === 'reports' && !create) {
    const family = workerContextChatReportFamilyRules.find(rule => rule.expression.test(text))?.family || null;
    if (family) return [{ name: 'reports.select', arguments: { family } }];
  }
  return [{ name: create ? 'ui.open_form' : 'ui.navigate', arguments: { view: target } }];
}

/** Combine local intent with model calls while gating actions on explicit requests. */
export function projectAtlasWorkerContextChatActionPlanV1(
  input: AtlasWorkerContextChatActionPlanInputV1,
): AtlasWorkerContextChatActionPlanV1 {
  const text = String(input.message || '');
  const directOperational = input.directOperational === true;
  const localCalls = projectAtlasWorkerContextChatUiIntentV1(text);
  const replyToolCalls = Array.isArray(input.replyToolCalls)
    ? input.replyToolCalls.filter((call): call is AtlasWorkerContextChatToolCallV1 =>
      Boolean(call && typeof call === 'object' && typeof (call as AtlasWorkerContextChatToolCallV1).name === 'string'))
    : [];
  const actionRequested = directOperational || /\b(abra|abrir|mostre|mostrar|acesse|acessar|ir para|navegue|navegar|novo|nova|criar|adicionar|registre|registrar|filtre|filtrar|destaque|destacar|aproxime|aproximar|afaste|afastar|gire|girar|imprima|imprimir|execute|executar|fa[cç]a|fazer)\b/i.test(text);
  const proposedCalls = !actionRequested ? []
    : directOperational && replyToolCalls.length ? replyToolCalls
      : localCalls.length ? localCalls.map(call => {
        const proposed = replyToolCalls.find(item => item.name === call.name);
        return call.name === 'records.open_form' && proposed
          ? { ...call, arguments: { ...call.arguments, ...(proposed.arguments || {}) } }
          : call;
      })
        : replyToolCalls;
  return { localCalls, actionRequested, proposedCalls };
}

export interface AtlasWorkerContextChatExecutionStoreV1 {
  get(): Record<string, any>;
  set(patch: Record<string, any>): void;
}

export interface AtlasWorkerContextChatExecutionPortsV1 {
  pathname: string;
  getStore(): AtlasWorkerContextChatExecutionStoreV1 | null;
  querySelector(selector: string): any;
  waitForUi(predicate: () => boolean): Promise<boolean>;
  nextPaint(): Promise<void>;
  apiFetch(path: string, init?: RequestInit): Promise<any>;
  setLocalStorage(key: string, value: string): void;
  now(): number;
  getLotDevelopmentProfileUpsert(): ((args: Record<string, unknown>) => { title?: string }) | null;
  allocateVisualRecord(): ((args: AtlasWorkerContextChatVisualAllocationArgumentsV1, context: Record<string, unknown>) => Promise<string | void>) | null;
}

export interface AtlasWorkerContextChatUiWaitOptionsV1 {
  host?: Pick<typeof globalThis, 'performance' | 'setTimeout'>;
  timeoutMs?: number;
  intervalMs?: number;
}

/** Wait for an observable UI transition without keeping timing policy in the MJS host adapter. */
export async function waitForAtlasWorkerContextChatUiV1(
  predicate: () => boolean,
  options: AtlasWorkerContextChatUiWaitOptionsV1 = {},
): Promise<boolean> {
  const host = options.host || globalThis;
  const timeoutMs = Number.isFinite(options.timeoutMs) ? Math.max(0, Number(options.timeoutMs)) : 1200;
  const intervalMs = Number.isFinite(options.intervalMs) ? Math.max(0, Number(options.intervalMs)) : 40;
  const now = (): number => host.performance?.now?.() ?? Date.now();
  const until = now() + timeoutMs;
  while (now() < until) {
    if (predicate()) return true;
    await new Promise<void>(resolve => host.setTimeout(resolve, intervalMs));
  }
  return Boolean(predicate());
}

export interface AtlasWorkerContextChatExecutionPortFactoryInputV1 {
  apiFetch: AtlasWorkerContextChatExecutionPortsV1['apiFetch'];
  waitForUi?: AtlasWorkerContextChatExecutionPortsV1['waitForUi'];
  host?: typeof globalThis;
}

/** Resolve browser, application-store, and feature ports for the worker-chat command executor. */
export function createAtlasWorkerContextChatExecutionPortsV1(
  input: AtlasWorkerContextChatExecutionPortFactoryInputV1,
): AtlasWorkerContextChatExecutionPortsV1 {
  const host = (input.host || globalThis) as typeof globalThis & {
    __belavistaAppStore?: AtlasWorkerContextChatExecutionStoreV1;
    __BELAVISTA_UPSERT_LOT_DEVELOPMENT_PROFILE_V1?: NonNullable<ReturnType<AtlasWorkerContextChatExecutionPortsV1['getLotDevelopmentProfileUpsert']>>;
    __BELAVISTA_ALLOCATE_VISUAL_RECORD_V1?: NonNullable<ReturnType<AtlasWorkerContextChatExecutionPortsV1['allocateVisualRecord']>>;
  };
  const documentRef = host.document;
  return {
    pathname: host.location.pathname,
    getStore: () => host.__belavistaAppStore || null,
    querySelector: selector => documentRef.querySelector(selector),
    waitForUi: input.waitForUi || (predicate => waitForAtlasWorkerContextChatUiV1(predicate, { host })),
    nextPaint: () => new Promise<void>(resolve => host.requestAnimationFrame(() => host.requestAnimationFrame(() => resolve()))),
    apiFetch: input.apiFetch,
    setLocalStorage: (key, value) => host.localStorage.setItem(key, value),
    now: () => host.Date.now(),
    getLotDevelopmentProfileUpsert: () => host.__BELAVISTA_UPSERT_LOT_DEVELOPMENT_PROFILE_V1 || null,
    allocateVisualRecord: () => host.__BELAVISTA_ALLOCATE_VISUAL_RECORD_V1 || null,
  };
}

/** Execute worker chat commands through browser, API, and store ports supplied by the MJS adapter. */
export async function executeAtlasWorkerContextChatCommandsV1(
  calls: readonly AtlasWorkerContextChatToolCallV1[],
  context: Record<string, unknown>,
  ports: AtlasWorkerContextChatExecutionPortsV1,
): Promise<string[]> {
  const isAdminSurface = ports.pathname.startsWith('/admin') || ports.pathname === '/';
  if (!isAdminSurface) return calls.length ? ['Ação disponível apenas no painel administrativo.'] : [];
  const store = ports.getStore();
  const allowed = new Set(['map','control','lot-development','materials','documents','stages','agenda','actions','activities','records','progress','personnel','leads','contracts','brokers','brokers-board','finance','reports','settings']);
  const forms: Record<string, string> = { materials: '[data-material-new]', documents: '[data-document-new]', agenda: '[data-agenda-new-v3]', activities: '[data-activity-new]', progress: '[data-progress-new]', contracts: '[data-contract-new]', brokers: '[data-commission-new]', reports: '[data-report-builder-open]' };
  const results: string[] = [];
  for (const call of calls.slice(0, 4)) {
    const args = call?.arguments || call?.args || {};
    const view = String(args.view || '');
    if (call?.name === 'lot-development.upsert_profile') {
      const upsert = ports.getLotDevelopmentProfileUpsert();
      if (!upsert) { results.push('Perfil do loteamento recebido, mas o cadastro ainda não terminou de carregar.'); continue; }
      const profile = upsert(args);
      results.push(`Perfil ${profile.title} preparado no Loteamento para revisão humana.`);
      continue;
    }
    if (call?.name === 'stage.allocate_visual_record') {
      const allocator = ports.allocateVisualRecord();
      if (!allocator) { results.push('Leitura visual recebida, mas o alocador do Dashboard ainda não terminou de carregar.'); continue; }
      const message = await allocator(normalizeAtlasWorkerContextChatVisualAllocationArgumentsV1(args), context);
      if (message) results.push(message);
      continue;
    }
    if (call?.name === 'records.open_form') {
      if (!store) { results.push('Ficha não abriu: estado da aplicação indisponível.'); continue; }
      ports.querySelector('.sidebar [data-view="control"]')?.click();
      await ports.nextPaint();
      await ports.nextPaint();
      store.set({ view: 'control', controlEventTab: 'event', controlEventDraft: {
        title: String(args.activity || '').slice(0, 120), responsible: String(args.responsible || '').slice(0, 120),
        details: String(args.details || '').slice(0, 4000),
        category: ['ocorrencia','vistoria','reuniao','comunicacao','decisao','outro'].includes(String(args.category)) ? args.category : 'ocorrencia',
      }, lastAction: 'Chat preparou evento para revisão' });
      results.push(store.get().view === 'control' ? 'Ficha de evento aberta para revisão; nenhum dado foi gravado.' : 'Ficha de evento não abriu.');
      continue;
    }
    if (call?.name === 'agenda.create_pending') {
      if (!store) { results.push('Apontamento não criado: estado da aplicação indisponível.'); continue; }
      const state = store.get() || {};
      const command = await applyAtlasAgendaPendingCommandV1({
        args,
        state,
        apiFetch: ports.apiFetch,
        setLocalStorage: ports.setLocalStorage,
        now: ports.now,
        executionStages: Array.isArray(context.stages) ? context.stages as AtlasAgendaCalendarStageV1[] : [],
      });
      if (!command.ok) {
        results.push(command.message);
        continue;
      }
      store.set(command.statePatch);
      results.push(command.message);
      continue;
    }
    if (call?.name === 'documents.open_form') {
      if (!store) { results.push('Documentos não abriram: estado da aplicação indisponível.'); continue; }
      store.set({ view:'documents', documentsEditId:'new', lastAction:`Assistente dos workers solicitou documento${args.reason ? `: ${String(args.reason).slice(0,120)}` : ''}` });
      results.push('Inclusão de documento aberta para anexar a evidência solicitada.');
      continue;
    }
    if ((call?.name === 'ui.navigate' || call?.name === 'ui.open_form') && allowed.has(view)) {
      const selector = `.sidebar [data-view="${view}"], aside [data-view="${view}"]`;
      if (!store || !ports.querySelector(selector)) { results.push(`${view}: acesso ou navegação indisponível.`); continue; }
      ports.querySelector(selector)?.click();
      if (!await ports.waitForUi(() => Boolean(ports.querySelector(`.sidebar [data-view="${view}"].active, aside [data-view="${view}"].active`)))) { results.push(`${view}: página não abriu.`); continue; }
      if (call.name === 'ui.open_form') {
        await ports.waitForUi(() => Boolean(forms[view] && ports.querySelector(forms[view])));
        const button = forms[view] && ports.querySelector(forms[view]);
        if (!button) { results.push(`${view}: formulário não encontrado nesta página.`); continue; }
        button.click();
        results.push(`${view}: formulário aberto para revisão; nada foi salvo.`);
      } else results.push(`${view}: página aberta.`);
      continue;
    }
    if (call?.name === 'reports.select' && store) {
      const family = ['Financeiro','Construção','Suprimentos','Comercial','Governança'].includes(String(args.family)) ? String(args.family) : 'Financeiro';
      const familySelector = `.sidebar [data-view="reports"][data-report-family="${family}"]`;
      const familyButton = ports.querySelector(familySelector);
      familyButton?.click();
      await ports.waitForUi(() => Boolean(familyButton?.classList.contains('active')));
      store.set({ view: 'reports', reportFamily: family, ...(args.reportType ? { reportType: String(args.reportType).slice(0, 80) } : {}), lastAction: `Chat abriu relatórios de ${family}` });
      results.push(ports.querySelector(`${familySelector}.active`) ? `Relatórios de ${family} abertos.` : `Relatórios de ${family} não abriram.`);
      continue;
    }
    if (call?.name === 'commissions.filter' && store) {
      ports.querySelector('.sidebar [data-view="brokers"]')?.click();
      await ports.nextPaint();
      await ports.nextPaint();
      store.set({ view: 'brokers', commissionFilters: { query: String(args.query || '').slice(0, 120), status: String(args.status || 'all'), profile: String(args.profile || 'all') }, lastAction: 'Chat filtrou negociações' });
      results.push('Filtro comercial aplicado.');
      continue;
    }
    if (call?.name === 'map.set_overlay') {
      const map = ports.querySelector('map-scene');
      const category = String(args.category || '');
      if (!map?.setStageOverlay || !['terraplanagem','drenagem','rede-agua','rede-eletrica','pavimentacao','urbanizacao','clear'].includes(category)) { results.push('Destaque do mapa indisponível.'); continue; }
      if (category === 'clear') map.clearStageOverlay?.(false); else map.setStageOverlay?.(category, false);
      results.push(category === 'clear' ? 'Destaque do mapa removido.' : `Mapa: ${category} destacada.`);
      continue;
    }
    if (call?.name === 'map.adjust_view') {
      const map = ports.querySelector('map-scene');
      if (!map?.setSceneZoom) { results.push('Controle de vista do mapa indisponível.'); continue; }
      if (args.fit) map.fitSceneView?.(true);
      else {
        if (Number.isFinite(Number(args.zoomDelta))) map.setSceneZoom(map.sceneManualZoom + Math.max(-1, Math.min(1, Number(args.zoomDelta))), true);
        if (Number.isFinite(Number(args.tiltDelta))) map.setSceneTiltAdjust?.(map.sceneTiltAdjust + Math.max(-24, Math.min(24, Number(args.tiltDelta))), true);
        if (Number.isFinite(Number(args.rotationDelta))) map.setSceneRotation?.(map.sceneManualRotation + Math.max(-90, Math.min(90, Number(args.rotationDelta))), true);
      }
      results.push('Vista do mapa ajustada.');
      continue;
    }
    if (call?.name === 'map.set_tiles') {
      const map = ports.querySelector('map-scene');
      if (!map?.setMapTileMode || !['satellite','osm'].includes(String(args.mode))) { results.push('Base cartográfica indisponível.'); continue; }
      map.setMapTileMode(args.mode, true);
      results.push(`Base ${args.mode === 'osm' ? 'OSM' : 'satélite'} selecionada.`);
      continue;
    }
    if (call?.name === 'ui.print') { results.push('Impressão não iniciada: use o comando de impressão da página para confirmar.'); continue; }
    if (call?.name) results.push(`${call.name}: ação ainda não disponível neste chat.`);
  }
  return results;
}

