/** Resolve browser storage in the program and attach the chat's transient state ports. */
export function createAtlasWorkerContextChatServiceRequestPortsV1(
  input: AtlasWorkerContextChatServiceRequestPortFactoryInputV1,
): AtlasWorkerContextChatServiceRequestPortsV1 {
  const host = input.host || globalThis;
  return {
    apiFetch: input.apiFetch,
    storageGet: key => host.localStorage.getItem(key),
    storageSet: (key, value) => host.localStorage.setItem(key, value),
    getChatState: input.getChatState,
    setChatState: input.setChatState,
    render: input.render,
    setStatus: input.setStatus,
  };
}

interface AtlasWorkerContextChatStageActivityV1 extends Record<string, unknown> {
  id?: unknown;
  key?: unknown;
  name?: unknown;
  title?: unknown;
  description?: unknown;
  details?: unknown;
}

interface AtlasWorkerContextChatStageProfileV1 extends Record<string, unknown> {
  typicalDescription?: unknown;
  executionDescription?: unknown;
  requestHints?: unknown;
  evidenceFocus?: unknown;
}

interface AtlasWorkerContextChatStageV1 extends Record<string, unknown> {
  key: string;
  name: string;
  id?: unknown;
  description?: unknown;
  executionProfile?: unknown;
  aiConfig?: unknown;
  activityHints?: unknown;
  activities?: unknown;
  materials?: unknown;
  unit?: unknown;
}

function normalizeAtlasWorkerContextChatStageTextV1(value: unknown): string {
  return String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLocaleLowerCase('pt-BR').replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ');
}

function normalizeAtlasWorkerContextChatStagesV1(stages: readonly unknown[]): AtlasWorkerContextChatStageV1[] {
  return (Array.isArray(stages) ? stages : []).map(value => {
    const stage = mapRecord(value) || {};
    return {
      ...stage,
      key: String(stage.key ?? '').trim(),
      name: String(stage.name ?? '').trim(),
    };
  }).filter(stage => stage.key && stage.name);
}

function atlasWorkerChatStagePhraseMatchesV1(text: unknown, phrase: unknown): boolean {
  const normalizedText = ` ${normalizeAtlasWorkerContextChatStageTextV1(text)} `;
  const normalizedPhrase = normalizeAtlasWorkerContextChatStageTextV1(phrase);
  return Boolean(normalizedPhrase && normalizedText.includes(` ${normalizedPhrase} `));
}

/** Resolve explicit stage names/keys, keeping overlapping names ambiguous unless the request directs a destination. */
export function resolveAtlasWorkerContextChatStageMentionV1(
  text: unknown,
  stages: readonly unknown[],
): { status: 'none' | 'ambiguous' | 'matched'; stage: AtlasWorkerContextChatStageV1 | null; matches?: AtlasWorkerContextChatStageV1[] } {
  const rows = normalizeAtlasWorkerContextChatStagesV1(stages);
  const matches = rows.filter(stage =>
    atlasWorkerChatStagePhraseMatchesV1(text, stage.name) || atlasWorkerChatStagePhraseMatchesV1(text, stage.key));
  if (!matches.length) return { status: 'none', stage: null };
  const normalizedText = ` ${normalizeAtlasWorkerContextChatStageTextV1(text)} `;
  const directed = matches.filter(stage => [stage.name, stage.key].map(normalizeAtlasWorkerContextChatStageTextV1).filter(Boolean).some(phrase => {
    const index = normalizedText.indexOf(` ${phrase} `);
    if (index < 0) return false;
    const prefix = normalizedText.slice(Math.max(0, index - 110), index);
    return /\b(?:na|em|para a|para) etapa\s*$/.test(prefix) ||
      /\betapa(?:\s+(?:explicitamente|solicitada|pedida|correta|de destino|alvo|indicada|selecionada)){0,3}\s+(?:e|:)\s*$/.test(prefix);
  }));
  const candidates = directed.length ? directed : matches;
  const mostSpecific = candidates.filter(stage => {
    const variants = [stage.name, stage.key].map(normalizeAtlasWorkerContextChatStageTextV1).filter(Boolean);
    return !candidates.some(other => other !== stage &&
      [other.name, other.key].map(normalizeAtlasWorkerContextChatStageTextV1).filter(Boolean).some(otherPhrase =>
        variants.some(phrase => otherPhrase.length > phrase.length && otherPhrase.includes(phrase))));
  });
  if (mostSpecific.length !== 1) return { status: 'ambiguous', stage: null, matches: mostSpecific };
  return { status: 'matched', stage: mostSpecific[0] };
}

function resolveAtlasWorkerContextChatOcrStageV1(item: unknown, stages: readonly unknown[]): AtlasWorkerContextChatStageV1 | null {
  const row = mapRecord(item) || {};
  const source = [row.stageName, row.stageKey].filter(Boolean).join(' ');
  if (!source) return null;
  const match = resolveAtlasWorkerContextChatStageMentionV1(source, stages);
  return match.status === 'matched' ? match.stage : null;
}

/** Resolve request stage from explicit text or OCR; unresolved evidence never inherits active stage. */
export function resolveAtlasWorkerContextChatRequestStageV1(input: {
  message?: unknown;
  recordOcr?: AtlasRecordOcrPayloadV1 | null;
  stages?: readonly unknown[];
  selectedStageKey?: unknown;
} = {}): { stage: AtlasWorkerContextChatStageV1 | null; source: string } {
  const stages = input.stages || [];
  const explicit = resolveAtlasWorkerContextChatStageMentionV1(input.message || '', stages);
  if (explicit.status === 'matched') return { stage: explicit.stage, source: 'user-description' };
  if (explicit.status === 'ambiguous') return { stage: null, source: 'ambiguous-user-description' };
  const items = Array.isArray(input.recordOcr?.items) ? input.recordOcr.items : [];
  const ocrStages = [...new Map(items.map(item => resolveAtlasWorkerContextChatOcrStageV1(item, stages))
    .filter((stage): stage is AtlasWorkerContextChatStageV1 => Boolean(stage)).map(stage => [stage.key, stage])).values()];
  if (ocrStages.length === 1) return { stage: ocrStages[0], source: 'ocr-suggestion' };
  if (ocrStages.length > 1) return { stage: null, source: 'conflicting-ocr-suggestions' };
  if (input.recordOcr) return { stage: null, source: 'unresolved-attachment-stage' };
  const selectedStageKey = String(input.selectedStageKey || '').trim();
  const selected = normalizeAtlasWorkerContextChatStagesV1(stages).find(stage => stage.key === selectedStageKey);
  return selected ? { stage: selected, source: 'selected-stage-fallback' } : { stage: null, source: 'unresolved' };
}

export interface AtlasWorkerContextChatVisualStageResolutionV1 {
  stage: AtlasWorkerContextChatStageV1 | null;
  source: 'user-description' | 'ambiguous-user-description' | 'ocr-suggestion' | 'unresolved-attachment-stage';
}

/** Resolve a single attachment destination. Navigation selection never supplies evidence. */
export function resolveAtlasWorkerContextChatVisualStageV1(input: {
  message?: unknown;
  item?: unknown;
  stages?: readonly unknown[];
  selectedStageKey?: unknown;
} = {}): AtlasWorkerContextChatVisualStageResolutionV1 {
  const stages = input.stages || [];
  const explicit = resolveAtlasWorkerContextChatStageMentionV1(input.message || '', stages);
  if (explicit.status === 'matched') return { stage: explicit.stage, source: 'user-description' };
  if (explicit.status === 'ambiguous') return { stage: null, source: 'ambiguous-user-description' };
  const ocrStage = resolveAtlasWorkerContextChatOcrStageV1(input.item, stages);
  if (ocrStage) return { stage: ocrStage, source: 'ocr-suggestion' };
  return { stage: null, source: 'unresolved-attachment-stage' };
}

export interface AtlasWorkerContextChatRecordInterpretationV1 {
  source: 'chat-attachment-ocr';
  userDescription: string;
  explicitStage: { key: string; name: string } | null;
  stageMentionStatus: 'none' | 'ambiguous' | 'matched';
  selectedStage: { key: string; name: string; role: 'navigation-context-only' } | null;
  stageCandidates: Record<string, unknown>[];
  documentType: string;
  ocrConfidence: unknown;
  ocrReviewRequired: boolean;
  ocrError: string;
  serviceEvidence: Record<string, string> | null;
  properties: Record<string, unknown>[];
  items: Record<string, unknown>[];
}

interface AtlasWorkerContextChatPresentationCatalogV1 {
  clarification: {
    stage: string;
    serviceAction: string;
  };
}

const workerContextChatPresentationV1: AtlasWorkerContextChatPresentationCatalogV1 = workerContextChatPresentationData;

/** Select the user clarification needed for an OCR result without creating a record. */
export function projectAtlasWorkerContextChatVisualClarificationV1(
  ocr: AtlasRecordOcrPayloadV1 | null | undefined,
): string {
  const evidence = mapRecord(ocr?.serviceEvidence) || {};
  const hasAction = Boolean(String(evidence.actionDescription || '').trim() ||
    (Array.isArray(ocr?.items) ? ocr.items : []).some(item =>
      /servi[cç]|service|labor/.test(String(item?.itemKind || item?.type || '').toLocaleLowerCase('pt-BR')) &&
      String(item?.activityName || item?.description || '').trim()
    ));
  return String(ocr?.documentType || '') === 'service_evidence' && !hasAction
    ? workerContextChatPresentationV1.clarification.serviceAction
    : workerContextChatPresentationV1.clarification.stage;
}

/** Build the typed, bounded context sent with an attachment inference request. */
export function buildAtlasWorkerContextChatRecordInterpretationV1(input: {
  message?: unknown;
  stages?: readonly unknown[];
  selectedStageKey?: unknown;
  recordOcr?: AtlasRecordOcrPayloadV1 | null;
} = {}): AtlasWorkerContextChatRecordInterpretationV1 {
  const rows = normalizeAtlasWorkerContextChatStagesV1(input.stages || []);
  const selectedStageKey = String(input.selectedStageKey || '').trim();
  const selected = rows.find(stage => stage.key === selectedStageKey) || null;
  const explicit = resolveAtlasWorkerContextChatStageMentionV1(input.message || '', rows);
  const recordOcr = input.recordOcr || null;
  const stageCandidate = (stage: AtlasWorkerContextChatStageV1): Record<string, unknown> => {
    const profile = (mapRecord(stage.executionProfile) || mapRecord(stage.aiConfig) || {}) as AtlasWorkerContextChatStageProfileV1;
    const list = (value: unknown): string[] => (Array.isArray(value) ? value : [])
      .map(item => {
        if (typeof item === 'string') return item;
        const row = mapRecord(item) || {};
        return [row.name, row.title, row.description].filter(Boolean).join(': ');
      })
      .map(item => String(item || '').trim().slice(0, 240))
      .filter(Boolean)
      .slice(0, 10);
    return {
      key: stage.key,
      name: stage.name,
      executionDescription: String(stage.description || profile.typicalDescription || profile.executionDescription || '').trim().slice(0, 700),
      activityHints: [...list(stage.activityHints), ...list(profile.requestHints), ...list(profile.evidenceFocus)],
      activities: (Array.isArray(stage.activities) ? stage.activities : []).slice(0, 12).map(value => {
        const activity = mapRecord(value) || {};
        return {
          id: String(activity.id || activity.key || ''),
          name: String(activity.name || activity.title || '').slice(0, 180),
          description: String(activity.description || activity.details || '').slice(0, 300),
        };
      }).filter(activity => activity.name || activity.description),
      materials: list(stage.materials),
    };
  };
  const items = Array.isArray(recordOcr?.items) ? recordOcr.items.slice(0, 30).map(item => ({
    itemKind: String(item?.itemKind || item?.type || 'outro'),
    materialId: String(item?.materialId || ''),
    materialName: String(item?.materialName || ''),
    description: String(item?.description || item?.name || ''),
    quantity: item?.quantity ?? null,
    unit: String(item?.unit || ''),
    stageKey: String(item?.stageKey || ''),
    stageName: String(item?.stageName || ''),
    activityId: String(item?.activityId || ''),
    activityName: String(item?.activityName || ''),
    details: String(item?.details || ''),
    pointer: String(item?.pointer || ''),
    confidence: item?.confidence ?? null,
  })) : [];
  const properties = Array.isArray(recordOcr?.properties) ? recordOcr.properties.slice(0, 24).map(property => ({
    key: String(property?.key || ''),
    label: String(property?.label || ''),
    value: property?.value ?? '',
  })) : [];
  const evidence = mapRecord(recordOcr?.serviceEvidence);

  return {
    source: 'chat-attachment-ocr',
    userDescription: String(input.message || '').trim().slice(0, 2000),
    explicitStage: explicit.status === 'matched' && explicit.stage
      ? { key: explicit.stage.key, name: explicit.stage.name } : null,
    stageMentionStatus: explicit.status,
    selectedStage: selected ? { key: selected.key, name: selected.name, role: 'navigation-context-only' } : null,
    stageCandidates: rows.slice(0, 40).map(stageCandidate),
    documentType: String(recordOcr?.documentType || 'unknown'),
    ocrConfidence: recordOcr?.confidence ?? null,
    ocrReviewRequired: recordOcr?.reviewRequired !== false,
    ocrError: String(recordOcr?.error || ''),
    serviceEvidence: evidence ? {
      actionDescription: String(evidence.actionDescription || ''),
      visualDescription: String(evidence.visualDescription || ''),
      observedDate: String(evidence.observedDate || ''),
      observedTime: String(evidence.observedTime || ''),
      stageKey: String(evidence.stageKey || ''),
      stageName: String(evidence.stageName || ''),
      activityId: String(evidence.activityId || ''),
      activityName: String(evidence.activityName || ''),
    } : null,
    properties,
    items,
  };
}

export interface AtlasWorkerContextChatVisualAllocationInputV1 {
  reply: Record<string, unknown> | null | undefined;
  message?: unknown;
  stages?: readonly unknown[];
  applicationState?: Record<string, unknown>;
}

export type AtlasWorkerContextChatVisualAllocationTargetV1 = 'material' | 'service' | 'office';

/** Arguments accepted by the existing visual-record allocation command. */
export interface AtlasWorkerContextChatVisualAllocationArgumentsV1 extends Record<string, unknown> {
  target: AtlasWorkerContextChatVisualAllocationTargetV1;
  stageKey: string;
  stageName: string;
  activityId: string;
  activityName: string;
  materialName: string;
  quantity?: number | string | null;
  unit: string;
  details: string;
  pointer: string;
  confidence?: number | null;
}

export interface AtlasWorkerContextChatVisualAllocationToolCallV1 extends AtlasWorkerContextChatToolCallV1 {
  name: 'stage.allocate_visual_record';
  arguments: AtlasWorkerContextChatVisualAllocationArgumentsV1;
}

/** Normalize the model's allocation arguments before they reach persistence. */
export function normalizeAtlasWorkerContextChatVisualAllocationArgumentsV1(
  value: unknown,
): AtlasWorkerContextChatVisualAllocationArgumentsV1 {
  const input = mapRecord(value) || {};
  const text = (key: string): string => {
    const field = input[key];
    return typeof field === 'string' || typeof field === 'number' ? String(field).trim() : '';
  };
  const rawTarget = input.target;
  const target: AtlasWorkerContextChatVisualAllocationTargetV1 = rawTarget === 'office'
    ? 'office' : rawTarget === 'material' ? 'material' : 'service';
  const rawQuantity = input.quantity;
  const quantity = rawQuantity == null || rawQuantity === ''
    ? null
    : typeof rawQuantity === 'number' || typeof rawQuantity === 'string' ? rawQuantity : null;
  const rawConfidence = input.confidence;
  const confidenceValue = rawConfidence == null || rawConfidence === '' ? Number.NaN : Number(rawConfidence);
  return {
    target,
    stageKey: text('stageKey'),
    stageName: text('stageName'),
    activityId: text('activityId'),
    activityName: text('activityName'),
    materialName: text('materialName'),
    ...(quantity === null ? {} : { quantity }),
    unit: text('unit'),
    details: text('details'),
    pointer: text('pointer'),
    ...(Number.isFinite(confidenceValue) ? { confidence: confidenceValue } : {}),
  };
}

/** Convert reviewed OCR/model evidence into explicit stage/activity allocation calls. */
export function projectAtlasWorkerContextChatVisualAllocationCallsV1(
  input: AtlasWorkerContextChatVisualAllocationInputV1,
): AtlasWorkerContextChatVisualAllocationToolCallV1[] {
  const reply = input.reply || {};
  const ocr = mapRecord(reply.recordOcr) as AtlasRecordOcrPayloadV1 | null;
  if (ocr?.error) return [];
  const items: AtlasRecordOcrItemV1[] = Array.isArray(ocr?.items) ? ocr.items : [];
  const message = String(input.message || '');
  const suppliedStages=input.stages||[];
  const destinationCatalog=(stageDestinationsCatalogData as {destinations?:Array<{key?:string;name?:string;description?:string}>}).destinations||[];
  const stages:Record<string,unknown>[]=[...suppliedStages.map(value=>mapRecord(value)||{}),...destinationCatalog.filter(destination=>!suppliedStages.some(value=>String((mapRecord(value)||{}).key||'')===String(destination.key||''))).map(destination=>({
    key:String(destination.key||''),name:String(destination.name||''),description:String(destination.description||''),activities:[],materials:[],unit:'registro administrativo'
  }))];
  const describedServiceAction = String(message.match(/\bAção de serviço\s*:\s*([^\n.!?]+)/i)?.[1] || '').trim();
  const provided = (Array.isArray(reply.toolCalls) ? reply.toolCalls : [])
    .map(call => mapRecord(call))
    .filter((call): call is Record<string, unknown> => Boolean(call && call.name === 'stage.allocate_visual_record'));
  const explicit = resolveAtlasWorkerContextChatStageMentionV1(message, stages);
  const explicitStage = explicit.status === 'matched' ? explicit.stage : null;
  const serviceEvidence = mapRecord(ocr?.serviceEvidence) || {};
  const normalize = normalizeAtlasWorkerContextChatStageTextV1;
  const isStageOnlyName = (value: unknown): boolean => Boolean(explicitStage && normalize(value) === normalize(explicitStage.name));
  const proposalAt = (index: number): Record<string, unknown> => {
    const current = provided[index];
    const first = provided[0];
    return mapRecord(current?.arguments) || mapRecord(current?.args) || mapRecord(first?.arguments) || mapRecord(first?.args) || {};
  };
  const purchaseDocument = ['purchase_invoice', 'purchase_receipt'].includes(String(ocr?.documentType || ''));
  const usableItems = items.filter((item, index) => {
    const description = String(item?.description || item?.name || item?.materialName || item?.materialId || '').trim();
    const confidence = Number(item?.confidence ?? ocr?.confidence);
    const proposedArgs = proposalAt(index);
    const kind = String(item?.itemKind || item?.type || proposedArgs.target || (purchaseDocument ? 'material' : ''))
      .toLocaleLowerCase('pt-BR');
    const service = /servi[cç]|atividade|labor|m[aã]o de obra/.test(kind);
    return description.length >= 3 && !/^item\s+ocr\s+\d+$/i.test(description) &&
      Number.isFinite(confidence) && confidence >= 0 &&
      /^(material|materiais|servico|serviço|serviços|servicos|service|labor|m[aã]o de obra)$/.test(kind) &&
      !(service && isStageOnlyName(description));
  });
  const ocrVisualActionCandidate = String(serviceEvidence.actionDescription || '').trim();
  const ocrVisualAction = isStageOnlyName(ocrVisualActionCandidate) ? '' : ocrVisualActionCandidate;
  const modelServiceCall = String(ocr?.documentType || '') === 'service_evidence' && explicitStage
    ? provided.map(call => mapRecord(call.arguments) || mapRecord(call.args) || {}).find(args => {
      const target = String(args.target || '').toLocaleLowerCase('pt-BR');
      const modelStage = resolveAtlasWorkerContextChatStageMentionV1(`${args.stageName || ''} ${args.stageKey || ''}`, stages);
      return target === 'service' && String(args.activityName || '').trim().length >= 3 && !isStageOnlyName(args.activityName) &&
        modelStage.status === 'matched' && modelStage.stage?.key === explicitStage.key;
    }) || null
    : null;
  const allocationItems: Record<string, unknown>[] = usableItems.length
    ? usableItems
    : String(ocr?.documentType || '') === 'service_evidence' && ocrVisualAction
      ? [{ itemKind: 'servico', description: ocrVisualAction, activityName: String(serviceEvidence.activityName || ocrVisualAction), details: ocrVisualAction, confidence: serviceEvidence.confidence ?? ocr?.confidence }]
      : String(ocr?.documentType || '') === 'service_evidence' && modelServiceCall
        ? [{ itemKind: 'servico', description: modelServiceCall.activityName, activityName: modelServiceCall.activityName, details: modelServiceCall.details || '', pointer: modelServiceCall.pointer || '', confidence: modelServiceCall.confidence }]
        : String(ocr?.documentType || '') === 'service_evidence' && describedServiceAction
          ? [{ itemKind: 'servico', description: describedServiceAction, confidence: 0 }]
          : [];
  if (!allocationItems.length || explicit.status === 'ambiguous' && !allocationItems.some(item=>String(item?.destinationHint||'')==='office'||String(item?.stageKey||'').toLowerCase()==='office')) return [];
  const applicationState = input.applicationState || {};
  const includesPhrase = (text: unknown, phrase: unknown): boolean => {
    const normalizedText = ` ${normalize(text)} `;
    const normalizedPhrase = normalize(phrase);
    return Boolean(normalizedPhrase && normalizedText.includes(` ${normalizedPhrase} `));
  };
  const stageRows = normalizeAtlasWorkerContextChatStagesV1(stages);
  const existingMaterials = [
    ...stageRows.flatMap(stage => Array.isArray(stage.materials) ? stage.materials : []),
    ...(Array.isArray(applicationState.materialCatalogAdditions)
      ? applicationState.materialCatalogAdditions.map(value => {
        const item = mapRecord(value) || {};
        return item.name || item.materialName || '';
      }) : []),
    ...(Array.isArray(applicationState.records) ? applicationState.records.flatMap(value => {
      const record = mapRecord(value) || {};
      return (Array.isArray(record.properties) ? record.properties : [])
        .map(propertyValue => mapRecord(propertyValue) || {})
        .filter(property => ['allocation_material', 'material_name'].includes(String(property.id || property.key || '')))
        .map(property => property.value || '');
    }) : []),
  ].map(value => String(value || '').trim()).filter(Boolean);
  const explicitlyRequestedMaterial = [...new Set(existingMaterials)].find(name => includesPhrase(message, name));
  return allocationItems.map((item, index): AtlasWorkerContextChatVisualAllocationToolCallV1 | null => {
    const args = proposalAt(index);
    const kind = String(item?.itemKind || item?.type || args.target || (purchaseDocument ? 'material' : ''))
      .toLocaleLowerCase('pt-BR');
    const description = String(item?.description || item?.name || item?.materialName || item?.materialId || `Item OCR ${index + 1}`).trim();
    const officeDestination=String(item?.destinationHint||'')==='office'||String(item?.stageKey||'').toLowerCase()==='office';
    const target: AtlasWorkerContextChatVisualAllocationTargetV1 = officeDestination?'office':/servi[cç]|atividade|m[aã]o de obra/.test(kind)?'service':'material';
    const itemStageMatch = resolveAtlasWorkerContextChatStageMentionV1(
      [item?.stageName, item?.stageKey].filter(Boolean).join(' '), stages,
    );
    const ocrStage = itemStageMatch.status === 'matched' ? itemStageMatch.stage : null;
    const modelStage = resolveAtlasWorkerContextChatStageMentionV1(`${args.stageName || ''} ${args.stageKey || ''}`, stages);
    const officeStage=officeDestination?stages.find(candidate=>String((mapRecord(candidate)||{}).key||'').toLowerCase()==='office')||null:null;
    const stage = officeStage || explicitStage || ocrStage || (modelStage.status === 'matched' ? modelStage.stage : null);
    if (!stage) return null;
    const stageRow = stageRows.find(candidate => candidate.key === stage.key) || stage;
    const activities: AtlasWorkerContextChatStageActivityV1[] = (Array.isArray(stageRow.activities) ? stageRow.activities : [])
      .map(value => mapRecord(value))
      .filter((activity): activity is Record<string, unknown> => Boolean(activity));
    const requestedActivityId = String(item?.activityId || args.activityId || '').trim();
    const activityMention = String(message.match(/\batividade\s+([^.;,]+)/i)?.[1] || '').trim();
    const requestedActivityCandidate = String(target==='office'?description:activityMention || (target === 'service' ? args.activityName : '') || item?.activityName || serviceEvidence.activityName || args.activityName || '').trim();
    const requestedActivityName = isStageOnlyName(requestedActivityCandidate) ? '' : requestedActivityCandidate;
    const explicitActivity = activities.find(activity => includesPhrase(message, activity?.name || activity?.title));
    const canonicalActivity = explicitActivity || activities.find(activity => requestedActivityId && String(activity?.id || activity?.key || '') === requestedActivityId) ||
      activities.find(activity => requestedActivityName && normalize(activity?.name || activity?.title) === normalize(requestedActivityName)) || null;
    const serviceWhen = [serviceEvidence.observedDate && `Data informada/visível: ${serviceEvidence.observedDate}`, serviceEvidence.observedTime && `Hora informada/visível: ${serviceEvidence.observedTime}`].filter(Boolean).join(' · ');
    const personDescription = target === 'service' && message && !/^\s*(?:etapa|stage)\s*:/i.test(message)
      ? `Descrição enviada pela pessoa: ${message}`
      : '';
    const stageHint = target === 'service' && explicitStage ? `Etapa indicada pela pessoa: ${stage.name}` : '';
    const invoiceFacts=purchaseDocument?[
      ocr?.supplier&&`Fornecedor: ${String(ocr.supplier)}`,
      ocr?.invoiceNumber&&`Nota fiscal: ${String(ocr.invoiceNumber)}`,
      ocr?.issueDate&&`Emissão: ${String(ocr.issueDate)}`,
      Number(ocr?.totalAmountCents)>0&&`Total da nota: ${(Number(ocr?.totalAmountCents)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}`,
      ocr?.accessKey&&`Chave de acesso: ${String(ocr.accessKey)}`,
    ]:[];
    const details = [item?.details,...invoiceFacts,personDescription,stageHint,target === 'service' && serviceWhen].filter(Boolean).join('\n');
    const confidence = [item?.confidence, ocr?.confidence, args.confidence]
      .map(Number).find(value => Number.isFinite(value) && value > 0);
    return {
      name: 'stage.allocate_visual_record',
      arguments: normalizeAtlasWorkerContextChatVisualAllocationArgumentsV1({
        target,
        stageKey: String(stage.key),
        stageName: stage.name,
        activityId: String(canonicalActivity?.id || canonicalActivity?.key || ''),
        activityName: String(target==='office'?description:canonicalActivity?.name || canonicalActivity?.title || requestedActivityName || (target === 'service' ? serviceEvidence.actionDescription : '') || (target === 'service' ? description : 'Leitura de material')),
        materialName: target === 'material' ? String(explicitlyRequestedMaterial || item?.materialName || description || args.materialName || '') : target==='office'?description:'',
        ...(item?.quantity == null && args.quantity == null ? {} : { quantity: item?.quantity ?? args.quantity }),
        unit: String(args.unit || (target === 'material' ? item?.unit || stage.unit || 'un.' : target==='office'?'registro administrativo':'registro')),
        details: String(details || args.details || 'Item identificado no anexo pelo OCR.'),
        pointer: String(target === 'material' ? description : item?.pointer || item?.description || description),
        ...(confidence == null ? {} : { confidence }),
      }),
    };
  }).filter((call): call is AtlasWorkerContextChatVisualAllocationToolCallV1 => call !== null);
}

