/** Resolve the OCR record for its attachment and project the authorized review destination. */
export function projectAtlasWorkerContextChatRecordReviewCommandV1(
  input: AtlasWorkerContextChatRecordReviewInputV1,
): AtlasWorkerContextChatRecordReviewCommandV1 {
  const state = input?.appState || {};
  const records = (Array.isArray(state.records) ? state.records : [])
    .map(record => mapRecord(record))
    .filter((record): record is Record<string, unknown> => Boolean(record));
  const attachmentName = String(input?.draft?.attachmentRef?.name || '').trim();
  const visualRecords = records.filter(record => record?.source === 'chat-visual');
  const record = [...visualRecords].reverse().find(candidate => {
    if (!attachmentName) return true;
    return (Array.isArray(candidate.attachments) ? candidate.attachments : []).some(value => {
      const attachment = mapRecord(value) || {};
      return [attachment.name, attachment.fileName, attachment.label]
        .some(value => String(value || '').trim() === attachmentName);
    });
  }) || [...visualRecords].reverse()[0];
  if (!record) return { kind: 'missing-record', collapseAssistant: false };
  const recordId = String(record.id || '');

  if (input.limitedActor) {
    return {
      kind: 'open-record',
      record,
      storePatch: {
        view: 'records',
        selectedRecordV5360: record.id,
        lastAction: 'Abriu registro visual do próprio perfil para revisão',
      },
      collapseAssistant: true,
    };
  }

  const target = record.allocationTarget === 'material' ? 'material' : 'service';
  const itemKey = target === 'material' ? `material:AI-MATERIAL-${recordId}` : `service:${recordId}`;
  return {
    kind: 'open-allocation',
    record,
    itemKey,
    storePatch: {
      view: 'agenda',
      selectedAgendaEventV3: `agenda-record-${recordId}`,
      selectedStageV9: record.stageKey || state.selectedStageV9 || state.selectedStage || '',
      selectedStage: record.stageKey || state.selectedStage || state.selectedStageV9 || '',
      stageSelected: true,
      activityDedicated: false,
      stageActivityDedicatedV9: false,
      controlStageCenterTab: target === 'material' ? 'materials' : 'services',
      controlStageCenterItemModalKey: itemKey,
      lastAction: 'Abriu a alocação OCR do chat para revisão humana',
    },
    collapseAssistant: false,
  };
}

/** Resolve the OCR review destination and apply its navigation patch to the active store. */
export function applyAtlasWorkerContextChatRecordReviewFlowV1(input: {
  draft: AtlasWorkerContextChatRecordReviewInputV1['draft'];
  store: AtlasWorkerContextChatRecordReviewStoreV1;
  ports?: Partial<AtlasWorkerContextChatRecordReviewPortsV1>;
}): AtlasWorkerContextChatRecordReviewCommandV1 {
  const appState = input.store.get() || {};
  const command = projectAtlasWorkerContextChatRecordReviewCommandV1({
    draft: input.draft,
    appState,
    limitedActor: isAtlasLimitedOperationalActorV1(appState.currentActor || {}),
  });
  if (command.kind === 'missing-record') {
    input.ports?.setStatus?.('A leitura foi preservada, mas ainda falta a etapa para alocar o item.');
    return command;
  }
  if (!command.storePatch) return command;
  input.store.set(command.storePatch);
  if (command.collapseAssistant) input.ports?.setCollapsed?.(true);
  if (command.itemKey) input.ports?.openItem?.(command.itemKey);
  input.ports?.clearDraft?.();
  input.ports?.render?.();
  return command;
}

/** Compatibility name for older callers; the program flow owns the full command. */
export function applyAtlasWorkerContextChatRecordReviewV1(input: {
  draft: AtlasWorkerContextChatRecordReviewInputV1['draft'];
  store: AtlasWorkerContextChatRecordReviewStoreV1;
  ports?: Partial<AtlasWorkerContextChatRecordReviewPortsV1>;
}): AtlasWorkerContextChatRecordReviewCommandV1 {
  return applyAtlasWorkerContextChatRecordReviewFlowV1(input);
}

