/** Compose the Worker chat's typed context policy with its DOM observation owner. */
export function installAtlasWorkerContextChatObservationProgramV1(input: {
  host: AtlasWorkerContextChatObservationProgramHostV1;
  root: HTMLElement;
  route: string;
  routeStorageKey: string;
  pathname(): string;
  readContext(): Record<string, unknown>;
  labelForPath(pathname: string): string;
  componentOwners: AtlasWorkerContextChatObservationComponentsV1;
  voiceEnabled(): boolean;
  speak(message: string): void;
}): (() => void) | null {
  const install = input?.componentOwners?.installAtlasWorkerContextChatObservationV1;
  if (!input?.root || typeof install !== 'function') return null;
  return install({
    host: input.host,
    root: input.root,
    route: input.route,
    routeStorageKey: input.routeStorageKey,
    pathname: input.pathname,
    readContext: input.readContext,
    labelForPath: input.labelForPath,
    projectEventMessage: projectAtlasWorkerContextChatObservationEventMessageV1,
    projectContextMessages: (previous, current) => projectAtlasWorkerContextChatObservationMessagesV1(
      previous as Partial<AtlasWorkerContextChatOperationalContextV1>,
      current as Partial<AtlasWorkerContextChatOperationalContextV1>,
    ),
    voiceEnabled: input.voiceEnabled,
    speak: input.speak,
  });
}

