export function projectAtlasWorkerContextChatStatusLabelV1(status: unknown): string {
  const value = String(status || '');
  return ({ triage: 'Em triagem', planned: 'Planejada', in_progress: 'Em execução', waiting_files: 'Aguardando arquivos', completed: 'Concluída', cancelled: 'Cancelada' } as Record<string, string>)[value] || value;
}

/** Run the Worker chat submission flow through typed policies and injected effects. */
export async function submitAtlasWorkerContextChatMessageV1(
  input: AtlasWorkerContextChatSubmitInputV1,
  ports: AtlasWorkerContextChatSubmitPortsV1,
): Promise<void> {
  for (const [name, value] of Object.entries({
    isPending: ports?.isPending,
    setPending: ports?.setPending,
    getApplicationState: ports?.getApplicationState,
    getContext: ports?.getContext,
    pathname: ports?.pathname,
    parseLotStatusCommand: ports?.parseLotStatusCommand,
    applyLotStatusCommand: ports?.applyLotStatusCommand,
    serviceRequestId: ports?.serviceRequestId,
    refreshServiceRequest: ports?.refreshServiceRequest,
    getCurrentRequest: ports?.getCurrentRequest,
    ask: ports?.ask,
    createServiceRequest: ports?.createServiceRequest,
    executeToolCalls: ports?.executeToolCalls,
    getRecordDraft: ports?.getRecordDraft,
    setRecordDraft: ports?.setRecordDraft,
    visualClarification: ports?.visualClarification,
    addAssistant: ports?.addAssistant,
    setStatus: ports?.setStatus,
    restoreComposer: ports?.restoreComposer,
    voiceEnabled: ports?.voiceEnabled,
    speak: ports?.speak,
    now: ports?.now,
  })) if (typeof value !== 'function') throw new TypeError(`Worker chat submit requires ${name}().`);
  if (ports.isPending()) return;

  const text = String(input.text || '');
  const attachment = input.attachment || null;
  const files = Array.isArray(input.files) ? input.files : [];
  const options = input.options || {};
  const directOperational = options.mode === 'priority';
  const pendingLabel = directOperational ? 'Executando prioridade operacional…'
    : isAtlasWorkerContextChatServiceRequestV1(text) ? 'Registrando solicitação e arquivos…'
      : 'Consultando o assistente…';
  ports.setPending(true, pendingLabel);

  try {
    ports.setRecordDraft(null);
    const lotCommand = !attachment && !files.length ? ports.parseLotStatusCommand(text) : null;
    if (lotCommand) {
      const answer = lotCommand.error ? String(lotCommand.error)
          : !ports.pathname().startsWith('/admin') || !ports.getApplicationState()
          ? 'A alteração de status está disponível apenas no painel administrativo.'
          : ports.applyLotStatusCommand(lotCommand);
      ports.addAssistant(answer, { audit: lotCommand.error ? 'Comando de lote não executado' : 'Controle do lote' });
      ports.setStatus(lotCommand.error ? 'Nenhuma alteração foi feita.' : answer);
      return;
    }

    const explicitAgenda = !attachment && !files.length && /\b(crie|criar|agende|agendar|adicione|adicionar)\b/i.test(text) && /\b(compromisso|agenda|calend[aá]rio)\b/i.test(text);
    if (explicitAgenda) {
      const context = ports.getContext();
      const stageMatch = resolveAtlasWorkerContextChatStageMentionV1(text, context.stages || []);
      const title = String(text.match(/(?:chamad[oa]|t[ií]tulo)\s+["“]?([^"”,.;\n]+?)(?=["”]|,\s*(?:na|no|em)\b|$)/i)?.[1] || '').trim();
      if (stageMatch.status !== 'matched' || !stageMatch.stage || !title) {
        ports.addAssistant('Para criar o compromisso, informe um título e uma etapa sem ambiguidade.');
        ports.setStatus('Nenhum compromisso foi criado.');
        return;
      }
      const tomorrow = /amanh[ãa]/i.test(text);
      const date = ports.now();
      if (tomorrow) date.setDate(date.getDate() + 1);
      const writtenDate = text.match(/\b(\d{2})\/(\d{2})\/(\d{4})\b/);
      const isoDate = writtenDate ? `${writtenDate[3]}-${writtenDate[2]}-${writtenDate[1]}`
        : tomorrow ? `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` : '';
      const start = text.match(/\b(?:[01]?\d|2[0-3]):[0-5]\d\b/)?.[0] || '';
      const materialName = String(text.match(/\bmaterial(?:\s+necess[aá]rio)?\s*:?\s+([^,.;\n]+)/i)?.[1] || '').trim();
      const results = await ports.executeToolCalls([{ name: 'agenda.create_pending', arguments: {
        title,
        stageKey: stageMatch.stage.key,
        stageName: stageMatch.stage.name,
        activityName: String(text.match(/atividade\s+([^,.;\n]+)/i)?.[1] || title).trim(),
        date: isoDate,
        start,
        durationHours: Number(text.match(/(?:por|dura[cç][aã]o\s+de)\s+(\d+(?:[.,]\d+)?)\s*horas?/i)?.[1]?.replace(',', '.') || 1),
        notes: 'Compromisso solicitado pelo chat; confirme os detalhes antes da execução.',
        materialIds: materialName ? [materialName] : [],
      } }]);
      const answer = results.join(' ') || 'Não foi possível criar o compromisso.';
      ports.addAssistant(answer);
      ports.setStatus(answer);
      return;
    }

    const serviceRequestId = ports.serviceRequestId();
    if (!directOperational && /\b(estado|status|andamento)\b/i.test(text) && /\b(solicita[cç][aã]o|pedido|servi[cç]o)\b/i.test(text) && serviceRequestId) {
      await ports.refreshServiceRequest();
      const request = ports.getCurrentRequest();
      ports.addAssistant(request
        ? `Solicitação ${request.id}: ${projectAtlasWorkerContextChatStatusLabelV1(request.status)}. ${(request.files || []).length} arquivo(s) vinculado(s).`
        : 'Não foi possível consultar a solicitação agora.');
      ports.setStatus('Acompanhamento consultado.');
      return;
    }

    const context = ports.getContext();
    const stageOnlyVisualSubmission = Boolean(attachment &&
      !/^(qual|quais|como|quando|onde|por que|o que|me explique|explique)\b/i.test(text.trim()) &&
      resolveAtlasWorkerContextChatStageMentionV1(text, context.stages || []).status === 'matched');
    const agendaIntent = /\b(agenda|compromisso|calend[aá]rio|hor[aá]rio)\b/i.test(text);
    if (!directOperational && ((isAtlasWorkerContextChatServiceRequestV1(text) && !agendaIntent) || stageOnlyVisualSubmission)) {
      const isInvoicePdf = Boolean(attachment && (
        String(attachment.mimeType || '').toLowerCase() === 'application/pdf' || /\.pdf$/i.test(String(attachment.name || ''))
      ));
      try {
        const shouldReadAttachment = Boolean(attachment && (stageOnlyVisualSubmission || /\b(nota|comprovante|registro|ocr|foto|imagem|anexo)\b/i.test(text)));
        const reply = shouldReadAttachment ? await ports.ask(text, attachment, options) : null;
        const attachmentOcr = reply?.recordOcr;
        const expectsAllocation = Boolean(attachmentOcr && !attachmentOcr.error && (
          (Array.isArray(attachmentOcr.items) && attachmentOcr.items.length) ||
          ['service_evidence', 'purchase_invoice', 'purchase_receipt'].includes(String(attachmentOcr.documentType || ''))
        ));
        const visualCalls = reply && shouldReadAttachment
          ? projectAtlasWorkerContextChatVisualAllocationCallsV1({ reply, message: text, stages: context.stages, applicationState: ports.getApplicationState() || {} })
          : [];
        if (shouldReadAttachment && expectsAllocation && !visualCalls.length) {
          ports.setRecordDraft({ ocr: attachmentOcr, attachmentRef: reply?.attachment, requestId: null, dataUrl: attachment?.dataUrl });
          ports.addAssistant(workerContextChatPresentationV1.clarification.stage);
          ports.setStatus('Nenhuma solicitação ou alocação foi criada; falta confirmar a etapa/atividade.');
          return;
        }
        if (isInvoicePdf && shouldReadAttachment) {
          if (!attachmentOcr || attachmentOcr.error) {
            if (reply?.source === 'error') ports.restoreComposer(text, attachment, files);
            ports.addAssistant(String(attachmentOcr?.error || reply?.text || 'Não foi possível ler a nota fiscal anexada.'));
            ports.setStatus('Leitura da nota não concluída; texto e PDF preservados.');
            return;
          }
          ports.setRecordDraft({ ocr: attachmentOcr, attachmentRef: reply?.attachment, requestId: null, dataUrl: attachment?.dataUrl });
          ports.addAssistant(String(reply?.text || 'Nota fiscal lida; revise os campos antes de confirmar.'));
          ports.setStatus('Leitura concluída; registrando no destino indicado para revisão humana.');
          const allocationResults = await ports.executeToolCalls(visualCalls, { sourceAttachment: attachment, payload: reply });
          if (allocationResults.length) {
            ports.addAssistant(allocationResults.join('\n'));
            ports.setStatus(allocationResults.some(result => /^Alocou a leitura visual/i.test(String(result)))
              ? 'Leitura persistida; abra o registro para revisão humana.'
              : 'Leitura recebida, mas o registro ainda não foi persistido.');
          } else {
            ports.addAssistant(workerContextChatPresentationV1.clarification.stage);
            ports.setStatus('Leitura preservada; confirme a etapa ou atividade para concluir a alocação.');
          }
          if (ports.voiceEnabled()) ports.speak(String(reply?.text || 'Nota fiscal lida.'));
          return;
        }
        const request = await ports.createServiceRequest(text, files, { recordOcr: reply?.recordOcr || null });
        const answer = `Solicitação ${request.id} recebida em triagem para ${request.domain}. ${(request.files || []).length} arquivo(s) vinculado(s). Acompanhe o estado abaixo; nenhuma alteração operacional foi executada automaticamente.`;
        ports.addAssistant(answer);
        ports.setStatus('Solicitação registrada e aguardando triagem.');
        if (shouldReadAttachment && reply) {
          const recordOcr = reply.recordOcr;
          if (recordOcr && !recordOcr.error) {
            ports.setRecordDraft({ ocr: recordOcr, attachmentRef: reply.attachment, requestId: request.id, dataUrl: attachment?.dataUrl });
            ports.addAssistant(`Solicitação ${request.id} · ${reply.text}`);
            ports.setStatus('Leitura concluída. Revise os campos antes de confirmar o registro.');
            const allocationCalls = projectAtlasWorkerContextChatVisualAllocationCallsV1({ reply, message: text, stages: context.stages, applicationState: ports.getApplicationState() || {} });
            ports.setRecordDraft({ ...ports.getRecordDraft(), allocations: allocationCalls.map(call => call.arguments || call.args || {}) });
            const allocationResults = await ports.executeToolCalls(allocationCalls, { sourceAttachment: attachment, payload: reply, serviceRequest: request });
            if (allocationResults.length) {
              ports.addAssistant(allocationResults.join('\n'));
              ports.setStatus(allocationResults.some(result => /^Alocou a leitura visual/i.test(String(result)))
                ? 'Leitura persistida; abra o registro para revisão humana.'
                : 'Leitura recebida, mas o registro ainda não foi persistido.');
            } else if (attachment && recordOcr.items?.length) {
              ports.addAssistant(workerContextChatPresentationV1.clarification.stage);
              ports.setStatus('Leitura preservada; falta confirmar a etapa ou atividade.');
            }
          } else {
            ports.addAssistant(`Solicitação ${request.id} registrada. ${reply.text}`);
            ports.setStatus('Solicitação preservada; leitura OCR indisponível.');
          }
        }
        if (ports.voiceEnabled()) ports.speak(answer);
      } catch (error) {
        ports.restoreComposer(text, attachment, files);
        ports.addAssistant(`${isInvoicePdf ? 'Não foi possível concluir a leitura/alocação da nota' : 'Não foi possível registrar a solicitação'}: ${error instanceof Error ? error.message : String(error)}`);
        ports.setStatus(isInvoicePdf ? 'Nota não alocada; texto e PDF preservados.' : 'Solicitação não registrada; texto e anexos preservados.');
      }
      return;
    }

    const reply = await ports.ask(text, attachment, options);
    const recordOcr = reply.recordOcr;
    if (recordOcr && !recordOcr.error) ports.setRecordDraft({ ocr: recordOcr, attachmentRef: reply.attachment, requestId: null, dataUrl: attachment?.dataUrl });
    if (reply.source === 'error') ports.restoreComposer(text, attachment, files);
    const actionPlan = projectAtlasWorkerContextChatActionPlanV1({ message: text, directOperational, replyToolCalls: reply.toolCalls });
    const visualCalls = attachment
      ? projectAtlasWorkerContextChatVisualAllocationCallsV1({ reply, message: text, stages: context.stages, applicationState: ports.getApplicationState() || {} })
      : [];
    if (visualCalls.length && ports.getRecordDraft())
      ports.setRecordDraft({ ...ports.getRecordDraft(), allocations: visualCalls.map(call => call.arguments || call.args || {}) });
    const calls = [...visualCalls, ...actionPlan.proposedCalls.filter(call => call.name !== 'stage.allocate_visual_record')];
    const needsStageClarification = Boolean(attachment && Array.isArray(recordOcr?.items) && recordOcr.items.length && !visualCalls.length);
    const needsActionClarification = Boolean(attachment && ports.visualClarification(recordOcr) === workerContextChatPresentationV1.clarification.serviceAction);
    const results = await ports.executeToolCalls(calls, { sourceAttachment: attachment, payload: reply });
    const actionText = results.length ? results.join(' ')
      : needsActionClarification ? workerContextChatPresentationV1.clarification.serviceAction
        : needsStageClarification ? ports.visualClarification(recordOcr) : '';
    const answer = [reply.text, actionText].filter(Boolean).join('\n\n');
    ports.addAssistant(answer, { audit: `${reply.audit}${actionText ? ` · ${actionText}` : ''}` });
    ports.setStatus(actionText || (reply.source === 'endpoint' ? 'Resposta recebida; nenhuma ação na interface.' : 'Endpoint indisponível; nenhuma ação executada.'));
    if (ports.voiceEnabled()) ports.speak(answer);
  } catch (error) {
    ports.restoreComposer(text, attachment, files);
    ports.addAssistant(`Não foi possível concluir: ${error instanceof Error ? error.message : String(error)}`);
    ports.setStatus('Falha no envio. Texto e anexos preservados para tentar novamente.');
  } finally {
    ports.setPending(false);
  }
}

/** Project the persisted worker request payload, preserving stage ambiguity and attachment metadata. */
export function projectAtlasWorkerContextChatServiceRequestV1(
  input: AtlasWorkerContextChatServiceRequestInputV1,
): AtlasWorkerContextChatServiceRequestPayloadV1 {
  const text = String(input.text || '');
  const state = input.applicationState || {};
  const context = input.context || {};
  const selectedStage = mapRecord(state.selectedStage);
  const selectedActivity = mapRecord(state.selectedActivity);
  const selectedStageKey = String(state.selectedStageV9 || selectedStage?.key || state.selectedStage || context.stage || '').trim();
  const stageResolution = resolveAtlasWorkerContextChatRequestStageV1({
    message: text,
    recordOcr: input.recordOcr || null,
    stages: context.stages || [],
    selectedStageKey,
  });
  const stageKey = String(stageResolution.stage?.key || '');
  const stageIsUnresolved = ['ambiguous-user-description','conflicting-ocr-suggestions','unresolved-attachment-stage'].includes(String(stageResolution.source || ''));
  const selectedActivityId = String(selectedActivity?.id || input.routeActivityId || '');
  const activityId = stageKey && stageKey !== selectedStageKey ? '' : selectedActivityId;
  const lower = text.toLocaleLowerCase('pt-BR');
  const domains: ReadonlyArray<readonly [string, RegExp]> = [
    ['obra', /obra|etapa|atividade|cronograma|drenagem|pavimenta/],
    ['suprimentos', /material|compra|fornecedor|estoque/],
    ['documentos', /documento|pdf|dwg|licen[cç]a|projeto/],
    ['comercial', /lead|cliente|reserva|contrato|comiss[aã]o|corretor/],
    ['financeiro', /caixa|pagamento|lan[cç]amento|despesa|financeir/],
    ['relatorios', /relat[oó]rio|indicador|balan[cç]o/],
  ];
  const domain = domains.find(([, pattern]) => pattern.test(lower))?.[0] || String(state.view || 'geral');
  return {
    title: text.trim().slice(0, 140),
    description: text.trim(),
    domain,
    stageKey: stageIsUnresolved ? '' : stageKey || selectedStageKey,
    activityId: stageIsUnresolved ? '' : activityId,
    files: (input.files || []).map(file => ({ fileName: file.name, dataUrl: file.dataUrl })),
  };
}

/** Persist a worker service request and refresh the selected request list through authenticated ports. */
export async function createAtlasWorkerContextChatServiceRequestV1(
  input: AtlasWorkerContextChatServiceRequestInputV1,
  ports: AtlasWorkerContextChatServiceRequestPortsV1,
): Promise<AtlasWorkerContextChatServiceRequestV1> {
  const response = await ports.apiFetch('/api/service-requests', {
    method: 'POST', cache: 'no-store', headers: { 'content-type': 'application/json' },
    body: JSON.stringify(projectAtlasWorkerContextChatServiceRequestV1(input)),
  });
  const payload = mapRecord(await response.json().catch(() => null)) as AtlasWorkerContextChatServiceRequestEnvelopeV1 | null;
  const request = projectAtlasWorkerContextChatServiceRequestRecordV1(payload?.request);
  if (!response.ok || !request) throw new Error(String(payload?.error || `HTTP ${response.status}`));
  ports.setChatState({ currentRequest: request });
  ports.storageSet(input.serviceKey, request.id);
  await refreshAtlasWorkerContextChatServiceRequestsV1(input.serviceKey, ports);
  const current = ports.getChatState();
  ports.setChatState({
    currentRequest: request,
    requests: [request, ...current.requests.filter(item => item.id !== request.id)],
  });
  ports.storageSet(input.serviceKey, request.id);
  ports.render();
  return request;
}

/** Refresh the selected worker service request while preserving the current list. */
export async function refreshAtlasWorkerContextChatServiceRequestV1(
  serviceKey: string,
  ports: AtlasWorkerContextChatServiceRequestPortsV1,
): Promise<void> {
  const id = ports.storageGet(serviceKey);
  if (!id) return;
  try {
    const response = await ports.apiFetch(`/api/service-requests/${encodeURIComponent(id)}`, { cache: 'no-store' });
    if (!response.ok) return;
    const payload = mapRecord(await response.json()) as AtlasWorkerContextChatServiceRequestEnvelopeV1 | null;
    ports.setChatState({ currentRequest: projectAtlasWorkerContextChatServiceRequestRecordV1(payload?.request) });
    ports.render();
  } catch {
    ports.setStatus('Acompanhamento temporariamente indisponível.');
  }
}

/** Load scoped service requests and restore the persisted selection, or select the newest request. */
export async function refreshAtlasWorkerContextChatServiceRequestsV1(
  serviceKey: string,
  ports: AtlasWorkerContextChatServiceRequestPortsV1,
): Promise<void> {
  try {
    const response = await ports.apiFetch('/api/service-requests', { cache: 'no-store' });
    if (!response.ok) return;
    const payload = mapRecord(await response.json()) as AtlasWorkerContextChatServiceRequestEnvelopeV1 | null;
    const requests = (Array.isArray(payload?.requests) ? payload.requests : [])
      .map(projectAtlasWorkerContextChatServiceRequestRecordV1)
      .filter((request): request is AtlasWorkerContextChatServiceRequestV1 => Boolean(request));
    const id = ports.storageGet(serviceKey);
    const currentRequest = requests.find((item: AtlasWorkerContextChatServiceRequestV1) => item.id === id) || requests[0] || null;
    if (currentRequest) ports.storageSet(serviceKey, String(currentRequest.id));
    ports.setChatState({ requests, currentRequest });
    ports.render();
  } catch {}
}

