  createServiceRequest(text: string, files: readonly AtlasWorkerContextChatAttachmentV1[], options: { recordOcr: AtlasRecordOcrPayloadV1 | null }): Promise<AtlasWorkerContextChatServiceRequestV1>;
  executeToolCalls(calls: readonly AtlasWorkerContextChatToolCallV1[], context?: Record<string, unknown>): Promise<string[]>;
  readRecordDraft(): AtlasWorkerContextChatRecordDraftV1 | null;
  writeRecordDraft(draft: AtlasWorkerContextChatRecordDraftV1 | null): void;
