/** Compose chat requests, inference, voice and command execution behind one program-owned controller. */
export function createAtlasWorkerContextChatOperationalControllerV1(
  input: AtlasWorkerContextChatOperationalControllerInputV1,
): AtlasWorkerContextChatOperationalControllerV1 {
  return Object.freeze({
    session: createAtlasWorkerContextChatSessionV1(input.session),
    serviceRequests: createAtlasWorkerContextChatServiceRequestControllerV1(input.serviceRequests),
    inference: createAtlasWorkerContextChatInferenceControllerV1(input.inference),
    voice: createAtlasWorkerContextChatVoiceControllerV1(input.voice.config, input.voice.ports),
    commands: Object.freeze({
      execute: (calls: readonly AtlasWorkerContextChatToolCallV1[], context: Record<string, unknown> = {}) =>
        executeAtlasWorkerContextChatCommandsV1(calls, context, input.getCommandPorts()),
    }),
  });
}

/** Assemble and attach the Worker chat session and its operational controllers in the program. */
export function createAtlasWorkerContextChatRuntimeV1(
  input: AtlasWorkerContextChatRuntimeInputV1,
): AtlasWorkerContextChatRuntimeV1 {
  const controller = createAtlasWorkerContextChatOperationalControllerV1({
    session: { pathname: input.pathname, search: input.search },
    serviceRequests: {
      serviceKey: input.serviceKey,
      getApplicationState: input.getApplicationState,
      getContext: input.getContext,
      getRouteActivityId: input.getRouteActivityId,
      getPorts: input.getServiceRequestPorts,
    },
    inference: {
      apiFetch: input.apiFetch,
      pathname: () => input.pathname,
      getContext: input.getContext,
      getApplicationState: input.getApplicationState,
      getMapContext: input.getMapContext,
    },
    voice: input.voice,
    getCommandPorts: input.getCommandPorts,
  });
  attachAtlasWorkerContextChatSessionStateV1(input.controller, controller.session);
  const componentStateControllerV1 = createAtlasWorkerContextChatComponentStateControllerV1(
    input.controller as unknown as AtlasWorkerContextChatComponentStateHostV1,
  );
  const host = input.controller as unknown as AtlasWorkerContextChatSubmitHostControllerV1;
  const observationHostController = input.controller as unknown as { root?: HTMLElement; route?: unknown };
  const submitMessage = (submission: AtlasWorkerContextChatSubmitInputV1): Promise<void> =>
    submitAtlasWorkerContextChatMessageV1(submission, {
      isPending: () => Boolean(host.readComposerState().pending),
      setPending: (value, label) => host.setPending(value, label),
      getApplicationState: input.getApplicationState,
      getContext: input.getContext,
      pathname: input.currentPathname,
      parseLotStatusCommand: input.parseLotStatusCommand,
      applyLotStatusCommand: input.applyLotStatusCommand,
      serviceRequestId: input.serviceRequestId,
      refreshServiceRequest: () => host.refreshServiceRequest(),
      getCurrentRequest: () => host.readConversationRequestState().currentRequest || null,
      ask: (text, attachment, options) => host.ask(text, attachment, options),
      createServiceRequest: (text, files, options) => host.createServiceRequest(text, files, options),
      executeToolCalls: (calls, context) => host.executeToolCalls(calls, context),
      getRecordDraft: () => host.readRecordDraft(),
      setRecordDraft: draft => host.writeRecordDraft(draft),
      visualClarification: input.visualClarification,
      addAssistant: (message, options) => { void host.add('assistant', message, options || {}); },
      setStatus: message => { if (host.status) host.status.textContent = message; },
      restoreComposer: (text, attachment, files) => host.restoreComposerSubmission(text, attachment || null, files),
      voiceEnabled: () => host.getVoiceState().enabled,
      speak: message => host.speak(message),
      now: () => new Date(),
    });
  return Object.freeze({
    ...controller,
    sessionStateOwnerV1: 'typescript-operational-controller',
    componentStateControllerV1,
    submitMessage,
    installObservation: () => {
      if (!input.observationHost || !observationHostController.root) return null;
      return installAtlasWorkerContextChatObservationProgramV1({
        host: input.observationHost,
        root: observationHostController.root,
        route: String(observationHostController.route || `${input.pathname}${input.search}`),
        routeStorageKey: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.lastRouteKey,
        pathname: input.currentPathname,
        readContext: input.getContext,
        labelForPath: input.labelForPath,
        componentOwners: { installAtlasWorkerContextChatObservationV1 },
        voiceEnabled: () => controller.voice.getState().enabled,
        speak: message => controller.voice.speak(message),
      });
    },
    installRecordSavedEvent: (
      eventTarget: Parameters<AtlasWorkerContextChatRuntimeV1['installRecordSavedEvent']>[0],
      ports: Parameters<AtlasWorkerContextChatRuntimeV1['installRecordSavedEvent']>[1],
    ) => {
      if (!observationHostController.root) return false;
      return installAtlasWorkerContextChatRecordSavedEventProgramV1({
        eventTarget,
        root: observationHostController.root,
        componentOwners: { installAtlasWorkerContextChatRecordSavedEventV1 },
        ports,
      });
    },
    bindComponent: (binding: Parameters<AtlasWorkerContextChatRuntimeV1['bindComponent']>[0]) => {
      const root = observationHostController.root;
      if (!root) return false;
      return installAtlasWorkerContextChatBindingsV1({
        root,
        controller: input.controller as unknown as AtlasWorkerContextChatBindingControllerV1,
        programOwners: {
          applyAtlasWorkerContextChatRecordReviewFlowV1,
          projectAtlasWorkerContextChatComposerSubmissionV1,
          projectAtlasWorkerContextChatActionPlanV1,
          executeAtlasWorkerContextChatCommandsV1,
          createAtlasWorkerContextChatServiceRequestV1,
          projectAtlasWorkerContextChatVisualAllocationCallsV1,
          resolveAtlasWorkerContextChatVisualStageV1,
          buildAtlasWorkerContextChatRecordInterpretationV1,
          projectAtlasWorkerContextChatVisualClarificationV1,
          requestAtlasWorkerContextChatReplyV1,
        },
        componentOwners: binding.componentOwners,
        serviceKey: input.serviceKey,
        setStorage: binding.setStorage,
        native: binding.native,
        capturePhoto: binding.capturePhoto,
        installSwipeSheet: binding.installSwipeSheet,
      });
    },
    mountComponent: (mountInput: Parameters<AtlasWorkerContextChatRuntimeV1['mountComponent']>[0]) => {
      if (!mountInput.documentRef?.body) return false;
      if (mountInput.documentRef.querySelector('[data-worker-context-assistant]')) return true;
      const mountPlan = prepareAtlasWorkerContextChatMountV1({
        storage: mountInput.storage,
        serviceKey: input.serviceKey,
      });
      return mountAtlasWorkerContextChatV1({
        ...mountInput,
        controller: input.controller as unknown as AtlasWorkerContextChatMountControllerV1,
        pathname: input.pathname,
        labelForPath: input.labelForPath,
        speakerProfiles: input.speakerProfiles,
        mobileDefaultCollapsed: mountPlan.mobileDefaultCollapsed,
      });
    },
  });
}

/** Assemble browser host ports and the complete chat runtime in the typed program. */
export function createAtlasWorkerContextChatHostRuntimeV1(
  input: AtlasWorkerContextChatHostRuntimeInputV1,
): AtlasWorkerContextChatRuntimeV1 {
  const host = input.controller as unknown as AtlasWorkerContextChatSubmitHostControllerV1;
  const voiceConfig: AtlasWorkerContextChatVoiceControllerInputV1 = {
    enabledStorageKey: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.voiceEnabledKey,
    profileStorageKey: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.speakerProfileKey,
    defaultProfile: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.defaultSpeakerProfile,
    profiles: input.speakerProfiles.map(profile => ({ ...profile, terms: [...profile.terms] })),
  };
  const voicePorts: AtlasWorkerContextChatVoiceControllerPortsV1 = {
    storage: input.voiceStorage,
    speechSynthesis: input.speechSynthesis,
    utteranceConstructor: input.utteranceConstructor,
    setStatus: message => { if (host.status) host.status.textContent = message; },
  };
  return createAtlasWorkerContextChatRuntimeV1({
    ...input,
    voice: { config: voiceConfig, ports: voicePorts },
  });
}

type AtlasWorkerContextChatRootHostV1 = HTMLElement & {
  getComposerState?(): {editingId: string | null; attachment: AtlasWorkerContextChatAttachmentV1 | null; files: readonly AtlasWorkerContextChatAttachmentV1[]; pending: boolean; pendingLabel: string};
  getConversationPresentation?(): AtlasWorkerContextChatLogInputV1;
  getConversationRequestState?(): {currentRequest?: AtlasWorkerContextChatServiceRequestV1 | null; requests?: readonly AtlasWorkerContextChatServiceRequestV1[]};
  setConversationRequestState?(patch: {currentRequest?: AtlasWorkerContextChatServiceRequestV1 | null; requests?: readonly AtlasWorkerContextChatServiceRequestV1[]}): void;
  setConversationMessage?(message: AtlasWorkerContextChatMessageV1 | null, warning?: unknown): void;
  getRecordDraft?(): AtlasWorkerContextChatRecordDraftV1 | null;
  setRecordDraft?(draft: AtlasWorkerContextChatRecordDraftV1 | null): void;
  readComposerSubmission?(text?: unknown): AtlasWorkerContextChatComposerSubmissionV1;
  clearComposerSubmission?(): void;
  restoreComposerSubmission?(text: unknown, attachment: AtlasWorkerContextChatAttachmentV1 | null, files: readonly AtlasWorkerContextChatAttachmentV1[]): void;
  removeComposerAttachment?(index: unknown): void;
  applyCollapsedState?(collapsed: boolean, native?: boolean): boolean;
  selectTab?(tab: unknown): 'register' | 'conversation';
  applyMapContext?(context: {kind: 'lot' | 'common-area'; label: string}): boolean;
  getMapContext?(): {kind: string; label: string} | null;
  applyPendingState?(pending: boolean, label?: string): boolean;
  renderConversation?(input: AtlasWorkerContextChatLogInputV1): boolean;
  renderAttachments?(): boolean;
  applyMessageEdit?(input: AtlasWorkerContextChatEditCommandV1): boolean;
  readFile?(file: File, source: 'camera' | 'file' | 'clipboard'): boolean;
  runQuickAction?(action: string): boolean;
  openRecordDrawer?(draft: AtlasWorkerContextChatRecordDraftV1 | null): HTMLDialogElement | null;
};

type AtlasWorkerContextChatBootstrapHostV1 = Record<string, unknown>
  & Omit<AtlasWorkerContextChatSubmitHostControllerV1, 'add'>
  & AtlasWorkerContextChatMountControllerV1
  & AtlasWorkerContextChatComponentStateHostV1
  & {
    root: AtlasWorkerContextChatRootHostV1 | null;
    route: string;
    recordDialog: HTMLDialogElement | null;
    readConversationPresentation(): AtlasWorkerContextChatLogInputV1;
    writeConversationRequestState(patch: {currentRequest?: AtlasWorkerContextChatServiceRequestV1 | null; requests?: readonly AtlasWorkerContextChatServiceRequestV1[]}): void;
    readComposerSubmission(text?: unknown): AtlasWorkerContextChatComposerSubmissionV1;
    clearComposerSubmission(): void;
    removeAttachmentAt(index: unknown): void;
    renderAttachment(): void;
    add(kind: string, text: string, options?: AtlasWorkerContextChatAssistantResponseInputV1['options']): AtlasWorkerContextChatAssistantResponseV1 | null;
    setConversationMessage(message: AtlasWorkerContextChatMessageRecordV1 | null, warning?: unknown): void;
    setCollapsed(collapsed: boolean): void;
    toggleVoice(): {enabled: boolean; status: string};
    selectSpeaker(profile: string): {profile: string; status: string};
    startEdit(messageId: string): void;
    runAction(action: string): void;
    setTab(tab: string): void;
    submitComposer(): void;
    submit(text: string, editingId?: string | null, attachment?: AtlasWorkerContextChatAttachmentV1 | null, files?: readonly AtlasWorkerContextChatAttachmentV1[], options?: Record<string, unknown>): Promise<void> | undefined;
    ask(text: string, attachment?: AtlasWorkerContextChatAttachmentV1 | null, options?: AtlasWorkerContextChatRequestOptionsV1): Promise<AtlasWorkerContextChatReplyV1>;
    createServiceRequest(text: string, files?: readonly AtlasWorkerContextChatAttachmentV1[], options?: {recordOcr?: AtlasRecordOcrPayloadV1 | null}): Promise<AtlasWorkerContextChatServiceRequestV1>;
    executeToolCalls(calls: readonly AtlasWorkerContextChatToolCallV1[], context?: Record<string, unknown>): Promise<string[]>;
    openRecordDrawer(): HTMLDialogElement | null;
    openLotStatusContext(lotLabel: unknown): boolean;
    openMapAreaContext(areaLabel: unknown): boolean;
  };

const atlasWorkerContextChatBootstrapByDocumentV1 = new WeakMap<Document, Promise<boolean>>();

/** Start the operational chat from the same TypeScript root, store, and API transport as admin. */
export function startAtlasWorkerContextChatBootstrapV1(input: {
  documentRef?: Document;
  windowRef?: Window & typeof globalThis;
  appStore: AtlasWorkerContextChatExecutionStoreV1;
  apiFetch(path: string, init: RequestInit): Promise<Response>;
}): Promise<boolean> {
  const documentRef = input.documentRef || globalThis.document;
  const windowRef = input.windowRef || globalThis.window as Window & typeof globalThis;
  if (!documentRef?.body || !windowRef) return Promise.resolve(false);
  const existing = atlasWorkerContextChatBootstrapByDocumentV1.get(documentRef);
  if (existing) return existing;
  const installedAssistant = (globalThis as typeof globalThis & {belavistaWorkerAssistant?: {root?: HTMLElement}}).belavistaWorkerAssistant;
  if (installedAssistant?.root?.isConnected) return Promise.resolve(true);
  if (documentRef.querySelector('[data-worker-context-assistant]')) return Promise.resolve(false);

  const activation = Promise.resolve().then(() => {
    const safeStorage = (key: 'localStorage' | 'sessionStorage'): Storage | null => {
      try { return windowRef[key]; } catch { return null; }
    };
    const localStoragePort = safeStorage('localStorage');
    const sessionStoragePort = safeStorage('sessionStorage');
    const storageAdapters = createAtlasWorkerContextChatHostAdaptersV1({
      documentRef,
      pathname: () => windowRef.location.pathname,
      search: () => windowRef.location.search,
      readStages: () => {
        const bridge = (globalThis as typeof globalThis & {__BELAVISTA_RECORD_OCR_BRIDGE_V21?: {stages?: unknown}})
          .__BELAVISTA_RECORD_OCR_BRIDGE_V21;
        return Array.isArray(bridge?.stages) ? bridge.stages as Array<Record<string, unknown>> : [];
      },
      readOperationalContext: ({document, pathname, search, stages}) =>
        atlasComponentOwners.readAtlasWorkerContextChatOperationalContextV1({
          document: document as Document,
          pathname,
          search,
          stages: stages as Array<Record<string, any>>,
        }),
      storage: localStoragePort,
    });
    const component = (): AtlasWorkerContextChatRootHostV1 | null =>
      host.root?.isConnected ? host.root : null;
    const setStatus = (message: string): void => {
      const status = host.status as HTMLElement | null;
      if (status) status.textContent = message;
    };
    let runtime: AtlasWorkerContextChatRuntimeV1 | null = null;
    const host: AtlasWorkerContextChatBootstrapHostV1 = {
      root: null as unknown as AtlasWorkerContextChatBootstrapHostV1['root'],
      log: null as HTMLElement | null,
      input: null as HTMLTextAreaElement | null,
      status: null as HTMLElement | null,
      sessionStateOwnerV1: 'typescript-operational-controller',
      voiceController: null as unknown,
      route: `${windowRef.location.pathname}${windowRef.location.search}`,
      recordDialog: null as HTMLDialogElement | null,
      getVoiceState: () => runtime?.voice.getState() || {enabled: false, profile: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.defaultSpeakerProfile},
      readComposerState: () => ({pending: Boolean(component()?.getComposerState?.().pending ?? host.pending)}),
      setPending: (pending: boolean, label = '') => {
        if (!component()?.applyPendingState?.(pending, label)) {
          host.pending = pending;
          host.pendingLabel = label;
        }
        host.render();
      },
      refreshServiceRequest: async () => { await runtime?.serviceRequests.refreshSelected(); },
      refreshServiceRequests: async () => { await runtime?.serviceRequests.refreshAll(); },
      readConversationRequestState: () => component()?.getConversationRequestState?.() || {
        currentRequest: host.currentRequest || null,
        requests: Array.isArray(host.requests) ? host.requests : [],
      },
      writeConversationRequestState: (patch: {currentRequest?: AtlasWorkerContextChatServiceRequestV1 | null; requests?: readonly AtlasWorkerContextChatServiceRequestV1[]}) => {
        const target = component();
        if (target?.setConversationRequestState) target.setConversationRequestState(patch);
        else {
          if (Object.prototype.hasOwnProperty.call(patch, 'currentRequest')) host.currentRequest = patch.currentRequest;
          if (Object.prototype.hasOwnProperty.call(patch, 'requests')) host.requests = [...(patch.requests || [])];
        }
      },
      readConversationPresentation: () => component()?.getConversationPresentation?.() || {
        message: (Array.isArray(host.messages) ? host.messages.at(-1) : null) as AtlasWorkerContextChatMessageV1 | null,
        persistenceWarning: String(host.persistenceWarning || ''),
        request: host.currentRequest || null,
        requests: Array.isArray(host.requests) ? host.requests : [],
        recordDraft: (host.recordDraft || null) as unknown as import('./components.js').AtlasWorkerContextChatRecordDraftV1 | null,
      },
      setConversationMessage: (message: AtlasWorkerContextChatMessageRecordV1 | null, warning = '') => {
        if (component()?.setConversationMessage) component()?.setConversationMessage?.(message ? { text: message.text, at: message.at } : null, warning);
        else { host.messages = message ? [message] : []; host.persistenceWarning = String(warning || ''); }
      },
      readRecordDraft: () => component()?.getRecordDraft?.() || (host.recordDraft as AtlasWorkerContextChatRecordDraftV1 | null) || null,
      writeRecordDraft: (draft: AtlasWorkerContextChatRecordDraftV1 | null) => {
        if (component()?.setRecordDraft) component()?.setRecordDraft?.(draft);
        else host.recordDraft = draft;
      },
      readComposerSubmission: (text = host.input?.value || '') => component()?.readComposerSubmission?.(text)
        || projectAtlasWorkerContextChatComposerSubmissionV1({text, editingId: host.editingId, attachment: host.attachment as AtlasWorkerContextChatAttachmentV1 | null, files: host.files as AtlasWorkerContextChatAttachmentV1[]}),
      clearComposerSubmission: () => {
        if (component()?.clearComposerSubmission) component()?.clearComposerSubmission?.();
        else { host.editingId = null; host.attachment = null; host.files = []; if (host.input) host.input.value = ''; }
        host.renderAttachment();
      },
      restoreComposerSubmission: (text: unknown, attachment: AtlasWorkerContextChatAttachmentV1 | null, files: readonly AtlasWorkerContextChatAttachmentV1[]) => {
        if (component()?.restoreComposerSubmission) component()?.restoreComposerSubmission?.(text, attachment, files);
        else { host.attachment = attachment; host.files = [...files]; if (host.input) host.input.value = String(text || ''); }
        host.renderAttachment();
      },
      removeAttachmentAt: (index: unknown) => {
        if (component()?.removeComposerAttachment) component()?.removeComposerAttachment?.(index);
        else {
          const current = component()?.getComposerState?.() as {files?: AtlasWorkerContextChatAttachmentV1[]} | undefined;
          const fallbackFiles = Array.isArray(host.files) ? host.files as AtlasWorkerContextChatAttachmentV1[] : [];
          const next = removeAtlasWorkerContextChatAttachmentV1(current?.files || fallbackFiles, index);
          host.files = next.files;
          host.attachment = next.attachment;
        }
        host.renderAttachment();
      },
      render: () => {
        const target = component();
        if (!target?.renderConversation || !runtime) return;
        const composer = runtime.componentStateControllerV1.readComposerState();
        const presentation = runtime.componentStateControllerV1.readConversationPresentation() as import('./components.js').AtlasWorkerContextChatLogInputV1;
        const actor = input.appStore.get().currentActor;
        target.renderConversation({
          message: presentation.message,
          pending: Boolean(composer.pending),
          pendingLabel: String(composer.pendingLabel || ''),
          request: presentation.request,
          requests: presentation.requests,
          persistenceWarning: presentation.persistenceWarning,
          recordDraft: presentation.recordDraft,
          limitedOperationalActor: isAtlasLimitedOperationalActorV1(actor || {}),
        });
      },
      renderAttachment: () => { component()?.renderAttachments?.(); },
      bind: () => {
        const native = Boolean((globalThis as typeof globalThis & {BELAVISTA_CAPACITOR_NATIVE?: boolean}).BELAVISTA_CAPACITOR_NATIVE)
          || Boolean((globalThis as typeof globalThis & {Capacitor?: {isNativePlatform?: () => boolean}}).Capacitor?.isNativePlatform?.());
        runtime?.bindComponent({
          componentOwners: atlasComponentOwners as unknown as AtlasWorkerContextChatBindingComponentsV1,
          setStorage: (key, value) => { storageAdapters.writeStorage(key, value); },
          native,
          capturePhoto: native ? captureAtlasWorkerContextChatPhotoV1 : undefined,
          installSwipeSheet: ({root, setCollapsed, native}) => {
            atlasComponentOwners.installAtlasWorkerChatSwipeSheetV1({root, setCollapsed, native, windowRef});
          },
        });
      },
      installRecordSavedEvent: () => {
        runtime?.installRecordSavedEvent(windowRef, {
          isDialogOpen: () => Boolean(host.recordDialog?.open || component()?.querySelector('dialog[open]')),
          getDraft: () => host.readRecordDraft(),
          setDraft: draft => host.writeRecordDraft(draft),
          addAssistant: message => { host.add('assistant', message); },
          setStatus,
          closeDialog: () => { (host.recordDialog || component()?.querySelector('dialog[open]'))?.close(); },
        });
      },
      installObservation: () => { runtime?.installObservation(); },
      add: (kind: string, text: string, options: AtlasWorkerContextChatAssistantResponseInputV1['options'] = {}) =>
        commitAtlasWorkerContextChatAssistantResponseV1({kind, text, options}, {
          storage: localStoragePort,
          now: () => new Date(),
          random: () => Math.random(),
          setConversationMessage: (message, warning) => host.setConversationMessage({ ...message }, warning),
          render: () => host.render(),
        }),
      readImage: (file: File, source: 'camera' | 'file' | 'clipboard' = 'file') => { component()?.readFile?.(file, source); },
      discardRecord: () => {
        const command = projectAtlasWorkerContextChatDiscardRecordCommandV1();
        host.writeRecordDraft(command.recordDraft);
        setStatus(command.status);
        host.render();
      },
      applyRecord: () => {
        const draft = host.readRecordDraft();
        if (!draft) return;
        applyAtlasWorkerContextChatRecordReviewFlowV1({draft, store: input.appStore, ports: {
          setStatus,
          setCollapsed: collapsed => host.setCollapsed(collapsed),
          openItem: itemKey => windowRef.setTimeout(() => {
            const item = Array.from(documentRef.querySelectorAll<HTMLElement>('[data-stage-center-item-open]'))
              .find(candidate => candidate.dataset.stageCenterItemOpen === itemKey);
            item?.click();
          }, 0),
          clearDraft: () => host.writeRecordDraft(null),
          render: () => host.render(),
        }});
      },
      setCollapsed: (collapsed: boolean) => {
        const target = component();
        if (target?.applyCollapsedState?.(collapsed, Boolean((globalThis as typeof globalThis & {BELAVISTA_CAPACITOR_NATIVE?: boolean}).BELAVISTA_CAPACITOR_NATIVE))) return;
      },
      toggleVoice: () => {
        const result = runtime?.voice.toggleEnabled() || {enabled: false, status: 'Avisos falados indisponíveis.'};
        setStatus(result.status);
        return result;
      },
      selectSpeaker: (profile: string) => {
        const result = runtime?.voice.selectProfile(profile) || {profile: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.defaultSpeakerProfile, status: 'Perfil de voz indisponível.'};
        setStatus(result.status);
        return result;
      },
      speak: (message: unknown) => runtime?.voice.speak(message),
      startEdit: (messageId: string) => {
        const presentation = host.readConversationPresentation() as {message?: AtlasWorkerContextChatMessageRecordV1 | null};
        const command = projectAtlasWorkerContextChatEditCommandV1(presentation.message ? [presentation.message] : [], messageId);
        if (command) component()?.applyMessageEdit?.(command);
      },
      runAction: (action: string) => { component()?.runQuickAction?.(action); },
      setTab: (tab: string) => { component()?.selectTab?.(tab); },
      submitComposer: () => {
        const submission = host.readComposerSubmission(host.input?.value || '');
        if (submission.shouldSubmit) void host.submit(submission.text, submission.editingId, submission.attachment, submission.files);
      },
      submit: (text: string, editingId: string | null = null, attachment: AtlasWorkerContextChatAttachmentV1 | null = null, files: readonly AtlasWorkerContextChatAttachmentV1[] = [], options: Record<string, unknown> = {}) =>
        runtime?.submitMessage({text, attachment, files, options: {...options, editingId}}),
      ask: (text: string, attachment?: AtlasWorkerContextChatAttachmentV1 | null, options?: AtlasWorkerContextChatRequestOptionsV1) =>
        runtime!.inference.ask({message: text, attachment, options}),
      createServiceRequest: (text: string, files: readonly AtlasWorkerContextChatAttachmentV1[] = [], {recordOcr = null}: {recordOcr?: AtlasRecordOcrPayloadV1 | null} = {}) =>
        runtime!.serviceRequests.create({text, files, recordOcr}),
      executeToolCalls: (calls: readonly AtlasWorkerContextChatToolCallV1[], context: Record<string, unknown> = {}) =>
        runtime!.commands.execute(calls, context),
      openRecordDrawer: () => {
        host.recordDialog = component()?.openRecordDrawer?.(host.readRecordDraft()) || null;
        return host.recordDialog;
      },
      openLotStatusContext: (lotLabel: unknown) => {
        const target = component();
        if (!target) return false;
        host.setCollapsed(false);
        return Boolean(target.applyMapContext?.({kind: 'lot', label: String(lotLabel || 'lote selecionado').trim()}));
      },
      openMapAreaContext: (areaLabel: unknown) => {
        const target = component();
        if (!target) return false;
        host.setCollapsed(false);
        return Boolean(target.applyMapContext?.({kind: 'common-area', label: String(areaLabel || 'área selecionada').trim()}));
      },
    };

    runtime = createAtlasWorkerContextChatHostRuntimeV1({
      controller: host,
      pathname: windowRef.location.pathname,
      search: windowRef.location.search,
      serviceKey: ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.serviceRequestKey,
      labelForPath: storageAdapters.labelForPath,
      speakerProfiles: atlasComponentOwners.ATLAS_WORKER_CONTEXT_CHAT_PRESENTATION_V1.speakerProfiles,
      apiFetch: input.apiFetch,
      getApplicationState: () => input.appStore.get(),
      getContext: storageAdapters.readContext,
      getMapContext: () => component()?.getMapContext?.() || null,
      getRouteActivityId: () => new URLSearchParams(windowRef.location.search).get('activity'),
      getServiceRequestPorts: () => createAtlasWorkerContextChatServiceRequestPortsV1({
        host: globalThis,
        apiFetch: input.apiFetch,
        getChatState: () => host.readConversationRequestState() as ReturnType<AtlasWorkerContextChatServiceRequestPortsV1['getChatState']>,
        setChatState: patch => host.writeConversationRequestState(patch),
        render: () => host.render(),
        setStatus,
      }),
      currentPathname: () => windowRef.location.pathname,
      parseLotStatusCommand: text => parseAtlasLotStatusCommandV1(text) as unknown as Record<string, unknown> | null,
      applyLotStatusCommand: command => applyAtlasLotStatusCommandV1(input.appStore, command, {documentRef}),
      serviceRequestId: () => storageAdapters.readStorage(ATLAS_WORKER_CONTEXT_CHAT_STORAGE_V1.serviceRequestKey),
      visualClarification: projectAtlasWorkerContextChatVisualClarificationV1,
      observationHost: {
        eventTarget: globalThis,
        documentRef: documentRef as Document,
        storage: sessionStoragePort,
        setTimeout: windowRef.setTimeout.bind(windowRef),
        clearTimeout: windowRef.clearTimeout.bind(windowRef),
        requestAnimationFrame: windowRef.requestAnimationFrame.bind(windowRef),
        cancelAnimationFrame: windowRef.cancelAnimationFrame.bind(windowRef),
        requestIdleCallback: windowRef.requestIdleCallback?.bind(windowRef),
        MutationObserverCtor: windowRef.MutationObserver,
      },
      getCommandPorts: () => createAtlasWorkerContextChatExecutionPortsV1({apiFetch: input.apiFetch, host: globalThis}),
      voiceStorage: localStoragePort,
      speechSynthesis: windowRef.speechSynthesis,
      utteranceConstructor: windowRef.SpeechSynthesisUtterance,
    });
    host.voiceController = runtime.voice;
    const globalRef = globalThis as typeof globalThis & {belavistaWorkerAssistant?: Record<string, unknown>; atlasWorkerContextChatRuntimeV1?: AtlasWorkerContextChatRuntimeV1};
    globalRef.belavistaWorkerAssistant = host;
    globalRef.atlasWorkerContextChatRuntimeV1 = runtime;
    const mounted = runtime.mountComponent({documentRef, storage: localStoragePort});
    if (!mounted) {
      delete globalRef.belavistaWorkerAssistant;
      delete globalRef.atlasWorkerContextChatRuntimeV1;
      return false;
    }
    documentRef.documentElement.dataset.atlasWorkerContextChatBootstrapOwnerV1 = 'typescript';
    documentRef.documentElement.dataset.atlasWorkerContextChatRootOwnerV1 = 'typescript';
    return true;
  });

  atlasWorkerContextChatBootstrapByDocumentV1.set(documentRef, activation);
  return activation;
}

export interface WorkerWorkbenchInputInferenceCommandV1 extends WorkerWorkbenchInferenceRequestInputV1 {
  request: WorkerWorkbenchApiReadV1;
}

/** Execute the canonical workbench inference command through the host API port. */
export function requestWorkerWorkbenchInputInferenceV1(
  input: WorkerWorkbenchInputInferenceCommandV1,
): Promise<Record<string, any>> {
  const payload = projectWorkerWorkbenchInferenceRequestV1(input);
  return input.request('/api/workbench/infer', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  });
}

/** Build and send the stage-input inference request from the typed stage runtime. */
export function requestWorkerWorkbenchStageInputInferenceV1(
  session: WorkerWorkbenchInputSessionV1,
  context: WorkerWorkbenchStageRuntimeV1,
  request: WorkerWorkbenchApiReadV1,
): Promise<Record<string, any>> {
  return requestWorkerWorkbenchInputInferenceV1({
    stageKey: context.definition.key,
    activityId: session.activityId,
    title: session.title,
    text: session.text,
    calendarDate: context.calendarDate,
    activities: context.flowActivities,
    automation: normalizeWorkerWorkbenchAutomationV1(session.automation),
    programming: normalizeWorkerWorkbenchProgrammingV1(session.programming, session),
    properties: normalizeWorkerWorkbenchPropertiesV1(session.properties, session),
    request,
  });
}

export function updateWorkerWorkbenchAutomationOptionV1(
  session: WorkerWorkbenchInputSessionV1,
  key: string,
  checked: boolean,
): WorkerWorkbenchAutomationV1 {
  const automation = normalizeWorkerWorkbenchAutomationV1(session.automation);
  if (Object.prototype.hasOwnProperty.call(automation, key)) automation[key] = checked;
  session.automation = automation;
  return automation;
}

export function updateWorkerWorkbenchProgrammingOptionV1(
  session: WorkerWorkbenchInputSessionV1,
  key: string,
  checked: boolean,
): WorkerWorkbenchProgrammingV1 {
  const programming = normalizeWorkerWorkbenchProgrammingV1(session.programming, session);
  if (Object.prototype.hasOwnProperty.call(programming, key)) programming[key] = checked;
  session.programming = programming;
  return programming;
}

export function updateWorkerWorkbenchProgrammingSettingV1(
  session: WorkerWorkbenchInputSessionV1,
  key: string,
  value: string,
): WorkerWorkbenchProgrammingV1 {
  const programming = normalizeWorkerWorkbenchProgrammingV1(session.programming, session);
  if (key === 'scheduleMode' && ['sequential', 'parallel', 'production'].includes(value))
    programming.scheduleMode = value as WorkerWorkbenchProgrammingV1['scheduleMode'];
  else if (key === 'productionBasis') programming.productionBasis = value;
  session.programming = programming;
  return programming;
}

export function updateWorkerWorkbenchInputPropertyV1(
  session: WorkerWorkbenchInputSessionV1,
  index: number,
  key: string,
  value: unknown,
): boolean {
  session.properties = normalizeWorkerWorkbenchPropertiesV1(session.properties, session);
  const property = session.properties[index];
  if (!property || (key !== 'label' && key !== 'value')) return false;
  if (key === 'label') property.label = String(value ?? '');
  else property.value = String(value ?? '');
  return true;
}

export function addWorkerWorkbenchInputPropertyV1(
  session: WorkerWorkbenchInputSessionV1,
  createId: (prefix: string) => string,
): boolean {
  session.properties = normalizeWorkerWorkbenchPropertiesV1(session.properties, session);
  if (session.properties.length >= 30) return false;
  session.properties.push({ id: createId('property'), label: 'Nova propriedade', value: '' });
  return true;
}

export function removeWorkerWorkbenchInputPropertyV1(session: WorkerWorkbenchInputSessionV1, index: number): boolean {
  session.properties = normalizeWorkerWorkbenchPropertiesV1(session.properties, session);
  if (!Number.isInteger(index) || index < 0 || index >= session.properties.length) return false;
  session.properties.splice(index, 1);
  return true;
}

export function reorderWorkerWorkbenchInputSessionsV1(
  sessions: WorkerWorkbenchInputSessionV1[],
  fromId: string,
  toId: string,
): boolean {
  const from = sessions.findIndex(session => session.id === fromId);
  const to = sessions.findIndex(session => session.id === toId);
  if (from < 0 || to < 0 || from === to) return false;
  const [moved] = sessions.splice(from, 1);
  sessions.splice(to, 0, moved);
  sessions.forEach((session, index) => { session.order = index; });
  return true;
}

export function updateWorkerWorkbenchInputTextV1(
  session: WorkerWorkbenchInputSessionV1,
  field: 'title' | 'text',
  value: unknown,
): string {
  const next = String(value ?? '');
  session[field] = next;
  return next;
}

export interface WorkerWorkbenchStageInputEventV1 {
  kind: 'title' | 'text' | 'automation-option' | 'programming-option' | 'programming-setting'
    | 'property-field' | 'property-add' | 'property-remove' | 'property-insert'
    | 'production-field' | 'condition-field' | 'condition-add' | 'condition-remove'
    | 'infer' | 'cycle' | 'session-remove' | 'reorder' | 'calendar-date' | 'activity-add';
  phase: 'input' | 'change' | 'click' | 'drop';
  id: string;
  fromId?: string;
  toId?: string;
  key?: string;
  index?: number;
  value?: unknown;
  checked?: boolean;
}

export interface WorkerWorkbenchStageInputApplicationPortsV1 {
  getContext(): WorkerWorkbenchStageRuntimeV1 | null;
  createId(prefix: string): string;
  todayIso(): string;
  renderSessions(): void;
  renderFlow(): void;
  drawConnections(): void;
  saveState(): void;
  renderInference(session: WorkerWorkbenchInputSessionV1): void;
  requestInference(session: WorkerWorkbenchInputSessionV1, context: WorkerWorkbenchStageRuntimeV1): Promise<Record<string, unknown>>;
  readTextSelection(sessionId: string): { text: string; selectionStart: number; selectionEnd: number } | null;
  applyTextInsertion(sessionId: string, insertion: { text: string; selectionStart: number; selectionEnd: number }): void;
  syncProductionUnit(sessionId: string, unit: string): void;
  focusTitle(sessionId: string): void;
  setActionBusy(kind: 'infer' | 'cycle', sessionId: string, busy: boolean, label: string): void;
  setStatus(message: string): void;
}

/** Compose the semantic stage-input events into domain changes and adapter effects. */
export function createWorkerWorkbenchStageInputApplicationV1(
  ports: WorkerWorkbenchStageInputApplicationPortsV1,
): (detail: WorkerWorkbenchStageInputEventV1) => void {
  const inferenceVersions = new Map<string, number>();
  const rebuildFlow = (context: WorkerWorkbenchStageRuntimeV1): void => {
    context.flowActivities = projectWorkerWorkbenchFlowActivitiesV1(context.definition, context.inputSessions);
  };
  const renderRelation = (
    context: WorkerWorkbenchStageRuntimeV1,
    session: WorkerWorkbenchInputSessionV1,
    inference: Record<string, unknown> | null,
  ): void => {
    context.links = projectWorkerWorkbenchInputRelationLinksV1(context.links, session, inference);
    ports.drawConnections();
    ports.saveState();
  };
  const infer = async (session: WorkerWorkbenchInputSessionV1, context: WorkerWorkbenchStageRuntimeV1): Promise<void> => {
    const version = (inferenceVersions.get(session.id) || 0) + 1;
    inferenceVersions.set(session.id, version);
    const isCurrent = (): boolean => inferenceVersions.get(session.id) === version
      && context.inputSessions.includes(session);
    if (!session.text.trim()) {
      session.inference = null;
      ports.renderInference(session);
      renderRelation(context, session, null);
      return;
    }
    session.inference = { ...(session.inference || {}), loading: true, confidence: 0, summary: 'Analisando a atividade e suas dependências…' };
    ports.renderInference(session);
    try {
      const result = await ports.requestInference(session, context);
      if (!isCurrent()) return;
      session.inference = { ...result, loading: false };
      renderRelation(context, session, session.inference);
      ports.renderInference(session);
      ports.setStatus('Compreensão registrada e cronograma atualizado');
    } catch (error) {
      if (!isCurrent()) return;
      session.inference = { loading: false, confidence: 0, summary: `A compreensão não pôde ser consultada: ${error instanceof Error ? error.message : String(error)}` };
      ports.renderInference(session);
      ports.setStatus('IA indisponível; entrada preservada para nova tentativa');
    }
    ports.saveState();
  };
  const queueInference = (context: WorkerWorkbenchStageRuntimeV1, session: WorkerWorkbenchInputSessionV1): void => {
    clearTimeout(context.inputTimers.get(session.id));
    inferenceVersions.set(session.id, (inferenceVersions.get(session.id) || 0) + 1);
    context.inputTimers.set(session.id, setTimeout(() => {
      context.inputTimers.delete(session.id);
      void infer(session, context);
    }, 650));
  };

  return detail => {
    const context = ports.getContext();
    if (!context) return;
    if (detail.kind === 'calendar-date') {
      context.calendarDate = updateWorkerWorkbenchInputCalendarDateV1(context.inputSessions, detail.value, ports.todayIso());
      context.scheduleContext = projectWorkerWorkbenchScheduleContextV1(context, context.calendarDate);
      ports.renderSessions(); ports.renderFlow(); ports.drawConnections(); ports.saveState();
      return;
    }
    if (detail.kind === 'activity-add') {
      const session = createWorkerWorkbenchCustomInputSessionV1(context.calendarDate, context.inputSessions.length, ports.createId);
      context.inputSessions.push(session);
      rebuildFlow(context);
      context.layout[session.activityId] = projectWorkerWorkbenchNextCustomActivityLayoutV1(context.flowActivities.length);
      ports.renderSessions(); ports.renderFlow(); ports.drawConnections(); ports.saveState();
      setTimeout(() => ports.focusTitle(session.id), 0);
      return;
    }

    const session = context.inputSessions.find(item => item.id === String(detail.id || ''));
    if (!session) return;
    if (detail.kind === 'title' || detail.kind === 'text') {
      updateWorkerWorkbenchInputTextV1(session, detail.kind, detail.value);
      if (detail.kind === 'title') { rebuildFlow(context); ports.renderFlow(); }
      if (detail.phase === 'input') { ports.saveState(); queueInference(context, session); }
      else if (detail.kind === 'title') { rebuildFlow(context); ports.renderFlow(); }
      return;
    }
    if (detail.kind === 'automation-option') {
      updateWorkerWorkbenchAutomationOptionV1(session, String(detail.key || ''), Boolean(detail.checked));
      if (detail.key === 'propagateRelations') renderRelation(context, session, session.inference);
      else ports.saveState();
      ports.setStatus('Diretriz da entrada atualizada');
      return;
    }
    if (detail.kind === 'programming-option') {
      updateWorkerWorkbenchProgrammingOptionV1(session, String(detail.key || ''), Boolean(detail.checked));
      ports.saveState(); ports.setStatus('Modo de programação atualizado');
      return;
    }
    if (detail.kind === 'programming-setting') {
      updateWorkerWorkbenchProgrammingSettingV1(session, String(detail.key || ''), String(detail.value || ''));
      ports.saveState(); ports.setStatus('Modo de programação atualizado');
      return;
    }
    if (detail.kind === 'property-field') {
      updateWorkerWorkbenchInputPropertyV1(session, Number(detail.index), String(detail.key || ''), detail.value);
      ports.saveState();
      return;
    }
    if (detail.kind === 'property-add') {
      addWorkerWorkbenchInputPropertyV1(session, ports.createId);
      ports.renderSessions(); ports.saveState();
      return;
    }
    if (detail.kind === 'property-remove') {
      removeWorkerWorkbenchInputPropertyV1(session, Number(detail.index));
      ports.renderSessions(); ports.saveState();
      return;
    }
    if (detail.kind === 'property-insert') {
      const selection = ports.readTextSelection(session.id);
      if (!selection) return;
      const insertion = projectWorkerWorkbenchPropertyTokenInsertionV1(
        session, Number(detail.index), selection.text, selection.selectionStart, selection.selectionEnd,
      );
      if (!insertion) return;
      updateWorkerWorkbenchInputTextV1(session, 'text', insertion.text);
      ports.applyTextInsertion(session.id, insertion);
      queueInference(context, session); ports.saveState();
      return;
    }
    if (detail.kind === 'production-field') {
      const result = updateWorkerWorkbenchProductionFieldV1(session, String(detail.key || ''), String(detail.value || ''));
      if (result.unitChanged) {
        ports.syncProductionUnit(session.id, result.unit);
        rebuildFlow(context); ports.renderFlow(); ports.drawConnections();
      }
      ports.saveState();
      return;
    }
    if (detail.kind === 'condition-field') {
      updateWorkerWorkbenchProductionConditionV1(session, Number(detail.index), String(detail.key || ''), String(detail.value || ''));
      ports.saveState();
      return;
    }
    if (detail.kind === 'condition-add') {
      addWorkerWorkbenchProductionConditionV1(session);
      ports.renderSessions(); ports.saveState();
      return;
    }
    if (detail.kind === 'condition-remove') {
      removeWorkerWorkbenchProductionConditionV1(session, Number(detail.index));
      ports.renderSessions(); ports.saveState();
      return;
    }
    if (detail.kind === 'infer' || detail.kind === 'cycle') {
      clearTimeout(context.inputTimers.get(session.id));
      const label = detail.kind === 'infer' ? 'Compreender agora' : 'Executar diretrizes';
      ports.setActionBusy(detail.kind, session.id, true, label);
      void infer(session, context).then(() => {
        if (detail.kind === 'cycle') {
          rebuildFlow(context); ports.renderFlow(); ports.drawConnections(); ports.saveState();
          ports.setStatus('Diretrizes executadas e propagadas ao cronograma');
        }
      }).finally(() => ports.setActionBusy(detail.kind as 'infer' | 'cycle', session.id, false, label));
      return;
    }
    if (detail.kind === 'session-remove') {
      if (removeWorkerWorkbenchInputSessionV1(context.inputSessions, context.flowActivities, context.links, context.layout, session.id)) {
        clearTimeout(context.inputTimers.get(session.id));
        context.inputTimers.delete(session.id);
        inferenceVersions.set(session.id, (inferenceVersions.get(session.id) || 0) + 1);
        ports.renderSessions(); ports.renderFlow(); ports.drawConnections(); ports.saveState();
      }
      return;
    }
    if (detail.kind === 'reorder') {
      if (reorderWorkerWorkbenchInputSessionsV1(context.inputSessions, String(detail.fromId || ''), String(detail.toId || ''))) {
        ports.renderSessions(); ports.saveState();
      }
    }
  };
}

/** Render and bind the stage-input editor through its typed component and program owners. */
export function mountWorkerWorkbenchStageInputEditorV1(input: {
  panel: HTMLElement;
  runtime: WorkerWorkbenchStageRuntimeV1;
  createId(prefix: string): string;
  todayIso(): string;
  request: WorkerWorkbenchApiReadV1;
  saveState(): void;
  renderFlow(): void;
  drawConnections(): void;
}): boolean {
  const { panel, runtime } = input;
  const projectSessions = (): AtlasWorkerWorkbenchInputSessionViewV1[] => runtime.inputSessions.map((session, index) => {
    session.automation = normalizeWorkerWorkbenchAutomationV1(session.automation);
    const composition = projectWorkerWorkbenchInputCardV1(session);
    const date = runtime.calendarDate;
    const dateLabel = date
      ? new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' })
      : 'A definir';
    return {
      id: session.id,
      index,
      custom: Boolean(session.custom),
      calendarDate: session.calendarDate,
      currentCalendarDate: runtime.calendarDate,
      title: session.title,
      text: session.text,
      unit: session.unit,
      release: session.release,
      hasInference: Boolean(session.inference?.summary),
      scheduleDateLabel: dateLabel,
      automation: session.automation,
      properties: composition.properties,
      composition,
    };
  });
  let application = (_detail: WorkerWorkbenchStageInputEventV1): void => {};
  const component = installAtlasWorkerStageInputEditorComponentV1({
    panel,
    projectSessions,
    onEvent: detail => application(detail),
  });
  if (!component) return false;
  application = createWorkerWorkbenchStageInputApplicationV1({
    getContext: () => runtime,
    createId: input.createId,
    todayIso: input.todayIso,
    renderSessions: component.renderSessions,
    renderFlow: input.renderFlow,
    drawConnections: input.drawConnections,
    saveState: input.saveState,
    renderInference: session => component.renderInference({
      id: session.id,
      sessionUnit: session.unit || 'registro',
      composition: projectWorkerWorkbenchInputCardV1(session),
    }),
    requestInference: (session, context) => requestWorkerWorkbenchStageInputInferenceV1(session, context, input.request),
    readTextSelection: component.readTextSelection,
    applyTextInsertion: component.applyTextInsertion,
    syncProductionUnit: component.syncProductionUnit,
    focusTitle: component.focusTitle,
    setActionBusy: component.setActionBusy,
    setStatus: component.setStatus,
  });
  panel.dataset.inputMode = panel.dataset.inputMode === 'edit' ? 'edit' : 'view';
  panel.dataset.inputApplicationOwnerV1 = 'typescript-program';
  component.renderSessions();
  return true;
}

export function removeWorkerWorkbenchInputSessionV1(
  sessions: WorkerWorkbenchInputSessionV1[],
  activities: WorkerWorkbenchFlowActivityV1[],
  links: WorkerWorkbenchInputRelationLinkV1[],
  layout: Record<string, unknown>,
  sessionId: string,
): boolean {
  const index = sessions.findIndex(session => session.id === sessionId);
  if (index < 0) return false;
  const [removed] = sessions.splice(index, 1);
  activities.splice(0, activities.length, ...activities.filter(activity => activity.id !== removed.activityId));
  links.splice(0, links.length, ...links.filter(link => link.from !== removed.activityId
    && link.to !== removed.activityId && link.sourceId !== removed.id));
  delete layout[removed.activityId];
  return true;
}

export function projectWorkerWorkbenchInputRelationLinksV1(
  links: WorkerWorkbenchInputRelationLinkV1[],
  session: WorkerWorkbenchInputSessionV1,
  inference: Record<string, unknown> | null,
): WorkerWorkbenchInputRelationLinkV1[] {
  const retained = links.filter(link => !(link.source === 'input-inference' && link.sourceId === session.id));
  if (!normalizeWorkerWorkbenchAutomationV1(session.automation).propagateRelations) return retained;
  const relation = workerWorkbenchRecordV1(inference?.relation);
  const from = String(relation.fromActivityId || '');
  const to = String(relation.toActivityId || '');
  if (from && to && from !== to) retained.push({
    from,
    to,
    label: String(relation.label || 'relação inferida'),
    source: 'input-inference',
    sourceId: session.id,
  });
  return retained;
}

export function projectWorkerWorkbenchPropertyTokenInsertionV1(
  session: WorkerWorkbenchInputSessionV1,
  index: number,
  value: string,
  selectionStart: number,
  selectionEnd: number,
): { text: string; selectionStart: number; selectionEnd: number } | null {
  session.properties = normalizeWorkerWorkbenchPropertiesV1(session.properties, session);
  const property = session.properties[index];
  if (!property) return null;
  const text = String(value || '');
  const start = Math.max(0, Math.min(text.length, Number(selectionStart) || 0));
  const end = Math.max(start, Math.min(text.length, Number(selectionEnd) || start));
  const token = `{{${property.label || 'propriedade'}}}`;
  const nextText = `${text.slice(0, start)}${token}${text.slice(end)}`;
  const caret = start + token.length;
  return { text: nextText, selectionStart: caret, selectionEnd: caret };
}

export function updateWorkerWorkbenchProductionFieldV1(
  session: WorkerWorkbenchInputSessionV1,
  key: string,
  value: string,
): { inference: Record<string, unknown>; unitChanged: boolean; unit: string } {
  const inference = ensureWorkerWorkbenchProductionDraftV1(session);
  const production = workerWorkbenchRecordV1(inference.production);
  const numeric = key === 'referenceRate' || key === 'totalQuantity';
  production[key] = numeric ? (value === '' ? '' : Number(value)) : value;
  if (key === 'unit') session.unit = String(value || 'registro');
  return { inference, unitChanged: key === 'unit', unit: String(session.unit || 'registro') };
}

export function updateWorkerWorkbenchProductionConditionV1(
  session: WorkerWorkbenchInputSessionV1,
  index: number,
  key: string,
  value: string,
): boolean {
  const inference = ensureWorkerWorkbenchProductionDraftV1(session);
  const conditions = Array.isArray(inference.conditions) ? inference.conditions as WorkerWorkbenchProductionConditionV1[] : [];
  const condition = conditions[index];
  if (!condition) return false;
  const tokens = (input: string): string[] => input.split(',').map(item => item.trim()).filter(Boolean);
  if (key === 'notifyRoles') {
    condition[key] = tokens(value).map(role => ({ dono: 'owner', proprietario: 'owner', encarregado: 'foreman', worker: 'foreman' }[role.toLocaleLowerCase('pt-BR')] || role));
  } else if (key === 'watchTerms' || key === 'negativeTerms') condition[key] = tokens(value);
  else condition[key] = value;
  return true;
}

export function addWorkerWorkbenchProductionConditionV1(session: WorkerWorkbenchInputSessionV1): boolean {
  const inference = ensureWorkerWorkbenchProductionDraftV1(session);
  const conditions = Array.isArray(inference.conditions) ? inference.conditions as WorkerWorkbenchProductionConditionV1[] : [];
  conditions.push({ kind: 'operacional', label: 'Nova condição', trigger: 'notificar quando o registro indicar impedimento ou pendência', notifyWhen: 'negative-match', notifyRoles: ['owner'], severity: 'warning', watchTerms: [], negativeTerms: ['bloqueado', 'pendente', 'atrasado'], message: 'Condição manual identificada na leitura operacional.' });
  inference.conditions = conditions;
  return true;
}

export function removeWorkerWorkbenchProductionConditionV1(session: WorkerWorkbenchInputSessionV1, index: number): boolean {
  const inference = ensureWorkerWorkbenchProductionDraftV1(session);
  const conditions = Array.isArray(inference.conditions) ? inference.conditions as WorkerWorkbenchProductionConditionV1[] : [];
  if (!Number.isInteger(index) || index < 0 || index >= conditions.length) return false;
  conditions.splice(index, 1);
  inference.conditions = conditions;
  return true;
}

export function createWorkerWorkbenchInputSessionsV1(
  definition: WorkerWorkbenchStageV1,
  calendarDate: string,
): WorkerWorkbenchInputSessionV1[] {
  return definition.activities.map((activity, index) => {
    const responsibility = workerWorkbenchRecordV1(activity.operational.responsibility);
    const session = {
      id: `input-${activity.id}`, activityId: activity.id, title: activity.title,
      text: `Entrada base: ${activity.release}. Equipamentos e materiais: ${activity.materials.join(', ')}.`,
      unit: activity.unit, materials: activity.materials, release: activity.release,
      responsible: String(responsibility.primary || ''), operational: activity.operational,
      calendarDate, order: index, custom: false, inference: null,
      automation: defaultWorkerWorkbenchAutomationV1(),
      programming: {} as WorkerWorkbenchProgrammingV1, properties: [] as WorkerWorkbenchPropertyV1[],
    } satisfies WorkerWorkbenchInputSessionV1;
    session.programming = defaultWorkerWorkbenchProgrammingV1(session);
    return session;
  });
}

export function normalizeWorkerWorkbenchInputSessionsV1(
  definition: WorkerWorkbenchStageV1,
  storedValue: unknown,
  calendarDate: string,
  createId: (prefix: string) => string,
): WorkerWorkbenchInputSessionV1[] {
  const stored = workerWorkbenchRecordV1(storedValue);
  const persisted = Array.isArray(stored.inputSessions) ? stored.inputSessions : [];
  const source = persisted.length ? persisted : createWorkerWorkbenchInputSessionsV1(definition, calendarDate);
  return source.slice(0, 40).map((value, index) => {
    const item = workerWorkbenchRecordV1(value);
    const activityId = String(item.activityId || item.id || '');
    const activity = definition.activities.find(row => row.id === activityId);
    const id = String(item.id || createId('input'));
    const normalizedActivityId = String(item.activityId || item.id || createId('activity'));
    const operationalValue = item.operational || activity?.operational || null;
    const operational = workerWorkbenchRecordV1(operationalValue);
    const responsibility = workerWorkbenchRecordV1(operational.responsibility);
    const materials = Array.isArray(item.materials)
      ? item.materials.map(material => {
        if (typeof material === 'string') return material;
        const row = workerWorkbenchRecordV1(material);
        return {
          id: String(row.id || createId('material')),
          name: String(row.name || row.title || ''),
          description: String(row.description || row.scope || ''),
          usage: String(row.usage || row.use || ''),
          quantity: row.quantity == null ? '' : String(row.quantity),
          unit: String(row.unit || ''),
        } satisfies WorkbenchMaterial;
      })
      : Array.isArray(activity?.materials) ? activity.materials.map(String) : [];
    const session: WorkerWorkbenchInputSessionV1 = {
      id,
      activityId: normalizedActivityId,
      title: String(item.title || activity?.title || 'Atividade de entrada'),
      text: String(item.text || ''),
      unit: String(item.unit || activity?.unit || 'atividade'),
      materials,
      release: String(item.release || activity?.release || ''),
      responsible: String(item.responsible || responsibility.primary || ''),
      operational: operationalValue as Record<string, unknown> | undefined,
      calendarDate,
      order: index,
      custom: Boolean(item.custom),
      inference: item.inference && typeof item.inference === 'object' ? item.inference as Record<string, unknown> : null,
      automation: normalizeWorkerWorkbenchAutomationV1(item.automation),
      programming: {} as WorkerWorkbenchProgrammingV1,
      properties: [],
    };
    session.properties = normalizeWorkerWorkbenchPropertiesV1(item.properties, session);
    session.programming = normalizeWorkerWorkbenchProgrammingV1(item.programming, session);
    return session;
  });
}

export function projectWorkerWorkbenchFlowActivityV1(session: WorkerWorkbenchInputSessionV1): WorkerWorkbenchFlowActivityV1 {
  return {
    id: session.activityId,
    title: session.title || 'Atividade de entrada',
    unit: session.unit || 'atividade',
    materials: session.materials,
    release: session.release || session.text || 'Entrada adicionada pelo usuário',
    responsible: session.responsible || '', weight: 1, custom: true,
    operational: (session.operational || null) as Record<string, unknown>,
    programming: normalizeWorkerWorkbenchProgrammingV1(session.programming, session),
  };
}

export function createWorkerWorkbenchCustomInputSessionV1(
  calendarDate: string,
  order: number,
  createId: (prefix: string) => string,
): WorkerWorkbenchInputSessionV1 {
  const session: WorkerWorkbenchInputSessionV1 = {
    id: createId('input'), activityId: createId('activity'), title: 'Nova atividade', text: '',
    unit: 'atividade', materials: [], release: '', responsible: '', properties: [],
    calendarDate, order, custom: true, inference: null,
    automation: defaultWorkerWorkbenchAutomationV1(),
    programming: {} as WorkerWorkbenchProgrammingV1,
  };
  session.programming = defaultWorkerWorkbenchProgrammingV1(session);
  return session;
}

export function updateWorkerWorkbenchInputCalendarDateV1(
  sessions: WorkerWorkbenchInputSessionV1[],
  value: unknown,
  fallbackDate: string,
): string {
  const candidate = String(value || '');
  const calendarDate = /^\d{4}-\d{2}-\d{2}$/.test(candidate) ? candidate : fallbackDate;
  sessions.forEach(session => { session.calendarDate = calendarDate; });
  return calendarDate;
}

export function projectWorkerWorkbenchNextCustomActivityLayoutV1(flowActivityCount: number): { x: number; y: number } {
  const count = Math.max(0, Math.floor(Number(flowActivityCount) || 0));
  return { x: 58 + count * 246, y: 96 + (count % 2) * 178 };
}

export function projectWorkerWorkbenchFlowActivitiesV1(
  definition: WorkerWorkbenchStageV1,
  sessions: WorkerWorkbenchInputSessionV1[],
): WorkerWorkbenchFlowActivityV1[] {
  const overrides = new Map(sessions.filter(item => !item.custom).map(item => [item.activityId, item]));
  const activities = definition.activities.map(activity => {
    const input = overrides.get(activity.id);
    return input ? {
      ...activity,
      title: input.title || activity.title,
      operational: input.operational || activity.operational,
      programming: normalizeWorkerWorkbenchProgrammingV1(input.programming, input),
    } : activity;
  });
  return activities.concat(sessions.filter(item => item.custom).map(projectWorkerWorkbenchFlowActivityV1));
}

export function projectWorkerWorkbenchDefaultLayoutV1(activities: readonly { id: string }[]): Record<string, { x: number; y: number }> {
  return Object.fromEntries(activities.map((item, index) => [item.id, { x: 58 + index * 246, y: 96 + (index % 2) * 178 }]));
}

export function projectWorkerWorkbenchDefaultLinksV1(definition: WorkerWorkbenchStageV1): Array<{ from: string; to: string; label: string }> {
  return definition.activities.slice(1).map((item, index) => ({
    from: definition.activities[index].id, to: item.id,
    label: index === 0 ? 'libera após aceite' : 'depende da liberação anterior',
  }));
}

export function projectWorkerWorkbenchScheduleContextV1<T extends Record<string, unknown>>(
  context: T,
  calendarDate: string,
): T & { automation: Record<string, unknown> & { plannedStart: string; plannedFinish: string } } {
  const validDate = (value: unknown): string => /^\d{4}-\d{2}-\d{2}$/.test(String(value || ''))
    ? String(value) : new Date().toISOString().slice(0, 10);
  const automation = workerWorkbenchRecordV1(context.automation);
  const start = validDate(calendarDate || automation.plannedStart);
  const finish = validDate(automation.plannedFinish || start);
  return {
    ...context,
    automation: { ...automation, plannedStart: start, plannedFinish: finish < start ? start : finish },
  };
}

export interface ConfiguredStage extends OperationalStage {
  stageKey: string;
  aiConfig: StageAIConfig | null;
  workbenchState: StageWorkbenchState;
  workbenchSessions: WorkbenchSession[];
  workbenchSource: 'persisted' | 'worker-defaults' | 'unavailable';
}

/** Rebuild the shared stage profiles from persisted AI settings and Worker sessions. */
export function projectAtlasStageSettingsProfilesV1(stages: readonly ConfiguredStage[]): Record<string, Record<string, unknown>> {
  const normalize = (value: unknown): string => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLocaleLowerCase('pt-BR');
  const profiles: Record<string, Record<string, unknown>> = {};
  for (const stage of stages) {
    const config = stage.aiConfig;
    if (!config) continue;
    const sessions = Array.isArray(stage.workbenchSessions) ? stage.workbenchSessions : [];
    const activityMaterials = sessions.flatMap(session => (Array.isArray(session.materials) ? session.materials : []).map(material => {
      const item = typeof material === 'string' ? { name: material, description: '', usage: '' } : material;
      return { ...item, activityName: session.title || '' };
    })).filter(item => item.name);
    const configuredMaterials = Array.isArray(config.executionProfile?.materialsTable) ? config.executionProfile.materialsTable : [];
    const seenMaterials = new Set<string>();
    const materialsTable = [...configuredMaterials, ...activityMaterials].filter(item => {
      const key = `${normalize(item.name)}|${normalize(item.activityName || '')}`;
      if (!item.name || seenMaterials.has(key)) return false;
      seenMaterials.add(key);
      return true;
    });
    const profile = config.executionProfile || {}, aiOrganization = profile.aiOrganization && typeof profile.aiOrganization === 'object'
      ? profile.aiOrganization as Record<string, unknown>
      : {};
    profiles[stage.stageKey] = {
      ...profile,
      materialsTable,
      expectedActivities: Array.isArray(profile.expectedActivities) && profile.expectedActivities.length
        ? profile.expectedActivities
        : sessions.map(session => session.title).filter(Boolean),
      requirements: Array.isArray(config.requirements) ? config.requirements : [],
      conditions: Array.isArray(config.conditions) ? config.conditions : [],
      typicalDescription: String(config.typicalDescription || ''),
      requestHints: Array.isArray(config.requestHints) ? config.requestHints : [],
      evidenceFocus: Array.isArray(config.evidenceFocus) ? config.evidenceFocus : [],
      procurementFocus: Array.isArray(config.procurementFocus) ? config.procurementFocus : [],
      notificationTargets: config.notificationTargets || {},
      organizationRequest: config.organizationRequest || aiOrganization.request || '',
      organizationContext: config.organizationContext || aiOrganization.context || '',
    };
  }
  return profiles;
}

