/** Project visibility for one rendered lead row using its existing visible fields. */
export function projectAtlasLeadToolbarRowVisibleV1(input: {
  filters: AtlasLeadToolbarFiltersV1;
  text: string;
  objective: string;
  status: string;
}): boolean {
  const { filters } = input;
  return !(
    (filters.query && !input.text.toLocaleLowerCase().includes(filters.query.toLocaleLowerCase()))
    || (filters.objective !== "all" && !input.objective.includes(filters.objective))
    || (filters.status !== "all" && input.status !== filters.status)
  );
}

