/** Project the active subdivision route's search, totals, profile card and cash details. */
export function projectAtlasLotDevelopmentPageV1(input: AtlasLotDevelopmentPageInputV1) {
  const profiles = input.profiles || [];
  const query = input.query.trim().toLocaleLowerCase('pt-BR');
  const visibleProfiles = profiles.filter(profile =>
    (input.filter === 'all' || profile.kind === input.filter) &&
    (!query || `${profile.title} ${profile.lotLabel} ${profile.quadra} ${profile.description}`
      .toLocaleLowerCase('pt-BR').includes(query)));
  const selectedProfile = profiles.find(profile => profile.id === input.selectedId) || null;
  const creatingProfile = input.formOpen && input.selectedId === '__new__';
  const money = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
  const number = (value: number) => Number(value).toLocaleString('pt-BR');
  const visible = visibleProfiles.map(profile => ({
    profile,
    selected: profile.id === input.selectedId,
    typeLabel: profile.kind === 'lot' ? 'LOTE' : 'ÁREA COMUM',
    statusLabel: profile.status || 'Sem situação',
    descriptionLabel: profile.description || 'Sem descrição cadastrada.',
    details: profile.kind === 'lot'
      ? [
          { label: 'Quadra', value: profile.quadra || '—' },
          { label: 'Área', value: `${number(profile.area)} m²` },
          { label: 'Valor', value: money.format(profile.value) },
        ]
      : [
          { label: 'Localização', value: profile.quadra || '—' },
          { label: 'Área', value: profile.area ? `${number(profile.area)} m²` : 'Não informada' },
          { label: 'Origem', value: 'Cadastro' },
        ],
  }));
  const selectedCashEntries = selectedProfile?.kind === 'lot'
    ? input.cashEntries
        .filter(row => row.kind === 'entrada' && row.lotKey === selectedProfile.lotLabel)
        .map(row => ({ ...row, categoryLabel: row.category || 'Entrada', amountLabel: money.format(row.amountCents / 100) }))
    : [];
  return {
    profiles,
    visible,
    selectedProfile,
    creatingProfile,
    formVisible: Boolean(selectedProfile || creatingProfile),
    selectedCashEntries,
    lotCount: profiles.filter(profile => profile.kind === 'lot').length,
    commonAreaCount: profiles.filter(profile => profile.kind === 'common-area').length,
    updatedProfileCount: profiles.filter(profile => profile.updatedAt).length,
    totalCount: profiles.length,
    visibleCount: visible.length,
  };
}

export interface AtlasCommunicationsPageInputV1 {
  contacts: Array<{ uid: string; name: string; role: string; label: string; online?: boolean }>;
  instagram: Array<{ id: string; contactName: string; externalThreadId?: string; status?: string }>;
  personalQuery: string;
  instagramQuery: string;
  selectedPersonalId: string;
  selectedInstagramId: string;
  assistant: Record<string, unknown> | null;
}

/** Project the sidebar's two-channel inbox lists and lead-qualification summary. */
export function projectAtlasCommunicationsPageV1(input: AtlasCommunicationsPageInputV1) {
  const personalQuery = input.personalQuery.toLocaleLowerCase('pt-BR');
  const instagramQuery = input.instagramQuery.toLocaleLowerCase('pt-BR');
  const contacts = input.contacts.filter(contact => !personalQuery ||
    `${contact.name} ${contact.role} ${contact.label}`.toLocaleLowerCase('pt-BR').includes(personalQuery))
    .map(contact => ({
      contact,
      selected: input.selectedPersonalId === contact.uid,
      initials: contact.name.slice(0, 1).toUpperCase() || '?',
      label: contact.label || contact.role,
    }));
  const instagram = input.instagram.filter(item => !instagramQuery ||
    `${item.contactName} ${item.externalThreadId || ''}`.toLocaleLowerCase('pt-BR').includes(instagramQuery))
    .map(item => ({
      conversation: item,
      selected: input.selectedInstagramId === item.id,
      contactName: item.contactName || 'Lead Instagram',
      status: item.status || 'aberta',
    }));
  const assistant = input.assistant;
  const objectValue = (value: unknown) => value && typeof value === 'object' ? value as Record<string, unknown> : {};
  const draft = objectValue(assistant?.leadDraft);
  const qualification = objectValue(assistant?.qualification);
  const registration = objectValue(assistant?.leadRegistration);
  const leadFacts = [
    { label: 'Nome', value: draft.name },
    { label: 'WhatsApp', value: draft.whatsapp },
    { label: 'Lote/preferência', value: draft.lotLabel || draft.lotId },
    { label: 'Objetivo', value: draft.objective },
    { label: 'Visita', value: draft.visitDate && draft.visitTime ? `${draft.visitDate} · ${draft.visitTime}` : '' },
  ].filter(item => Boolean(item.value));
  const readyForVisit = Boolean(qualification.readyForVisit);
  const readyForLead = Boolean(qualification.readyForLead);
  return {
    contacts,
    instagram,
    assistant: assistant ? {
      reply: String(assistant.reply || 'Sem rascunho de resposta.'),
      qualificationLabel: readyForVisit ? 'Dados de visita completos' : readyForLead ? 'Lead pronto para encaminhar' : 'Dados ainda pendentes',
      readyForLead,
      facts: leadFacts,
      leadId: String(registration.leadId || ''),
      handoffMessage: String(objectValue(assistant.handoff).message || 'Revisar o rascunho antes de enviar.'),
    } : null,
  };
}

export interface AtlasLotDevelopmentProfileStoreStateV1 extends AtlasApplicationStoreState {
  lotStatuses?: Record<string, AtlasLotStatus | undefined>;
  developmentProfiles?: LotDevelopmentProfile[];
  selectedDevelopmentProfileId?: string | null;
  developmentProfileQuery?: string;
}

export interface AtlasLotDevelopmentProfilesDependenciesV1 {
  appStore: AtlasApplicationStore<AtlasLotDevelopmentProfileStoreStateV1>;
  REPASSE_PRICE_CATALOG: RepassePriceCatalogEntry[];
  host?: Record<string, any>;
}

export interface AtlasLotDevelopmentProfilesServiceV1 {
  lotDevelopmentProfilesV1(state?: AtlasLotDevelopmentProfileStoreStateV1): LotDevelopmentProfile[];
  normalizeLotDevelopmentTextV1(value: unknown): string;
  upsertLotDevelopmentProfileV1(input?: Record<string, unknown>): LotDevelopmentProfile;
}

/** Project and edit the legacy lot profile bridge from typed rows and JSON seeds. */
export function createAtlasLotDevelopmentProfilesV1(
  input: AtlasLotDevelopmentProfilesDependenciesV1,
): AtlasLotDevelopmentProfilesServiceV1 {
  const { appStore, REPASSE_PRICE_CATALOG } = input;
  if (!appStore || typeof appStore.get !== 'function' || typeof appStore.set !== 'function')
    throw new TypeError('Lot-development profiles require appStore.get() and appStore.set().');
  if (!Array.isArray(REPASSE_PRICE_CATALOG))
    throw new TypeError('Lot-development profiles require REPASSE_PRICE_CATALOG.');
  const host = input.host || globalThis as typeof globalThis & Record<string, any>;
  if (!host || typeof host !== 'object')
    throw new TypeError('Lot-development profiles require the assistant bridge host.');
  const commonAreas = lotDevelopmentCommonAreasData as LotDevelopmentProfile[];
  const normalizeLotDevelopmentTextV1 = (value: unknown): string => String(value || '').trim().toLocaleLowerCase('pt-BR');
  const lotDevelopmentBaseProfilesV1 = (state = appStore.get()): LotDevelopmentProfile[] => {
    const statusByLot = state.lotStatuses || {};
    const lots = REPASSE_PRICE_CATALOG.filter(item => Number(item?.lot) > 0).map(item => {
      const label = String(item.label || `${item.quadra}-${item.lot}`);
      const status = String(statusByLot[label]?.status || 'Disponível');
      return {
        id: `lot:${label}`, kind: 'lot', title: `Lote ${label}`, lotLabel: label,
        quadra: String(item.quadra || 'Quadra a definir'), area: Number(item.area) || 0,
        value: Number(item.price) || 0, status,
        description: `Perfil comercial do ${label}, vinculado à tabela de preços e ao controle de lote.`,
        source: 'Tabela de lotes', customized: false, inferredAt: null, createdAt: null, updatedAt: null,
      } satisfies LotDevelopmentProfile;
    });
    return [...lots, ...commonAreas.map(profile => ({ ...profile }))];
  };
  const lotDevelopmentProfilesV1 = (state = appStore.get()): LotDevelopmentProfile[] => {
    const custom = new Map((state.developmentProfiles || []).filter(Boolean).map(item => [String(item.id || ''), item]));
    const base = lotDevelopmentBaseProfilesV1(state).map(item => ({ ...item, ...(custom.get(item.id) || {}) }));
    const additions = [...custom.values()].filter(item => item?.id && !base.some(baseItem => baseItem.id === item.id));
    return [...base, ...additions];
  };
  const upsertLotDevelopmentProfileV1 = (profileInput: Record<string, unknown> = {}): LotDevelopmentProfile => {
    const state = appStore.get();
    const kind = /common|área|area/i.test(String(profileInput.kind || '')) ? 'common-area' : 'lot';
    const requestedLot = String(profileInput.lotLabel || profileInput.lot || '').trim();
    const catalogLot = kind === 'lot' && requestedLot
      ? REPASSE_PRICE_CATALOG.find(item => normalizeLotDevelopmentTextV1(item.label) === normalizeLotDevelopmentTextV1(requestedLot))
        || REPASSE_PRICE_CATALOG.find(item => Number(item.lot) === Number(requestedLot.replace(/\D/g, '')))
      : null;
    const title = String(profileInput.title || (catalogLot ? `Lote ${catalogLot.label}` : profileInput.name || 'Área comum do loteamento')).trim().slice(0, 120);
    const id = String(profileInput.id || (catalogLot ? `lot:${catalogLot.label}` : `common:custom-${Date.now().toString(36)}`));
    const existing = lotDevelopmentProfilesV1(state).find(item => item.id === id) || {} as LotDevelopmentProfile;
    const profile: LotDevelopmentProfile = {
      ...existing, id, kind, title,
      lotLabel: catalogLot ? String(catalogLot.label) : String(profileInput.lotLabel || existing.lotLabel || ''),
      quadra: catalogLot ? String(catalogLot.quadra || '') : String(profileInput.quadra || existing.quadra || ''),
      area: Number(profileInput.area) || (catalogLot ? Number(catalogLot.area) || 0 : Number(existing.area) || 0),
      value: Number(profileInput.value) || (catalogLot ? Number(catalogLot.price) || 0 : Number(existing.value) || 0),
      status: String(profileInput.status || existing.status || 'Em planejamento').slice(0, 80),
      description: String(profileInput.description || existing.description || 'Perfil criado para organizar informações do loteamento.').trim().slice(0, 2000),
      source: 'Assistente operacional · revisão humana necessária',
      inferredAt: new Date().toISOString(),
      createdAt: existing.createdAt || null,
      updatedAt: new Date().toISOString(),
    };
    const entries = [...(state.developmentProfiles || []).filter(item => item?.id !== id), profile];
    appStore.set({ developmentProfiles: entries, selectedDevelopmentProfileId: id, view: 'lot-profile', lastAction: `Assistente preparou o perfil ${profile.title}` });
    return profile;
  };
  host.__BELAVISTA_LOT_DEVELOPMENT_PROFILES_V1 = lotDevelopmentProfilesV1;
  host.__BELAVISTA_UPSERT_LOT_DEVELOPMENT_PROFILE_V1 = upsertLotDevelopmentProfileV1;
  return Object.freeze({ lotDevelopmentProfilesV1, normalizeLotDevelopmentTextV1, upsertLotDevelopmentProfileV1 });
}

