export function createAtlasInstagramReplyDraftV1(input: {
  comments: readonly Pick<InstagramComment, 'id' | 'username'>[];
  commentId: unknown;
  instructions: unknown;
}): { commentId: string; draft: string } | null {
  const commentId = String(input.commentId || '');
  const comment = input.comments.find(item => item.id === commentId);
  if (!comment) return null;
  const first = String(comment.username || '').replace(/^@/, '').split(/[._-]/)[0];
  const greeting = first ? `Olá, ${first}!` : 'Olá!';
  const draft = `${greeting} Obrigado por comentar no Aliança Park. ${String(input.instructions || '')} Fale com nossa equipe pelo Direct para receber as informações confirmadas do empreendimento em Amargosa, Bahia.`
    .replace(/\s+/g, ' ')
    .slice(0, 980);
  return { commentId, draft };
}

