export interface AtlasActivityAdminSavePayloadV1 {
  stageId: number;
  name: string;
  category: string;
  status: string;
  progress: number;
  plannedStart: string | null;
  plannedEnd: string | null;
}

export type AtlasActivityAdminDraftProjectionV1 =
  | { ok: true; payload: AtlasActivityAdminSavePayloadV1 }
  | { ok: false };

/** Normalize and validate an activity editor draft before its command reaches the UI controller. */
export function projectAtlasActivityAdminDraftV1(value: unknown): AtlasActivityAdminDraftProjectionV1 {
  const draft = value && typeof value === 'object' ? value as Record<string, unknown> : {};
  const payload: AtlasActivityAdminSavePayloadV1 = {
    stageId: Number(draft.stageId),
    name: String(draft.name || '').trim(),
    category: String(draft.category || '').trim(),
    status: String(draft.status || ''),
    progress: Number(draft.progress),
    plannedStart: String(draft.plannedStart || '') || null,
    plannedEnd: String(draft.plannedEnd || '') || null,
  };
  if (!payload.stageId || !payload.name || !payload.category || !Number.isFinite(payload.progress)
    || payload.progress < 0 || payload.progress > 100
    || (payload.plannedStart && payload.plannedEnd && payload.plannedEnd < payload.plannedStart))
    return { ok: false };
  return { ok: true, payload };
}

