export interface AtlasStageActivityAdminLoaderInputV1 {
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
}

/** Keep stage-activity loading, request de-duplication, and failure state in the program. */
export function createAtlasStageActivityAdminLoaderV1(
  input: AtlasStageActivityAdminLoaderInputV1,
): () => Promise<void> {
  let pending: Promise<void> | null = null;
  return (): Promise<void> => {
    if (pending) return pending;
    pending = (async () => {
      try {
        const response = await input.apiFetch('/api/stages-admin', { cache: 'no-store' });
        const payload = await response.json().catch(() => ({})) as {
          stages?: AtlasStageActivityAdminStageV1[];
          error?: string;
        };
        if (!response.ok || !Array.isArray(payload.stages)) throw new Error(payload.error || `HTTP ${response.status}`);
        input.appStore.set({
          dashboardStageAdminStagesV1: payload.stages,
          atlasActivitiesLoadedV1: true,
          atlasActivitiesErrorV1: '',
        });
      } catch (error) {
        const message = String((error as Error)?.message || 'Serviço indisponível');
        const authUnavailable = /default credentials|OAuth2 access token|Project Id/i.test(message);
        input.appStore.set({
          atlasActivitiesLoadedV1: true,
          atlasActivitiesErrorV1: authUnavailable
            ? 'O servidor não possui as credenciais Firebase necessárias para consultar as atividades.'
            : message,
        });
      }
    })().finally(() => { pending = null; });
    return pending;
  };
}

/** Apply activity-admin commands to canonical state and invoke its persisted data loader. */
export function applyAtlasStageActivityPageActionV1(input: {
  action: AtlasStageActivityPageActionV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  loadActivities(): Promise<void>;
}): void | Promise<void> {
  const { action, appStore, loadActivities } = input;
  switch (action.kind) {
    case 'load-activities':
      return loadActivities();
    case 'refresh-activities':
      appStore.set({ atlasActivitiesLoadedV1: false, atlasActivitiesErrorV1: '' });
      return loadActivities();
    case 'filter-stage':
      appStore.set({ atlasActivityStageFilterV1: action.stageId });
      return;
    case 'open-editor':
      appStore.set({ atlasActivityEditorOpenV1: true, atlasActivityEditorIdV1: '', atlasActivityMutationErrorV1: '' });
      return;
    case 'close-editor':
      appStore.set({ atlasActivityEditorOpenV1: false, atlasActivityEditorIdV1: '', atlasActivityMutationErrorV1: '' });
      return;
    case 'edit-activity':
      appStore.set({ atlasActivityEditorOpenV1: true, atlasActivityEditorIdV1: action.activityId, atlasActivityMutationErrorV1: '' });
  }
}

