export type AtlasOperationalLoopRunInputV1 = Pick<AtlasLegacyViewLayerDependenciesV1,
  'appStore' | 'readIntegrationSettings'> & {
    apiFetch(path: string, init?: RequestInit): Promise<Response>;
    operationalHeaders(extra?: Record<string, string>): Record<string, string | undefined>;
    stageProfilesFromSettings: ReturnType<typeof createAtlasStageMaterialProfileHelpersV1>['stageProfilesFromSettings'];
    publishOperationalRealtime: AtlasFirebaseOperationalCommunicationsV1['publishRealtime'];
    reason: string;
    quiet?: boolean;
    now?: Date;
    consoleRef?: Pick<Console, 'info'>;
  };

/** Run the cross-domain operational inference cycle and apply its canonical result. */
export async function runAtlasOperationalLoopV1(input: AtlasOperationalLoopRunInputV1): Promise<void> {
  const consoleRef = input.consoleRef || globalThis.console;
  try {
    const state = input.appStore.get();
    const actor = state.currentActor || { role: 'owner' };
    const savedSettings = {
      ...((state.integrationSettings && typeof state.integrationSettings === 'object')
        ? state.integrationSettings as Record<string, unknown> : {}),
      ...(input.readIntegrationSettings() || {}),
    };
    const response = await input.apiFetch('/api/operational-loop', {
      method: 'POST',
      headers: Object.fromEntries(Object.entries(input.operationalHeaders({ 'Content-Type': 'application/json' }))
        .filter((entry): entry is [string, string] => typeof entry[1] === 'string')),
      body: JSON.stringify({
        reason: input.reason,
        referenceDate: (input.now || new Date()).toISOString().slice(0, 10),
        syncActivities: true,
        publishNotifications: true,
        stageProfiles: input.stageProfilesFromSettings(savedSettings),
        clientState: {
          view: state.view,
          mapContext: Boolean(state.mapMode === 'focus'),
          globalSituation: true,
          recordsTracked: Array.isArray(state.records) ? state.records.length : 0,
          notificationsTracked: Array.isArray(state.operationalNotifications) ? state.operationalNotifications.length : 0,
        },
      }),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload = await response.json() as Record<string, any>;
    input.appStore.set({
      cashSummary: payload.cashSummary || {},
      operationalState: payload.operational || null,
      operationalNotifications: payload.notifications || [],
      systemCalibration: payload.calibration || null,
      operationalAgenda: payload.agenda || [],
      operationalGuidance: payload.guidance || null,
      cashFlowLocal: payload.cashEntries || [],
      lastAction: input.quiet
        ? state.lastAction
        : `Atualizou ciclo operacional para o perfil ${actor.label || actor.role}`,
    });
    try {
      await input.publishOperationalRealtime(actor as unknown as Record<string, unknown>, payload, { reason: input.reason });
    } catch (realtimeError) {
      consoleRef.info('Espelho público do ciclo operacional ainda indisponível.', realtimeError);
    }
  } catch (error) {
    consoleRef.info('Ciclo operacional indisponível.', error);
  }
}

export interface AtlasOperationalNotificationLifecycleV1 {
  connect(force?: boolean): Promise<void>;
  disconnect(): void;
}

export interface AtlasOperationalNotificationLifecycleInputV1 extends Pick<AtlasLegacyViewLayerDependenciesV1,
  'appStore'> {
  subscribeOperationalNotifications: AtlasFirebaseOperationalCommunicationsV1['subscribeNotifications'];
  consoleRef?: Pick<Console, 'info'>;
}

/** Own actor-scoped notification subscriptions and their canonical store updates. */
export function createAtlasOperationalNotificationLifecycleV1(
  input: AtlasOperationalNotificationLifecycleInputV1,
): AtlasOperationalNotificationLifecycleV1 {
  type Unsubscribe = Awaited<ReturnType<AtlasOperationalNotificationLifecycleInputV1['subscribeOperationalNotifications']>>;
  const consoleRef = input.consoleRef || globalThis.console;
  let activeUid: unknown = undefined;
  let unsubscribe: Unsubscribe | null = null;
  return {
    async connect(force = false): Promise<void> {
      const actorValue = input.appStore.get().currentActor;
      const actor = actorValue && typeof actorValue === 'object'
        ? actorValue as unknown as Record<string, unknown>
        : { role: 'owner' };
      if (activeUid === actor.uid && !force) return;
      unsubscribe?.();
      unsubscribe = null;
      try {
        unsubscribe = await input.subscribeOperationalNotifications(actor, records => {
          const notifications: Array<Record<string, unknown> & { id: string }> = Object.entries(records || {})
            .map(([id, item]): Record<string, unknown> & { id: string } => ({
              id,
              ...(item && typeof item === 'object' ? item as Record<string, unknown> : {}),
            }))
            .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
          input.appStore.set({
            operationalNotifications: notifications,
            lastAction: notifications.length
              ? 'Atualizou notificações em tempo real'
              : 'Canal em tempo real conectado',
          });
        });
        activeUid = actor.uid;
      } catch (error) {
        activeUid = '';
        consoleRef.info('Canal em tempo real ainda não registrado neste dispositivo.', error);
      }
    },
    disconnect(): void {
      unsubscribe?.();
      unsubscribe = null;
      activeUid = undefined;
    },
  };
}

/** Own activity editor persistence commands and state transitions for the admin route. */
export function installAtlasActivityAdminMutationCommandsV1(input: AtlasActivityAdminMutationCommandsV1): void {
  installAtlasActivityAdminMutationEventsV1({
    page: input.page,
    onSave: async data => {
      const id = String(data.id || '');
      const projection = projectAtlasActivityAdminDraftV1(data);
      if (!projection.ok) {
        input.appStore.set({ atlasActivityMutationErrorV1: 'Revise etapa, nome, categoria, progresso e intervalo de datas.' });
        return;
      }
      try {
        const response = await input.apiFetch(id ? `/api/activities/${encodeURIComponent(id)}` : '/api/activities', {
          method: id ? 'PUT' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(projection.payload),
        });
        const payload = await response.json().catch(() => ({})) as { activity?: unknown; error?: string };
        if (!response.ok || !payload.activity) throw new Error(payload.error || `HTTP ${response.status}`);
        input.appStore.set({ atlasActivityEditorOpenV1: false, atlasActivityEditorIdV1: '', atlasActivityMutationErrorV1: '', atlasActivitiesLoadedV1: false });
        await input.reload();
      } catch (error) {
        input.appStore.set({ atlasActivityMutationErrorV1: `Não foi possível salvar a atividade: ${String((error as Error)?.message || error)}` });
      }
    },
    onDelete: async id => {
      if (!input.confirm('Excluir esta atividade cadastrada?')) return;
      try {
        const response = await input.apiFetch(`/api/activities/${encodeURIComponent(id)}`, { method: 'DELETE' });
        const payload = await response.json().catch(() => ({})) as { ok?: boolean; error?: string };
        if (!response.ok || !payload.ok) throw new Error(payload.error || `HTTP ${response.status}`);
        input.appStore.set({ atlasActivityMutationErrorV1: '', atlasActivitiesLoadedV1: false });
        await input.reload();
      } catch (error) {
        input.appStore.set({ atlasActivityMutationErrorV1: `Não foi possível excluir a atividade: ${String((error as Error)?.message || error)}` });
      }
    },
  });
}

