export interface AtlasRecordsPageProjectionInputV1 {
  records: OperationalRecord[];
  stages: OperationalStage[];
  selectedStage: string;
  selectedId: string;
  actorName: string;
  limitedActor: boolean;
}

/** Project the authorized, stage-filtered and newest-first records archive. */
export function projectAtlasRecordsPageV1(input: AtlasRecordsPageProjectionInputV1) {
  const stageName = (record: OperationalRecord): string => {
    const value = String(record.stageId ?? record.stageKey ?? record.etapa ?? record.stage ?? '');
    const stage = input.stages.find(item => String(item.id) === value || String(item.key || '') === value ||
      item.name.toLocaleLowerCase('pt-BR') === value.toLocaleLowerCase('pt-BR'));
    return stage?.name || String(record.etapa || record.stage || record.stageKey || record.stageId || record.atividade || 'Etapa não informada');
  };
  const query = input.selectedStage.toLocaleLowerCase('pt-BR');
  const matchesStage = (stage: OperationalStage) => String(stage.id) === input.selectedStage ||
    String(stage.key || '').toLocaleLowerCase('pt-BR') === query || stage.name.toLocaleLowerCase('pt-BR') === query;
  const filteredRecords = input.records.filter(record => {
    if (input.limitedActor && (!input.actorName || String(record.responsavel || '').trim()
      .localeCompare(input.actorName, 'pt-BR', { sensitivity: 'base' }) !== 0)) return false;
    if (!input.selectedStage) return true;
    const matchesRecordStage = (stage: OperationalStage) => String(record.stageId ?? '') === String(stage.id) ||
      String(record.stageKey || '').toLocaleLowerCase('pt-BR') === String(stage.key || '').toLocaleLowerCase('pt-BR') ||
      [record.etapa, record.stage].some(value => String(value || '').toLocaleLowerCase('pt-BR') === stage.name.toLocaleLowerCase('pt-BR'));
    if ([record.stageId, record.stageKey, record.etapa, record.stage, record.atividade]
      .some(value => String(value ?? '').toLocaleLowerCase('pt-BR') === query)) return true;
    if (input.stages.some(stage => matchesStage(stage) && (matchesRecordStage(stage) || String(record.atividade || '') === stage.name))) return true;
    const activities = input.stages.flatMap(stage => stage.activities || []).filter(activity =>
      String(activity.id).toLocaleLowerCase('pt-BR') === query || activity.name.toLocaleLowerCase('pt-BR') === query);
    return activities.some(activity => String(record.activityId || '').toLocaleLowerCase('pt-BR') === String(activity.id).toLocaleLowerCase('pt-BR') ||
      String(record.atividade || '').toLocaleLowerCase('pt-BR') === activity.name.toLocaleLowerCase('pt-BR'));
  }).slice().sort((a, b) => `${b.data || ''}T${b.hora || '00:00'}`.localeCompare(`${a.data || ''}T${a.hora || '00:00'}`));
  const records = filteredRecords.map(record => ({
    record,
    stageName: stageName(record),
    completed: /concl|final|feito/i.test(String(record.status || '')),
  }));
  const selected = records.find(item => String(item.record.id) === input.selectedId) || null;
  const completedCount = records.filter(item => item.completed).length;
  const stage = input.stages.find(item => String(item.id) === input.selectedStage || String(item.key || '') === input.selectedStage || item.name === input.selectedStage);
  return {
    records,
    selected,
    headingScope: input.selectedStage ? stage?.name || input.selectedStage : '',
    completedCount,
    pendingCount: Math.max(0, records.length - completedCount),
    stageCount: new Set(records.map(item => item.stageName)).size,
  };
}

