/** Keep every operational record form on the same authenticated persistence and response owner. */
export function createAtlasOperationalRecordServiceV1(
  persist: (payload: OperationalRecordCreateInputV1) => Promise<unknown>,
): (payload: OperationalRecordCreateInputV1) => Promise<AtlasOperationalRecordCreateResultV1> {
  return async payload => {
    const envelope = mapRecord(await persist(payload)) || {};
    const record = mapRecord(envelope.record) || envelope;
    return {
      id: String(record.id || envelope.id || ''),
      record: record as Partial<OperationalRecord> & Record<string, unknown>,
    };
  };
}

