export const ATLAS_DASHBOARD_RECORD_ATTACHMENT_MAX_BYTES_V1 = 6 * 1024 * 1024;

export interface AtlasDashboardRecordDraftV1 {
  stageId: string;
  activityId: string;
  date: string;
  time: string;
  responsible: string;
  detail: string;
  status: string;
  evidenceSizeBytes?: number;
}

export type AtlasDashboardRecordSubmissionV1 =
  | { status: 'ready'; payload: AtlasOperationalRecordSubmissionV1 }
  | { status: 'invalid'; reason: 'stage-activity' | 'required-fields' | 'attachment-too-large' };

/** Validate a dashboard record draft and build the canonical diary payload. */
export function projectAtlasDashboardRecordSubmissionV1(
  stages: OperationalStage[],
  draft: AtlasDashboardRecordDraftV1,
): AtlasDashboardRecordSubmissionV1 {
  const stage = stages.find(item => String(item.id) === String(draft.stageId || ''));
  const activity = stage?.activities?.find(item => item.id === String(draft.activityId || ''));
  if (!stage || !activity) return { status: 'invalid', reason: 'stage-activity' };
  const date = String(draft.date || ''), time = String(draft.time || ''), detail = String(draft.detail || '').trim();
  if (!date || !time || !detail) return { status: 'invalid', reason: 'required-fields' };
  if (Number(draft.evidenceSizeBytes) > ATLAS_DASHBOARD_RECORD_ATTACHMENT_MAX_BYTES_V1) {
    return { status: 'invalid', reason: 'attachment-too-large' };
  }
  return {
    status: 'ready',
    payload: {
      obra: 'Aliança Park', etapa: stage.name, stageKey: stage.key || '', stageId: stage.id,
      activityId: activity.id, atividade: activity.name, data: date, hora: time,
      responsavel: String(draft.responsible || '').trim(), detalhes: detail,
      status: String(draft.status || 'Pendente'),
    },
  };
}

export type AtlasDashboardQuickRecordSubmissionV1 =
  | { status: 'ready'; stageName: string; activity: string; payload: Record<string, unknown> }
  | { status: 'invalid'; reason: 'stage-activity' };

/** Build the quick-dashboard diary command without losing its free-text activity flow. */
export function buildAtlasDashboardQuickRecordSubmissionV1(input: {
  stage: { key?: unknown; name?: unknown } | null | undefined;
  values: Record<string, unknown>;
  now: Date;
}): AtlasDashboardQuickRecordSubmissionV1 {
  const stageName = String(input.stage?.name || '').trim();
  const activity = String(input.values.activity || '').trim();
  if (!input.stage || !stageName || !activity) return { status: 'invalid', reason: 'stage-activity' };
  return {
    status: 'ready',
    stageName,
    activity,
    payload: {
      obra: 'Aliança Park',
      etapa: stageName,
      stageKey: String(input.stage.key || ''),
      atividade: activity,
      data: String(input.values.date || ''),
      hora: input.now.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
      responsavel: String(input.values.responsible || 'A definir').trim() || 'A definir',
      detalhes: String(input.values.detail || `Registro operacional: ${activity}`).trim(),
      status: 'Pendente',
      properties: [{ label: 'Origem', value: 'Registro rápido do Dashboard' }],
    },
  };
}

/** Normalize persisted dashboard rows before the component turns them into table markup. */
export interface AtlasDashboardSnapshotSourcesV1 {
  cashFlow: unknown;
  stages: unknown;
  records: unknown;
  notifications: unknown;
  agenda: unknown;
  materials: unknown;
  repasses: unknown;
  lotStatuses?: Record<string, AtlasLotStatus | undefined>;
}

/** Validate canonical dashboard responses and project them into the component snapshot. */
export function projectAtlasDashboardSnapshotV1(input: AtlasDashboardSnapshotSourcesV1): DashboardSnapshot {
  const record = (value: unknown): Record<string, unknown> =>
    value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const cash = record(input.cashFlow);
  const cashSummary = record(cash.summary);
  const stages = input.stages && typeof input.stages === 'object' ? (input.stages as Record<string, unknown>).stages : null;
  const records = input.records && typeof input.records === 'object' ? (input.records as Record<string, unknown>).records : null;
  const notifications = input.notifications && typeof input.notifications === 'object' ? (input.notifications as Record<string, unknown>).notifications : null;
  const agenda = input.agenda && typeof input.agenda === 'object' ? (input.agenda as Record<string, unknown>).events : null;
  const materials = input.materials && typeof input.materials === 'object' ? (input.materials as Record<string, unknown>).materials : null;
  const repasses = input.repasses && typeof input.repasses === 'object' ? input.repasses as Record<string, unknown> : {};
  const cashBalanceCents = Number(cashSummary.balanceCents);
  if (!Number.isFinite(cashBalanceCents) || !Array.isArray(cash.entries) || !Array.isArray(stages) ||
      !Array.isArray(records) || !Array.isArray(notifications) || !Array.isArray(agenda) || !Array.isArray(materials) ||
      !Array.isArray(repasses.sales) || !Array.isArray(repasses.entries) || !Array.isArray(repasses.brokerRules) ||
      !Array.isArray(repasses.reasons)) throw new Error('Resposta inválida ao compor a Central de operação.');
  return {
    cashBalanceCents,
    cashEntries: cash.entries as CashFlowRecord[],
    stages: stages as OperationalStage[],
    records: records as OperationalRecord[],
    notifications: notifications as OperationalNotification[],
    agendaEvents: agenda as OperationalAgendaEvent[],
    materials: materials as OperationalMaterial[],
    repasses: repasses as unknown as RepasseOperations,
    commercialInterestCount: null,
    commercialInterestState: 'loading',
    lotAnalysis: projectAtlasDashboardLotAnalysis(projectAtlasLotBoardRows(input.lotStatuses || {})),
  };
}

/** Return the low-PII commercial interest count only for a valid repository summary. */
export function projectAtlasDashboardCommercialInterestV1(value: unknown): number | null {
  const summary = value && typeof value === 'object' ? value as Partial<PublicCommercialSummary> : null;
  if (!summary || !Number.isInteger(summary.leadCount) || Number(summary.leadCount) < 0 ||
      !Number.isInteger(summary.reservationCount) || Number(summary.reservationCount) < 0 || summary.source !== 'github') return null;
  return Number(summary.leadCount) + Number(summary.reservationCount);
}

