/** Read a material-transition form into the typed draft consumed by the program. */
export function buildAtlasMaterialTransitionDraftV1(input: {
  values: Record<string, unknown>;
  files: readonly File[];
}): AtlasMaterialTransitionDraftV1 {
  const { values } = input;
  return {
    name: String(values.name || ''),
    materialNumber: String(values.materialNumber || ''),
    stageId: String(values.stageId || ''),
    activityName: String(values.activityName || ''),
    quantity: String(values.quantity || ''),
    unit: String(values.unit || ''),
    status: String(values.status || ''),
    description: String(values.description || ''),
    documentNumber: String(values.documentNumber || ''),
    documentDescription: String(values.documentDescription || ''),
    files: [...input.files],
  };
}

export type AtlasMaterialTransitionCommandProjectionV1 =
  | { ok: true; stage: OperationalStage; after: Omit<AtlasMaterialTransitionDraftV1, 'stageId' | 'quantity' | 'files'> & { stageId: number; quantity: number; files: File[] } }
  | { ok: false; error: string };

/** Validate and normalize the material transition form against the current persisted stage catalog. */
export function projectAtlasMaterialTransitionCommandV1(
  draft: AtlasMaterialTransitionDraftV1,
  stages: readonly OperationalStage[],
): AtlasMaterialTransitionCommandProjectionV1 {
  const files = Array.isArray(draft?.files) ? [...draft.files] : [];
  if (files.length > 3 || files.some(file => file.size > 6 * 1024 * 1024 || ![/^application\/pdf$/, /^image\/(jpeg|png|webp)$/].some(pattern => pattern.test(file.type)))) {
    return { ok: false, error: 'Anexe até 3 comprovantes PDF/JPEG/PNG/WebP de até 6 MB cada.' };
  }
  const after = {
    name: String(draft?.name || '').trim(),
    materialNumber: String(draft?.materialNumber || '').trim(),
    stageId: Number(draft?.stageId),
    activityName: String(draft?.activityName || '').trim(),
    quantity: Number(draft?.quantity),
    unit: String(draft?.unit || '').trim(),
    status: String(draft?.status || '').trim(),
    description: String(draft?.description || '').trim(),
    documentNumber: String(draft?.documentNumber || '').trim(),
    documentDescription: String(draft?.documentDescription || '').trim(),
    files,
  };
  if (!after.name || !after.materialNumber || !Number.isFinite(after.quantity) || after.quantity < 0 || !after.description) {
    return { ok: false, error: 'Informe nome, número, quantidade válida e descrição da mudança.' };
  }
  const stage = (Array.isArray(stages) ? stages : []).find(item => item.id === after.stageId);
  if (!stage) return { ok: false, error: 'Selecione uma etapa operacional existente.' };
  return { ok: true, stage, after };
}

