/** Keep material filtering, paging, stage joins, and persisted-history joins together. */
export function projectAtlasMaterialsPageV1(input: AtlasMaterialsPageProjectionInputV1): AtlasMaterialsPageProjectionV1 {
  const query = String(input.query || '').trim().toLocaleLowerCase('pt-BR');
  const rows = input.materials.filter(item => (input.activeStage === 'inventory' || item.stageId === input.activeStage)
    && (input.statusFilter === 'all' || item.status === input.statusFilter)
    && (!query || [item.name, item.unit, item.status, item.stageName, item.activityName, item.scope, ...Object.values(item.properties || {})]
      .some(value => String(value || '').toLocaleLowerCase('pt-BR').includes(query))));
  const pages = Math.max(1, Math.ceil(rows.length / 15));
  const page = Math.min(input.page, pages);
  const visible = rows.slice((page - 1) * 15, page * 15);
  const selected = input.editing && typeof input.editing === 'object' ? input.editing : null;
  const formOpen = input.editing !== false;
  const baseColumns: Array<[string, string]> = [
    ...input.presentation.columns.map(([id, label]) => [id, label] as [string, string]),
    ...input.columns.map(column => [column.id, column.label] as [string, string]),
    ['updatedAt', 'Última alteração'],
  ];
  const shownColumns = baseColumns.filter(([id]) => !input.hiddenColumns.includes(id));
  const statusLabel = (value: string) => input.presentation.statusLabels[value.toLocaleLowerCase('pt-BR')] || value;
  const tableRows = visible.map(item => ({
    item,
    cells: shownColumns.map(([key]) => {
      const value = key.startsWith('material-property-') ? item.properties?.[key]
        : key === 'stageId' ? item.stageName
          : key === 'status' ? statusLabel(item.status)
            : key === 'id' ? item.id
              : key === 'updatedAt' && item.updatedAt ? new Date(item.updatedAt).toLocaleString('pt-BR')
                : (item as unknown as Record<string, unknown>)[key];
      return { key, value: value == null || value === '' ? '—' : value };
    }),
  }));
  const stageAllocations = input.stages.map(stage => ({
    stage,
    selected: input.activeStage === stage.id,
    allocatedCount: input.materials.filter(item => item.stageId === stage.id).length,
    agenda: input.agenda.filter(event => String(event.stageKey || '') === String(stage.key || '')
      || String(event.stageName || '').toLocaleLowerCase('pt-BR') === stage.name.toLocaleLowerCase('pt-BR')),
    agendaPreview: input.agenda.filter(event => String(event.stageKey || '') === String(stage.key || '')
      || String(event.stageName || '').toLocaleLowerCase('pt-BR') === stage.name.toLocaleLowerCase('pt-BR')).slice(0, 5),
  }));
  const canvasMaterials = rows.map(material => ({
    material,
    documents: input.documents.filter(document => document.sourceMaterialId === material.id),
    statusLabel: statusLabel(material.status),
    stageLabel: material.stageName || 'Sem etapa',
  }));
  const history = input.transitionHistory.map(record => {
    const properties = Array.isArray(record.properties) ? record.properties as Array<{ id: string; value: string }> : [];
    const get = (id: string): string => properties.find(item => item.id === id)?.value || '';
    let documentIds: string[] = [];
    try { documentIds = JSON.parse(get('document_ids')) as string[]; } catch { documentIds = []; }
    return {
      record,
      beforeQuantity: get('before_quantity'),
      beforeUnit: get('before_unit'),
      afterQuantity: get('after_quantity'),
      afterUnit: get('after_unit'),
      afterDescription: get('after_description'),
      documents: input.transitionAttachments.filter(file => documentIds.includes(String(file.id))),
    };
  });
  const transitionStage = input.transition?.stageId
    ? input.stages.find(stage => stage.id === input.transition!.stageId) || null
    : null;
  const selectedStageOptionId = selected ? Number(selected.stageId)
    : input.transition ? Number(input.transition.stageId) : null;
  const stageOptions = input.stages.map(stage => ({ stage, selected: selectedStageOptionId === stage.id }));
  return {
    rows,
    pages,
    page,
    visible,
    selected,
    formOpen,
    baseColumns,
    shownColumns,
    tableRows,
    stageOptions,
    stageAllocations,
    canvasMaterials,
    history,
    transitionStage,
    selectedStageOptionId,
    statusOptions: [...new Set(input.materials.map(item => item.status))].map(value => ({
      value,
      label: input.presentation.statusLabels[value.toLocaleLowerCase('pt-BR')] || value,
      selected: input.statusFilter === value,
    })),
  };
}

