export type AtlasAgendaEventPayloadV1 =
  | { ok: true; payload: OperationalAgendaEvent }
  | { ok: false; error: string };

/** Build and validate an agenda form command before the component dispatches it. */
export function buildAtlasAgendaEventPayloadV1(input: {
  values: AtlasAgendaEventFormValuesV1;
  stages: OperationalStage[];
  existingEvents: OperationalAgendaEvent[];
  createId(): string;
  nowIso(): string;
}): AtlasAgendaEventPayloadV1 {
  const values = input.values;
  const stageName = String(values.stageKey || ''), stage = input.stages.find(item => item.name === stageName);
  const activityId = String(values.activityId || ''), activity = stage?.activities?.find(item => item.id === activityId);
  const lines = (value: unknown): string[] => String(value || '').split(/\r?\n/).map(item => item.trim()).filter(Boolean);
  const payload: OperationalAgendaEvent = {
    id: String(values.id || input.createId()),
    title: String(values.title || '').trim(),
    stageKey: stageName,
    stageName,
    activityId,
    activityName: activity?.name || '',
    owner: String(values.owner || '').trim(),
    date: String(values.date || ''),
    start: String(values.start || '08:00'),
    durationHours: Number(values.durationHours || 1.5),
    spanDays: Number(values.spanDays || 1),
    status: String(values.status || 'Planejado'),
    relatedFrom: String(values.relatedFrom || ''),
    notes: String(values.notes || '').trim(),
    materialIds: Array.isArray(values.materialIds) ? values.materialIds.map(String) : [],
    customStatus: String(values.customStatus || '').trim(),
    requirements: lines(values.requirements),
    materials: lines(values.materials),
    cancellationReason: String(values.cancellationReason || '').trim(),
    cancellationConfirmed: values.cancellationConfirmed === true,
    notificationOffsetMinutes: Number(values.notificationOffsetMinutes ?? 30),
    mapAreas: (Array.isArray(values.mapAreas) ? values.mapAreas : []).map(projectAtlasMapProgressArea).filter((area): area is AtlasMapProgressArea => Boolean(area)),
  };
  const normalizeStatus = (value: unknown): string => String(value || '').toLocaleLowerCase('pt-BR')
    .normalize('NFD').replace(/[\u0300-\u034f]/g, '').replaceAll('_', ' ').trim();
  const cancelled = normalizeStatus(payload.status) === normalizeStatus('Anulado');
  const previous = input.existingEvents.find(item => item.id === payload.id);
  if (cancelled && !payload.cancellationConfirmed)
    return { ok: false, error: 'Marque a confirmação antes de cancelar o compromisso.' };
  payload.cancelledAt = cancelled ? previous?.cancelledAt || input.nowIso() : '';
  if (!cancelled) {
    payload.cancellationReason = '';
    payload.cancellationConfirmed = false;
    if (normalizeStatus(payload.customStatus) === normalizeStatus('Anulado')) payload.customStatus = '';
  }
  const reminder = Number(payload.notificationOffsetMinutes);
  if (!payload.title || !payload.date || !Number.isFinite(payload.durationHours) || payload.durationHours < 0.5
    || payload.durationHours > 24 || !Number.isInteger(payload.spanDays) || payload.spanDays < 1 || payload.spanDays > 366
    || !Number.isFinite(reminder) || reminder < 0 || reminder > 1440)
    return { ok: false, error: 'Revise título, data, duração e antecedência do lembrete.' };
  return { ok: true, payload };
}

export type AtlasAgendaStatusTransitionV1 =
  | { ok: true; payload: OperationalAgendaEvent }
  | { ok: false; error: string };

/** Build the canonical agenda payload for the completion control. */
export function buildAtlasAgendaCompletionPayloadV1(input: {
  source: OperationalAgendaEvent;
  nowIso(): string;
}): AtlasAgendaStatusTransitionV1 {
  return {
    ok: true,
    payload: {
      ...input.source,
      status: 'Concluído',
      customStatus: 'Concluído',
      cancellationReason: '',
      cancelledAt: '',
      cancellationConfirmed: false,
      updatedAt: input.nowIso(),
    },
  };
}

/** Validate cancellation confirmation and build its canonical agenda payload. */
export function buildAtlasAgendaCancellationPayloadV1(input: {
  source: OperationalAgendaEvent;
  cancellationReason: unknown;
  cancellationConfirmed: boolean;
  nowIso(): string;
}): AtlasAgendaStatusTransitionV1 {
  if (!input.cancellationConfirmed)
    return { ok: false, error: 'Marque a confirmação antes de cancelar o compromisso.' };
  const timestamp = input.nowIso();
  return {
    ok: true,
    payload: {
      ...input.source,
      status: 'Anulado',
      customStatus: 'Anulado',
      cancellationReason: String(input.cancellationReason || '').trim(),
      cancelledAt: timestamp,
      cancellationConfirmed: true,
      updatedAt: timestamp,
    },
  };
}

export type AtlasAgendaRecordPayloadV1 =
  | { ok: true; activity: string; payload: AtlasOperationalRecordSubmissionV1 }
  | { ok: false; error: string };

/** Build the operational diary command linked to the selected agenda event. */
export function buildAtlasAgendaRecordPayloadV1(input: {
  source: OperationalAgendaEvent;
  stageName: string;
  details: unknown;
  date: unknown;
  time: unknown;
  responsible: unknown;
  status: unknown;
}): AtlasAgendaRecordPayloadV1 {
  const details = String(input.details || '').trim();
  if (!input.stageName || !details)
    return { ok: false, error: 'Informe o relato e selecione uma etapa operacional existente.' };
  const activity = input.source.activityName || input.source.title;
  return {
    ok: true,
    activity,
    payload: {
      obra: 'Aliança Park',
      etapa: input.stageName,
      stageKey: input.source.stageKey,
      atividade: activity,
      data: String(input.date || input.source.date),
      hora: String(input.time || input.source.start || ''),
      responsavel: String(input.responsible || input.source.owner || 'A definir').trim() || 'A definir',
      detalhes: details,
      status: String(input.status || 'Pendente'),
      properties: [
        { label: 'Origem', value: `Agenda operacional · ${activity}` },
        { label: 'ID da atividade', value: input.source.id },
      ],
    },
  };
}

