/** Typed, normalized command produced by chat/OCR inference before agenda persistence. */
export interface AtlasAgendaPendingProposalV1 {
  title: string;
  date: string;
  start: string;
  stageKey: string;
  stageName: string;
  activityId: string;
  activityName: string;
  owner: string;
  durationHours: number;
  spanDays: number;
  notes: string;
  materialIds: string[];
  detailsNeeded: string;
  evidenceRequired: boolean;
}

