export interface AtlasAgendaDataRefreshInputV1 {
  events: OperationalAgendaEvent[];
  stages: OperationalStage[];
  materials: OperationalMaterial[];
  focusDate: string;
  selectedEventId: string;
  focusWeek: string;
  detailMode: boolean;
  notificationsEnabled: boolean;
  previousWeek: string;
  previousSelectedDate: string;
  previousEditor: OperationalAgendaEvent | null | false;
  previousRelatedFrom: string;
  now?: Date;
}

export interface AtlasAgendaDataRefreshProjectionV1 {
  events: OperationalAgendaEvent[];
  stages: OperationalStage[];
  materials: OperationalMaterial[];
  week: string;
  selectedDate: string;
  editor: OperationalAgendaEvent | null | false;
  relatedFrom: string;
  detailMode: boolean;
  notificationsEnabled: boolean;
}

/** Normalize agenda data and resolve the route's date, week, and focused event. */
export function projectAtlasAgendaDataRefreshV1(input: AtlasAgendaDataRefreshInputV1): AtlasAgendaDataRefreshProjectionV1 {
  const iso = (date: Date): string => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  const plusDays = (value: string, count: number): string => {
    const date = new Date(`${value}T12:00:00`);
    date.setDate(date.getDate() + count);
    return iso(date);
  };
  const ordered = [...input.events].filter(event => /^\d{4}-\d{2}-\d{2}$/.test(event.date))
    .sort((left, right) => `${left.date}T${left.start || '00:00'}`.localeCompare(`${right.date}T${right.start || '00:00'}`));
  const isDate = (value: string): boolean => /^\d{4}-\d{2}-\d{2}$/.test(value)
    && iso(new Date(`${value}T12:00:00`)) === value;
  const focusedEvent = input.selectedEventId ? ordered.find(event => event.id === input.selectedEventId) || null : null;
  const requestedDate = isDate(input.focusDate) ? input.focusDate : focusedEvent?.date || '';
  const requestedWeek = isDate(input.focusWeek) ? input.focusWeek : requestedDate;
  let week = input.previousWeek;
  if (requestedWeek) {
    const date = new Date(`${requestedWeek}T12:00:00`);
    date.setDate(date.getDate() - date.getDay());
    week = iso(date);
  } else if (!ordered.some(event => event.date >= week && event.date < plusDays(week, 7)) && ordered.length) {
    const now = input.now || new Date();
    const nearest = [...ordered].sort((left, right) => Math.abs(Date.parse(`${left.date}T12:00:00`) - now.getTime())
      - Math.abs(Date.parse(`${right.date}T12:00:00`) - now.getTime()))[0];
    const date = new Date(`${nearest.date}T12:00:00`);
    date.setDate(date.getDate() - date.getDay());
    week = iso(date);
  }
  const selectedDate = requestedDate || (input.previousSelectedDate < week || input.previousSelectedDate >= plusDays(week, 7)
    ? week
    : input.previousSelectedDate);
  const previousEditor = input.previousEditor;
  const editor = input.selectedEventId
    ? focusedEvent || false
    : previousEditor && typeof previousEditor === 'object'
      ? ordered.find(event => event.id === previousEditor.id) || false
      : previousEditor;
  return {
    events: ordered,
    stages: input.stages,
    materials: input.materials,
    week,
    selectedDate,
    editor,
    relatedFrom: focusedEvent?.relatedFrom || input.previousRelatedFrom,
    detailMode: input.detailMode,
    notificationsEnabled: input.notificationsEnabled,
  };
}

/** Read and persist one AI-proposed pending commitment against the canonical agenda snapshot. */
export async function createAtlasWorkerAgendaPendingV1(input: {
  proposal: AtlasAgendaPendingProposalV1;
  state: AtlasWorkerAgendaPendingStateV1;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
  setLocalStorage(key: string, value: string): void;
  now(): number;
  today?: Date;
}): Promise<AtlasWorkerAgendaPendingCreationV1> {
  let events: OperationalAgendaEvent[];
  try {
    const response = await input.apiFetch('/api/agenda-events', { cache: 'no-store' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const value = await response.json().catch(() => null) as { events?: unknown } | null;
    if (!Array.isArray(value?.events)) throw new Error('Agenda inválida.');
    events = value.events as OperationalAgendaEvent[];
  } catch (error) {
    return { ok: false, phase: 'read', error: error instanceof Error ? error.message : String(error) };
  }

  const today = input.today || new Date();
  const proposal = input.proposal;
  const dateValue = proposal.date;
  const parsedDate = dateValue ? new Date(`${dateValue}T12:00:00`) : null;
  const date = parsedDate && Number.isFinite(parsedDate.getTime())
    ? dateValue
    : `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
  const sameDay = events.filter(event => String(event.date || '') === date);
  const toMinutes = (value: unknown): number => {
    const match = String(value || '').match(/^(\d{2}):(\d{2})$/);
    return match ? Number(match[1]) * 60 + Number(match[2]) : 0;
  };
  const requestedStart = proposal.start;
  const latest = sameDay.reduce((max, event) => Math.max(max, toMinutes(event.start) + Math.round((Number(event.durationHours) || 1) * 60)), 8 * 60);
  const slotMinutes = /^\d{2}:\d{2}$/.test(requestedStart)
    ? toMinutes(requestedStart)
    : Math.min(18 * 60, Math.max(8 * 60, Math.ceil(latest / 30) * 30));
  const start = `${String(Math.floor(slotMinutes / 60)).padStart(2, '0')}:${String(slotMinutes % 60).padStart(2, '0')}`;
  const stageKey = String(proposal.stageKey || '').trim();
  const stageName = String(proposal.stageName || '').trim();
  const event = projectAtlasAgendaPendingEventV1({
    proposal,
    id: `agenda-worker-ai-${input.now().toString(36)}`,
    stageKey,
    stageName,
    date,
    start,
  });

  try {
    const response = await input.apiFetch('/api/agenda-events', {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ events: [...events, event] }),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const value = await response.json().catch(() => null) as { events?: unknown } | null;
    if (!Array.isArray(value?.events)) throw new Error('A agenda não confirmou os compromissos salvos.');
    const savedEvents = value.events as OperationalAgendaEvent[];
    input.setLocalStorage('belavista.agenda-calendar.v3', JSON.stringify({ version: 3, initialized: true, events: savedEvents }));
    return { ok: true, event, events: savedEvents };
  } catch (error) {
    return { ok: false, phase: 'write', error: error instanceof Error ? error.message : String(error) };
  }
}

/** Apply one agenda-create command and return the UI state patch to its caller. */
export async function applyAtlasAgendaPendingCommandV1(input: {
  args: unknown;
  state: AtlasAgendaPendingCommandStateV1;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
  setLocalStorage(key: string, value: string): void;
  now(): number;
  executionStages?: readonly AtlasAgendaCalendarStageV1[];
  normalizeActivityRouteText?: (value: unknown) => string;
}): Promise<AtlasAgendaPendingCommandResultV1> {
  if (!normalizeAiAgendaComprehensionV1(input.state.aiAgendaComprehensionV1).autoCreatePending)
    return { ok: false, message: 'Apontamento não criado: geração pela IA desativada em Configurações.' };

  const catalog = resolveAtlasAgendaPendingCatalogV1({
    proposal: normalizeAtlasAgendaPendingProposalV1(input.args),
    executionStages: input.executionStages || [],
    normalizeActivityRouteText: input.normalizeActivityRouteText,
  });
  if (!catalog.ok)
    return { ok: false, message: `Apontamento não criado: ${catalog.message}` };

  const creation = await createAtlasWorkerAgendaPendingV1({
    proposal: catalog.proposal,
    state: input.state,
    apiFetch: input.apiFetch,
    setLocalStorage: input.setLocalStorage,
    now: input.now,
  });
  if (!creation.ok) {
    const action = creation.phase === 'read' ? 'carregar a agenda' : 'salvar na agenda';
    return { ok: false, message: `Apontamento não criado: não foi possível ${action} (${creation.error}).` };
  }

  const { event } = creation;
  const { id, stageKey, stageName, title, start } = event;
  const agendaItem = projectAtlasAgendaCalendarItemV1(event);
  const currentAgenda = Array.isArray(input.state.operationalAgenda)
    ? input.state.operationalAgenda as Array<Record<string, unknown>>
    : [];
  return {
    ok: true,
    message: `Apontamento pendente criado na agenda${stageName ? ` de ${stageName}` : ''}; complete os detalhes solicitados.`,
    statePatch: {
      view: 'agenda',
      ...(stageKey ? { selectedStageV9: stageKey, selectedStage: stageKey } : {}),
      selectedAgendaEventV3: id,
      operationalAgenda: [...currentAgenda.filter(item => String(item?.id || '') !== id), agendaItem],
      agendaCalendarRevisionV3: input.now(),
      agendaCalendarRevisionV7: input.now(),
      lastAction: `Assistente dos workers criou apontamento pendente ${title}`,
    },
  };
}

