export interface AtlasAgendaCalendarProgramV1 extends AtlasAgendaCalendarSharedServicesV1 {
  agendaCalendarPadV3: (value: string | number) => string;
  agendaCalendarMonthKeyV3: (date: Date) => string;
  agendaCalendarAddDaysV3: (value: Date | string, days: number) => string;
  agendaCalendarTimeToHoursV3: (value: unknown) => number;
  agendaCalendarHoursToTimeV3: (hours: number) => string;
  agendaCalendarMonthLabelV3: (key: string) => string;
  agendaCalendarShiftMonthV3: (key: string, delta: number) => string;
  agendaCalendarMonthDaysV3: (key: string) => Date[];
  agendaCalendarWeekStartV8: (value: Date | string) => Date;
  agendaCalendarShiftWeekV8: (weekKey: string, delta: number) => string;
  agendaCalendarNavigateWeekStateV8: (weekKey: string, delta: number, recordAction?: boolean) => void;
  agendaCalendarSelectWeekStateV8: (date: unknown, options?: { validate?: boolean; recordAction?: boolean }) => boolean;
  agendaCalendarSetPresentationV1: (presentation: unknown) => boolean;
  agendaCalendarLastAvailableSlotV8: (events: OperationalAgendaEvent[], weekKey: string) => AtlasAgendaCalendarSlotV1;
  agendaCalendarWriteV3: (data: { version?: 3; initialized?: boolean; events?: OperationalAgendaEvent[] }) => Promise<OperationalAgendaEvent[]>;
  ensureAgendaCalendarLoadedV8: () => void;
  agendaCalendarSaveEventV1: (draft: AtlasAgendaCalendarEventDraftV1) => Promise<AtlasAgendaCalendarEventSaveResultV1>;
  agendaCalendarSaveInlineEditorEventV1: (draft: AtlasAgendaCalendarInlineEditorDraftV1) => Promise<AtlasAgendaCalendarEventSaveResultV1>;
  agendaCalendarDeleteEventV1: (id: unknown) => Promise<OperationalAgendaEvent[]>;
  agendaCalendarSaveGestureEventV1: (input: AtlasAgendaCalendarGestureEventDraftV1) => Promise<OperationalAgendaEvent[]>;
  agendaCalendarFindStageV3: (value: unknown) => AtlasAgendaCalendarStageV1 | null;
  agendaCalendarActivitiesForStageV3: (stageKey: unknown, stageName?: string) => AtlasAgendaCalendarActivityV1[];
  agendaCalendarDemoEventsV3: (stage?: AtlasAgendaCalendarStageV1 | null) => Array<Record<string, unknown>>;
  agendaCalendarStateV3: (state: Record<string, unknown>, stage?: AtlasAgendaCalendarStageV1 | null) => AgendaCalendarSnapshotV3;
  agendaCalendarInitialMonthV3: (state: Record<string, unknown>, data: { events: OperationalAgendaEvent[] }) => string;
  agendaCalendarEventEndV3: (event: Partial<OperationalAgendaEvent>) => number;
  agendaCalendarLastAvailableSlotV3: (events: OperationalAgendaEvent[], monthKey: string) => AtlasAgendaCalendarSlotV1;
  agendaCalendarStatusToneV3: (status: unknown) => 'done' | 'active' | 'warning' | 'planned';
  agendaCalendarPointerHoursV1: (offsetPx: number, options: { grabOffsetPx?: number; minimumPx: number; maximumPx: number; pixelsPerHour: number; minimumHours: number; maximumHours: number }) => number;
  agendaCalendarNormalizePreviewV7: (source: Partial<OperationalAgendaEvent>) => Partial<OperationalAgendaEvent>;
  agendaCalendarPreviewFromPointerV7: (source: Partial<OperationalAgendaEvent>, mode: AtlasAgendaCalendarPointerModeV1, input: AtlasAgendaCalendarPointerPreviewInputV1) => Partial<OperationalAgendaEvent>;
}

/** Complete typed return contract for the administrative agenda component installer. */
export interface AtlasAgendaCalendarPageServicesV1 extends AtlasAgendaCalendarProgramV1 {
  AGENDA_CALENDAR_STORAGE_KEY_V3: string;
  AGENDA_CALENDAR_PIXELS_PER_HOUR_V6: number;
  AGENDA_CALENDAR_HALF_HOUR_PIXELS_V6: number;
  AGENDA_CALENDAR_DAY_BODY_HEIGHT_V6: number;
  agendaCalendarEventMarkupV3: (event: Partial<OperationalAgendaEvent>, weekdayIndex: number) => string;
  agendaCalendarFormMarkupV3: (
    stage: AtlasAgendaCalendarStageV1 | null | undefined,
    data: AgendaCalendarSnapshotV3,
    slot: AtlasAgendaCalendarSlotV1,
    weekKey: string,
  ) => string;
  agendaCalendarMarkupV3: (stage: AtlasAgendaCalendarStageV1 | null | undefined) => string;
}

export type AtlasAgendaCalendarPointerModeV1 = 'move' | 'start-hours' | 'end-hours' | 'start-days' | 'end-days';

export interface AtlasAgendaCalendarPointerPreviewInputV1 {
  date?: string;
  startHours?: number;
  pointerHours?: number;
}

export interface AtlasAgendaCalendarGestureEventDraftV1 {
  id: unknown;
  date: unknown;
  start: unknown;
  durationHours: unknown;
  spanDays: unknown;
}

/** Keep agenda date math, event projections, and persistence in the program monolith. */
export function createAtlasAgendaCalendarProgramV1(ports: AtlasAgendaCalendarProgramPortsV1): AtlasAgendaCalendarProgramV1 {
  const now = ports.now || (() => new Date());
  const executionStages = [...(ports.executionStages || [])];
  const workbenchStages = ports.workbenchStages || [];
  const administrativeDestinations = (stageDestinationsCatalogData as { destinations?: Array<{ key?: string; name?: string; description?: string }> }).destinations || [];
  for (const destination of administrativeDestinations) {
    const key = String(destination.key || '').trim(), name = String(destination.name || '').trim();
    if (!key || !name || executionStages.some(stage => String(stage.key || '').toLocaleLowerCase('pt-BR') === key.toLocaleLowerCase('pt-BR')
      || String(stage.name || '').toLocaleLowerCase('pt-BR') === name.toLocaleLowerCase('pt-BR'))) continue;
    executionStages.push({ key, name, owner: 'Equipe administrativa', description: destination.description || 'Destino administrativo.' });
  }
  const pad = (value: string | number): string => String(value).padStart(2, '0');
  const iso = (date: Date): string => `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
  const monthKey = (date: Date): string => `${date.getFullYear()}-${pad(date.getMonth() + 1)}`;
  const parseDate = (value: unknown): Date | null => {
    const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (!match) return null;
    const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    return Number.isFinite(date.getTime()) ? date : null;
  };
  const addDays = (value: Date | string, days: number): string => {
    const date = value instanceof Date
      ? new Date(value.getFullYear(), value.getMonth(), value.getDate())
      : parseDate(value);
    if (!date) return String(value || '');
    date.setDate(date.getDate() + Number(days || 0));
    return iso(date);
  };
  const timeToHours = (value: unknown): number => {
    const [hour = 0, minute = 0] = String(value || '08:00').split(':').map(Number);
    return Math.max(0, Math.min(23.5, hour + minute / 60));
  };
  const hoursToTime = (hours: number): string => {
    const value = Math.max(0, Math.min(23.5, Number(hours) || 0));
    const total = Math.round(value * 2) * 30;
    return `${pad(Math.floor(total / 60))}:${pad(total % 60)}`;
  };
  const monthLabel = (key: string): string => {
    const [year, month] = String(key || '').split('-').map(Number);
    return new Date(year || 2024, Math.max(0, (month || 1) - 1), 1).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
  };
  const shiftMonth = (key: string, delta: number): string => {
    const [year, month] = String(key || '').split('-').map(Number);
    return monthKey(new Date(year || 2024, Math.max(0, (month || 1) - 1) + Number(delta || 0), 1));
  };
  const monthDays = (key: string): Date[] => {
    const [year, month] = String(key || '').split('-').map(Number);
    const first = new Date(year || 2024, Math.max(0, (month || 1) - 1), 1);
    const last = new Date(first.getFullYear(), first.getMonth() + 1, 0);
    const start = new Date(first);
    const end = new Date(last);
    start.setDate(start.getDate() - start.getDay());
    end.setDate(end.getDate() + (6 - end.getDay()));
    const days: Date[] = [];
    for (let cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) days.push(new Date(cursor));
    return days;
  };
  const weekStart = (value: Date | string): Date => {
    const source = value instanceof Date
      ? new Date(value.getFullYear(), value.getMonth(), value.getDate())
      : parseDate(value) || now();
    const start = new Date(source.getFullYear(), source.getMonth(), source.getDate());
    start.setDate(start.getDate() - start.getDay());
    return start;
  };
  const weekKey = (value: Date | string): string => iso(weekStart(value));
  const weekDays = (key: string): Date[] => {
    const start = weekStart(key);
    return Array.from({ length: 7 }, (_, index) => {
      const date = new Date(start);
      date.setDate(start.getDate() + index);
      return date;
    });
  };
  const shiftWeek = (key: string, delta: number): string => addDays(weekKey(key), Number(delta || 0) * 7);
  const navigateWeekState = (key: string, delta: number, recordAction = false): void => {
    ports.appStore.set({
      agendaCalendarWeekV8: shiftWeek(key, delta),
      ...(recordAction ? { lastAction: 'Navegou pela semana da agenda' } : {}),
    });
  };
  const selectWeekState = (value: unknown, options: { validate?: boolean; recordAction?: boolean } = {}): boolean => {
    const chosen = String(value || '');
    if (options.validate && !parseDate(chosen)) return false;
    ports.appStore.set({
      agendaCalendarWeekV8: weekKey(chosen),
      ...(options.recordAction ? { lastAction: `Selecionou a semana de ${chosen}` } : {}),
    });
    return true;
  };
  const setPresentation = (value: unknown): boolean => {
    const presentation = String(value || '');
    if (presentation !== 'status' && presentation !== 'timeline') return false;
    ports.appStore.set({
      agendaCalendarPresentationV1: presentation,
      lastAction: presentation === 'status' ? 'Organizou a agenda por estado' : 'Organizou a agenda por horário',
    });
    return true;
  };
  const weekLabel = (key: string): string => {
    const days = weekDays(key);
    const first = days[0];
    const last = days[6];
    if (first.getMonth() === last.getMonth() && first.getFullYear() === last.getFullYear())
      return `${first.getDate()} — ${last.getDate()} de ${first.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}`;
    return `${first.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' })} — ${last.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' })}`;
  };
  const initialWeek = (state: Record<string, unknown>, data: { events: OperationalAgendaEvent[] }): string => {
    const requested = String(state.agendaCalendarWeekV8 || '');
    if (/^\d{4}-\d{2}-\d{2}$/.test(requested)) return weekKey(requested);
    const today = now();
    const todayWeek = weekKey(today);
    const todayDays = new Set(weekDays(todayWeek).map(iso));
    const events = Array.isArray(data?.events) ? data.events : [];
    if (events.some(event => todayDays.has(String(event.date || '')))) return todayWeek;
    const dated = events.map(event => ({ date: parseDate(event.date) })).filter((item): item is { date: Date } => Boolean(item.date))
      .sort((left, right) => Math.abs(left.date.getTime() - today.getTime()) - Math.abs(right.date.getTime() - today.getTime()));
    return dated[0]?.date ? weekKey(dated[0].date) : todayWeek;
  };
  const eventEnd = (event: Partial<OperationalAgendaEvent>): number => {
    const date = parseDate(event.date);
    if (!date) return 0;
    date.setDate(date.getDate() + Math.max(0, Number(event.spanDays || 1) - 1));
    const hours = timeToHours(event.start) + Math.max(0.5, Number(event.durationHours || 1));
    date.setMinutes(date.getMinutes() + Math.round(hours * 60));
    return date.getTime();
  };
  const lastAvailableSlotWeek = (events: OperationalAgendaEvent[], key: string): AtlasAgendaCalendarSlotV1 => {
    const days = weekDays(key);
    const daySet = new Set(days.map(iso));
    const inWeek = events.filter(item => daySet.has(String(item.date || ''))).sort((left, right) => eventEnd(left) - eventEnd(right));
    if (!inWeek.length) return { date: iso(days[1] || days[0]), start: '08:00' };
    const last = inWeek[inWeek.length - 1];
    const lastDate = parseDate(last.date) || weekStart(key);
    const endHour = timeToHours(last.start) + Math.max(0.5, Number(last.durationHours || 1));
    lastDate.setDate(lastDate.getDate() + Math.max(0, Number(last.spanDays || 1) - 1));
    if (endHour <= 23.5) return { date: iso(lastDate), start: hoursToTime(Math.ceil(endHour * 2) / 2) };
    lastDate.setDate(lastDate.getDate() + 1);
    if (lastDate > days[6]) lastDate.setTime(days[0].getTime());
    return { date: iso(lastDate), start: '08:00' };
  };
  const read = (): AgendaCalendarSnapshotV3 => readAgendaCalendarSnapshotV3(ports.appStore.get());
  const ensureLoaded = (): void => {
    const state = ports.appStore.get();
    if (state.agendaCalendarLoadedV3 || state.agendaCalendarLoadingV3) return;
    ports.appStore.set({ agendaCalendarLoadingV3: true });
    void Promise.resolve().then(async () => {
      const response = await Promise.race([
        ports.apiFetch('/api/agenda-events', { cache: 'no-store' }),
        new Promise<never>((_resolve, reject) => globalThis.setTimeout(
          () => reject(new Error('Tempo limite da conexão com o servidor (12 s).')),
          12000,
        )),
      ]) as Response;
      const payload = await response.json().catch(() => ({})) as {
        events?: OperationalAgendaEvent[];
        error?: string;
      };
      if (!response.ok || !Array.isArray(payload.events)) throw new Error(payload.error || `HTTP ${response.status}`);
      ports.appStore.set({
        agendaCalendarLoadedV3: true,
        agendaCalendarLoadingV3: false,
        agendaCalendarErrorV3: '',
        agendaDatabaseEventsV3: payload.events,
      });
    }).catch(error => {
      const detail = String((error as Error)?.message || error);
      const authUnavailable = /default credentials|OAuth2 access token|Project Id|Autentica|HTTP 401/i.test(detail);
      ports.appStore.set({
        agendaCalendarLoadedV3: true,
        agendaCalendarLoadingV3: false,
        agendaCalendarErrorV3: authUnavailable
          ? 'A agenda está indisponível porque o servidor não tem credenciais de autenticação configuradas.'
          : `Não foi possível carregar a agenda: ${detail}`,
        agendaDatabaseEventsV3: [],
      });
    });
  };
  const write = async (data: { version?: 3; initialized?: boolean; events?: OperationalAgendaEvent[] }): Promise<OperationalAgendaEvent[]> => {
    if (!read().initialized) throw new Error('Agenda ainda não foi carregada do banco de dados.');
    const response = await ports.apiFetch('/api/agenda-events', {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ events: data?.events || [] }),
    });
    const payload = await response.json().catch(() => ({})) as { events?: OperationalAgendaEvent[]; error?: string };
    if (!response.ok || !Array.isArray(payload.events)) throw new Error(payload.error || `HTTP ${response.status}`);
    ports.appStore.set({ agendaDatabaseEventsV3: payload.events, agendaCalendarRevisionV3: now().getTime(), agendaCalendarErrorV3: '' });
    return payload.events;
  };
  const saveEvent = async (draft: AtlasAgendaCalendarEventDraftV1): Promise<AtlasAgendaCalendarEventSaveResultV1> => {
    const current = read();
    const id = String(draft.id || `agenda-${now().getTime().toString(36)}`);
    const previous = current.events.find(item => item.id === id);
    const stage = findStage(draft.stageKey);
    const item: OperationalAgendaEvent = {
      ...previous,
      id,
      title: String(draft.title || '').trim(),
      stageKey: String(draft.stageKey || ''),
      stageName: stage?.name || '',
      activityId: String(draft.activityId || ''),
      activityName: String(draft.activityName || draft.title || ''),
      owner: String(draft.owner || ''),
      date: String(draft.date || ''),
      start: String(draft.start || '08:00'),
      durationHours: Number(draft.durationHours || 1.5),
      spanDays: Number(draft.spanDays || 1),
      status: String(draft.status || 'Planejado'),
      relatedFrom: String(previous?.relatedFrom || ''),
      notes: String(draft.notes || ''),
      materialIds: (Array.isArray(draft.materialIds) ? draft.materialIds : []).map(String),
      mapAreas: (Array.isArray(draft.mapAreas) ? draft.mapAreas : previous?.mapAreas || [])
        .map(value => projectAtlasMapProgressArea(value as AtlasMapPartInput))
        .filter((value): value is AtlasMapProgressArea => Boolean(value)),
    };
    const events = await write({ events: [...current.events.filter(entry => entry.id !== id), item] });
    return { event: events.find(entry => entry.id === id) || item, events, created: !previous };
  };
  const deleteEvent = async (value: unknown): Promise<OperationalAgendaEvent[]> => {
    const id = String(value || '');
    return write({ events: read().events.filter(item => item.id !== id) });
  };
  const saveGestureEvent = async (draft: AtlasAgendaCalendarGestureEventDraftV1): Promise<OperationalAgendaEvent[]> => {
    const id = String(draft.id || ''), current = read();
    const events = current.events.map(item => String(item.id) === id
      ? { ...item, date: String(draft.date || item.date), start: String(draft.start || item.start),
          durationHours: Number(draft.durationHours || item.durationHours), spanDays: Number(draft.spanDays || item.spanDays) }
      : item);
    return write({ events });
  };
  const saveInlineEditorEvent = async (draft: AtlasAgendaCalendarInlineEditorDraftV1): Promise<AtlasAgendaCalendarEventSaveResultV1> => {
    const current = read();
    const existingId = String(draft.id || '').trim();
    const id = existingId || `agenda-${now().getTime().toString(36)}`;
    const title = String(draft.title || '').trim()
      || String(draft.activityTitle || '')
      || 'Compromisso operacional';
    const stage = findStage(draft.stageKey);
    const activityLabel = String(draft.activityLabel || '').split('·').pop()?.trim();
    const item: OperationalAgendaEvent = {
      id,
      title,
      stageKey: String(draft.stageKey || ''),
      stageName: stage?.name || 'Etapa',
      activityId: String(draft.activityId || ''),
      activityName: String(draft.activityTitle || activityLabel || title),
      owner: String(draft.owner || '').trim(),
      date: String(draft.date || ''),
      start: String(draft.start || '08:00'),
      durationHours: Math.max(0.5, Math.min(24, Number(draft.durationHours || 1.5))),
      spanDays: Math.max(1, Math.min(7, Math.round(Number(draft.spanDays || 1)))),
      status: String(draft.status || 'Planejado'),
      relatedFrom: String(draft.relatedFrom || ''),
      notes: String(draft.notes || '').trim(),
      materialIds: (Array.isArray(draft.materialIds) ? draft.materialIds : []).map(String),
    };
    if (!item.date) {
      const slot = lastAvailableSlotWeek(current.events, String(draft.weekKey || ''));
      item.date = slot.date;
      item.start = slot.start;
    }
    const nextEvents = [...current.events];
    const index = nextEvents.findIndex(entry => String(entry.id) === id);
    if (index >= 0) nextEvents[index] = item;
    else nextEvents.push(item);
    const events = await write({ version: 3, initialized: true, events: nextEvents });
    return { event: events.find(entry => entry.id === id) || item, events, created: index < 0 };
  };
  const findStage = (value: unknown): AtlasAgendaCalendarStageV1 | null => {
    const token = ports.normalizeActivityRouteText(value);
    return executionStages.find(stage => ports.normalizeActivityRouteText(stage.key) === token
      || ports.normalizeActivityRouteText(stage.name) === token) || executionStages[0] || null;
  };
  const activitiesForStage = (stageKey: unknown, stageName = ''): AtlasAgendaCalendarActivityV1[] => {
    const administrativeDestination = administrativeDestinations.find(destination =>
      String(destination.key || '').toLocaleLowerCase('pt-BR') === String(stageKey || '').toLocaleLowerCase('pt-BR')
      || String(destination.name || '').toLocaleLowerCase('pt-BR') === String(stageName || '').toLocaleLowerCase('pt-BR'));
    if (administrativeDestination) return [{ id: `${administrativeDestination.key}-note`, title: 'Nota / atividade administrativa', materials: [] }];
    const direct = workbenchStages.find(stage => String(stage.key) === String(stageKey)
      || ports.normalizeActivityRouteText(stage.title) === ports.normalizeActivityRouteText(stageName))
      || ports.workbenchStageFromValue?.(stageKey || stageName);
    const values = Array.isArray(direct?.activities) ? direct.activities : [];
    if (values.length) return values.map(item => {
      const materialValues = Array.isArray(item.materials) ? item.materials : [];
      const materials = materialValues.map(value => {
        const row = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
        const name = String(row.name || row.title || row.materialName || row.description || (typeof value === 'string' ? value : '')).trim();
        const id = String(row.id || row.key || row.materialId || name).trim();
        return name ? { id, name } : null;
      }).filter((value): value is AtlasAgendaCalendarActivityMaterialV1 => Boolean(value));
      return {
        id: String(item.id || item.title),
        title: String(item.title || item.name || item.id),
        materials,
      };
    });
    return [{ id: String(stageKey || 'atividade'), title: String(stageName || 'Atividade da etapa'), materials: [] }];
  };
  const demoEvents = (stage?: AtlasAgendaCalendarStageV1 | null): Array<Record<string, unknown>> => {
    const stageKey = stage?.key || 'drainage';
    const stageName = stage?.name || 'Drenagem Pluvial';
    const owner = ports.stageV9LiveFor?.(stage || {})?.owner || stage?.owner || '';
    const rows = [
      ['agenda-demo-01', 'Planejar frente', 'front', 'Preparar frente', owner || 'Paula', '2024-06-03', '08:00', 2, 'Planejado'],
      ['agenda-demo-02', 'Comprar materiais', 'materials', 'Suprimentos', 'Suprimentos', '2024-06-04', '10:00', 2, 'Em andamento'],
      ['agenda-demo-03', 'Conferir medição', 'measure', 'Validar medição', 'Carlos', '2024-06-05', '14:00', 2, 'Pendente'],
      ['agenda-demo-04', 'Confirmar medição', 'measure', 'Validar medição', 'Carlos', '2024-06-06', '08:30', 1.5, 'Em andamento'],
      ['agenda-demo-05', 'Receber materiais', 'materials', 'Recebimento', 'Paula', '2024-06-06', '10:30', 2, 'Em andamento'],
      ['agenda-demo-06', 'Liberar próxima frente', 'release', 'Liberar próxima frente', 'Mariana', '2024-06-06', '16:00', 2, 'Pendente'],
      ['agenda-demo-07', 'Validar evidências', 'evidence', 'Validar evidências', 'Paula', '2024-06-07', '09:00', 2, 'Planejado'],
      ['agenda-demo-08', 'Revisar pendências', 'review', 'Revisar pendências', 'Admin', '2024-06-08', '11:00', 2, 'Pendente'],
    ] as const;
    return rows.map(([id, title, activityId, activityName, eventOwner, date, start, durationHours, status]) => ({
      id, title, stageKey, stageName, activityId, activityName, owner: eventOwner, date, start,
      durationHours, spanDays: 1, status,
    }));
  };
  const operationalEvents = (state: Record<string, unknown>): OperationalAgendaEvent[] => {
    const source = Array.isArray(state.operationalAgenda) ? state.operationalAgenda as Array<Record<string, unknown>> : [];
    return source.map((item, index) => {
      const raw = item.plannedStart || item.start || item.date || item.referenceDate || '';
      const rawText = String(raw || '');
      const parsed = new Date(rawText);
      const date = parseDate(raw) || (Number.isFinite(parsed.getTime())
        ? new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate()) : null);
      if (!date) return null;
      const stage = findStage(item.stageKey || item.stageName);
      const start = rawText.match(/T(\d{2}):(\d{2})/)?.slice(1, 3).join(':') || item.time || '08:00';
      return {
        id: `agenda-op-${item.id || index + 1}`,
        title: item.title || item.name || 'Compromisso operacional',
        stageKey: stage?.key || item.stageKey || '',
        stageName: stage?.name || item.stageName || 'Etapa',
        activityId: item.activityId || item.activity || item.title || '',
        activityName: item.activity || item.title || 'Atividade',
        owner: item.owner || item.responsible || '',
        date: iso(date), start: String(start),
        durationHours: Math.max(0.5, Number(item.durationHours || item.hours || 1.5)),
        spanDays: Math.max(1, Number(item.spanDays || item.durationDays || 1)),
        status: item.status || 'Planejado',
      } as OperationalAgendaEvent;
    }).filter((event): event is OperationalAgendaEvent => Boolean(event));
  };
  const initialMonth = (state: Record<string, unknown>, data: { events: OperationalAgendaEvent[] }): string => {
    const requested = String(state.agendaCalendarMonthV3 || '');
    if (/^\d{4}-\d{2}$/.test(requested)) return requested;
    const first = data.events.map(item => parseDate(item.date)).filter((date): date is Date => Boolean(date))
      .sort((left, right) => left.getTime() - right.getTime())[0];
    return first ? monthKey(first) : monthKey(now());
  };
  const lastAvailableSlotMonth = (events: OperationalAgendaEvent[], key: string): AtlasAgendaCalendarSlotV1 => {
    const inMonth = events.filter(item => String(item.date || '').startsWith(key)).sort((left, right) => eventEnd(left) - eventEnd(right));
    const [year, month] = key.split('-').map(Number);
    const monthLast = new Date(year, month, 0);
    const first = new Date(year, month - 1, 1);
    if (!inMonth.length) {
      while (first.getDay() === 0 || first.getDay() === 6) first.setDate(first.getDate() + 1);
      return { date: iso(first), start: '08:00' };
    }
    const last = inMonth[inMonth.length - 1];
    const lastDate = parseDate(last.date) || first;
    const endHour = timeToHours(last.start) + Math.max(0.5, Number(last.durationHours || 1));
    lastDate.setDate(lastDate.getDate() + Math.max(0, Number(last.spanDays || 1) - 1));
    if (endHour <= 19.5 && lastDate <= monthLast) return { date: iso(lastDate), start: hoursToTime(Math.ceil(endHour * 2) / 2) };
    lastDate.setDate(lastDate.getDate() + 1);
    if (lastDate > monthLast) lastDate.setTime(first.getTime());
    return { date: iso(lastDate), start: '08:00' };
  };
  const statusTone = (status: unknown): 'done' | 'active' | 'warning' | 'planned' => {
    const token = ports.normalizeActivityRouteText(status);
    if (token.includes('concl')) return 'done';
    if (token.includes('andamento') || token.includes('exec')) return 'active';
    if (token.includes('pend') || token.includes('risco')) return 'warning';
    return 'planned';
  };
  const clamp = (value: number, minimum: number, maximum: number): number =>
    Math.max(minimum, Math.min(maximum, Number(value) || 0));
  const snapHalfHour = (value: number): number => Math.round((Number(value) || 0) * 2) / 2;
  const dayDifference = (fromIso: string, toIso: string): number => {
    const from = parseDate(fromIso);
    const to = parseDate(toIso);
    if (!from || !to) return 0;
    return Math.round((new Date(to.getFullYear(), to.getMonth(), to.getDate()).getTime()
      - new Date(from.getFullYear(), from.getMonth(), from.getDate()).getTime()) / 86400000);
  };
  const pointerHours = (offsetPx: number, options: {
    grabOffsetPx?: number;
    minimumPx: number;
    maximumPx: number;
    pixelsPerHour: number;
    minimumHours: number;
    maximumHours: number;
  }): number => {
    const pixels = clamp(offsetPx - Number(options.grabOffsetPx || 0), options.minimumPx, options.maximumPx);
    return clamp(snapHalfHour(pixels / options.pixelsPerHour), options.minimumHours, options.maximumHours);
  };
  const normalizePreview = (source: Partial<OperationalAgendaEvent>): Partial<OperationalAgendaEvent> => {
    const startHours = timeToHours(source.start || '08:00');
    const duration = clamp(snapHalfHour(Number(source.durationHours || 0.5)), 0.5, Math.max(0.5, 24 - startHours));
    const date = String(source.date || '');
    const weekday = Number(parseDate(date)?.getDay() || 0);
    const span = clamp(Math.round(Number(source.spanDays || 1)), 1, Math.max(1, 7 - weekday));
    return { ...source, date, start: hoursToTime(startHours), durationHours: duration, spanDays: span };
  };
  const previewFromPointer = (
    source: Partial<OperationalAgendaEvent>,
    mode: AtlasAgendaCalendarPointerModeV1,
    input: AtlasAgendaCalendarPointerPreviewInputV1,
  ): Partial<OperationalAgendaEvent> => {
    const original = normalizePreview(source);
    const date = String(original.date || '');
    const originalStart = timeToHours(original.start || '08:00');
    const originalEnd = Math.min(24, originalStart + Number(original.durationHours || 0.5));
    const originalSpan = Number(original.spanDays || 1);
    if (mode === 'move') {
      const targetDate = String(input.date || date);
      const targetWeekday = Number(parseDate(targetDate)?.getDay() || 0);
      return normalizePreview({ ...original, date: targetDate,
        start: hoursToTime(Number(input.startHours || 0)),
        spanDays: Math.min(originalSpan, Math.max(1, 7 - targetWeekday)) });
    }
    if (mode === 'start-hours') {
      const nextStart = clamp(Number(input.pointerHours || 0), 0, Math.max(0, originalEnd - 0.5));
      return normalizePreview({ ...original, start: hoursToTime(nextStart),
        durationHours: Math.max(0.5, snapHalfHour(originalEnd - nextStart)) });
    }
    if (mode === 'end-hours') {
      const nextEnd = clamp(Number(input.pointerHours || 0), originalStart + 0.5, 24);
      return normalizePreview({ ...original,
        durationHours: Math.max(0.5, snapHalfHour(nextEnd - originalStart)) });
    }
    if (mode === 'start-days') {
      const targetDate = String(input.date || date);
      const originalEndDate = addDays(date, originalSpan - 1);
      const originalWeekday = Number(parseDate(date)?.getDay() || 0);
      const minDate = addDays(date, -originalWeekday);
      const min = parseDate(minDate)?.getTime() || 0;
      const max = parseDate(originalEndDate)?.getTime() || 0;
      const candidate = parseDate(targetDate)?.getTime() || min;
      const clampedDate = candidate < min ? minDate : candidate > max ? originalEndDate : targetDate;
      const nextSpan = Math.max(1, dayDifference(clampedDate, originalEndDate) + 1);
      return normalizePreview({ ...original, date: clampedDate, spanDays: nextSpan });
    }
    if (mode === 'end-days') {
      const targetDate = String(input.date || addDays(date, originalSpan - 1));
      const startWeekday = Number(parseDate(date)?.getDay() || 0);
      const maxDate = addDays(date, 6 - startWeekday);
      const startMs = parseDate(date)?.getTime() || 0;
      const maxMs = parseDate(maxDate)?.getTime() || 0;
      const candidate = parseDate(targetDate)?.getTime() || startMs;
      const clampedDate = candidate < startMs ? date : candidate > maxMs ? maxDate : targetDate;
      const nextSpan = Math.max(1, dayDifference(date, clampedDate) + 1);
      return normalizePreview({ ...original, spanDays: nextSpan });
    }
    return original;
  };

  return Object.freeze({
    agendaCalendarPadV3: pad,
    agendaCalendarIsoV3: iso,
    agendaCalendarMonthKeyV3: monthKey,
    agendaCalendarParseDateV3: parseDate,
    agendaCalendarAddDaysV3: addDays,
    agendaCalendarTimeToHoursV3: timeToHours,
    agendaCalendarHoursToTimeV3: hoursToTime,
    agendaCalendarMonthLabelV3: monthLabel,
    agendaCalendarShiftMonthV3: shiftMonth,
    agendaCalendarMonthDaysV3: monthDays,
    agendaCalendarWeekStartV8: weekStart,
    agendaCalendarWeekKeyV8: weekKey,
    agendaCalendarWeekDaysV8: weekDays,
    agendaCalendarShiftWeekV8: shiftWeek,
    agendaCalendarWeekLabelV8: weekLabel,
    agendaCalendarInitialWeekV8: initialWeek,
    agendaCalendarLastAvailableSlotV8: lastAvailableSlotWeek,
    agendaCalendarNavigateWeekStateV8: navigateWeekState,
    agendaCalendarSelectWeekStateV8: selectWeekState,
    agendaCalendarSetPresentationV1: setPresentation,
    agendaCalendarReadV3: read,
    ensureAgendaCalendarLoadedV8: ensureLoaded,
    agendaCalendarWriteV3: write,
    agendaCalendarSaveEventV1: saveEvent,
    agendaCalendarSaveInlineEditorEventV1: saveInlineEditorEvent,
    agendaCalendarDeleteEventV1: deleteEvent,
    agendaCalendarSaveGestureEventV1: saveGestureEvent,
    agendaCalendarFindStageV3: findStage,
    agendaCalendarActivitiesForStageV3: activitiesForStage,
    agendaCalendarDemoEventsV3: demoEvents,
    agendaCalendarOperationalEventsV3: operationalEvents,
    agendaCalendarStateV3: (_state: Record<string, unknown>, _stage?: AtlasAgendaCalendarStageV1 | null) => read(),
    agendaCalendarInitialMonthV3: initialMonth,
    agendaCalendarEventEndV3: eventEnd,
    agendaCalendarLastAvailableSlotV3: lastAvailableSlotMonth,
    agendaCalendarStatusToneV3: statusTone,
    agendaCalendarPointerHoursV1: pointerHours,
    agendaCalendarNormalizePreviewV7: normalizePreview,
    agendaCalendarPreviewFromPointerV7: previewFromPointer,
  });
}

export interface AtlasStageAgendaApplicationCompositionInputV1 extends AtlasActivityInstallationDependenciesV1 {
  ViewLayer: AtlasPlanningViewLayer;
  STAGE_WORKBENCH: typeof WORKER_STAGE_WORKBENCH_CATALOG_V1;
  apiFetch: AtlasPlanningPagesApplicationInput['apiFetch'];
  beginCardCanvasLinkV1: AtlasPlanningPagesApplicationInput['beginCardCanvasLinkV1'];
  dashboardPageMarkup: (calendarWeek?: string) => string;
  extensionStage: AtlasPlanningPagesApplicationInput['extensionStage'];
  normalizeActivityRouteTextV1: AtlasPlanningRuntimeContextV1['normalizeActivityRouteTextV1'];
  stagePersistentTimelineMarkupV1: () => string;
  workbenchStageFromValueV1: AtlasPlanningPagesApplicationInput['stageRecordServices']['workbenchStageFromValueV1'];
}

/** Compose the Agenda, activity-installation route, and stage-home calendar. */
export async function installAtlasStageAgendaApplicationCompositionV1(
  input: AtlasStageAgendaApplicationCompositionInputV1,
): Promise<Readonly<ReturnType<typeof installAtlasAgendaCalendarPageV8> & {
  stageHomeSnapshotV1(calendarWeek?: string): ReturnType<typeof projectAtlasStageHomeSnapshot>;
}>> {
  const {
    ViewLayer, STAGE_WORKBENCH, activityCatalog, activityInstallationDefaults,
    appStore, apiFetch, beginCardCanvasLinkV1, dashboardPageMarkup, demoData,
    esc, executionModel, extensionStage, ico, normalizeActivityRouteTextV1,
    notify, onCommit, operationalRaid, renderActivityFormGroupsV1,
    stagePersistentTimelineMarkupV1, stageV9LiveFor, stageV9MaterialsFor,
    stageV9ProductionFor, stageV9StatusFor, workbenchStageFromValueV1,
  } = input;
  const globalRef = input.globalRef || globalThis;

  installAtlasStageAgendaInstallationOpenBindingV1({
    ViewLayer: ViewLayer as any,
    onCommand: command => {
      if (command.type === 'open-installation') appStore.set({
        view: 'activity-installation',
        lastAction: 'Abriu a sessão de instalação de atividades',
      });
    },
  });
  const agendaCalendarProgramV1 = createAtlasAgendaCalendarProgramV1({
    appStore,
    apiFetch,
    executionStages: executionModel.stages || [],
    workbenchStages: [...STAGE_WORKBENCH] as unknown as AtlasAgendaCalendarWorkbenchStageV1[],
    normalizeActivityRouteText: normalizeActivityRouteTextV1,
    workbenchStageFromValue: value => workbenchStageFromValueV1(value) as AtlasAgendaCalendarWorkbenchStageV1 | null,
    stageV9LiveFor,
  });
  const agendaCalendarV1 = installAtlasAgendaCalendarPageV8(ViewLayer as any, {
    readState: () => appStore.get(),
    appStore,
    agendaCalendarProgramV1,
    beginCardCanvasLinkV1, demoData, esc,
    executionModel, extensionStage, host: globalRef, ico,
    normalizeActivityRouteTextV1, notify, stagePersistentTimelineMarkupV1,
    stageV9LiveFor, stageV9MaterialsFor, workbenchStageFromValueV1,
  });

  const activityInstallationDependenciesV1: AtlasActivityInstallationDependenciesV1 = {
    activityCatalog, activityInstallationDefaults, appStore, demoData, esc,
    executionModel, ico, notify, operationalRaid, renderActivityFormGroupsV1,
    onCommit,
    onNavigate: input.onNavigate,
    stageV9LiveFor, stageV9MaterialsFor, stageV9ProductionFor, stageV9StatusFor,
  };
  installAtlasActivityInstallationSessionV1(
    ViewLayer as any,
    { ...activityInstallationDependenciesV1, globalRef },
  );

  const stageHomeSnapshotV1 = (calendarWeekOverride = '') => projectAtlasStageHomeSnapshot({
    state: appStore.get(),
    executionStages: executionModel.stages || [],
    activityCatalog,
    operationalRaid: operationalRaid(),
    stageV9LiveFor: stageV9LiveFor as unknown as AtlasStageHomeSnapshotInput['stageV9LiveFor'],
    agendaCalendarRead: agendaCalendarV1.agendaCalendarReadV3 as unknown as AtlasStageHomeSnapshotInput['agendaCalendarRead'],
    agendaCalendarOperationalEvents: agendaCalendarV1.agendaCalendarOperationalEventsV3 as unknown as AtlasStageHomeSnapshotInput['agendaCalendarOperationalEvents'],
    agendaCalendarInitialWeek: agendaCalendarV1.agendaCalendarInitialWeekV8 as unknown as AtlasStageHomeSnapshotInput['agendaCalendarInitialWeek'],
    agendaCalendarIso: agendaCalendarV1.agendaCalendarIsoV3,
    agendaCalendarWeekDays: agendaCalendarV1.agendaCalendarWeekDaysV8,
    agendaCalendarWeekLabel: agendaCalendarV1.agendaCalendarWeekLabelV8,
    calendarWeekOverride,
    icons: { shield: ico('shield-alert'), sparkles: ico('sparkles'), plus: ico('plus') },
  });

  installAtlasStageHomeCalendar({
    ViewLayer: ViewLayer as any,
    readState: () => {
      const state = appStore.get();
      return { view: state.view, stageActivityDedicatedV9: state.stageActivityDedicatedV9 };
    },
    onAction: action => {
      if (action.kind === 'set-calendar-week') {
        appStore.set({ stageHomeCalendarWeekV1: action.week });
      } else if (action.kind === 'open-agenda-event') {
        appStore.set({
          view: 'agenda',
          agendaCalendarWeekV8: agendaCalendarV1.agendaCalendarWeekKeyV8(new globalRef.Date(`${action.date}T12:00:00`)),
          selectedAgendaEventV3: action.eventId,
          lastAction: 'Abriu compromisso pela linha do tempo das etapas',
        });
      } else if (action.kind === 'open-view') {
        appStore.set({
          view: action.view,
          activityDedicated: false,
          stageActivityDedicatedV9: false,
          lastAction: `Abriu ${action.view === 'activities' ? 'as atividades' : action.view === 'records' ? 'os registros' : 'a agenda'} pelo organizador`,
        });
      } else if (action.kind === 'create-record') {
        appStore.set({ view: 'records', editingRecord: 'new', recordContext: null, stageRecordsContext: false, lastAction: 'Abriu novo registro pelo organizador de etapas' });
      } else if (action.kind === 'open-record') {
        appStore.set({ view: 'records', selectedRecordV5362: action.recordId, lastAction: 'Abriu registro pelo organizador de etapas' });
      } else if (action.kind === 'open-stage') {
        const modelStage = (executionModel.stages || []).find(stage => String(stage.key) === String(action.stageKey));
        const stage = modelStage || { key: String(action.stageKey || ''), name: action.stageLabel || 'Etapa operacional' };
        const record = (demoData.activities || []).find(activity => String(activity.name).toLocaleLowerCase('pt-BR') === String(stage.name || '').toLocaleLowerCase('pt-BR'));
        appStore.set({ view: 'stages', selectedStageV9: String(stage.key), selectedStage: (record?.id || stage.key) as string | number, activityDedicated: true, stageActivityDedicatedV9: false, lastAction: `Abriu a etapa ${stage.name} pelo cronograma` });
      }
    },
    getStageHomePageMarkup: (calendarWeek = '') => dashboardPageMarkup(calendarWeek),
    shiftWeek: (weekKey, delta) => {
      const date = agendaCalendarV1.agendaCalendarParseDateV3(weekKey);
      if (!date) return '';
      date.setDate(date.getDate() + Number(delta || 0) * 7);
      return agendaCalendarV1.agendaCalendarWeekKeyV8(date);
    },
    document: globalRef.document,
    window: globalRef.window,
    globalRef: globalRef as any,
  });

  return Object.freeze({ ...agendaCalendarV1, stageHomeSnapshotV1 });
}

/** Read the shared agenda snapshot from application state without an MJS calendar service. */
export function readAgendaCalendarSnapshotV3(state: Readonly<Record<string, unknown>>): AgendaCalendarSnapshotV3 {
  return {
    version: 3,
    initialized: Boolean(state.agendaCalendarLoadedV3 && !state.agendaCalendarErrorV3),
    events: Array.isArray(state.agendaDatabaseEventsV3)
      ? state.agendaDatabaseEventsV3 as OperationalAgendaEvent[]
      : [],
  };
}

