/** Project the stage detail context from live, configured, and operational state. */
export function createAtlasStageOperationalModelV1(input: AtlasStageOperationalModelInputV1): AtlasStageOperationalModelV1 {
  if (typeof input.appStore?.get !== 'function') throw new TypeError('Stage operational model requires appStore.get().');
  if (!Array.isArray(input.executionModel?.stages)) throw new TypeError('Stage operational model requires executionModel.stages.');
  for (const [name, value] of Object.entries({ stageOverlayKey: input.stageOverlayKey, stageProfileSettingsFor: input.stageProfileSettingsFor, stageMaterialsFor: input.stageMaterialsFor }))
    if (typeof value !== 'function') throw new TypeError(`Stage operational model requires ${name}().`);

  const stages = input.executionModel.stages;
  const activities = Array.isArray(input.demoData?.activities) ? input.demoData.activities : [];
  const stageOf = (record: AtlasStageOperationalRecordV1): string => String(record?.etapa || record?.stage || record?.atividade || 'Etapa operacional');
  const stageV9LiveFor = (stage: AtlasStageOperationalStageV1): AtlasStageOperationalLiveStateV1 =>
    activities.find(item => item.id === stage.id || item.name === stage.name)
      || activities.find(item => input.stageOverlayKey(item.name) === input.stageOverlayKey(stage.name))
      || {};
  const stageV9ByState = (state: AtlasStageOperationalStateV1): AtlasStageOperationalStageV1 | undefined =>
    stages.find(item => String(item.key) === String(state.selectedStageV9 || ''))
      || stages.find(item => String(item.key) === String(state.selectedStage || ''))
      || stages.find(item => String(item.id) === String(state.selectedStage || ''))
      || stages.find(item => item.name === state.selectedStage)
      || stages[0];
  const stageV9OperationalFor = (stage: AtlasStageOperationalStageV1, state = input.appStore.get()): AtlasStageOperationalAllocationV1 => {
    const rawOperational = state.operationalState;
    const operational = rawOperational && typeof rawOperational === 'object' && !Array.isArray(rawOperational)
      ? rawOperational as Record<string, unknown>
      : {};
    const candidateRows = Array.isArray(operational.stages)
      ? operational.stages
      : Array.isArray(operational.stageAllocations)
        ? operational.stageAllocations
        : [];
    const allocation = candidateRows.find((value): value is AtlasStageOperationalAllocationV1 => {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
      const row = value as AtlasStageOperationalAllocationV1;
      return row.key === stage.key || row.stageKey === stage.key || row.name === stage.name;
    });
    return allocation || {};
  };
  const stageV9ProfileFor = (stage: AtlasStageOperationalStageV1): Record<string, unknown> => ({ ...(stage.executionProfile || {}), ...(input.stageProfileSettingsFor(stage.key) || {}) });
  const stageV9ProductionFor = (stage: AtlasStageOperationalStageV1): string => {
    const production = stage.production || {};
    const quantity = production.quantity == null
      ? '—'
      : typeof production.quantity === 'number'
        ? production.quantity.toLocaleString('pt-BR')
        : production.quantity;
    return `${quantity} ${production.unit || 'un.'} · ${production.rate || '—'} ${production.rateUnit || ''}`.trim();
  };
  const stageV9MaterialsFor = (stage: AtlasStageOperationalStageV1): AtlasStageOperationalMaterialV1[] => {
    const configured = input.stageMaterialsFor(stage.name);
    if (configured.length) return configured;
    return (stage.materials || []).map((name, index) => ({ name, scope: 'Requisito operacional', quantity: null, unit: '—', status: index === 0 ? 'Principal' : 'Planejado' }));
  };
  const stageV9BudgetFor = (stage: AtlasStageOperationalStageV1, state = input.appStore.get()): number => {
    const operational = stageV9OperationalFor(stage, state);
    const cents = Number(operational.needCents || operational.budgetCents || 0);
    return cents > 0 ? cents / 100 : 2800000 * Number(stage.cashWeight || 0);
  };
  const stageV9StatusFor = (live: AtlasStageOperationalLiveStateV1): string => Number(live.progress) >= 100 ? 'Concluída' : Number(live.progress) > 0 ? 'Em andamento' : 'Planejada';
  const stageV9DirectiveText = (stage: AtlasStageOperationalStageV1, profile: Record<string, unknown>): string =>
    profile.typicalDescription ? String(profile.typicalDescription) : `A inteligência acompanha ${stage.name.toLowerCase()} por produção, caixa, dependências e comprovações.`;
  const stageV9FlowPackets = (stage: AtlasStageOperationalStageV1): AtlasStageOperationalFlowPacketV1[] => {
    const production = stage.production || {};
    return [
      { key: 'front', label: 'Preparar frente', detail: 'Confirmar equipe, área liberada, materiais e segurança.', trigger: 'Fato: frente liberada', unit: 'checklist' },
      { key: 'execute', label: 'Executar atividade', detail: `Medir ${production.unit || 'produção'} conforme a unidade cadastrada.`, trigger: 'Fato: produção apontada', unit: String(production.rateUnit || production.unit || 'un.') },
      { key: 'measure', label: 'Validar medição', detail: 'Conferir quantidade, evidência, orçamento e responsável.', trigger: 'Fato: evidência anexada', unit: 'medição' },
      { key: 'release', label: 'Liberar próxima frente', detail: 'Propagar status, pedido e notificação somente após validação.', trigger: 'Diretriz: completude confirmada', unit: 'liberação' },
    ];
  };
  return Object.freeze({ stageOf, stageV9LiveFor, stageV9ByState, stageV9OperationalFor, stageV9ProfileFor, stageV9ProductionFor, stageV9MaterialsFor, stageV9BudgetFor, stageV9StatusFor, stageV9DirectiveText, stageV9FlowPackets });
}

export interface AtlasDashboardStageControlProgramInputV1 {
  ViewLayer: AtlasPlanningViewLayer;
  documentRef?: Document;
  appStore: {
    get(): Record<string, any>;
    set(patch: Record<string, any>): unknown;
  };
  executionModel: { stages: Array<Record<string, any>> };
  stageV9LiveFor(stage: Record<string, any>): Record<string, any>;
  esc(value: unknown): string;
  ico(name: string): string;
  runtimeRouteV1(path: string, query?: string): string;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
  windowRef: Window;
  globalRef?: typeof globalThis;
}

/** Join configured stages with live worker progress for Dashboard presentation. */
export function projectAtlasDashboardStageControlRowsV1(
  input: Pick<AtlasDashboardStageControlProgramInputV1, 'appStore' | 'executionModel' | 'stageV9LiveFor'>,
): AtlasDashboardStageControlRowV1[] {
  const state = input.appStore.get();
  const operational = state.operationalState && typeof state.operationalState === 'object' ? state.operationalState : {};
  const adminStages: Array<Record<string, any>> = Array.isArray(state.dashboardStageAdminStagesV1) ? state.dashboardStageAdminStagesV1 : [];
  const stageNameKey = (value: unknown): string => String(value || '').toLocaleLowerCase('pt-BR');
  const modeledStages: Array<Record<string, any>> = (input.executionModel.stages || []).map((stage: Record<string, any>) => ({
    ...stage,
    stageId: adminStages.find(item => stageNameKey(item.name) === stageNameKey(stage.name))?.id || '',
  }));
  const additionalStages: Array<Record<string, any>> = adminStages
    .filter(item => !modeledStages.some(stage => stageNameKey(stage.name) === stageNameKey(item.name)))
    .map(item => ({
      key: `stage-${item.id}`,
      stageId: item.id,
      name: item.name,
      owner: item.owner,
      status: item.status,
      progress: item.progress,
      week: item.week,
      dependsOn: [],
    }));
  return [...modeledStages, ...additionalStages].map((stage, index) => {
    const live = (operational.stages || []).find((item: Record<string, any>) => item.key === stage.key)
      || input.stageV9LiveFor(stage)
      || {};
    const progress = Math.max(0, Math.min(100, Number(live.progress) || 0));
    return {
      key: String(stage.key || ''),
      stageId: String(stage.stageId || ''),
      name: String(stage.name || ''),
      period: String(live.week || stage.week || `Fase ${String(index + 1).padStart(2, '0')}`),
      status: progress >= 100 ? 'Concluída' : progress > 0 ? 'Em andamento' : 'Planejada',
      progress,
    };
  });
}

/** Own Dashboard stage catalog loading and worker-page navigation effects. */
export function installAtlasDashboardStageControlV1(input: AtlasDashboardStageControlProgramInputV1): boolean {
  const globalRef = input.globalRef || globalThis;
  const viewLayerTarget = input.documentRef || globalRef.document;
  const connectedViewLayers = new WeakSet<object>();
  installAtlasDashboardStageControlElementV1({
    ViewLayer: input.ViewLayer as any,
    rows: () => projectAtlasDashboardStageControlRowsV1(input),
    esc: input.esc,
    ico: input.ico,
    CustomEventCtor: globalRef.CustomEvent,
    createIcons: () => (globalRef.window as Window & { lucide?: { createIcons(): void } })?.lucide?.createIcons(),
  });
  viewLayerTarget.addEventListener('atlas:dashboard-stage-control-connected', event => {
    const owner = (event.currentTarget || viewLayerTarget) as object;
    if (connectedViewLayers.has(owner)) return;
    connectedViewLayers.add(owner);
    void input.apiFetch('/api/stages-admin', { cache: 'no-store' })
      .then(async response => {
        const payload = await response.json().catch(() => ({})) as { stages?: Array<Record<string, any>> };
        if (!response.ok || !Array.isArray(payload.stages)) return;
        if (JSON.stringify(payload.stages) !== JSON.stringify(input.appStore.get().dashboardStageAdminStagesV1 || []))
          input.appStore.set({ dashboardStageAdminStagesV1: payload.stages });
      })
      .catch(() => {});
  });
  viewLayerTarget.addEventListener('atlas:dashboard-stage-control-command', event => {
    const detail = (event as CustomEvent<{ key?: unknown; mode?: unknown; stageId?: unknown }>).detail;
    if (!detail) return;
    const key = String(detail.key || 'new');
    const mode = String(detail.mode || '');
    const stageId = String(detail.stageId || '');
    const query = `stage=${encodeURIComponent(key)}${stageId ? `&stageId=${encodeURIComponent(stageId)}` : ''}${mode ? `&mode=${encodeURIComponent(mode)}` : ''}`;
    input.windowRef.location.assign(input.runtimeRouteV1('/admin/workers/stage', query));
  });
  return true;
}

export type AtlasDashboardQuickReportKindV1 = 'records' | 'agenda';

export interface AtlasDashboardQuickReportV1 {
  kind: AtlasDashboardQuickReportKindV1;
  filename: string;
  csv: string;
  rowCount: number;
}

export type AtlasDashboardHomeCommandV1 =
  | { type: 'select-stage'; stageKey: string; stageName: string }
  | { type: 'open-worker'; stageKey: string }
  | { type: 'select-focus-tab'; tab: string; label: string }
  | { type: 'close-focus' }
  | { type: 'open-focus-view'; view: string; fallbackStageKey: string }
  | { type: 'open-map-context'; key: string; view: string; label: string };

const ATLAS_DASHBOARD_QUICK_REPORTS_V1: Readonly<Record<AtlasDashboardQuickReportKindV1, {
  path: string;
  payloadKey: 'records' | 'events';
  filename: string;
  columns: readonly string[];
}>> = Object.freeze({
  records: {
    path: '/api/records', payloadKey: 'records', filename: 'registros-de-campo.csv',
    columns: ['id', 'data', 'hora', 'obra', 'etapa', 'atividade', 'responsavel', 'status', 'detalhes'],
  },
  agenda: {
    path: '/api/agenda-events', payloadKey: 'events', filename: 'agenda-por-estado.csv',
    columns: ['id', 'status', 'date', 'start', 'title', 'stageName', 'activityName', 'owner', 'durationHours', 'spanDays', 'notes'],
  },
});

const atlasDashboardCsvCellV1 = (value: unknown): string => {
  const text = String(value ?? '').replace(/[\r\n]+/g, ' ');
  return `"${(/^[=+@-]/.test(text) ? `'${text}` : text).replaceAll('"', '""')}"`;
};

/** Read persisted Dashboard export rows and serialize the existing CSV contract. */
export async function loadAtlasDashboardQuickReportV1(input: {
  kind: AtlasDashboardQuickReportKindV1;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
}): Promise<AtlasDashboardQuickReportV1> {
  const report = ATLAS_DASHBOARD_QUICK_REPORTS_V1[input.kind];
  if (!report) throw new Error('Relatório não reconhecido.');
  const response = await input.apiFetch(report.path, { cache: 'no-store' });
  const payload = await response.json().catch(() => ({})) as Record<string, unknown>;
  const sourceRows = payload[report.payloadKey];
  if (!response.ok || !Array.isArray(sourceRows))
    throw new Error(String(payload.error || `HTTP ${response.status}`));

  const rows = [...sourceRows] as Array<Record<string, unknown>>;
  if (input.kind === 'agenda') {
    const priority = ['pendente', 'em andamento', 'planejado', 'concluído'];
    rows.sort((left, right) => {
      const leftStatus = String(left.status || 'Planejado').toLocaleLowerCase('pt-BR');
      const rightStatus = String(right.status || 'Planejado').toLocaleLowerCase('pt-BR');
      const difference = (priority.indexOf(leftStatus) < 0 ? priority.length : priority.indexOf(leftStatus))
        - (priority.indexOf(rightStatus) < 0 ? priority.length : priority.indexOf(rightStatus));
      return difference
        || leftStatus.localeCompare(rightStatus, 'pt-BR')
        || `${left.date || ''}T${left.start || ''}`.localeCompare(`${right.date || ''}T${right.start || ''}`);
    });
  }
  const csv = rows.length
    ? `\uFEFF${report.columns.map(atlasDashboardCsvCellV1).join(';')}\r\n${rows.map(row => report.columns.map(key => atlasDashboardCsvCellV1(row[key])).join(';')).join('\r\n')}`
    : '';
  return { kind: input.kind, filename: report.filename, csv, rowCount: rows.length };
}

/** Apply Dashboard stage-focus commands to canonical app state or browser navigation. */
export function applyAtlasDashboardHomeCommandV1(input: {
  command: AtlasDashboardHomeCommandV1;
  appStore: AtlasApplicationStore<AtlasApplicationInitialState>;
  executionStages: readonly Record<string, unknown>[];
  demoStages: readonly Record<string, unknown>[];
  workbenchActivityRouteV1(route: string, stageKey: string): string;
  navigateTo(url: string): void;
}): void {
  const { command, appStore } = input;
  if (command.type === 'open-map-context') {
    applyAtlasDashboardMapContextCommandV1({ command, appStore });
    return;
  }
  if (command.type === 'open-worker') {
    input.navigateTo(input.workbenchActivityRouteV1('', command.stageKey));
    return;
  }
  if (command.type === 'select-stage') {
    const stage = input.executionStages.find(item => String(item.key || '') === command.stageKey);
    const stageName = String(stage?.name || command.stageName || command.stageKey);
    const record = input.demoStages.find(item =>
      String(item.name || '').toLocaleLowerCase('pt-BR') === stageName.toLocaleLowerCase('pt-BR'));
    appStore.set({
      view: 'stages',
      selectedStageV9: String(command.stageKey),
      selectedStage: (record?.id || String(command.stageKey)) as string | number,
      stageSelected: true,
      activityDedicated: true,
      stageActivityDedicatedV9: false,
      dashboardStageFocus: '',
      dashboardStageFocusTab: 'overview',
      lastAction: `Abriu a etapa ${command.stageName || stageName} pelo cronograma`,
    });
    return;
  }
  if (command.type === 'select-focus-tab') {
    appStore.set({ dashboardStageFocusTab: command.tab, lastAction: `Alternou a aba ${command.label} da etapa` });
    return;
  }
  if (command.type === 'close-focus') {
    appStore.set({ dashboardStageFocus: '', dashboardStageFocusTab: 'overview', lastAction: 'Fechou a etapa em foco' });
    return;
  }
  if (command.type === 'open-focus-view') {
    const state = appStore.get();
    const stageKey = String(state.dashboardStageFocus || command.fallbackStageKey || '');
    if (command.view === 'agenda') appStore.set({ view: 'agenda', selectedStageV9: stageKey });
    else if (command.view === 'records') appStore.set({ view: 'records', selectedStageV9: stageKey });
  }
}

/** Apply a map-context intent emitted by the Dashboard component. */
export function applyAtlasDashboardMapContextCommandV1(input: {
  command: Extract<AtlasDashboardHomeCommandV1, { type: 'open-map-context' }>;
  appStore: { set(patch: Record<string, unknown>): unknown };
}): void {
  input.appStore.set({
    view: input.command.view,
    mapFilterWidget: input.command.key,
    lastAction: `Abriu contexto de ${input.command.label || 'camada'} no mapa`,
  });
}

/** Apply commercial and financial navigation commands emitted by the view. */
export function applyAtlasCommercialWorkspaceCommandV1(input: {
  command: AtlasCommercialWorkspaceCommandV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
}): void {
  const { command, appStore } = input;
  if (command.type === 'open-broker') {
    appStore.set({
      view: 'commissions',
      selectedCommissionProfile: command.profileId,
      selectedCommissionContract: null,
      lastAction: 'Abriu carteira do corretor',
    });
    return;
  }
  if (command.type === 'open-finance-report') {
    appStore.set({
      view: 'finance',
      reportFamily: 'Financeiro',
      reportType: command.reportId,
      lastAction: 'Abriu planilha financeira',
    });
    return;
  }
  appStore.set({
    reportPeriod: command.period,
    lastAction: `Alterou período para ${command.label}`,
  });
}

/** Apply commission workspace state transitions emitted by its DOM controller. */
export function applyAtlasCommissionWorkspaceCommandV1(input: {
  command: AtlasCommissionWorkspaceComponentCommandV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  commissionDeals: AtlasCommissionDealV1[];
  DateCtor: DateConstructor;
  formatBRL(value: unknown): string;
  brlToNumber(value: unknown): number;
}): void {
  const { command, appStore } = input;
  if (command.type === 'commission-filter') {
    const current = appStore.get();
    appStore.set({
      commissionFilters: { ...(current.commissionFilters || {}), [command.key]: command.value },
      lastAction: 'Filtrou lançamentos de comissão',
    });
    return;
  }
  if (command.type === 'commission-clear-filters') {
    appStore.set({
      commissionFilters: { query: '', status: 'all', profile: 'all' },
      lastAction: 'Limpou filtros de comissões',
    });
    return;
  }
  if (command.type === 'commission-exported') {
    appStore.set({ lastAction: 'Exportou carteira de comissões' });
    return;
  }
  if (command.type === 'commission-new-entry') {
    appStore.set({
      view: 'contracts',
      commissionEditorOpen: false,
      commissionEditing: null,
      proposalFormOpen: true,
      selectedCommissionProposal: null,
      selectedCommissionContract: null,
      lastAction: 'Abriu nova venda de lote',
    });
    return;
  }
  if (command.type === 'commission-cancel-entry') {
    appStore.set({ commissionEditorOpen: false, commissionEditing: null, lastAction: 'Fechou lançamento de comissão' });
    return;
  }
  if (command.type === 'commission-edit-entry') {
    const current = appStore.get();
    const deal = [...input.commissionDeals, ...(current.commissionEntries || [])]
      .find(item => item.id === command.id);
    if (deal) appStore.set({ commissionEditorOpen: true, commissionEditing: deal, lastAction: `Editou ${deal.id}` });
    return;
  }
  if (command.type === 'commission-delete-entry') {
    const current = appStore.get();
    appStore.set({
      commissionHiddenIds: [...(current.commissionHiddenIds || []), command.id],
      lastAction: `Excluiu lançamento ${command.id}`,
    });
    return;
  }
  if (command.type === 'commission-open-deal') {
    const deal = input.commissionDeals.find(item => item.id === command.id);
    if (deal) appStore.set({ selectedCommissionContract: deal.id, lastAction: `Abriu contrato ${deal.id}` });
    return;
  }

  const current = appStore.get();
  const values = command.values;
  const entry = createAtlasCommissionEntryV1({
    editingId: (current.commissionEditing as { id?: string } | null)?.id,
    profile: values.profile,
    lot: values.lot,
    client: values.client,
    status: values.status,
    value: values.value,
    rate: values.rate,
    now: input.DateCtor.now(),
    dateLabel: new input.DateCtor().toLocaleDateString('pt-BR'),
    formatBRL: input.formatBRL,
    brlToNumber: input.brlToNumber,
  });
  appStore.set({
    commissionEntries: [...(current.commissionEntries || []).filter(item => item.id !== entry.id), entry],
    commissionEditorOpen: false,
    commissionEditing: null,
    lastAction: `Salvou lançamento ${entry.id}`,
  });
}

/** Apply lead toolbar state transitions emitted by its DOM controller. */
export function applyAtlasLeadsToolbarCommandV1(input: {
  command: AtlasLeadsToolbarComponentCommandV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
}): void {
  if (input.command.type === 'set-filter') {
    const current = input.appStore.get();
    input.appStore.set({
      leadFilters: { ...(current.leadFilters || {}), [input.command.key]: input.command.value },
      lastAction: 'Filtrou a lista comercial',
    });
  } else if (input.command.type === 'clear-filters') {
    input.appStore.set({ leadFilters: { query: '', objective: 'all', status: 'all' }, lastAction: 'Limpou filtros de leads' });
  } else {
    input.appStore.set({ lastAction: 'Exportou lista de leads' });
  }
}

/** Apply reports controls and export effects emitted by the legacy reports component. */
export function applyAtlasLegacyReportsComponentCommandV1(input: {
  command: AtlasLegacyReportsComponentCommandV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  reportCatalog: typeof reportCatalogData;
  syncLiveSystemReportV1(state: Record<string, unknown>): void;
  notify: AtlasLegacyViewLayerDependenciesV1['notify'];
  documentRef: Document;
  URLCtor: Pick<typeof URL, 'createObjectURL' | 'revokeObjectURL'>;
  BlobCtor: typeof Blob;
  setTimeoutRef: typeof setTimeout;
  print(): void;
}): void {
  const { command, appStore } = input;
  if (command.type === 'select-family') {
    const first = input.reportCatalog.find(report => report.family === command.family);
    appStore.set({
      reportFamily: command.family,
      ...(first ? { reportType: first.id } : {}),
      reportExpandedRows: [],
      lastAction: first ? `Abriu ${first.label}` : `Selecionou família de relatório ${command.family}`,
    });
    return;
  }
  if (command.type === 'select-report') {
    const report = input.reportCatalog.find(item => item.id === command.reportId);
    appStore.set({
      ...(report ? { reportFamily: report.family } : {}),
      reportType: report?.id || command.reportId,
      reportExpandedRows: [],
      lastAction: report ? `Abriu ${report.label}` : 'Selecionou relatório',
    });
    return;
  }
  if (command.type === 'select-period') {
    appStore.set({ reportPeriod: command.period, lastAction: `Alterou período do relatório para ${command.label}` });
    return;
  }
  if (command.type === 'toggle-row') {
    const expanded = new Set(appStore.get().reportExpandedRows || []);
    if (command.open) expanded.add(command.index);
    else expanded.delete(command.index);
    appStore.set({ reportExpandedRows: [...expanded] });
    return;
  }
  if (command.type === 'print-report') {
    input.print();
    appStore.set({ lastAction: 'Abriu impressão do relatório' });
    return;
  }

  input.syncLiveSystemReportV1(appStore.get());
  const state = appStore.get();
  const report = input.reportCatalog.find(item => item.id === state.reportType) || input.reportCatalog[0];
  if (!report) return;
  const projection = projectAtlasReportExportV1(report as ReportDefinition);
  const url = input.URLCtor.createObjectURL(
    new input.BlobCtor([projection.csv], { type: 'text/csv;charset=utf-8' }),
  );
  const link = input.documentRef.createElement('a');
  link.href = url;
  link.download = projection.fileName;
  link.click();
  input.setTimeoutRef(() => input.URLCtor.revokeObjectURL(url), 1000);
  input.notify(projection.notice, 'success');
  appStore.set({ lastAction: `Exportou ${report.label}` });
}

/** Apply record-editor commands and forward persistence payloads to the operational record owner. */
export function applyAtlasLegacyRecordEditorCommandV1(input: {
  command: AtlasLegacyRecordEditorComponentCommandV1;
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  confirmRef(message: string): boolean;
}): void {
  const { command, appStore } = input;
  if (command.kind === 'open-new') {
    appStore.set({ editingRecord: 'new', recordContext: null, lastAction: 'Abriu formulário de novo registro' });
    return;
  }
  if (command.kind === 'edit') {
    appStore.set({ editingRecord: command.id, lastAction: `Editou registro ${command.id}` });
    return;
  }
  if (command.kind === 'cancel') {
    appStore.set({ editingRecord: null });
    return;
  }
  if (command.kind === 'delete') {
    if (!input.confirmRef('Excluir este registro?')) return;
    command.element.dispatchEvent(new CustomEvent<AtlasLegacyOperationalRecordDeleteCommandV1>('atlas:view-record-delete', {
      bubbles: true,
      detail: { element: command.element, id: command.id },
    }));
    return;
  }
  const rawEditingId = appStore.get().editingRecord;
  const editingId = rawEditingId && rawEditingId !== 'new' ? String(rawEditingId) : null;
  const detail: AtlasLegacyOperationalRecordSaveCommandV1 = {
    element: command.element,
    editingId,
    values: command.values,
    nature: command.nature,
    contextFields: command.contextFields,
    attachments: command.attachments,
  };
  command.element.dispatchEvent(new CustomEvent<AtlasLegacyOperationalRecordSaveCommandV1>('atlas:view-record-save', {
    bubbles: true,
    detail,
  }));
}

