/** Install dashboard, stage detail, agenda, and activity owners in bootstrap order. */
export function installAtlasStageOperationalPagesCompositionV1(
  input: AtlasStageOperationalPagesCompositionInputV1,
): ReturnType<typeof createAtlasStageOperationalModelV1> & {
  stageV9EscList(items: unknown, empty?: string): string;
  dashboardHomePageV1: ReturnType<typeof installAtlasDashboardHomePageV1>;
} {
  const {
    ViewLayer, appStore, demoData, executionModel, activityCatalog, extensionStage,
    stageOverlayKey, stageProfileSettingsFor, stageMaterialsFor, formatBRL, apiFetch,
    esc, ico, workbenchActivityRouteV1, notify,
  } = input;
  const globalRef = input.globalRef || globalThis;
  const stageOperationalModelInputV1: AtlasStageOperationalModelInputV1 = {
    appStore, demoData, executionModel, stageOverlayKey,
    stageProfileSettingsFor, stageMaterialsFor,
  };
  const stageOperationalModelV1 = createAtlasStageOperationalModelV1(stageOperationalModelInputV1);
  const {
    stageOf, stageV9LiveFor, stageV9ByState, stageV9ProfileFor,
    stageV9ProductionFor, stageV9MaterialsFor, stageV9BudgetFor,
    stageV9StatusFor, stageV9DirectiveText, stageV9FlowPackets,
  } = stageOperationalModelV1;
  const stageV9EscList = (items: unknown, empty = 'Não configurado'): string =>
    renderAtlasStageEscListV1(items, esc, empty);

  const dashboardHomeDependenciesV1: AtlasStageOperationalDashboardDependenciesV1 = {
    ViewLayer,
    readState: () => appStore.get(),
    demoData,
    executionModel,
    formatBRL,
    esc,
    ico,
    stageV9DirectiveText,
    stageV9ProfileFor,
    loadQuickReport: kind => loadAtlasDashboardQuickReportV1({ kind, apiFetch }),
    onCommand: command => applyAtlasDashboardHomeCommandV1({
      command,
      appStore,
      executionStages: executionModel.stages || [],
      demoStages: demoData.activities || [],
      workbenchActivityRouteV1,
      navigateTo: url => globalRef.window.location.assign(url),
    }),
    documentRef: globalRef.document,
    URLCtor: globalRef.URL,
    BlobCtor: globalRef.Blob,
    notify,
    windowRef: globalRef.window,
  };
  const dashboardHomePageV1 = installAtlasDashboardHomePageV1(dashboardHomeDependenciesV1);

  const stageDedicatedPageDependenciesV1: Parameters<typeof installAtlasStageDedicatedPageBaseV1>[1] = {
    readState: () => appStore.get(),
    executionModel,
    stageV9ByState,
    stageV9LiveFor,
    stageV9ProfileFor,
    stageV9MaterialsFor,
    stageV9FlowPackets,
    stageV9BudgetFor,
    stageOf,
    stageV9StatusFor,
    stageV9ProductionFor,
    stageV9DirectiveText,
    formatBRL,
    esc,
    ico,
  };
  installAtlasStageDedicatedPageBaseV1(ViewLayer, stageDedicatedPageDependenciesV1);

  const stageV9DedicatedAgendaBase = ViewLayer.prototype.activityDedicatedPage;
  const calendarPortsV1: AtlasStageAgendaCalendarPortsV1 = {
    isoDate: (date) => input.agendaCalendarIsoV3(date),
    parseDate: (value) => input.agendaCalendarParseDateV3(value),
    timeToHours: (value) => input.agendaCalendarTimeToHoursV3(value),
    eventEnd: (event) => input.agendaCalendarEventEndV3(event),
  };
  const typedStageAgendaNextSlotV1 = (events: AtlasStageAgendaCalendarEventV1[], durationHours = 1.5) =>
    projectAtlasStageAgendaNextSlotV1(events || [], durationHours, new globalRef.Date(), calendarPortsV1);
  const createStageAgendaEventV1 = createAtlasStageAgendaEventWriterV1({
    appStore,
    executionStages: executionModel.stages || [],
    stageV9FlowPackets,
    readCalendar: () => input.agendaCalendarReadV3(),
    writeCalendar: data => input.agendaCalendarWriteV3(data),
    weekKey: date => input.agendaCalendarWeekKeyV8(date),
    calendarPorts: calendarPortsV1,
    nowMs: () => globalRef.Date.now(),
    random: () => globalRef.Math.random(),
  });
  const stageAgendaPageDependenciesV1: AtlasStageOperationalAgendaDependenciesV1 = {
    readState: () => appStore.get() as AtlasStageAgendaStateV1,
    onAction: action => {
      if (action.kind === 'open-agenda-event') {
        appStore.set({ view: 'agenda', selectedAgendaEventV3: action.eventId, lastAction: 'Abriu atividade na agenda' });
      }
    },
    executionModel,
    stageV9ByState,
    stageV9LiveFor,
    stageV9FlowPackets,
    stageOf,
    agendaCalendarReadV3: () => input.agendaCalendarReadV3(),
    agendaCalendarOperationalEventsV3: (state: AtlasStageAgendaStateV1) => input.agendaCalendarOperationalEventsV3(state),
    controlCenterMaterialRowsV1: (state: AtlasStageAgendaStateV1) => input.controlCenterMaterialRowsV1(state),
    stageAgendaNextSlotV1: typedStageAgendaNextSlotV1,
    projectStageAgendaMaterialsV1: projectAtlasStageAgendaMaterialsV1,
    createStageAgendaEventV1,
    stageV9DedicatedAgendaBase,
    ensureAgendaCalendarLoadedV8: () => input.ensureAgendaCalendarLoadedV8?.(),
    esc,
    FormData: globalRef.FormData,
  };
  installAtlasStageAgendaPageV1(ViewLayer, stageAgendaPageDependenciesV1);

  const loadStageActivitiesV1 = createAtlasStageActivityAdminLoaderV1({ appStore, apiFetch });
  const stageActivityPageDependenciesV1 = {
    readState: () => appStore.get(),
    onAction: (action: AtlasStageActivityPageActionV1) => applyAtlasStageActivityPageActionV1({ action, appStore, loadActivities: loadStageActivitiesV1 }),
    installActivityAdminMutations: (page: HTMLElement, reload: () => Promise<void>) => installAtlasActivityAdminMutationCommandsV1({
      page,
      appStore,
      apiFetch,
      reload,
      confirm: message => Boolean(globalRef.confirm?.(message)),
    }),
    dispatchNavigation: (command: AtlasStageActivityNavigationCommandV1) => applyAtlasStageActivityNavigationV1({
      appStore: appStore as unknown as AtlasApplicationStore<AtlasApplicationStoreState>,
      executionModel: { stages: executionModel.stages as unknown as AtlasStageActivityStageV1[] },
      extensionStage: () => extensionStage() as unknown as AtlasStageActivityStageV1 | null,
      stageV9FlowPackets: stage => stageV9FlowPackets(stage as unknown as AtlasStageOperationalStageV1) as unknown as AtlasStageActivityFlowPacketV1[],
      command: command as unknown as AtlasStageActivityNavigationCommandV1,
    }),
    executionModel,
    activityCatalog,
    extensionStage: () => extensionStage() || {},
    stageV9FlowPackets,
    stageV9ByState,
    stageV9ProfileFor,
    stageV9LiveFor,
    stageV9MaterialsFor,
    stageV9BudgetFor,
    stageOf,
    stageV9ProductionFor,
    stageV9DirectiveText,
    formatBRL,
    esc,
    ico,
    notify,
    workbenchActivityRouteV1,
    globalRef,
  } as unknown as AtlasStageOperationalActivityDependenciesV1;
  installAtlasStageActivityPageV1(ViewLayer, stageActivityPageDependenciesV1);

  return Object.freeze({ ...stageOperationalModelV1, stageV9EscList, dashboardHomePageV1 });
}

