export interface AtlasStageAgendaCalendarPortsV1 {
  isoDate(date: Date): string;
  parseDate(value: unknown): Date | null;
  timeToHours(value: unknown): number;
  eventEnd(event: AtlasStageAgendaCalendarEventV1): number;
}

/** Find the first half-hour appointment slot inside weekday work hours. */
export function projectAtlasStageAgendaNextSlotV1(
  events: AtlasStageAgendaCalendarEventV1[],
  durationHours = 1.5,
  from = new Date(),
  ports: AtlasStageAgendaCalendarPortsV1,
): AtlasStageAgendaSlotV1 | null {
  const minutes = Math.max(30, Math.min(8 * 60, Math.ceil(Number(durationHours || 1.5) * 2) * 30));
  const beginning = new Date(from);
  beginning.setMinutes(Math.ceil(beginning.getMinutes() / 30) * 30, 0, 0);
  for (let dayOffset = 0; dayOffset < 90; dayOffset++) {
    const day = new Date(beginning.getFullYear(), beginning.getMonth(), beginning.getDate() + dayOffset);
    if (day.getDay() === 0 || day.getDay() === 6) continue;
    const date = ports.isoDate(day);
    for (let startMinute = 8 * 60; startMinute + minutes <= 18 * 60; startMinute += 30) {
      const candidate = new Date(day.getFullYear(), day.getMonth(), day.getDate(), Math.floor(startMinute / 60), startMinute % 60);
      if (candidate < beginning) continue;
      const end = candidate.getTime() + minutes * 60_000;
      const conflict = events.some((event) => {
        const eventDay = ports.parseDate(event.date);
        if (!eventDay) return false;
        const hour = ports.timeToHours(event.start);
        const start = new Date(eventDay.getFullYear(), eventDay.getMonth(), eventDay.getDate(), Math.floor(hour), Math.round((hour % 1) * 60)).getTime();
        return candidate.getTime() < ports.eventEnd(event) && end > start;
      });
      if (!conflict) return { date, start: `${String(Math.floor(startMinute / 60)).padStart(2, '0')}:${String(startMinute % 60).padStart(2, '0')}` };
    }
  }
  return null;
}

/** Validate a stage appointment's weekday work window and calendar conflicts. */
export function validateAtlasStageAgendaSlotV1(
  input: { date: string; start: string; durationHours: number; events: AtlasStageAgendaCalendarEventV1[] },
  ports: AtlasStageAgendaCalendarPortsV1,
): 'invalid' | 'conflict' | null {
  const day = ports.parseDate(input.date);
  const startHour = ports.timeToHours(input.start);
  const duration = Number(input.durationHours);
  if (!day || day.getDay() === 0 || day.getDay() === 6 || !Number.isFinite(duration) || duration < 0.5 || duration > 8 || startHour < 8 || startHour + duration > 18) return 'invalid';
  const slotStart = new Date(day.getFullYear(), day.getMonth(), day.getDate(), Math.floor(startHour), Math.round((startHour % 1) * 60)).getTime();
  const slotEnd = slotStart + duration * 3_600_000;
  const conflict = input.events.some((event) => {
    const eventDay = ports.parseDate(event.date);
    if (!eventDay) return false;
    const hour = ports.timeToHours(event.start);
    const otherStart = new Date(eventDay.getFullYear(), eventDay.getMonth(), eventDay.getDate(), Math.floor(hour), Math.round((hour % 1) * 60)).getTime();
    return slotStart < ports.eventEnd(event) && slotEnd > otherStart;
  });
  return conflict ? 'conflict' : null;
}

export interface AtlasStageAgendaCreateEventWriterPortsV1 {
  appStore: AtlasApplicationStore<AtlasApplicationStoreState>;
  executionStages: AtlasStageOperationalStageV1[];
  stageV9FlowPackets(stage: AtlasStageOperationalStageV1): AtlasStageOperationalFlowPacketV1[];
  readCalendar(): AgendaCalendarSnapshotV3;
  writeCalendar(data: { version?: 3; initialized?: boolean; events?: OperationalAgendaEvent[] }): Promise<OperationalAgendaEvent[]>;
  weekKey(date: string): string;
  calendarPorts: AtlasStageAgendaCalendarPortsV1;
  nowMs(): number;
  random(): number;
}

/** Create and persist a custom stage appointment, then project its confirmed state. */
export function createAtlasStageAgendaEventWriterV1(
  ports: AtlasStageAgendaCreateEventWriterPortsV1,
): (draft: AtlasStageAgendaCreateEventDraftV1) => Promise<AtlasStageAgendaCreateEventResultV1> {
  return async (draft) => {
    const stored = ports.readCalendar();
    if (!stored.initialized) return { status: 'loading' };
    const stageKey = String(draft.stageKey || '');
    const stage = ports.executionStages.find(item => String(item.key) === stageKey);
    const date = String(draft.date || ''), start = String(draft.start || '');
    const durationHours = Number(draft.durationHours);
    const slotStatus = validateAtlasStageAgendaSlotV1({ date, start, durationHours, events: stored.events }, ports.calendarPorts);
    if (!stage || slotStatus === 'invalid') return { status: 'invalid' };
    if (slotStatus === 'conflict') return { status: 'conflict' };
    const title = String(draft.title || '').trim();
    if (!title) return { status: 'title-required' };
    const packetKey = String(draft.relatedPacket || '');
    const packet = ports.stageV9FlowPackets(stage).find(item => item.key === packetKey);
    const id = `agenda-stage-${ports.nowMs().toString(36)}-${ports.random().toString(36).slice(2, 6)}`;
    const event: OperationalAgendaEvent = {
      id,
      title,
      stageKey: stage.key,
      stageName: stage.name,
      activityId: packet ? `${stage.key}:${packet.key}` : id,
      activityName: title,
      relatedPacket: packet?.key || '',
      owner: String(draft.owner || '').trim(),
      date,
      start,
      durationHours,
      spanDays: 1,
      status: String(draft.status || 'Planejado'),
      notes: String(draft.notes || '').trim(),
      materialIds: (Array.isArray(draft.materialIds) ? draft.materialIds : []).map(String).filter(Boolean),
      stageAgendaCustomV1: true,
    };
    const events = await ports.writeCalendar({ version: 3, initialized: true, events: [...stored.events, event] });
    if (!events.some(item => item.id === id)) throw new Error('O banco não confirmou o compromisso salvo.');
    const state = ports.appStore.get() as AtlasStageAgendaStateV1;
    ports.appStore.set({
      stageAgendaItems: [...(state.stageAgendaItems || []), event],
      agendaCalendarWeekV8: ports.weekKey(date),
      lastAction: `Adicionou atividade ${title} à agenda de ${stage.name}`,
    });
    return { status: 'saved', event, events };
  };
}

export interface AtlasStageAgendaMaterialProofV1 {
  id: string;
  name: string;
  status: string;
  activityName: string;
  quantity: unknown;
  unit: string;
  description: string;
  proofName: string;
  proofRecordId: string;
}

/** Associate stage materials with matching stage records and their evidence. */
export function projectAtlasStageAgendaMaterialsV1(
  materials: AtlasStageAgendaMaterialV1[],
  records: AtlasStageAgendaRecordV1[],
  stageName: string,
  stageOf: (record: AtlasStageAgendaRecordV1) => string,
): AtlasStageAgendaMaterialProofV1[] {
  const normalizedStage = stageName.toLocaleLowerCase('pt-BR');
  const stageRecords = records.filter((record) => String(stageOf(record) || '').toLocaleLowerCase('pt-BR') === normalizedStage);
  return materials.map((material) => {
    const identity = String(material.id || '').toLocaleLowerCase('pt-BR');
    const name = String(material.name || '').toLocaleLowerCase('pt-BR');
    const proof = stageRecords.find((record) => {
      const hasEvidence = Boolean(record.evidenceUri || record.comprovante || record.evidencias?.length || record.attachments?.length);
      if (!hasEvidence) return false;
      let properties = '';
      try { properties = JSON.stringify(record.properties || []); } catch { properties = ''; }
      const relation = `${record.detalhes || ''} ${record.materialId || ''} ${record.materialName || ''} ${properties}`.toLocaleLowerCase('pt-BR');
      return Boolean((identity && relation.includes(identity)) || (name && relation.includes(name)));
    });
    const source = proof?.attachments?.[0]?.fileName || proof?.evidencias?.[0]?.fileName || proof?.comprovante || proof?.evidenceUri || '';
    const proofName = typeof source === 'string' && !/^(data:|blob:)/i.test(source) ? source.split(/[\\/]/).pop()?.slice(0, 90) || 'Arquivo anexado' : proof ? 'Arquivo anexado' : '';
    return {
      id: String(material.id || ''),
      name: String(material.name || 'Material'),
      status: String(material.status || 'Planejado'),
      activityName: String(material.activityName || ''),
      quantity: material.quantity,
      unit: String(material.unit || 'un.'),
      description: String(material.description || material.scope || ''),
      proofName,
      proofRecordId: proof ? String(proof.id || 'sem ID') : '',
    };
  });
}

