/** Combine the JSON reason defaults with state overrides without changing the stored entries. */
export function projectAtlasBrokerCommissionReasonsV1(
  state: AtlasBrokerCommissionReportStateV1,
): AtlasBrokerCommissionReasonV1[] {
  const configured = Array.isArray(state.commissionReasons) ? state.commissionReasons : [];
  return (commissionReasonDefaultsData as AtlasBrokerCommissionReasonV1[]).map(defaults => ({
    ...defaults,
    ...(configured.find(item => item.id === defaults.id) || {}),
    id: defaults.id,
  }));
}

/** Preserve the broker commission ledger, reason allocation, and month/year totals in the typed program. */
export function projectAtlasBrokerCommissionReportV1(
  brokerName: unknown,
  state: AtlasBrokerCommissionReportStateV1,
  now = new Date().toISOString(),
): AtlasBrokerCommissionReportV1 | null {
  const name = String(brokerName || '').trim().replace(/\s+/g, ' ').toLocaleLowerCase('pt-BR');
  const profile = (commissionProfilesCatalogData as AtlasCommissionProfileCatalogEntry[]).find(item =>
    item.name.trim().replace(/\s+/g, ' ').toLocaleLowerCase('pt-BR') === name,
  );
  if (!profile) return null;

  const toNumber = (value: unknown): number =>
    Number(String(value || '').replace(/[^\d,]/g, '').replace(',', '.')) || 0;
  const reasons = projectAtlasBrokerCommissionReasonsV1(state);
  const deals = [
    ...(commissionDealsCatalogData as AtlasCommissionDealV1[]),
    ...(Array.isArray(state.commissionEntries) ? state.commissionEntries : []),
  ].filter(item => item?.profile === profile.id);
  let fallbackReasonIndex = 0;
  const allRows = deals.map(deal => {
    const reasonText = `${deal.reason || ''} ${deal.payment || ''} ${deal.stage || ''}`.toLocaleLowerCase('pt-BR');
    const reasonId: AtlasBrokerCommissionReasonV1['id'] = /mensal|parcela mensal/.test(reasonText)
      ? 'monthly'
      : /intermedi/.test(reasonText)
        ? 'intermediate'
        : /sinal|entrada|reserva/.test(reasonText)
          ? 'signal'
          : reasons[fallbackReasonIndex++ % Math.max(1, reasons.length)]?.id || 'signal';
    const reason = reasons.find(item => item.id === reasonId) || reasons[0];
    const numberValue = toNumber(deal.value);
    const numberCommission = toNumber(deal.commission);
    const warley = numberCommission * Number(reason?.warley || 0) / 100;
    return {
      ...deal,
      reason: reason || { id: 'signal', label: 'Sinal', sharePercent: 40, warley: 50, partner: 50, payment: 'À vista / sinal' },
      numberValue,
      numberCommission,
      warley,
      partner: numberCommission - warley,
    };
  });
  const periodKey = (value: unknown): string => {
    const raw = String(value || '').trim();
    if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 7);
    const br = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    return br ? `${br[3]}-${br[2].padStart(2, '0')}` : '';
  };
  const latest = allRows.map(row => periodKey(row.date)).filter(Boolean).sort().at(-1) || now.slice(0, 7);
  const mode = state.brokerPrintMode === 'monthly' ? 'monthly' : 'annual';
  const month = /^\d{4}-\d{2}$/.test(String(state.brokerPrintMonth || '')) ? String(state.brokerPrintMonth) : latest;
  const year = /^\d{4}$/.test(String(state.brokerPrintYear || '')) ? String(state.brokerPrintYear) : latest.slice(0, 4);
  const rows = allRows.filter(row => {
    const key = periodKey(row.date);
    return key && (mode === 'monthly' ? key === month : key.startsWith(year));
  });
  const totals = rows.reduce((sum, row) => ({
    value: sum.value + row.numberValue,
    commission: sum.commission + row.numberCommission,
    warley: sum.warley + row.warley,
    partner: sum.partner + row.partner,
  }), { value: 0, commission: 0, warley: 0, partner: 0 });
  const periodLabel = mode === 'monthly'
    ? new Date(`${month}-01T12:00:00`).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })
    : `Ano ${year}`;
  return { profile, mode, month, year, periodLabel, allRows, rows, totals };
}

