/** Model a local commission entry while retaining the contract fields used by commercial pages. */
export function createAtlasCommissionEntryV1(input: {
  editingId?: string | null;
  profile: unknown;
  lot: unknown;
  client: unknown;
  status: unknown;
  value: unknown;
  rate: unknown;
  now: number;
  dateLabel: string;
  formatBRL(value: unknown): string;
  brlToNumber(value: unknown): number;
}): AtlasCommissionDealV1 {
  const rate = Number(input.rate || 0);
  const lot = String(input.lot || "").toUpperCase();
  const value = input.formatBRL(input.value);
  return {
    id: input.editingId || `CT-LOCAL-${input.now.toString().slice(-6)}`,
    profile: String(input.profile || ""),
    lot,
    quadra: `Lote ${lot}`,
    client: String(input.client || ""),
    status: String(input.status || ""),
    value,
    commission: input.formatBRL((input.brlToNumber(value) * rate) / 100),
    rate: `${rate.toLocaleString("pt-BR", { minimumFractionDigits: 2 })}%`,
    date: input.dateLabel,
    payment: "A definir",
    purpose: "A definir",
    stage: "Cadastro comercial local",
  };
}

