/** Project the canonical JSON price table with the current locally persisted commercial controls. */
export function projectAtlasLotBoardRows(
  lotStatuses: Record<string, AtlasLotStatus | undefined> = {},
  catalog: RepassePriceCatalogEntry[] = repassePriceCatalogData as RepassePriceCatalogEntry[],
  receivables: readonly AtlasLotBoardReceivableV1[] = [],
): AtlasLotBoardRow[] {
  const normalizeLotKey = (value: unknown): string => String(value || '').toLocaleUpperCase('pt-BR').replace(/[^\p{L}\p{N}]/gu, '');
  const receivableByLot = new Map(receivables.map(item => [normalizeLotKey(item.lotKey), item]));
  return catalog.map(item => {
    const key = String(item.label || `${item.quadra}-${item.lot}`);
    const status = lotStatuses[key];
    const receivable = receivableByLot.get(normalizeLotKey(key));
    return {
      ...item,
      label: key,
      status: String(status?.status || 'Disponível'),
      paymentStatus: String(status?.payment?.status || 'Pendente'),
      sellerId: String(status?.sellerId || ''),
      sellerName: String(status?.sellerName || ''),
      note: String(status?.note || ''),
      updatedAt: String(status?.updatedAt || ''),
      hasControl: Boolean(status),
      contractPriceCents: receivable?.contractPriceCents ?? null,
      receivedCents: receivable?.receivedCents ?? 0,
      remainingCents: receivable?.remainingCents ?? null,
      balanceStatus: receivable?.status ?? 'Sem venda',
    };
  });
}

/** Use the same persisted sales, receivables, contract base, and cents rounding as Repasses. */
export function projectAtlasLotBoardReceivablesV1(
  sales: readonly RepasseSale[],
  reasons: RepasseOperations['reasons'],
): AtlasLotBoardReceivableV1[] {
  const normalizeLotKey = (value: unknown): string => String(value || '').toLocaleUpperCase('pt-BR').replace(/[^\p{L}\p{N}]/gu, '');
  const resolveSaleLotKey = (sale: RepasseSale): string => {
    const catalogLabel = String(sale.tablePrice?.label || '').trim();
    if (catalogLabel) return catalogLabel;
    const lot = String(sale.lot || '').trim();
    const quadra = String(sale.tablePrice?.quadra || '').trim();
    return quadra && /^\d+$/.test(lot) ? `${quadra}-${lot}` : lot;
  };
  const latestSaleByLot = new Map<string, RepasseSale>();
  for (const sale of sales) {
    const lotKey = normalizeLotKey(resolveSaleLotKey(sale));
    if (!lotKey) continue;
    const current = latestSaleByLot.get(lotKey);
    const currentAt = Date.parse(current?.updatedAt || current?.createdAt || '') || 0;
    const saleAt = Date.parse(sale.updatedAt || sale.createdAt || '') || 0;
    if (!current || saleAt >= currentAt) latestSaleByLot.set(lotKey, sale);
  }
  const reportBySale = new Map(projectAtlasRepasseReportsV1([...latestSaleByLot.values()], reasons).map(report => [report.saleId, report]));
  return [...latestSaleByLot.entries()].map(([lotKey, sale]) => {
    const report = reportBySale.get(sale.id);
    const normalizedStatus = String(sale.status || '').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const canceled = normalizedStatus === 'cancelado' || normalizedStatus === 'cancelada';
    const contractPriceCents = report?.basePriceCents ?? 0;
    const receivedCents = report?.receivedCents ?? 0;
    const remainingCents = canceled ? null : Math.max(0, contractPriceCents - receivedCents);
    const status: AtlasLotBoardReceivableV1['status'] = canceled
      ? 'Cancelado'
      : remainingCents === 0 ? 'Quitado' : receivedCents > 0 ? 'Parcial' : 'Pendente';
    return { lotKey: resolveSaleLotKey(sale) || lotKey, saleId: sale.id, contractPriceCents, receivedCents, remainingCents, status };
  });
}

/** Aggregate the same price catalog and local statuses shown by Lotes for the dashboard. */
export function projectAtlasDashboardLotAnalysis(
  rows: AtlasLotBoardRow[],
  policy: { statuses: Array<{ label: string; aliases: string[]; committed: boolean }>; valueByBlockLimit: number } = dashboardLotAnalysisData as { statuses: Array<{ label: string; aliases: string[]; committed: boolean }>; valueByBlockLimit: number },
): AtlasDashboardLotAnalysis {
  const normalize = (value: unknown) => String(value || '').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const statusByAlias = new Map<string, typeof policy.statuses[number]>();
  for (const status of policy.statuses) {
    statusByAlias.set(normalize(status.label), status);
    for (const alias of status.aliases) statusByAlias.set(normalize(alias), status);
  }
  const source = rows.filter(row => Number(row.lot) > 0 && Number(row.price) > 0);
  const counts = new Map(policy.statuses.map(status => [status.label, 0]));
  const blocks = new Map<string, AtlasDashboardLotBlockSummary>();
  let totalArea = 0, totalValue = 0, committedCount = 0;
  for (const row of source) {
    const status = statusByAlias.get(normalize(row.status)) || policy.statuses[0];
    counts.set(status.label, (counts.get(status.label) || 0) + 1);
    if (status.committed) committedCount += 1;
    const area = Number(row.area) || 0, value = Number(row.price) || 0;
    totalArea += area; totalValue += value;
    const quadra = String(row.quadra || 'Sem quadra');
    const block = blocks.get(quadra) || { quadra, lots: 0, area: 0, value: 0, available: 0, committed: 0 };
    block.lots += 1; block.area += area; block.value += value;
    if (status.committed) block.committed += 1;
    else block.available += 1;
    blocks.set(quadra, block);
  }
  const grouped = [...blocks.values()].sort((left, right) => left.quadra.localeCompare(right.quadra, 'pt-BR', { numeric: true }));
  const topValueBlocks = [...grouped].sort((left, right) => right.value - left.value).slice(0, Math.max(1, Math.trunc(Number(policy.valueByBlockLimit) || 8)));
  return {
    lotCount: source.length,
    totalArea,
    totalValue,
    committedCount,
    statuses: policy.statuses.map(status => ({ label: status.label, count: counts.get(status.label) || 0, committed: status.committed })),
    blocks: grouped,
    topValueBlocks,
  };
}

/** Project the shared JSON broker profile catalog into seller options for lot controls. */
export function projectAtlasLotBoardSellers(
  profiles: AtlasCommissionProfileCatalogEntry[] = commissionProfilesCatalogData as AtlasCommissionProfileCatalogEntry[],
): AtlasLotBoardSeller[] {
  return profiles.map(({ id, name }) => ({ id: String(id), name: String(name) }));
}

/** Build the local status command without mutating persisted state in place. */
export function createAtlasLotStatusCommand(input: {
  lotStatuses: Record<string, AtlasLotStatus | undefined>;
  lotKey: string;
  status: AtlasLotCommercialStatus;
  seller: AtlasLotBoardSeller | null;
  note: string;
  updatedAt: string;
}): { lotStatuses: Record<string, AtlasLotStatus | undefined>; lastAction: string } {
  const next: AtlasLotStatus = {
    ...(input.lotStatuses[input.lotKey] || {}),
    status: input.status,
    sellerId: input.seller?.id || '',
    sellerName: input.seller?.name || '',
    note: input.note,
    updatedAt: input.updatedAt,
  };
  return {
    lotStatuses: { ...input.lotStatuses, [input.lotKey]: next },
    lastAction: `Atualizou controle do lote ${input.lotKey}`,
  };
}

/** Apply lot-board status and navigation commands to canonical application state. */
export function applyAtlasLotBoardComponentCommandV1(input: {
  command: AtlasLotBoardComponentCommandV1;
  appStore: AtlasLotStatusCommandStoreV1;
  now?: () => Date;
}): void {
  const { command, appStore } = input;
  if (command.type === 'save-status') {
    const seller = projectAtlasLotBoardSellers().find(item => item.id === command.sellerId) || null;
    appStore.set(createAtlasLotStatusCommand({
      lotStatuses: appStore.get().lotStatuses || {},
      lotKey: command.lotKey,
      status: command.status,
      seller,
      note: command.note,
      updatedAt: (input.now || (() => new Date()))().toISOString(),
    }));
    return;
  }
  if (command.type === 'delete-status') {
    const next = { ...(appStore.get().lotStatuses || {}) };
    delete next[command.lotKey];
    appStore.set({ lotStatuses: next, lastAction: `Excluiu controle do lote ${command.lotKey}` });
    return;
  }
  if (command.view === 'lot-detail') {
    appStore.set({ view: 'lot-detail', selectedLotDetailKey: command.lotKey, lotDetailReturnView: 'brokers-board', lastAction: `Abriu a ficha do lote ${command.lotKey}` });
    return;
  }
  appStore.set({ view: 'repasses', repasseSelectedLotKey: command.lotKey, repasseSelectedSaleId: '', lastAction: `Abriu Repasses para o lote ${command.lotKey}` });
}

