export const PUBLIC_RESERVATION_OCR_POLICY_V1 = Object.freeze(publicReservationPolicyCatalog.ocr);

/** Match the current reservation form's required identity fields before OCR starts. */
export function isAtlasPublicReservationIdentityReadyV1(fullName: string, cpfValue: string): boolean {
  return Boolean(String(fullName || '').trim()) && String(cpfValue || '').replace(/\D/g, '').length === 11;
}

export interface AtlasPublicReservationReviewInputV1 {
  fullName: string;
  cpf: string;
  recognizedText?: string | null;
  ocrUnavailable?: boolean;
}

/** Keep OCR output interpretation in the application program, beside reservation policy. */
export function evaluateAtlasPublicReservationReviewV1(input: AtlasPublicReservationReviewInputV1): typeof PUBLIC_RESERVATION_REVIEW_RESULT_CODES_V1[keyof typeof PUBLIC_RESERVATION_REVIEW_RESULT_CODES_V1] {
  const codes = PUBLIC_RESERVATION_REVIEW_RESULT_CODES_V1;
  if (input.ocrUnavailable) return codes.ocrUnavailable;
  if (input.recognizedText == null) return codes.humanReview;
  const digits = (value: string): string => String(value || '').replace(/\D/g, '');
  const cpf = digits(input.cpf);
  const text = String(input.recognizedText).toUpperCase();
  const tokens = String(input.fullName || '').toUpperCase().split(/\s+/)
    .filter(token => token.length >= PUBLIC_RESERVATION_OCR_POLICY_V1.minimumNameTokenLength);
  const matchedTokens = tokens.filter(token => text.includes(token)).length;
  return digits(text).includes(cpf)
    && matchedTokens >= Math.min(PUBLIC_RESERVATION_OCR_POLICY_V1.minimumMatchingNameTokens, tokens.length)
    ? codes.compatible
    : codes.inconclusive;
}

function publicReservationPixFieldV1(id: string, value: string): string {
  return `${String(id).padStart(2, '0')}${String(value).length.toString().padStart(2, '0')}${value}`;
}

function publicReservationPixCrc16V1(value: string): string {
  let crc = 0xffff;
  for (let index = 0; index < value.length; index += 1) {
    crc ^= value.charCodeAt(index) << 8;
    for (let bit = 0; bit < 8; bit += 1) crc = (crc & 0x8000) ? (crc << 1) ^ 0x1021 : crc << 1;
  }
  return (crc & 0xffff).toString(16).toUpperCase().padStart(4, '0');
}

export interface AtlasPublicReservationPixPaymentV1 { amount: number; payload: string; transactionId: string }

/** Read local reservation settings and project the existing Pix EMV payload. */
export function createAtlasPublicReservationPixPaymentV1(settingsValue: unknown): AtlasPublicReservationPixPaymentV1 | null {
  const settings = settingsValue && typeof settingsValue === 'object' && !Array.isArray(settingsValue)
    ? settingsValue as Record<string, unknown> : {};
  if (!settings.pixKey) return null;
  const policy = publicReservationPolicyCatalog.pix;
  const amount = Math.max(0, Number(settings.signalAmount || policy.defaultSignalAmount));
  const transactionId = `${policy.transactionIdPrefix}${Date.now().toString(36).toUpperCase()}`;
  const clean = (value: string): string => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
  const merchant = publicReservationPixFieldV1('00', policy.gui)
    + publicReservationPixFieldV1('01', String(settings.pixKey));
  const base = publicReservationPixFieldV1('00', '01')
    + publicReservationPixFieldV1('26', merchant)
    + publicReservationPixFieldV1('52', policy.merchantCategoryCode)
    + publicReservationPixFieldV1('53', policy.currency)
    + (amount ? publicReservationPixFieldV1('54', amount.toFixed(2)) : '')
    + publicReservationPixFieldV1('58', policy.country)
    + publicReservationPixFieldV1('59', clean(String(settings.pixReceiver || policy.defaultReceiver)).slice(0, 25))
    + publicReservationPixFieldV1('60', clean(String(settings.pixCity || policy.defaultCity)).slice(0, 15))
    + publicReservationPixFieldV1('62', publicReservationPixFieldV1('05', String(transactionId || policy.transactionIdFallback).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || policy.transactionIdFallback))
    + '6304';
  return { amount, transactionId, payload: base + publicReservationPixCrc16V1(base) };
}

