export interface AtlasActivityMapStatusV1 { label: string; color: string; hex: number; priority: number }
export type AtlasActivityMapStatusKeyV1 = 'scheduled' | 'in_progress' | 'completed' | 'blocked';
export type AtlasActivityMapStatusCatalogV1 = Record<AtlasActivityMapStatusKeyV1, AtlasActivityMapStatusV1>;
export interface AtlasActivityMapLeadGroupV1 { number: string; label: string; count: number; selected: boolean }
export interface AtlasActivityMapAssignmentV1 { status?: unknown; partIds?: unknown; [key: string]: unknown }
export interface AtlasActivityMapProjectedAssignmentV1 { partId: string; assignment: AtlasActivityMapAssignmentV1; statusKey: AtlasActivityMapStatusKeyV1; status: AtlasActivityMapStatusV1 }
export const ACTIVITY_MAP_STATUSES_V1 = Object.freeze(activityMapStatusesData as unknown as AtlasActivityMapStatusCatalogV1);

/** Normalize the lot number used to bind lead and workbench activity overlays to map parts. */
export function projectAtlasActivityMapLotNumberV1(value: unknown): string {
  const text = String(value || ''), match = text.match(/(?:lote|lot)[^0-9]*(\d{1,4})/i) || text.match(/\b(\d{1,4})\b/);
  return match ? String(Number(match[1])) : '';
}

/** Group operational leads by lot while preserving the selected lead and first display label. */
export function projectAtlasActivityMapLeadGroupsV1(input: { liveLeads?: unknown[]; demoLeads?: unknown[]; selectedLead?: unknown }): AtlasActivityMapLeadGroupV1[] {
  const all = [...(Array.isArray(input.liveLeads) ? input.liveLeads : []), ...(Array.isArray(input.demoLeads) ? input.demoLeads : [])];
  const selectedIndex = Math.max(0, Math.min(all.length - 1, Number(input.selectedLead) || 0));
  const groups = new Map<string, AtlasActivityMapLeadGroupV1>();
  all.forEach((row, index) => {
    const lead = row && typeof row === 'object' ? row as Record<string, unknown> : {}, number = projectAtlasActivityMapLotNumberV1(lead.lot);
    if (!number) return;
    const fallback = `Lote ${number}`, prior = groups.get(number), label = String(lead.lot || fallback);
    if (prior) { prior.count++; prior.selected ||= index === selectedIndex; if (!prior.label || prior.label === fallback) prior.label = label; }
    else groups.set(number, { number, label, count: 1, selected: index === selectedIndex });
  });
  return [...groups.values()];
}

/** Keep the highest-priority activity status assigned to each physical map part. */
export function projectAtlasActivityMapAssignmentsV1(assignments: unknown): AtlasActivityMapProjectedAssignmentV1[] {
  const strongest = new Map<string, AtlasActivityMapProjectedAssignmentV1>();
  for (const item of Array.isArray(assignments) ? assignments : []) {
    if (!item || typeof item !== 'object') continue;
    const assignment = item as AtlasActivityMapAssignmentV1;
    const rawStatus = String(assignment.status || 'scheduled');
    const statusKey = (rawStatus in ACTIVITY_MAP_STATUSES_V1 ? rawStatus : 'scheduled') as AtlasActivityMapStatusKeyV1;
    const status = ACTIVITY_MAP_STATUSES_V1[statusKey];
    for (const rawId of Array.isArray(assignment.partIds) ? assignment.partIds : []) {
      const partId = String(rawId || ''); if (!partId) continue;
      const current = strongest.get(partId);
      if (!current || status.priority > current.status.priority) strongest.set(partId, { partId, assignment, statusKey, status });
    }
  }
  return [...strongest.values()];
}

/** Load persisted activity-map overlays through the request port supplied by the host. */
export async function loadAtlasActivityMapAssignmentsV1(input: {
  request: WorkerWorkbenchApiReadV1;
}): Promise<AtlasActivityMapAssignmentV1[]> {
  const payload = await input.request('/api/workbench/state?resource=activity-map');
  return Array.isArray(payload.assignments) ? payload.assignments as AtlasActivityMapAssignmentV1[] : [];
}

