/** Persist an activity location without dropping other worker stage fields. */
export function projectAtlasActivityLocationStateV1(input: {
  currentState: unknown;
  activityId: string;
  partIds: unknown[];
  zoneKey: string;
  zoneLabel: string;
  status: unknown;
  progress: number;
  source: string;
  note: string;
  updatedAt?: string;
}): Record<string, unknown> {
  const state = input.currentState && typeof input.currentState === 'object' ? input.currentState as Record<string, unknown> : {};
  const sourceLocations = state.activityLocations && typeof state.activityLocations === 'object' ? state.activityLocations as Record<string, unknown> : {};
  const status = String(input.status || 'scheduled');
  const statusKey = (status in ACTIVITY_MAP_STATUSES_V1 ? status : 'scheduled') as AtlasActivityMapStatusKeyV1;
  const activityLocations = {
    ...sourceLocations,
    [input.activityId]: {
      partIds: [...new Set(input.partIds.map(String))],
      zoneKey: input.zoneKey,
      zoneLabel: input.zoneLabel,
      status: statusKey,
      progress: Math.max(0, Math.min(100, Number(input.progress) || 0)),
      source: input.source,
      note: input.note.trim(),
      updatedAt: input.updatedAt || new Date().toISOString(),
    } satisfies AtlasActivityLocationSaveV1,
  };
  return {
    ...state,
    layout: state.layout && typeof state.layout === 'object' ? state.layout : {},
    links: Array.isArray(state.links) ? state.links : [],
    activityLocations,
  };
}

export interface AtlasActivityLocationRecordV1 {
  partIds: unknown[];
  zoneKey: string;
  status: string;
  source: string;
  note: string;
}

/** Read one saved map-location entry without leaking untyped storage into the view. */
export function projectAtlasActivityLocationRecordV1(stateValue: unknown, activityId: string): AtlasActivityLocationRecordV1 | null {
  if (!stateValue || typeof stateValue !== 'object' || Array.isArray(stateValue)) return null;
  const activityLocations = (stateValue as Record<string, unknown>).activityLocations;
  if (!activityLocations || typeof activityLocations !== 'object' || Array.isArray(activityLocations)) return null;
  const value = (activityLocations as Record<string, unknown>)[activityId];
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  return {
    partIds: Array.isArray(record.partIds) ? record.partIds : [],
    zoneKey: String(record.zoneKey || ''),
    status: String(record.status || ''),
    source: String(record.source || ''),
    note: String(record.note || ''),
  };
}

