/** Read the persisted activity-location catalog through the authenticated workbench port. */
export async function loadWorkerWorkbenchActivityLocationStateV1(input: {
  stageKey: string;
  request: WorkerWorkbenchApiReadV1;
}): Promise<Record<string, unknown>> {
  const payload = await input.request(`/api/workbench/state?stage=${encodeURIComponent(input.stageKey)}`);
  return payload.state && typeof payload.state === 'object' && !Array.isArray(payload.state)
    ? payload.state as Record<string, unknown>
    : {};
}

/** Merge a physical activity location into the latest stage snapshot, then persist it. */
export async function saveWorkerWorkbenchActivityLocationV1(input: {
  stageKey: string;
  command: AtlasWorkerActivityLocationCommandV1;
  request: WorkerWorkbenchApiReadV1;
}): Promise<Record<string, unknown>> {
  const currentState = await loadWorkerWorkbenchActivityLocationStateV1({ stageKey: input.stageKey, request: input.request });
  const nextState = projectAtlasActivityLocationStateV1({ currentState, ...input.command });
  await input.request(`/api/workbench/state?stage=${encodeURIComponent(input.stageKey)}`, {
    method: 'PUT',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(nextState),
  });
  return nextState;
}

