/** Validate georeference data and derive the canonical public satellite frame. */
export function projectPublicDwgSatelliteFrame(value: unknown, zoom: number): PublicDwgSatelliteFrame {
  const geo = mapRecord(value);
  if (!geo) throw new Error('Georreferência do mapa inválida.');
  const points = Array.isArray(geo.controlPoints) ? geo.controlPoints.map(mapRecord).filter((point): point is Record<string, unknown> => Boolean(point)) : [];
  const center = points.find(point => point.id === 'site-center') || points[0];
  const lat = Number(center?.lat), lng = Number(center?.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) throw new Error('Centro GPS ausente no DWG');
  const rawBounds = mapRecord(mapRecord(geo.drawingBounds)?.gps);
  const numbers = rawBounds && ['south', 'west', 'north', 'east'].map(key => Number(rawBounds[key]));
  const bounds = numbers && numbers.every(Number.isFinite)
    ? { south: numbers[0], west: numbers[1], north: numbers[2], east: numbers[3] }
    : null;
  return { geo, center: [lat, lng], zoom: Number.isFinite(zoom) ? zoom : 18, epsg: Number(geo.crs && mapRecord(geo.crs)?.epsg) || null, controlPointCount: points.filter(point => Number.isFinite(Number(point.lat)) && Number.isFinite(Number(point.lng))).length, bounds };
}

/** Load the georeference document and return the normalized camera/frame DTO. */
export async function loadPublicDwgSatelliteFrame(url: string, zoom: number, fetcher: (url: string, init?: RequestInit) => Promise<Response>): Promise<PublicDwgSatelliteFrame> {
  const response = await fetcher(url, { cache: 'no-store' });
  if (!response.ok) throw new Error(`DWG HTTP ${response.status}`);
  return projectPublicDwgSatelliteFrame(await response.json(), zoom);
}

/** Load and validate the five authoritative geometry/index assets for the public lot map. */
export async function loadPublicMapGeometryAssets(urls: PublicMapGeometryAssetUrls): Promise<PublicMapGeometryAssetBundle> {
  const read = async (url: string, optional: boolean): Promise<Record<string, unknown> | null> => {
    try {
      const response = await fetch(url, { cache: 'no-store' });
      if (!response.ok) {
        if (optional) return null;
        throw new Error(`HTTP ${response.status}`);
      }
      const value: unknown = await response.json();
      return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : optional ? null : null;
    } catch (error) {
      if (optional) return null;
      throw new Error(`Falha ao carregar geometria do mapa (${url}): ${error instanceof Error ? error.message : String(error)}`);
    }
  };
  const [trace, georeference, masterplanPolygons, lotLabels, greenMapping, roadTrace] = await Promise.all([
    read(urls.trace, false), read(urls.georeference, false), read(urls.masterplanPolygons, true), read(urls.lotLabels, true), read(urls.greenMapping, true),
    urls.roadTrace ? read(urls.roadTrace, true) : Promise.resolve(null),
  ]);
  if (!trace || !trace.lots || typeof trace.lots !== 'object' || Array.isArray(trace.lots)) throw new Error('Prancha PDF sem polígonos de lote.');
  if (!georeference) throw new Error('Georreferência do mapa inválida.');
  return { trace: trace as PublicMapGeometryAssetBundle['trace'], georeference, masterplanPolygons, lotLabels, greenMapping, roadTrace };
}

/** Join official PDF lot areas to reviewed green-polygon mappings by source ID. */
export function publicMapLotPdfAreas(
  geometryRows: unknown,
  links: PublicMapLotPdfAreaLink[],
): PublicMapLotPdfAreaIndex {
  const geometryByPolygonId = new Map<string, unknown[]>();
  if (Array.isArray(geometryRows)) {
    for (const row of geometryRows) {
      if (!Array.isArray(row) || row.length === 0 || row[0] == null) continue;
      geometryByPolygonId.set(String(row[0]), row);
    }
  }
  return new Map(links.map(({ lotId, greenPolygonId, officialAreaM2 }) => {
    const official = Number(officialAreaM2);
    const geometry = Number(geometryByPolygonId.get(String(greenPolygonId))?.[5]);
    const area = Number.isFinite(official) && official > 0 ? official : geometry;
    return [lotId, Number.isFinite(area) && area > 0 ? area : null];
  }));
}
