/** Project the complete static admin-georeference catalog and derived visual-recovery IDs. */
export function projectAdminMapGeoreferenceConfigV1(): AdminMapGeoreferenceConfigV1 {
  const source = structuredClone(mapProjectionCatalog);
  const first = Math.min(source.adminGeoreferenceScene.visualRecoveryLotNumberRange.first, source.adminGeoreferenceScene.visualRecoveryLotNumberRange.last);
  const last = Math.max(source.adminGeoreferenceScene.visualRecoveryLotNumberRange.first, source.adminGeoreferenceScene.visualRecoveryLotNumberRange.last);
  const visualRecoveryLotIds = [
    ...source.adminGeoreferenceScene.visualRecoveryAdditionalLotIds,
    ...Array.from({ length: last - first + 1 }, (_, index) => `Lote_${String(first + index).padStart(3, '0')}`),
  ];
  return Object.freeze({
    scene: Object.freeze(source.adminGeoreferenceScene),
    projection: Object.freeze({
      canonicalLotTraceToMasterplanUvHomography: source.canonicalLotTraceToMasterplanUvHomography,
      pdfLotTraceToSatelliteUvHomography: source.pdfLotTraceToSatelliteUvHomography,
      aerialUtmToUvHomography: source.aerialUtmToUvHomography,
      aerialResidualWarpV2: source.aerialResidualWarpV2,
      aerialGeoQuadUv: source.aerialGeoQuadUv,
      masterplanSatelliteFrame: source.masterplanSatelliteFrame,
      invalidMasterplanLotIds: source.invalidMasterplanLotIds,
      geometryRepairLotIds: source.geometryRepairLotIds,
      commonAreaSourceIds: source.commonAreaSourceIds,
      canonicalLotTraceOverlayAlignment: source.canonicalLotTraceOverlayAlignment,
      pdfLotTraceSatelliteAlignment: source.pdfLotTraceSatelliteAlignment,
      publicSatellite: source.publicSatellite,
      adminGeoreferenceScene: source.adminGeoreferenceScene,
    }),
    visualRecoveryLotIds,
  });
}

