export interface AtlasAdminPdfMasterplanFrameV1 extends AdminMapFrameV1 {
  width: number;
  height: number;
  siteWidth: number;
  siteDepth: number;
  siteCenterU: number;
  siteCenterV: number;
  pageWidth: number;
  pageDepth: number;
  offsetX: number;
  offsetZ: number;
  frame: string;
}

/** Project GLB world dimensions into the original PDF page and its site window. */
export function projectAtlasAdminPdfMasterplanPageFrameV1(
  sourceWidth: unknown,
  sourceDepth: unknown,
): AtlasAdminPdfMasterplanFrameV1 {
  const pdf = mapProjectionCatalog.adminGeoreferenceScene.pdfMasterplan;
  const site = pdf.siteFrame;
  const siteWidth = Math.max(0.01, site.right - site.left);
  const siteDepth = Math.max(0.01, site.bottom - site.top);
  const pageWidth = Math.max(0.1, Number(sourceWidth) || 1) / siteWidth;
  const pageDepth = Math.max(0.1, Number(sourceDepth) || 1) / siteDepth;
  const siteCenterU = (site.left + site.right) / 2;
  const siteCenterV = (site.top + site.bottom) / 2;
  return {
    ...site,
    width: pdf.pageSize.width,
    height: pdf.pageSize.height,
    siteWidth,
    siteDepth,
    siteCenterU,
    siteCenterV,
    pageWidth,
    pageDepth,
    offsetX: (0.5 - siteCenterU) * pageWidth,
    offsetZ: (siteCenterV - 0.5) * pageDepth,
    frame: 'full PDF page with DWG-aligned site window',
  };
}

/** Fit the original aerial reference to the same semantic site window as the GLB. */
export function projectAtlasAdminReferenceAerialFrameV1(
  sourceWidth: unknown,
  sourceDepth: unknown,
  imageSize: { width?: unknown; height?: unknown } = {},
  siteFrame: AdminMapFrameV1,
): AtlasAdminPdfMasterplanFrameV1 {
  const width = Math.max(1, Number(imageSize.width) || 1672);
  const height = Math.max(1, Number(imageSize.height) || 942);
  const siteWidth = Math.max(0.01, siteFrame.right - siteFrame.left);
  const siteDepth = Math.max(0.01, siteFrame.bottom - siteFrame.top);
  const siteCenterU = (siteFrame.left + siteFrame.right) / 2;
  const siteCenterV = (siteFrame.top + siteFrame.bottom) / 2;
  const pageWidth = Math.max(0.1, Number(sourceWidth) || 1) / siteWidth;
  const pageDepth = Math.max(0.1, Number(sourceDepth) || 1) / siteDepth;
  return {
    ...siteFrame,
    width,
    height,
    siteWidth,
    siteDepth,
    siteCenterU,
    siteCenterV,
    pageWidth,
    pageDepth,
    offsetX: (0.5 - siteCenterU) * pageWidth,
    offsetZ: (siteCenterV - 0.5) * pageDepth,
    frame: 'user supplied aerial reference · semantic GLB alignment',
  };
}

/** Normalize the PDF texture UV for one already-oriented GLB footprint point. */
export function projectAtlasAdminPdfTextureUvV1(
  orientedPoint: { x: unknown; z: unknown },
  sourceWidth: unknown,
  sourceDepth: unknown,
  frame: Pick<AtlasAdminPdfMasterplanFrameV1, 'siteCenterU' | 'siteCenterV' | 'siteWidth' | 'siteDepth'>,
): { u: number; v: number } {
  const pdf = mapProjectionCatalog.adminGeoreferenceScene.pdfMasterplan;
  const imageU = frame.siteCenterU + (Number(orientedPoint.x) / Math.max(0.01, Number(sourceWidth) || 1)) * frame.siteWidth;
  const imageV = frame.siteCenterV + (Number(orientedPoint.z) / Math.max(0.01, Number(sourceDepth) || 1)) * frame.siteDepth + pdf.textureShiftUp;
  return {
    u: Math.max(0, Math.min(1, imageU)),
    v: Math.max(0, Math.min(1, 1 - imageV)),
  };
}

/** Convert a GLB-local point into a pixel anchor on the full original page. */
export function projectAtlasAdminPdfElementImageAnchorV1(
  center: { x: unknown; z: unknown },
  sourceWidth: unknown,
  sourceDepth: unknown,
  frame: Pick<AtlasAdminPdfMasterplanFrameV1, 'siteCenterU' | 'siteCenterV' | 'siteWidth' | 'siteDepth' | 'width' | 'height'>,
): { u: number; v: number; x: number; y: number; coordinateSpace: string } {
  const u = frame.siteCenterU + (Number(center.x) / Math.max(0.01, Number(sourceWidth) || 1)) * frame.siteWidth;
  const v = frame.siteCenterV + (Number(center.z) / Math.max(0.01, Number(sourceDepth) || 1)) * frame.siteDepth;
  const normalizedU = Math.max(0, Math.min(1, u));
  const normalizedV = Math.max(0, Math.min(1, v));
  return {
    u: Number(normalizedU.toFixed(6)),
    v: Number(normalizedV.toFixed(6)),
    x: Number((normalizedU * frame.width).toFixed(2)),
    y: Number((normalizedV * frame.height).toFixed(2)),
    coordinateSpace: 'full PDF page · top-left origin',
  };
}

export type AtlasAdminPdfElementKindV1 = 'lot' | 'street' | 'tree' | 'structure' | 'leisure' | 'asset' | 'vehicle';

/** Resolve the PDF overlay role from the GLB semantic metadata and fallback hint. */
export function projectAtlasAdminPdfElementKindV1(
  input: { userData?: Record<string, unknown>; name?: unknown } | null | undefined,
  hint: unknown = 'asset',
): AtlasAdminPdfElementKindV1 {
  const data = input?.userData || {};
  const explicit = String(data.pdfSemanticKind || data.pdfElementKind || '').toLowerCase();
  const normalizedHint = String(hint || 'asset').toLowerCase();
  const valid = new Set<AtlasAdminPdfElementKindV1>(['lot', 'street', 'tree', 'structure', 'leisure', 'asset', 'vehicle']);
  if (valid.has(explicit as AtlasAdminPdfElementKindV1)) return explicit === 'leisure' ? 'structure' : explicit as AtlasAdminPdfElementKindV1;
  if (valid.has(normalizedHint as AtlasAdminPdfElementKindV1) && normalizedHint !== 'asset') return normalizedHint === 'leisure' ? 'structure' : normalizedHint as AtlasAdminPdfElementKindV1;
  const name = String(input?.name || '').toLowerCase();
  const role = String(data.belavistaRole || data.partKind || '').toLowerCase();
  if (role === 'lot' || role === 'lots' || /(^|[_\s-])(lote|quadra|gleba)([_\s-]|$)/.test(name)) return 'lot';
  if (role === 'street' || role === 'streets' || role === 'road' || role === 'curb' || role === 'curbs' || /(asfalto|rua|road|street|meio.?fio|guia|paviment|curb)/.test(name)) return 'street';
  if (role === 'landscape' || /(arvore|tree|tronco|copa|folhagem|outer.?east.?row|upper.?median.?row)/.test(name)) return 'tree';
  if (role === 'leisure' || /(area.?de.?lazer|court|gym|pavilhao|play|praca|banco.?praca|estrutura|building|edificio)/.test(name)) return 'structure';
  return 'asset';
}

/** Project the lot number encoded in a GLB node name to the displayed PDF ID. */
export function projectAtlasAdminPdfLotNumberV1(input: { userData?: Record<string, unknown>; name?: unknown } | null | undefined): string {
  const data = input?.userData || {};
  const name = String(data.partId || input?.name || '');
  const match = name.match(/(?:^|[_\s-])lote[_\s-]?0*(\d+)(?:$|[_\s-])/i) || name.match(/lote\D*(\d+)/i);
  return match ? String(Number(match[1])).padStart(3, '0') : '';
}

/** Resolve an existing PDF lot integration record by normalized number. */
export function projectAtlasAdminPdfLotIntegrationV1<T extends { number: string }>(number: unknown, records: readonly T[] | null | undefined): T | null {
  const token = String(number ?? '').match(/\d+/)?.[0];
  if (!token) return null;
  const normalized = String(Number(token)).padStart(3, '0');
  return records?.find(item => item.number === normalized) || null;
}

/** Load and validate the authoritative DWG→GLB alignment without dropping source fields. */
export async function loadAdminDwgGeoreferenceV1(
  url: string,
  fetcher: typeof fetch = globalThis.fetch.bind(globalThis),
): Promise<AdminDwgGeoreferenceDocument> {
  const response = await fetcher(url, { cache: 'no-store' });
  if (!response.ok) throw new Error(`DWG georeference indisponível (${response.status})`);
  const value: unknown = await response.json();
  const geo = value && typeof value === 'object' ? value as Record<string, unknown> : {};
  const alignment = geo.alignment && typeof geo.alignment === 'object'
    ? geo.alignment as Record<string, unknown>
    : {};
  const matrix = alignment.glbToDwgMatrix;
  const translation = alignment.translation;
  if (
    !Array.isArray(matrix) || matrix.length < 2 ||
    !Array.isArray(matrix[0]) || !Array.isArray(matrix[1]) ||
    !Array.isArray(translation) || translation.length < 2
  ) throw new Error('DWG georeference sem matriz GLB→UTM');
  return geo as AdminDwgGeoreferenceDocument;
}

export interface AtlasAdminStandaloneAerialAssetLoaderInputV1 {
  lotTraceUrl: string;
  roadTraceUrl: string;
  loadGeoreference(): Promise<AdminDwgGeoreferenceDocument>;
  fetcher?: typeof fetch;
}

/** Load the administrative 3D map's authoritative georeference and aerial traces. */
export async function loadAtlasAdminStandaloneAerialAssetsV1(
  input: AtlasAdminStandaloneAerialAssetLoaderInputV1,
): Promise<AtlasAdminStandaloneAerialAssetsV1> {
  const georeference = await input.loadGeoreference();
  const fetcher = input.fetcher || globalThis.fetch.bind(globalThis);
  const [traceResponse, roadTraceResponse] = await Promise.all([
    fetcher(input.lotTraceUrl),
    fetcher(input.roadTraceUrl),
  ]);
  const [trace, roadTrace] = await Promise.all([
    traceResponse.ok ? traceResponse.json() : Promise.resolve(null),
    roadTraceResponse.ok ? roadTraceResponse.json() : Promise.resolve(null),
  ]);
  return Object.freeze({ georeference, trace, roadTrace });
}

/** Keep the 298-lot and road-outline source requirements beside map service ownership. */
export function validateAtlasAdminStandaloneAerialAssetsV1(
  input: Pick<AtlasAdminStandaloneAerialAssetsV1, 'trace' | 'roadTrace'>,
): AtlasAdminStandaloneValidatedAerialAssetsV1 {
  const trace = mapRecord(input.trace);
  const roadTrace = mapRecord(input.roadTrace);
  if (trace?.lotCount !== 298 || !Array.isArray(trace.grid))
    throw new Error('Traçado aéreo dos 298 lotes indisponível ou inválido');
  if (!Array.isArray(roadTrace?.roads) || !roadTrace.roads.length)
    throw new Error('Contorno aéreo das ruas indisponível ou inválido');
  return {
    trace: trace as AtlasAdminStandaloneValidatedAerialAssetsV1['trace'],
    roadTrace: roadTrace as AtlasAdminStandaloneValidatedAerialAssetsV1['roadTrace'],
  };
}

/** Persist the same startup-phase record consumed by the administrative loading diagnostics. */
export function persistAtlasAdminStandaloneBootPhaseV5370(
  phase: string,
  extra: Record<string, unknown> = {},
  storage?: Pick<Storage, 'setItem'>,
  DateRef: DateConstructor = Date,
): AtlasAdminStandaloneBootPhaseV5370 {
  const payload = {
    version: '5.3.70' as const,
    phase,
    at: new DateRef().toISOString(),
    ...extra,
  } as AtlasAdminStandaloneBootPhaseV5370;
  try { storage?.setItem('belavista.3d.boot.last.v5370', JSON.stringify(payload)); }
  catch { }
  return payload;
}

/** Weighted polygon center used for stable lot labels; degenerate polygons use the valid-point mean. */
export function publicMapPolygonCentroid(polygon: unknown): { x: number; y: number } | null {
  if (!Array.isArray(polygon) || polygon.length < 3) return null;
  const points: unknown[] = polygon;
  let twiceArea = 0, x = 0, y = 0;
  points.forEach((point, index) => {
    const next = points[(index + 1) % points.length];
    const currentPoint = Array.isArray(point) ? point : [];
    const nextPoint = Array.isArray(next) ? next : [];
    const px = Number(currentPoint[0]), py = Number(currentPoint[1]);
    const nx = Number(nextPoint[0]), ny = Number(nextPoint[1]);
    if (![px, py, nx, ny].every(Number.isFinite)) return;
    const cross = px * ny - nx * py;
    twiceArea += cross; x += (px + nx) * cross; y += (py + ny) * cross;
  });
  if (Math.abs(twiceArea) < 1e-9) {
    const valid = points.flatMap(point => {
      const row = Array.isArray(point) ? point : [];
      const px = Number(row[0]), py = Number(row[1]);
      return Number.isFinite(px) && Number.isFinite(py) ? [{ x: px, y: py }] : [];
    });
    if (!valid.length) return null;
    return valid.reduce((total, point) => ({ x: total.x + point.x / valid.length, y: total.y + point.y / valid.length }), { x: 0, y: 0 });
  }
  return { x: x / (3 * twiceArea), y: y / (3 * twiceArea) };
}

/** Select the official PDF anchor before fallback trace/label/centroid positions. */
export function publicMapLotMarkerPlacement(input: PublicMapLotMarkerPlacementInput): PublicMapLotMarkerPlacement | null {
  if (!input.projected.length) return null;
  const centerPoint = publicMapPolygonCentroid(input.projected.map(point => [point.u, point.v]));
  if (!centerPoint) return null;
  const center = { u: centerPoint.x, v: centerPoint.y };
  if (!input.useMappedAnchors) return { ...center, center };
  const positioned = publicMapFramePosition(center.u, center.v, input.frame);
  return { ...positioned, center, relativeU: center.u, relativeV: center.v };
}

/** Resolve the complete, stable view model for one vector lot marker. */
export function publicMapLotMarkerRenderModel(input: PublicMapLotMarkerRenderInput): PublicMapLotMarkerRenderModel | null {
  if (!input.placement) return null;
  const identity = publicMapLotMarkerIdentity(input.lotId, input.greenMapping?.number);
  const candidate = mapRecord(input.manualPosition);
  const u = Number(candidate?.u), v = Number(candidate?.v);
  const manualPosition = Number.isFinite(u) && Number.isFinite(v) ? { u, v } : null;
  const relativeU = Number.isFinite(Number(input.placement.relativeU)) ? Number(input.placement.relativeU) : null;
  const relativeV = Number.isFinite(Number(input.placement.relativeV)) ? Number(input.placement.relativeV) : null;
  return {
    ...identity,
    source: input.greenMapping ? 'pdf-original-label' : input.usesCanonicalTraceMarkers ? 'canonical-trace' : 'pdf-green-mapping',
    center: input.placement.center,
    relativeU,
    relativeV,
    manualPosition,
    position: {
      u: manualPosition?.u ?? input.placement.u,
      v: manualPosition?.v ?? input.placement.v,
      zIndex: 1000 - input.lotIndex,
      manualPosition,
    },
  };
}

/** Resolve a PDF circle-only marker for lots without a corresponding polygon. */
export function publicMapFallbackLotMarkerModel(input: PublicMapFallbackLotMarkerInput): PublicMapFallbackLotMarkerModel {
  const identity = publicMapLotMarkerIdentity(input.lotId, input.pdfNumber);
  const source = input.usesGreenLotMapping ? 'pdf-circle-only' : 'canonical-trace-fallback';
  const candidate = mapRecord(input.manualPosition);
  const u = Number(candidate?.u), v = Number(candidate?.v);
  const manualPosition = Number.isFinite(u) && Number.isFinite(v) ? { u, v } : null;
  const projected = publicMapFramePosition(input.relativePosition.u, input.relativePosition.v, input.frame);
  return {
    ...identity,
    title: input.usesGreenLotMapping ? `${identity.label} · posição conferida no PDF` : `${identity.label} · contorno recuperado da geometria oficial`,
    source,
    selectionSource: source,
    relativePosition: input.relativePosition,
    position: {
      u: manualPosition?.u ?? projected.u,
      v: manualPosition?.v ?? projected.v,
      zIndex: 720 - input.fallbackIndex,
      manualPosition,
    },
  };
}

/** Project all PDF-backed map markers in drawing order, including circle-only PDF anchors. */
export function projectPublicSatelliteLotMarkerBatch(input: PublicMapSatelliteLotMarkerBatchInput): PublicMapSatelliteLotMarkerBatch {
  if (!input.renderDomMarkers) return Object.freeze({ lotMarkers: [], fallbackMarkers: [] });
  const useMappedAnchors = Boolean(input.hasMasterplanOverlay || input.hasOfficialPdfLabels);
  const lotMarkers = input.projectedLots.flatMap((lot, lotIndex): PublicMapSatelliteLotMarkerModel[] => {
    const placement = publicMapLotMarkerPlacement({
      projected: lot.projected,
      greenMapping: lot.greenMapping,
      canonicalMarker: input.canonicalTraceMarkerByLot.get(lot.lotId) || null,
      officialMarker: input.officialMarkerByLot.get(lot.lotId) || null,
      usesNativeMasterplanPolygons: input.usesNativeMasterplanPolygons,
      useMappedAnchors,
      projectedBounds: input.projectedBounds,
      frame: input.frame,
    });
    const marker = publicMapLotMarkerRenderModel({
      lotId: lot.lotId,
      lotIndex,
      placement,
      greenMapping: lot.greenMapping,
      usesCanonicalTraceMarkers: input.usesCanonicalTraceMarkers,
      manualPosition: input.isPublicLeadsMap ? null : input.manualOverrides?.[lot.lotId],
    });
    if (!marker) return [];
    const relativePosition = marker.relativeU !== null && marker.relativeV !== null
      ? { u: marker.relativeU, v: marker.relativeV }
      : null;
    return [{
      ...marker,
      lotId: lot.lotId,
      title: marker.label,
      selectionSource: 'pdf-trace-satellite',
      relativePosition,
    }];
  });
  const renderedLots = new Set(input.projectedLots.map(lot => lot.lotId));
  const fallbackSource = input.usesGreenLotMapping
    ? [...input.greenMappingByLot.entries()]
    : [...input.canonicalTraceMarkerByLot.entries()];
  const fallbackMarkers = input.usesGreenLotMapping || input.usesCanonicalTraceMarkers
    ? fallbackSource
      .filter(([lotId]) => !renderedLots.has(lotId) && input.officialMarkerByLot.has(lotId))
      .sort(([left], [right]) => left.localeCompare(right, 'pt-BR', { numeric: true }))
      .flatMap(([lotId, relativePosition], fallbackIndex) => [{
        ...publicMapFallbackLotMarkerModel({
          lotId,
          relativePosition,
          pdfNumber: input.usesGreenLotMapping ? input.greenMappingByLot.get(lotId)?.number : undefined,
          frame: input.frame,
          fallbackIndex,
          usesGreenLotMapping: input.usesGreenLotMapping,
          manualPosition: input.isPublicLeadsMap ? null : input.manualOverrides?.[lotId],
        }),
        lotId,
      }])
    : [];
  return Object.freeze({ lotMarkers, fallbackMarkers });
}

/** Apply the persisted masterplan frame transform to a normalized map anchor. */
export function publicMapFrameFromOverrides(base: PublicMapFrame, rawOverride: unknown): PublicMapFrame {
  let candidate: unknown = rawOverride;
  if (typeof rawOverride === 'string') {
    try { candidate = JSON.parse(rawOverride) as unknown; }
    catch { candidate = null; }
  }
  const override = mapRecord(candidate);
  const number = (key: keyof PublicMapFrame): number => {
    const value = Number(override?.[key]);
    return Number.isFinite(value) ? value : base[key];
  };
  return { left: number('left'), top: number('top'), width: number('width'), height: number('height'), rotation: number('rotation') };
}

/** Validate frame changes from the admin calibration controls before persistence. */
export function publicMapFramePatch(current: PublicMapFrame, patch: Record<string, unknown>): PublicMapFrame {
  const next = { ...current };
  for (const key of ['left', 'top', 'width', 'height', 'rotation'] as const) {
    if (!(key in patch)) continue;
    const value = Number(patch[key]);
    if (!Number.isFinite(value)) throw new TypeError(`Frame '${key}' precisa ser um número finito.`);
    if ((key === 'width' || key === 'height') && value <= 0) throw new RangeError(`Frame '${key}' precisa ser maior que zero.`);
    next[key] = value;
  }
  return next;
}

/** Read stored admin marker overrides without allowing malformed entries into the renderer. */
export function publicMapMarkerOverrides(value: unknown): PublicMapMarkerOverrides {
  let candidate = value;
  if (typeof value === 'string') {
    try { candidate = JSON.parse(value) as unknown; }
    catch { candidate = null; }
  }
  const source = mapRecord(candidate);
  const overrides: PublicMapMarkerOverrides = {};
  for (const [lotId, candidate] of Object.entries(source || {})) {
    const point = mapRecord(candidate);
    const u = Number(point?.u), v = Number(point?.v);
    if (Number.isFinite(u) && Number.isFinite(v)) overrides[lotId] = { u, v };
  }
  return overrides;
}

