/** Resolve an admin placement number to the exact active marker ID and UV. */
export function publicMapManualLotPlacement(input: PublicMapManualLotPlacementInput): PublicMapManualLotPlacementResolution {
  const digits = String(input.rawLotNumber ?? '').match(/\d+/)?.[0] || '';
  const lotNumber = digits.padStart(3, '0');
  const lotId = lotNumber ? `Lote_${lotNumber}` : '';
  const u = Number(input.u), v = Number(input.v);
  const found = Boolean(lotId && input.availableLotIds.includes(lotId) && Number.isFinite(u) && Number.isFinite(v));
  return { lotNumber, lotId, u, v, found };
}

export interface PublicMapTextureQualityProjectionInputV1 {
  devicePixelRatio: unknown;
  maximumAnisotropy: unknown;
}

export interface PublicMapTextureQualityProjectionV1 {
  pixelRatio: number;
  anisotropy: number;
}

/** Keep the public renderer crisp across displays without exceeding its old GPU limits. */
export function projectPublicMapTextureQualityV1(
  input: PublicMapTextureQualityProjectionInputV1,
): PublicMapTextureQualityProjectionV1 {
  const devicePixelRatio = Number(input.devicePixelRatio) || 1;
  const maximumAnisotropy = Number(input.maximumAnisotropy) || 1;
  return {
    pixelRatio: Math.min(2, Math.max(1.65, devicePixelRatio)),
    anisotropy: Math.max(1, Math.min(12, maximumAnisotropy)),
  };
}

/** Browser persistence port for admin calibration; all persisted shapes are normalized here. */
export const publicMapCalibrationStorage = {
  readFrame(storageKey: string, base: PublicMapFrame): PublicMapFrame {
    try { return publicMapFrameFromOverrides(base, globalThis.localStorage.getItem(storageKey)); }
    catch { return { ...base }; }
  },
  saveFrame(storageKey: string, frame: PublicMapFrame): boolean {
    try { globalThis.localStorage.setItem(storageKey, JSON.stringify(frame)); return true; }
    catch { return false; }
  },
  removeFrame(storageKey: string): boolean {
    try { globalThis.localStorage.removeItem(storageKey); return true; }
    catch { return false; }
  },
  readMarkers(storageKey: string): PublicMapMarkerOverrides {
    try { return publicMapMarkerOverrides(globalThis.localStorage.getItem(storageKey)); }
    catch { return {}; }
  },
  saveMarkers(storageKey: string, markers: unknown): PublicMapMarkerOverrides {
    const overrides = publicMapMarkerOverrides(markers);
    try { globalThis.localStorage.setItem(storageKey, JSON.stringify(overrides)); }
    catch { /* Browser storage may be disabled; the live map still updates. */ }
    return overrides;
  },
  saveMarker(storageKey: string, lotId: string, point: PublicMapProjectionPoint): PublicMapMarkerOverrides {
    const overrides = this.readMarkers(storageKey);
    const u = Number(point.u), v = Number(point.v);
    if (lotId && Number.isFinite(u) && Number.isFinite(v)) overrides[lotId] = { u, v };
    return this.saveMarkers(storageKey, overrides);
  },
  removeMarkers(storageKey: string): boolean {
    try { globalThis.localStorage.removeItem(storageKey); return true; }
    catch { return false; }
  },
};

export function readPublicMapCalibrationFrame(input: {
  storageKey: string;
  baseFrame: PublicMapFrame;
}): PublicMapFrame {
  return publicMapCalibrationStorage.readFrame(input.storageKey, input.baseFrame);
}

export function resetPublicMapCalibrationFrame(storageKey: string): boolean {
  return publicMapCalibrationStorage.removeFrame(storageKey);
}

export function readPublicMapCalibrationMarkers(storageKey: string): PublicMapMarkerOverrides {
  return publicMapCalibrationStorage.readMarkers(storageKey);
}

export function resetPublicMapCalibrationMarkers(storageKey: string): boolean {
  return publicMapCalibrationStorage.removeMarkers(storageKey);
}

interface AtlasMapDragCalibrationSceneV1 extends HTMLElement {
  adminMasterplanDevToolsV1?: { get?: () => { defaults?: PublicMapFrame } | null };
}

interface AtlasMapDragCalibrationToolbarV1 extends HTMLElement {
  installPointerController?: (scene: HTMLElement, defaults: PublicMapFrame) => boolean;
}

/** Discover the calibration surface and observe late map mounting; gestures stay in the typed toolbar component. */
export function installAtlasMapDragCalibrationProgramV1(input: {
  documentRef?: Document;
  MutationObserverCtor?: typeof MutationObserver;
} = {}): boolean {
  const documentRef = input.documentRef || globalThis.document;
  if (!documentRef) return false;
  const install = (): boolean => {
    const scene = documentRef.querySelector<AtlasMapDragCalibrationSceneV1>('map-scene[data-admin-masterplan-overlay]');
    const toggle = documentRef.querySelector<HTMLElement>('[data-map-marker-adjust-toggle]');
    if (!scene || !toggle) return false;
    if (toggle.dataset.dragCalibrationBound === 'true') return true;

    const toolbar = toggle.closest<AtlasMapDragCalibrationToolbarV1>('atlas-map-adjustment-toolbar');
    const defaults = scene.adminMasterplanDevToolsV1?.get?.()?.defaults
      || { left: 0, top: 0, width: 0.25, height: 0.3, rotation: 0 };
    const installed = toolbar?.installPointerController?.(scene, defaults) === true;
    if (installed && scene.dataset.adminMapCalibrationTsOwner === 'true') {
      toggle.dataset.dragCalibrationBound = 'true';
      return true;
    }

    return false;
  };

  if (!install()) {
    const MutationObserverCtor = input.MutationObserverCtor || globalThis.MutationObserver;
    if (MutationObserverCtor) new MutationObserverCtor(() => install()).observe(documentRef.documentElement, { childList: true, subtree: true });
    else return false;
  }
  return true;
}

/** Persist the latest adjusted masterplan frame through the browser storage port. */
export function commitPublicMapCalibrationFrame(input: PublicMapCalibrationFrameCommitInput): boolean {
  return publicMapCalibrationStorage.saveFrame(input.storageKey, input.frame);
}

/** Merge one adjusted marker position without replacing other lot overrides. */
export function commitPublicMapCalibrationMarker(input: PublicMapCalibrationMarkerCommitInput): PublicMapMarkerOverrides {
  return publicMapCalibrationStorage.saveMarker(input.storageKey, input.lotId, input.point);
}

/** Apply and persist one manually placed marker while keeping DOM updates injectable. */
export function commitPublicMapManualLotPlacement(input: PublicMapManualLotPlacementCommandInput): PublicMapManualLotPlacementCommandResult {
  const resolution = publicMapManualLotPlacement(input);
  if (!resolution.found || !input.applyPosition(resolution)) return { ...resolution, committed: false };
  publicMapCalibrationStorage.saveMarker(input.storageKey, resolution.lotId, { u: resolution.u, v: resolution.v });
  return { ...resolution, committed: true };
}

/** Normalize pointer coordinates from admin marker dragging to the overlay's unit frame. */
export function publicMapDragPosition(
  clientX: number,
  clientY: number,
  rect: { left: number; top: number; width: number; height: number },
): PublicMapProjectionPoint | null {
  if (!(rect.width > 0) || !(rect.height > 0)) return null;
  const u = Math.max(0, Math.min(1, (Number(clientX) - rect.left) / rect.width));
  const v = Math.max(0, Math.min(1, (Number(clientY) - rect.top) / rect.height));
  return Number.isFinite(u) && Number.isFinite(v) ? { u, v } : null;
}

export interface PublicMapCalibrationFrameDrag {
  initialFrame: PublicMapFrame;
  deltaX: number;
  deltaY: number;
  boundsWidth: number;
  boundsHeight: number;
  resizeSide?: 'n' | 'e' | 's' | 'w' | '';
  rotating?: boolean;
}

/** Calculate the admin frame after pan, rotation or edge-resize pointer movement. */
export function publicMapCalibrationFrameAfterDrag(input: PublicMapCalibrationFrameDrag): PublicMapFrame | null {
  const { initialFrame: frame, deltaX: dx, deltaY: dy, boundsWidth, boundsHeight } = input;
  if (!(boundsWidth > 0) || !(boundsHeight > 0)) return null;
  const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(max, value));
  const normalizeAngle = (value: number) => ((value + 180) % 360 + 360) % 360 - 180;
  const resizeSide = input.resizeSide || '';
  if (resizeSide) {
    const angle = (frame.rotation * Math.PI) / 180;
    const localDx = dx * Math.cos(angle) + dy * Math.sin(angle);
    const localDy = -dx * Math.sin(angle) + dy * Math.cos(angle);
    const horizontal = resizeSide === 'e' || resizeSide === 'w';
    const vertical = resizeSide === 'n' || resizeSide === 's';
    const fromLeft = resizeSide === 'w';
    const fromTop = resizeSide === 'n';
    const initialWidth = frame.width || 0.25;
    const initialHeight = frame.height || 0.3;
    const width = horizontal ? clamp(initialWidth + (fromLeft ? -localDx : localDx) / boundsWidth, 0.04, 1.6) : initialWidth;
    const height = vertical ? clamp(initialHeight + (fromTop ? -localDy : localDy) / boundsHeight, 0.04, 1.6) : initialHeight;
    const shiftX = horizontal ? (fromLeft ? -1 : 1) * (width - initialWidth) * boundsWidth / 2 : 0;
    const shiftY = vertical ? (fromTop ? -1 : 1) * (height - initialHeight) * boundsHeight / 2 : 0;
    return {
      ...frame,
      left: clamp(frame.left + (initialWidth - width) / 2 + (shiftX * Math.cos(angle) - shiftY * Math.sin(angle)) / boundsWidth, -1, 1),
      top: clamp(frame.top + (initialHeight - height) / 2 + (shiftX * Math.sin(angle) + shiftY * Math.cos(angle)) / boundsHeight, -1, 1),
      width,
      height,
    };
  }
  if (input.rotating) return { ...frame, rotation: normalizeAngle(frame.rotation + (dx / boundsWidth) * 180) };
  return {
    ...frame,
    left: clamp(frame.left + dx / boundsWidth, -1, 1),
    top: clamp(frame.top + dy / boundsHeight, -1, 1),
  };
}

export function publicMapFramePosition(relativeU: number, relativeV: number, frame: PublicMapFrame): PublicMapProjectionPoint {
  const angle = (frame.rotation * Math.PI) / 180;
  const localU = Number(relativeU) - 0.5, localV = Number(relativeV) - 0.5;
  const cos = Math.cos(angle), sin = Math.sin(angle);
  return {
    u: frame.left + (0.5 + localU * cos - localV * sin) * frame.width,
    v: frame.top + (0.5 + localU * sin + localV * cos) * frame.height,
  };
}

/** Serialize projected polygon points for the SVG adapter. */
export function publicMapProjectedSvgPath(points: PublicMapProjectionPoint[]): string {
  return `${points.map((point, index) => `${index ? 'L' : 'M'}${(point.u * 1000).toFixed(2)} ${(point.v * 1000).toFixed(2)}`).join(' ')} Z`;
}

/** Keep lot hit-area UV data aligned with the native or normalized masterplan frame. */
export function publicMapRelativeLotPolygon(
  points: PublicMapProjectionPoint[],
  usesNativeMasterplanPolygons: boolean,
  bounds: PublicMapProjectedBounds,
): PublicMapProjectionPoint[] {
  if (usesNativeMasterplanPolygons) return points;
  const width = bounds.maxU - bounds.minU;
  const height = bounds.maxV - bounds.minV;
  return points.map(point => ({ u: (point.u - bounds.minU) / width, v: (point.v - bounds.minV) / height }));
}

/** Position a projected common-area context using its polygon's vertex mean. */
export function publicMapPolygonMean(points: PublicMapProjectionPoint[]): PublicMapProjectionPoint {
  if (!points.length) return { u: 0.5, v: 0.5 };
  return points.reduce((total, point) => ({ u: total.u + point.u / points.length, v: total.v + point.v / points.length }), { u: 0, v: 0 });
}

/** Resolve selected common-area geometry into its panel anchor and UI feedback. */
export function publicMapCommonAreaSelection(input: {
  sourceId: string;
  label: string;
  projected: PublicMapProjectionPoint[];
  frame: PublicMapFrame;
}): { sourceId: string; label: string; center: PublicMapProjectionPoint; position: PublicMapProjectionPoint; dataset: Record<string, string>; feedback: string } {
  const center = publicMapPolygonMean(input.projected);
  const label = String(input.label || 'Área compartilhada').trim();
  const sourceId = String(input.sourceId || '').trim();
  return {
    sourceId,
    label,
    center,
    position: publicMapFramePosition(center.u, center.v, input.frame),
    dataset: { selectedMapArea: label, selectedMapAreaSource: sourceId },
    feedback: `${label} selecionada no mapa`,
  };
}

