/** Project the shared lot-selection DOM state and accessible event payload. */
export function publicMapOverlayLotSelection(input: PublicMapOverlayLotSelectionInput): {
  dataset: Record<string, string>;
  eventDetail: { lotId: string; label: string; source: string };
  feedback: string;
} {
  const lotId = String(input.lotId || '').trim();
  const label = String(input.label || lotId || 'Lote').trim();
  const source = String(input.source || 'pdf-trace-satellite').trim();
  return {
    dataset: { selectedLot: lotId, selectedLotSource: source, selectedLotCount: '1', selectedLots: lotId },
    eventDetail: { lotId, label, source },
    feedback: `${label} selecionado no mapa`,
  };
}

interface PublicMapWorkerAssistantPort {
  openLotStatusContext?: (label: string) => boolean | Promise<boolean>;
  openMapAreaContext?: (label: string) => boolean | Promise<boolean>;
}

interface PublicMapAssistantChatPort {
  prepareMapAreaPrompt?: (label: string) => boolean | Promise<boolean>;
}

export interface PublicMapAssistantContextActionsInput {
  host?: (typeof globalThis & { belavistaWorkerAssistant?: PublicMapWorkerAssistantPort }) | null;
  documentRef?: { querySelector?: (selector: string) => PublicMapAssistantChatPort | null } | null;
  commonAreaLabel?: string;
}

/** Bridge map selection directly into the already-mounted TypeScript chat. */
export function createPublicMapAssistantContextActions(input: PublicMapAssistantContextActionsInput = {}): {
  prepareAssistantLotStatusPromptV1: (lotLabel: string) => Promise<boolean>;
  prepareAssistantMapAreaPromptV1: (areaLabel: string) => Promise<boolean>;
} {
  if (!input.host || typeof input.host !== 'object')
    throw new TypeError('Map assistant actions require the application host.');
  const host = input.host;
  const prepareAssistantLotStatusPrompt = async (lotLabel: string): Promise<boolean> => {
    return host.belavistaWorkerAssistant?.openLotStatusContext?.(lotLabel) || false;
  };
  const prepareAssistantMapAreaPrompt = async (areaLabel: string): Promise<boolean> => {
    const label = String(areaLabel || input.commonAreaLabel).trim();
    return host.belavistaWorkerAssistant?.openMapAreaContext?.(label)
      || input.documentRef?.querySelector?.('ai-chat')?.prepareMapAreaPrompt?.(label)
      || false;
  };
  return Object.freeze({
    prepareAssistantLotStatusPromptV1: prepareAssistantLotStatusPrompt,
    prepareAssistantMapAreaPromptV1: prepareAssistantMapAreaPrompt,
  });
}

/** Resolve the canonical source priority and screen-space position for a selected lot widget. */
export function publicMapLotSelectionWidgetPosition(input: {
  greenMapping?: PublicMapProjectionPoint | null;
  officialPdfMarker?: PublicMapProjectionPoint | null;
  projectedPolygon?: PublicMapProjectionPoint | null;
  frame: PublicMapFrame;
}): { position: PublicMapProjectionPoint; source: 'green-mapping' | 'official-pdf' | 'projected-polygon' | 'frame-center' } {
  const anchor = input.greenMapping || input.officialPdfMarker || input.projectedPolygon;
  const source = input.greenMapping ? 'green-mapping' : input.officialPdfMarker ? 'official-pdf' : input.projectedPolygon ? 'projected-polygon' : 'frame-center';
  const point = anchor || { u: 0.5, v: 0.5 };
  return { position: publicMapFramePosition(point.u, point.v, input.frame), source };
}

