export interface AtlasMapLotSelectionCommandInput {
  partId?: unknown;
  partLabel?: unknown;
  partKind?: unknown;
  sourceName?: unknown;
  selectedLotIds?: Iterable<string>;
}
export interface AtlasMapLotSelectionCommand {
  operation: 'select' | 'clear';
  partId: string;
  label: string;
  selectedLotIds: string[];
  selectedCount: number;
  lastAction: string;
}

/** Apply the multi-lot selection policy for the administrative 3D map. */
export function createAtlasMapLotSelectionCommand(input: AtlasMapLotSelectionCommandInput): AtlasMapLotSelectionCommand | null {
  if (String(input.partKind || '') !== 'lots') return null;
  const partId = String(input.partId || input.sourceName || '').trim();
  if (!partId) return null;
  const label = String(input.partLabel || input.sourceName || 'Lote').trim();
  const selectedLotIds = new Set(input.selectedLotIds || []);
  const operation = selectedLotIds.has(partId) ? 'clear' : 'select';
  if (operation === 'clear') selectedLotIds.delete(partId);
  else selectedLotIds.add(partId);
  const nextIds = [...selectedLotIds];
  return Object.freeze({
    operation,
    partId,
    label,
    selectedLotIds: nextIds,
    selectedCount: nextIds.length,
    lastAction: nextIds.length ? `Selecionou ${nextIds.length} lote(s) para reserva` : 'Limpou seleção de lotes',
  });
}

export interface AtlasMapReservation {
  id: string;
  lotes: string[];
  interessado: string;
  objetivo: string;
  prazo: string;
  observacoes: string;
  createdAt: string;
}
export interface AtlasMapReservationCommandInput {
  lotLabels: string[];
  interested?: unknown;
  objective?: unknown;
  term?: unknown;
  notes?: unknown;
  timestamp?: number;
}
export interface AtlasMapReservationCommand {
  reservation: AtlasMapReservation;
  lastAction: string;
  feedback: string;
}

/** Project the existing local reservation intent and its success copy. */
export function createAtlasMapReservationCommand(input: AtlasMapReservationCommandInput): AtlasMapReservationCommand {
  const options = projectAtlasMapReservationOptions();
  const timestamp = Number.isFinite(input.timestamp) ? Number(input.timestamp) : Date.now();
  const labels = input.lotLabels.map(label => String(label));
  return Object.freeze({
    reservation: Object.freeze({
      id: `RES-${timestamp}`,
      lotes: labels,
      interessado: String(input.interested || 'Interessado não informado'),
      objetivo: String(input.objective || options.defaultObjective),
      prazo: String(input.term || options.defaultTerm),
      observacoes: String(input.notes || ''),
      createdAt: new Date(timestamp).toISOString(),
    }),
    lastAction: `Abriu reserva para ${labels.join(', ')}`,
    feedback: `Janela de reserva aberta para ${labels.length} lote(s).`,
  });
}

export interface AtlasMapProgressArea {
  partId: string;
  label: string;
  kind: string;
}
export interface AtlasMapSelectionOptions {
  progressNatureOptions: string[];
}
const atlasMapSelectionOptions = atlasMapSelectionOptionsData as AtlasMapSelectionOptions;

/** Read the static progress choices used by map forms and the compatibility adapter. */
export function projectAtlasMapSelectionOptions(): AtlasMapSelectionOptions {
  return Object.freeze({ progressNatureOptions: [...atlasMapSelectionOptions.progressNatureOptions] });
}

export interface AtlasMapPartInput {
  partId?: unknown;
  partLabel?: unknown;
  partKind?: unknown;
  name?: unknown;
  label?: unknown;
  kind?: unknown;
  userData?: Record<string, unknown>;
}

/** Normalize a Three.js part or persisted selection into a stable area record. */
export function projectAtlasMapProgressArea(value: AtlasMapPartInput | null | undefined): AtlasMapProgressArea | null {
  if (!value) return null;
  const data = value.userData || {};
  const partId = String(data.partId || value.partId || value.name || '').trim();
  if (!partId) return null;
  return Object.freeze({
    partId,
    label: String(data.partLabel || value.partLabel || value.name || value.label || 'Área do empreendimento'),
    kind: String(data.partKind || value.partKind || value.kind || 'other'),
  });
}

export interface AtlasMapProgressSelectionCommand {
  records: AtlasMapProgressArea[];
  lastAction: string;
}

/** Apply append/replace semantics for areas selected for progress tracking. */
export function createAtlasMapProgressSelectionCommand(input: { current?: unknown; parts?: AtlasMapPartInput[]; append?: boolean }): AtlasMapProgressSelectionCommand {
  const next = new Map<string, AtlasMapProgressArea>();
  if (input.append && Array.isArray(input.current)) {
    input.current.forEach(value => {
      const record = projectAtlasMapProgressArea(value as AtlasMapPartInput);
      if (record) next.set(record.partId, record);
    });
  }
  (Array.isArray(input.parts) ? input.parts : []).forEach(value => {
    const record = projectAtlasMapProgressArea(value);
    if (record) next.set(record.partId, record);
  });
  const records = [...next.values()];
  return Object.freeze({
    records,
    lastAction: records.length ? `Selecionou ${records.length} área(s) para leitura de progresso` : 'Limpou áreas de progresso',
  });
}

export interface AtlasMapStatusSelection {
  parts: AtlasMapProgressArea[];
  labels: string[];
  kinds: string[];
  lots: number;
  streets: number;
}

/** Summarize a spatial status selection before the component renders its panel. */
export function projectAtlasMapStatusSelection(parts: AtlasMapPartInput[]): AtlasMapStatusSelection {
  const unique = new Map<string, AtlasMapProgressArea>();
  (Array.isArray(parts) ? parts : []).forEach(value => {
    const record = projectAtlasMapProgressArea(value);
    if (record) unique.set(record.partId, record);
  });
  const selected = [...unique.values()];
  return Object.freeze({
    parts: selected,
    labels: selected.map(item => item.label),
    kinds: [...new Set(selected.map(item => item.kind || 'estrutura'))],
    lots: selected.filter(item => item.kind === 'lots').length,
    streets: selected.filter(item => item.kind === 'streets').length,
  });
}

export interface AtlasMapProgressRecordInput {
  nature: string;
  activity: string;
  stage: string;
  responsible: string;
  date: string;
  details: string;
  evidenceUri: string;
  progress: number;
  areas: AtlasMapProgressArea[];
  timestamp?: number;
}
export interface AtlasMapProgressRecordCommand {
  record: OperationalRecord;
  lastAction: string;
  feedback: string;
}

/** Build the existing map-created operational record without mutating application state. */
export function createAtlasMapProgressRecordCommand(input: AtlasMapProgressRecordInput): AtlasMapProgressRecordCommand {
  const timestamp = Number.isFinite(input.timestamp) ? Number(input.timestamp) : Date.now();
  const date = new Date(timestamp);
  const areas = input.areas.map(area => ({ label: area.label, kind: area.kind, partId: area.partId }));
  const record: OperationalRecord = {
    id: `REG-${timestamp}`,
    obra: 'Aliança Park',
    atividade: input.activity,
    etapa: input.stage,
    categoria: input.nature,
    responsavel: input.responsible,
    data: input.date || date.toISOString().slice(0, 10),
    hora: date.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
    detalhes: input.details,
    evidenceUri: input.evidenceUri,
    status: 'Pendente',
    progresso: Math.max(0, Math.min(100, Number(input.progress) || 0)),
    mapArea: JSON.stringify(areas),
    createdAt: date.toISOString(),
  };
  return Object.freeze({
    record,
    lastAction: `Registrou ${input.nature} em ${areas.length || 'área geral'} área(s)`,
    feedback: `Progresso de ${input.nature} registrado no mapa.`,
  });
}

export interface AtlasMapSelectionCommandsV1 {
  selectProgressAreas(parts: AtlasMapPartInput[], append: boolean): AtlasMapProgressSelectionCommand;
  toggleProgressArea(part: AtlasMapPartInput): AtlasMapProgressSelectionCommand | null;
  clearProgressAreas(): void;
  projectStatusSelection(parts: AtlasMapPartInput[]): AtlasMapStatusSelection;
  recordStatusQuery(count: number): void;
  clearMapFilters(): void;
  submitProgressRecord(input: AtlasMapProgressRecordInput): AtlasMapProgressRecordCommand;
}

/** Own persistent selection state and map-created progress records for the scene. */
export function createAtlasMapSelectionCommandsV1(appStore: {
  get(): Record<string, unknown>;
  set(patch: Record<string, unknown>): unknown;
}): AtlasMapSelectionCommandsV1 {
  const selectProgressAreas = (parts: AtlasMapPartInput[], append: boolean): AtlasMapProgressSelectionCommand => {
    const command = createAtlasMapProgressSelectionCommand({ current: appStore.get().mapProgressSelection, parts, append });
    appStore.set({ mapProgressSelection: command.records, lastAction: command.lastAction });
    return command;
  };
  return Object.freeze({
    selectProgressAreas,
    toggleProgressArea(part: AtlasMapPartInput): AtlasMapProgressSelectionCommand | null {
      const record = projectAtlasMapProgressArea(part);
      if (!record) return null;
      const current = appStore.get().mapProgressSelection;
      const selected = Array.isArray(current) ? current : [];
      const next = selected.some(value => String((value as AtlasMapProgressArea)?.partId || '') === record.partId)
        ? selected.filter(value => String((value as AtlasMapProgressArea)?.partId || '') !== record.partId)
        : [...selected, record];
      return selectProgressAreas(next as AtlasMapPartInput[], false);
    },
    clearProgressAreas(): void {
      appStore.set({ mapProgressSelection: [], lastAction: 'Limpou a seleção de áreas de progresso' });
    },
    projectStatusSelection(parts: AtlasMapPartInput[]): AtlasMapStatusSelection {
      return projectAtlasMapStatusSelection(parts);
    },
    recordStatusQuery(count: number): void {
      appStore.set({ lastAction: count ? `Consultou status de ${count} parte(s) do mapa` : 'Limpou consulta do mapa' });
    },
    clearMapFilters(): void {
      appStore.set({ mapFilters: [], mapFilter: null, mapFilterWidget: null, lastAction: 'Limpou seleção e filtros do mapa' });
    },
    submitProgressRecord(input: AtlasMapProgressRecordInput): AtlasMapProgressRecordCommand {
      const command = createAtlasMapProgressRecordCommand(input);
      const state = appStore.get();
      appStore.set({
        records: [command.record, ...(Array.isArray(state.records) ? state.records : [])],
        lastAction: command.lastAction,
      });
      return command;
    },
  });
}

export interface AtlasMapRecordArea {
  label: string;
  kind: string;
  partId?: string;
  labels?: string[];
  partIds?: Array<string | undefined>;
  overlayKey: string;
  nature: string;
  activity: string;
  initial: unknown[];
  execution: unknown[];
  stage: string;
  selectedAt: string;
}

/** Project one or more selected map parts into the record-paint callback payload. */
export function projectAtlasMapRecordArea(input: {
  parts: AtlasMapPartInput[];
  activityCatalog?: Array<Record<string, unknown>>;
  stage?: string;
  timestamp?: number;
}): AtlasMapRecordArea | null {
  const unique = new Map<string, AtlasMapPartInput>();
  (Array.isArray(input.parts) ? input.parts : []).filter(Boolean).forEach(part => {
    const record = projectAtlasMapProgressArea(part);
    if (record) unique.set(record.partId, part);
  });
  const entries = [...unique.entries()].map(([id, part]) => ({ id, ...projectAtlasMapProgressArea(part)! }));
  if (!entries.length) return null;
  const first = entries[0];
  const overlayKey = first.kind === 'lots' ? 'terraplanagem' : first.kind === 'streets' ? 'pavimentacao' : 'urbanizacao';
  const natureByOverlay: Record<string, string> = {
    terraplanagem: 'Terraplanagem', pavimentacao: 'Pavimentação', urbanizacao: 'Urbanização',
  };
  const nature = natureByOverlay[overlayKey] || 'Execução operacional';
  const catalog = Array.isArray(input.activityCatalog) ? input.activityCatalog : [];
  const searchTerm = nature.toLocaleLowerCase('pt-BR').split(' ')[0];
  const activity = catalog.find(item => item.nature === nature)
    || catalog.find(item => String(item.name || '').toLocaleLowerCase('pt-BR').includes(searchTerm))
    || catalog[0];
  const timestamp = Number.isFinite(input.timestamp) ? Number(input.timestamp) : Date.now();
  const stage = String(input.stage || 'Etapa não vinculada');
  const many = entries.length > 1;
  return Object.freeze({
    label: many ? `${entries.length} áreas selecionadas` : first.label,
    ...(many ? { labels: entries.map(item => item.label), partIds: entries.map(item => item.id) } : { partId: first.id }),
    kind: first.kind,
    overlayKey,
    nature: String(activity?.nature || nature),
    activity: String(activity?.name || 'Registrar atividade da área'),
    initial: Array.isArray(activity?.initial) ? activity.initial : [],
    execution: Array.isArray(activity?.execution) ? activity.execution : [],
    stage,
    selectedAt: new Date(timestamp).toISOString(),
  });
}

export interface AtlasStaticSatelliteGesturePolicy {
  minimumZoom: number;
  maximumZoom: number;
  markerRevealZoom: number;
  wheelMinimumStep: number;
  wheelMaximumStep: number;
  wheelSensitivity: number;
  controlWheelSensitivity: number;
  shiftDragZoomSensitivity: number;
  dragThresholdPixels: number;
  draggedClickSuppressRadiusPixels: number;
  draggedClickSuppressDurationMs: number;
  fitScale: number;
}

interface AtlasStaticSatelliteGesturePolicyCatalog extends Omit<AtlasStaticSatelliteGesturePolicy, 'maximumZoom'> {
  adminMaximumZoom: number;
  otherMaximumZoom: number;
}

const atlasStaticSatelliteGesturePolicyCatalog = mapStaticSatelliteGesturesData as AtlasStaticSatelliteGesturePolicyCatalog;

/** Resolve the static satellite gesture limits for the administrative or compact map surface. */
export function projectAtlasStaticSatelliteGesturePolicy(isAdminPublicMap: boolean): AtlasStaticSatelliteGesturePolicy {
  return Object.freeze({
    minimumZoom: atlasStaticSatelliteGesturePolicyCatalog.minimumZoom,
    maximumZoom: isAdminPublicMap ? atlasStaticSatelliteGesturePolicyCatalog.adminMaximumZoom : atlasStaticSatelliteGesturePolicyCatalog.otherMaximumZoom,
    markerRevealZoom: atlasStaticSatelliteGesturePolicyCatalog.markerRevealZoom,
    wheelMinimumStep: atlasStaticSatelliteGesturePolicyCatalog.wheelMinimumStep,
    wheelMaximumStep: atlasStaticSatelliteGesturePolicyCatalog.wheelMaximumStep,
    wheelSensitivity: atlasStaticSatelliteGesturePolicyCatalog.wheelSensitivity,
    controlWheelSensitivity: atlasStaticSatelliteGesturePolicyCatalog.controlWheelSensitivity,
    shiftDragZoomSensitivity: atlasStaticSatelliteGesturePolicyCatalog.shiftDragZoomSensitivity,
    dragThresholdPixels: atlasStaticSatelliteGesturePolicyCatalog.dragThresholdPixels,
    draggedClickSuppressRadiusPixels: atlasStaticSatelliteGesturePolicyCatalog.draggedClickSuppressRadiusPixels,
    draggedClickSuppressDurationMs: atlasStaticSatelliteGesturePolicyCatalog.draggedClickSuppressDurationMs,
    fitScale: atlasStaticSatelliteGesturePolicyCatalog.fitScale,
  });
}

export interface AtlasStaticSatelliteViewCommand {
  zoom: number;
  panX: number;
  panY: number;
}

/** Keep anchored zoom inside the viewport pan bounds. Coordinates are viewport-relative. */
export function createAtlasStaticSatelliteViewCommand(input: {
  zoom: number;
  panX: number;
  panY: number;
  nextZoom: number;
  anchorX: number;
  anchorY: number;
  width: number;
  height: number;
  minimumZoom: number;
  maximumZoom: number;
}): AtlasStaticSatelliteViewCommand {
  const targetZoom = Math.max(input.minimumZoom, Math.min(input.maximumZoom, input.nextZoom));
  const offsetX = input.anchorX - input.width / 2;
  const offsetY = input.anchorY - input.height / 2;
  const ratio = targetZoom / input.zoom;
  const side = Math.max(input.width, input.height);
  const limitX = Math.max(0, (side * targetZoom - input.width) / 2);
  const limitY = Math.max(0, (side * targetZoom - input.height) / 2);
  return Object.freeze({
    zoom: targetZoom,
    panX: Math.max(-limitX, Math.min(limitX, offsetX - (offsetX - input.panX) * ratio)),
    panY: Math.max(-limitY, Math.min(limitY, offsetY - (offsetY - input.panY) * ratio)),
  });
}

/** Project the initial satellite framing while leaving the frame's rotation in place. */
export function createAtlasStaticSatelliteFitCommand(input: {
  width: number;
  height: number;
  frame: PublicMapFrame;
  minimumZoom: number;
  maximumZoom: number;
  fitScale: number;
}): AtlasStaticSatelliteViewCommand {
  const side = Math.max(input.width, input.height);
  const angle = Number(input.frame.rotation || 0) * Math.PI / 180;
  const visualWidth = Math.abs(Number(input.frame.width) * Math.cos(angle)) + Math.abs(Number(input.frame.height) * Math.sin(angle));
  const visualHeight = Math.abs(Number(input.frame.width) * Math.sin(angle)) + Math.abs(Number(input.frame.height) * Math.cos(angle));
  const targetZoom = Math.max(input.minimumZoom, Math.min(
    input.maximumZoom,
    input.width * input.fitScale / Math.max(1, side * visualWidth),
    input.height * input.fitScale / Math.max(1, side * visualHeight),
  ));
  const frameCenterX = (input.width - side) / 2 + (Number(input.frame.left) + Number(input.frame.width) / 2) * side;
  const frameCenterY = (input.height - side) / 2 + (Number(input.frame.top) + Number(input.frame.height) / 2) * side;
  const limitX = Math.max(0, (side * targetZoom - input.width) / 2);
  const limitY = Math.max(0, (side * targetZoom - input.height) / 2);
  return Object.freeze({
    zoom: targetZoom,
    panX: Math.max(-limitX, Math.min(limitX, (input.width / 2 - frameCenterX) * targetZoom)),
    panY: Math.max(-limitY, Math.min(limitY, (input.height / 2 - frameCenterY) * targetZoom)),
  });
}

/** Clamp drag-pan movement against the current zoomed viewport. */
export function createAtlasStaticSatellitePanCommand(input: {
  panX: number;
  panY: number;
  deltaX: number;
  deltaY: number;
  zoom: number;
  width: number;
  height: number;
}): Pick<AtlasStaticSatelliteViewCommand, 'panX' | 'panY'> {
  const side = Math.max(input.width, input.height);
  const limitX = Math.max(0, (side * input.zoom - input.width) / 2);
  const limitY = Math.max(0, (side * input.zoom - input.height) / 2);
  return Object.freeze({
    panX: Math.max(-limitX, Math.min(limitX, input.panX + input.deltaX)),
    panY: Math.max(-limitY, Math.min(limitY, input.panY + input.deltaY)),
  });
}

export interface AtlasMapSceneControlCommand {
  action: 'rotate' | 'pan' | 'zoom' | 'tilt' | 'overlay' | 'selection' | 'tiles' | 'print' | 'fit';
  value?: string;
  nextValue?: number;
  controlAction: string;
}

/** Resolve visible map-control input into the imperative action the component applies. */
export function createAtlasMapSceneControlCommand(input: {
  action: AtlasMapSceneControlCommand['action'] | 'tilt-range';
  value?: unknown;
  rotation?: number;
  zoom?: number;
  tilt?: number;
  baseTilt?: number;
}): AtlasMapSceneControlCommand {
  const value = String(input.value ?? '');
  if (input.action === 'rotate') return Object.freeze({ action: 'rotate', value, nextValue: value === 'reset' ? 0 : (Number(input.rotation) || 0) + Number(value), controlAction: `rotate:${value}` });
  if (input.action === 'pan') return Object.freeze({ action: 'pan', value, controlAction: `pan:${value}` });
  if (input.action === 'zoom') return Object.freeze({ action: 'zoom', value, nextValue: (Number(input.zoom) || 0) + Number(value), controlAction: `zoom:${value}` });
  if (input.action === 'tilt') return Object.freeze({ action: 'tilt', value, nextValue: (Number(input.tilt) || 0) + Number(value), controlAction: `tilt:${value}` });
  if (input.action === 'overlay') return Object.freeze({ action: 'overlay', value, controlAction: `overlay:${value}` });
  if (input.action === 'selection') {
    const selection = value || 'progress';
    return Object.freeze({ action: 'selection', value: selection, controlAction: `selection:${selection}` });
  }
  if (input.action === 'tiles') return Object.freeze({ action: 'tiles', value, controlAction: `tiles:${value}` });
  if (input.action === 'print') return Object.freeze({ action: 'print', controlAction: 'print-map-pdf-interface' });
  if (input.action === 'fit') return Object.freeze({ action: 'fit', controlAction: 'fit' });
  if (input.action === 'tilt-range') return Object.freeze({ action: 'tilt', value, nextValue: Number(value) - (Number(input.baseTilt) || 0), controlAction: `tilt:absolute:${value}` });
  return Object.freeze({ action: 'tilt', value, nextValue: Number(input.tilt) || 0, controlAction: `tilt:${value}` });
}

