export type AtlasMapSceneStartupMode = 'wait-admin-shell' | 'static-only' | 'public-static-first' | 'shared-map' | 'leaflet-first';

/** Choose the map startup path from the active surface before touching browser state. */
export function projectAtlasMapSceneStartupPolicy(input: {
  adminShared: boolean;
  viewportReady: boolean;
  publicStaticOnly: boolean;
  publicCustomerExperience: boolean;
}): AtlasMapSceneStartupMode {
  if (input.adminShared && !input.viewportReady) return 'wait-admin-shell';
  if (input.publicStaticOnly) return 'static-only';
  if (input.publicCustomerExperience) return 'public-static-first';
  if (input.adminShared) return 'shared-map';
  return 'leaflet-first';
}

