export const atlasMapThreeFoundation = mapThreeFoundationData as AtlasMapThreeFoundationCatalog;

/** Keep render quality aligned with the active map surface and browser device. */
export function projectAtlasMapThreeRendererProfile(input: {
  adminRuntime: boolean;
  publicHighQuality: boolean;
  devicePixelRatio: unknown;
}): AtlasMapThreeRendererProfile {
  const highQuality = !input.adminRuntime && input.publicHighQuality;
  const devicePixelRatio = Number(input.devicePixelRatio) || 1;
  return {
    antialias: highQuality,
    powerPreference: highQuality ? 'high-performance' : 'low-power',
    precision: highQuality ? 'highp' : 'mediump',
    pixelRatio: input.adminRuntime
      ? atlasMapThreeFoundation.renderer.adminPixelRatio
      : highQuality
        ? Math.min(
          atlasMapThreeFoundation.renderer.publicMaximumPixelRatio,
          Math.max(atlasMapThreeFoundation.renderer.publicMinimumPixelRatio, devicePixelRatio),
        )
        : atlasMapThreeFoundation.renderer.adminPixelRatio,
  };
}

export interface AtlasMapThreePointerStartCommand {
  selecting: boolean;
  enableProgressSelection: boolean;
  zooming: boolean;
  tilting: false;
  rotating: boolean;
  panning: boolean;
  gesture: string;
}

/** Project the existing pointer-button and modifier policy for the 3D map. */
export function projectAtlasMapThreePointerStartCommand(input: {
  recordPaintMode: boolean;
  mapSelectionMode: unknown;
  button: number;
  altKey: boolean;
  shiftKey: boolean;
  ctrlKey: boolean;
}): AtlasMapThreePointerStartCommand {
  const selecting = (input.recordPaintMode || input.mapSelectionMode === 'progress') && input.button === 0;
  const zooming = !selecting && input.button === 0 && (input.shiftKey || input.ctrlKey);
  const rotating = !selecting && input.button === 2;
  const panning = !selecting && !zooming && !rotating && (input.button === 0 || input.button === 1);
  return Object.freeze({
    selecting,
    enableProgressSelection: false,
    zooming,
    tilting: false,
    rotating,
    panning,
    gesture: selecting ? 'select-progress' : zooming ? input.shiftKey ? 'shift-drag-zoom' : 'ctrl-drag-zoom' : rotating ? 'rotate' : panning ? 'pan' : 'idle',
  });
}

export interface AtlasMapThreeWheelZoomCommand {
  wheelMagnitude: number;
  nextZoom: number;
  gesture: string;
  label: string;
}

/** Keep cursor zoom steps and diagnostics consistent for normal and Ctrl-wheel input. */
export function projectAtlasMapThreeWheelZoom(input: {
  currentZoom: unknown;
  deltaY: unknown;
  ctrlKey: boolean;
}): AtlasMapThreeWheelZoomCommand {
  const deltaY = Number(input.deltaY) || 0;
  const wheelMagnitude = Math.max(
    input.ctrlKey ? 0.025 : 0.055,
    Math.min(input.ctrlKey ? 0.08 : 0.18, Math.abs(deltaY) * (input.ctrlKey ? 0.00035 : 0.0008)),
  );
  return Object.freeze({
    wheelMagnitude,
    nextZoom: (Number(input.currentZoom) || 0) + (deltaY < 0 ? wheelMagnitude : -wheelMagnitude),
    gesture: input.ctrlKey ? 'ctrl-wheel-zoom' : 'wheel-zoom',
    label: input.ctrlKey ? 'ctrl-wheel · cursor-ground · precise' : 'wheel · cursor-ground',
  });
}

/** Clamp world-space pan deltas to the active 3D map limits. */
export function projectAtlasMapThreePan(input: {
  currentPan: { x: number; y: number };
  delta: { x: number; y: number };
  bounds: { x?: unknown; y?: unknown };
}): { x: number; y: number } {
  const limitX = Number.isFinite(Number(input.bounds.x)) ? Math.max(0, Number(input.bounds.x)) : Infinity;
  const limitY = Number.isFinite(Number(input.bounds.y)) ? Math.max(0, Number(input.bounds.y)) : Infinity;
  return {
    x: Math.max(-limitX, Math.min(limitX, input.currentPan.x + input.delta.x)),
    y: Math.max(-limitY, Math.min(limitY, input.currentPan.y + input.delta.y)),
  };
}

/** Preserve static-first and explicit-activation gates for the expensive Three.js scene. */
export function projectAtlasMapSceneThreeSchedule(input: {
  staticOnly: boolean;
  publicCustomerExperience: boolean;
  force: boolean;
  standalone: boolean;
  standaloneActivated: boolean;
  alreadyScheduled: boolean;
  rendererInitialized: boolean;
}): AtlasMapSceneThreeScheduleCommand {
  if (input.staticOnly) return { action: 'blocked-static-only', forcedPublicBoot: false, modelBootPhase: 'static-only-no-webgl' };
  const forcedPublicBoot = input.force && input.publicCustomerExperience;
  if (input.standalone && !input.standaloneActivated && !forcedPublicBoot)
    return { action: 'blocked-static-first', forcedPublicBoot: false, modelBootPhase: 'blocked-until-explicit-activation' };
  if (input.alreadyScheduled || input.rendererInitialized)
    return { action: 'already-initialized', forcedPublicBoot, modelBootPhase: forcedPublicBoot ? 'scheduled-after-static-base' : 'scheduled-after-first-paint' };
  return { action: 'schedule', forcedPublicBoot, modelBootPhase: forcedPublicBoot ? 'scheduled-after-static-base' : 'scheduled-after-first-paint' };
}

