/** Return persisted map-startup metadata from the same reviewed screen catalog. */
export function projectAtlasMapLoadingBootStateConfig(): { version: string; storageKey: string } {
  return Object.freeze({ version: atlasMapLoadingCatalog.bootStateVersion, storageKey: atlasMapLoadingCatalog.bootStorageKey });
}

export interface AtlasMapLoadingBootStateGlobalV1 {
  __BELAVISTA_ADMIN_MODEL_STATE__?: Record<string, unknown>;
  Date: DateConstructor;
  localStorage?: Pick<Storage, 'setItem'>;
}

export interface AtlasMapLoadingBootStateRecorderPortsV1 {
  globalRef: AtlasMapLoadingBootStateGlobalV1;
  performanceNow: () => number;
  writeStorage: (key: string, value: string) => void;
  wallClock: () => string;
}

export interface AtlasMapLoadingBootStateCommandsV1 {
  beginBootStateV5367(initial: Record<string, unknown>): Record<string, unknown>;
  updateBootStateV5367(patch: Record<string, unknown>): Record<string, unknown>;
  persistBootPhaseV5367(phase: string, extra?: Record<string, unknown>): Record<string, unknown>;
}

/** Keep map boot-state lifecycle and durable persistence in the program owner. */
export function createAtlasMapLoadingBootStateCommandsV1(
  ports: AtlasMapLoadingBootStateRecorderPortsV1,
): AtlasMapLoadingBootStateCommandsV1 {
  const { version, storageKey } = projectAtlasMapLoadingBootStateConfig();
  const readOrCreate = (): Record<string, unknown> => {
    const state = ports.globalRef.__BELAVISTA_ADMIN_MODEL_STATE__
      ??= { version, startedAt: ports.performanceNow() };
    state.version = version;
    return state;
  };
  return Object.freeze({
    beginBootStateV5367(initial: Record<string, unknown>) {
      const state = { version, startedAt: ports.performanceNow(), ...initial };
      ports.globalRef.__BELAVISTA_ADMIN_MODEL_STATE__ = state;
      return state;
    },
    updateBootStateV5367(patch: Record<string, unknown>) {
      const state = readOrCreate();
      Object.assign(state, patch);
      return state;
    },
    persistBootPhaseV5367(phase: string, extra: Record<string, unknown> = {}) {
      const state = readOrCreate();
      state.version = version;
      state.phase = phase;
      Object.assign(state, extra);
      ports.globalRef.__BELAVISTA_ADMIN_MODEL_STATE__ = state;
      try {
        ports.writeStorage(storageKey, JSON.stringify({ version, phase, wallClock: ports.wallClock(), ...extra }));
      } catch { }
      return state;
    },
  });
}

export interface AtlasMapMasterplanMeshSemanticsInputV1 {
  name?: unknown;
  role?: unknown;
  partKind?: unknown;
  publicMap?: boolean;
  adminSharedMap?: boolean;
  publicRoadBaseHidden?: boolean;
  streetIndex?: unknown;
  otherIndex?: unknown;
}

export interface AtlasMapMasterplanMeshSemanticsV1 {
  kind: 'lots' | 'streets' | 'other';
  isLotDivider: boolean;
  isSocial: boolean;
  isPublicRoadSource: boolean;
  isPublicDividerSource: boolean;
  isLandscape: boolean;
  isStructure: boolean;
  partId: string;
  partLabel: string;
  selectable: boolean;
  mapSelectionKind: 'lot' | 'street' | '';
}

/** Resolve the canonical semantic role and interaction metadata for one GLB mesh. */
export function projectAtlasMapMasterplanMeshSemanticsV1(
  input: AtlasMapMasterplanMeshSemanticsInputV1,
): AtlasMapMasterplanMeshSemanticsV1 {
  const name = String(input.name || '');
  const normalizedName = name.toLowerCase();
  const role = String(input.role || '').toLowerCase();
  const roadRole = String(input.role || input.partKind || '').toLowerCase();
  const isPublicMap = input.publicMap === true;
  const isLotDivider = /^divisa(?:[_\s-]|$)/i.test(name);
  const isSocial = role === 'leisure' ||
    /area.?de.?lazer|court|gym.?pad|gym.?post|gym.?beam|gym.?seat|pavilhao|play|praca|banco.?praca/.test(normalizedName);
  const isPublicRoadSource = isPublicMap && (
    input.publicRoadBaseHidden === true ||
    /^(street|road|streets|curb|curbs)$/.test(roadRole) ||
    /(asfalto|rua|road|street|meio.?fio|guia|curb|paviment)/i.test(name)
  );
  const isPublicDividerSource = isPublicMap && /^divisa(?:[_\s-]|$)/i.test(name);
  const isStructure = /pavilhao.?telhado|pavilhao.?base/.test(normalizedName);
  const kind: AtlasMapMasterplanMeshSemanticsV1['kind'] = isPublicMap && isLotDivider
    ? 'other'
    : role === 'lot' || role === 'lots'
      ? 'lots'
      : role === 'street' || role === 'streets' || role === 'road'
        ? 'streets'
        : isSocial
          ? 'other'
          : /(lote|quadra|gleba)/.test(normalizedName)
            ? 'lots'
            : /(asfalto|rua|road|street|meio.?fio|guia|paviment)/.test(normalizedName)
              ? 'streets'
              : 'other';
  const streetIndex = Math.max(0, Math.floor(Number(input.streetIndex) || 0));
  const otherIndex = Math.max(0, Math.floor(Number(input.otherIndex) || 0));
  const partId = kind === 'lots'
    ? name
    : kind === 'streets'
      ? `street-source-${streetIndex + 1}`
      : name || `other-${otherIndex + 1}`;
  const partLabel = kind === 'lots'
    ? `Lote ${name.replace(/^.*?lote[_ -]?/i, '').replace(/[_ -]?mesh.*$/i, '')}`
    : kind === 'streets'
      ? `Paralelepípedo · trecho original ${streetIndex + 1}`
      : name || 'Elemento do empreendimento';
  const selectable = kind === 'lots' || kind === 'streets';
  return {
    kind,
    isLotDivider,
    isSocial,
    isPublicRoadSource,
    isPublicDividerSource,
    isLandscape: role === 'landscape' ||
      /arvore|tree|tronco|copa|folhagem|outer.?east.?row|upper.?median.?row/.test(normalizedName),
    isStructure,
    partId,
    partLabel,
    selectable,
    mapSelectionKind: kind === 'lots' ? 'lot' : kind === 'streets' ? 'street' : '',
  };
}

export interface AtlasMapLoadingScreenSnapshot extends AtlasMapLoadingPhase {
  phase: string;
  state: 'loading' | 'ready' | 'error' | 'public-static';
  value: string;
  error: boolean;
  hidden: boolean;
}

/** Project WebGL loading events into the exact copy, progress, and visibility shown by the map. */
export function projectAtlasMapLoadingScreen(input: {
  phase?: unknown;
  extra?: Record<string, unknown>;
  modelProgress?: unknown;
  publicCustomer?: boolean;
  adminMasterplanOverlay?: boolean;
}): AtlasMapLoadingScreenSnapshot {
  const normalized = String(input.phase || 'waiting').toLowerCase();
  const configured = atlasMapLoadingCatalog.phases[normalized];
  const text = configured || { ...atlasMapLoadingCatalog.fallback, progress: atlasMapLoadingCatalog.defaultProgress };
  if (input.publicCustomer) return {
    phase: normalized,
    ...text,
    state: 'public-static',
    value: `${text.progress}%`,
    error: false,
    hidden: true,
  };
  const extra = input.extra || {};
  const meshNumber = Number(extra.meshNumber || extra.stagedMeshes || 0);
  const meshCount = Number(extra.meshCount || 0);
  let progress = Number(extra.progress ?? input.modelProgress);
  if (!Number.isFinite(progress) || progress <= 0) progress = configured?.progress ?? atlasMapLoadingCatalog.defaultProgress;
  if (meshCount && meshNumber && /gpu-mesh|gpu-visible/.test(normalized))
    progress = Math.max(progress, 46 + Math.round((meshNumber / meshCount) * 32));
  if (normalized === 'gpu-ready' || normalized === 'ready') progress = 100;
  progress = Math.max(0, Math.min(100, Math.round(progress)));
  const error = /error$/.test(normalized);
  const state: AtlasMapLoadingScreenSnapshot['state'] = error ? 'error' : progress >= 100 ? 'ready' : 'loading';
  return {
    phase: normalized,
    progress,
    title: text.title,
    detail: text.detail,
    label: text.label,
    state,
    value: error ? '!' : `${progress}%`,
    error,
    hidden: Boolean(input.adminMasterplanOverlay || progress >= 100 && !error),
  };
}

/** Decide whether the public welcome screen or the map's in-place spinner owns the current loading phase. */
export function projectAtlasPublicModelLoadingV1(input: AtlasPublicModelLoadingSnapshotInputV1): AtlasPublicModelLoadingSnapshotV1 {
  const modelReady = Boolean(input.modelReady);
  const tiles = String(input.mapTextureTiles || '').split('/').map(value => Number(value));
  const loaded = Number.isFinite(tiles[0]) ? tiles[0] : 0;
  const total = Number.isFinite(tiles[1]) ? tiles[1] : 0;
  const satelliteReady = !input.hasPublicSatelliteBase || Boolean(input.publicDwgCenter && total > 0 && loaded >= total && input.mapTexture === 'ready');
  const vegetationReady = !input.publicPresentation || input.publicVegetation === 'cc0-tree-glb' && Number(input.publicTreeCount || 0) > 0;
  const roadTextureReady = !input.publicPresentation || input.publicRoadTextureRequired === 'false' || ['ready', 'fallback'].includes(String(input.publicRoadTexture || ''));
  const staticPresentationReady = Boolean(input.publicStaticOnly && (
    input.publicStaticImage === 'loaded' || input.publicStaticState === 'static-base-loaded' || input.publicStaticBaseReady === 'true'
  ));
  const presentationReady = staticPresentationReady || modelReady && satelliteReady && vegetationReady && roadTextureReady;
  const fallback = Boolean(input.modelError || input.publicThree === 'fallback' || input.three === 'fallback' || input.threeContext === 'lost');
  const rawProgress = Math.max(0, Math.min(100, Number.parseFloat(String(input.modelProgress || '0')) || 0));
  const modelAreaProgress = presentationReady
    ? 100
    : modelReady
      ? satelliteReady && vegetationReady && roadTextureReady
        ? 100
        : 80 + (Number(satelliteReady) + Number(vegetationReady) + Number(roadTextureReady)) / 3 * 20
      : Math.min(79, rawProgress * .55 + 20);
  const phaseCopy = atlasPublicModelLoadingCatalogV1.phases;
  let phase: AtlasPublicModelLoadingPhaseV1;
  let configured: { label: string; detail: string; target: number };
  if (fallback) {
    phase = 'error'; configured = phaseCopy.error;
  } else if (presentationReady) {
    phase = 'ready'; configured = phaseCopy.ready;
  } else if (input.publicThree === 'deferred' || !input.three && !input.rendererReady) {
    phase = 'boot'; configured = phaseCopy.boot;
  } else if (input.publicThree === 'scheduled') {
    phase = 'boot'; configured = phaseCopy.scheduled;
  } else if (input.publicThree === 'loading' || input.three === 'loading') {
    phase = 'runtime'; configured = phaseCopy.runtime;
  } else if (input.three === 'ready' && rawProgress <= 0) {
    phase = 'transfer'; configured = phaseCopy.transfer;
  } else if (rawProgress > 0 && rawProgress < 100) {
    phase = 'transfer'; configured = {
      ...phaseCopy.transfer,
      detail: `Sua visita está sendo preparada · ${Math.round(rawProgress)}%`,
      target: 38 + rawProgress * .5,
    };
  } else if (modelReady && !satelliteReady) {
    phase = 'satellite'; configured = {
      ...phaseCopy.satellite,
      detail: total > 0 ? phaseCopy.satellite.detail : 'Descobrindo cada detalhe da localização.',
      target: 82 + (total > 0 ? loaded / total : 0) * 14,
    };
  } else if (modelReady && satelliteReady && !vegetationReady) {
    phase = 'vegetation'; configured = phaseCopy.vegetation;
  } else if (modelReady && satelliteReady && vegetationReady && !roadTextureReady) {
    phase = 'road-texture'; configured = phaseCopy.roadTexture;
  } else if (rawProgress >= 100 || input.modelLoadStarted) {
    phase = 'processing'; configured = phaseCopy.processing;
  } else if (input.three === 'ready') {
    phase = 'processing'; configured = phaseCopy.processingReady;
  } else {
    phase = 'boot'; configured = phaseCopy.initial;
  }
  return { phase, ...configured, modelReady, presentationReady, fallback, satelliteReady, vegetationReady, roadTextureReady, modelAreaProgress };
}

/** Resolve the local satellite capture from viewport, Capacitor platform, and page overrides. */
export function projectAtlasMapStaticCaptureSource(input: {
  nativePlatform?: boolean;
  platform?: string;
  compactViewport?: boolean;
  userAgent?: string;
  mobileCapture?: string | null;
  publicCapture?: string | null;
  generatedAsset: string;
}): string {
  const mobile = input.nativePlatform === true || input.platform === 'android' || input.platform === 'ios' ||
    input.compactViewport === true || /Android|iPhone|iPad|iPod|Mobile/i.test(String(input.userAgent || ''));
  return mobile
    ? String(input.mobileCapture || atlasMapAssetProfile.satellite)
    : String(input.publicCapture || input.generatedAsset);
}

/** Normalize requested map imagery and describe the visible/persisted transition. */
export function createAtlasMapTileModeCommand(input: { requested?: unknown; current?: unknown; publicCustomer?: boolean }): AtlasMapTileModeCommand {
  const requested = String(input.requested ?? 'satellite');
  const mode: AtlasMapTileModeCommand['mode'] = input.publicCustomer ? 'generated' : ['satellite', 'osm', 'generated'].includes(requested) ? requested as AtlasMapTileModeCommand['mode'] : 'satellite';
  const label = mode === 'satellite' ? 'Satélite realista' : mode === 'generated' ? 'Satélite tratado · DWG' : 'Mapa OSM';
  return Object.freeze({
    mode,
    changed: input.current !== mode,
    label,
    lastAction: `Alterou base cartográfica para ${label}`,
    feedback: `${label} ativado na cena compartilhada.`,
  });
}

export interface AtlasMapSceneInitialStateCommand {
  isAdminPublicMap: boolean;
  isAdminReferenceAerial: boolean;
  isCurrentSceneState: boolean;
  initialSceneZoom: number;
  mapTileMode: string;
  sceneManualRotation: number;
  sceneManualZoom: number;
  sceneManualPan: { x: number; y: number };
  sceneTiltAdjust: number;
  sceneUserInteracted: boolean;
  stageOverlayKey: string;
}

/** Reconcile persisted camera preferences with the active map-surface policy. */
export function createAtlasMapSceneInitialStateCommand(input: {
  savedMap?: unknown;
  isDashboardScene: boolean;
  isAdminPublicMap: boolean;
  isAdminReferenceAerial: boolean;
  isPublicCustomer: boolean;
  storedTileMode?: unknown;
  stageOverlayKey: string;
  ADMIN_FIXED_MAP_ROTATION_DEG: number;
  ADMIN_REFERENCE_AERIAL_INITIAL_SCENE_ZOOM: number;
  ADMIN_REFERENCE_AERIAL_VIEW_VERSION: number;
  DASHBOARD_INITIAL_SCENE_ZOOM: number;
  INITIAL_SCENE_ZOOM: number;
  MAP_SCENE_STATE_VERSION: number;
}): AtlasMapSceneInitialStateCommand {
  const saved = input.savedMap && typeof input.savedMap === 'object' ? input.savedMap as Record<string, unknown> : {};
  const savedPan = saved.pan && typeof saved.pan === 'object' ? saved.pan as Record<string, unknown> : {};
  const initialSceneZoom = input.isDashboardScene
    ? input.isAdminPublicMap ? 1.62
      : input.isAdminReferenceAerial ? input.ADMIN_REFERENCE_AERIAL_INITIAL_SCENE_ZOOM
      : input.DASHBOARD_INITIAL_SCENE_ZOOM
    : input.INITIAL_SCENE_ZOOM;
  const isCurrentSceneState = !input.isAdminPublicMap
    && Number(saved.sceneVersion) === input.MAP_SCENE_STATE_VERSION
    && (!input.isAdminReferenceAerial || Number(saved.referenceAerialVersion) === input.ADMIN_REFERENCE_AERIAL_VIEW_VERSION);
  const sceneManualRotation = input.isAdminPublicMap ? 0
    : input.isAdminReferenceAerial ? input.ADMIN_FIXED_MAP_ROTATION_DEG
    : isCurrentSceneState ? Number(saved.rotation) || 0 : 0;
  const sceneManualZoom = isCurrentSceneState ? Number(saved.zoom) || initialSceneZoom : initialSceneZoom;
  const sceneManualPan = isCurrentSceneState
    ? { x: Number(savedPan.x) || 0, y: Number(savedPan.y) || 0 }
    : { x: 0, y: 0 };
  const sceneTiltAdjust = isCurrentSceneState ? Number(saved.tiltAdjust) || 0 : 0;
  const sceneUserInteracted = isCurrentSceneState && Boolean(
    sceneManualRotation || sceneTiltAdjust || sceneManualPan.x || sceneManualPan.y || sceneManualZoom !== initialSceneZoom,
  );
  return Object.freeze({
    isAdminPublicMap: input.isAdminPublicMap,
    isAdminReferenceAerial: input.isAdminReferenceAerial,
    isCurrentSceneState,
    initialSceneZoom,
    mapTileMode: input.isPublicCustomer ? 'generated' : String(input.storedTileMode || 'satellite'),
    sceneManualRotation,
    sceneManualZoom,
    sceneManualPan,
    sceneTiltAdjust,
    sceneUserInteracted,
    stageOverlayKey: String(input.stageOverlayKey || ''),
  });
}

export interface AtlasMapSceneSurfacePolicyInput {
  publicMapAttribute: boolean;
  publicPresentationAttribute: boolean;
  adminSharedAttribute: boolean;
  adminPublicAttribute: boolean;
  activityLocationEditorAttribute: boolean;
  publicCameraInteracted: boolean;
  mapInit: string;
  locationPath: string;
  insideAdminApplication: boolean;
}

export interface AtlasMapSceneSurfacePolicy {
  isPublicMapVisual: boolean;
  isPublicCustomerExperience: boolean;
  isAdminPublicMap: boolean;
  isPublicCameraPreset: boolean;
  isAdminStandalone3D: boolean;
}

/** Classify the public, shared-admin and standalone map surfaces from current host state. */
export function projectAtlasMapSceneSurfacePolicy(input: AtlasMapSceneSurfacePolicyInput): AtlasMapSceneSurfacePolicy {
  const isPublicMapVisual = input.publicMapAttribute || input.publicPresentationAttribute;
  const isPublicCustomerExperience = isPublicMapVisual && !input.adminSharedAttribute;
  const isAdminPublicMap = input.adminPublicAttribute;
  const isAdminRoute = input.locationPath === '/admin' || input.locationPath.startsWith('/admin/');
  const isRubyAdminRoute = input.mapInit === 'admin-static-first-v5370';
  const isAdminStandalone3D = !input.activityLocationEditorAttribute && !isAdminPublicMap && (
    input.adminSharedAttribute
      ? isAdminRoute || isRubyAdminRoute
      : isAdminRoute || input.insideAdminApplication
  );
  return {
    isPublicMapVisual,
    isPublicCustomerExperience,
    isAdminPublicMap,
    isPublicCameraPreset: isPublicCustomerExperience && (isAdminPublicMap || !input.publicCameraInteracted),
    isAdminStandalone3D,
  };
}

