/** Resolve the selected demonstration stage name used by the shared map context. */
export function projectAtlasMapContextStageNameV1(activitiesValue: unknown, selectedStageValue: unknown): string | null {
  const activities = Array.isArray(activitiesValue) ? activitiesValue : [];
  const stage = activities.find(item => {
    const activity = item && typeof item === 'object' ? item as Record<string, unknown> : {};
    return activity.id === selectedStageValue;
  });
  if (!stage || typeof stage !== 'object') return null;
  const name = (stage as Record<string, unknown>).name;
  return name == null || name === '' ? null : String(name);
}

/** Resolve whether a theme change is duplicate and whether page layout needs a recenter. */
export function projectAtlasMapSceneContextTransition(input: {
  view: unknown;
  currentTheme: unknown;
  themeGuard: unknown;
}): { action: 'skip' | 'apply'; recenterAfterLayout: boolean } {
  const view = input.view;
  if (input.currentTheme === view && input.themeGuard === view) return { action: 'skip', recenterAfterLayout: false };
  return {
    action: 'apply',
    recenterAfterLayout: typeof view === 'string' && atlasMapSceneContextCatalog.recenterViews.includes(view),
  };
}

export interface AtlasMapSceneTiltCommand {
  branch: 'standalone' | 'shared';
  targetTilt: number;
  sceneTiltAdjust: number;
  bounds: { min: number; max: number };
  publicPresentation: boolean;
}

/** Project the requested tilt while preserving standalone and public camera constraints. */
export function projectAtlasMapSceneTilt(input: {
  requestedAdjust: unknown;
  previousAdjust: unknown;
  previousTilt: unknown;
  previousStandaloneTilt: unknown;
  standalone: boolean;
  standaloneBaseTilt: number;
  sharedAdmin: boolean;
  publicPresentation: boolean;
  themeTilt: unknown;
  tiltBoost: number;
  minTilt: number;
  maxTilt: number;
  adjustLimit: number;
  bounds?: { min: number; max: number } | null;
}): AtlasMapSceneTiltCommand {
  const previousAdjust = Number(input.previousAdjust) || 0;
  const requestedAdjust = Math.max(-input.adjustLimit, Math.min(input.adjustLimit, Number(input.requestedAdjust) || 0));
  if (input.standalone) {
    const previousStandaloneTilt = Number(input.previousStandaloneTilt) || input.standaloneBaseTilt;
    const targetTilt = Math.max(input.minTilt, Math.min(input.maxTilt, previousStandaloneTilt + (requestedAdjust - previousAdjust)));
    return {
      branch: 'standalone', targetTilt, sceneTiltAdjust: targetTilt - input.standaloneBaseTilt,
      bounds: { min: input.minTilt, max: input.maxTilt }, publicPresentation: false,
    };
  }
  const bounds = input.bounds || { min: input.minTilt, max: input.maxTilt };
  const previousTiltValue = Number(input.previousTilt);
  const previousTilt = Number.isFinite(previousTiltValue) ? previousTiltValue : 22;
  const base = input.sharedAdmin ? 22 : (Number(input.themeTilt) || 18) + input.tiltBoost;
  const targetTilt = input.publicPresentation
    ? 22
    : Math.max(bounds.min, Math.min(bounds.max, previousTilt + (requestedAdjust - previousAdjust)));
  return {
    branch: 'shared', targetTilt, sceneTiltAdjust: input.publicPresentation ? 0 : targetTilt - base,
    bounds, publicPresentation: input.publicPresentation,
  };
}

interface AtlasMapCameraFramingCatalog {
  focus: {
    padXMinPx: number; padXMaxPx: number; padXViewportRatio: number;
    padYMinPx: number; padYMaxPx: number; padYViewportRatio: number;
    maxFrameWidthRatio: number; minFrameWidthPx: number;
    maxFrameHeightRatio: number; minFrameHeightPx: number;
  };
  gap: {
    minVisibleOpacity: number; minVisibleSizePx: number; mobileViewportWidthPx: number;
    mobileLeftRatio: number; mobileRightRatio: number; heroFallbackRightRatio: number;
    chatFallbackLeftRatio: number; marginMinPx: number; marginMaxPx: number;
    marginViewportRatio: number; minimumGapWidthPx: number; fallbackLeftRatio: number;
    fallbackRightRatio: number; targetYRatio: number; frameTopRatio: number;
    frameHeightRatio: number; defaultTiltDeg: number; defaultSceneZoom: number;
    tiltCompensationStartDeg: number; tiltCompensationPerDegree: number;
    minimumTargetWidthPx: number; targetWidthViewportRatio: number;
    targetWidthGapMultiplier: number; maximumTargetHeightViewportRatio: number;
    targetHeightViewportRatio: number; minimumZoomRatio: number; maximumZoomRatio: number;
    minimumSceneZoom: number; maximumSceneZoom: number;
  };
  fit: { standaloneSceneZoom: number; syncDelayMs: number };
}
const atlasMapCameraFramingCatalog = mapCameraFramingData as AtlasMapCameraFramingCatalog;

export interface AtlasMapCameraScreenPoint { x: number; y: number }
export interface AtlasMapCameraScreenBounds {
  left: number; right: number; top: number; bottom: number; centerDepth: number;
}

/** Apply the shared visibility thresholds used by public map framing overlays. */
export function isAtlasMapCameraFramingRectVisible(input: {
  display: string; visibility: string; opacity: unknown; width: number; height: number;
}): boolean {
  const config = atlasMapCameraFramingCatalog.gap;
  return input.display !== 'none' && input.visibility !== 'hidden' && Number(input.opacity || 1) >= config.minVisibleOpacity &&
    input.width >= config.minVisibleSizePx && input.height >= config.minVisibleSizePx;
}

/** Project the public focus frame from projected 3D footprint corners. */
export function projectAtlasPublicFocusFrame(input: {
  width: number; height: number; points: AtlasMapCameraScreenPoint[];
}): { centerX: number; centerY: number; width: number; height: number } | null {
  if (!input.points.length) return null;
  const { focus } = atlasMapCameraFramingCatalog;
  const xs = input.points.map(point => point.x), ys = input.points.map(point => point.y);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  const padX = Math.max(focus.padXMinPx, Math.min(focus.padXMaxPx, input.width * focus.padXViewportRatio));
  const padY = Math.max(focus.padYMinPx, Math.min(focus.padYMaxPx, input.height * focus.padYViewportRatio));
  const width = Math.min(input.width * focus.maxFrameWidthRatio, Math.max(focus.minFrameWidthPx, maxX - minX + padX * 2));
  const height = Math.min(input.height * focus.maxFrameHeightRatio, Math.max(focus.minFrameHeightPx, maxY - minY + padY * 2));
  const centerX = Math.max(width / 2, Math.min(input.width - width / 2, (minX + maxX) / 2));
  const centerY = Math.max(height / 2, Math.min(input.height - height / 2, (minY + maxY) / 2));
  return { centerX, centerY, width, height };
}

/** Project the public corridor and its idempotency signature from live layout. */
export function projectAtlasPublicGapLayout(input: {
  width: number; height: number; heroRight?: number | null; chatLeft?: number | null;
  visualTilt: unknown; scrollSection?: string; previousSignature?: string;
}): {
  skip: boolean; signature: string; left: number; right: number; gapWidth: number;
  targetX: number; targetY: number; rectTop: number; rectHeight: number; source: string; visualTilt: number;
} {
  const config = atlasMapCameraFramingCatalog.gap;
  const visualTilt = Number(input.visualTilt || config.defaultTiltDeg);
  const mobile = input.width <= config.mobileViewportWidthPx;
  const margin = Math.max(config.marginMinPx, Math.min(config.marginMaxPx, input.width * config.marginViewportRatio));
  let left = mobile ? input.width * config.mobileLeftRatio : (input.heroRight ?? input.width * config.heroFallbackRightRatio) + margin;
  let right = mobile ? input.width * config.mobileRightRatio : (input.chatLeft ?? input.width * config.chatFallbackLeftRatio) - margin;
  if (!mobile && right - left < config.minimumGapWidthPx) {
    left = input.width * config.fallbackLeftRatio;
    right = input.width * config.fallbackRightRatio;
  }
  const gapWidth = Math.max(config.minimumGapWidthPx, right - left);
  const targetX = mobile ? input.width / 2 : (left + right) / 2;
  const targetY = input.height * config.targetYRatio;
  const signature = [
    Math.round(input.width), Math.round(input.height), Math.round(left), Math.round(right),
    Math.round(visualTilt * 10), input.scrollSection || 'title',
  ].join('|');
  return {
    skip: input.previousSignature === signature, signature, left, right, gapWidth, targetX, targetY,
    rectTop: input.height * config.frameTopRatio,
    rectHeight: input.height * config.frameHeightRatio,
    source: mobile ? 'viewport-mobile' : input.heroRight != null && input.chatLeft != null ? 'hero-right · chat-left' : 'public-safe-corridor',
    visualTilt,
  };
}

/** Project target public-map zoom from the corridor, tilt, and projected footprint. */
export function projectAtlasPublicGapScale(input: {
  width: number; height: number; gapWidth: number; visualTilt: number; currentScale?: unknown;
  bounds: AtlasMapCameraScreenBounds;
}): {
  targetWidth: number; targetHeight: number; currentWidth: number; currentHeight: number;
  targetScale: number; tiltCompensation: number;
} {
  const config = atlasMapCameraFramingCatalog.gap;
  const tiltCompensation = 1 + Math.max(0, input.visualTilt - config.tiltCompensationStartDeg) * config.tiltCompensationPerDegree;
  const targetWidth = Math.max(config.minimumTargetWidthPx, Math.min(input.width * config.targetWidthViewportRatio, input.gapWidth * config.targetWidthGapMultiplier * tiltCompensation));
  const targetHeight = Math.min(input.height * config.maximumTargetHeightViewportRatio, input.height * config.targetHeightViewportRatio * tiltCompensation);
  const currentWidth = Math.max(1, input.bounds.right - input.bounds.left);
  const currentHeight = Math.max(1, input.bounds.bottom - input.bounds.top);
  const ratio = Math.max(config.minimumZoomRatio, Math.min(config.maximumZoomRatio, Math.min(targetWidth / currentWidth, targetHeight / currentHeight)));
  const currentScale = Math.max(0.01, Number(input.currentScale) || config.defaultSceneZoom);
  const targetScale = Math.max(config.minimumSceneZoom, Math.min(config.maximumSceneZoom, currentScale * ratio));
  return { targetWidth, targetHeight, currentWidth, currentHeight, targetScale, tiltCompensation };
}

/** Resolve the state reset and sync timing for the scene's fit action. */
export function createAtlasMapSceneFitCommand(input: {
  sharedAdmin: boolean; standalone: boolean; fixedRotation: number; defaultZoom: number;
}): { rotation: number; zoom: number; pan: { x: number; y: number }; tiltAdjust: number; standalone: boolean; syncDelayMs: number } {
  return {
    rotation: input.sharedAdmin ? input.fixedRotation : 0,
    zoom: input.standalone ? atlasMapCameraFramingCatalog.fit.standaloneSceneZoom : input.defaultZoom,
    pan: { x: 0, y: 0 }, tiltAdjust: 0, standalone: input.standalone,
    syncDelayMs: atlasMapCameraFramingCatalog.fit.syncDelayMs,
  };
}

