export interface AtlasMapSceneStateCommandsV1 {
  transitionTileMode(input: { requested?: unknown; current?: unknown; publicCustomer?: boolean; persist?: boolean }): AtlasMapTileModeCommand;
  saveSolarHour(hour: number, formattedTime: string): void;
  toggleMapMode(): AtlasMapModeToggleCommand;
  recordSelection(lastAction: string): void;
  openCatalogLot(catalogLabel: string): void;
  createReservation(input: AtlasMapReservationCommandInput): AtlasMapReservationCommand;
  recordModelPartSelection(label: string): void;
  markMapReady(): void;
  saveMapView(mapView: unknown): void;
}

/** Own persisted map imagery, solar-time, and focus-mode transitions. */
export function createAtlasMapSceneStateCommandsV1(appStore: {
  get(): Record<string, unknown>;
  set(patch: Record<string, unknown>): unknown;
}): AtlasMapSceneStateCommandsV1 {
  return Object.freeze({
    transitionTileMode(input: { requested?: unknown; current?: unknown; publicCustomer?: boolean; persist?: boolean }): AtlasMapTileModeCommand {
      const command = createAtlasMapTileModeCommand(input);
      if (command.changed && input.persist) appStore.set({ mapTileMode: command.mode, lastAction: command.lastAction });
      return command;
    },
    saveSolarHour(hour: number, formattedTime: string): void {
      appStore.set({ solarHour: hour, solarHourMode: 'manual', lastAction: `Horário solar ajustado para ${formattedTime}` });
    },
    toggleMapMode(): AtlasMapModeToggleCommand {
      const command = createAtlasMapModeToggleCommand(appStore.get().mapMode);
      appStore.set({ mapMode: command.mapMode, lastAction: command.lastAction });
      return command;
    },
    recordSelection(lastAction: string): void {
      appStore.set({ lastAction });
    },
    openCatalogLot(catalogLabel: string): void {
      const label = String(catalogLabel || '').trim();
      if (!label) return;
      appStore.set({ view: 'lot-detail', selectedLotDetailKey: label, lotDetailReturnView: 'map', lastAction: `Abriu a ficha do lote ${label} pelo mapa` });
    },
    createReservation(input: AtlasMapReservationCommandInput): AtlasMapReservationCommand {
      const command = createAtlasMapReservationCommand(input);
      appStore.set({ lastAction: command.lastAction, mapReservation: command.reservation });
      return command;
    },
    recordModelPartSelection(label: string): void {
      appStore.set({ lastAction: `Selecionou ${label}` });
    },
    markMapReady(): void {
      appStore.set({ mapReady: true });
    },
    saveMapView(mapView: unknown): void {
      appStore.set({ mapView });
    },
  });
}

export interface SidebarNavigationCommandInput {
  view: unknown;
  buttonLabel: string;
  reportFamily?: string;
  reportCatalog: Array<{ id: string; family: string }>;
}

export interface SidebarNavigationCommand {
  requestedNext: string;
  next: string;
  patch: Record<string, unknown>;
  collapseWorkerAssistant: boolean;
  refreshCashFlow: boolean;
}

/** Project one sidebar intent into canonical application state and adapter effects. */
export function createSidebarNavigationCommand(input: SidebarNavigationCommandInput): SidebarNavigationCommand {
  const { requestedNext, next } = resolveSidebarNavigationTarget(input.view);
  const patch: Record<string, unknown> = {
    view: next,
    activityDedicated: false,
    stageActivityDedicatedV9: false,
    selectedActivity: null,
    sidebarCollapsed: false,
    lastAction: requestedNext === next
      ? `Abriu ${String(input.buttonLabel || '').trim()}`
      : 'Área removida da navegação; abriu a Central operacional',
  };
  if (next === 'contracts' || next === 'proposals') {
    patch.proposalFormOpen = false;
    patch.contractEditing = null;
  }
  if (next === 'reports' && input.reportFamily) {
    const first = input.reportCatalog.find(report => report.family === input.reportFamily);
    patch.reportFamily = input.reportFamily;
    patch.reportType = first?.id || 'financial-balance';
  }
  return Object.freeze({
    requestedNext,
    next,
    patch: Object.freeze(patch),
    collapseWorkerAssistant: next === 'lot-development',
    refreshCashFlow: next === 'finance',
  });
}

/** Apply the shared sidebar route policy and its browser effects from any shell entry. */
export function applyAtlasSidebarNavigationCommandV1(input: {
  appStore: { set(patch: Record<string, unknown>): unknown };
  command: SidebarNavigationCommand;
  document?: Pick<Document, 'querySelector'>;
  window?: Pick<Window, 'location' | 'history'>;
  getWorkerAssistant?: () => { setCollapsed?: (collapsed: boolean) => unknown } | null | undefined;
}): void {
  const { appStore, command } = input;
  appStore.set(command.patch);
  if (command.collapseWorkerAssistant)
    input.getWorkerAssistant?.()?.setCollapsed?.(true);

  const viewLayer = input.document?.querySelector('view-layer') as
    | (Element & { render?: () => unknown; refreshCashFlow?: () => unknown })
    | null
    | undefined;
  if (viewLayer?.getAttribute('data-view') !== command.next && typeof viewLayer?.render === 'function')
    viewLayer.render();

  const location = input.window?.location;
  const history = input.window?.history;
  if (location?.href && history?.replaceState) {
    const url = new URL(location.href);
    url.searchParams.set('view', command.next);
    history.replaceState(history.state, '', url);
  }
  if (command.refreshCashFlow) viewLayer?.refreshCashFlow?.();
}

