  installCommunicationsPanel(host: Document, services: { subscribeContacts: (actor: Record<string, unknown>, onChange: (contacts: CommunicationContact[]) => void) => Promise<() => void>; subscribeConversation: (actor: Record<string, unknown>, contact: CommunicationContact, onChange: (messages: CommunicationMessage[]) => void) => Promise<() => void>; sendMessage: (actor: Record<string, unknown>, contact: CommunicationContact, message: string) => Promise<unknown>; currentActor?: () => Record<string, unknown> }): void;
