/** Project configurable report fields, property bags, stable identities, and grouping order. */
export function createAtlasStageMaterialReportModelV1(input: AtlasStageMaterialReportModelInputV1): AtlasStageMaterialReportModelV1 {
  const { normalize, attachments } = input;
  const text = (value: unknown): string => {
    if (value == null || value === '') return '—';
    if (Array.isArray(value)) return value.map(text).join(', ');
    if (typeof value === 'object') return Object.entries(value as Record<string, unknown>).map(([key, item]) => `${key}: ${text(item)}`).join(' · ');
    return String(value);
  };
  const properties = (item: AtlasStageMaterialReportRowV1): Array<Record<string, any>> => {
    const value = item?.properties;
    if (Array.isArray(value)) return value.filter(entry => entry && typeof entry === 'object');
    if (value && typeof value === 'object') return Object.entries(value).map(([key, itemValue]) => ({ id: key, label: key, value: itemValue }));
    return [];
  };
  const fields = (rows: AtlasStageMaterialReportRowV1[]): AtlasStageMaterialReportFieldV1[] => {
    const baseFields: AtlasStageMaterialReportFieldV1[] = [
      { key: 'stage', label: 'Etapa', read: item => item.stageName || item.etapa || 'Sem etapa' },
      { key: 'activity', label: 'Atividade', read: item => item.activityName || item.activity || item.atividade || item.title || 'Sem atividade vinculada' },
      { key: 'name', label: 'Material / equipamento', read: item => item.name || item.materialName || 'Material sem nome' },
      { key: 'scope', label: 'Descrição / uso', read: item => item.scope || item.detail || item.description || item.detalhes || '—' },
      { key: 'quantity', label: 'Quantidade', read: item => item.quantity ?? item.quantidade ?? '—' },
      { key: 'unit', label: 'Unidade', read: item => item.unit || item.unidade || 'un.' },
      { key: 'status', label: 'Status', read: item => item.status || 'Planejado' },
      { key: 'responsible', label: 'Responsável', read: item => item.responsible || item.responsavel || item.owner || '—' },
      { key: 'source', label: 'Origem do registro', read: item => item.source === 'chat-visual' ? 'OCR do assistente' : item.source || 'Adição do assistente' },
      { key: 'date', label: 'Data do registro', read: item => item.createdAt || item.updatedAt || item.date || item.data || '—' },
      { key: 'attachments', label: 'Comprovantes', read: item => attachments(item).map(attachment => attachment.label).join(', ') || 'Sem anexo' },
    ];
    const custom = new Map<string, { key: string; label: string }>();
    rows.forEach(item => properties(item).forEach(property => {
      const identity = String(property.id || property.key || property.name || property.label || '').trim();
      if (!identity) return;
      const key = identity.toLocaleLowerCase('pt-BR');
      if (!custom.has(key)) custom.set(key, { key: identity, label: String(property.label || property.name || property.key || identity) });
    }));
    const customFields = [...custom.values()].map(property => ({
      key: `property:${property.key}`,
      label: property.label,
      read: (item: AtlasStageMaterialReportRowV1): unknown => {
        const found = properties(item).find(entry => String(entry.id || entry.key || entry.name || entry.label || '').toLocaleLowerCase('pt-BR') === property.key.toLocaleLowerCase('pt-BR'));
        return found?.value ?? '—';
      },
    }));
    return baseFields.concat(customFields);
  };
  const id = (item: AtlasStageMaterialReportRowV1, index: number): string => String(item?.id ?? item?.sourceRecordId ?? `material-${index}`);
  const groups: AtlasStageMaterialReportModelV1['groups'] = (rows, groupKeys, sortKey, direction, allFields) => {
    const byKey = new Map(allFields.map(field => [field.key, field]));
    const compare = (left: unknown, right: unknown): number => {
      const result = normalize(text(left)).localeCompare(normalize(text(right)), 'pt-BR', { numeric: true, sensitivity: 'base' });
      return direction === 'desc' ? -result : result;
    };
    const orderedRows = [...rows].sort((left, right) => {
      for (const key of groupKeys) {
        const field = byKey.get(key);
        if (field) {
          const result = compare(field.read(left), field.read(right));
          if (result) return result;
        }
      }
      const field = byKey.get(sortKey);
      return field ? compare(field.read(left), field.read(right)) : 0;
    });
    const grouped = new Map<string, { label: string; rows: Array<{ item: AtlasStageMaterialReportRowV1; index: number }> }>();
    orderedRows.forEach((item, index) => {
      const values = groupKeys.map(key => {
        const field = byKey.get(key);
        return field ? text(field.read(item)) : '';
      });
      const label = values.length ? values.join(' · ') : 'Todos os materiais';
      const key = JSON.stringify(values);
      if (!grouped.has(key)) grouped.set(key, { label, rows: [] });
      grouped.get(key)!.rows.push({ item, index });
    });
    return [...grouped.values()];
  };
  return { normalize, properties, fields, id, text, groups };
}

export interface AtlasStageRecordServicesInputV1 {
  executionModel?: { stages?: AtlasStageRecordStageV1[] };
  demoData?: { activities?: Array<Record<string, unknown>> };
  controlCenterMaterialRowsV1?: (state: Record<string, unknown>) => AtlasStageRecordRowV1[];
  isAssistantVisualAdditionV1: (record: Record<string, unknown>) => unknown;
  stageV9LiveFor?: (stage: AtlasStageRecordStageV1) => Record<string, unknown> | null | undefined;
}

/** Build typed stage, attachment, OCR and material projections from live record data. */
export function createAtlasStageRecordServicesV1(input: AtlasStageRecordServicesInputV1): AtlasStageRecordServicesV1 {
  const { executionModel, demoData, controlCenterMaterialRowsV1, isAssistantVisualAdditionV1, stageV9LiveFor } = input;
  const asRecord = (value: unknown): Record<string, unknown> | null =>
    value !== null && typeof value === 'object' && !Array.isArray(value)
      ? value as Record<string, unknown>
      : null;
  const recordList = (value: unknown): Record<string, unknown>[] =>
    Array.isArray(value) ? value.map(asRecord).filter((item): item is Record<string, unknown> => item !== null) : [];
  const stageRecordNormalizeV1 = (value: unknown): string => String(value ?? '').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
  const stageRecordStagesV1 = (): AtlasStageRecordStageV1[] => {
    const sourceStages = Array.isArray(executionModel?.stages) && executionModel.stages.length
      ? executionModel.stages
      : (Array.isArray(demoData?.activities) ? demoData.activities : []).map(stage => ({ key: stage.key || stage.id, name: stage.name, ...stage })) as AtlasStageRecordStageV1[];
    const stages = [...sourceStages];
    const destinations = (stageDestinationsCatalogData as { destinations?: Array<AtlasRecordOcrStageOptionV1 & { description?: string }> }).destinations || [];
    for (const destination of destinations) {
      const key = String(destination.key || '').trim(), name = String(destination.name || '').trim();
      if (!key || !name || stages.some(stage => stageRecordNormalizeV1(stage.key) === stageRecordNormalizeV1(key) || stageRecordNormalizeV1(stage.name) === stageRecordNormalizeV1(name))) continue;
      stages.push({
        key,
        name,
        status: 'planejado',
        progress: 0,
        owner: 'Equipe administrativa',
        week: 'Apoio administrativo',
        priority: 'Administrativa',
        description: destination.description || 'Destino administrativo para notas, atividades e repasses.',
        production: { unit: 'registro administrativo' },
        activities: [],
      });
    }
    return stages;
  };
  const stageRecordStageForV1 = (record: Record<string, unknown>, stages: AtlasStageRecordStageV1[]): AtlasStageRecordStageV1 | null => {
    const values = [record?.stageKey, record?.stageId, record?.stage, record?.stageName, record?.etapa, record?.etapaNome, record?.activityStage, record?.atividade].map(stageRecordNormalizeV1).filter(Boolean);
    return stages.find(stage => {
      const candidates = [stage.key, stage.id, stage.name].map(stageRecordNormalizeV1).filter(Boolean);
      return values.some(value => candidates.includes(value) || candidates.some(candidate => candidate.length > 3 && (value.includes(candidate) || candidate.includes(value))));
    }) || null;
  };
  const stageRecordAttachmentsV1 = (record: Record<string, unknown>): AtlasStageRecordAttachmentV1[] => {
    const entries = (value: unknown): Record<string, unknown>[] => {
      if (Array.isArray(value)) return value.map(asRecord).map(item => item || {});
      const object = asRecord(value);
      return object ? Object.values(object).map(asRecord).map(item => item || {}) : [];
    };
    const lists: Array<Record<string, unknown>> = [record.attachments, record.files, record.evidencias].flatMap(entries);
    const properties = recordList(record.properties);
    const propertyValue = (id: string): unknown => properties.find(item => item.id === id)?.value;
    const storedFileUrl = String(propertyValue('allocation_attachment_url') || '').trim();
    if (storedFileUrl) lists.push({ fileUrl: storedFileUrl, url: storedFileUrl, fileName: String(propertyValue('allocation_attachment') || 'Anexo do registro'), mimeType: String(propertyValue('allocation_attachment_mime') || ''), notes: 'Arquivo original salvo na solicitação vinculada' });
    if (record.evidenceUri || record.comprovante) lists.push({ url: record.evidenceUri || record.comprovante, name: 'Comprovante do registro' });
    const seen = new Set<string>();
    return lists.map((item, index) => ({
      label: item.title || item.fileName || item.name || item.label || `Anexo ${index + 1}`,
      url: item.fileUrl || item.url || item.href || item.dataUrl || item.evidenceUri || item.path || '',
      meta: item.mimeType || item.type || item.notes || '',
    })).filter(item => {
      const key = `${String(item.label)}|${String(item.url)}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  };
  const stageRecordPropertiesV1 = (record: Record<string, unknown>): AtlasStageRecordPropertyV1[] => {
    if (Array.isArray(record.properties)) return recordList(record.properties)
      .filter(item => !['allocation_attachment_url', 'allocation_attachment_mime'].includes(String(item.id || '')))
      .map((item, index) => ({ label: item.label || item.name || item.id || `Propriedade ${index + 1}`, value: item.value ?? item.text ?? item.description ?? '—' }))
      .filter((item: AtlasStageRecordPropertyV1) => String(item.value ?? '').trim());
    const properties = asRecord(record.properties);
    if (properties) return Object.entries(properties).map(([label, value]) => ({ label, value: Array.isArray(value) ? value.join(' · ') : value }));
    return [];
  };
  const stageRecordStatusLabelV1 = (record: Record<string, unknown>): unknown => record.status || record.situacao || record.state || 'Pendente';
  const stageRecordProgressV1 = (stage: AtlasStageRecordStageV1, state: Record<string, unknown>): number => {
    const live = typeof stageV9LiveFor === 'function' ? stageV9LiveFor(stage) || {} : {};
    const operationalState = asRecord(state.operationalState);
    const operational = recordList(operationalState?.stages).find(item => item.key === stage.key);
    return Number(operational?.progress ?? live.progress ?? stage?.progress ?? 0) || 0;
  };
  const stageRecordMaterialRowsV1 = (state: Record<string, unknown>): AtlasStageRecordRowV1[] => typeof controlCenterMaterialRowsV1 === 'function' ? controlCenterMaterialRowsV1(state) : [];
  const stageRecordServiceRowsV1 = (state: Record<string, unknown>): AtlasStageRecordRowV1[] => stageRecordStagesV1().flatMap(stage => {
    const records = recordList(state.records);
    return records.filter(record => {
      const target = record.allocationTarget || recordList(record.properties).find(property => property.id === 'allocation_target')?.value;
      return Boolean(isAssistantVisualAdditionV1(record)) && String(target || '').toLocaleLowerCase('pt-BR').includes('serv') && stageRecordStageForV1(record, [stage]) === stage;
    }).map(record => ({
      id: `record:${record.id}`,
      recordId: record.id,
      stageKey: stage.key,
      stageName: stage.name,
      name: record.activityName || record.atividade || record.activity || 'Serviço lido no chat',
      detail: record.detalhes || 'Registro visual alocado pelo assistente.',
      trigger: 'Leitura OCR do assistente · revisão humana',
      unit: record.unit || (asRecord(stage.production)?.unit) || 'registro',
      responsible: record.responsavel || 'Assistente operacional',
      progress: Number(record.progresso || 0),
      status: record.status || 'Pendente',
      properties: record.properties || [],
      attachments: stageRecordAttachmentsV1(record),
    }));
  });
  const stageRecordEstimateNameKeyV1 = (value: unknown): string => stageRecordNormalizeV1(value).replace(/\b\d+(?:[.,]\d+)?\b/g, ' ').split(/\s+/).map(token => token.replace(/s$/, '')).filter(token => token.length > 2).join(' ');
  const stageRecordEstimateMatchesV1 = (left: unknown, right: unknown): boolean => {
    const a = stageRecordEstimateNameKeyV1(left), b = stageRecordEstimateNameKeyV1(right);
    return Boolean(a && b && (a === b || a.includes(b) || b.includes(a) || a.split(' ').some(token => b.split(' ').includes(token))));
  };
  const stageRecordEstimateKindV1 = (item: Record<string, unknown>): AtlasStageRecordEstimateKindV1 => /equip\.?|maquin|p[aá]\s*carreg|escav|patrol|pipa|rolo|compactador|ca[cç]amba|caminh[aã]o|retro|trator|gerador|bomba|betoneira|h(?:ora|\b)/i.test(`${item.name || ''} ${item.scope || ''} ${item.unit || ''}`) ? 'equipment' : 'material';
  const stageRecordEstimateNumberV1 = (value: unknown): number | null => {
    if (value == null || value === '') return null;
    const number = Number(String(value).replace(/\./g, '').replace(',', '.'));
    return Number.isFinite(number) ? number : null;
  };
  const stageRecordEstimateFormatV1 = (value: number | null): string => value == null ? 'A dimensionar' : new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 2 }).format(value);
  return { stageRecordNormalizeV1, stageRecordStagesV1, stageRecordStageForV1, stageRecordAttachmentsV1, stageRecordPropertiesV1, stageRecordStatusLabelV1, stageRecordProgressV1, stageRecordMaterialRowsV1, stageRecordServiceRowsV1, stageRecordEstimateNameKeyV1, stageRecordEstimateMatchesV1, stageRecordEstimateKindV1, stageRecordEstimateNumberV1, stageRecordEstimateFormatV1 };
}

