/** Own the OCR endpoint contract so record forms only handle file selection and review. */
export async function requestAtlasRecordOcrV1(input: {
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
  request: AtlasRecordOcrRequestV1;
}): Promise<AtlasRecordOcrPayloadV1> {
  const response = await input.apiFetch('/api/records/ocr', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input.request),
  });
  const value = await response.json().catch(() => ({}));
  const payload: AtlasRecordOcrPayloadV1 = value && typeof value === 'object' && !Array.isArray(value)
    ? value as AtlasRecordOcrPayloadV1
    : {};
  if (!response.ok) throw new Error(payload.error || `HTTP ${response.status}`);
  return payload;
}

