/** Project edited OCR review controls into the existing operational-record properties DTO. */
export function projectAtlasRecordOcrReviewPropertiesV1(input: {
  result: AtlasRecordOcrPayloadV1;
  fields: readonly AtlasRecordOcrReviewFieldInputV1[];
  items: readonly AtlasRecordOcrReviewItemInputV1[];
}): AtlasRecordOcrSerializedPropertyV1[] {
  const provider = String(input.result.provider || 'image-ocr');
  const properties: AtlasRecordOcrSerializedPropertyV1[] = input.fields.map(field => {
    const type = field.type || 'text';
    let value: string | number = field.value;
    if (type === 'currency') value = Math.round(Number(value || 0) * 100);
    else if (type === 'number') value = Number(value || 0);
    const key = field.key || '';
    return {
      key,
      label: field.label || key,
      type,
      value,
      source: provider,
      confidence: Number(input.result.properties?.find(item => item.key === key)?.confidence || 0),
    };
  });
  const items = input.items.map(item => ({
    itemKind: String(item.itemKind || '').trim(),
    stageName: String(item.stageName || '').trim(),
    activityName: String(item.activityName || '').trim(),
    materialName: String(item.materialName || '').trim(),
    materialId: String(item.materialId || '').trim(),
    description: String(item.description || '').trim(),
    quantity: Number(item.quantity || 0),
    unit: String(item.unit || '').trim(),
    unitPriceCents: Math.round(Number(item.unitPriceCents || 0) * 100),
    totalPriceCents: Math.round(Number(item.totalPriceCents || 0) * 100),
  }));
  if (items.length) properties.push({
    key: 'items',
    label: 'Itens',
    type: 'items',
    value: items,
    source: provider,
    confidence: Number(input.result.confidence || 0),
  });
  return properties;
}

export interface AtlasRecordOcrDynamicStageV1 {
  key: string;
  name: string;
  description: string;
  activityHints: string[];
  activities: Array<{ id: string; name: string; description: string; materials: string[] }>;
  unit: string;
  materials: string[];
}
const atlasRecordOcrStageOptionsV1 = (stages: readonly AtlasRecordOcrStageOptionV1[]): AtlasRecordOcrStageOptionV1[] => {
  const options = stages.map(stage => ({ key: String(stage.key || ''), name: String(stage.name || '') }))
    .filter(stage => stage.key && stage.name);
  const known = new Set(options.flatMap(stage => [stage.key.toLocaleLowerCase('pt-BR'), stage.name.toLocaleLowerCase('pt-BR')]));
  const destinations = (stageDestinationsCatalogData as { destinations?: AtlasRecordOcrStageOptionV1[] }).destinations || [];
  for (const destination of destinations) {
    const key = String(destination.key || ''), name = String(destination.name || '');
    if (!key || !name || known.has(key.toLocaleLowerCase('pt-BR')) || known.has(name.toLocaleLowerCase('pt-BR'))) continue;
    options.push({ key, name });
    known.add(key.toLocaleLowerCase('pt-BR'));
    known.add(name.toLocaleLowerCase('pt-BR'));
  }
  return options;
};
export interface AtlasRecordOcrDynamicBridgeV1 {
  apiFetch: AtlasLotDetailProgramCommandsInputV1['apiFetch'];
  operationalHeaders: AtlasLotDetailProgramCommandsInputV1['operationalHeaders'];
  appStore: AtlasLotDetailProgramCommandsInputV1['appStore'] & { subscribe(listener: (state: Record<string, unknown>) => void): () => void };
  stages: AtlasRecordOcrDynamicStageV1[];
}

/** Publish the live stage vocabulary and API ports consumed by chat/OCR inference. */
export function installAtlasRecordOcrDynamicBridgeV1(input: {
  host: typeof globalThis & { __BELAVISTA_RECORD_OCR_BRIDGE_V21?: AtlasRecordOcrDynamicBridgeV1 };
  apiFetch: AtlasLotDetailProgramCommandsInputV1['apiFetch'];
  operationalHeaders: AtlasLotDetailProgramCommandsInputV1['operationalHeaders'];
  appStore: AtlasRecordOcrDynamicBridgeV1['appStore'];
  executionModel: { stages?: AtlasStageRecordStageV1[] };
  stageProfileSettingsFor(stageKey: string): unknown;
}): AtlasRecordOcrDynamicBridgeV1 {
  const { host, apiFetch, operationalHeaders, appStore, executionModel, stageProfileSettingsFor } = input;
  if (!host || !appStore?.get || !Array.isArray(executionModel?.stages))
    throw new TypeError('Record OCR bridge requires the live app store and execution model.');
  const labels = (value: unknown): string[] => (Array.isArray(value) ? value : [])
    .map(item => typeof item === 'string'
      ? item
      : item && typeof item === 'object'
        ? [Reflect.get(item, 'name'), Reflect.get(item, 'title'), Reflect.get(item, 'description')].filter(Boolean).join(': ')
        : '')
    .filter(Boolean)
    .slice(0, 20);
  const destinationStages = ((stageDestinationsCatalogData as { destinations?: Array<AtlasRecordOcrStageOptionV1 & { description?: string }> }).destinations || [])
    .map(stage => ({
      key: stage.key,
      name: stage.name,
      description: stage.description || '',
      activities: [],
      materials: [],
      production: { unit: 'registro administrativo' },
      executionProfile: {
        requestHints: ['Destino administrativo para nota, serviço interno ou lançamento de repasse.'],
        evidenceFocus: ['Identificar documento, responsável e finalidade administrativa.'],
        materialsTable: [],
      },
    }));
  const stages = [...executionModel.stages, ...destinationStages]
    .map(stage => {
      const settings = stageProfileSettingsFor(stage.key);
      const profile = {
        ...(stage.executionProfile && typeof stage.executionProfile === 'object' ? stage.executionProfile : {}),
        ...(settings && typeof settings === 'object' ? settings : {}),
      } as Record<string, any>;
      const activityHints = [
        ...labels(profile.requestHints),
        ...labels(profile.expectedActivities),
        ...labels(profile.evidenceFocus),
      ].slice(0, 20);
      const workbenchStage = WORKER_STAGE_WORKBENCH_CATALOG_V1.find(item => item.key === String(stage.key || ''));
      const activitySource = Array.isArray(stage.activities) && stage.activities.length
        ? stage.activities
        : workbenchStage?.activities || [];
      const activities = activitySource.slice(0, 24).map((activity: any) => ({
        id: String(activity?.id || activity?.key || ''),
        name: String(activity?.name || activity?.title || '').slice(0, 180),
        description: String(activity?.description || activity?.details || activity?.operational?.description || '').slice(0, 360),
        materials: labels(activity?.materials).slice(0, 16),
      })).filter(activity => activity.name || activity.description);
      const materialSource = Array.isArray(profile.materialsTable) && profile.materialsTable.length
        ? profile.materialsTable : stage.materials;
      const materials = [...new Set([
        ...labels(materialSource),
        ...activities.flatMap(activity => activity.materials),
      ])].slice(0, 30);
      return {
        key: String(stage.key || ''),
        name: String(stage.name || ''),
        description: String(stage.description || profile.typicalDescription || profile.executionDescription || '').slice(0, 900),
        activityHints,
        activities,
        unit: String((stage.production as Record<string, unknown> | undefined)?.unit || ''),
        materials,
      };
    })
    .filter(stage => stage.key && stage.name);
  const bridge: AtlasRecordOcrDynamicBridgeV1 = { apiFetch, operationalHeaders, appStore, stages };
  host.__BELAVISTA_RECORD_OCR_BRIDGE_V21 = bridge;
  return bridge;
}

