/** Apply stage-record workspace actions to the shared operational state. */
export function applyAtlasStageRecordCenterActionV1(input: {
  action: AtlasStageRecordCenterActionV1;
  appStore: AtlasApplicationStore<AtlasApplicationInitialState>;
}): void {
  const { action, appStore } = input;
  switch (action.kind) {
    case 'open-item':
      appStore.set({ controlStageCenterItemModalKey: action.key, lastAction: `Abriu as propriedades da adição ${action.key}` });
      return;
    case 'select-tab':
      appStore.set({ controlStageCenterTab: action.tab, controlStageRecordModalId: null, lastAction: `Abriu a aba ${action.label}` });
      return;
    case 'set-view-mode': {
      const field = action.section === 'materials' ? 'controlStageCenterMaterialMode' : 'controlStageCenterServiceMode';
      const section = action.section === 'materials' ? 'materiais' : 'serviços';
      appStore.set({ [field]: action.mode, lastAction: `Abriu ${action.mode === 'proofs' ? 'os comprovantes' : 'a tabela'} de ${section}` });
      return;
    }
    case 'open-record':
      appStore.set({ controlStageRecordModalId: action.recordId, lastAction: `Abriu as propriedades do registro ${action.recordId}` });
      return;
    case 'open-stage':
      appStore.set({
        view: 'stages', selectedStageV9: action.stageKey, selectedStage: action.stageKey, stageSelected: true,
        lastAction: `Abriu a etapa ${action.stageKey} pela Central operacional`,
      });
      return;
    case 'open-service-record':
      appStore.set({ controlStageCenterItemModalKey: `service:${action.recordId}`, lastAction: `Abriu as propriedades do serviço ${action.recordId}` });
      return;
    case 'close-record':
      appStore.set({ controlStageRecordModalId: null });
      return;
    case 'close-item':
      appStore.set({ controlStageCenterItemModalKey: null });
  }
}

/** Compose stage record services, record center, lot details and the live OCR bridge. */
export function installAtlasRecordApplicationCompositionV1(input: AtlasRecordApplicationCompositionInputV1): Readonly<
  ReturnType<typeof createAtlasStageRecordServicesV1>
  & ReturnType<typeof createAtlasStageMaterialReportViewV1>
  & AtlasStageRecordCenterOutputV1
  & {
    stageMaterialReportModelV1: ReturnType<typeof createAtlasStageMaterialReportModelV1>;
    recordOcrBridgeV1: ReturnType<typeof installAtlasRecordOcrDynamicBridgeV1>;
    recordOcrFormsOwnerV1: ReturnType<AtlasRecordApplicationCompositionInputV1['installRecordOcrFormsV1']>;
  }
> {
  const { host } = input;
  const stageRecordServicesV1 = createAtlasStageRecordServicesV1({ executionModel: input.executionModel, demoData: input.demoData, controlCenterMaterialRowsV1: input.controlCenterMaterialRowsV1, isAssistantVisualAdditionV1: input.isAssistantVisualAdditionV1, stageV9LiveFor: input.stageV9LiveFor });
  const stageMaterialReportModelV1 = createAtlasStageMaterialReportModelV1({
    normalize: stageRecordServicesV1.stageRecordNormalizeV1,
    attachments: stageRecordServicesV1.stageRecordAttachmentsV1,
  });
  const stageMaterialReportViewV1 = input.createStageMaterialReportView({
    model: stageMaterialReportModelV1,
    esc: input.esc as (value: unknown) => string,
    ico: input.ico as (name: string) => string,
    appStore: input.appStore,
    document: input.documentRef,
    window: input.windowRef,
  });
  const stageRecordCenterModulesV1 = input.installStageRecordCenter(input.ViewLayer as AtlasStageRecordViewLayerV1, {
    REPASSE_PRICE_CATALOG: input.REPASSE_PRICE_CATALOG, apiFetch: input.apiFetch,
    readState: () => input.appStore.get(),
    onAction: action => applyAtlasStageRecordCenterActionV1({ action, appStore: input.appStore }),
    defaultStageMaterialRows: input.defaultStageMaterialRows, demoData: input.demoData, esc: input.esc,
    formatBRL: input.formatBRL, ico: input.ico, isAssistantVisualAdditionV1: input.isAssistantVisualAdditionV1,
    operationalHeaders: input.operationalHeaders, notify: input.notify, renderStageHomePageV1: input.renderStageHomePageV1,
    stageContextV1: input.stageContextV1, stageHomeSnapshotV1: input.stageHomeSnapshotV1,
    stageMaterialReportDialogV1: stageMaterialReportViewV1.dialogMarkup,
    stageMaterialReportBindV1: stageMaterialReportViewV1.bind,
    ...stageRecordServicesV1, stageViewTabs: input.stageViewTabs, document: input.documentRef,
  });
  const lotDetailEventsInputV1: Omit<AtlasLotDetailProgramCommandsInputV1, 'ViewLayer'> = {
    REPASSE_PRICE_CATALOG: input.REPASSE_PRICE_CATALOG,
    apiFetch: input.apiFetch,
    appStore: input.appStore as unknown as AtlasLotDetailProgramCommandsInputV1['appStore'],
    commissionProfiles: input.commissionProfiles,
    downloadBrandedLotExcelV1: input.downloadBrandedLotExcelV1,
    formatBRL: input.formatBRL,
    esc: input.esc,
    ico: input.ico,
    notify: input.notify,
    operationalHeaders: input.operationalHeaders,
    prepareAssistantLotStatusPromptV1: input.prepareAssistantLotStatusPromptV1,
    host,
  };
  installAtlasLotDetailProgramCommandsV1({ ...lotDetailEventsInputV1, ViewLayer: input.ViewLayer as AtlasCommercialViewLayerConstructor });
  const recordOcrFormsOwnerV1 = input.installRecordOcrFormsV1({
    documentRef: input.documentRef,
    host,
    appStore: input.appStore,
    requestOcr: request => requestAtlasRecordOcrV1({ apiFetch: input.apiFetch, request }),
    stageOptions: atlasRecordOcrStageOptionsV1((input.executionModel.stages || []).map(stage => ({ key: String(stage.key || ''), name: String(stage.name || '') }))),
  });
  const recordOcrBridgeV1 = installAtlasRecordOcrDynamicBridgeV1({ host, apiFetch: input.apiFetch, operationalHeaders: input.operationalHeaders, appStore: input.appStore, executionModel: input.executionModel, stageProfileSettingsFor: input.stageProfileSettingsFor });
  return Object.freeze({ ...stageRecordServicesV1, stageMaterialReportModelV1, ...stageMaterialReportViewV1, ...stageRecordCenterModulesV1, recordOcrBridgeV1, recordOcrFormsOwnerV1 });
}

