  let activePublicMapSelection: PublicLeadChatSelection = {};
  const newPublicLeadChatSession = (): PublicLeadChatSession => createAtlasPublicLeadChatSessionV1();
  const readPublicLeadChatSession = (): PublicLeadChatSession => {
    try {
      const stored = JSON.parse(sessionStorage.getItem(publicChatSessionKey) || 'null');
      const value = stored && typeof stored === 'object' && !Array.isArray(stored) ? stored as Partial<PublicLeadChatSession> : {};
      const fallback = newPublicLeadChatSession();
      return { ...fallback, ...value, id: String(value.id || fallback.id) };
    } catch { return newPublicLeadChatSession(); }
  };
  const savePublicLeadChatSession = (session: PublicLeadChatSession): PublicLeadChatSession => {
    const next = { ...session, updatedAt: new Date().toISOString() };
    try { sessionStorage.setItem(publicChatSessionKey, JSON.stringify(next)); } catch {}
    return next;
  };
  const newPublicLeadChatMemory = (): PublicLeadChatMemory => createAtlasPublicLeadChatMemoryV1();
  const readPublicLeadChatMemory = (): PublicLeadChatMemory => {
    try {
      const parsed = JSON.parse(localStorage.getItem(publicChatMemoryKey) || 'null') as Partial<PublicLeadChatMemory> | null;
      if (!parsed || parsed.version !== 'v5.3.40' || !Array.isArray(parsed.turns) || Date.now() - Number(parsed.updatedAt || 0) > publicChatMemoryTtl) return newPublicLeadChatMemory();
      const turns = parsed.turns.filter((turn): turn is PublicLeadChatTurn => Boolean(turn && ['user', 'assistant'].includes(String(turn.role)) && String(turn.content || '').trim())).slice(-publicChatMemoryTurnLimit);
      return { version: 'v5.3.40', id: String(parsed.id || newPublicLeadChatMemory().id), createdAt: Number(parsed.createdAt) || Date.now(), updatedAt: Number(parsed.updatedAt) || Date.now(), turns };
    } catch { return newPublicLeadChatMemory(); }
  };
  const savePublicLeadChatMemory = (memory: PublicLeadChatMemory): PublicLeadChatMemory => {
    const next = { ...memory, updatedAt: Date.now(), turns: memory.turns.slice(-publicChatMemoryTurnLimit) };
    try { localStorage.setItem(publicChatMemoryKey, JSON.stringify(next)); } catch {}
    return next;
  };

  /** Advance the single route iterator, then mirror only its route fields to the legacy shell. */
  function navigateRoute(appStore: { get(): Record<string, unknown>; set(state: Record<string, unknown>): void }, patch: Partial<RouteState>, nonRouteState: Record<string, unknown> = {}): void {
    const raw = appStore.get();
    const current: RouteState = {
      view: String(raw.view || 'map'),
      ...(raw.selectedStageV9 != null ? { stageKey: String(raw.selectedStageV9) } : {}),
      ...(raw.selectedStage != null ? { stageId: String(raw.selectedStage) } : {}),
      ...(raw.selectedBrokerDirectoryId != null ? { brokerId: String(raw.selectedBrokerDirectoryId) } : {}),
      ...(raw.selectedSalesHistoryId != null ? { saleId: String(raw.selectedSalesHistoryId) } : {}),
      ...(raw.selectedDevelopmentProfileId != null ? { lotProfileId: String(raw.selectedDevelopmentProfileId) } : {}),
    };
    routeState.next({ type: 'sync', state: current });
    const next = routeState.next({ type: 'navigate', patch }).value;
    const stageId = next.stageId == null ? null : /^\d+$/.test(String(next.stageId)) ? Number(next.stageId) : String(next.stageId);
    // Shell flags may accompany navigation, but route fields always come from
    // the single route iterator. A caller cannot overwrite its yielded route.
    const shellOnly = { ...nonRouteState };
    for (const field of ['view', 'selectedStageV9', 'selectedStage', 'selectedBrokerDirectoryId', 'selectedSalesHistoryId', 'selectedDevelopmentProfileId']) delete shellOnly[field];
    appStore.set({
      view: next.view,
      ...(next.stageKey ? { selectedStageV9: next.stageKey } : {}),
      ...(stageId == null ? {} : { selectedStage: stageId }),
      ...(next.brokerId == null ? {} : { selectedBrokerDirectoryId: next.brokerId }),
      selectedSalesHistoryId: next.saleId ?? null,
      selectedDevelopmentProfileId: next.lotProfileId ?? null,
      ...shellOnly,
    });
  }

  /** Own the state and route effects for controls rendered by the final-workspace component binding. */
  function installFinalWorkspaceActionProgramV1(host: Document, appStore: AtlasSidebarRouteAppStore): void {
    if (finalWorkspaceEventHosts.has(host)) return;
    finalWorkspaceEventHosts.add(host);
    host.addEventListener('atlas:final-workspace-action', event => {
      const activeView = host.querySelector('view-layer');
      if (!activeView || event.target !== activeView) return;
      const detail = (event as CustomEvent<{ action?: unknown; value?: unknown }>).detail;
      const action = String(detail?.action || '');
      const value = typeof detail?.value === 'string' ? detail.value.trim() : '';
      switch (action) {
        case 'record-open':
          if (value) appStore.set({ selectedRecordV5362: value, lastAction: 'Abriu registro' });
          return;
        case 'record-back':
          appStore.set({ selectedRecordV5362: null, lastAction: 'Voltou ao Diário' });
          return;
        case 'activity-open':
          if (value) navigateRoute(appStore, { view: 'activities' }, { selectedActivity: value, activityDedicated: true, lastAction: 'Abriu atividade' });
          return;
        case 'commission-toggle': {
          const state = appStore.get();
          appStore.set({ dashboardCommissionOpenV5362: !Boolean(state.dashboardCommissionOpenV5362), dashboardCommissionBrokerV5362: null, lastAction: 'Comissões rápidas' });
          return;
        }
        case 'commission-close':
          appStore.set({ dashboardCommissionOpenV5362: false, dashboardCommissionBrokerV5362: null });
          return;
        case 'broker-open':
          if (value) appStore.set({ dashboardCommissionOpenV5362: true, dashboardCommissionBrokerV5362: value });
          return;
        case 'broker-back':
          appStore.set({ dashboardCommissionOpenV5362: true, dashboardCommissionBrokerV5362: null });
          return;
        case 'commission-open':
          if (value) navigateRoute(appStore, { view: 'commissions' }, { selectedCommissionProfile: value, lastAction: 'Abriu comissão' });
          return;
        case 'commission-correction':
          if (value) navigateRoute(appStore, { view: 'commissions' }, { commissionEditorOpen: true, commissionFilters: { query: '', status: 'all', profile: value }, lastAction: 'Abriu correção' });
          return;
      }
    });
  }

  function installLegacyRecordCommandsV1(input: AtlasSidebarRouteCompositionInput): void {
    const { host, appStore, apiFetch, notify } = input;
    if (legacyRecordEventHosts.has(host)) return;
    legacyRecordEventHosts.add(host);
    const operationalHeaders = createOperationalHeadersV1({ appStore });
    host.addEventListener('atlas:view-record-delete', event => {
      const detail = (event as CustomEvent<AtlasLegacyOperationalRecordDeleteCommandV1>).detail;
      const activeView = host.querySelector('view-layer');
      if (!detail || detail.element !== activeView || event.target !== activeView || String(appStore.get().view || '') !== 'records') return;
      void (async () => {
        try {
          const response = await apiFetch(`/api/records/${encodeURIComponent(detail.id)}`, {
            method: 'DELETE', headers: operationalHeaders(),
          });
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          const current = appStore.get();
          const records = Array.isArray(current.records) ? current.records as OperationalRecord[] : [];
          appStore.set({
            records: records.filter(record => String(record.id) !== detail.id),
            lastAction: 'Excluiu registro no banco',
          });
          notify('Registro excluído do banco operacional.', 'success');
        } catch (error) {
          notify('Não foi possível excluir o registro.', 'warning');
          globalThis.console.warn('Exclusão persistente indisponível.', error);
        }
      })();
    });
    host.addEventListener('atlas:view-record-save', event => {
      const detail = (event as CustomEvent<AtlasLegacyOperationalRecordSaveCommandV1>).detail;
      const activeView = host.querySelector('view-layer');
      if (!detail || detail.element !== activeView || event.target !== activeView || String(appStore.get().view || '') !== 'records') return;
      void (async () => {
        const value: Record<string, unknown> = { ...detail.values };
        const contextFields = detail.contextFields
          .map(field => `${field.label}: ${field.value}`)
          .filter(Boolean);
        const details = String(value.detalhes || '');
        if (contextFields.length) value.detalhes = [
          details,
          `Campos de ${detail.nature || 'execução'}:`,
          ...contextFields,
        ].filter(Boolean).join('\n');
        if (detail.attachments.length) {
          const summary = detail.attachments
            .map(file => `${file.name} (${file.type || 'documento'}, ${(file.size / 1024 / 1024).toFixed(2)} MB)`)
            .join(' · ');
          value.detalhes = [String(value.detalhes || ''), `Anexos: ${summary}`].filter(Boolean).join('\n');
          const image = detail.attachments.find(file => /^image\//i.test(file.type));
          if (image) {
            const dataUrl = await fileDataUrl(image).catch(() => '');
            const base64 = dataUrl.split(',')[1] || '';
            if (base64) value.evidence = {
              kind: 'upload',
              fileName: image.name,
              mimeType: image.type || 'image/jpeg',
              imageBase64: base64,
            };
          }
        }
        try {
          const path = detail.editingId
            ? `/api/records/${encodeURIComponent(detail.editingId)}`
            : '/api/records';
          const response = await apiFetch(path, {
            method: detail.editingId ? 'PUT' : 'POST',
            headers: operationalHeaders({ 'Content-Type': 'application/json' }),
            body: JSON.stringify(value),
          });
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          const record = await response.json() as OperationalRecord;
          const current = appStore.get();
          const records = Array.isArray(current.records) ? current.records as OperationalRecord[] : [];
          appStore.set({
            records: detail.editingId
              ? records.map(item => String(item.id) === detail.editingId ? record : item)
              : [record, ...records],
            editingRecord: null,
            recordContext: null,
            recordCameraName: null,
            recordCameraPreview: null,
            lastAction: detail.editingId ? 'Atualizou registro no banco' : 'Criou registro no banco',
          });
          (detail.element as HTMLElement & { _recordCameraFile?: File | null })._recordCameraFile = null;
          notify('Registro salvo na camada operacional.', 'success');
        } catch (error) {
          notify('Serviço operacional indisponível; registro não confirmado.', 'warning');
          globalThis.console.warn('Persistência de registro indisponível.', error);
        }
      })();
    });
  }

  /** Resolve API origin for local, ngrok, deployed-web, or native Capacitor runtime. */
  function apiBase(): string {
    if (/\.ngrok-free\.dev$/i.test(location.hostname)) {
      const portPrefix = location.pathname.match(/^\/\d+(?=\/|$)/)?.[0] || '/8080';
      return location.origin + portPrefix;
    }
    if (runtime.BELAVISTA_CAPACITOR_NATIVE) {
      const base = String(runtime.BELAVISTA_API_BASE || '').replace(/\/$/, '');
      if (!base) throw new Error('API do aplicativo não configurada.');
      return base;
    }
    if (/^(localhost|127\.0\.0\.1)$/i.test(location.hostname)) return '';
    const base = String(runtime.BELAVISTA_API_BASE ||
      document.querySelector<HTMLMetaElement>('meta[name="belavista-api-base"]')?.content || '').replace(/\/$/, '');
    if (!base) throw new Error('API do aplicativo não configurada.');
    return base;
  }

  /** Join a service path to the configured API origin. */
  function apiUrl(path: string): string {
    if (path === '/api/public/lead-chat') {
      const workerBase = String(runtime.BELAVISTA_AI_BASE ||
        document.querySelector<HTMLMetaElement>('meta[name="belavista-ai-base"]')?.content ||
        document.querySelector<HTMLMetaElement>('meta[name="belavista-api-base"]')?.content ||
        runtime.BELAVISTA_API_BASE || '').replace(/\/$/, '');
      if (!workerBase) throw new Error('Worker Cloudflare não configurado para o atendimento público.');
      return workerBase + path;
    }
    // The local server owns the operational SQLite API, but administrative CRM
    // data is stored in the GitHub-backed Worker. Route these reads directly
    // to the already configured Worker origin (the same origin used for AI),
    // retaining the caller's Firebase bearer token and avoiding a fake local
    // repository path. Other localhost APIs remain same-origin.
    if ((path === '/api/admin/public-leads' || path === '/api/admin/public-lead-summary') && /^(localhost|127\.0\.0\.1)$/i.test(location.hostname)) {
      const workerBase = String(runtime.BELAVISTA_API_BASE ||
        document.querySelector<HTMLMetaElement>('meta[name="belavista-ai-base"]')?.content || '').replace(/\/$/, '');
      if (!workerBase) throw new Error('Worker não configurado para consultar leads do repositório.');
      return workerBase + path;
    }
    return apiBase() + path;
  }

  /** Public chat transport and persistence; the visual component owns only transient UI state. */
  function installPublicLeadRegistration(): void {
    if (runtime.__BELAVISTA_PUBLIC_LEAD_REGISTRATION_INSTALLED || typeof document === 'undefined') return;
    runtime.__BELAVISTA_PUBLIC_LEAD_REGISTRATION_INSTALLED = true;
    // Chat intent detection and modal opening are owned by AtlasPublicLeadChat;
    // this program handler only validates and persists the submitted lead.
    document.addEventListener('atlas:public-lead-registration-submit', event => {
      const detail = (event as CustomEvent<PublicLeadRegistrationCommandV1>).detail;
      if (!detail?.element || !detail.context) return;
      void (async () => {
        const validation = validatePublicLeadRegistration(detail.fields);
        if (!validation.ok) {
          detail.element.dispatchEvent(new CustomEvent('atlas:public-lead-registration-result', { detail: { ok: false, stage: 'validation', error: validation.error } satisfies PublicLeadRegistrationResponse }));
          return;
        }
        const selection = detail.context.selection || {}, lotKey = String(selection.selectedLotId || selection.selectedLot || 'sem-lote');
        if (hasPublicLeadRegistration({ selectedLot: selection.selectedLot, selectedLotId: selection.selectedLotId })) {
          detail.element.dispatchEvent(new CustomEvent('atlas:public-lead-registration-result', { detail: { ok: false, stage: 'validation', error: publicLeadFormPolicyCatalog.registration.messages.alreadyRegistered } satisfies PublicLeadRegistrationResponse }));
          return;
        }
        try {
          const configured = document.querySelector<HTMLMetaElement>('meta[name="belavista-api-base"]')?.content?.trim() || document.querySelector<HTMLMetaElement>('meta[name="belavista-ai-base"]')?.content?.trim() || '';
          const endpoint = new URL('/api/public/lead-register', configured || location.origin).href;
          const submission = publicLeadFormPolicyCatalog.registration.submission;
          const requestBody: PublicLeadRegistrationApiRequestV1 = {
            schema: submission.schema,
            name: validation.name,
            whatsapp: validation.whatsapp,
            instagramHandle: validation.instagramHandle || '',
            document: { type: validation.documentType, value: validation.documentValue },
            consent: true,
            lot: { ...selection },
            intent: { message: String(detail.context.message || '').slice(0, submission.maximumIntentCharacters), detectedAt: new Date().toISOString() },
            conversation: { id: String(detail.context.memory?.id || ''), history: Array.isArray(detail.context.memory?.turns) ? detail.context.memory.turns.slice(-submission.conversationTurns) : [] },
            page: { href: location.href, source: submission.pageSource },
          };
          const response = await fetch(endpoint, {
            method: 'POST', mode: 'cors', headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
            body: JSON.stringify(requestBody),
          });
          const raw = await response.text(); let payload: PublicLeadRegistrationApiResponseV1 = {};
          try { payload = raw ? JSON.parse(raw) as PublicLeadRegistrationApiResponseV1 : {}; } catch { /* Report the HTTP response below. */ }
          if (!response.ok || payload.ok !== true) throw new Error(String(payload.error || `HTTP ${response.status}`));
          const leadId = String(payload.leadId || '');
          if (typeof sessionStorage !== 'undefined') {
            try { const key = publicLeadFormPolicyCatalog.registration.sessionStorageKey; const entries = JSON.parse(sessionStorage.getItem(key) || '{}') as Record<string, unknown>; entries[lotKey] = { leadId, at: Date.now() }; sessionStorage.setItem(key, JSON.stringify(entries)); } catch { /* Registration success must not depend on local storage. */ }
          }
          const realtime = payload.realtime && typeof payload.realtime === 'object' ? payload.realtime as { published?: boolean } : undefined;
          detail.element.dispatchEvent(new CustomEvent('atlas:public-lead-registration-result', { detail: { ok: true, leadId, realtime } satisfies PublicLeadRegistrationResponse }));
        } catch (error) {
          detail.element.dispatchEvent(new CustomEvent('atlas:public-lead-registration-result', { detail: { ok: false, stage: 'service', error: error instanceof Error ? error.message : String(error) } satisfies PublicLeadRegistrationResponse }));
        }
      })();
    });
  }

  /** Persist the reservation form through the canonical commercial-sales API. */
  function installPublicReservationApplication(apiFetch: (path: string, init?: RequestInit) => Promise<Response>): void {
    const appRuntime = runtime as Runtime & { __BELAVISTA_PUBLIC_RESERVATION_APPLICATION_INSTALLED?: boolean };
    if (appRuntime.__BELAVISTA_PUBLIC_RESERVATION_APPLICATION_INSTALLED || typeof document === 'undefined') return;
    if (typeof apiFetch !== 'function') throw new TypeError('Reserva pública requer o serviço autenticado apiFetch.');
    appRuntime.__BELAVISTA_PUBLIC_RESERVATION_APPLICATION_INSTALLED = true;
    document.addEventListener('atlas:public-reservation-pix-request', event => {
      const detail = (event as CustomEvent<{ element: AtlasPublicReservationFlow; requestId: string }>).detail;
      if (!detail?.element || !(detail.element instanceof AtlasPublicReservationFlow)) return;
      let settings: Record<string, unknown> = {};
      try { settings = JSON.parse(localStorage.getItem(publicReservationPolicyCatalog.settingsStorageKey) || '{}') as Record<string, unknown>; } catch {}
      const payment = createAtlasPublicReservationPixPaymentV1(settings);
      detail.element.dispatchEvent(new CustomEvent('atlas:public-reservation-pix-result', {
        detail: { requestId: detail.requestId, ok: Boolean(payment), reason: payment ? undefined : 'pix-key-missing', payment: payment || undefined },
      }));
    });
    document.addEventListener('atlas:public-reservation-submit', event => {
      const detail = (event as CustomEvent<AtlasPublicReservationSubmitDetailV1>).detail;
      if (!detail?.element || !(detail.element instanceof AtlasPublicReservationFlow)) return;
      void (async () => {
        try {
          const files = Object.entries(detail.files) as [AtlasPublicReservationFileKindV1, File | null][];
          const attachments = await Promise.all(files.filter((entry): entry is [AtlasPublicReservationFileKindV1, File] => Boolean(entry[1])).map(async ([kind, file]): Promise<PublicReservationAttachmentPayloadV1> => ({
            fileName: file.name,
            kind,
            dataUrl: await fileDataUrl(file),
          })));
          let settings: Record<string, unknown> = {};
          try { settings = JSON.parse(localStorage.getItem(publicReservationPolicyCatalog.settingsStorageKey) || '{}') as Record<string, unknown>; } catch {}
          const sale = buildAtlasPublicReservationSalePayloadV1({ data: detail.data, attachments, signalAmount: settings.signalAmount });
          const response = await apiFetch('/api/commercial-sales', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(sale),
          });
          if (!response.ok) throw new Error('O serviço seguro de reservas está indisponível. Tente novamente em instantes.');
          const payload = await response.json() as { sale?: { id?: unknown } };
          detail.element.dispatchEvent(new CustomEvent('atlas:public-reservation-result', { detail: { requestId: detail.requestId, ok: true, reservationId: payload.sale?.id } }));
        } catch (error) {
          console.info('Serviço local de reservas indisponível.', error);
          detail.element.dispatchEvent(new CustomEvent('atlas:public-reservation-result', { detail: { requestId: detail.requestId, ok: false, error: 'O serviço seguro de reservas está indisponível. Tente novamente em instantes.' } }));
        }
      })();
    });
  }

  function installPublicLeadApplication(uploadFiles?: PublicLeadFileUploader): void {
    if (runtime.__BELAVISTA_PUBLIC_LEAD_APPLICATION_INSTALLED || typeof document === 'undefined') return;
    runtime.__BELAVISTA_PUBLIC_LEAD_APPLICATION_INSTALLED = true;
    installPublicLeadChat(uploadFiles);
    installPublicLeadRegistration();
    installPublicLeadMapScene();
    installAtlasPublicMapTextureQualityV1({ project: projectPublicMapTextureQualityV1 });

    if (typeof window !== 'undefined') {
      window.addEventListener('DOMContentLoaded', () => {
        (globalThis as typeof globalThis & { lucide?: { createIcons?: () => void } }).lucide?.createIcons?.();
      });
    }

    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator) || location.protocol === 'file:') return;
    void (async () => {
      try {
        const registration = await navigator.serviceWorker.register(
          './lead-sw.js?v=asset-stream-v184-ts-main-public-entry-v1&ts-public-map-scene-registration-v2&ts-map-lot-assets-298-v1',
          { updateViaCache: 'none' },
        );
        await registration.update();
      } catch (error) {
        console.info('Service Worker público não ativado.', error);
      }
    })();
  }

  /** Start the public DWG map through the same typed application program as the lead chat. */
  function installPublicLeadMapScene(): boolean {
    if (!document.body.classList.contains('public-leads-page')) return false;
    const surface = document.querySelector<AtlasPublicLeadsSurface>('public-leads-surface');
    const mapHost = surface?.querySelector<HTMLElement>('map-scene[data-public-map],map-scene[data-public-presentation]');
    if (!surface || !mapHost) return false;
    const installed = surface.initializePublicMapScene({
      mapHost,
      fetcher: (path, init) => fetch(apiUrl(path), init),
      mapServices: createAtlasPublicLeadsMapServicesV1(
        (path, init) => fetch(path, init),
        (path, init) => fetch(apiUrl(path), init),
      ),
    });
    if (installed) surface.dataset.publicMapBootstrapOwnerV1 = 'typescript';
    return installed;
  }

  function installPublicLeadChat(uploadFiles?: PublicLeadFileUploader): void {
    if (uploadFiles) publicLeadFileUploader = uploadFiles;
    runtime.belavistaPreparePublicLeadChatContext = preparePublicLeadChatContext;
    const restorePublicMapSelectionView = (map: PublicMapSelectionScenePort): void => {
      const surface = document.querySelector<HTMLElement & { restorePublicMapSelectionView?: (mapHost: HTMLElement) => boolean }>('public-leads-surface');
      if (surface?.restorePublicMapSelectionView?.(map)) return;
      runtime.belavistaRestorePublicMapSelectionView?.(map);
    };
    runtime.belavistaPublicChatSelection = {
      get(requestSelection) {
        const merged = { ...activePublicMapSelection, ...(requestSelection || {}) };
        const selectedLotData = merged.selectedLotData || null;
        const requestKind = String(merged.requestKind || '').trim();
        return {
          selectedLot: String(selectedLotData?.label || merged.selectedLot || '').trim(),
          selectedLotId: String(selectedLotData?.id || merged.selectedLotId || '').trim(),
          requestKind: ['availability', 'characteristics', 'conditions'].includes(requestKind) ? requestKind as PublicLeadChatRequestKind : '',
          selectedLotData,
        };
      },
    };
    runtime.belavistaPublicLeadSession = { read: readPublicLeadChatSession, save: savePublicLeadChatSession };
    runtime.belavistaPublicChatContext = {
      get: readPublicLeadChatMemory,
      save: savePublicLeadChatMemory,
      clear: () => savePublicLeadChatMemory(newPublicLeadChatMemory()),
    };
    runtime.belavistaExecutePublicLeadChatTurnV1 = input => executeAtlasPublicLeadChatTurnV1(input, {
      getSelection: requestSelection => runtime.belavistaPublicChatSelection?.get(requestSelection) || {},
      readMemory: readPublicLeadChatMemory,
      saveMemory: savePublicLeadChatMemory,
      saveSession: savePublicLeadChatSession,
    });
    runtime.belavistaPublicLeadConversation = async (payload: PublicLeadChatPayload): Promise<PublicLeadChatResult> => {
      const response = await fetch(apiUrl('/api/public/lead-chat'), {
        method: 'POST',
        cache: 'no-store',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const raw = await response.text();
      let data: unknown;
      try { data = raw ? JSON.parse(raw) as unknown : {}; }
      catch { throw new Error('O Worker de Leads respondeu fora do formato JSON.'); }
      if (!data || typeof data !== 'object' || Array.isArray(data))
        throw new Error('O Worker de Leads respondeu com um objeto inválido.');
      const result = data as PublicLeadChatResult;
      if (!response.ok) throw new Error(result.error || result.message || `Worker respondeu HTTP ${response.status}`);
      return result;
    };
    if (typeof document !== 'undefined') installAtlasPublicLeadChatEventControllerV1({
      host: document,
      readSession: readPublicLeadChatSession,
      getSelection: () => activePublicMapSelection,
      selectLot: detail => {
        activePublicMapSelection = publicLeadMapSelection(detail);
        return activePublicMapSelection;
      },
      clearSelection: () => { activePublicMapSelection = {}; },
      converse: payload => runtime.belavistaPublicLeadConversation!(payload),
      upload: async ({sessionId, files, scope}) => {
        if (!publicLeadFileUploader) throw new Error('Serviço de upload de documentos não iniciou.');
        return publicLeadFileUploader(sessionId, files, {scope});
      },
      clearMapSelection: (map, hideWidget) => {
        const scene = map as PublicMapSelectionScenePort;
        clearPublicMapSelection(scene, true, () => restorePublicMapSelectionView(scene), hideWidget);
      },
      projectMapAction: publicLeadMapAction,
    });
  }

  /** Authenticated uncached GET; keeps local PTA separate from the Worker session used by Leads. */
  async function readApi<T>(path: string): Promise<T> {
    await runtime.BELAVISTA_ADMIN_AUTH_READY;
    const workerLeadsRequest = (path === '/api/admin/public-leads' || path === '/api/admin/public-lead-summary') && /^(localhost|127\.0\.0\.1)$/i.test(location.hostname);
    const token = workerLeadsRequest
      ? await runtime.BELAVISTA_GET_WORKER_ID_TOKEN?.()
      : await runtime.BELAVISTA_GET_ID_TOKEN?.();
    if (!token) throw new Error('Autenticação necessária para consultar o histórico.');
    const requestUrl = apiUrl(path);
    const request = () => fetch(requestUrl, {
      cache: 'no-store',
      headers: { Authorization: 'Bearer ' + token },
    });
    let response = await request();
    if (response.status === 401 && workerLeadsRequest) {
      runtime.BELAVISTA_RESET_WORKER_SESSION?.();
      const refreshedToken = await runtime.BELAVISTA_GET_WORKER_ID_TOKEN?.();
      if (refreshedToken) response = await fetch(requestUrl, { cache: 'no-store', headers: { Authorization: 'Bearer ' + refreshedToken } });
    } else if (response.status === 401) runtime.BELAVISTA_ADMIN_AUTH_INVALIDATE?.();
    if (!response.ok) {
      const payload = await response.json().catch(() => null) as { error?: string } | null;
      throw new Error(payload?.error || 'Serviço indisponível (HTTP ' + response.status + ').');
    }
    return response.json() as Promise<T>;
  }

  /** Authenticated JSON PUT for backend replacement/upsert endpoints. */
  async function writeApi<T>(path: string, payload: unknown): Promise<T> {
    await runtime.BELAVISTA_ADMIN_AUTH_READY;
    const token = await runtime.BELAVISTA_GET_ID_TOKEN?.();
    if (!token) throw new Error('Autenticação necessária para atualizar a venda.');
    const response = await fetch(apiUrl(path), {
      method: 'PUT', cache: 'no-store',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (response.status === 401) runtime.BELAVISTA_ADMIN_AUTH_INVALIDATE?.();
    if (!response.ok) {
      const error = await response.json().catch(() => null) as { error?: string } | null;
      throw new Error(error?.error || 'Não foi possível salvar a venda (HTTP ' + response.status + ').');
    }
    return response.json() as Promise<T>;
  }

  /** Authenticated domain CRUD request with response and error validation. */
  async function mutateApi<T>(path: string, method: 'POST' | 'PUT' | 'DELETE', payload?: unknown): Promise<T> {
    await runtime.BELAVISTA_ADMIN_AUTH_READY;
    const token = await runtime.BELAVISTA_GET_ID_TOKEN?.();
    if (!token) throw new Error('Autenticação necessária para alterar materiais.');
    const response = await fetch(apiUrl(path), { method, cache: 'no-store', headers: {
      Authorization: 'Bearer ' + token, ...(payload === undefined ? {} : { 'Content-Type': 'application/json' }),
    }, ...(payload === undefined ? {} : { body: JSON.stringify(payload) }) });
    if (response.status === 401) runtime.BELAVISTA_ADMIN_AUTH_INVALIDATE?.();
    const result = await response.json().catch(() => null) as (T & { error?: string }) | null;
    if (!response.ok) throw new Error(result?.error || `Não foi possível alterar material (HTTP ${response.status}).`);
    if (!result) throw new Error('Resposta inválida ao salvar material.');
    return result;
  }

  const createOperationalRecord = createAtlasOperationalRecordServiceV1(
    payload => mutateApi<unknown>('/api/records', 'POST', payload),
  );

  /** Load persisted materials, stages, property schema, and agenda links concurrently. */
  async function reloadMaterials(): Promise<void> {
    const target=materialsElement;
    if(!target)return;
    const requestId=++materialsRequestId;
    try {
      const [materialPayload,stagePayload,columnPayload,agendaPayload,documentPayload]=await Promise.all([
        readApi<{materials:OperationalMaterial[]}>('/api/materials'),
        readApi<{stages:OperationalStage[]}>('/api/stages-admin'),
        readApi<{columns:MaterialCustomColumn[]}>('/api/materials/schema'),
        readApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events'),
        readApi<{documents:ProjectDocument[]}>('/api/project-documents'),
      ]);
      const configuredStages = stagePayload.stages as Array<OperationalStage & { hasAiConfig?: boolean }>;
      const aiConfigResults = await Promise.allSettled(configuredStages.filter(stage => stage.hasAiConfig).map(async stage => {
        const payload = await readApi<{ stage: OperationalStage & { aiConfig?: StageAIConfig | null } }>(`/api/stages-admin/${encodeURIComponent(String(stage.id))}`);
        return { stageId: stage.id, aiConfig: payload.stage?.aiConfig || null };
      }));
      const aiConfigByStage = new Map<number, StageAIConfig>();
      for (const result of aiConfigResults) if (result.status === 'fulfilled' && result.value.aiConfig) aiConfigByStage.set(result.value.stageId, result.value.aiConfig);
      const modelStages = materialsExecutionStages;
      const stageOperationalModel = materialsStageOperationalModel;
      const stageAiPreviews = Object.fromEntries(stagePayload.stages.map(stage => {
        const executionStage = modelStages.find(item => String(item.key || '') === String(stage.key || ''))
          || modelStages.find(item => normalizeMaterialsStageTokenV1(item.name) === normalizeMaterialsStageTokenV1(stage.name));
        const persistedConfig = aiConfigByStage.get(stage.id);
        const configuredProfile = executionStage && stageOperationalModel ? stageOperationalModel.stageV9ProfileFor(executionStage) : {};
        const profile = {
          ...configuredProfile,
          ...(persistedConfig?.executionProfile || {}),
          ...(persistedConfig ? { procurementFocus: persistedConfig.procurementFocus, requestHints: persistedConfig.requestHints } : {}),
        };
        const previewStage: AtlasMaterialsStageAiPreviewStageV1 = {
          id: stage.id,
          key: executionStage?.key || stage.key || String(stage.id),
          name: stage.name,
          week: stage.week || executionStage?.week,
          materials: executionStage?.materials || [],
          executionProfile: executionStage?.executionProfile || {},
        };
        const connectedItems = materialPayload.materials.filter(item => item.stageId === stage.id ||
          (!item.stageId && normalizeMaterialsStageTokenV1(item.stageName) === normalizeMaterialsStageTokenV1(stage.name)));
        const preview = projectAtlasMaterialsStageAiPreviewV1({
          stage: previewStage,
          connectedItems,
          agenda: agendaPayload.events,
          profile,
          flowPackets: executionStage && stageOperationalModel ? stageOperationalModel.stageV9FlowPackets(executionStage) : [],
        });
        return [String(stage.id), preview] as const;
      }));
      if(requestId===materialsRequestId&&target===materialsElement){materialsStages=stagePayload.stages;target.setData(materialPayload.materials,stagePayload.stages,columnPayload.columns,agendaPayload.events,documentPayload.documents,stageAiPreviews,Boolean(runtime.BELAVISTA_CAPACITOR_NATIVE));}
    } catch(error) {
      if(requestId===materialsRequestId&&target===materialsElement)target.setError(error instanceof Error?error.message:String(error));
    }
  }

  function agendaNotificationId(eventId: string): number {
    let hash=2166136261;
    for(const character of eventId)hash=Math.imul(hash^character.charCodeAt(0),16777619);
    return (hash>>>0)||1;
  }

  function agendaIsNative(): boolean {
    const platform=agendaRouteServices.capacitor?.getPlatform?.();
    return Boolean(agendaRouteServices.capacitor?.isNativePlatform?.() || platform&&platform!=='web');
  }

  async function loadAgendaNotifications(): Promise<AgendaLocalNotificationPlugin> {
    const loader=agendaRouteServices.loadLocalNotifications;
    if(!loader)throw new Error('O plugin de notificações locais não está instalado neste aplicativo.');
    return loader();
  }

  async function agendaNotificationPermission(plugin: AgendaLocalNotificationPlugin): Promise<boolean> {
    let permission=await plugin.checkPermissions?.();
    if(permission?.display!=='granted'&&plugin.requestPermissions)permission=await plugin.requestPermissions();
    return permission?.display==='granted';
  }

  async function cancelAgendaNotification(event: OperationalAgendaEvent, plugin?: AgendaLocalNotificationPlugin): Promise<void> {
    const notifications=plugin||await loadAgendaNotifications();
    await notifications.cancel({notifications:[{id:agendaNotificationId(event.id)}]});
  }

  async function scheduleAgendaNotification(event: OperationalAgendaEvent, plugin?: AgendaLocalNotificationPlugin): Promise<void> {
    const notifications=plugin||await loadAgendaNotifications(),offset=Math.max(0,Math.min(1440,Number(event.notificationOffsetMinutes??30)));
    const at=new Date(`${event.date}T${event.start||'08:00'}:00`);
    at.setMinutes(at.getMinutes()-offset);
    if(!Number.isFinite(at.getTime())||at.getTime()<=Date.now()){
      await cancelAgendaNotification(event,notifications);
      return;
    }
    const requirement=event.requirements?.[0];
    await notifications.schedule({notifications:[{id:agendaNotificationId(event.id),title:event.title,body:[event.stageName,event.owner,requirement].filter(Boolean).join(' · '),schedule:{at},extra:{agendaEventId:event.id}}]});
  }

  async function syncAgendaNotification(event: OperationalAgendaEvent, plugin?: AgendaLocalNotificationPlugin): Promise<void> {
    if(!agendaIsNative())return;
    const notifications=plugin||await loadAgendaNotifications(),status=[event.status,event.customStatus].filter(Boolean).join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
    if(!Boolean(agendaRouteStore?.get().agendaMobileNotificationsEnabled)||/conclu|anulad|cancel/.test(status)){
      await cancelAgendaNotification(event,notifications);
      return;
    }
    await scheduleAgendaNotification(event,notifications);
  }

  async function setAgendaNotificationsEnabled(enabled: boolean, appStore: {get():Record<string,unknown>;set(state:Record<string,unknown>):void}): Promise<void> {
    if(enabled){
      if(agendaIsNative()){
        const notifications=await loadAgendaNotifications();
        if(!await agendaNotificationPermission(notifications))throw new Error('Permissão de notificações recusada no aparelho.');
        appStore.set({...appStore.get(),agendaMobileNotificationsEnabled:true,lastAction:'Ativou lembretes da agenda'});
        agendaElement?.setNotificationsEnabled(true);
      await Promise.all(agendaEvents.map(event=>syncAgendaNotification(event,notifications)));
      }else{
        const request=agendaRouteServices.NotificationCtor?.requestPermission;
        if(!request)throw new Error('Este navegador não oferece notificações. No APK elas são programadas no aparelho.');
        if(await request.call(agendaRouteServices.NotificationCtor)!=='granted')throw new Error('Permissão de notificações recusada no navegador.');
        appStore.set({...appStore.get(),agendaMobileNotificationsEnabled:true,lastAction:'Ativou permissão de lembretes da agenda'});
        agendaElement?.setNotificationsEnabled(true);
        agendaRouteServices.notify?.('Permissão concedida. O navegador não agenda avisos locais; no APK os lembretes são programados no aparelho.','info');
      }
    }else{
      appStore.set({...appStore.get(),agendaMobileNotificationsEnabled:false,lastAction:'Desativou lembretes da agenda'});
      agendaElement?.setNotificationsEnabled(false);
      if(agendaIsNative()){
        const notifications=await loadAgendaNotifications();
        await Promise.all(agendaEvents.map(event=>cancelAgendaNotification(event,notifications)));
      }
    }
  }

  async function mergeLegacyAgendaMetadata(events: OperationalAgendaEvent[]): Promise<OperationalAgendaEvent[]> {
    if(agendaLegacyMetadataMerged)return events;
    const typedSnapshot=readAgendaCalendarSnapshotV3(agendaRouteStore?.get()||{});
    const legacySource=typedSnapshot.events.length?typedSnapshot.events:agendaRouteServices.readLegacyEvents?.();
    const candidate=Array.isArray(legacySource)?legacySource:legacySource&&typeof legacySource==='object'&&'events' in legacySource?(legacySource as {events?:unknown}).events:[];
    if(!Array.isArray(candidate)){agendaLegacyMetadataMerged=true;return events;}
    type LegacyAgendaMetadataEvent = Omit<OperationalAgendaEvent, 'requirements' | 'materials'> & { requirements?: unknown; materials?: unknown };
    const legacyById=new Map((candidate as LegacyAgendaMetadataEvent[]).filter(item=>item&&item.id).map(item=>[String(item.id),item]));
    let changed=false;
    const merged=events.map(event=>{
      const legacy=legacyById.get(event.id);
      if(!legacy)return event;
      const next={...event} as OperationalAgendaEvent;
      const listKeys=['requirements','materials'] as const;
      for(const key of listKeys){const oldValue=legacy[key],oldList=Array.isArray(oldValue)?oldValue.map(String):typeof oldValue==='string'?oldValue.split(/\r?\n/).map(item=>item.trim()).filter(Boolean):[];if(oldList.length&&(!Array.isArray(next[key])||!next[key]!.length)){next[key]=oldList;changed=true;}}
      for(const key of ['customStatus','cancellationReason','cancelledAt'] as const){const oldValue=legacy[key];if(oldValue&&!next[key]){next[key]=oldValue;changed=true;}}
      if(legacy.cancellationConfirmed&&!next.cancellationConfirmed){next.cancellationConfirmed=true;changed=true;}
      if(Number.isFinite(Number(legacy.notificationOffsetMinutes))&&Number(legacy.notificationOffsetMinutes)!==30&&(next.notificationOffsetMinutes==null||next.notificationOffsetMinutes===30)){next.notificationOffsetMinutes=Number(legacy.notificationOffsetMinutes);changed=true;}
      return next;
    });
    if(!changed){agendaLegacyMetadataMerged=true;return events;}
    const saved=await writeApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events',{events:merged});
    if(!Array.isArray(saved.events))throw new Error('A agenda não confirmou a importação dos detalhes locais antigos.');
    agendaLegacyMetadataMerged=true;
    return saved.events;
  }

  /** Load canonical agenda events plus real stage/material context; discard stale reads. */
  async function reloadAgenda(focus: { date?: string; eventId?: string; week?: string; detailMode?: boolean } = {}): Promise<boolean> {
    const target=agendaElement;
    if(!target)return false;
    const requestId=++agendaRequestId;
    try{
      const demoActor = (agendaRouteStore?.get().currentActor || (runtime as unknown as { BELAVISTA_ADMIN_ACTOR?: unknown }).BELAVISTA_ADMIN_ACTOR || {}) as Record<string, unknown>;
      if(demoActor.mode === 'desktop-demo'){
        const snapshot=createAtlasLocalDemoDashboardSnapshotV1({});
        demoAgendaEvents ??= snapshot.agendaEvents;
        agendaEvents=demoAgendaEvents;
        agendaStages=snapshot.stages;
        const route=agendaRouteStore?.get()||{};
        target.setData(agendaEvents,agendaStages,snapshot.materials,focus.date||String(route.agendaFocusedDateV1||''),focus.eventId||String(route.agendaFocusedEventId||route.selectedAgendaEventV3||''),focus.week||String(route.agendaCalendarWeekV8||''),focus.detailMode??route.view==='agenda-detail',false);
        return true;
      }
      demoAgendaEvents=null;
      const [agenda,stages,materials]=await Promise.all([
        readApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events'),
        readApi<{stages:OperationalStage[]}>('/api/stages-admin'),
        readApi<{materials:OperationalMaterial[]}>('/api/materials'),
      ]);
      if(requestId!==agendaRequestId||target!==agendaElement)return false;
      const events=await mergeLegacyAgendaMetadata(agenda.events);
      if(requestId!==agendaRequestId||target!==agendaElement)return false;
      agendaEvents=events;
      agendaStages=stages.stages;
      const route=agendaRouteStore?.get()||{},notificationsEnabled=Boolean(route.agendaMobileNotificationsEnabled),detailMode=focus.detailMode??route.view==='agenda-detail';
      target.setData(events,stages.stages,materials.materials,focus.date||String(route.agendaFocusedDateV1||''),focus.eventId||String(route.agendaFocusedEventId||route.selectedAgendaEventV3||''),focus.week||String(route.agendaCalendarWeekV8||''),detailMode,notificationsEnabled);
      if(notificationsEnabled&&agendaIsNative()&&!agendaNotificationsRescheduled){
        agendaNotificationsRescheduled=true;
        try{const plugin=await loadAgendaNotifications(),permission=await plugin.checkPermissions?.();if(permission?.display==='granted')await Promise.all(events.map(event=>syncAgendaNotification(event,plugin)));}
        catch(error){agendaRouteServices.notify?.(`Lembretes da agenda não foram reprogramados: ${error instanceof Error?error.message:String(error)}`,'warning');}
      }
      return true;
    }catch(error){if(requestId===agendaRequestId&&target===agendaElement)target.setError(error instanceof Error?error.message:String(error));return false;}
  }

  /** Persist a canonical agenda DTO, then reload its authoritative server snapshot. */
  async function persistAgendaEvent(element:AtlasAgenda,payload:OperationalAgendaEvent,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    if(element!==agendaElement)return;
    try{
      await enqueueAgendaMutation(async()=>{
        const actor=(appStore.get().currentActor||(runtime as unknown as { BELAVISTA_ADMIN_ACTOR?: unknown }).BELAVISTA_ADMIN_ACTOR||{}) as Record<string, unknown>;
        if(actor.mode==='desktop-demo'){
          const previous=agendaEvents.find(item=>item.id===payload.id),next={...previous,...payload};
          demoAgendaEvents=previous?agendaEvents.map(item=>item.id===next.id?next:item):[...agendaEvents,next];
          appStore.set({operationalAgenda:demoAgendaEvents,agendaDatabaseEventsV3:demoAgendaEvents,agendaCalendarLoadedV3:true,lastAction:`Atualizou compromisso ${next.title}`});
          element.closeEditor();
          await reloadAgenda();
          return;
        }
        const latest=await readApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events');
        if(!Array.isArray(latest.events))throw new Error('O serviço não retornou o snapshot atual da agenda.');
        const previous=latest.events.find(item=>item.id===payload.id),next={...previous,...payload};
        const events=previous?latest.events.map(item=>item.id===next.id?next:item):[...latest.events,next];
         const saved=await writeApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events',{events});
         if(!Array.isArray(saved.events))throw new Error('A agenda não confirmou o snapshot salvo.');
         agendaEvents=saved.events;
         const savedEvent=saved.events.find(item=>item.id===next.id);
          if(savedEvent)try{await syncAgendaNotification(savedEvent);}catch(error){agendaRouteServices.notify?.(`Compromisso salvo; lembrete não programado: ${error instanceof Error?error.message:String(error)}`,'warning');}
          appStore.set({...appStore.get(),operationalAgenda:saved.events,agendaDatabaseEventsV3:saved.events,agendaCalendarLoadedV3:true,lastAction:`Atualizou compromisso ${next.title}`});
          element.closeEditor();
          await reloadAgenda();
       });
     }catch(error){element.setError(error instanceof Error?error.message:String(error));}
  }

  /** Validate a raw form draft against the currently loaded canonical resources before persistence. */
  async function saveAgendaDraft(event:CustomEvent<AtlasAgendaFormDraftCommandV1>,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    const detail=event.detail;
    if(!detail||detail.element!==agendaElement)return;
    const draft=buildAtlasAgendaEventPayloadV1({
      values:detail.values,
      stages:agendaStages,
      existingEvents:agendaEvents,
      createId:()=>`agenda-${crypto.randomUUID()}`,
      nowIso:()=>new Date().toISOString(),
    });
    if(!draft.ok){detail.element.setError(draft.error);return;}
    await persistAgendaEvent(detail.element,draft.payload,appStore);
  }

  /** Upsert a transition or gesture payload already projected by a typed program policy. */
  async function saveAgendaEvent(event:CustomEvent<AtlasAgendaSaveCommandV1>,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    const detail=event.detail;
    if(!detail||detail.element!==agendaElement)return;
    await persistAgendaEvent(detail.element,detail.payload,appStore);
  }

  /** Resolve an agenda status command against canonical events, then persist its policy projection. */
  async function transitionAgendaEvent(event:CustomEvent<AtlasAgendaTransitionDraftCommandV1>,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    const detail=event.detail;
    if(!detail||detail.element!==agendaElement)return;
    const source=agendaEvents.find(item=>item.id===detail.eventId);
    if(!source){detail.element.setError('O compromisso selecionado não está mais disponível na agenda.');return;}
    const transition=detail.kind==='complete'
      ? buildAtlasAgendaCompletionPayloadV1({source,nowIso:()=>new Date().toISOString()})
      : buildAtlasAgendaCancellationPayloadV1({source,cancellationConfirmed:detail.cancellationConfirmed,cancellationReason:detail.cancellationReason,nowIso:()=>new Date().toISOString()});
    if(!transition.ok){detail.element.setError(transition.error);return;}
    await persistAgendaEvent(detail.element,transition.payload,appStore);
  }

  /** Reproject a calendar gesture against the latest loaded event before persistence. */
  async function saveAgendaGesture(event:CustomEvent<AtlasAgendaGestureSaveCommandV1>,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    const detail=event.detail;
    if(!detail||detail.element!==agendaElement)return;
    const source=agendaEvents.find(item=>item.id===detail.eventId);
    if(!source){detail.element.setError('O compromisso arrastado não está mais disponível na agenda.');return;}
    const payload=projectAtlasAgendaWeekGestureV1({source,mode:detail.mode,date:detail.date,pointerHours:detail.pointerHours});
    await persistAgendaEvent(detail.element,payload,appStore);
  }

  /** Remove only the selected event from the persistent snapshot and reload it. */
  async function deleteAgendaEvent(event:CustomEvent<AtlasAgendaDeleteCommandV1>,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    const detail=event.detail;
    if(!detail||detail.element!==agendaElement)return;
    try{
      await enqueueAgendaMutation(async()=>{
        const actor=(appStore.get().currentActor||(runtime as unknown as { BELAVISTA_ADMIN_ACTOR?: unknown }).BELAVISTA_ADMIN_ACTOR||{}) as Record<string, unknown>;
        if(actor.mode==='desktop-demo'){
          demoAgendaEvents=agendaEvents.filter(item=>item.id!==detail.id);
          appStore.set({operationalAgenda:demoAgendaEvents,agendaDatabaseEventsV3:demoAgendaEvents,agendaCalendarLoadedV3:true,lastAction:`Excluiu compromisso ${detail.id}`});
          detail.element.closeEditor();
          await reloadAgenda();
          return;
        }
        const latest=await readApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events');
        if(!Array.isArray(latest.events))throw new Error('O serviço não retornou o snapshot atual da agenda.');
         const saved=await writeApi<{events:OperationalAgendaEvent[]}>('/api/agenda-events',{events:latest.events.filter(item=>item.id!==detail.id)});
         if(!Array.isArray(saved.events))throw new Error('A agenda não confirmou o snapshot salvo.');
         agendaEvents=saved.events;
         const removed=latest.events.find(item=>item.id===detail.id);
         if(removed&&agendaIsNative()&&Boolean(appStore.get().agendaMobileNotificationsEnabled))try{await cancelAgendaNotification(removed);}catch(error){agendaRouteServices.notify?.(`Compromisso excluído; lembrete local não cancelado: ${error instanceof Error?error.message:String(error)}`,'warning');}
         appStore.set({...appStore.get(),operationalAgenda:saved.events,agendaDatabaseEventsV3:saved.events,agendaCalendarLoadedV3:true,lastAction:`Excluiu compromisso ${detail.id}`});
         await reloadAgenda();
      });
    }catch(error){detail.element.setError(error instanceof Error?error.message:String(error));}
  }

  /** Create a field record linked to the selected agenda event. */
  async function persistAgendaRecord(element:AtlasAgenda,payload:AtlasOperationalRecordSubmissionV1,activity:string,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    try{
      const created=await createOperationalRecord(payload),record=created.record,recordId=created.id||String(record.id||'salvo');
      const agendaReloaded=await reloadAgenda();
      const message=`Registro ${recordId} adicionado à atividade ${activity}.`,state=appStore.get(),existing=Array.isArray(state.records)?state.records as Array<{id?:string}>:[];
      appStore.set({...state,records:[record,...existing.filter(item=>String(item.id)!==recordId)],...(agendaReloaded?{operationalAgenda:agendaEvents}:{}),agendaActivityRecordFeedbackV1:{eventId:String((payload.properties as Array<{label?:string;value?:string}>|undefined)?.find(item=>item.label==='ID da atividade')?.value||''),message},lastAction:`Adicionou registro ${recordId} na atividade ${activity}`});
      element.setRecordFeedback(message);
      agendaRouteServices.notify?.(`Registro salvo na atividade ${activity}.`,'success');
    }catch(error){
      element.setRecordFeedback(`Registro não salvo: ${error instanceof Error?error.message:String(error)}`,false);
      agendaRouteServices.notify?.('Registro não confirmado; revise a conexão e tente novamente.','warning');
    }
  }

  /** Validate the linked diary draft against canonical agenda and stage data. */
  async function createAgendaRecordDraft(event:CustomEvent<AtlasAgendaRecordDraftCommandV1>,appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void}):Promise<void>{
    const detail=event.detail;
    if(!detail||detail.element!==agendaElement)return;
    const source=agendaEvents.find(item=>item.id===detail.values.eventId);
    if(!source){detail.element.setRecordFeedback(null,false);detail.element.setError('O compromisso associado ao registro não foi encontrado.');return;}
    const stage=agendaStages.find(item=>item.name===source.stageName);
    const draft=buildAtlasAgendaRecordPayloadV1({
      source,
      stageName:stage?.name||'',
      details:detail.values.details,
      date:detail.values.date,
      time:detail.values.time,
      responsible:detail.values.responsible,
      status:detail.values.status,
    });
    if(!draft.ok){detail.element.setRecordFeedback(null,false);detail.element.setError(draft.error);return;}
    await persistAgendaRecord(detail.element,draft.payload,draft.activity,appStore);
  }

  /** Preserve the canonical-command receiver for existing Agenda integrations. */
