  /** Persist profile attachments in the same browser-local store used by the legacy profile. */
  async function addBrokerProfileAttachments(event: Event): Promise<void> {
    const detail = (event as CustomEvent<{ element: AtlasBrokers; profileId: string; files: File[] }>).detail;
    if (!detail || detail.element !== brokersElement || !detail.profileId || !Array.isArray(detail.files)) return;
    const files = detail.files;
    if (!files.length) return;
    const current = readBrokerProfileAttachmentsV1();
    const storedSize = Object.values(current).flat().reduce((sum, item) => sum + Number(item.size || 0), 0);
    const addedSize = files.reduce((sum, file) => sum + Number(file.size || 0), 0);
    if (files.some(file => file.size > 2 * 1024 * 1024 || !/^(application\/pdf|image\/(jpeg|png|webp))$/.test(file.type)) || storedSize + addedSize > 2 * 1024 * 1024) {
      detail.element.setMessage('Use PDF ou imagem; limite total de 2 MB para os anexos de perfil neste dispositivo.');
      return;
    }
    try {
      const additions = await Promise.all(files.map(async file => ({
        name: file.name,
        type: file.type,
        size: file.size,
        dataUrl: await fileDataUrl(file),
      })));
      const next = { ...current, [detail.profileId]: [...(current[detail.profileId] || []), ...additions] };
      if (!writeBrokerProfileAttachmentsV1(next)) throw new Error('Não foi possível salvar os anexos neste dispositivo. Libere espaço local.');
      syncBrokerCommissionSnapshotV1(detail.element);
      detail.element.setMessage(null);
    } catch (error) {
      detail.element.setMessage(error instanceof Error ? error.message : String(error));
    }
  }

  /** Remove only the selected local profile attachment. */
  function removeBrokerProfileAttachment(event: Event): void {
    const detail = (event as CustomEvent<{ element: AtlasBrokers; profileId: string; index: number }>).detail;
    if (!detail || detail.element !== brokersElement || !detail.profileId || !Number.isInteger(detail.index)) return;
    const current = readBrokerProfileAttachmentsV1();
    const next = { ...current, [detail.profileId]: (current[detail.profileId] || []).filter((_, index) => index !== detail.index) };
    if (!writeBrokerProfileAttachmentsV1(next)) {
      detail.element.setMessage('Não foi possível atualizar os anexos neste dispositivo.');
      return;
    }
    syncBrokerCommissionSnapshotV1(detail.element);
    detail.element.setMessage(null);
  }

