  /** Route a component intent to its corresponding persisted repasse CRUD endpoint. */
  async function mutateRepasse(event: Event): Promise<void> {
    const detail=(event as CustomEvent<{element:AtlasRepasses;command:AtlasRepasseMutationCommandV1}>).detail;
    if(!detail||detail.element!==repassesElement)return;
    const projection=projectAtlasRepasseMutationV1(detail.command,repassesSnapshot);
    if(!projection.ok){detail.element.setMessage(projection.error);return;}
    const {request}=projection;
    try {
      await runtime.BELAVISTA_ADMIN_AUTH_READY;
      const token=await runtime.BELAVISTA_GET_ID_TOKEN?.();if(!token)throw new Error('Autenticação necessária para modificar repasses.');
      const response=await fetch(apiUrl(request.path),{method:request.method,cache:'no-store',headers:{Authorization:'Bearer '+token,...('body'in request?{'Content-Type':'application/json'}:{})},...('body'in request?{body:JSON.stringify(request.body)}:{})});
      if(response.status===401)runtime.BELAVISTA_ADMIN_AUTH_INVALIDATE?.();
      const result=await response.json().catch(()=>({})) as {error?:string};if(!response.ok)throw new Error(result.error||'Operação recusada (HTTP '+response.status+').');
      await reloadRepasses();detail.element.setMessage('Alteração persistida; relatórios recalculados.');
    }catch(error){detail.element.setMessage(error instanceof Error?error.message:String(error));}
  }

