  /** Install broker directory/detail routes; own URL/store selection and domain listeners. */
  function installBrokersRoute(ViewLayer:{prototype:HTMLElement&Record<string,unknown>},appStore:{get():Record<string,unknown>;set(state:Record<string,unknown>):void},host:Document):void{
    brokersStore = appStore;
    let selectedBrokerId=String(appStore.get().selectedBrokerDirectoryId||'');
    const persistSelectionInUrl=()=>{if(typeof globalThis.history==='undefined')return;const url=new URL(location.href);if(selectedBrokerId)url.searchParams.set('broker',selectedBrokerId);else url.searchParams.delete('broker');globalThis.history.replaceState(globalThis.history.state,'',url);};
    installAtlasBrokersComponentControllerV1({
      ViewLayer,
      host,
      onDirectoryRoute: () => { selectedBrokerId = ''; persistSelectionInUrl(); },
      getDetailBrokerId: () => String(selectedBrokerId || new URL(location.href).searchParams.get('broker') || appStore.get().selectedBrokerDirectoryId || ''),
      onConnected: element => { brokersElement = element; void reloadBrokers(); },
      onRefresh: element => { if (element === brokersElement) void reloadBrokers(); },
      onExport: event => exportBrokers(event),
      onProfileSave: event => { void saveBrokerProfile(event); },
      onProfileDelete: event => { void deleteBrokerProfile(event); },
      onFile: event => { void downloadBrokerFile(event); },
      onPrintPeriodChange: event => {
        const detail = (event as CustomEvent<{ element: AtlasBrokers; brokerPrintMode?: string; brokerPrintMonth?: string; brokerPrintYear?: string }>).detail;
        if (!detail || detail.element !== brokersElement) return;
        const patch: Record<string, unknown> = {};
        if (detail.brokerPrintMode === 'monthly' || detail.brokerPrintMode === 'annual') patch.brokerPrintMode = detail.brokerPrintMode;
        if (detail.brokerPrintMonth && /^\d{4}-\d{2}$/.test(detail.brokerPrintMonth)) patch.brokerPrintMonth = detail.brokerPrintMonth;
        if (detail.brokerPrintYear && /^\d{4}$/.test(detail.brokerPrintYear)) patch.brokerPrintYear = detail.brokerPrintYear;
        if (Object.keys(patch).length) appStore.set(patch);
        syncBrokerCommissionSnapshotV1(detail.element);
      },
      onAttachmentsAdd: event => { void addBrokerProfileAttachments(event); },
      onAttachmentRemove: event => removeBrokerProfileAttachment(event),
      onApplyRules: event => {
        const detail = (event as CustomEvent<{ element: AtlasBrokers }>).detail;
        if (!detail || detail.element !== brokersElement) return;
        appStore.set({ commissionRulesAppliedAt: new Date().toISOString(), lastAction: 'Aplicou regras de repasse na carteira dedicada' });
        syncBrokerCommissionSnapshotV1(detail.element);
        detail.element.setMessage('Regras atuais aplicadas à tabela da carteira.');
      },
      onProfilePrint: event => {
        const detail = (event as CustomEvent<{ element: AtlasBrokers }>).detail;
        if (detail?.element === brokersElement) host.defaultView?.print();
      },
      onNavigate: event => {
        const navigation = (event as CustomEvent<{ view: string; id?: string }>).detail;
        if (!navigation || !['brokers', 'broker-detail'].includes(navigation.view)) return;
        selectedBrokerId = navigation.view === 'broker-detail' ? String(navigation.id || '') : '';
        persistSelectionInUrl();
        navigateRoute(appStore, { view: navigation.view, brokerId: selectedBrokerId }, {
          selectedBrokerDirectoryId: selectedBrokerId,
          lastAction: navigation.view === 'broker-detail' ? 'Abriu o perfil do corretor' : 'Voltou à listagem de corretores',
        });
      },
    });
  }

