  /** Compose the local demo from checked-in fixtures; never send those examples to the Worker. */
  function createAtlasLocalDemoDashboardSnapshotV1(
    lotStatuses: Record<string, AtlasLotStatus | undefined>,
  ): DashboardSnapshot {
    const demo = ATLAS_STATE_CATALOGS_V1.demoData as unknown as {
      metrics?: { leads?: number; delayed?: number };
      activities?: Array<{ id?: number | string; name?: string; status?: string; progress?: number; week?: string; owner?: string }>;
      materials?: unknown[][];
    };
    const seed = ATLAS_STATE_CATALOGS_V1.cashFlowSeed as unknown as CashFlowRecord[];
    const balanceCents = seed.reduce((balance, row) => balance + (row.kind === 'entrada' ? 1 : -1) * Number(row.amountCents || 0), 0);
    const stages: OperationalStage[] = (demo.activities || []).map((item, index) => {
      const id = Number(item.id) || index + 1;
      const name = String(item.name || `Etapa ${index + 1}`);
      return {
        id, key: `demo-stage-${id}`, name, status: String(item.status || 'planejado'),
        progress: Number(item.progress) || 0, week: String(item.week || ''), owner: String(item.owner || ''),
        activities: [{ id: `demo-activity-${id}`, name } as unknown as OperationalActivity],
      };
    });
    const today = new Date();
    const localDate = (offsetDays: number): string => {
      const date = new Date(today);
      date.setDate(date.getDate() + offsetDays);
      return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
    };
    const records: OperationalRecord[] = stages.slice(0, 3).map((stage, index) => ({
      id: `DEMO-REG-${String(index + 1).padStart(3, '0')}`,
      data: localDate(-index), hora: '09:00', obra: 'Aliança Park', etapa: stage.name,
      stageId: stage.id, stageKey: stage.key, activityId: `demo-activity-${stage.id}`,
      activityName: stage.name, atividade: stage.name, responsavel: stage.owner || 'Equipe de demonstração',
      status: index === 0 ? 'Em andamento' : 'Concluído', progresso: stage.progress,
      detalhes: 'Apontamento de exemplo do ambiente local de demonstração.', source: 'local-demo',
    }));
    const agendaEvents: OperationalAgendaEvent[] = stages.slice(0, 4).map((stage, index) => ({
      id: `DEMO-AGENDA-${index + 1}`, title: stage.name, stageKey: stage.key || '', stageName: stage.name,
      activityId: `demo-activity-${stage.id}`, activityName: stage.name,
      owner: stage.owner || 'Equipe de demonstração', date: localDate(index + 1), start: '08:00',
      durationHours: 3, spanDays: 1, status: 'Planejado', notes: 'Compromisso ilustrativo da demonstração.', materialIds: [],
    }));
    const quantity = (value: unknown): number => {
      const text = String(value ?? '').trim().replace(/\.(?=\d{3}(?:\D|$))/g, '').replace(',', '.');
      const parsed = Number(text);
      return Number.isFinite(parsed) ? parsed : 0;
    };
    const materials: OperationalMaterial[] = (demo.materials || []).map((row, index) => ({
      id: `DEMO-MAT-${index + 1}`, name: String(row[0] || `Nota ${index + 1}`),
      plannedQuantity: quantity(row[1]), receivedQuantity: quantity(row[2]), usedQuantity: quantity(row[3]),
      unit: String(row[4] || 'un'), status: String(row[5] || 'planejado'), stageId: null,
      stageName: 'Demonstração', activityName: 'Estoque de referência', scope: 'Dado local ilustrativo',
      updatedAt: '', properties: {},
    }));
    const notifications: OperationalNotification[] = (Number(demo.metrics?.delayed) || 0) > 0
      ? [{ id: 'DEMO-ALERTA-01', title: 'Compras com prazo de atenção', message: 'A demonstração inclui compras que exigem acompanhamento.', status: 'unread' },
         { id: 'DEMO-ALERTA-02', title: 'Revisar materiais críticos', message: 'Confira quantidades e estados no catálogo ilustrativo.', status: 'unread' }]
      : [];
    const snapshot = projectAtlasDashboardSnapshotV1({
      cashFlow: { summary: { balanceCents }, entries: seed }, stages: { stages }, records: { records },
      notifications: { notifications }, agenda: { events: agendaEvents }, materials: { materials },
      repasses: { sales: [], entries: [], brokerRules: [], reasons: [], stages: [] }, lotStatuses,
    });
    return {
      ...snapshot,
      commercialInterestCount: Number(demo.metrics?.leads) || 0,
      commercialInterestState: 'demo',
      demoMode: true,
    };
  }

  /** Read each dashboard metric from its owning operational service; never infer missing sources. */
  async function reloadDashboard(): Promise<void> {
    const target = dashboardElement;
    if (!target) return;
    const requestId = ++dashboardRequestId;
    try {
      const runtime = globalThis as typeof globalThis & { BELAVISTA_ADMIN_ACTOR?: Record<string, unknown> | null };
      const storedActor = dashboardAppStore?.get().currentActor;
      const actor = storedActor && typeof storedActor === 'object'
        ? storedActor as Record<string, unknown>
        : runtime.BELAVISTA_ADMIN_ACTOR || {};
      if (actor.mode === 'desktop-demo') {
        const state = dashboardAppStore?.get() || {};
        const snapshot = createAtlasLocalDemoDashboardSnapshotV1(
          (state.lotStatuses || {}) as Record<string, AtlasLotStatus | undefined>,
        );
        dashboardStages = snapshot.stages;
        target.setData(snapshot);
        return;
      }
      // The dashboard needs counts only. The Worker summary avoids transferring
      // contact and document fields from the CRM list endpoint into this route.
      const commercialSummaryTask: Promise<number | null> = readApi<PublicCommercialSummary>('/api/admin/public-lead-summary')
        .then(projectAtlasDashboardCommercialInterestV1)
        .catch(() => null);
      const [cashPayload, stagePayload, recordPayload, notificationPayload, agendaPayload, materialPayload, repassePayload] = await Promise.all([
        readApi<{ summary: { balanceCents: number }; entries: CashFlowRecord[] }>('/api/cash-flow'),
        readApi<{ stages: OperationalStage[] }>('/api/stages-admin'),
        readApi<{ records: OperationalRecord[] }>('/api/records'),
        readApi<{ notifications: OperationalNotification[] }>('/api/notifications'),
        readApi<{ events: OperationalAgendaEvent[] }>('/api/agenda-events'),
        readApi<{ materials: OperationalMaterial[] }>('/api/materials'),
        readApi<RepasseOperations>('/api/repasses'),
      ]);
      if (requestId !== dashboardRequestId || target !== dashboardElement) return;
      const snapshot = projectAtlasDashboardSnapshotV1({
        cashFlow: cashPayload, stages: stagePayload, records: recordPayload,
        notifications: notificationPayload, agenda: agendaPayload, materials: materialPayload,
        repasses: repassePayload,
        lotStatuses: (dashboardAppStore?.get().lotStatuses || {}) as Record<string, AtlasLotStatus | undefined>,
      });
      dashboardStages = snapshot.stages;
      target.setData(snapshot);
      void commercialSummaryTask.then(commercialInterestCount => {
        if (requestId !== dashboardRequestId || target !== dashboardElement) return;
        target.setCommercialInterestSummary(
          commercialInterestCount,
          commercialInterestCount === null ? 'unavailable' : 'loaded',
        );
      });
    } catch (error) {
      if (requestId === dashboardRequestId && target === dashboardElement)
        target.setError(error instanceof Error ? error.message : String(error));
    }
  }

  /** Generate a CSV from a fresh authenticated read of the requested operational collection. */
  async function exportDashboardReport(event: Event): Promise<void> {
    const detail = (event as CustomEvent<{ element: AtlasDashboard; kind: string }>).detail;
    if (!detail || detail.element !== dashboardElement) return;
    try {
      const report = detail.kind === 'records'
        ? { path: '/api/records', key: 'records', filename: 'registros-de-campo.csv', columns: ['id','data','hora','obra','etapa','atividade','responsavel','status','detalhes'] as const }
        : detail.kind === 'agenda'
          ? { path: '/api/agenda-events', key: 'events', filename: 'agenda-por-estado.csv', columns: ['id','status','date','start','title','stageName','activityName','owner','durationHours','spanDays','notes'] as const }
          : null;
      if (!report) throw new Error('Tipo de relatório não reconhecido.');
      const payload = await readApi<Record<string, unknown>>(report.path);
      const rows = payload[report.key];
      if (!Array.isArray(rows)) throw new Error('O serviço não retornou a lista esperada para exportação.');
      if (detail.kind === 'agenda') {
        const priority = operationalPolicies.agendaStatusPriority;
        rows.sort((left, right) => {
          const a = left as Record<string, unknown>, b = right as Record<string, unknown>;
          const leftStatus = String(a.status || 'Planejado').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
          const rightStatus = String(b.status || 'Planejado').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
          const leftRank = priority.indexOf(leftStatus), rightRank = priority.indexOf(rightStatus);
          return (leftRank < 0 ? priority.length : leftRank) - (rightRank < 0 ? priority.length : rightRank) ||
            leftStatus.localeCompare(rightStatus, 'pt-BR') || `${a.date || ''}T${a.start || ''}`.localeCompare(`${b.date || ''}T${b.start || ''}`);
        });
      }
      if (!rows.length) { detail.element.setFeedback('A fonte persistida não contém registros para exportar.'); return; }
      const cell = (value: unknown) => {
        const text = String(value ?? '').replace(/[\r\n]+/g, ' ');
        return `"${(/^[=+@-]/.test(text) ? `'${text}` : text).replaceAll('"', '""')}"`;
      };
      const csv = '\uFEFF' + [report.columns.map(cell).join(';'), ...rows.map(row => {
        const record = row as Record<string, unknown>;
        return report.columns.map(key => cell(record[key])).join(';');
      })].join('\r\n');
      const objectUrl = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
      const anchor = document.createElement('a'); anchor.href = objectUrl; anchor.download = report.filename;
      document.body.append(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000);
      detail.element.setFeedback(`CSV gerado a partir de ${rows.length} registro(s) persistido(s).`);
    } catch (error) {
      detail.element.setFeedback(`Relatório não gerado: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /** Validate and persist the legacy quick-entry form through the dashboard program. */
  async function createDashboardQuickRecord(
    event: CustomEvent<AtlasDashboardQuickRecordSubmitDetailV1>,
    appStore: { get(): Record<string, unknown>; set(state: Record<string, unknown>): void },
    host: Document,
  ): Promise<void> {
    const detail = event.detail;
    if (!detail?.form?.isConnected || !detail.view?.isConnected) return;
    const values = detail.values;
    const stage = dashboardStages.find(item => String(item.key) === String(values.stageKey));
    const submission = buildAtlasDashboardQuickRecordSubmissionV1({ stage, values, now: new Date() });
    if (submission.status !== 'ready') {
      host.dispatchEvent(new CustomEvent<AtlasDashboardQuickRecordResultDetailV1>(
        'atlas:dashboard-quick-record-result',
        { detail: { ...detail, saved: false, message: 'Selecione uma etapa e informe a atividade.' } },
      ));
      return;
    }
    try {
      const saved = await createOperationalRecord(submission.payload as OperationalRecordCreateInputV1);
      const state = appStore.get();
      const records = Array.isArray(state.records) ? state.records as OperationalRecord[] : [];
      appStore.set({
        records: [saved.record as OperationalRecord, ...records.filter(item => String(item.id) !== String(saved.id))],
        lastAction: `Criou registro de ${submission.activity} na etapa ${submission.stageName}`,
        dashboardQuickRecordFeedbackV1: `Registro ${saved.id} salvo e vinculado a ${submission.stageName}.`,
      });
      host.dispatchEvent(new CustomEvent<AtlasDashboardQuickRecordResultDetailV1>(
        'atlas:dashboard-quick-record-result',
        { detail: { ...detail, saved: true, message: `Registro ${saved.id} salvo e vinculado a ${submission.stageName}.` } },
      ));
      try {
        await (detail.view as HTMLElement & { runOperationalLoop?: (eventName: string) => Promise<unknown> })
          .runOperationalLoop?.('record.created');
      } catch (error) {
        console.warn('Replanejamento após registro não concluído.', error);
      }
    } catch (error) {
      const message = `Registro não salvo: ${error instanceof Error ? error.message : 'serviço indisponível'}`;
      appStore.set({ dashboardQuickRecordFeedbackV1: message });
      host.dispatchEvent(new CustomEvent<AtlasDashboardQuickRecordResultDetailV1>(
        'atlas:dashboard-quick-record-result',
        { detail: { ...detail, saved: false, message } },
      ));
    }
  }

  /** Validate the dashboard draft, persist it, and refresh canonical sources. */
  async function createDashboardRecord(event: Event): Promise<void> {
    const detail = (event as CustomEvent<AtlasDashboardRecordCreateCommandDetailV1>).detail;
    if (!detail || detail.element !== dashboardElement) return;
    const projected = projectAtlasDashboardRecordSubmissionV1(dashboardStages, detail.draft);
    if (projected.status === 'invalid') {
      const message = projected.reason === 'stage-activity'
        ? 'Selecione uma etapa e uma atividade cadastradas no serviço.'
        : projected.reason === 'required-fields'
          ? 'Data, hora e resumo do registro são obrigatórios.'
          : 'O comprovante deve ter até 6 MB.';
      detail.element.setRecordError(message);
      return;
    }
    try {
      await createOperationalRecord({
        ...projected.payload,
        ...(detail.evidenceUri ? { evidenceUri: detail.evidenceUri } : {}),
      });
      if (detail.element !== dashboardElement) return;
      await reloadDashboard();
      if (detail.element === dashboardElement) detail.element.setRecordResult('Registro confirmado pelo serviço do diário. Os indicadores foram atualizados.');
    } catch (error) {
      if (detail.element === dashboardElement)
        detail.element.setRecordError(error instanceof Error ? error.message : String(error));
    }
  }

  /** Ask Cloudflare Workers AI for a non-persistent Dashboard preview. */
  async function generateDashboardAiPlan(event: Event): Promise<void> {
    const detail = (event as CustomEvent<{ element: AtlasDashboard; kind: AtlasDashboardGenerationKindV1 }>).detail;
    if (!detail || detail.element !== dashboardElement) return;
    detail.element.setAiGenerationLoading(detail.kind);
    try {
      const runtime = globalThis as typeof globalThis & { BELAVISTA_ADMIN_ACTOR?: Record<string, unknown> | null };
      const actor = dashboardAppStore?.get().currentActor as Record<string, unknown> | undefined || runtime.BELAVISTA_ADMIN_ACTOR || {};
      const demoMode = actor.mode === 'desktop-demo';
      const demoSnapshot = demoMode ? createAtlasLocalDemoDashboardSnapshotV1({}) : null;
      const demoCatalog = demoSnapshot ? {
        projectName: 'Aliança Park · demonstração',
        stages: demoSnapshot.stages.map(stage => ({
          id: `demo-stage-${String(stage.id)}`, name: stage.name, status: stage.status, owner: stage.owner,
          activities: (stage.activities || []).map(activity => ({
            id: `demo-activity-${String(stage.id)}`, name: activity.name, status: activity.status || stage.status,
            owner: activity.owner || stage.owner, durationDays: 1,
            durationBasis: 'estimativa ilustrativa de 1 dia, exclusiva da demonstração',
            description: `Atividade ilustrativa da etapa ${stage.name}; ajustar duração e sequência antes de uso real.`,
          })),
        })),
        materials: demoSnapshot.materials.map(material => ({
          name: material.name, unit: material.unit, plannedQuantity: material.plannedQuantity,
          stockQuantity: Math.max(0, Number(material.receivedQuantity || 0) - Number(material.usedQuantity || 0)),
          orderedQuantity: 0,
        })),
      } : null;
      const response = await apiFetch(demoMode ? '/api/ai/dashboard-demo-generation' : '/api/ai/dashboard-generation', {
        method: 'POST', cache: 'no-store',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ kind: detail.kind, ...(demoCatalog ? { catalog: demoCatalog } : {}) }),
      });
      const payload = await response.json().catch(() => null) as (AtlasDashboardAiGenerationV1 & { error?: string }) | null;
      if (!response.ok) throw new Error(payload?.error || `Cloudflare Workers AI respondeu HTTP ${response.status}.`);
      if (!payload || payload.inference?.provider !== 'cloudflare-workers-ai')
        throw new Error('A resposta não confirmou geração por Cloudflare Workers AI.');
      if (detail.element === dashboardElement) detail.element.setAiGenerationResult(payload);
    } catch (error) {
      if (detail.element === dashboardElement)
        detail.element.setAiGenerationError(error instanceof Error ? error.message : String(error));
    }
  }

  /** Supply persisted service actions to the Dashboard component controller. */
  function installDashboardRoute(ViewLayer: { prototype: HTMLElement & Record<string, unknown> }, appStore: { get(): Record<string, unknown>; set(state: Record<string, unknown>): void }, host: Document): void {
    dashboardAppStore = appStore;
    installAtlasDashboardComponentControllerV1({
      ViewLayer,
      host,
      onConnected: element => { dashboardElement = element; void reloadDashboard(); },
      onRefresh: element => { if (element === dashboardElement) void reloadDashboard(); },
      onGenerate: event => { void generateDashboardAiPlan(event); },
      onReport: event => { void exportDashboardReport(event); },
      onRecordCreate: event => { void createDashboardRecord(event); },
      onQuickRecord: event => { void createDashboardQuickRecord(event, appStore, host); },
      onNavigate: (element, navigation) => {
        if (element !== dashboardElement) return;
        if (!navigation || !['assistant','map','reports','records','progress','activities','materials','leads','brokers','brokers-board','finance','repasses','cash-record','settings','stages','agenda'].includes(navigation.view)) return;
        const stageId = navigation.stageKey && /^\d+$/.test(navigation.stageKey) ? Number(navigation.stageKey) : null;
        const agendaContext = navigation.view === 'agenda'
          ? { agendaFocusedDateV1: navigation.agendaDate || null, selectedAgendaEventV3: navigation.agendaEventId || null, agendaCalendarWeekV8: navigation.agendaDate || null }
          : {};
        navigateRoute(appStore, { view: navigation.view, ...(navigation.stageKey ? { stageKey: navigation.stageKey, ...(stageId === null ? {} : { stageId }) } : {}) }, { ...agendaContext, ...(navigation.stageKey ? { stageSelected: true } : {}), ...(navigation.view === 'stages' && navigation.stageKey ? { activityDedicated: true, stageActivityDedicatedV9: false } : {}), ...(navigation.newRecord ? { activityDedicated: false, selectedActivity: null, selectedRecordsActivityV5377: null, recordsRegistrationRequestedV5377: true, editingRecord: null, recordContext: null, lastAction: 'Abriu novo registro' } : { lastAction: 'Abriu ' + navigation.view + ' pelo panorama operacional' }) });
      },
    });
  }

