// MIGRATION: components/shared/routing.mjs.
// Preserves router prefixes for multiplexed/ngrok deployments and the existing
// session key. The location is injected for deterministic tests.
export interface AtlasRuntimeRouteLocation {
  pathname?: string;
  hostname?: string;
  search?: string;
}
export function runtimeRouteV1(
  path: unknown,
  query: unknown = '',
  locationRef: AtlasRuntimeRouteLocation = globalThis.location,
): string {
  const route = String(path || '/').startsWith('/')
    ? String(path || '/') : `/${String(path || '')}`;
  const currentPath = String(locationRef?.pathname || '');
  const embeddedPrefix = currentPath.match(/^\/(\d{2,5})(?=\/|$)/)?.[0] || '';
  const host = String(locationRef?.hostname || '');
  const tunnelPrefix = embeddedPrefix || (/ngrok/i.test(host) ? '/8080' : '');
  const params = new URLSearchParams(String(query || '').replace(/^\?/, ''));
  const key = new URLSearchParams(String(locationRef?.search || '')).get('key');
  if (key && !params.has('key')) params.set('key', key);
  const suffix = params.toString();
  return `${tunnelPrefix}${route}${suffix ? `?${suffix}` : ''}`;
}

