/** Create the stable same-origin cache key, excluding temporary ngrok key parameters. */
export function projectAtlasMapModelCacheKeyV1(locationRef: AtlasMapModelClientLocationV1): string {
  const currentPath = String(locationRef.pathname || '');
  const embeddedPrefix = currentPath.match(/^\/(\d{2,5})(?=\/|$)/)?.[0] || '';
  const host = String(locationRef.hostname || '');
  const tunnelPrefix = embeddedPrefix || (/ngrok/i.test(host) ? '/8080' : '');
  return `${String(locationRef.origin || '')}${tunnelPrefix}${ATLAS_MAP_MODEL_ASSET_V1}?client-cache=${atlasMapModelClientCacheCatalogV1.cacheVersion}`;
}

export interface AtlasMapModelCacheRuntimeV1 {
  locationRef?: AtlasMapModelClientLocationV1;
  cacheStorage?: CacheStorage;
  fetcher?: typeof fetch;
  documentRef?: Pick<Document, 'documentElement'> | null;
  navigatorRef?: Pick<Navigator, 'storage'> | null;
  globalRef?: Record<string, any>;
  consoleRef?: Pick<Console, 'warn'>;
}

/** Read the GLB from Cache Storage or network and report the same byte-progress contract. */
export async function loadAtlasMapModelBufferV1(
  fetchUrl?: string,
  onProgress?: (progress: AtlasMapModelCacheProgressV1) => void,
  runtime: AtlasMapModelCacheRuntimeV1 = {},
): Promise<{ buffer: ArrayBuffer; source: 'network' | 'cache-storage'; fetchUrl: string }> {
  const locationRef = runtime.locationRef || globalThis.location;
  const absoluteFetchUrl = new URL(String(fetchUrl || ATLAS_MAP_MODEL_ASSET_V1), locationRef.href).href;
  const stableCacheKey = projectAtlasMapModelCacheKeyV1(locationRef);
  let cache: Cache | null = null;
  let response: Response | null = null;
  let source: 'network' | 'cache-storage' = 'network';
  const cacheStorage = runtime.cacheStorage || globalThis.caches;
  if (cacheStorage) {
    try {
      cache = await cacheStorage.open(atlasMapModelClientCacheCatalogV1.cacheName);
      response = await cache.match(stableCacheKey) || null;
      if (response) source = 'cache-storage';
    } catch (error) {
      (runtime.consoleRef || console).warn('[Belavista] Cache Storage indisponível para o GLB.', error);
    }
  }
  if (!response) {
    const fetcher = runtime.fetcher || globalThis.fetch.bind(globalThis);
    response = await fetcher(absoluteFetchUrl, { method: 'GET', cache: 'no-store', credentials: 'same-origin' });
    if (!response.ok) throw new Error(`Falha ao baixar modelo 3D (${response.status})`);
    if (cache) {
      try {
        await cache.put(stableCacheKey, response.clone());
      } catch (error) {
        (runtime.consoleRef || console).warn('[Belavista] Modelo carregou, mas não pôde ser persistido no Cache Storage.', error);
      }
    }
  }
  const buffer = await response.arrayBuffer();
  const bytes = buffer.byteLength;
  onProgress?.({ loaded: bytes, total: bytes, lengthComputable: true, clientCacheSource: source });
  const globalRef = runtime.globalRef || globalThis as unknown as Record<string, any>;
  globalRef.__BELAVISTA_MODEL_CLIENT_CACHE_V14__ = {
    cacheName: atlasMapModelClientCacheCatalogV1.cacheName,
    cacheKey: stableCacheKey,
    source,
    bytes,
    ready: true,
  };
  const documentRef = runtime.documentRef === undefined ? globalThis.document : runtime.documentRef;
  if (documentRef?.documentElement) {
    documentRef.documentElement.dataset.model3dClientCacheV14 = source;
    documentRef.documentElement.dataset.model3dClientCacheBytesV14 = String(bytes);
  }
  return { buffer, source, fetchUrl: absoluteFetchUrl };
}

/** Request persistent browser storage for the model cache when the platform permits it. */
export async function requestAtlasMapModelPersistentStorageV1(
  runtime: Pick<AtlasMapModelCacheRuntimeV1, 'navigatorRef' | 'documentRef'> = {},
): Promise<boolean> {
  const navigatorRef = runtime.navigatorRef === undefined ? globalThis.navigator : runtime.navigatorRef;
  if (!navigatorRef?.storage?.persist) return false;
  try {
    const alreadyPersistent = await navigatorRef.storage.persisted?.() === true;
    if (alreadyPersistent) return true;
    return await navigatorRef.storage.persist() === true;
  } catch {
    return false;
  }
}

/** Preload the GLB through the same cache path used by the live map scene. */
export async function preloadAtlasMapModelV1(runtime: AtlasMapModelCacheRuntimeV1 = {}): Promise<{ buffer: ArrayBuffer; source: 'network' | 'cache-storage'; fetchUrl: string }> {
  const globalRef = runtime.globalRef || globalThis as unknown as Record<string, any>;
  if (globalRef.__BELAVISTA_MODEL_CLIENT_PRELOAD_V14__) return globalRef.__BELAVISTA_MODEL_CLIENT_PRELOAD_V14__;
  const task = (async () => {
    const persistent = await requestAtlasMapModelPersistentStorageV1(runtime);
    const documentRef = runtime.documentRef === undefined ? globalThis.document : runtime.documentRef;
    if (documentRef?.documentElement)
      documentRef.documentElement.dataset.model3dPersistentStorageV14 = persistent ? 'granted' : 'best-effort';
    const locationRef = runtime.locationRef || globalThis.location;
    const fetchUrl = runtimeRouteV1(ATLAS_MAP_MODEL_ASSET_V1, `v=${atlasMapModelClientCacheCatalogV1.cacheVersion}`, locationRef);
    try {
      const result = await loadAtlasMapModelBufferV1(fetchUrl, undefined, runtime);
      if (documentRef?.documentElement) documentRef.documentElement.dataset.model3dPreloadV14 = 'ready';
      return result;
    } catch (error) {
      if (documentRef?.documentElement) documentRef.documentElement.dataset.model3dPreloadV14 = 'failed';
      (runtime.consoleRef || console).warn('[Belavista] Pré-cache do modelo 3D não concluído.', error);
      throw error;
    }
  })();
  globalRef.__BELAVISTA_MODEL_CLIENT_PRELOAD_V14__ = task;
  return task;
}

