export type AtlasAiChatComponentActionV1 =
  | { type: 'navigate'; requestedView: string; label: string }
  | { type: 'open-map-context' }
  | { type: 'set-print-mode'; enabled: boolean };
export interface AtlasAiChatComponentStatePortV1 {
  readState: () => Record<string, any>;
  subscribe: (listener: (state: Record<string, any>) => void) => (() => void) | void;
  onAction: (action: AtlasAiChatComponentActionV1) => void;
}
/** Apply a chat view command to canonical application state. */
export function applyAtlasAiChatComponentActionV1(input: {
  action: AtlasAiChatComponentActionV1;
  appStore: Pick<AtlasAiChatStatePortV1, 'set'>;
}): void {
  const { action, appStore } = input;
  if (action.type === 'navigate') {
    const view = action.requestedView === 'inventory' || action.requestedView === 'assistant'
      ? 'map'
      : action.requestedView;
    appStore.set({
      view,
      activityDedicated: false,
      selectedActivity: null,
      lastAction: `Abriu ${action.label}`,
    });
    return;
  }
  if (action.type === 'open-map-context') {
    appStore.set({ view: 'map', lastAction: 'Abriu os lotes 3D pelo chat da IA' });
    return;
  }
  if (action.enabled) {
    appStore.set({ printMode: true, lastAction: 'Solicitou impressão pelo assistente' });
    return;
  }
  appStore.set({ printMode: false });
}
