export interface AtlasAiChatLotStatusShortcutEffectsV1 {
  appendUserMessage(message: unknown): unknown;
  appendAssistantMessage(message: string): unknown;
  persistAssistantMessage(message: string): unknown;
}

/** Handle the deterministic lot-status shortcut before sending a request to the model. */
export function handleAtlasAiChatLotStatusShortcutV1(input: {
  message: unknown;
  attachment: unknown;
  commands: AtlasAiChatPortsV1['commands'];
  effects: AtlasAiChatLotStatusShortcutEffectsV1;
}): boolean {
  if (input.attachment) return false;
  const command = input.commands.parseLotStatusCommand(input.message);
  if (!command) return false;
  input.effects.appendUserMessage(input.message);
  const answerText = 'error' in command
    ? command.error
    : input.commands.applyLotStatusCommand(command);
  input.effects.appendAssistantMessage(answerText);
  input.effects.persistAssistantMessage(answerText);
  return true;
}

const ATLAS_AI_CHAT_PORT_CONTRACT_V1 = Object.freeze({
  chat: ["CHAT_IMAGE_MAX_BYTES_V1", "CHAT_OPERATIONAL_EXECUTION_INSTRUCTION_V1", "CHAT_VISUAL_ALLOCATION_POLICY_V1"],
  storage: ["readChatHistory", "readChatWindowLayout", "writeChatHistory", "writeChatWindowLayout", "clearChatHistory", "readChatVoiceEnabled", "writeChatVoiceEnabled"],
  agenda: ["findLastAvailableSlot", "parseDate", "readCalendar", "weekKey", "writeCalendar", "refreshCalendar", "normalizeActivityRouteText", "createPendingAgenda"],
  state: ["get", "set", "update", "subscribe"],
  componentState: ["readState", "subscribe", "onAction"],
  projectContext: [],
  assistant: ["infer"],
  recordPersistence: ["persistVisualAttachment", "createRecord"],
  visualAllocation: ["allocateRecord"],
  commands: ["applyLotStatusCommand", "parseLotStatusCommand"],
  events: ["createServiceEventAdministrators"],
  map: ["commonAreaLabel"],
  records: ["listLotDevelopmentProfiles", "readStageRecordAttachments", "normalizeStageRecord", "saveLotDevelopmentProfile"],
  ui: ["esc", "ico", "notify"],
} as const);
const ATLAS_AI_CHAT_PORT_MEMBERS_V1: Record<string, readonly string[]> = Object.freeze({
  ...ATLAS_AI_CHAT_PORT_CONTRACT_V1,
  storage: [...ATLAS_AI_CHAT_PORT_CONTRACT_V1.storage, "CHAT_HISTORY_STORAGE_KEY", "CHAT_VOICE_STORAGE_KEY_V1"],
  projectContext: ["metrics", "activities", "executionModel"],
});

/** Validate app services and browser capabilities at the chat composition boundary. */
export function createAtlasAiChatDependenciesV1(input: AtlasAiChatDependenciesV1): AtlasAiChatDependenciesV1 {
  const { browser, ports } = input;
  if (!ports || typeof ports !== "object" || Array.isArray(ports))
    throw new TypeError("AI chat requires a named service-port container.");
  const expectedGroups = Object.keys(ATLAS_AI_CHAT_PORT_CONTRACT_V1);
  const unexpectedGroups = Object.keys(ports).filter(name => !expectedGroups.includes(name));
  if (unexpectedGroups.length)
    throw new TypeError(`AI chat received an unknown service port: ${unexpectedGroups.join(", ")}.`);
  for (const [group, requiredMembers] of Object.entries(ATLAS_AI_CHAT_PORT_CONTRACT_V1)) {
    const port = ports[group as keyof AtlasAiChatPortsV1];
    if (!port || typeof port !== "object") throw new TypeError(`AI chat requires the ${group} port.`);
    const unexpectedMembers = Object.keys(port).filter(name => !(ATLAS_AI_CHAT_PORT_MEMBERS_V1[group] || []).includes(name));
    if (unexpectedMembers.length)
      throw new TypeError(`AI chat received unknown members in ${group}: ${unexpectedMembers.join(", ")}.`);
    for (const member of requiredMembers) {
      const value = (port as Record<string, unknown>)[member];
      if (group === "chat" && member === "CHAT_IMAGE_MAX_BYTES_V1") {
        if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) throw new TypeError(`AI chat requires a positive ${group}.${member}.`);
      } else if (group === "chat" || group === "map") {
        if (typeof value !== "string" || !value.trim()) throw new TypeError(`AI chat requires a non-empty ${group}.${member}.`);
      } else if (typeof value !== "function") {
        throw new TypeError(`AI chat requires ${group}.${member}().`);
      }
    }
  }
  const projectContext = ports.projectContext;
  if (!projectContext.metrics || typeof projectContext.metrics !== "object" || !Array.isArray(projectContext.activities))
    throw new TypeError("AI chat requires projectContext metrics and activities.");
  if (!projectContext.executionModel || typeof projectContext.executionModel !== "object")
    throw new TypeError("AI chat requires the projectContext execution model.");
  if (!browser?.HTMLElement || typeof browser.FileReader !== "function" ||
      typeof browser.document?.createElement !== "function" ||
      typeof browser.eventTarget?.addEventListener !== "function" || typeof browser.createIcons !== "function" ||
      !["setTimeout", "clearTimeout", "requestAnimationFrame"].every(method => typeof browser[method] === "function"))
    throw new TypeError("AI chat requires a complete browser port at composition time.");
  if (browser.print != null && typeof browser.print !== "function")
    throw new TypeError("AI chat browser print capability must be a function when available.");
  if (browser.speechSynthesis != null && typeof browser.speechSynthesis.speak !== "function")
    throw new TypeError("AI chat speech synthesis capability must implement speak().");
  if (browser.SpeechSynthesisUtterance != null && typeof browser.SpeechSynthesisUtterance !== "function")
    throw new TypeError("AI chat speech utterance capability must be a constructor when available.");
  const immutablePorts = Object.freeze(Object.fromEntries(
    Object.entries(ATLAS_AI_CHAT_PORT_CONTRACT_V1).map(([name]) => [name, Object.freeze({ ...ports[name as keyof AtlasAiChatPortsV1] })]),
  )) as unknown as AtlasAiChatPortsV1;
  return Object.freeze({ browser: Object.freeze({ ...browser }), ports: immutablePorts });
}

