/** Build the chat request and invoke the configured inference service through application ports. */
export async function requestAtlasAiChatInferenceV1(
  input: AtlasAiChatInferenceExecutionInputV1,
): Promise<AtlasAiChatInferenceExecutionResultV1> {
  const { ports } = input;
  const attachment = input.attachment || null;
  const endpoint = attachment ? '/api/ai/vision-reasoning' : '/api/ai';
  const state = ports.state.get();
  const requestBody: AtlasAiChatInferenceRequestBodyV1 = {
    message: input.message,
    view: typeof state.view === 'string' ? state.view : undefined,
    mapContext: input.mapContext,
    instruction: `${ports.chat.CHAT_OPERATIONAL_EXECUTION_INSTRUCTION_V1} ${ports.chat.CHAT_VISUAL_ALLOCATION_POLICY_V1} ${aiAgendaInstructionV1(state.aiAgendaComprehensionV1)}`,
    requestContext: input.requestContext && typeof input.requestContext === 'object' ? input.requestContext : null,
    context: input.context,
    attachment: attachment
      ? { name: attachment.name, mimeType: attachment.mimeType, dataUrl: attachment.dataUrl }
      : null,
  };
  const requestInit: RequestInit = {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(requestBody),
  };
  const modelBody = JSON.parse(String(requestInit.body)) as AtlasAiChatInferenceRequestBodyV1;
  const payload = await ports.assistant.infer({
    modelRequest: { endpoint: '/api/inference', body: modelBody },
    httpRequest: { endpoint, init: requestInit },
  });
  return { endpoint, payload: payload as AtlasAiChatInferencePayloadV1 };
}

/** Normalize an inference response before the chat component presents it. */
export function projectAtlasAiChatInferenceResponseV1(input: {
  endpoint: string;
  payload: unknown;
}): AtlasAiChatInferenceResponseProjectionV1 {
  if (!input.payload || typeof input.payload !== 'object' || Array.isArray(input.payload))
    throw new TypeError('A inferência não retornou uma resposta estruturada.');
  const payload = input.payload as AtlasAiChatInferencePayloadV1;
  const inference = payload.inference && typeof payload.inference === 'object' && !Array.isArray(payload.inference)
    ? payload.inference as Record<string, unknown>
    : null;
  const systemModel = inference?.systemModel;
  const jev = inference?.jev && typeof inference.jev === 'object' && !Array.isArray(inference.jev)
    ? inference.jev as Record<string, unknown>
    : null;
  const calls = Array.isArray(payload.toolCalls) ? payload.toolCalls : [];
  return {
    payload,
    answerText: String(payload.text || 'Ação preparada.'),
    telemetry: inference ? {
      endpoint: String(inference.endpoint || input.endpoint),
      systemModel: String(systemModel && typeof systemModel === 'object' && !Array.isArray(systemModel)
        ? (systemModel as Record<string, unknown>).id || ''
        : systemModel || ''),
      ...(jev?.choice ? { choice: String(jev.choice) } : {}),
      ...(jev?.error ? { error: String(jev.error).slice(0, 240) } : {}),
    } : null,
    visionDetected: Boolean(payload.vision),
    toolCalls: calls.filter((call): call is AtlasAiChatToolCallV1 =>
      Boolean(call && typeof call === 'object' && !Array.isArray(call))),
  };
}

export interface AtlasAiChatAttachmentActionsProjectionV1 {
  attachment: AtlasAiChatInferenceAttachmentReferenceV1;
  recordOcrAvailable: boolean;
  allocation: Record<string, unknown> | null;
  allocationTarget: 'material' | 'service' | 'office';
  destinationLabel: 'Materiais' | 'Serviços' | 'Escritório';
  allocationTitle: string;
  allocationStageName: string;
  presentation: 'upload-required' | 'allocated' | 'review';
}

/** Project attachment/OCR inference into the states displayed by the chat component. */
export function projectAtlasAiChatAttachmentActionsV1(
  payload: AtlasAiChatInferencePayloadV1,
): AtlasAiChatAttachmentActionsProjectionV1 | null {
  const attachment = payload?.attachment;
  if (!attachment) return null;
  const allocationCall = (Array.isArray(payload.toolCalls) ? payload.toolCalls : [])
    .find((call: any) => String(call?.name || '') === 'stage.allocate_visual_record');
  const allocation = allocationCall?.arguments && typeof allocationCall.arguments === 'object' && !Array.isArray(allocationCall.arguments)
    ? allocationCall.arguments as Record<string, unknown>
    : null;
  const allocationTarget = allocation?.target === 'office' ? 'office' : allocation?.target === 'material' ? 'material' : 'service';
  const destinationLabel = allocationTarget === 'material' ? 'Materiais' : allocationTarget==='office'?'Escritório':'Serviços';
  const allocationTitle = String(
    allocationTarget === 'material'
      ? allocation?.materialName || allocation?.activityName || 'Item reconhecido'
      : allocation?.activityName || 'Serviço reconhecido',
  ).trim();
  const allocationStageName = String(allocation?.stageName || 'Etapa a confirmar').trim();
  const recordOcrAvailable = Boolean(payload.recordOcr);
  return {
    attachment,
    recordOcrAvailable,
    allocation,
    allocationTarget,
    destinationLabel,
    allocationTitle,
    allocationStageName,
    presentation: !attachment.stored && !recordOcrAvailable
      ? 'upload-required'
      : allocation ? 'allocated' : 'review',
  };
}

export function applyAtlasAiChatAttachmentActionV1(input: {
  projection: AtlasAiChatAttachmentActionsProjectionV1;
  purpose: 'record' | 'proof';
  ports: Pick<AtlasAiChatPortsV1, 'state' | 'projectContext' | 'records'>;
}): { notification: string; tone: 'success' } {
  const { projection, ports } = input;
  const state = ports.state.get();
  const activities = Array.isArray(ports.projectContext.activities)
    ? ports.projectContext.activities : [];
  const executionModel = ports.projectContext.executionModel || {};
  const executionStages = Array.isArray(executionModel.stages) ? executionModel.stages : [];
  const allocation = projection.allocation;
  const stage = allocation
    ? executionStages.find((item: Record<string, any>) => String(item.key) === String(allocation.stageKey || '')) ||
      executionStages.find((item: Record<string, any>) =>
        ports.records.normalizeStageRecord(item.name) === ports.records.normalizeStageRecord(allocation.stageName))
    : activities.find((item: Record<string, any>) => item.id === state.selectedStage);
  const purpose = input.purpose === 'proof' ? 'comprovação' : 'registro';

  if (allocation && input.purpose === 'record' && stage) {
    const attachmentMatches = (item: Record<string, any>): boolean => {
      const attachments = ports.records.readStageRecordAttachments(item);
      return Array.isArray(attachments) && attachments.some((itemAttachment: Record<string, any>) =>
        String(itemAttachment.label || '') === String(projection.attachment.name || ''));
    };
    const material = projection.allocationTarget === 'material'
      ? (state.materialCatalogAdditions || []).find((item: Record<string, any>) =>
          String(item.stageKey || '') === String(stage.key) && attachmentMatches(item))
      : null;
    const service = projection.allocationTarget === 'service'
      ? (state.records || []).find((item: Record<string, any>) =>
          String(item.stageKey || '') === String(stage.key) &&
          String(item.allocationTarget || '') === 'service' && attachmentMatches(item))
      : null;
    const itemKey = material?.id || (service?.id ? `service:${service.id}` : '');
    ports.state.set({
      view: 'stages',
      sidebarCollapsed: false,
      selectedStageV9: stage.key,
      selectedStage: stage.key,
      stageSelected: true,
      controlStageCenterTab: projection.allocationTarget === 'material' ? 'materials' : 'services',
      controlStageCenterItemModalKey: itemKey || null,
      lastAction: `Abriu a revisão de ${projection.allocationTitle} em ${stage.name}`,
    });
    return { notification: `Abrindo ${projection.destinationLabel} da etapa ${stage.name} para revisão.`, tone: 'success' };
  }

  ports.state.set({
    view: 'records',
    sidebarCollapsed: true,
    editingRecord: 'new',
    recordContext: {
      stage: stage?.name || '',
      activity: state.selectedActivity || '',
      label: `Imagem protegida · ${purpose}`,
      attachmentRef: projection.attachment,
      evidencePurpose: purpose,
    },
    lastAction: `Preparou imagem para ${purpose}`,
  });
  return { notification: `Imagem preparada como ${purpose}. Revise e confirme o formulário.`, tone: 'success' };
}

export interface AtlasAiChatInferenceCycleEffectsV1 {
  presentResponse(response: AtlasAiChatInferenceResponseProjectionV1): void | Promise<void>;
  executeToolCalls(
    calls: readonly AtlasAiChatToolCallV1[],
    context: Record<string, unknown>,
  ): Promise<string[]>;
}

export interface AtlasAiChatInferenceCycleInputV1 {
  ports: Pick<AtlasAiChatPortsV1, 'assistant' | 'chat' | 'state'>;
  message: string;
  mapContext: boolean;
  requestContext?: Record<string, unknown> | null;
  context: AtlasAiChatToolContextV1;
  attachment?: AtlasAiChatInferenceExecutionInputV1['attachment'];
  effects: AtlasAiChatInferenceCycleEffectsV1;
}

/** Coordinate inference, response presentation, tool dispatch, and the resulting app action. */
export async function runAtlasAiChatInferenceCycleV1(input: AtlasAiChatInferenceCycleInputV1): Promise<{
  response: AtlasAiChatInferenceResponseProjectionV1;
  executed: string[];
}> {
  const { endpoint, payload } = await requestAtlasAiChatInferenceV1(input);
  const response = projectAtlasAiChatInferenceResponseV1({ endpoint, payload });
  await input.effects.presentResponse(response);
  const executed = await input.effects.executeToolCalls(response.toolCalls, {
    payload: response.payload,
    sourceAttachment: input.attachment || null,
  });
  if (executed.length)
    input.ports.state.set({ lastAction: `IA executou ${executed.length} ferramenta(s)` });
  return { response, executed };
}

