/** Persist OCR/chat evidence as a pending operational record using typed application ports. */
export async function allocateAtlasWorkerContextChatVisualRecordV1(input: {
  args?: AtlasWorkerContextChatVisualAllocationArgumentsV1;
  context?: AtlasWorkerContextChatVisualRecordAllocationContextV1;
  ports: AtlasWorkerContextChatVisualRecordAllocationPortsV1;
}): Promise<string> {
  const args = normalizeAtlasWorkerContextChatVisualAllocationArgumentsV1(input.args || {});
  const context = input.context || {};
  const ports = input.ports;
  const executionStages = Array.isArray(ports.executionModel?.stages) ? ports.executionModel.stages : [];
  const destinations=(stageDestinationsCatalogData as {destinations?:Array<{key?:string;name?:string;description?:string}>}).destinations||[];
  const stages=[...executionStages,...destinations.filter(destination=>!executionStages.some(stage=>String(stage.key||'')===String(destination.key||''))).map(destination=>({
    key:String(destination.key||''),name:String(destination.name||''),description:String(destination.description||''),activities:[],materials:[],production:{unit:'registro administrativo'}
  }))];
  const normalizedStageKey = String(args.stageKey || '').trim();
  const normalizedStageName = normalizeAtlasWorkerContextChatStageTextV1(args.stageName);
  const stage = stages.find(item => String(item.key || '') === normalizedStageKey) ||
    (normalizedStageName ? stages.find(item => normalizeAtlasWorkerContextChatStageTextV1(item.name) === normalizedStageName) : null);
  if (!stage) {
    const question = 'Não consegui encaixar esta descrição com segurança em uma etapa. Qual etapa ou atividade deve receber este item?';
    ports.addFeedback(question, 'question');
    return question;
  }

  const target = args.target;
  const sourceAttachment = context.sourceAttachment || context.payload?.attachment || null;
  const sourceName = String(sourceAttachment?.name || 'anexo visual').trim();
  let storedAttachment = (Array.isArray(context.serviceRequest?.files) ? context.serviceRequest.files : [])
    .find(file => String(file.fileName || file.name || '').trim() === sourceName) || null;
  if (!storedAttachment && sourceAttachment?.dataUrl && stage.key) {
    try {
      const persisted = await ports.persistVisualAttachment({
        stageKey: String(stage.key),
        activityKey: String(args.activityId || (stage.key==='office'?'office-note':args.materialName) || 'ocr'),
        target: target === 'material' ? 'material-proof' : 'service-proof',
        title: `OCR · ${sourceName}`,
        notes: 'Arquivo original recebido pelo assistente operacional para revisão humana.',
        fileName: sourceName,
        dataUrl: sourceAttachment.dataUrl,
      });
      storedAttachment = mapRecord(persisted);
    } catch (error) {
      ports.warn?.('Não foi possível persistir o anexo da leitura visual:', error);
    }
  }
  const sourceFileUrl = String(storedAttachment?.fileUrl || storedAttachment?.url || storedAttachment?.reference || '').trim();
  if (sourceAttachment && !sourceFileUrl) {
    const message = 'O registro não foi criado: a foto não pôde ser persistida. Tente novamente com conexão ativa.';
    ports.addFeedback(message, 'warning');
    return message;
  }

  const now = ports.now();
  const activityName = String(args.activityName || '').trim().slice(0, 160);
  const materialName = String(args.materialName || '').trim().slice(0, 160);
  const title = target === 'material'
    ? materialName || activityName || 'Material identificado na leitura visual'
    : target === 'office'
      ? activityName || materialName || 'Documento administrativo identificado na leitura visual'
    : activityName || 'Serviço identificado na leitura visual';
  const details = String(args.details || 'Leitura visual recebida pelo assistente operacional.').trim().slice(0, 4000);
  const pointer = String(args.pointer || '').trim().slice(0, 1200);
  const quantity = args.quantity == null || args.quantity === ''
    ? null
    : Number.isFinite(Number(args.quantity)) ? Number(args.quantity) : null;
  const confidence = Number.isFinite(Number(args.confidence)) && Number(args.confidence) > 0
    ? Math.round(Number(args.confidence) * 100)
    : null;
  const production = mapRecord(stage.production) || {};
  const unit = String(args.unit || (target === 'material' ? production.unit || 'un.' : target==='office'?'registro administrativo':'registro')).trim().slice(0, 40);
  const properties: AtlasWorkerContextChatVisualRecordPropertyV1[] = [
    { id: 'allocation_target', label: 'Destino da leitura visual', type: 'text', value: target === 'material' ? 'Materiais' : target==='office'?'Escritório':'Serviços' },
    { id: 'allocation_source', label: 'Origem', type: 'text', value: 'Assistente operacional · leitura visual no chat' },
    { id: 'allocation_stage_key', label: 'Chave da etapa', type: 'text', value: String(stage.key || '') },
    { id: 'allocation_stage', label: 'Etapa associada', type: 'text', value: String(stage.name || '') },
    { id: 'allocation_activity_id', label: 'ID da atividade', type: 'text', value: String(args.activityId || '') || 'Não informado' },
    { id: 'allocation_activity', label: 'Atividade / serviço', type: 'text', value: activityName || 'Não informado' },
    { id: 'allocation_material', label: 'Material / equipamento', type: 'text', value: materialName || 'Não informado' },
    { id: 'allocation_quantity', label: 'Quantidade identificada', type: 'number', value: quantity == null ? 'Não informado' : quantity },
    { id: 'allocation_unit', label: 'Unidade identificada', type: 'text', value: unit || 'Não informado' },
    { id: 'allocation_pointer', label: 'Apontamento que sustentou a alocação', type: 'text', value: pointer || details },
    { id: 'allocation_confidence', label: 'Confiança da leitura', type: 'text', value: confidence == null ? 'Não informado' : `${confidence}%` },
    { id: 'allocation_attachment', label: 'Anexo analisado', type: 'text', value: sourceName },
    { id: 'allocation_attachment_url', label: 'Arquivo persistido', type: 'text', value: sourceFileUrl },
    { id: 'allocation_attachment_mime', label: 'Tipo do arquivo', type: 'text', value: String(storedAttachment?.mimeType || sourceAttachment?.mimeType || '') },
  ];
  const localId = `REG-VIS-${now.getTime().toString(36).toUpperCase()}`;
  const payload: AtlasWorkerContextChatVisualRecordCreateV1 = {
    id: localId,
    obra: 'Aliança Park',
    etapa: String(stage.name || ''),
    stageKey: String(stage.key || ''),
    stageName: String(stage.name || ''),
    atividade: target === 'material' ? `Material: ${title}` : target==='office'?`Nota / atividade administrativa: ${title}`:title,
    activityId: String(args.activityId || '').trim(),
    responsavel: String(ports.state.get().currentActor?.name || ports.state.get().currentActor?.displayName || '').trim(),
    data: now.toISOString().slice(0, 10),
    hora: now.toTimeString().slice(0, 5),
    detalhes: [details, pointer ? `Indicação visual: ${pointer}` : '', `Anexo analisado: ${sourceName}`].filter(Boolean).join('\n'),
    status: 'Pendente',
    progresso: 0,
    unit,
    quantity,
    allocationTarget: target,
    source: 'chat-visual',
    properties,
    attachments: sourceAttachment ? [{
      name: sourceName,
      fileName: sourceName,
      label: sourceName,
      mimeType: String(storedAttachment?.mimeType || sourceAttachment.mimeType || 'image/*'),
      fileUrl: sourceFileUrl,
      url: sourceFileUrl,
      notes: 'Arquivo original salvo na solicitação vinculada',
    }] : [],
    evidenceUri: '',
  };
  let saved: Record<string, unknown>;
  try {
    saved = mapRecord(await ports.createRecord(payload)) || {};
  } catch (error) {
    const message = `O registro não foi criado no banco: ${error instanceof Error ? error.message : String(error)}`;
    ports.addFeedback(message, 'warning');
    return message;
  }
  const record = {
    ...saved,
    ...payload,
    id: saved.id || localId,
    properties: saved.properties || properties,
    attachments: payload.attachments,
    pendingPersistence: false,
  };
  const materialAddition = target === 'material' ? {
    id: `AI-MATERIAL-${record.id}`,
    name: materialName || title,
    scope: details,
    quantity,
    unit,
    status: 'Pendente',
    stageKey: stage.key,
    stageName: stage.name,
    activityName: activityName || 'Leitura visual do chat',
    source: 'chat-visual',
    sourceRecordId: record.id,
    properties,
    attachments: record.attachments,
    updatedAt: now.toISOString(),
  } : null;
  ports.state.update(current => ({
    ...current,
    records: [record, ...(current.records || []).filter((item: Record<string, unknown>) => item.id !== record.id)],
    materialCatalogAdditions: materialAddition
      ? [materialAddition, ...(current.materialCatalogAdditions || []).filter((item: Record<string, unknown>) => item.id !== materialAddition.id)]
      : current.materialCatalogAdditions || [],
    lastAction: `Alocou leitura visual em ${target === 'material' ? 'Materiais' : target==='office'?'Escritório':'Serviços'} · ${String(stage.name || '')}`,
  }));
  try {
    await ports.refreshCalendar();
  } catch (error) {
    ports.addFeedback(`Registro salvo, mas a agenda precisa ser sincronizada: ${error instanceof Error ? error.message : String(error)}`, 'warning');
  }
  const destination = target === 'material' ? 'Materiais' : target==='office'?'Escritório':'Serviços';
  ports.addFeedback(`Leitura visual alocada em ${destination} · ${String(stage.name || '')} · ${title}. Status: Pendente para revisão humana.`, 'pending');
  return `Alocou a leitura visual em ${destination} na etapa ${String(stage.name || '')}, com status Pendente para revisão humana.`;
}

export type AtlasAiChatApplicationHostV1 = typeof globalThis & {
  __BELAVISTA_LOT_DEVELOPMENT_PROFILES_V1: AtlasAiChatPortFunctionV1;
  __BELAVISTA_UPSERT_LOT_DEVELOPMENT_PROFILE_V1: AtlasAiChatPortFunctionV1;
  __BELAVISTA_ALLOCATE_VISUAL_RECORD_V1: AtlasAiChatPortFunctionV1;
  window: Window & typeof globalThis & { lucide?: { createIcons: () => void } };
  lucide?: { createIcons: () => void };
  RubyOperationalAssistant?: { infer: (request: { endpoint: string; body: unknown }) => Promise<unknown> } | null;
};

const isAtlasAiChatRecordV1 = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

/** Compose the administrative chat ports and TS component from application services. */
export function createAtlasAiChatApplicationV1(input: {
  host: AtlasAiChatApplicationHostV1;
  services: AtlasAiChatApplicationServicesV1;
}): CustomElementConstructor {
  const { host, services } = input;
  if (!host || !services) throw new TypeError('AI chat application composition requires host and services.');
  const storage = services.storage;
  for (const method of ['getItem', 'setItem', 'removeItem'] as const)
    if (typeof storage?.[method] !== 'function') throw new TypeError(`AI chat storage requires storage.${method}().`);
  const appStore = services.appStore;
  for (const method of ['get', 'set', 'update', 'subscribe'] as const)
    if (typeof appStore?.[method] !== 'function') throw new TypeError(`AI chat state requires appStore.${method}().`);
  for (const [name, value] of Object.entries({
    apiFetch: services.apiFetch,
    operationalHeaders: services.operationalHeaders,
  })) if (typeof value !== 'function') throw new TypeError(`AI chat application service requires ${name}().`);
  if (services.operationalAssistant != null && typeof services.operationalAssistant.infer !== 'function')
    throw new TypeError('AI chat application service requires operationalAssistant.infer().');

  const view = host.window || host;
  if (typeof view.lucide?.createIcons !== 'function')
    throw new TypeError('AI chat browser adapter requires lucide.createIcons().');
  const browser: AtlasAiChatComponentBrowserV1 = {
    eventTarget: host as EventTarget,
    document: host.document,
    HTMLElement: host.HTMLElement,
    FileReader: host.FileReader,
    speechSynthesis: view.speechSynthesis || null,
    SpeechSynthesisUtterance: view.SpeechSynthesisUtterance || null,
    createIcons: view.lucide.createIcons.bind(view.lucide),
    print: typeof view.print === 'function' ? view.print.bind(view) : null,
    setTimeout: host.setTimeout.bind(host),
    clearTimeout: host.clearTimeout.bind(host),
    requestAnimationFrame: host.requestAnimationFrame.bind(host),
  };

  const historyKey = String(aiChatStorageData.historyKey);
  const layoutKey = String(aiChatStorageData.layoutKey);
  const voiceKey = String(aiChatStorageData.voiceKey);
  const historyLimit = Number(aiChatStorageData.historyLimit);
  const readJson = (key: string, fallback: unknown): unknown => {
    try { return JSON.parse(storage.getItem(key) || JSON.stringify(fallback)); }
    catch { return fallback; }
  };
  const writeJson = (key: string, value: unknown): void => {
    try { storage.setItem(key, JSON.stringify(value)); } catch {}
  };
  const storagePort: AtlasAiChatStoragePortV1 = Object.freeze({
    CHAT_HISTORY_STORAGE_KEY: historyKey,
    CHAT_VOICE_STORAGE_KEY_V1: voiceKey,
    readChatHistory: () => {
      const value = readJson(historyKey, []);
      return Array.isArray(value)
        ? value.filter((item): item is Record<string, unknown> & { text: string } =>
            isAtlasAiChatRecordV1(item) && typeof item.text === 'string')
          .slice(-historyLimit)
        : [];
    },
    writeChatHistory: history => writeJson(historyKey, Array.isArray(history) ? history.slice(-historyLimit) : []),
    clearChatHistory: () => { try { storage.removeItem(historyKey); } catch {} },
    readChatWindowLayout: () => {
      const value = readJson(layoutKey, null);
      if (!isAtlasAiChatRecordV1(value)) return null;
      const numberField = (key: 'left' | 'top' | 'width' | 'height'): number | undefined =>
        typeof value[key] === 'number' && Number.isFinite(value[key]) ? value[key] as number : undefined;
      return {
        left: numberField('left'),
        top: numberField('top'),
        width: numberField('width'),
        height: numberField('height'),
        collapsed: Boolean(value.collapsed),
      };
    },
    writeChatWindowLayout: layout => writeJson(layoutKey, layout),
    readChatVoiceEnabled: () => { try { return storage.getItem(voiceKey) === '1'; } catch { return false; } },
    writeChatVoiceEnabled: enabled => { try { storage.setItem(voiceKey, enabled ? '1' : '0'); } catch {} },
  });
  const apiFetch = services.apiFetch;
  const basePorts: Omit<AtlasAiChatPortsV1, 'visualAllocation'> = {
    chat: services.policies,
    storage: storagePort,
    agenda: services.agenda,
    state: Object.freeze({
      get: () => appStore.get(),
      set: (patch: Record<string, any>) => appStore.set(patch),
      update: (updater: (state: Record<string, any>) => Record<string, any>) => appStore.update(state => updater(state) as AtlasApplicationInitialState),
      subscribe: (listener: (state: Record<string, any>) => void) => appStore.subscribe(state => listener(state)),
    }),
    componentState: Object.freeze({
      readState: () => appStore.get(),
      subscribe: (listener: (state: Record<string, any>) => void) => appStore.subscribe(state => listener(state)),
      onAction: (action: Parameters<typeof applyAtlasAiChatComponentActionV1>[0]['action']) => applyAtlasAiChatComponentActionV1({ action, appStore }),
    }),
    projectContext: Object.freeze({
      metrics: services.demoData.metrics,
      activities: services.demoData.activities,
      executionModel: services.executionModel,
    }),
    assistant: Object.freeze({
      infer: async ({ modelRequest, httpRequest }: AtlasAiChatInferenceRequestV1 = {}) => {
        if (!modelRequest || typeof modelRequest.endpoint !== 'string' || !modelRequest.body)
          throw new TypeError('AI chat inference requires a model request endpoint and body.');
        if (!httpRequest || typeof httpRequest.endpoint !== 'string' || !httpRequest.init)
          throw new TypeError('AI chat inference requires an HTTP fallback endpoint and init.');
        if (services.operationalAssistant) return services.operationalAssistant.infer({ endpoint: modelRequest.endpoint, body: modelRequest.body });
        const response = await apiFetch(httpRequest.endpoint, httpRequest.init);
        if (!response.ok) {
          const payload = await response.json().catch(() => ({})) as { error?: unknown };
          throw new Error(String(payload.error || `HTTP ${response.status}`));
        }
        return response.json();
      },
    }),
    recordPersistence: Object.freeze({
      async persistVisualAttachment({ stageKey, activityKey, target, title, notes, fileName, dataUrl }: AtlasAiChatVisualAttachmentInputV1) {
        const query = `stage=${encodeURIComponent(String(stageKey || ''))}&activity=${encodeURIComponent(String(activityKey || 'ocr'))}`;
        const response = await apiFetch(`/api/workbench/attachments?${query}`, {
          method: 'POST', headers: services.operationalHeaders({ 'Content-Type': 'application/json' }),
          body: JSON.stringify({ kind: target, title, notes, fileName, dataUrl }),
        });
        if (!response.ok) return null;
        const payload = await response.json() as { attachment?: unknown };
        return payload.attachment || null;
      },
      async createRecord(record: Record<string, unknown>) {
        const response = await apiFetch('/api/records', {
          method: 'POST', headers: services.operationalHeaders({ 'Content-Type': 'application/json' }),
          body: JSON.stringify(record),
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      },
    }),
    commands: Object.freeze({
      parseLotStatusCommand: (message: unknown) => parseAtlasLotStatusCommandV1(message),
      applyLotStatusCommand: (command: unknown) => applyAtlasLotStatusCommandV1(appStore, command, {
        renderBrokerBoard: services.workspace?.renderBrokerBoard,
        documentRef: host.document,
      }),
    }),
    events: Object.freeze({ createServiceEventAdministrators }),
    map: Object.freeze({ commonAreaLabel: services.commonAreaLabel }),
    records: services.records,
    ui: services.ui,
  };
  const ports: AtlasAiChatPortsV1 = {
    ...basePorts,
    visualAllocation: Object.freeze({
      allocateRecord: (args, context, addFeedback) => allocateAtlasWorkerContextChatVisualRecordV1({
        args,
        context,
        ports: {
          executionModel: services.executionModel as { stages?: Array<Record<string, unknown>> },
          state: basePorts.state,
          persistVisualAttachment: value => basePorts.recordPersistence.persistVisualAttachment(value),
          createRecord: value => basePorts.recordPersistence.createRecord(value),
          refreshCalendar: () => Promise.resolve(basePorts.agenda.refreshCalendar()),
          now: () => new host.Date(),
          addFeedback,
          warn: (message, error) => host.console?.warn?.(message, error),
        },
      }),
    }),
  };
  const dependencies = createAtlasAiChatDependenciesV1({ browser, ports });
  host.__BELAVISTA_ALLOCATE_VISUAL_RECORD_V1 = (args: Record<string, unknown> = {}, context: Record<string, unknown> = {}, feedback: (message: string) => void = () => {}) =>
    dependencies.ports.visualAllocation.allocateRecord(
      args as AtlasWorkerContextChatVisualAllocationArgumentsV1,
      context as AtlasWorkerContextChatVisualRecordAllocationContextV1,
      feedback,
    );
  return createAtlasAiChatV1({
    ...dependencies,
    browser,
  });
}

export interface AtlasAdminAiChatRegistrationInputV1 {
  host: AtlasAiChatApplicationHostV1;
  appStore: AtlasAiChatPortsV1['state'];
  demoData: { metrics: Record<string, unknown>; activities: Array<Record<string, unknown>> };
  executionModel: Record<string, unknown>;
  apiFetch: (endpoint: string, init?: RequestInit) => Promise<Response>;
  operationalHeaders: (headers?: Record<string, string>) => HeadersInit;
  agendaCalendar: {
    lastAvailableSlot: AtlasAgendaCalendarProgramV1['agendaCalendarLastAvailableSlotV8'];
    parseDate: AtlasAgendaCalendarProgramV1['agendaCalendarParseDateV3'];
    read: AtlasAgendaCalendarProgramV1['agendaCalendarReadV3'];
    weekKey: AtlasAgendaCalendarProgramV1['agendaCalendarWeekKeyV8'];
    write: AtlasAgendaCalendarProgramV1['agendaCalendarWriteV3'];
    normalizeActivityRouteText: AtlasAiChatAgendaPortV1['normalizeActivityRouteText'];
  };
  stageRecords: {
    attachments: (record: Record<string, unknown>) => AtlasStageRecordAttachmentV1[];
    normalize: (value: unknown) => string;
  };
  ui: AtlasAiChatUiPortV1;
  policies: AtlasAiChatPortsV1['chat'];
  commands?: AtlasAiChatApplicationServicesV1['commands'];
  commonAreaLabel: string;
}

/** Register the chat Web Element and bind its operational services through the TS program. */
export function registerAtlasAdminAiChatV1(input: AtlasAdminAiChatRegistrationInputV1): CustomElementConstructor {
  const {
    host, appStore, demoData, executionModel, apiFetch, operationalHeaders,
    agendaCalendar, stageRecords, ui, policies, commonAreaLabel,
  } = input;
  const refreshAgendaCalendar = async (): Promise<OperationalAgendaEvent[]> => {
    const response = await apiFetch('/api/agenda-events', { cache: 'no-store' });
    const payload = await response.json();
    if (!response.ok || !Array.isArray(payload.events)) throw new Error(payload.error || `HTTP ${response.status}`);
    appStore.set({
      agendaDatabaseEventsV3: payload.events,
      agendaCalendarLoadedV3: true,
      agendaCalendarErrorV3: '',
      agendaCalendarRevisionV3: Date.now(),
    });
    return payload.events;
  };
  const executionStages = Array.isArray((executionModel as { stages?: unknown }).stages)
    ? (executionModel as { stages: AtlasAgendaCalendarStageV1[] }).stages.map(stage => {
      const workbench = WORKER_STAGE_WORKBENCH_CATALOG_V1.find(item => item.key === String(stage.key || ''));
      return {
        ...stage,
        activities: Array.isArray(stage.activities) && stage.activities.length ? stage.activities : workbench?.activities || [],
      };
    })
    : [];
  const agenda: AtlasAiChatAgendaPortV1 = {
    findLastAvailableSlot: agendaCalendar.lastAvailableSlot,
    parseDate: agendaCalendar.parseDate,
    readCalendar: agendaCalendar.read,
    weekKey: agendaCalendar.weekKey,
    writeCalendar: agendaCalendar.write,
    refreshCalendar: refreshAgendaCalendar,
    normalizeActivityRouteText: agendaCalendar.normalizeActivityRouteText,
    createPendingAgenda: proposal => createAtlasAiChatAgendaPendingCommandV1({
      proposal,
      appStore,
      executionStages,
      agenda: {
        findLastAvailableSlot: agendaCalendar.lastAvailableSlot,
        parseDate: agendaCalendar.parseDate,
        readCalendar: agendaCalendar.read,
        weekKey: agendaCalendar.weekKey,
        writeCalendar: agendaCalendar.write,
        refreshCalendar: refreshAgendaCalendar,
        normalizeActivityRouteText: agendaCalendar.normalizeActivityRouteText,
      },
      now: () => new host.Date(),
    }),
  };
  const AiChat = createAtlasAiChatApplicationV1({
    host,
    services: {
      policies,
      storage: host.localStorage,
      apiFetch,
      operationalHeaders,
      operationalAssistant: host.RubyOperationalAssistant,
      appStore,
      demoData,
      executionModel,
      agenda,
      commonAreaLabel,
      records: {
        listLotDevelopmentProfiles: host.__BELAVISTA_LOT_DEVELOPMENT_PROFILES_V1,
        readStageRecordAttachments: stageRecords.attachments,
        normalizeStageRecord: stageRecords.normalize,
        saveLotDevelopmentProfile: host.__BELAVISTA_UPSERT_LOT_DEVELOPMENT_PROFILE_V1,
      },
      ui,
      workspace: {
        renderBrokerBoard: () => host.document.querySelector<HTMLElement & { render?: () => unknown }>('view-layer')?.render?.(),
      },
    },
  });
  const registry = host.customElements as CustomElementRegistry | undefined;
  if (!registry) throw new TypeError('Administrative AI chat requires customElements.');
  if (!registry.get('ai-chat')) registry.define('ai-chat', AiChat);
  return AiChat;
}

export function normalizeAiAgendaComprehensionV1(value: unknown = {}): AiAgendaComprehensionV1 {
  const source = value && typeof value === 'object' ? value as Partial<AiAgendaComprehensionV1> : {};
  return {
    reading: String(source.reading ?? AI_AGENDA_COMPREHENSION_DEFAULTS_V1.reading).trim().slice(0, 1200),
    determination: String(source.determination ?? AI_AGENDA_COMPREHENSION_DEFAULTS_V1.determination).trim().slice(0, 1200),
    generation: String(source.generation ?? AI_AGENDA_COMPREHENSION_DEFAULTS_V1.generation).trim().slice(0, 1200),
    autoCreatePending: source.autoCreatePending !== false,
  };
}

/** Resolve, persist, and publish the administrative chat's AI-proposed agenda commitment. */
export async function createAtlasAiChatAgendaPendingCommandV1(input: {
  proposal: AtlasAgendaPendingProposalV1;
  appStore: AtlasAiChatPortsV1['state'];
  executionStages: AtlasAgendaCalendarStageV1[];
  agenda: Pick<AtlasAiChatAgendaPortV1,
    'findLastAvailableSlot' | 'parseDate' | 'readCalendar' | 'weekKey' | 'writeCalendar' | 'refreshCalendar' | 'normalizeActivityRouteText'>;
  now: () => Date;
}): Promise<AtlasAiChatAgendaPendingCommandResultV1> {
  const proposal = input.proposal;
  const state = input.appStore.get();
  if (!normalizeAiAgendaComprehensionV1(state.aiAgendaComprehensionV1).autoCreatePending)
    return { ok: false, reason: 'disabled', message: 'A criação de apontamentos pela IA está desativada em Configurações.' };

  const stageKey = proposal.stageKey;
  const stageName = proposal.stageName;
  const normalizedStageName = input.agenda.normalizeActivityRouteText(stageName);
  const stage = input.executionStages.find(item => String(item.key || '') === stageKey)
    || (normalizedStageName ? input.executionStages.find(item => input.agenda.normalizeActivityRouteText(String(item.name || '')) === normalizedStageName) : undefined);
  if (!stage)
    return { ok: false, reason: 'stage', message: 'A IA precisa confirmar a etapa antes de criar o apontamento na agenda.' };

  const normalize = input.agenda.normalizeActivityRouteText;
  const activityRows = (Array.isArray(stage.activities) ? stage.activities : []).map(value => {
    const row = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const id = String(row.id || row.key || row.title || row.name || '').trim();
    const title = String(row.title || row.name || row.id || '').trim();
    const materials = (Array.isArray(row.materials) ? row.materials : []).map(materialValue => {
      const material = materialValue && typeof materialValue === 'object' && !Array.isArray(materialValue) ? materialValue : {};
      const name = String(material.name || material.title || material.materialName || material.description || (typeof materialValue === 'string' ? materialValue : '')).trim();
      const id = String(material.id || material.key || material.materialId || name).trim();
      return name ? { id, name } : null;
    }).filter((value): value is { id: string; name: string } => Boolean(value));
    return { id, title, materials };
  }).filter(item => item.id && item.title);
  const requestedActivity = String(proposal.activityId || proposal.activityName || proposal.title || '').trim();
  const requestedActivityKey = normalize(requestedActivity);
  const activity = activityRows.find(item => item.id === proposal.activityId)
    || activityRows.find(item => normalize(item.title) === requestedActivityKey);
  if (!activity)
    return { ok: false, reason: 'activity', message: `A etapa ${String(stage.name || stage.key)} está identificada, mas a atividade "${requestedActivity || 'não informada'}" não corresponde ao catálogo dessa etapa. Confirme uma atividade cadastrada.` };

  const stageMaterialRows = (Array.isArray(stage.materials) ? stage.materials : []).map(value => {
    const row = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
    const name = String(row.name || row.title || row.materialName || row.description || (typeof value === 'string' ? value : '')).trim();
    const id = String(row.id || row.key || row.materialId || name).trim();
    return name ? { id, name } : null;
  }).filter((value): value is { id: string; name: string } => Boolean(value));
  const knownMaterials = activity.materials.length ? activity.materials : stageMaterialRows;
  const materialReferences = [...new Set(proposal.materialIds.map(value => String(value || '').trim()).filter(Boolean))];
  const chosenMaterials = materialReferences.length ? materialReferences : knownMaterials.map(item => item.id || item.name);
  const materialIds: string[] = [];
  for (const reference of chosenMaterials) {
    const token = normalize(reference);
    const exact = knownMaterials.filter(item => item.id === reference || normalize(item.name) === token || normalize(item.id) === token);
    const candidates = exact.length ? exact : token.length >= 4
      ? knownMaterials.filter(item => normalize(item.name).includes(token) || token.includes(normalize(item.name)))
      : [];
    if (candidates.length !== 1)
      return { ok: false, reason: 'material', message: `O material "${reference}" não foi associado sem ambiguidade à atividade ${activity.title}. Revise a lista de materiais dessa atividade.` };
    materialIds.push(candidates[0].id || candidates[0].name);
  }
  const canonicalProposal: AtlasAgendaPendingProposalV1 = {
    ...proposal,
    activityId: activity.id,
    activityName: activity.title,
    materialIds,
  };

  try { await input.agenda.refreshCalendar(); }
  catch (error) {
    return { ok: false, reason: 'read', message: `Não foi possível carregar a agenda: ${error instanceof Error ? error.message : String(error)}` };
  }

  const events = [...(input.agenda.readCalendar().events || [])];
  const requestedDate = proposal.date;
  const parsedDate = input.agenda.parseDate(requestedDate);
  const baseWeek = input.agenda.weekKey(parsedDate || input.now());
  const slot = input.agenda.findLastAvailableSlot(events, baseWeek);
  const date = parsedDate ? requestedDate : slot.date;
  const requestedStart = proposal.start;
  const start = /^\d{2}:\d{2}$/.test(requestedStart) ? requestedStart : slot.start;
  const timestamp = input.now();
  const event = projectAtlasAgendaPendingEventV1({
    proposal: canonicalProposal,
    id: `agenda-ai-${timestamp.getTime().toString(36)}`,
    stageKey: String(stage.key || ''),
    stageName: String(stage.name || ''),
    date,
    start,
  });
  const title = event.title;

  try {
    await input.agenda.writeCalendar({ version: 3, initialized: true, events: [...events, event] });
  } catch (error) {
    return { ok: false, reason: 'write', message: `Não foi possível salvar o compromisso na agenda: ${error instanceof Error ? error.message : String(error)}` };
  }

  const agendaItem = projectAtlasAgendaCalendarItemV1(event);
  input.appStore.set({
    view: 'agenda',
    selectedStageV9: stage.key,
    selectedStage: stage.key,
    selectedAgendaEventV3: event.id,
    operationalAgenda: [
      ...((state.operationalAgenda || []) as OperationalAgendaEvent[]).filter(item => String(item?.id || '') !== event.id),
      agendaItem,
    ],
    agendaCalendarRevisionV3: timestamp.getTime(),
    agendaCalendarRevisionV7: timestamp.getTime(),
    agendaCalendarWeekV8: input.agenda.weekKey(date),
    lastAction: `IA criou apontamento pendente ${title} em ${String(stage.name || '')}`,
  });
  return {
    ok: true,
    event,
    message: `Criou apontamento pendente na agenda de ${String(stage.name || '')} e abriu para completar os dados.`,
  };
}

/** Execute administrative chat tools through typed application services and narrow browser effects. */
export async function executeAtlasAiChatToolCallsV1(input: {
  calls: readonly AtlasAiChatToolCallV1[];
  context?: Record<string, unknown>;
  ports: Pick<AtlasAiChatPortsV1, 'state' | 'projectContext' | 'agenda' | 'visualAllocation' | 'records' | 'commands'>;
  effects: AtlasAiChatToolExecutionEffectsV1;
}): Promise<string[]> {
  const { ports, effects } = input;
  const appStore = ports.state;
  const map = effects.map;
  const execution = ports.projectContext.executionModel as { stages?: AtlasAgendaCalendarStageV1[] };
  const executionStages = Array.isArray(execution.stages) ? execution.stages : [];
  const allowedViews = new Set([
    'assistant', 'stages', 'agenda', 'activities', 'progress', 'records',
    'leads', 'commissions', 'lot-development', 'reports', 'settings',
  ]);
  const executed: string[] = [];

  for (const call of input.calls.slice(0, 4)) {
    const name = String(call?.name || '');
    const args = call?.arguments && typeof call.arguments === 'object'
      ? call.arguments as Record<string, unknown>
      : {};

    if (name === 'ui.navigate' && typeof args.view === 'string' && allowedViews.has(args.view)) {
      appStore.set({
        view: args.view,
        sidebarCollapsed: args.view === 'records',
        lastAction: `IA abriu ${args.view}`,
      });
      executed.push(`Abriu ${args.view}.`);
      continue;
    }
    if (name === 'lot-development.upsert_profile') {
      const profile = ports.records.saveLotDevelopmentProfile(args);
      executed.push(`Preparou o perfil ${profile.title} no Loteamento para revisão.`);
      continue;
    }
    if (name === 'map.set_overlay' && map) {
      const category = args.category;
      if (category === 'clear') map.clearStageOverlay?.(false);
      else if (typeof category === 'string' && ['terraplanagem', 'drenagem', 'rede-agua', 'rede-eletrica', 'pavimentacao', 'urbanizacao'].includes(category))
        map.setStageOverlay?.(category, false);
      executed.push(category === 'clear' ? 'Limpou destaque do mapa.' : `Destacou ${String(category)} no mapa.`);
      continue;
    }
    if (name === 'map.adjust_view' && map) {
      if (args.fit) map.fitSceneView?.(true);
      else {
        if (Number.isFinite(Number(args.rotationDelta)))
          map.setSceneRotation?.(map.sceneManualRotation + Number(args.rotationDelta), true);
        if (Number.isFinite(Number(args.tiltDelta)))
          map.setSceneTiltAdjust?.(map.sceneTiltAdjust + Number(args.tiltDelta), true);
        if (Number.isFinite(Number(args.zoomDelta)))
          map.setSceneZoom?.(map.sceneManualZoom + Number(args.zoomDelta), true);
      }
      executed.push('Ajustou a vista 3D.');
      continue;
    }
    if (name === 'map.set_tiles' && map && typeof args.mode === 'string' && ['satellite', 'osm', 'generated'].includes(args.mode)) {
      const mode = args.mode;
      map.setMapTileMode?.(mode, true);
      executed.push(`Base ${mode === 'osm' ? 'OpenStreetMap' : mode === 'generated' ? 'aérea HD gerada' : 'satélite'} ativada.`);
      continue;
    }
    if (name === 'records.open_form') {
      const categories = ['ocorrencia', 'vistoria', 'reuniao', 'comunicacao', 'decisao', 'outro'];
      const category = typeof args.category === 'string' && categories.includes(args.category) ? args.category : 'ocorrencia';
      appStore.set({
        view: 'control',
        controlEventTab: 'event',
        controlEventDraft: {
          title: String(args.activity || '').slice(0, 120),
          responsible: String(args.responsible || '').slice(0, 120),
          details: String(args.details || '').slice(0, 4000),
          category,
        },
        lastAction: 'IA preparou registro geral para revisão',
      });
      executed.push('Abriu a ficha de evento geral para revisão, sem gravar dados.');
      continue;
    }
    if (name === 'stage.allocate_visual_record') {
      const message = await ports.visualAllocation.allocateRecord(
        args as AtlasWorkerContextChatVisualAllocationArgumentsV1,
        (input.context || {}) as AtlasWorkerContextChatVisualRecordAllocationContextV1,
        effects.addToolFeedback,
      );
      if (message) executed.push(message);
      continue;
    }
    if (name === 'agenda.create_pending') {
      const result = await ports.agenda.createPendingAgenda(normalizeAtlasAgendaPendingProposalV1(args));
      if (!result.ok) effects.addToolFeedback(result.message, 'warning');
      else executed.push(result.message);
      continue;
    }
    if (name === 'documents.open_form') {
      const reason = String(args.reason || '').replace(/\s+/g, ' ').trim().slice(0, 120);
      const runtime = globalThis as typeof globalThis & { BELAVISTA_PROJECT_DOCUMENT_ROUTE_TYPESCRIPT_V1?: boolean };
      if (runtime.BELAVISTA_PROJECT_DOCUMENT_ROUTE_TYPESCRIPT_V1 === true && effects.documentRef?.dispatchEvent && globalThis.CustomEvent) {
        effects.documentRef.dispatchEvent(new globalThis.CustomEvent('atlas:documents-open-request', {
          detail: { intent: 'create', source: 'assistant', reason },
        }));
      } else {
        appStore.set({
          view: 'documents',
          documentsEditId: 'new',
          documentsOpenRequest: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
          lastAction: `IA solicitou documento${reason ? `: ${reason}` : ''}`,
        });
      }
      executed.push('Abriu a inclusão de documento para anexar a evidência solicitada.');
      continue;
    }
    if (name === 'reports.select') {
      const families = ['Financeiro', 'Construção', 'Suprimentos', 'Comercial', 'Governança'];
      const family = typeof args.family === 'string' && families.includes(args.family) ? args.family : 'Financeiro';
      appStore.set({
        view: 'reports',
        reportFamily: family,
        reportType: args.reportType || appStore.get().reportType,
        lastAction: `IA abriu relatório ${family}`,
      });
      executed.push(`Abriu relatórios de ${family}.`);
      continue;
    }
    if (name === 'commissions.filter') {
      appStore.set({
        view: 'commissions',
        commissionFilters: {
          ...(appStore.get().commissionFilters || {}),
          query: args.query || '',
          status: args.status || 'all',
          profile: args.profile || 'all',
        },
        lastAction: 'IA filtrou carteira comercial',
      });
      executed.push('Aplicou filtro na carteira comercial.');
      continue;
    }
    if (name === 'ui.print') {
      effects.requestToolConfirmation(call);
      executed.push('Solicitou confirmação para impressão.');
    }
  }

  return executed;
}

export function aiAgendaInstructionV1(value: unknown): string {
  const config = normalizeAiAgendaComprehensionV1(value);
  return `Compreensão da agenda configurada pela operação. Leitura: ${config.reading} Determinação: ${config.determination} Geração: ${config.generation} ${config.autoCreatePending ? 'É permitido criar apenas apontamentos Pendentes sustentados pelos dados conhecidos.' : 'Não chame agenda.create_pending nem crie apontamentos pela IA; apresente somente uma sugestão para revisão.'}`;
}


