interface AtlasAdminHostStore {
  get(): Record<string, unknown>;
  set(patch: Record<string, unknown>): unknown;
}

export const ATLAS_SHELL_COMMAND_EVENT_V1 = 'atlas:shell-command-v1';
export type AtlasShellCommandV1 =
  | { kind: 'navigate'; source: 'shell' | 'mobile' | 'topbar'; view: string; label: string; reportFamily?: string }
  | { kind: 'return-to-stages'; source: 'shell' }
  | { kind: 'restricted-route-fallback'; source: 'shell' }
  | { kind: 'toggle-admin-menu'; source: 'topbar' }
  | { kind: 'account-action'; source: 'topbar'; label: string }
  | { kind: 'notification-action'; source: 'topbar'; actionUrl: string; currentUrl: string; title: string }
  | { kind: 'install-prompt'; source: 'shell'; prompt: Event | null };

export interface AtlasShellCommandControllerInputV1 {
  appStore: AtlasAdminHostStore;
  document?: Document;
  window?: Window & typeof globalThis;
}

const atlasShellCommandControllersV1 = new WeakMap<Document, { dispose(): void }>();

/** Apply shell, sidebar, mobile, and topbar intents after validating their active emitter. */
export function installAtlasShellCommandControllerV1(
  input: AtlasShellCommandControllerInputV1,
): { dispose(): void } {
  const documentRef = input.document || globalThis.document;
  const windowRef = input.window || globalThis.window;
  if (!documentRef || !input.appStore?.get || !input.appStore?.set)
    throw new TypeError('Shell commands require an active document and application store.');
  const existing = atlasShellCommandControllersV1.get(documentRef);
  if (existing) return existing;

  const onCommand = (event: Event): void => {
    const shell = documentRef.querySelector<HTMLElement>('belavista-app');
    const target = event.target instanceof Element ? event.target : null;
    const detail = (event as CustomEvent<AtlasShellCommandV1>).detail;
    if (!shell || !detail || typeof detail !== 'object') return;
    const topbar = shell.querySelector('app-topbar');
    const emittedByTopbar = Boolean(target?.closest('app-topbar') && target.closest('app-topbar') === topbar);
    const emittedByShell = target === shell;
    const emittedByMobileShell = target === shell || target === shell.querySelector('#app.app');
    if (detail.source === 'topbar' && !emittedByTopbar) return;
    if (detail.source === 'shell' && !emittedByShell) return;
    if (detail.source === 'mobile' && !emittedByMobileShell) return;

    switch (detail.kind) {
      case 'navigate': {
        const command = createSidebarNavigationCommand({
          view: detail.view,
          buttonLabel: detail.label,
          reportFamily: detail.reportFamily,
          reportCatalog: [],
        });
        applyAtlasSidebarNavigationCommandV1({
          appStore: input.appStore,
          command,
          document: documentRef,
          window: windowRef,
          getWorkerAssistant: () => (globalThis as typeof globalThis & {
            belavistaWorkerAssistant?: { setCollapsed?: (collapsed: boolean) => unknown };
          }).belavistaWorkerAssistant,
        });
        return;
      }
      case 'return-to-stages':
        input.appStore.set({ view: 'stages', activityDedicated: false, stageActivityDedicatedV9: false, selectedActivity: null, lastAction: 'Voltou para a central de etapas' });
        return;
      case 'restricted-route-fallback': {
        const projection = projectAtlasApplicationShellNavigation(input.appStore.get());
        if (projection.limitedActor && !projection.canOpenCurrentView)
          input.appStore.set({ view: projection.restrictedFallbackView, activityDedicated: false, stageActivityDedicatedV9: false, selectedActivity: null, lastAction: 'Área indisponível para este perfil' });
        return;
      }
      case 'toggle-admin-menu':
        input.appStore.set({ adminMenu: !Boolean(input.appStore.get().adminMenu), lastAction: 'Alternou menu do administrador' });
        return;
      case 'account-action': {
        const command = createSidebarAdminMenuCommand(detail.label);
        input.appStore.set(command.patch);
        if (!command.signOut) return;
        const signOut = (globalThis as typeof globalThis & { BELAVISTA_ADMIN_SIGN_OUT?: () => unknown | Promise<unknown> }).BELAVISTA_ADMIN_SIGN_OUT;
        if (typeof signOut === 'function') void Promise.resolve(signOut()).catch(error => console.warn('[Atlas shell] encerramento de sessão falhou', error));
        else console.warn('[Atlas shell] sessão autenticada indisponível para encerramento.');
        return;
      }
      case 'notification-action': {
        const command = createAtlasTopbarNotificationActionCommand({
          actionUrl: detail.actionUrl,
          currentUrl: detail.currentUrl,
          title: detail.title,
        });
        if (command.kind === 'state') input.appStore.set(command.patch);
        else if (command.kind === 'location') windowRef?.location.assign(command.href);
        return;
      }
      case 'install-prompt':
        input.appStore.set({ installPrompt: detail.prompt });
        return;
    }
  };
  documentRef.addEventListener(ATLAS_SHELL_COMMAND_EVENT_V1, onCommand);
  const controller = Object.freeze({
    dispose: () => documentRef.removeEventListener(ATLAS_SHELL_COMMAND_EVENT_V1, onCommand),
  });
  atlasShellCommandControllersV1.set(documentRef, controller);
  return controller;
}

