/** Apply the host-specific preflight that used to run in inline index.html scripts. */
export function prepareAtlasAdminDocumentEnvironmentV1(input: {
  document?: Document;
  window?: Window & typeof globalThis;
} = {}): void {
  const rootDocument = input.document || globalThis.document;
  const rootWindow = input.window || globalThis.window;
  if (!rootDocument?.body.classList.contains('admin-shell-page') || !rootWindow) return;

  const host = rootWindow.location.hostname;
  const isLocalHost = /^(?:localhost|127\.0\.0\.1)$/i.test(host);
  const isNgrokHost = /\.ngrok-free\.dev$/i.test(host);
  const isCloudflareTunnelHost = /(?:^|\.)trycloudflare\.com$/i.test(host);
  const runtime = globalThis as typeof globalThis & {
    BELAVISTA_DISABLE_SERVICE_WORKER?: boolean;
    BELAVISTA_AI_BASE?: string;
  };

  if (isLocalHost || isNgrokHost || isCloudflareTunnelHost)
    runtime.BELAVISTA_DISABLE_SERVICE_WORKER = true;
  if (isLocalHost)
    runtime.BELAVISTA_AI_BASE = 'https://belavista-cloudflare-worker.icaroglaucooliveira.workers.dev';

  const unregisterServiceWorkers = async (): Promise<void> => {
    const serviceWorker = rootWindow.navigator.serviceWorker;
    if (!serviceWorker) return;
    const registrations = await serviceWorker.getRegistrations();
    await Promise.all(registrations.map(registration => registration.unregister()));
  };
  const clearApplicationCaches = async (): Promise<void> => {
    const cacheStorage = rootWindow.caches;
    if (!cacheStorage) return;
    const keys = await cacheStorage.keys();
    await Promise.all(keys.map(key => cacheStorage.delete(key)));
  };

  if (isLocalHost) {
    const nativeLocalHost = rootWindow.location.protocol === 'https:' && host === 'localhost';
    void (async (): Promise<void> => {
      await unregisterServiceWorkers();
      await clearApplicationCaches();
      if (!nativeLocalHost || rootWindow.sessionStorage.getItem('belavista.mobile.assets') === 'mobile-chat-toggle-v1') return;
      rootWindow.sessionStorage.setItem('belavista.mobile.assets', 'mobile-chat-toggle-v1');
      const next = new URL(rootWindow.location.href);
      next.searchParams.set('_assets', 'mobile-chat-toggle-v1');
      rootWindow.location.replace(next.href);
    })().catch(error => rootWindow.console.warn('Não foi possível limpar o cache local:', error));
  }

  if (isNgrokHost || isCloudflareTunnelHost)
    void unregisterServiceWorkers().catch(() => undefined);

  if (isNgrokHost) {
    const reloadKey = 'belavista.ngrok.sw.purged.v5372';
    try {
      if (rootWindow.sessionStorage.getItem(reloadKey) === '1') return;
      rootWindow.sessionStorage.setItem(reloadKey, '1');
    } catch (error) {
      rootWindow.console.warn('[Aliança Park v5.3.72] não foi possível registrar a limpeza de cache:', error);
      return;
    }
    void (async (): Promise<void> => {
      try {
        await unregisterServiceWorkers();
        await clearApplicationCaches();
      } catch (error) {
        rootWindow.console.warn('[Aliança Park v5.3.72] purge SW/cache parcial', error);
      }
      const next = new URL(rootWindow.location.href);
      next.searchParams.set('_bv', '5372');
      rootWindow.location.replace(next.href);
    })();
  }
}

