/** Route the optional shell bridge through its TypeScript component owner. */
export function installAtlasGlaucoShellBridgeV1(input: AtlasGlaucoShellBridgeInputV1): boolean {
  return installAtlasGlaucoShellBridgeComponentV1(input);
}

/** Assemble the administrative runtime, route components, and registered shell. */
export async function startAtlasAdminApplicationCompositionV1(
  input: AtlasAdminApplicationCompositionInputV1,
): Promise<AtlasAdminApplicationRuntime> {
  const globalRef = input.globalRef || globalThis as unknown as AtlasAdminApplicationCompositionInputV1['globalRef'];
  const windowRef = input.windowRef || globalThis.window;
  const documentRef = input.documentRef || globalThis.document;
  if (!globalRef || !windowRef || !documentRef?.documentElement)
    throw new Error('O host do administrativo não disponibilizou window e document.');

  const registerShell = input.componentOwners?.registerAtlasShellHostElements;
  if (typeof registerShell !== 'function')
    throw new Error('O owner TypeScript do shell administrativo não está disponível.');

  installAtlasGlaucoShellBridgeV1({
    windowRef,
    documentRef,
    customElementsRef: windowRef.customElements,
  });

  const readBrowserStorage = (key: 'localStorage' | 'sessionStorage'): Storage | null => {
    try { return windowRef[key]; }
    catch { return null; }
  };
  const { appStore } = initializeAtlasApplicationRuntimeV1({
    globalRef: globalRef as unknown as AtlasApplicationRuntimeGlobalV1,
    localStorage: readBrowserStorage('localStorage'),
    sessionStorage: readBrowserStorage('sessionStorage'),
  });
  installAtlasShellCommandControllerV1({ appStore, document: documentRef, window: windowRef });
  const readPreferences = () => readAtlasUsagePreferencesV1(() => windowRef.localStorage);
  const viewThemes = ATLAS_STATE_CATALOGS_V1.viewThemes;
  const runtime = createAtlasAdminApplicationRuntime({
    appStore,
    restoreUiState: () => restoreAtlasUiState(readBrowserStorage('localStorage') || undefined),
    readDefaultPage: () => readPreferences().defaultPage,
    apiFetch,
    authenticatedActor: globalRef.BELAVISTA_ADMIN_ACTOR,
    getAuthenticatedActor: () => globalRef.BELAVISTA_ADMIN_ACTOR,
    authenticationRequired: globalRef.BELAVISTA_ADMIN_AUTH_REQUIRED,
    getAuthenticationRequired: () => globalRef.BELAVISTA_ADMIN_AUTH_REQUIRED,
    authenticationReady: globalRef.BELAVISTA_ADMIN_AUTH_READY,
    getAuthenticationReady: () => globalRef.BELAVISTA_ADMIN_AUTH_READY,
    serviceWorkerDisabled: globalRef.BELAVISTA_DISABLE_SERVICE_WORKER as boolean | undefined,
    installStageInfrastructure: () => {
      const hook = globalRef.installStageHomeRaidAiRecordsCalendarV1;
      if (typeof hook === 'function') (hook as () => void)();
    },
    refreshStageInfrastructure: () => {
      const hook = globalRef.ensureStageHomeRaidAiRecordsCalendarV1;
      if (typeof hook === 'function') (hook as () => void)();
    },
    window: windowRef,
    document: documentRef,
    moduleBaseUrl: input.moduleBaseUrl,
    mapViewTheme: (viewThemes.map || viewThemes.assistant) as unknown as AtlasAdminHostPorts['mapViewTheme'],
    prepareApplication: () => { applyAtlasUsagePreferencesV1(readPreferences(), documentRef); },
  });

  globalRef.__BELAVISTA_ADMIN_RUNTIME_TS_V1 = runtime;
  documentRef.documentElement.dataset.adminRuntimeOwnerV1 = 'typescript';
  await composeAtlasAdminComponentApplicationV1();
  registerShell({
    appStore,
    persistUiState: persistAtlasUiState,
    loadAdminExtensions: () => runtime.loadDeferredModules({ force: true }),
    window: windowRef,
    document: documentRef,
  });
  void startAtlasRecordsActivityDrillBootstrapV1({
    host: documentRef,
    customElementsRef: windowRef.customElements,
    appStore,
    apiFetch,
  });
  void installAtlasWorkerActivityMapLayerV1({
    appStore,
    demoData: ATLAS_STATE_CATALOGS_V1.demoData as AtlasApplicationRuntimeGlobalV1['__belavistaDemoData'],
  });
  void startAtlasWorkerContextChatBootstrapV1({
    documentRef,
    windowRef,
    appStore,
    apiFetch,
  });
  const bootstrapElement = documentRef.querySelector<HTMLElement>('cloudflare-bootstrap');
  queueMicrotask(() => void runtime.bootstrap().catch(error => {
    console.error('[Aliança Park] bootstrap TypeScript falhou', error);
    reportAtlasBootstrapFailureV1(bootstrapElement, error);
  }));
  return runtime;
}

export interface AtlasComponentApplicationConfigurationV1 {
  root: string;
  groups: readonly string[];
}

export const ATLAS_COMPONENT_APPLICATION_CONFIGURATION_V1: Readonly<AtlasComponentApplicationConfigurationV1> = Object.freeze({
  root: String(componentApplicationConfigurationData.root || 'components/index.mjs'),
  groups: Object.freeze([...componentApplicationConfigurationData.groups]),
});

export type AtlasComponentApplicationStepV1<TComponents = unknown> =
  | { type: 'resolve-component-runtime'; host: typeof globalThis }
  | { type: 'validate-component-configuration'; configuration: AtlasComponentApplicationConfigurationV1 }
  | { type: 'compose-component-application'; runtime: Record<string, unknown>; configuration: AtlasComponentApplicationConfigurationV1; compose?: () => TComponents | Promise<TComponents> }
  | { type: 'publish-component-application'; runtime: Record<string, unknown>; components: TComponents };

export interface AtlasComponentApplicationProgramInputV1<TComponents = unknown> {
  host?: typeof globalThis;
  configuration?: AtlasComponentApplicationConfigurationV1;
  compose?: () => TComponents | Promise<TComponents>;
}

export type AtlasComponentApplicationProgramHandlerV1<TComponents = unknown> = (step: AtlasComponentApplicationStepV1<TComponents>) => unknown | Promise<unknown>;
export type AtlasComponentApplicationProgramHandlersV1<TComponents = unknown> = Partial<Record<AtlasComponentApplicationStepV1<TComponents>['type'], AtlasComponentApplicationProgramHandlerV1<TComponents>>>;

/** Yield the host integration stages in the exact historical component order. */
export const AtlasComponentApplicationProgramV1 = Object.freeze({
  *program<TComponents = unknown>(input: AtlasComponentApplicationProgramInputV1<TComponents> = {}): Generator<AtlasComponentApplicationStepV1<TComponents>, TComponents, unknown> {
    const host = input.host || globalThis;
    const configuration = input.configuration || ATLAS_COMPONENT_APPLICATION_CONFIGURATION_V1;
    const runtime = (yield { type: 'resolve-component-runtime', host }) as Record<string, unknown>;
    const validatedConfiguration = (yield { type: 'validate-component-configuration', configuration }) as AtlasComponentApplicationConfigurationV1;
    const components = (yield { type: 'compose-component-application', runtime, configuration: validatedConfiguration, compose: input.compose }) as TComponents;
    yield { type: 'publish-component-application', runtime, components };
    return components;
  },
});

/** Execute each yielded integration step through its named host adapter. */
export async function driveAtlasComponentApplicationProgramV1<TComponents>(
  program: Generator<AtlasComponentApplicationStepV1<TComponents>, TComponents, unknown>,
  handlers: AtlasComponentApplicationProgramHandlersV1<TComponents>,
): Promise<TComponents> {
  let step = program.next();
  while (!step.done) {
    const handler = handlers?.[step.value.type];
    if (typeof handler !== 'function') {
      throw new Error(`No component application handler for step: ${step.value.type || 'unknown'}`);
    }
    step = program.next(await handler(step.value));
  }
  return step.value;
}

/** Resolve, validate, compose, and publish the root component application in order. */
export async function composeAtlasComponentApplicationV1<TComponents>(
  input: AtlasComponentApplicationProgramInputV1<TComponents>,
): Promise<TComponents> {
  const program = AtlasComponentApplicationProgramV1.program(input);
  let step = program.next();
  while (!step.done) {
    const effect = step.value;
    let result: unknown;
    switch (effect.type) {
      case 'resolve-component-runtime':
        if (!effect.host?.document) throw new Error('Component application requires a browser document.');
        result = effect.host;
        break;
      case 'validate-component-configuration':
        if (!effect.configuration?.root || !Array.isArray(effect.configuration.groups)
          || new Set(effect.configuration.groups).size !== effect.configuration.groups.length) {
          throw new Error('Invalid component application configuration.');
        }
        result = effect.configuration;
        break;
      case 'compose-component-application':
        if (typeof effect.compose !== 'function') throw new Error('Component application composer is unavailable.');
        result = await effect.compose();
        break;
      case 'publish-component-application':
        (effect.runtime as typeof globalThis & { BELAVISTA_COMPONENTS_V1?: unknown }).BELAVISTA_COMPONENTS_V1 = effect.components;
        result = undefined;
        break;
    }
    step = program.next(result);
  }
  return step.value;
}

type AtlasAdminMapRegistrationDependenciesV1 = Omit<
  Parameters<typeof installAtlasMapApplicationRegistrationV1>[0],
  'customElementsRef' | 'dashboardModeKeyV1' | 'installMapFilterRail' | 'createMapSceneElement'
>;

/** Own initial Atlas shell registration: primitives, navigation, operational map, then ViewLayer. */
export interface AtlasAdminShellElementBundleV1 {
  AppSidebar: CustomElementConstructor;
  AppTopbar: CustomElementConstructor;
  ViewLayer: CustomElementConstructor;
  MapFilterRail: CustomElementConstructor;
  MapScene: CustomElementConstructor;
  prepareAssistantLotStatusPromptV1(lotLabel: string): Promise<boolean>;
  prepareAssistantMapAreaPromptV1(areaLabel: string): Promise<boolean>;
  dashboardFilters: AtlasMapFilterItem[];
  highlightStatus: Record<string, AtlasMapFilterHighlight>;
}

export async function composeAtlasAdminShellElementsV1(input: {
  customElementsRef?: CustomElementRegistry;
  navigationDependencies: Parameters<typeof registerAtlasNavigationElementsV1>[0] & Record<string, unknown>;
  mapDependencies: AtlasAdminMapRegistrationDependenciesV1;
  viewLayerDependencies: Parameters<typeof createAtlasLegacyViewLayerV1>[0];
  composeMapSceneV1: Parameters<typeof createAtlasMapSceneElementV1>[0]['composeMapSceneV1'];
}): Promise<Readonly<AtlasAdminShellElementBundleV1>> {
  const customElementsRef = input.customElementsRef || globalThis.customElements;
  if (!customElementsRef) throw new Error('O shell Atlas precisa do registro de elementos do navegador.');
  const dashboardModeKeyV1 = () => 'tracking';
  return registerAtlasApplicationElements({
    customElementsRef,
    navigationDependencies: input.navigationDependencies,
    mapDependencies: input.mapDependencies,
    viewLayerDependencies: input.viewLayerDependencies,
    dashboardModeKeyV1,
    registerPrimitives: ({customElementsRef: registry}) => registerAtlasPrimitiveElementsV1(registry),
    createNavigation: ({customElements: registry}) => registerAtlasNavigationElementsV1({
      ...input.navigationDependencies,
      customElements: registry,
    }),
    registerMap: ({customElementsRef: registry}) => installAtlasMapApplicationRegistrationV1({
      ...input.mapDependencies,
      customElementsRef: registry,
      dashboardModeKeyV1,
      installMapFilterRail: installAtlasMapFilterRail,
      createMapSceneElement: options => createAtlasMapSceneElementV1({
        ...options,
        composeMapSceneV1: input.composeMapSceneV1,
      }),
    }),
    createViewLayer: dependencies => createAtlasLegacyViewLayerV1(dependencies),
  });
}

