const atlasAdminAccessPolicyV1 = adminAccessPolicyData as unknown as AtlasAdminAccessPolicyDataV1;
const atlasBrokerRolesV1 = new Set(atlasAdminAccessPolicyV1.brokerRoles);
const atlasPrivilegedRolesV1 = new Set(atlasAdminAccessPolicyV1.privilegedRoles);
