const workerStageAdminFormOptionsV1 = workerStageAdminFormOptionsData as WorkerStageAdminFormOptionsV1;
interface AtlasAdminStageConfigBridgeEntryV1 { id: number; name: string; key: string }
interface AtlasAdminStageConfigBridgeCatalogV1 { stages: readonly AtlasAdminStageConfigBridgeEntryV1[] }
const atlasAdminStageConfigBridgeCatalogV1 = adminStageConfigBridgeData as AtlasAdminStageConfigBridgeCatalogV1;
const atlasAdminStageConfigBridgeByIdV1 = new Map(atlasAdminStageConfigBridgeCatalogV1.stages.map(stage => [stage.id, stage]));
const atlasAdminStageConfigBridgeTextV1 = (value: unknown, limit = 500): string => String(value ?? '').trim().slice(0, limit);
const atlasAdminStageConfigBridgeObjectV1 = (value: unknown): Record<string, any> =>
  value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, any> : {};
const atlasAdminStageConfigBridgeArrayV1 = (value: unknown): Record<string, any>[] =>
  Array.isArray(value) ? value as Record<string, any>[] : [];
const atlasAdminStageConfigBridgeKeyV1 = (id: unknown, name = ''): string => {
  const numericId = Number(id);
  const catalogKey = atlasAdminStageConfigBridgeByIdV1.get(numericId)?.key;
  if (catalogKey) return catalogKey;
  const normalized = atlasAdminStageConfigBridgeTextV1(name, 100).toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return normalized || `stage-${id}`;
};
const atlasAdminStageConfigBridgeListV1 = (data: unknown): Record<string, any>[] => {
  if (Array.isArray(data)) return data as Record<string, any>[];
  return atlasAdminStageConfigBridgeArrayV1(atlasAdminStageConfigBridgeObjectV1(data).stages);
};
const atlasAdminStageConfigBridgeProfileV1 = (data: unknown, id: unknown, name: string): Record<string, any> => {
  const key = atlasAdminStageConfigBridgeKeyV1(id, name);
  const source = atlasAdminStageConfigBridgeObjectV1(data);
  const profiles = atlasAdminStageConfigBridgeObjectV1(source.stageProfiles || source.profiles);
  return atlasAdminStageConfigBridgeObjectV1(profiles[key] || profiles[String(id)] || profiles[name]);
};
const atlasAdminStageConfigBridgeStateV1 = (data: unknown, id: unknown, name: string): Record<string, any> => {
  const key = atlasAdminStageConfigBridgeKeyV1(id, name);
  const source = atlasAdminStageConfigBridgeObjectV1(data);
  const states = atlasAdminStageConfigBridgeObjectV1(source.stageState || source.state);
  return atlasAdminStageConfigBridgeObjectV1(states[key] || states[String(id)] || states[name]);
};
const atlasAdminStageConfigBridgeFindStageV1 = (data: unknown, id: unknown): Record<string, any> => {
  const numericId = Number(id);
  const name = atlasAdminStageConfigBridgeByIdV1.get(numericId)?.name || `Etapa ${id}`;
  const key = atlasAdminStageConfigBridgeKeyV1(id, name);
  return atlasAdminStageConfigBridgeListV1(data).find(item =>
    Number(item.id) === numericId || String(item.key || item.stageId || '') === key
      || String(item.name || '').toLowerCase() === name.toLowerCase(),
  ) || {};
};
const atlasAdminStageConfigBridgeAiV1 = (profile: Record<string, any> = {}, stage: Record<string, any> = {}): Record<string, unknown> => {
  const source = {
    ...atlasAdminStageConfigBridgeObjectV1(stage.aiConfig),
    ...atlasAdminStageConfigBridgeObjectV1(stage.ai),
    ...atlasAdminStageConfigBridgeObjectV1(profile.aiConfig),
    ...atlasAdminStageConfigBridgeObjectV1(profile.ai),
    ...profile,
  };
  const executionProfile = atlasAdminStageConfigBridgeObjectV1(source.executionProfile);
  return {
    requirements: atlasAdminStageConfigBridgeArrayV1(source.requirements),
    conditions: atlasAdminStageConfigBridgeArrayV1(source.conditions || source.peculiarities),
    typicalDescription: atlasAdminStageConfigBridgeTextV1(source.typicalDescription || source.executionDescription || source.description || '', 6000),
    requestHints: atlasAdminStageConfigBridgeArrayV1(source.requestHints || source.planningHints),
    evidenceFocus: atlasAdminStageConfigBridgeArrayV1(source.evidenceFocus || source.evidenceRequirements),
    procurementFocus: atlasAdminStageConfigBridgeArrayV1(source.procurementFocus || source.purchaseFocus),
    notificationTargets: atlasAdminStageConfigBridgeObjectV1(source.notificationTargets),
    executionProfile: { ...executionProfile, materialsTable: atlasAdminStageConfigBridgeArrayV1(executionProfile.materialsTable || source.materialsTable) },
    updatedAt: source.updatedAt || source.modifiedAt || null,
  };
};
const atlasAdminStageConfigBridgeReportV1 = (data: unknown, id: unknown): Record<string, unknown> => {
  const catalogStage = atlasAdminStageConfigBridgeByIdV1.get(Number(id));
  const defaultName = catalogStage?.name || `Etapa ${id}`;
  const stage = atlasAdminStageConfigBridgeFindStageV1(data, id);
  const profile = atlasAdminStageConfigBridgeProfileV1(data, id, defaultName);
  const state = atlasAdminStageConfigBridgeStateV1(data, id, defaultName);
  return {
    id: Number(id), name: atlasAdminStageConfigBridgeTextV1(stage.name || defaultName, 160),
    owner: atlasAdminStageConfigBridgeTextV1(stage.owner || stage.ownerName || profile.owner || '', 160),
    status: atlasAdminStageConfigBridgeTextV1(state.status || stage.status || 'planejado', 60),
    progress: Number(state.progress ?? stage.progress ?? 0) || 0,
    week: atlasAdminStageConfigBridgeTextV1(stage.week || stage.reference || profile.week || '', 160),
    aiConfig: atlasAdminStageConfigBridgeAiV1(profile, stage),
    activities: atlasAdminStageConfigBridgeArrayV1(stage.activities || profile.activities),
    purchases: atlasAdminStageConfigBridgeArrayV1(stage.purchases || profile.purchases),
    materials: atlasAdminStageConfigBridgeArrayV1(stage.materials || profile.materials),
    records: atlasAdminStageConfigBridgeArrayV1(stage.records || profile.records),
    receipts: atlasAdminStageConfigBridgeArrayV1(stage.receipts || profile.receipts),
    outsourcing: atlasAdminStageConfigBridgeArrayV1(stage.outsourcing || profile.outsourcing),
    relations: atlasAdminStageConfigBridgeArrayV1(stage.relations || profile.relations),
    cashEntries: atlasAdminStageConfigBridgeArrayV1(stage.cashEntries || profile.cashEntries),
    summary: atlasAdminStageConfigBridgeObjectV1(stage.summary || profile.summary),
    situation: atlasAdminStageConfigBridgeObjectV1(stage.situation || profile.situation),
  };
};
const atlasAdminStageConfigBridgeMergeV1 = (data: unknown, id: unknown, patch: Record<string, any>, aiOnly: boolean): unknown => {
  const numericId = Number(id);
  const catalogStage = atlasAdminStageConfigBridgeByIdV1.get(numericId);
  const name = catalogStage?.name || `Etapa ${id}`;
  const key = atlasAdminStageConfigBridgeKeyV1(id, name);
  const next = structuredClone(data ?? {}) as Record<string, any> | Record<string, any>[];
  const list = atlasAdminStageConfigBridgeListV1(next);
  if (list.length) {
    const index = list.findIndex(item => Number(item.id) === numericId || String(item.key || item.stageId || '') === key
      || String(item.name || '').toLowerCase() === name.toLowerCase());
    const current = index >= 0 ? list[index] : { id: numericId, key, name };
    list[index >= 0 ? index : list.length] = aiOnly
      ? { ...current, aiConfig: { ...atlasAdminStageConfigBridgeObjectV1(current.aiConfig), ...patch }, updatedAt: new Date().toISOString() }
      : { ...current, ...patch, updatedAt: new Date().toISOString() };
    if (Array.isArray(next)) return list;
    const objectNext = next as Record<string, any>;
    objectNext.stages = list;
    return objectNext;
  }
  const objectNext = Array.isArray(next) ? {} : next as Record<string, any>;
  const profiles = { ...atlasAdminStageConfigBridgeObjectV1(objectNext.stageProfiles || objectNext.profiles) };
  const current = atlasAdminStageConfigBridgeObjectV1(profiles[key]);
  profiles[key] = aiOnly
    ? { ...current, ...patch, aiConfig: { ...atlasAdminStageConfigBridgeObjectV1(current.aiConfig), ...patch }, updatedAt: new Date().toISOString() }
    : { ...current, ...patch, updatedAt: new Date().toISOString() };
  objectNext.stageProfiles = profiles;
  return objectNext;
};

/** Translate the legacy stage-admin routes into the persistent Worker config API. */
export function installAtlasAdminStageConfigBridgeV1(input: {
  globalRef: typeof globalThis;
  locationRef: Pick<Location, 'href'>;
}): () => void {
  const previousFetch = input.globalRef.fetch;
  const marker = '__atlasAdminStageConfigBridgeV1';
  if ((previousFetch as typeof globalThis.fetch & { [key: string]: unknown })[marker]) return () => {};
  const nativeFetch = previousFetch.bind(input.globalRef);
  const jsonResponse = (payload: unknown, status = 200): Response => new Response(JSON.stringify(payload), {
    status,
    headers: { 'content-type': 'application/json' },
  });
  const bridgeFetch: typeof globalThis.fetch = async (requestInput, init = {}) => {
    let url: URL;
    try {
      const requestUrl = typeof requestInput === 'string' ? requestInput
        : requestInput instanceof URL ? requestInput.href : requestInput.url;
      url = new URL(requestUrl, input.locationRef.href);
    } catch { return nativeFetch(requestInput, init); }
    const match = url.pathname.match(/^\/api\/stages-admin\/(\d+)(?:\/(ai|report))?$/);
    if (!match) return nativeFetch(requestInput, init);

    const id = Number(match[1]);
    const resource = match[2] || '';
    const methodFromRequest = requestInput instanceof Request ? requestInput.method : '';
    const method = String(init.method || methodFromRequest || 'GET').toUpperCase();
    const requestHeaders = requestInput instanceof Request ? requestInput.headers : undefined;
    const headers = new Headers(init.headers || requestHeaders);
    const configUrl = new URL('/api/admin/config/stages', url.origin).href;
    try {
      const read = await nativeFetch(configUrl, { method: 'GET', headers, cache: 'no-store' });
      const raw = await read.text();
      if (!read.ok) return new Response(raw, { status: read.status, headers: { 'content-type': 'application/json' } });
      const config = raw ? JSON.parse(raw) as Record<string, any> : {};
      const data = config.data ?? config;
      if (method === 'GET' && resource === 'report')
        return jsonResponse({ report: atlasAdminStageConfigBridgeReportV1(data, id), source: config.source, sha: config.sha });
      if (method === 'GET')
        return jsonResponse({ stage: atlasAdminStageConfigBridgeReportV1(data, id), source: config.source, sha: config.sha });
      if (method === 'PUT') {
        const bodyText = typeof init.body === 'string' ? init.body : '{}';
        const patch = bodyText ? JSON.parse(bodyText) as Record<string, any> : {};
        const next = atlasAdminStageConfigBridgeMergeV1(data, id, patch, resource === 'ai');
        const writeHeaders = new Headers(headers);
        writeHeaders.set('Content-Type', 'application/json');
        const write = await nativeFetch(configUrl, {
          method: 'PUT', headers: writeHeaders,
          body: JSON.stringify({ data: next, sha: config.sha }),
        });
        const savedText = await write.text();
        if (!write.ok) return new Response(savedText, { status: write.status, headers: { 'content-type': 'application/json' } });
        return jsonResponse({
          stage: atlasAdminStageConfigBridgeReportV1(next, id),
          saved: savedText ? JSON.parse(savedText) : {},
          source: 'github-worker',
        });
      }
      return jsonResponse({ error: 'Método não permitido.' }, 405);
    } catch (error) {
      return jsonResponse({
        error: `Falha na configuração persistente da etapa: ${error instanceof Error ? error.message : String(error)}`,
      }, 502);
    }
  };
  Object.defineProperty(bridgeFetch, marker, { value: true });
  input.globalRef.fetch = bridgeFetch;
  return () => { if (input.globalRef.fetch === bridgeFetch) input.globalRef.fetch = previousFetch; };
}

export interface AtlasAdminCashEvidenceRuntimeV1 {
  documentRef: Document;
  windowRef: Window & typeof globalThis;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
}

/** Own evidence validation, proof persistence, and the strict cash-state transition. */
export function mountAtlasAdminCashEvidenceRuntimeV1(input: AtlasAdminCashEvidenceRuntimeV1): () => void {
  const stageCatalog = adminStageConfigBridgeData as AtlasAdminStageConfigBridgeCatalogV1;
  const report = (form: HTMLFormElement, message: string, busy = false): void => view.setStatus(form, message, busy);
  const submit = async (form: HTMLFormElement): Promise<void> => {
    const values = Object.fromEntries(new input.windowRef.FormData(form)) as Record<string, FormDataEntryValue>;
    const amount = String(values.amount || '');
    const amountCents = Math.round((Number(amount.replace(/\./g, '').replace(',', '.').replace(/[^\d.-]/g, '')) || 0) * 100);
    if (!amountCents) { report(form, 'Informe um valor maior que zero.'); return; }
    const file = form.querySelector<HTMLInputElement>('input[name="cashProof"]')?.files?.[0];
    const canvas = form.querySelector<HTMLCanvasElement>('[data-cash-signature]');
    if (!file && !canvas?.dataset.dirty) { report(form, 'Anexe um comprovante ou assine/desenhe no quadro.'); return; }
    report(form, 'Salvando evidência no GitHub…', true);
    try {
      let evidence: Record<string, unknown>;
      if (file) {
        if (file.size > 6 * 1024 * 1024) throw new Error('Comprovante deve ter no máximo 6 MB.');
        const dataUrl = await new Promise<string>((resolve, reject) => {
          const reader = new input.windowRef.FileReader();
          reader.onload = () => resolve(String(reader.result || ''));
          reader.onerror = () => reject(reader.error || new Error('Falha ao ler comprovante.'));
          reader.readAsDataURL(file);
        });
        evidence = { kind: 'upload', fileName: atlasAdminStageConfigBridgeTextV1(file.name, 120),
          contentType: atlasAdminStageConfigBridgeTextV1(file.type || 'application/octet-stream', 100), dataUrl };
      } else {
        evidence = { kind: 'canvas-signature', fileName: `assinatura-caixa-${input.windowRef.Date.now()}.png`,
          contentType: 'image/png', dataUrl: canvas!.toDataURL('image/png') };
      }
      const proofResponse = await input.apiFetch('/api/admin/cash-evidence', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ evidence }),
      });
      const proofPayload = await proofResponse.json() as Record<string, any>;
      if (!proofResponse.ok) throw new Error(proofPayload.error || `HTTP ${proofResponse.status}`);
      report(form, 'Evidência salva. Enviando o fato para a transição NVIDIA…', true);
      const stateResponse = await input.apiFetch('/api/admin/config/state', { cache: 'no-store' });
      const statePayload = await stateResponse.json() as Record<string, any>;
      if (!stateResponse.ok) throw new Error(statePayload.error || `HTTP ${stateResponse.status}`);
      const previousState = statePayload.data ?? statePayload;
      const event = {
        id: `cash-${input.windowRef.Date.now()}`, type: 'cash.entry.recorded', at: new input.windowRef.Date().toISOString(),
        actor: { id: 'admin-web', role: 'admin' },
        payload: {
          kind: values.kind === 'saida' ? 'saida' : 'entrada', stage: atlasAdminStageConfigBridgeTextV1(values.stage, 120) || 'Geral',
          category: atlasAdminStageConfigBridgeTextV1(values.category, 120), description: atlasAdminStageConfigBridgeTextV1(values.description, 500),
          date: atlasAdminStageConfigBridgeTextV1(values.date, 20), amountCents, evidence: proofPayload.proof,
        },
      };
      const loopResponse = await input.apiFetch('/api/operational-loop', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mode: 'strict-ai-state-transition', persist: true, previousState, event,
          inference: { provider: 'nvidia', strict: true, requireFullState: true, requireMetaTrace: true, noDeterministicFallback: true } }),
      });
      const loop = await loopResponse.json() as Record<string, any>;
      if (!loopResponse.ok) throw new Error(loop.error || `HTTP ${loopResponse.status}`);
      report(form, 'Lançamento comprovado e incorporado ao estado pela NVIDIA.', true);
      view.reset(form);
      input.windowRef.dispatchEvent(new input.windowRef.CustomEvent('belavista:operational-refresh', {
        detail: { source: 'cash-evidence-v11', loop },
      }));
      input.windowRef.setTimeout(() => input.windowRef.location.reload(), 650);
    } catch (error) {
      report(form, error instanceof Error ? error.message : 'Falha ao registrar o lançamento.');
    }
  };
  let view: AtlasAdminCashEvidenceFormViewV1;
  view = mountAtlasAdminCashEvidenceFormV1({
    documentRef: input.documentRef, windowRef: input.windowRef,
    stageNames: stageCatalog.stages.map(stage => stage.name),
    onSubmit: form => { void submit(form); },
  });
  return () => view.dispose();
}

/** Install all administrative map presentation owners through one component controller. */
interface AtlasAdminMapRuntimeInputV1 {
  documentRef: Document;
  windowRef: Window;
  registry?: CustomElementRegistry;
  fetchRef?: (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;
}

interface AtlasAdminPublicMapRuntimeSurfaceOwnerV1 { dispose(): void }
const atlasAdminPublicMapRuntimeSurfaceOwnersV1 = new WeakMap<Document, AtlasAdminPublicMapRuntimeSurfaceOwnerV1>();

/** Resolve administrative public maps to the existing typed map-surface controller. */
export function installAtlasAdminPublicMapRuntimeSurfaceResolverV1(input: {
  documentRef: Document;
  windowRef: Window & typeof globalThis;
}): () => void {
  const existing = atlasAdminPublicMapRuntimeSurfaceOwnersV1.get(input.documentRef);
  if (existing) return () => existing.dispose();

  const globalRef = input.windowRef as Window & typeof globalThis & {
    belavistaPublicMapRuntimeSurfaceForMapV1?: (map: HTMLElement) => AtlasPublicLeadsSurface | null;
  };
  const previousResolver = globalRef.belavistaPublicMapRuntimeSurfaceForMapV1;
  const surfaces = new Map<HTMLElement, AtlasPublicLeadsSurface>();
  const resolve = (map: HTMLElement): AtlasPublicLeadsSurface | null => {
    if (!map?.isConnected || typeof map.matches !== 'function'
      || !map.matches('map-scene[data-public-map],map-scene[data-public-presentation]')) return null;
    const enclosing = map.closest<HTMLElement>('public-leads-surface');
    if (enclosing) return enclosing as AtlasPublicLeadsSurface;
    let surface = surfaces.get(map);
    if (!surface || !surface.isConnected) {
      surface = createAtlasPublicMapRuntimeSurfaceV1(input.documentRef);
      surface.dataset.publicMapRuntimeKey = map.id || `map-${surfaces.size + 1}`;
      surfaces.set(map, surface);
    }
    map.dataset.publicMapRuntimeSurfaceOwnerV1 = 'typescript';
    return surface;
  };
  globalRef.belavistaPublicMapRuntimeSurfaceForMapV1 = resolve;

  const Observer = input.windowRef.MutationObserver;
  const observer = Observer ? new Observer(() => {
    for (const [map, surface] of surfaces) {
      if (map.isConnected) continue;
      surface.remove();
      surfaces.delete(map);
    }
  }) : null;
  observer?.observe(input.documentRef.documentElement, { childList: true, subtree: true });

  let disposed = false;
  const owner: AtlasAdminPublicMapRuntimeSurfaceOwnerV1 = {
    dispose(): void {
      if (disposed) return;
      disposed = true;
      observer?.disconnect();
      for (const surface of surfaces.values()) surface.remove();
      surfaces.clear();
      if (globalRef.belavistaPublicMapRuntimeSurfaceForMapV1 === resolve) {
        if (previousResolver) globalRef.belavistaPublicMapRuntimeSurfaceForMapV1 = previousResolver;
        else delete globalRef.belavistaPublicMapRuntimeSurfaceForMapV1;
      }
      atlasAdminPublicMapRuntimeSurfaceOwnersV1.delete(input.documentRef);
    },
  };
  atlasAdminPublicMapRuntimeSurfaceOwnersV1.set(input.documentRef, owner);
  return () => owner.dispose();
}

const atlasAdminMapComponentOwnersV1 = new WeakMap<Document, ReturnType<typeof installAtlasAdminMapComponentControllerV1>>();

export function installAtlasAdminMapComponentRuntimeV1(input: AtlasAdminMapRuntimeInputV1): () => void {
  if (atlasAdminMapComponentOwnersV1.has(input.documentRef)) return () => {};
  const windowRef = input.windowRef as Window & typeof globalThis;
  const fetcher = input.fetchRef || ((resource: RequestInfo | URL, init?: RequestInit) => windowRef.fetch(resource, init));
  const controller = installAtlasAdminMapComponentControllerV1({
    documentRef: input.documentRef,
    windowRef,
    registry: input.registry || windowRef.customElements,
    loadGeoreference: url => loadAdminDwgGeoreferenceV1(url, fetcher),
  });
  atlasAdminMapComponentOwnersV1.set(input.documentRef, controller);
  return () => {
    if (atlasAdminMapComponentOwnersV1.get(input.documentRef) !== controller) return;
    controller.dispose();
    atlasAdminMapComponentOwnersV1.delete(input.documentRef);
  };
}

/** Start the deferred admin runtime extensions in their historical order. */
export async function startAtlasAdminRuntimeExtensionsV1(input: {
  documentRef: Document;
  windowRef: Window & typeof globalThis;
  registry?: CustomElementRegistry;
}): Promise<void> {
  const { documentRef, windowRef } = input;
  const globalRef = globalThis;
  const baseUrl = (): string => {
    const runtime = String((globalRef as typeof globalThis & { BELAVISTA_API_BASE?: unknown }).BELAVISTA_API_BASE || '').replace(/\/$/, '');
    if (runtime) return runtime;
    try {
      const saved = JSON.parse(windowRef.localStorage.getItem('belavista.integrations.v1') || '{}') as { apiBase?: unknown };
      if (saved.apiBase) return String(saved.apiBase).replace(/\/$/, '');
    } catch { /* local integration settings are optional */ }
    return String(documentRef.querySelector<HTMLMetaElement>('meta[name="belavista-api-base"]')?.content || '').replace(/\/$/, '');
  };
  const api = (path: string): string => {
    const base = baseUrl();
    return base ? `${base}${path}` : path;
  };
  const adminFetch = async (path: string, init: RequestInit = {}): Promise<Response> => {
    const headers = new Headers(init.headers || {});
    try {
      const token = await (globalRef as typeof globalThis & { BELAVISTA_GET_ID_TOKEN?: () => Promise<string | null> }).BELAVISTA_GET_ID_TOKEN?.();
      if (token) headers.set('Authorization', `Bearer ${token}`);
    } catch { /* authenticated host may be unavailable during local demo */ }
    return windowRef.fetch(api(path), { ...init, headers });
  };

  installAtlasAdminStageConfigBridgeV1({ globalRef, locationRef: windowRef.location });
  documentRef.documentElement.dataset.adminStageConfigBridgeOwnerV1 = 'typescript';

  mountAtlasAdminCashEvidenceRuntimeV1({ documentRef, windowRef, apiFetch: adminFetch });
  documentRef.documentElement.dataset.adminCashEvidenceOwnerV1 = 'typescript';

  installAtlasAdminMapComponentRuntimeV1({ documentRef, windowRef, registry: input.registry || windowRef.customElements });
  installAtlasAdminPublicMapRuntimeSurfaceResolverV1({ documentRef, windowRef });
  documentRef.documentElement.dataset.adminMapContextOwnerV1 = 'typescript';
  documentRef.documentElement.dataset.adminMapComponentRuntimeOwnerV1 = 'typescript';
  console.info('[BELAVISTA_ADMIN_RUNTIME_V11] ativo');
}

