let atlasFirebaseAdminEntryPointsPromiseV1: Promise<AtlasFirebaseAdminEntryPointsV1> | null = null;

/** Load typed Firebase owners first; retain the MJS service adapter as recovery. */
export function loadAtlasFirebaseAdminEntryPointsV1(): Promise<AtlasFirebaseAdminEntryPointsV1> {
  if (atlasFirebaseAdminEntryPointsPromiseV1) return atlasFirebaseAdminEntryPointsPromiseV1;
  atlasFirebaseAdminEntryPointsPromiseV1 = Promise.resolve()
    .then(() => createAtlasFirebaseAdminEntryPointsV1())
    .catch(error => {
      atlasFirebaseAdminEntryPointsPromiseV1 = null;
      throw error;
    });
  return atlasFirebaseAdminEntryPointsPromiseV1;
}

