const ATLAS_FIREBASE_SDK_VERSION_V1 = String(firebaseWebConfigData.sdkVersion || '12.16.0');
const ATLAS_FIREBASE_WEB_CONFIG_V1 = Object.freeze({
  apiKey: String(firebaseWebConfigData.apiKey || ''),
  authDomain: String(firebaseWebConfigData.authDomain || ''),
  databaseURL: String(firebaseWebConfigData.databaseURL || ''),
  projectId: String(firebaseWebConfigData.projectId || ''),
  storageBucket: String(firebaseWebConfigData.storageBucket || ''),
  messagingSenderId: String(firebaseWebConfigData.messagingSenderId || ''),
  appId: String(firebaseWebConfigData.appId || ''),
  measurementId: String(firebaseWebConfigData.measurementId || ''),
});
let atlasFirebaseSdkRuntimePromiseV1: Promise<AtlasFirebaseSdkRuntimeV1> | null = null;

/** Load the browser Firebase SDK once; persistence and route policy stay in typed program owners. */
export function loadAtlasFirebaseSdkRuntimeV1(): Promise<AtlasFirebaseSdkRuntimeV1> {
  if (atlasFirebaseSdkRuntimePromiseV1) return atlasFirebaseSdkRuntimePromiseV1;
  atlasFirebaseSdkRuntimePromiseV1 = (async () => {
    const base = `https://www.gstatic.com/firebasejs/${ATLAS_FIREBASE_SDK_VERSION_V1}`;
    const [appSdk, databaseSdk, authSdk, storageSdk] = await Promise.all([
      import(/* @vite-ignore */ `${base}/firebase-app.js`) as Promise<AtlasFirebaseAppSdkModuleV1>,
      import(/* @vite-ignore */ `${base}/firebase-database.js`) as Promise<AtlasFirebaseDatabaseSdkModuleV1>,
      import(/* @vite-ignore */ `${base}/firebase-auth.js`) as Promise<AtlasFirebaseAuthSdkModuleV1>,
      import(/* @vite-ignore */ `${base}/firebase-storage.js`) as Promise<AtlasFirebaseStorageSdkModuleV1>,
    ]);
    const apps = typeof appSdk.getApps === 'function' ? appSdk.getApps() as unknown[] : [];
    const app = apps.length && typeof appSdk.getApp === 'function'
      ? appSdk.getApp()
      : appSdk.initializeApp(ATLAS_FIREBASE_WEB_CONFIG_V1);
    if (typeof globalThis.WebSocket === 'function' && typeof databaseSdk.forceWebSockets === 'function')
      databaseSdk.forceWebSockets();
    const auth = authSdk.getAuth(app);
    const persistentAuthPersistence = authSdk.indexedDBLocalPersistence || authSdk.browserLocalPersistence;
    if (typeof authSdk.setPersistence === 'function' && persistentAuthPersistence) {
      try {
        await authSdk.setPersistence(auth, persistentAuthPersistence);
      } catch (error) {
        if ((globalThis as typeof globalThis & { BELAVISTA_CAPACITOR_NATIVE?: boolean }).BELAVISTA_CAPACITOR_NATIVE === true)
          throw new Error('Não foi possível habilitar o login persistente neste aparelho. Verifique o armazenamento do aplicativo e tente novamente.', { cause: error });
        console.info('Persistência local do Firebase indisponível neste contexto.', error);
      }
    } else if ((globalThis as typeof globalThis & { BELAVISTA_CAPACITOR_NATIVE?: boolean }).BELAVISTA_CAPACITOR_NATIVE === true) {
      throw new Error('O Firebase não disponibilizou um mecanismo de login persistente para este aplicativo.');
    }
    void import(/* @vite-ignore */ `${base}/firebase-analytics.js`)
      .then((sdk: AtlasFirebaseAnalyticsSdkModuleV1) => { try { sdk.getAnalytics(app); } catch (error) { console.info('Firebase Analytics indisponível neste contexto.', error); } })
      .catch(() => undefined);
    const db = databaseSdk.getDatabase(app);
    return Object.freeze({
      app, auth, db, storage: storageSdk.getStorage(app),
      ...authSdk, ...storageSdk, ...databaseSdk,
      ref: databaseSdk.ref, storageRef: storageSdk.ref,
    }) as AtlasFirebaseSdkRuntimeV1;
  })().catch(error => {
    atlasFirebaseSdkRuntimePromiseV1 = null;
    throw error;
  });
  return atlasFirebaseSdkRuntimePromiseV1;
}

/** Compose the typed Firebase owners used by the administrative shell. */
export function createAtlasFirebaseAdminEntryPointsV1(): AtlasFirebaseAdminEntryPointsV1 {
  const readItem = (key: string): string => globalThis.localStorage.getItem(key) || '';
  const text = (value: unknown, max = 240): string => String(value ?? '').trim().slice(0, max);
  const slug = (value: unknown): string => text(value, 160).normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9/_-]+/g, '-').replace(/^-+|-+$/g, '');
  const integrationSettingsReader = createIntegrationSettingsReaderV1();
  const readIntegrationSettings = (): Record<string, unknown> => {
    const value = integrationSettingsReader();
    return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  };
  const ensureInstallationId = (): string => {
    const current = readItem('belavista.device.installation.v1');
    if (current) return current;
    const created = globalThis.crypto.randomUUID();
    globalThis.localStorage.setItem('belavista.device.installation.v1', created);
    return created;
  };
  const communications = createAtlasFirebaseOperationalCommunicationsV1({
    loadRuntime: loadAtlasFirebaseSdkRuntimeV1,
    text,
    slug,
    readIntegrationSettings,
    ensureInstallationId,
    readStoredChannelUid: () => readItem('belavista.device.channel.uid.v1'),
    readStoredChannelRole: () => readItem('belavista.device.channel.role.v1'),
    rememberOperationalChannel: channel => {
      if (channel.uid) globalThis.localStorage.setItem('belavista.device.channel.uid.v1', String(channel.uid));
      if (channel.role) globalThis.localStorage.setItem('belavista.device.channel.role.v1', String(channel.role));
    },
    defaultProjectId: 'project-alianca-park',
    navigatorRef: globalThis.navigator,
    notificationApi: typeof globalThis.Notification === 'undefined' ? null : globalThis.Notification,
    firebaseMessagingVapidKey,
    loadMessagingSdk: async () => await import(/* @vite-ignore */ `https://www.gstatic.com/firebasejs/${ATLAS_FIREBASE_SDK_VERSION_V1}/firebase-messaging.js`) as AtlasFirebaseMessagingSdkV1,
  });
  const leadFiles = createAtlasFirebasePublicLeadFilesV1({ loadRuntime: loadAtlasFirebaseSdkRuntimeV1, text });
  const proposals = createAtlasOperationalProposalPersistenceV1({ loadRuntime: loadAtlasFirebaseSdkRuntimeV1, text });
  return Object.freeze({
    sendOperationalMessage: communications.sendMessage,
    subscribeOperationalContacts: communications.subscribeContacts,
    subscribeOperationalConversation: communications.subscribeConversation,
    subscribePublicLeads: leadFiles.subscribePublicLeads,
    registerOperationalDevice: communications.registerDevice,
    subscribeOperationalNotifications: communications.subscribeNotifications,
    publishOperationalRealtime: communications.publishRealtime,
    publishOperationalEvent: communications.publishEvent,
    subscribeOperationalControlCenter: communications.subscribeControlCenter,
    saveOperationalProposal: proposals.save,
  });
}

