interface AtlasFirebasePublicLeadStorageRuntimeV1 {
  db: unknown;
  ref(database: unknown, path: string): unknown;
  onValue(reference: unknown, callback: (snapshot: { val(): unknown }) => void): () => void;
  storage: unknown;
  storageRef(storage: unknown, path: string): { fullPath: string };
  uploadBytes(reference: unknown, file: File, metadata: { contentType: string }): Promise<unknown>;
  getDownloadURL(reference: unknown): Promise<string>;
}

/** Own public-lead RTDB reads and Storage uploads; Firebase SDK stays injected. */
export function createAtlasFirebasePublicLeadFilesV1(input: {
  loadRuntime(): Promise<AtlasFirebasePublicLeadStorageRuntimeV1>;
  text(value: unknown, max?: number): string;
}): AtlasFirebasePublicLeadFilesV1 {
  return Object.freeze({
    async subscribePublicLeads(onChange: (records: Record<string, unknown>) => void = () => undefined): Promise<() => void> {
      const runtime = await input.loadRuntime();
      if (!runtime?.db || typeof runtime.ref !== 'function' || typeof runtime.onValue !== 'function') {
        console.info('Firebase Realtime Database indisponível; leads em tempo real desativados.');
        return () => undefined;
      }
      return runtime.onValue(runtime.ref(runtime.db, 'publicLeads'), snapshot => {
        onChange((snapshot.val() || {}) as Record<string, unknown>);
      });
    },

    async uploadPublicLeadFiles(
      sessionId: unknown,
      files: Record<string, File | null | undefined> = {},
      options: { scope?: unknown } = {},
    ): Promise<Record<string, unknown>> {
      const runtime = await input.loadRuntime();
      const scope = input.text(options.scope || 'documents', 40);
      const id = input.text(sessionId || `session-${Date.now()}`, 120);
      const result: Record<string, unknown> = {};
      for (const [kind, file] of Object.entries(files || {})) {
        if (!file) continue;
        const contentType = String(file.type || '');
        const allowed = contentType.startsWith('image/') || contentType === 'application/pdf';
        if (!allowed || Number(file.size || 0) > 12 * 1024 * 1024) {
          throw new Error('Cada arquivo deve ser imagem ou PDF de até 12 MB.');
        }
        const safeName = String(file.name || `${kind}.bin`).replace(/[^a-z0-9._-]/gi, '-').slice(-96);
        const storageRef = runtime.storageRef(runtime.storage, `publicLeadSessions/${id}/${scope}/${kind}-${Date.now()}-${safeName}`);
        await runtime.uploadBytes(storageRef, file, { contentType: contentType || 'application/octet-stream' });
        result[kind] = {
          name: input.text(file.name, 120),
          contentType: input.text(contentType, 80),
          size: Number(file.size) || 0,
          storagePath: storageRef.fullPath,
          url: await runtime.getDownloadURL(storageRef),
        };
      }
      return result;
    },
  });
}

export interface AtlasFirebasePublicSalesPersistenceV1 {
  savePublicLead(input?: Record<string, unknown>): Promise<string | null | undefined>;
  savePublicReservation(input?: Record<string, unknown>, files?: Record<string, File | null | undefined>): Promise<string | null | undefined>;
  savePublicFieldRecord(input?: Record<string, unknown>, photoFile?: File | null): Promise<string | null | undefined>;
  saveFieldConfirmation(input?: Record<string, unknown>): Promise<{ record: { id: string | null | undefined }; propagated: Array<{ type: string; message: string }> }>;
}

interface AtlasFirebasePublicSalesRuntimeV1 {
  db: unknown;
  storage: unknown;
  ref(database: unknown, path: string): unknown;
  push(reference: unknown): { key?: string | null };
  serverTimestamp(): unknown;
  set(reference: unknown, value: unknown): Promise<unknown>;
  storageRef(storage: unknown, path: string): { fullPath: string };
  uploadBytes(reference: unknown, file: File, metadata: { contentType: string }): Promise<unknown>;
  getDownloadURL(reference: unknown): Promise<string>;
}

/** Own public lead, reservation, and field-submission payload policy; inject Firebase SDK access. */
export function createAtlasFirebasePublicSalesPersistenceV1(input: {
  loadRuntime(): Promise<AtlasFirebasePublicSalesRuntimeV1>;
  text(value: unknown, max?: number): string;
}): AtlasFirebasePublicSalesPersistenceV1 {
  const reservationFileKinds = new Set(['identityFront', 'identityBack', 'addressProof', 'paymentProof']);
  const digitsOnly = (value: unknown): string => String(value ?? '').replace(/\D/g, '');

  return Object.freeze({
    async savePublicLead(lead: Record<string, unknown> = {}): Promise<string | null | undefined> {
      const runtime = await input.loadRuntime();
      const leadRef = runtime.push(runtime.ref(runtime.db, 'publicLeads'));
      const payload = {
        name: input.text(lead.name, 120),
        whatsapp: input.text(lead.whatsapp, 40),
        instagramHandle: input.text(lead.instagramHandle || lead.instagram, 60),
        email: input.text(lead.email, 160).toLowerCase(),
        objective: input.text(lead.objective, 60),
        sun: input.text(lead.sun, 30),
        altitude: input.text(lead.altitude, 40),
        terrain: input.text(lead.terrain, 40),
        budget: input.text(lead.budget, 60),
        notes: input.text(lead.notes || lead.chatIntent, 500),
        conversation: input.text(lead.chatIntent, 500),
        source: 'belavista-public-lead',
        createdAt: runtime.serverTimestamp(),
        updatedAt: runtime.serverTimestamp(),
      };
      await runtime.set(leadRef, payload);
      return leadRef.key;
    },

    async savePublicReservation(
      reservation: Record<string, unknown> = {},
      files: Record<string, File | null | undefined> = {},
    ): Promise<string | null | undefined> {
      const runtime = await input.loadRuntime();
      const reservationRef = runtime.push(runtime.ref(runtime.db, 'publicReservations'));
      const reservationId = reservationRef.key;
      const documents: Record<string, Record<string, unknown>> = {};
      for (const [kind, file] of Object.entries(files || {})) {
        if (!reservationFileKinds.has(kind) || !file) continue;
        const contentType = String(file.type || '');
        const allowed = contentType.startsWith('image/') || contentType === 'application/pdf';
        if (!allowed || file.size > 12 * 1024 * 1024)
          throw new Error('Cada documento deve ser uma imagem ou PDF de até 12 MB.');
        const safeName = String(file.name || `${kind}.bin`).replace(/[^a-z0-9._-]/gi, '-').slice(-96);
        const storageRef = runtime.storageRef(runtime.storage, `publicReservations/${reservationId}/${kind}-${Date.now()}-${safeName}`);
        await runtime.uploadBytes(storageRef, file, { contentType: contentType || 'application/octet-stream' });
        documents[kind] = {
          name: input.text(file.name, 120),
          contentType: input.text(contentType, 80),
          size: Number(file.size) || 0,
          storagePath: storageRef.fullPath,
          url: await runtime.getDownloadURL(storageRef),
        };
      }
      const cpf = digitsOnly(reservation.cpf);
      const payload = {
        fullName: input.text(reservation.fullName || reservation.name, 120),
        cpfLast4: cpf.slice(-4),
        birthDate: input.text(reservation.birthDate, 20),
        lot: input.text(reservation.lot, 60),
        whatsapp: input.text(reservation.whatsapp, 40),
        email: input.text(reservation.email, 160).toLowerCase(),
        objective: input.text(reservation.objective, 60),
        status: input.text(reservation.status || 'Documentos em análise', 60),
        reviewResult: input.text(reservation.reviewResult, 80),
        lastInteraction: 'Documentos enviados para conferência cadastral',
        pixTxid: input.text(reservation.pixTxid, 25),
        pixPayload: input.text(reservation.pixPayload, 700),
        documents,
        consent: true,
        source: 'belavista-public-reservation',
        createdAt: runtime.serverTimestamp(),
        updatedAt: runtime.serverTimestamp(),
      };
      await runtime.set(reservationRef, payload);
      return reservationId;
    },

    async savePublicFieldRecord(
      record: Record<string, unknown> = {},
      photoFile: File | null = null,
    ): Promise<string | null | undefined> {
      const runtime = await input.loadRuntime();
      if (photoFile && (!String(photoFile.type || '').startsWith('image/') || photoFile.size > 12 * 1024 * 1024))
        throw new Error('A foto deve ser uma imagem de até 12 MB.');
      const recordRef = runtime.push(runtime.ref(runtime.db, 'publicFieldRecords'));
      const recordId = recordRef.key;
      let photo: Record<string, unknown> | null = null;
      if (photoFile) {
        const safeName = String(photoFile.name || 'evidencia.jpg').replace(/[^a-z0-9._-]/gi, '-').slice(-96);
        const storageRef = runtime.storageRef(runtime.storage, `publicFieldRecords/${recordId}/${Date.now()}-${safeName}`);
        await runtime.uploadBytes(storageRef, photoFile, { contentType: photoFile.type || 'image/jpeg' });
        photo = {
          name: input.text(photoFile.name, 120),
          contentType: input.text(photoFile.type, 80),
          size: Number(photoFile.size) || 0,
          storagePath: storageRef.fullPath,
          url: await runtime.getDownloadURL(storageRef),
        };
      }
      const payload = {
        project: input.text(record.project, 100),
        stage: input.text(record.stage, 100),
        activity: input.text(record.activity, 140),
        category: input.text(record.category, 100),
        responsible: input.text(record.responsible, 120),
        date: input.text(record.date, 20),
        time: input.text(record.time, 12),
        progress: Math.max(0, Math.min(100, Number(record.progress) || 0)),
        status: input.text(record.status, 40),
        details: input.text(record.details, 1200),
        photo,
        source: 'belavista-twa-field-record',
        createdAt: runtime.serverTimestamp(),
        updatedAt: runtime.serverTimestamp(),
      };
      await runtime.set(recordRef, payload);
      return recordId;
    },

    async saveFieldConfirmation(confirmation: Record<string, unknown> = {}): Promise<{ record: { id: string | null | undefined }; propagated: Array<{ type: string; message: string }> }> {
      const runtime = await input.loadRuntime();
      const services = Array.isArray(confirmation.servicos)
        ? confirmation.servicos.map(item => input.text(item, 120)).filter(Boolean).slice(0, 12)
        : [];
      if (!confirmation.confirmed || !services.length)
        throw new Error('Confirme o serviço e selecione os itens conferidos.');
      const recordRef = runtime.push(runtime.ref(runtime.db, 'fieldConfirmations'));
      const stage = input.text(confirmation.etapa, 100);
      const stageKey = stage.toLocaleLowerCase('pt-BR');
      const propagated = [{ type: 'record', message: 'Registro auditável encaminhado ao painel operacional.' }];
      if (stageKey.includes('água') || stageKey.includes('agua') || stageKey.includes('drenagem'))
        propagated.push({ type: 'dependency', message: 'Checagem de liberação antes da pavimentação foi solicitada.' });
      if (stageKey.includes('elétrica') || stageKey.includes('eletrica'))
        propagated.push({ type: 'dependency', message: 'Requisitos e prazo de ligação Coelba foram sinalizados.' });
      const { evidence: _evidenceFile, ...safeInput } = confirmation;
      const payload: Record<string, unknown> = {
        ...safeInput,
        responsavel: input.text(confirmation.responsavel, 120),
        etapa: stage,
        atividade: input.text(confirmation.atividade, 140),
        detalhes: input.text(confirmation.detalhes, 1200),
        servicos: services,
        progresso: Math.max(0, Math.min(100, Number(confirmation.progresso) || 0)),
        source: 'belavista-github-field-portal',
        propagated,
        createdAt: runtime.serverTimestamp(),
        updatedAt: runtime.serverTimestamp(),
      };
      delete payload.evidenceUri;
      await runtime.set(recordRef, payload);
      return { record: { id: recordRef.key }, propagated };
    },
  });
}

export interface AtlasOperationalProposalAttachmentV1 {
  name: string;
  type: string;
  size: number;
  storagePath: string;
  url: string;
}

export interface AtlasOperationalProposalPersistenceV1 {
  save(input?: Record<string, unknown>, files?: File[], actor?: Record<string, unknown>): Promise<{ id: string; attachments: AtlasOperationalProposalAttachmentV1[] }>;
}

interface AtlasOperationalProposalRuntimeV1 {
  db: unknown;
  ref(database: unknown, path: string): unknown;
  push(reference: unknown): { key?: string | null };
  storage: unknown;
  storageRef(storage: unknown, path: string): { fullPath: string };
  uploadBytes(reference: unknown, file: File, metadata: { contentType: string }): Promise<unknown>;
  getDownloadURL(reference: unknown): Promise<string>;
  set(reference: unknown, value: unknown): Promise<unknown>;
  serverTimestamp(): unknown;
}

/** Persist proposals and attachments without moving Firebase SDK concerns into the view. */
export function createAtlasOperationalProposalPersistenceV1(input: {
  loadRuntime(): Promise<AtlasOperationalProposalRuntimeV1>;
  text(value: unknown, max?: number): string;
}): AtlasOperationalProposalPersistenceV1 {
  return Object.freeze({
    async save(
      proposal: Record<string, unknown> = {},
      files: File[] = [],
      actor: Record<string, unknown> = {},
    ): Promise<{ id: string; attachments: AtlasOperationalProposalAttachmentV1[] }> {
      const runtime = await input.loadRuntime();
      const proposalRef = runtime.push(runtime.ref(runtime.db, 'operationalProposals'));
      const proposalId = proposalRef.key as string;
      const attachments: AtlasOperationalProposalAttachmentV1[] = [];
      for (const file of files || []) {
        if (!file || file.size > 12 * 1024 * 1024) throw new Error('Cada anexo deve ter no máximo 12 MB.');
        const safeName = String(file.name || 'anexo').replace(/[^a-z0-9._-]/gi, '-').slice(-96);
        const storageRef = runtime.storageRef(runtime.storage, `operationalProposals/${actor.uid || 'unknown'}/${proposalId}/${safeName}`);
        await runtime.uploadBytes(storageRef, file, { contentType: file.type || 'application/octet-stream' });
        attachments.push({
          name: file.name || safeName,
          type: file.type || '',
          size: Number(file.size) || 0,
          storagePath: storageRef.fullPath,
          url: await runtime.getDownloadURL(storageRef),
        });
      }
      const payload = {
        ...proposal,
        uid: String(actor.uid || ''),
        profile: String(proposal.profile || ''),
        attachments,
        inference: proposal.inference && typeof proposal.inference === 'object' ? proposal.inference : null,
        source: 'belavista-twa-proposal',
        createdAt: runtime.serverTimestamp(),
        updatedAt: runtime.serverTimestamp(),
      };
      await runtime.set(proposalRef, payload);
      return { id: proposalId, attachments };
    },
  });
}

/** Own Firebase realtime personal messaging policy while keeping SDK access injected. */
export function createAtlasFirebaseOperationalCommunicationsV1(input: {
  loadRuntime(): Promise<AtlasFirebaseOperationalRuntimeV1>;
  text(value: unknown, max?: number): string;
  slug(value: unknown): string;
  readIntegrationSettings(): Record<string, unknown>;
  ensureInstallationId(): string;
  readStoredChannelUid(): string;
  readStoredChannelRole(): string;
  rememberOperationalChannel(device: Record<string, unknown>): void;
  defaultProjectId: string;
  navigatorRef: Navigator | undefined;
  notificationApi: { permission: NotificationPermission; requestPermission(): Promise<NotificationPermission> } | null;
  firebaseMessagingVapidKey(): string;
  loadMessagingSdk(): Promise<AtlasFirebaseMessagingSdkV1>;
}): AtlasFirebaseOperationalCommunicationsV1 {
  const channelUidForRole = (role: unknown, settings: Record<string, unknown>, authUid = ''): string => {
    const normalized = input.slug(role).split('/').pop();
    if (normalized === 'owner') return input.text(settings.ownerNotificationUid || authUid, 160);
    if (normalized === 'admin') return input.text(settings.adminNotificationUid || authUid, 160);
    if (normalized === 'foreman') return input.text(settings.foremanNotificationUid || authUid, 160);
    if (normalized === 'developer') return input.text(authUid, 160);
    return '';
  };
  const resolveChannelUid = (actor: Record<string, unknown>, settings: Record<string, unknown>, installationId: string): string => {
    const role = input.text(actor.role || input.readStoredChannelRole() || 'owner', 40);
    return input.text(
      actor.uid || channelUidForRole(role, settings, '') || input.readStoredChannelUid() || installationId || `device-${Date.now()}`,
      160,
    );
  };
  const notificationEnvelope = (item: AtlasFirebaseOperationalNotificationV1, context: Record<string, unknown>): Record<string, unknown> => ({
    id: input.text(item.id || `${input.slug(item.type || 'notification')}-${Date.now()}`, 120),
    type: input.text(item.type || 'operational.notice', 80),
    severity: input.text(item.severity || 'info', 40),
    title: input.text(item.title || 'Atualização operacional', 180),
    message: input.text(item.message || '', 1200),
    actionUrl: input.text(item.actionUrl || '/', 240),
    role: input.text(item.role || context.role || 'owner', 40),
    source: input.text(context.source || 'belavista-client-operational', 80),
    loopId: input.text(context.loopId || '', 120),
    reason: input.text(context.reason || '', 80),
    projectId: input.text(context.projectId || input.defaultProjectId, 120),
    stageKey: input.text(item.stageKey || context.stageKey || '', 80),
    createdAt: context.createdAt,
    status: 'unread',
  });
  const asJson = (value: unknown): unknown => JSON.parse(JSON.stringify(value ?? null)) as unknown;
  const conversationKey = (left: unknown, right: unknown): string => [
    input.slug(left).replaceAll('/', '-'),
    input.slug(right).replaceAll('/', '-'),
  ].filter(Boolean).sort().join('__');

  return Object.freeze({
    async subscribeContacts(
      actor: Record<string, unknown> = {},
      onChange: (contacts: (CommunicationContact & { pushEnabled: boolean; updatedAt: unknown })[]) => void = () => undefined,
    ): Promise<() => void> {
      const runtime = await input.loadRuntime();
      if (!runtime?.db || typeof runtime.ref !== 'function' || typeof runtime.onValue !== 'function') {
        console.info('Firebase Realtime Database sem runtime de referência; contatos em tempo real desativados.');
        return () => undefined;
      }
      const ownUid = input.text(actor.uid, 160);
      return runtime.onValue(runtime.ref(runtime.db, 'metadata'), snapshot => {
        const value = snapshot.val();
        const metadata = value && typeof value === 'object' ? value as Record<string, unknown> : {};
        const contacts = Object.entries(metadata).map(([uid, raw]) => {
          const entry = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {};
          return {
            uid: input.text(uid, 160),
            name: input.text(entry.actorName || entry.name || uid, 120),
            role: input.text(entry.role || 'user', 40),
            label: input.text(entry.actorLabel || '', 120),
            online: Boolean(entry.online),
            pushEnabled: Boolean(entry.pushEnabled),
            updatedAt: entry.updatedAt || null,
          };
        }).filter(contact => contact.uid && contact.uid !== ownUid).sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
        onChange(contacts);
      });
    },

    async subscribeConversation(
      actor: Record<string, unknown> = {},
      contact: CommunicationContact = { uid: '', name: '', role: '', label: '', online: false },
      onChange: (messages: CommunicationMessage[], metadata?: { threadId: string; contactUid: string }) => void = () => undefined,
    ): Promise<() => void> {
      const runtime = await input.loadRuntime();
      const ownUid = input.text(actor.uid, 160);
      const contactUid = input.text(contact.uid, 160);
      if (!ownUid || !contactUid) throw new Error('Remetente e contato são obrigatórios.');
      const threadId = conversationKey(ownUid, contactUid);
      const baseRef = runtime.ref(runtime.db, `operationalConversations/${threadId}/messages`);
      const messagesRef = runtime.query && runtime.limitToLast ? runtime.query(baseRef, runtime.limitToLast(100)) : baseRef;
      const unsubscribe = runtime.onValue(messagesRef, snapshot => {
        const value = snapshot.val();
        const entries = value && typeof value === 'object' ? value as Record<string, unknown> : {};
        const messages = Object.entries(entries).map(([id, raw]) => ({
          ...(raw && typeof raw === 'object' ? raw as CommunicationMessage : {}),
          id,
        })).sort((a, b) => Number(a.createdAt || 0) - Number(b.createdAt || 0));
        onChange(messages, { threadId, contactUid });
      });
      await runtime.update(runtime.ref(runtime.db, `operationalConversations/${threadId}/participants`), {
        [ownUid]: { uid: ownUid, name: input.text(actor.name || ownUid, 120), role: input.text(actor.role || 'user', 40), updatedAt: runtime.serverTimestamp() },
        [contactUid]: { uid: contactUid, name: input.text(contact.name || contactUid, 120), role: input.text(contact.role || 'user', 40), updatedAt: runtime.serverTimestamp() },
      });
      return unsubscribe;
    },

    async sendMessage(
      actor: Record<string, unknown> = {},
      contact: CommunicationContact = { uid: '', name: '', role: '', label: '', online: false },
      message = '',
    ): Promise<{ id: string; threadId: string; notificationId: string }> {
      const runtime = await input.loadRuntime();
      const ownUid = input.text(actor.uid, 160);
      const contactUid = input.text(contact.uid, 160);
      const body = input.text(message, 2000);
      if (!ownUid || !contactUid) throw new Error('Selecione um contato autenticado.');
      if (!body) throw new Error('Digite uma mensagem.');
      const threadId = conversationKey(ownUid, contactUid);
      const messageRef = runtime.push(runtime.ref(runtime.db, `operationalConversations/${threadId}/messages`));
      const id = String(messageRef.key || '');
      if (!id) throw new Error('Firebase não gerou o identificador da mensagem.');
      const createdAt = runtime.serverTimestamp();
      const payload = {
        id, threadId, fromUid: ownUid, fromName: input.text(actor.name || ownUid, 120), fromRole: input.text(actor.role || 'user', 40),
        toUid: contactUid, toName: input.text(contact.name || contactUid, 120), toRole: input.text(contact.role || 'user', 40),
        message: body, status: 'sent', createdAt, source: 'belavista-twa-realtime-message',
      };
      const notificationId = `MSG-${id}`;
      const notification = {
        id: notificationId, type: 'message.received', severity: 'info', title: `Mensagem de ${payload.fromName}`, message: body,
        actionUrl: '/admin/workers?panel=messages', role: payload.toRole, source: 'belavista-twa-realtime-message',
        threadId, fromUid: ownUid, status: 'unread', createdAt,
      };
      await runtime.update(runtime.ref(runtime.db), {
        [`operationalConversations/${threadId}/messages/${id}`]: payload,
        [`operationalConversations/${threadId}/updatedAt`]: createdAt,
        [`notifications/${contactUid}/${notificationId}`]: notification,
        [`agentBridgeEvents/message-${id}`]: {
          id: `message-${id}`, type: 'message.sent', entity: 'operationalConversations', entityId: threadId,
          actor: { uid: ownUid, role: payload.fromRole, name: payload.fromName },
          payload: { toUid: contactUid, messageId: id }, source: 'belavista-twa-realtime-message', createdAt,
        },
      });
      return { id, threadId, notificationId };
    },

    async subscribeNotifications(
      actor: Record<string, unknown> = {},
      onChange: (records: Record<string, unknown>, channel: Record<string, unknown>) => void = () => undefined,
    ): Promise<() => void> {
      const runtime = await input.loadRuntime();
      if (!runtime?.db || typeof runtime.ref !== 'function' || typeof runtime.onValue !== 'function') {
        console.info('Firebase Realtime Database indisponível; notificações em tempo real desativadas.');
        return () => undefined;
      }
      const settings = input.readIntegrationSettings();
      const channel: Record<string, unknown> = {
        uid: String(actor.uid || input.readStoredChannelUid() || '').trim(),
        role: String(actor.role || input.readStoredChannelRole() || '').trim(),
        installationId: input.ensureInstallationId(),
      };
      channel.uid = resolveChannelUid(actor, settings, String(channel.installationId || ''));
      channel.role = input.text(actor.role || input.readStoredChannelRole() || 'owner', 40);
      input.rememberOperationalChannel(channel);
      let direct: Record<string, unknown> = {};
      let commercialArea: Record<string, unknown> = {};
      const objectSpread = (value: unknown): Record<string, unknown> => value == null ? {} : Object.assign({}, Object(value)) as Record<string, unknown>;
      const emit = (): void => onChange({ ...commercialArea, ...direct }, channel);
      const own = runtime.onValue(runtime.ref(runtime.db, `notifications/${channel.uid}`), snapshot => {
        direct = objectSpread(snapshot.val() || {});
        emit();
      });
      const role = input.slug(channel.role).split('/').pop();
      let area: () => void = () => undefined;
      if (role === 'commercial' || role === 'sales' || role === 'admin' || role === 'owner' || role === 'developer') {
        area = runtime.onValue(runtime.ref(runtime.db, 'notificationAreas/commercial'), snapshot => {
          commercialArea = objectSpread(snapshot.val() || {});
          emit();
        });
      }
      return () => { own?.(); area?.(); };
    },

    async subscribeControlCenter(
      actor: Record<string, unknown> = {},
      onChange: (snapshot: AtlasFirebaseOperationalSnapshotV1) => void = () => undefined,
    ): Promise<() => void> {
      const runtime = await input.loadRuntime();
      const projectId = input.text(actor.projectId || input.defaultProjectId, 120);
      let snapshot: unknown = null;
      let events: unknown = {};
      const emit = (source: AtlasFirebaseOperationalSnapshotV1['source']): void => onChange({
        projectId, snapshot, events, source, updatedAt: new Date().toISOString(),
      });
      const unsubscribeSnapshot = runtime.onValue(runtime.ref(runtime.db, `operationalSnapshots/${projectId}`), value => {
        snapshot = value.val() || null;
        emit('operationalSnapshots');
      });
      const eventBase = runtime.ref(runtime.db, 'agentBridgeEvents');
      const eventRef = runtime.query && runtime.limitToLast ? runtime.query(eventBase, runtime.limitToLast(30)) : eventBase;
      const unsubscribeEvents = runtime.onValue(eventRef, value => {
        events = value.val() || {};
        emit('agentBridgeEvents');
      });
      return () => { unsubscribeSnapshot?.(); unsubscribeEvents?.(); };
    },

    async publishRealtime(
      actor: Record<string, unknown> = {},
      payload: AtlasFirebaseOperationalPayloadV1 = {},
      context: Record<string, unknown> = {},
    ): Promise<{ projectId: string; notificationsPublished: number; destinationCount: number; areaCount: number }> {
      const runtime = await input.loadRuntime();
      const settings = input.readIntegrationSettings();
      const installationId = input.ensureInstallationId();
      const channelUid = resolveChannelUid(actor, settings, installationId);
      const panorama = payload.panorama || {};
      const projectId = input.text(payload.projectId || panorama.projectId || context.projectId || input.defaultProjectId, 120);
      const notifications = Array.isArray(panorama.notifications) ? panorama.notifications : Array.isArray(payload.notifications) ? payload.notifications : [];
      const rootUpdates: Record<string, unknown> = {};
      rootUpdates[`operationalSnapshots/${projectId}`] = {
        projectId,
        loopId: input.text(payload.loopId || '', 120),
        reason: input.text(context.reason || payload.reason || 'client.manual', 80),
        source: 'belavista-client-operational',
        actor: {
          channelUid,
          role: input.text(actor.role || 'owner', 40),
          actorUid: input.text(actor.uid || '', 120),
          name: input.text(actor.name || 'Dispositivo', 120),
          label: input.text(actor.label || '', 120),
        },
        summary: asJson(panorama.summary || payload.summary || {}),
        guidance: asJson(payload.guidance || {}),
        cashSummary: asJson(payload.cashSummary || {}),
        agenda: asJson(((payload.agenda || []) as unknown[]).slice(0, 24)),
        updatedAt: runtime.serverTimestamp(),
      };
      if (payload.calibration) {
        rootUpdates[`calibrations/${projectId}`] = {
          ...asJson(payload.calibration) as Record<string, unknown>,
          source: 'belavista-client-operational',
          updatedAt: runtime.serverTimestamp(),
        };
      }
      rootUpdates[`agentBridgeEvents/${input.text(payload.loopId || `loop-${Date.now()}`, 120)}`] = {
        id: input.text(payload.loopId || `loop-${Date.now()}`, 120),
        type: 'operational.loop.completed',
        entity: 'operationalSnapshots',
        entityId: projectId,
        actor: {
          channelUid,
          role: input.text(actor.role || 'owner', 40),
          actorUid: input.text(actor.uid || '', 120),
          name: input.text(actor.name || 'Dispositivo', 120),
        },
        reason: input.text(context.reason || payload.reason || 'client.manual', 80),
        summary: asJson(panorama.summary || payload.summary || {}),
        source: 'belavista-client-operational',
        createdAt: runtime.serverTimestamp(),
      };
      const createdAt = runtime.serverTimestamp();
      for (const item of notifications) {
        const envelope = notificationEnvelope(item, {
          createdAt, loopId: payload.loopId, reason: context.reason, projectId, role: item.role,
          source: 'belavista-client-operational', stageKey: item.stageKey,
        });
        const directRecipients = new Set<string>();
        const areaRecipients = new Set<string>();
        for (const destination of Array.isArray(item.destinations) ? item.destinations : []) {
          const normalized = input.text(destination, 160);
          if (!normalized) continue;
          if (normalized.startsWith('rtdb/')) {
            const channel = normalized.slice('rtdb/'.length);
            const uid = channelUidForRole(channel, settings, '');
            if (uid) directRecipients.add(uid);
            else areaRecipients.add(input.slug(channel));
            continue;
          }
          if (normalized.startsWith('uid/')) { directRecipients.add(input.text(normalized.slice(4), 160)); continue; }
          if (normalized.startsWith('area/')) { areaRecipients.add(input.slug(normalized.slice(5))); continue; }
        }
        if (!directRecipients.size) {
          const fallbackUid = channelUidForRole(item.role, settings, '') || channelUid;
          if (fallbackUid) directRecipients.add(fallbackUid);
        }
        for (const uid of directRecipients) rootUpdates[`notifications/${uid}/${String(envelope.id)}`] = { ...envelope, destinationUid: uid };
        for (const area of areaRecipients) rootUpdates[`notificationAreas/${area}/${String(envelope.id)}`] = { ...envelope, area };
      }
      await runtime.update(runtime.ref(runtime.db), rootUpdates);
      return {
        projectId,
        notificationsPublished: notifications.length,
        destinationCount: Object.keys(rootUpdates).filter(key => key.startsWith('notifications/')).length,
        areaCount: Object.keys(rootUpdates).filter(key => key.startsWith('notificationAreas/')).length,
      };
    },

    async publishEvent(event: Record<string, unknown> = {}): Promise<Record<string, unknown>> {
      const runtime = await input.loadRuntime();
      const settings = input.readIntegrationSettings();
      const actor = event.actor && typeof event.actor === 'object' ? event.actor as Record<string, unknown> : {};
      const channelUid = resolveChannelUid(actor, settings, input.ensureInstallationId());
      const id = input.text(event.id || `${input.slug(event.type || 'event')}-${Date.now()}`, 120);
      const payload = {
        id,
        type: input.text(event.type || 'operational.event', 80),
        entity: input.text(event.entity || '', 80),
        entityId: input.text(event.entityId || '', 120),
        actor: {
          channelUid,
          role: input.text(actor.role || event.role || 'owner', 40),
          actorUid: input.text(actor.uid || event.actorUid || '', 120),
          name: input.text(actor.name || event.actorName || 'Dispositivo', 120),
        },
        source: 'belavista-client-event',
        payload: asJson(event.payload || {}),
        createdAt: runtime.serverTimestamp(),
      };
      await runtime.set(runtime.ref(runtime.db, `agentBridgeEvents/${id}`), payload);
      return payload;
    },

    async registerDevice(actor: Record<string, unknown> = {}): Promise<{ device: Record<string, unknown>; permission: string; pushEnabled: boolean; realtime: true; source: 'firebase-client' }> {
      const navigatorRef = input.navigatorRef;
      if (!navigatorRef || !('serviceWorker' in navigatorRef)) throw new Error('Este navegador não oferece Service Worker.');
      const runtime = await input.loadRuntime();
      const registration = await navigatorRef.serviceWorker.ready;
      let fcmToken = '';
      let permission: string = input.notificationApi ? input.notificationApi.permission : 'unsupported';
      if (input.notificationApi && permission !== 'granted') permission = await input.notificationApi.requestPermission();
      const vapidKey = input.firebaseMessagingVapidKey();
      if (permission === 'granted' && vapidKey) {
        const messagingSdk = await input.loadMessagingSdk();
        if (await messagingSdk.isSupported()) {
          fcmToken = await messagingSdk.getToken(messagingSdk.getMessaging(runtime.app), {
            vapidKey,
            serviceWorkerRegistration: registration,
          });
        }
      }
      const installationId = input.ensureInstallationId();
      const settings = input.readIntegrationSettings();
      const channelUid = resolveChannelUid(actor, settings, installationId);
      const device = {
        uid: channelUid,
        role: input.text(actor.role || 'foreman', 40),
        actorUid: input.text(actor.uid || '', 120),
        actorName: input.text(actor.name || 'Dispositivo', 120),
        actorLabel: input.text(actor.label || '', 120),
        installationId,
        fcmToken,
        platform: 'web',
        permission,
        source: 'belavista-client-device',
        updatedAt: runtime.serverTimestamp(),
      };
      await runtime.set(runtime.ref(runtime.db, `operationalDevices/${channelUid}/${installationId}`), device);
      await runtime.set(runtime.ref(runtime.db, `metadata/${channelUid}`), {
        uid: channelUid,
        role: device.role,
        actorUid: device.actorUid,
        actorName: device.actorName,
        actorLabel: device.actorLabel,
        installationId,
        pushEnabled: Boolean(fcmToken),
        updatedAt: runtime.serverTimestamp(),
        source: 'belavista-client-device',
      });
      input.rememberOperationalChannel({ uid: channelUid, role: device.role });
      return { device, permission, pushEnabled: Boolean(fcmToken), realtime: true, source: 'firebase-client' };
    },
  });
}

const atlasWorkerCommunicationsControllersV1 = new WeakMap<Document, AtlasWorkerCommunicationsControllerV1>();

/** Mount the worker's Realtime alerts, push action, personal chat, and Instagram inbox. */
export function mountAtlasWorkerCommunicationsV1(input: {
  documentRef: Document;
  route(path: string, query?: string): string;
  waitForAuth(): Promise<unknown>;
  currentActor(): Record<string, unknown>;
  currentIdToken(): Promise<string | null | undefined> | string | null | undefined;
  fetcher(path: string, init: RequestInit): Promise<Response>;
  services: AtlasWorkerCommunicationsServicesV1;
  componentsTs: typeof import('./components.js');
}): AtlasWorkerCommunicationsControllerV1 | null {
  const existing = atlasWorkerCommunicationsControllersV1.get(input.documentRef);
  if (existing) return existing;
  if (typeof input.componentsTs.mountAtlasWorkerRealtimeNotificationsV1 !== 'function'
    || typeof input.componentsTs.AtlasWorkerRealtimeNotificationsV1 !== 'function') return null;

  const { documentRef, componentsTs } = input;
  const panel = componentsTs.mountAtlasWorkerRealtimeNotificationsV1({ documentRef, route: input.route });
  if (!panel) return null;

  const system = program().next().value;
  system.installCommunicationsPanel(documentRef, { ...input.services, currentActor: input.currentActor });
  documentRef.querySelectorAll('[data-communication-sidebar], .communication-scrim').forEach(element => element.remove());
  const request = createWorkerWorkbenchApiV1({
    fetcher: input.fetcher,
    waitForAuth: input.waitForAuth,
    currentActor: input.currentActor,
    currentIdToken: input.currentIdToken,
  });
  let active = false;
  let unsubscribe: (() => void) | null = null;

  const onOpen = (event: Event): void => {
    const target = event.target instanceof Element ? event.target.closest<HTMLButtonElement>('[data-open-communications]') : null;
    if (!target) return;
    const tab = target.dataset.openCommunications || '';
    const messages = documentRef.querySelector<HTMLElement & { setOpen?: (open: boolean, tab?: 'personal' | 'instagram') => void }>('atlas-communications');
    if (tab === 'notifications') { messages?.setOpen?.(false); panel.setOpen(true); }
    else if (tab === 'messages') { panel.setOpen(false); documentRef.dispatchEvent(new CustomEvent('belavista:open-communications', { detail: { tab: 'personal' } })); }
    else if (tab === 'social') { panel.setOpen(false); documentRef.dispatchEvent(new CustomEvent('belavista:open-communications', { detail: { tab: 'instagram' } })); }
  };
  const onPanelTab = (event: Event): void => {
    const detail = (event as CustomEvent<{ element?: Element; tab?: string }>).detail;
    if (detail?.element !== panel || (detail.tab !== 'personal' && detail.tab !== 'instagram')) return;
    documentRef.dispatchEvent(new CustomEvent('belavista:open-communications', { detail: { tab: detail.tab } }));
  };
  const onPush = (event: Event): void => {
    const detail = (event as CustomEvent<{ element?: Element }>).detail;
    if (detail?.element !== panel || !active) return;
    panel.setPushStatus('Registrando este celular…', true);
    void (async () => {
      try {
        const actor = input.currentActor();
        const result = await input.services.registerDevice(actor);
        await request('/api/devices', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({
            installationId: result.device.installationId,
            fcmToken: result.device.fcmToken,
            platform: 'twa',
          }),
        }).catch(() => null);
        panel.setPushStatus(
          result.pushEnabled ? 'Push e Realtime Database ativos neste celular.' : 'Realtime Database ativo; push aguarda a chave VAPID do ambiente.',
          false,
          true,
        );
      } catch (error) {
        panel.setPushStatus(`Não foi possível ativar: ${error instanceof Error ? error.message : String(error)}`);
      }
    })();
  };
  documentRef.addEventListener('click', onOpen);
  documentRef.addEventListener('atlas:worker-notifications-tab-v1', onPanelTab);
  documentRef.addEventListener('atlas:worker-push-enable-v1', onPush);

  const start = async (): Promise<boolean> => {
    if (active) return true;
    active = true;
    panel.setNotifications({});
    panel.setPushStatus('Aguardando permissão deste dispositivo.');
    void Promise.resolve().then(() => input.services.registerServiceWorker()).catch(() => null);
    try {
      await input.waitForAuth();
      unsubscribe = await input.services.subscribeNotifications(input.currentActor(), value => panel.setNotifications(value));
    } catch (error) {
      panel.setPushStatus(`Canal indisponível: ${error instanceof Error ? error.message : String(error)}`);
    }
    if (new URLSearchParams(documentRef.defaultView?.location.search || '').get('panel') === 'messages') {
      documentRef.dispatchEvent(new CustomEvent('belavista:open-communications', { detail: { tab: 'personal' } }));
    }
    return true;
  };
  const stop = (): void => {
    active = false;
    unsubscribe?.(); unsubscribe = null;
    documentRef.removeEventListener('click', onOpen);
    documentRef.removeEventListener('atlas:worker-notifications-tab-v1', onPanelTab);
    documentRef.removeEventListener('atlas:worker-push-enable-v1', onPush);
    panel.remove();
    documentRef.querySelector('atlas-communications')?.remove();
    if (atlasWorkerCommunicationsControllersV1.get(documentRef) === controller)
      atlasWorkerCommunicationsControllersV1.delete(documentRef);
  };
  const controller = Object.freeze({ start, stop });
  atlasWorkerCommunicationsControllersV1.set(documentRef, controller);
  return controller;
}

export interface AtlasStageAdministrationHostStoreV1 {
  get(): Record<string, any>;
  set(patch: Record<string, any>): unknown;
  subscribe(listener: (state: Record<string, any>) => void): () => unknown;
}
export interface AtlasStageAdministrationHostPortsV1 {
  appStore: AtlasStageAdministrationHostStoreV1;
  apiFetch(path: string, init?: RequestInit): Promise<Response>;
  document?: Document;
  window?: Window;
  storage?: Storage;
}

/** Persisted service DTO for the stage report endpoint. */
export interface AtlasStageAdministrationReportV1 extends AtlasStageAdministrationWorkspaceModelV1 {}

/** Move the detailed stage report and AI configuration lifecycle into the program. */
export function installAtlasStageAdministrationV1(input: AtlasStageAdministrationHostPortsV1): { dispose(): void } {
  const documentRef = input.document || globalThis.document;
  const windowRef = (input.window || documentRef?.defaultView || globalThis.window) as (Window & typeof globalThis) | undefined;
  if (!documentRef || !windowRef) throw new Error('A administração da etapa precisa de um documento ativo.');
  const cache = new Map<number, AtlasStageAdministrationReportV1>();
  const pending = new Map<number, Promise<void>>();
  let viewController: AtlasStageAdministrationViewControllerV1 | null = null;
  const currentStageId = (): number | null => Number(input.appStore.get().selectedStage) || null;
  const notify = (message: string, tone = 'info'): void => { windowRef.dispatchEvent(new CustomEvent('belavista:notify', { detail: { message, tone } })); };
  const actorHeaders = (extra: Record<string, string> = {}): Record<string, string> => {
    const actor = input.appStore.get().currentActor || { role: 'owner', uid: 'local-warley', name: 'Warley' };
    return { 'X-Belavista-Role': String(actor.role), 'X-Belavista-User': String(actor.uid), 'X-Belavista-Name': String(actor.name), ...extra };
  };
  const splitLines = (value: unknown): string[] => String(value || '').split(/\r?\n|,/).map(item => item.trim()).filter(Boolean);
  const field = (values: AtlasStageAdministrationFormValuesV1, name: string): string => values[name] || '';
  const asReport = (value: unknown): AtlasStageAdministrationReportV1 => value && typeof value === 'object' && !Array.isArray(value) ? value as AtlasStageAdministrationReportV1 : {};

  async function loadStage(stageId: number, force = false): Promise<void> {
    if (!stageId) return;
    if (cache.has(stageId) && !force) { viewController?.render(cache.get(stageId)!); return; }
    const active = pending.get(stageId);
    if (active) return active;
    viewController?.setLoading(true);
    const task = (async () => {
      try {
        const response = await input.apiFetch(`/api/stages-admin/${stageId}/report`, { cache: 'no-store', headers: actorHeaders() });
        const result = asReport(await response.json());
        if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`));
        const data = asReport(result.report || result.stage || result);
        cache.set(stageId, data);
        viewController?.render(data);
      } catch (error) {
        globalThis.console.info('[stage-admin] relatório persistente indisponível', error);
        viewController?.showUnavailable();
      } finally { viewController?.setLoading(false); }
    })();
    pending.set(stageId, task);
    try { await task; } finally { if (pending.get(stageId) === task) pending.delete(stageId); }
  }

  const saveMetadata = async (values: AtlasStageAdministrationFormValuesV1): Promise<string> => {
    const stageId = currentStageId(); if (!stageId) return 'Nenhuma etapa selecionada.';
    const payload: Record<string, string | number> = { ...values, progress: Number(values.progress) || 0 };
    try {
      const response = await input.apiFetch(`/api/stages-admin/${stageId}`, { method: 'PUT', headers: actorHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify(payload) });
      const result = asReport(await response.json()); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`));
      cache.set(stageId, asReport(result.stage || result));
      notify('Etapa atualizada.', 'success');
      await loadStage(stageId, true);
      return 'Propriedades salvas e adicionadas ao histórico.';
    } catch (error) {
      notify('Não foi possível atualizar a etapa.', 'warning');
      throw error;
    }
  };

  const saveAiRules = async (values: AtlasStageAdministrationFormValuesV1): Promise<string> => {
    const stageId = currentStageId(); if (!stageId) return 'Nenhuma etapa selecionada.';
    const current = cache.get(stageId)?.aiConfig || {};
    const payload = {
      requirements: splitLines(field(values, 'requirements')), conditions: splitLines(field(values, 'conditions')),
      typicalDescription: field(values, 'typicalDescription'), requestHints: splitLines(field(values, 'requestHints')),
      evidenceFocus: splitLines(field(values, 'evidenceFocus')), procurementFocus: splitLines(field(values, 'procurementFocus')),
      notificationTargets: current.notificationTargets || {}, executionProfile: current.executionProfile || {},
    };
    try {
      const response = await input.apiFetch(`/api/stages-admin/${stageId}/ai`, { method: 'PUT', headers: actorHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify(payload) });
      const result = asReport(await response.json()); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`));
      cache.set(stageId, asReport(result.stage || result));
      notify('Regras da IA atualizadas.', 'success');
      await loadStage(stageId, true);
      return 'Requisitos e condições persistidos e disponíveis para o ciclo operacional.';
    } catch (error) {
      notify('Não foi possível salvar as regras da IA.', 'warning');
      throw error;
    }
  };

  const saveDedicatedContext = async (draft: AtlasStageAdministrationContextDraftV1): Promise<string> => {
    const stageId = currentStageId(); if (!stageId) return 'Nenhuma etapa selecionada.';
    const { values, contextKey, materialRows } = draft;
    const current = cache.get(stageId)?.aiConfig || {};
    const payload = {
      requirements: splitLines(field(values, 'requirements')), conditions: splitLines(field(values, 'conditions')),
      typicalDescription: field(values, 'typicalDescription'), requestHints: splitLines(field(values, 'requestHints')),
      evidenceFocus: splitLines(field(values, 'evidenceFocus')), procurementFocus: splitLines(field(values, 'procurementFocus')),
      notificationTargets: { owner: splitLines(field(values, 'notifyOwner')), admin: splitLines(field(values, 'notifyAdmin')), foreman: splitLines(field(values, 'notifyForeman')) },
      executionProfile: { ...(current.executionProfile || {}), materialsTable: materialRows },
    };
    let localPreferenceSaved = false;
    try {
      const storage = input.storage || windowRef.localStorage, settings = JSON.parse(storage.getItem('belavista.integrations.v1') || '{}') as Record<string, any>;
      const previous = settings.stageProfiles?.[contextKey] || {};
      settings.stageProfiles = { ...(settings.stageProfiles || {}), [contextKey]: { ...previous, requirements: payload.requirements, conditions: payload.conditions } };
      storage.setItem('belavista.integrations.v1', JSON.stringify(settings));
      localPreferenceSaved = true;
      const state = input.appStore.get();
      input.appStore.set({ integrationSettings: { ...(state.integrationSettings || {}), stageProfiles: { ...(state.integrationSettings?.stageProfiles || {}), [contextKey]: { ...(state.integrationSettings?.stageProfiles?.[contextKey] || {}), requirements: payload.requirements, conditions: payload.conditions } } } });
    } catch { /* Local preference storage is optional; the service remains authoritative. */ }
    try {
      const response = await input.apiFetch(`/api/stages-admin/${stageId}/ai`, { method: 'PUT', headers: actorHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify(payload) });
      const result = asReport(await response.json()); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`));
      cache.set(stageId, asReport(result.stage || result));
      notify('Configuração de IA da etapa persistida.', 'success');
      await loadStage(stageId, true);
      return 'Requisitos, condições e contexto persistidos. O ciclo operacional pode usar essa configuração.';
    } catch (error) {
      globalThis.console.info('[stage-admin] persistência de IA indisponível', error);
      const prefix = localPreferenceSaved ? 'Contexto local salvo; persistência da etapa falhou' : 'Persistência da etapa falhou';
      return `${prefix}: ${error instanceof Error ? error.message : String(error)}`;
    }
  };

  viewController = installAtlasStageAdministrationViewV1({
    documentRef,
    windowRef,
    currentStageId,
    subscribe: listener => input.appStore.subscribe(() => listener()),
    onStageChanged: stageId => { if (stageId) cache.delete(stageId); },
    loadStage: (stageId, force) => { void loadStage(stageId, force); },
    onContextSubmit: saveDedicatedContext,
    onMetadataSubmit: saveMetadata,
    onRulesSubmit: saveAiRules,
  });
  return Object.freeze({ dispose: () => viewController?.dispose() });
}

/** Start the deferred stage-admin page with the shell's shared store and API owner. */
export async function startAtlasStageAdministrationEntryV1(input: {
  documentRef?: Document;
  windowRef?: Window & typeof globalThis;
  globalRef?: typeof globalThis;
} = {}): Promise<{ dispose(): void } | void> {
  const documentRef = input.documentRef || globalThis.document;
  const windowRef = input.windowRef || globalThis.window;
  const globalRef = (input.globalRef || globalThis) as typeof globalThis & AtlasApplicationRuntimeGlobalV1 & {
    __belavistaStageAdministrationControllerV1?: { dispose(): void };
  };
  if (!documentRef || !windowRef) throw new Error('A administração de etapas exige um documento ativo.');
  if (globalRef.__belavistaStageAdministrationControllerV1) return globalRef.__belavistaStageAdministrationControllerV1;
  const appStore = globalRef.__belavistaAppStore || initializeAtlasApplicationRuntimeV1({ globalRef }).appStore;
  const controller = installAtlasStageAdministrationV1({ appStore, apiFetch, document: documentRef, window: windowRef });
  globalRef.__belavistaStageAdministrationControllerV1 = controller;
  documentRef.documentElement.dataset.stageAdministrationOwnerV1 = 'typescript';
  return controller;
}

