interface AtlasExecutionPlanningRuntimeControllerV1 { dispose(): void }
const atlasExecutionPlanningControllersV1 = new WeakMap<Document, AtlasExecutionPlanningRuntimeControllerV1>();

/** Own the legacy execution-planning augmentation through typed DOM and API ports. */
export function installAtlasExecutionPlanningV1(input: AtlasExecutionPlanningHostPortsV1): AtlasExecutionPlanningRuntimeControllerV1 {
  const documentRef = input.document || globalThis.document;
  const windowRef = (input.window || documentRef?.defaultView || globalThis.window) as (Window & typeof globalThis) | undefined;
  if (!documentRef || !windowRef) throw new Error('O planejamento operacional precisa de um documento ativo.');
  const currentController = atlasExecutionPlanningControllersV1.get(documentRef);
  if (currentController) return currentController;

  const executionModel = ATLAS_STATE_CATALOGS_V1.executionModel as unknown as AtlasExecutionPlanningModelV1;
  const demoData = ATLAS_STATE_CATALOGS_V1.demoData as unknown as {
    activities: AtlasExecutionPlanningDemoActivityV1[];
    stageMaterials?: Record<string, Array<{ quantity?: number | null; [field: string]: unknown }>>;
  };
  const cashFlowSeed = ATLAS_STATE_CATALOGS_V1.cashFlowSeed as unknown as AtlasExecutionPlanningCashEntryV1[];
  const commissionDefaults = ATLAS_STATE_CATALOGS_V1.commissionReasonDefaults as unknown as AtlasBrokerCommissionReasonV1[];
  let apiCash: AtlasExecutionPlanningCashEntryV1[] = [];
  let cashSummary: AtlasExecutionPlanningCashSummaryV1 | null = null;
  let commissionReasons: AtlasBrokerCommissionReasonV1[] = [];
  let outsourcing: AtlasExecutionPlanningOutsourcingReceiptV1[] = [];
  let brokerReports: AtlasExecutionPlanningBrokerReportV1[] = [];
  let stopped = false;

  const asRecord = (value: unknown): Record<string, unknown> => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const recordRows = (value: unknown): Array<Record<string, unknown>> => Array.isArray(value) ? value.filter((row): row is Record<string, unknown> => Boolean(row && typeof row === 'object' && !Array.isArray(row))) : [];
  const normalize = (value: unknown): string => String(value ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const money = (cents: number): string => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format((Number(cents) || 0) / 100);
  const actorHeaders = (extra: Record<string, string> = {}): Record<string, string> => {
    const actor = asRecord(input.appStore.get().currentActor);
    const headers: Record<string, string> = { ...extra };
    if (actor.role) headers['x-belavista-role'] = String(actor.role);
    if (actor.uid) headers['x-belavista-user'] = String(actor.uid);
    if (actor.name) headers['x-belavista-name'] = String(actor.name);
    return headers;
  };
  const notify = (message: string, tone = 'info'): void => { windowRef.dispatchEvent(new CustomEvent('belavista:notify', { detail: { message, tone } })); };
  const readApi = async (path: string): Promise<Record<string, unknown>> => {
    const response = await input.apiFetch(path, { cache: 'no-store', headers: actorHeaders() });
    const payload: unknown = await response.json().catch(() => ({}));
    const result = asRecord(payload);
    if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`));
    return result;
  };
  const responseJson = async (response: Response): Promise<Record<string, unknown>> => {
    const payload: unknown = await response.json().catch(() => ({}));
    const result = asRecord(payload);
    if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`));
    return result;
  };
  const allCash = (): AtlasExecutionPlanningCashEntryV1[] => {
    const localCash = recordRows(input.appStore.get().cashFlowLocal) as AtlasExecutionPlanningCashEntryV1[];
    return [...cashFlowSeed, ...localCash, ...apiCash];
  };
  const calculateCash = (): AtlasExecutionPlanningCashSummaryV1 => {
    if (cashSummary) return cashSummary;
    return allCash().reduce((totals, entry) => {
      const amount = Number(entry.amountCents) || 0;
      if (entry.kind === 'entrada') totals.entriesCents += amount;
      else totals.exitsCents += amount;
      totals.balanceCents = totals.entriesCents - totals.exitsCents;
      return totals;
    }, { entriesCents: 0, exitsCents: 0, balanceCents: 0 });
  };
  const stageActivity = (plan: AtlasExecutionPlanningStagePlanV1): AtlasExecutionPlanningDemoActivityV1 => {
    const firstWord = normalize(plan.name).split(' ')[0] || '';
    return demoData.activities.find(activity => normalize(activity.name).includes(firstWord)) || demoData.activities[0] || { id: 0, name: plan.name, progress: 0 };
  };
  const readiness = (): Array<{ plan: AtlasExecutionPlanningStagePlanV1; stage: AtlasExecutionPlanningDemoActivityV1; dependencyDone: boolean; cashCoverage: number; materialScore: number; score: number }> => {
    const plans = executionModel.stages || [];
    const balance = calculateCash().balanceCents;
    const totalWeight = plans.reduce((total, plan) => total + (Number(plan.cashWeight) || 0), 0) || 1;
    return plans.map(plan => {
      const stage = stageActivity(plan);
      const overrides = asRecord(asRecord(input.appStore.get().productionOverrides)[String(stage.id)]);
      const production = { ...asRecord(plan.production), ...overrides };
      const dependencyDone = (plan.dependsOn || []).every(dependency => {
        const dependencyPlan = plans.find(candidate => candidate.key === dependency);
        const dependencyStage = dependencyPlan && stageActivity(dependencyPlan);
        return dependencyStage ? Number(dependencyStage.progress) >= 80 : true;
      });
      const envelope = Math.max(1, Math.round(280000000 * ((Number(plan.cashWeight) || 0) / totalWeight)));
      const cashCoverage = Math.max(0, Math.min(100, Math.round(balance / envelope * 100)));
      const materials = demoData.stageMaterials?.[stage.name] || [];
      const materialScore = Math.min(100, Math.round(((materials.filter(item => item.quantity != null).length || 1) / Math.max(1, materials.length || 1)) * 100));
      const score = Math.round((dependencyDone ? 35 : 5) + Math.min(35, cashCoverage * 0.35) + Math.min(30, materialScore * 0.3));
      // Keep the same production inputs live in the local application state.
      void production;
      return { plan, stage, dependencyDone, cashCoverage, materialScore, score };
    });
  };
  const projectCashPanel = (): AtlasExecutionPlanningCashPanelV1 => {
    const cash = calculateCash(), stages = readiness();
    const unfinished = stages.filter(item => Number(item.stage.progress) < 100).sort((left, right) => Number(right.plan.priority) - Number(left.plan.priority) || right.score - left.score);
    const next = unfinished[0] || stages[0];
    const suggestions: string[] = [];
    if (next && !next.dependencyDone) suggestions.push(`Concluir predecessoras antes de liberar ${next.stage.name}.`);
    if (next && next.cashCoverage < 70) suggestions.push(`Reservar caixa para ${next.stage.name}; cobertura estimada ${next.cashCoverage}%.`);
    if (next && next.materialScore < 75) suggestions.push(`Completar dimensionamento de materiais de ${next.stage.name}.`);
    if (next?.plan.key === 'electrical') suggestions.push('Rede elétrica está marcada como prioridade e deve anteceder pavimentação.');
    return {
      entries: money(cash.entriesCents), exits: money(cash.exitsCents), balance: money(cash.balanceCents),
      suggestedStage: next?.stage.name || '—', readiness: next?.score || 0, cashCoverage: next?.cashCoverage || 0,
      stages: stages.map(item => ({ id: item.stage.id, name: item.stage.name, score: item.score, selected: item.stage.name === next?.stage.name })),
      stageOptions: demoData.activities.map(activity => activity.name), suggestions,
      today: new Date().toISOString().slice(0, 10),
    };
  };
  const normalizedCommissionReasons = (): AtlasExecutionPlanningCommissionReasonV1[] => {
    const source = commissionReasons.length ? commissionReasons : commissionDefaults.map((reason, index) => ({ ...reason, sharePercent: [40, 30, 30][index] ?? reason.sharePercent }));
    return source.map(reason => ({ id: String(reason.id), label: String(reason.label || ''), sharePercent: Number(reason.sharePercent) || 0, description: String(reason.description || '') }));
  };
  const sourceNote = (): string => {
    const notes = executionModel.sourceNotes;
    const number = (value: number): string => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 2 }).format(Number(value) || 0);
    return `Terraplanagem: corte ${number(notes.earthwork.cutM3)} m³ · aterro ${number(notes.earthwork.fillM3)} m³ · compensação ${number(notes.earthwork.balanceM3)} m³. Drenagem: ~${number(notes.drainage.linearM)} m e ${number(notes.drainage.inlets)} bocas de lobo. Meio-fio: ~${number(notes.curbs.linearM)} m. Rede elétrica: ~${number(notes.electrical.poles)} postes. Rede de água: ${number(notes.water.targetLots)} lotes.`;
  };
  const componentController = installAtlasExecutionPlanningComponentControllerV1({ document: documentRef, window: windowRef });
  const createComponentSnapshot = (): AtlasExecutionPlanningComponentSnapshotV1 => {
    const view = String(input.appStore.get().view || '');
    return {
      view,
      cashPanel: view === 'assistant' ? projectCashPanel() : null,
      commissionReasons: normalizedCommissionReasons(),
      brokerReports,
      stageNames: demoData.activities.map(activity => activity.name),
      outsourcingReceipts: outsourcing,
      sourceNote: sourceNote(),
    };
  };
  const syncComponents = (): void => {
    if (stopped) return;
    componentController.update(createComponentSnapshot());
  };
  const parseCashSummary = (value: unknown): AtlasExecutionPlanningCashSummaryV1 | null => {
    const summary = asRecord(value);
    if (!('entriesCents' in summary) && !('exitsCents' in summary) && !('balanceCents' in summary)) return null;
    return { entriesCents: Number(summary.entriesCents) || 0, exitsCents: Number(summary.exitsCents) || 0, balanceCents: Number(summary.balanceCents) || 0 };
  };
  const loadApi = async (): Promise<void> => {
    const results = await Promise.allSettled([readApi('/api/cash-flow'), readApi('/api/commission-reasons'), readApi('/api/outsourcing-receipts'), readApi('/api/broker-reports')]);
    const cash = results[0]; if (cash.status === 'fulfilled') { apiCash = recordRows(cash.value.entries).map(entry => ({ ...entry, kind: String(entry.kind || ''), amountCents: Number(entry.amountCents) || 0 })); cashSummary = parseCashSummary(cash.value.summary); }
    const reasons = results[1]; if (reasons.status === 'fulfilled') commissionReasons = recordRows(reasons.value.reasons).map(reason => ({ id: String(reason.id || ''), label: String(reason.label || ''), description: String(reason.description || ''), active: reason.active !== false, sharePercent: Number(reason.sharePercent) || 0, warley: Number(reason.warley) || 0, partner: Number(reason.partner) || 0, payment: String(reason.payment || '') })).filter(reason => reason.id) as AtlasBrokerCommissionReasonV1[];
    const receipts = results[2]; if (receipts.status === 'fulfilled') outsourcing = recordRows(receipts.value.receipts).map(receipt => ({ contractor: String(receipt.contractor || ''), stage: String(receipt.stage || ''), service: String(receipt.service || ''), amountCents: Number(receipt.amountCents) || 0, fileUrl: String(receipt.fileUrl || '') }));
    const reports = results[3]; if (reports.status === 'fulfilled') brokerReports = recordRows(reports.value.files).map(file => ({ name: String(file.name || ''), month: String(file.month || ''), url: String(file.url || '') }));
    syncComponents();
  };
  const formStatus = (form: HTMLFormElement, selector: string, message: string): void => {
    const status = form.querySelector<HTMLElement>(selector);
    if (status) status.textContent = message;
  };
  const onCashSubmit = async (event: Event): Promise<void> => {
    const form = (event as CustomEvent<{ form?: HTMLFormElement }>).detail?.form;
    if (!form || !documentRef.contains(form)) return;
    const fields = new FormData(form);
    const payload = { kind: String(fields.get('kind') || ''), stage: String(fields.get('stage') || ''), date: String(fields.get('date') || ''), description: String(fields.get('description') || ''), category: 'Operação', amountCents: Math.round((Number(fields.get('amount')) || 0) * 100) };
    try {
      formStatus(form, '[data-v8-cash-status]', 'Salvando movimento…');
      const response = await input.apiFetch('/api/cash-flow', { method: 'POST', headers: actorHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify(payload) });
      const result = await responseJson(response);
      const entry = asRecord(result.entry);
      if (Object.keys(entry).length) apiCash = [{ ...entry, kind: String(entry.kind || payload.kind), amountCents: Number(entry.amountCents) || payload.amountCents }, ...apiCash];
      cashSummary = parseCashSummary(result.summary) || cashSummary;
      form.reset(); syncComponents();
      notify('Movimento registrado e caixa recalculado.', 'success');
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Falha ao registrar caixa.';
      formStatus(form, '[data-v8-cash-status]', message); notify(message, 'warning');
    }
  };
  const onCommissionSave = async (event: Event): Promise<void> => {
    const detail = (event as CustomEvent<{ form?: HTMLFormElement; id?: string }>).detail;
    const form = detail?.form, id = String(detail?.id || '');
    if (!form || !id || !documentRef.contains(form)) return;
    const fields = new FormData(form);
    try {
      const response = await input.apiFetch(`/api/commission-reasons/${encodeURIComponent(id)}`, { method: 'PUT', headers: actorHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify({ label: String(fields.get('label') || ''), description: String(fields.get('description') || ''), sharePercent: Number(fields.get('sharePercent')) || 0, active: true }) });
      const result = await responseJson(response);
      commissionReasons = recordRows(result.reasons).map(reason => ({ id: String(reason.id || ''), label: String(reason.label || ''), description: String(reason.description || ''), active: reason.active !== false, sharePercent: Number(reason.sharePercent) || 0, warley: Number(reason.warley) || 0, partner: Number(reason.partner) || 0, payment: String(reason.payment || '') })).filter(reason => reason.id) as AtlasBrokerCommissionReasonV1[];
      input.appStore.set({ commissionReasons, lastAction: `Atualizou regra de comissão ${id}` });
      syncComponents(); notify('Regra de comissão atualizada.', 'success');
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Falha ao atualizar regra de comissão.';
      const status = form.closest('[data-execution-planning-commission]')?.querySelector<HTMLElement>('[data-v8-commission-status]');
      if (status) status.textContent = message;
      notify(message, 'warning');
    }
  };
  const fileAsDataUrl = (file: File): Promise<string> => new Promise((resolve, reject) => {
    const reader = new windowRef.FileReader();
    reader.onerror = () => reject(reader.error || new Error('Falha ao ler o comprovante.'));
    reader.onload = () => resolve(String(reader.result || ''));
    reader.readAsDataURL(file);
  });
  const onOutsourcingSubmit = async (event: Event): Promise<void> => {
    const form = (event as CustomEvent<{ form?: HTMLFormElement }>).detail?.form;
    if (!form || !documentRef.contains(form)) return;
    const fields = new FormData(form), fileValue = fields.get('file');
    if (!(fileValue instanceof File) || !fileValue.size) { formStatus(form, '[data-v8-outsourcing-status]', 'Selecione o comprovante.'); return; }
    try {
      formStatus(form, '[data-v8-outsourcing-status]', 'Enviando comprovante…');
      const payload = { contractor: String(fields.get('contractor') || ''), stage: String(fields.get('stage') || ''), service: String(fields.get('service') || ''), amountCents: Math.round((Number(fields.get('amount')) || 0) * 100), issueDate: String(fields.get('issueDate') || ''), documentNumber: String(fields.get('documentNumber') || ''), notes: String(fields.get('notes') || ''), fileName: fileValue.name, dataUrl: await fileAsDataUrl(fileValue) };
      const response = await input.apiFetch('/api/outsourcing-receipts', { method: 'POST', headers: actorHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify(payload) });
      const result = await responseJson(response), receipt = asRecord(result.receipt);
      if (Object.keys(receipt).length) outsourcing = [{ contractor: String(receipt.contractor || payload.contractor), stage: String(receipt.stage || payload.stage), service: String(receipt.service || payload.service), amountCents: Number(receipt.amountCents) || payload.amountCents, fileUrl: String(receipt.fileUrl || '') }, ...outsourcing];
      syncComponents(); notify('Comprovante de terceirização armazenado.', 'success');
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Falha ao armazenar comprovante.';
      formStatus(form, '[data-v8-outsourcing-status]', message); notify(message, 'warning');
    }
  };
  const onFocusStage = (event: Event): void => {
    const id = Number((event as CustomEvent<{ stageId?: string }>).detail?.stageId);
    if (!id) return;
    input.appStore.set({ selectedStage: id, stageSelected: true, lastAction: 'Focou etapa sugerida pelo caixa' });
  };

  documentRef.addEventListener('atlas:execution-planning-cash-submit', onCashSubmit);
  documentRef.addEventListener('atlas:execution-planning-commission-save', onCommissionSave);
  documentRef.addEventListener('atlas:execution-planning-outsourcing-submit', onOutsourcingSubmit);
  documentRef.addEventListener('atlas:execution-planning-focus-stage', onFocusStage);
  const unsubscribe = input.appStore.subscribe?.(() => syncComponents()) || (() => undefined);
  syncComponents();
  void loadApi();

  const controller: AtlasExecutionPlanningRuntimeControllerV1 = Object.freeze({ dispose(): void {
    stopped = true; componentController.dispose(); unsubscribe();
    documentRef.removeEventListener('atlas:execution-planning-cash-submit', onCashSubmit);
    documentRef.removeEventListener('atlas:execution-planning-commission-save', onCommissionSave);
    documentRef.removeEventListener('atlas:execution-planning-outsourcing-submit', onOutsourcingSubmit);
    documentRef.removeEventListener('atlas:execution-planning-focus-stage', onFocusStage);
    atlasExecutionPlanningControllersV1.delete(documentRef);
  } });
  atlasExecutionPlanningControllersV1.set(documentRef, controller);
  return controller;
}

/** Resolve the already-started shell store and mount execution planning from the program root. */
export function startAtlasExecutionPlanningEntryV1(input: {
  documentRef?: Document;
  windowRef?: Window & typeof globalThis;
  globalRef?: typeof globalThis;
} = {}): ReturnType<typeof installAtlasExecutionPlanningV1> {
  const documentRef = input.documentRef || globalThis.document;
  const windowRef = input.windowRef || globalThis.window;
  const globalRef = (input.globalRef || globalThis) as typeof globalThis & AtlasApplicationRuntimeGlobalV1 & {
    __belavistaExecutionPlanningControllerV1?: ReturnType<typeof installAtlasExecutionPlanningV1>;
  };
  if (!documentRef || !windowRef) throw new Error('A inicialização do planejamento exige um documento ativo.');
  if (globalRef.__belavistaExecutionPlanningControllerV1) return globalRef.__belavistaExecutionPlanningControllerV1;
  const appStore = globalRef.__belavistaAppStore || initializeAtlasApplicationRuntimeV1({ globalRef }).appStore;
  const controller = installAtlasExecutionPlanningV1({ appStore, apiFetch, document: documentRef, window: windowRef });
  globalRef.__belavistaExecutionPlanningControllerV1 = controller;
  documentRef.documentElement.dataset.executionPlanningOwnerV1 = 'typescript';
  return controller;
}

