export interface AtlasFinalStageCalendarStageV5360 {
  id?: unknown;
  name?: unknown;
  status?: unknown;
  owner?: unknown;
  progress?: unknown;
  week?: unknown;
  date?: unknown;
  data?: unknown;
}

export interface AtlasFinalStageCalendarGroupV5360 {
  period: string;
  items: Array<{
    id: string;
    status: string;
    name: string;
    owner: string;
    progress: number;
    tone: string;
  }>;
}

export function projectAtlasFinalStageCalendarV5360(activities: readonly AtlasFinalStageCalendarStageV5360[] = []): AtlasFinalStageCalendarGroupV5360[] {
  const groups: AtlasFinalStageCalendarGroupV5360[] = [];
  activities.forEach((item, index) => {
    const period = activityPeriodV5360(item, index);
    let group = groups.find(entry => entry.period === period);
    if (!group) { group = { period, items: [] }; groups.push(group); }
    const progress = Math.max(0, Math.min(100, Number(item.progress) || 0));
    group.items.push({
      id: String(item.id || item.name || ''),
      status: String(item.status || 'Planejada'),
      name: String(item.name || 'Atividade'),
      owner: String(item.owner || 'Responsável a definir'),
      progress,
      tone: toneV5360(item.status),
    });
  });
  return groups;
}

export interface AtlasFinalWorkspacesStateV5360 {
  view?: string;
  selectedActivity?: unknown;
  activityDedicated?: boolean;
  lastAction?: string;
}

export interface AtlasFinalWorkspacesHostV5360 {
  ViewLayer: { prototype: HTMLElement & Record<string, any> };
  appStore: {
    get(): AtlasFinalWorkspacesStateV5360 & Record<string, any>;
    set(patch: Record<string, unknown>): unknown;
  };
  demoData: { activities?: AtlasFinalStageCalendarStageV5360[] };
  esc(value: unknown): string;
  document?: Document;
  window?: Window & typeof globalThis;
  globalRef?: Window & typeof globalThis;
  DateCtor?: DateConstructor;
}

export interface AtlasFinalWorkspacesControllerV5360 extends AtlasFinalStageCalendarComponentControllerV5360 {}

const atlasFinalWorkspacesControllersV5360 = new WeakMap<object, AtlasFinalWorkspacesControllerV5360>();

/** Own the final activity calendar and preserve the TypeScript records route installed by the shell. */
export function installAtlasFinalWorkspacesV5360(input: AtlasFinalWorkspacesHostV5360): AtlasFinalWorkspacesControllerV5360 {
  const windowRef = input.window || globalThis.window;
  const documentRef = input.document || windowRef?.document || globalThis.document;
  const globalRef = (input.globalRef || windowRef || globalThis) as Window & typeof globalThis & {
    __BELAVISTA_FINAL_WORKSPACES_V5360?: { version: string; installedAt: string; owner: string };
    installBelavistaFinalWorkspacesV5360?: () => boolean;
  };
  if (!windowRef || !documentRef) throw new Error('O calendário de atividades precisa de uma janela ativa.');
  const prototype = input.ViewLayer.prototype;
  const existing = atlasFinalWorkspacesControllersV5360.get(prototype);
  if (existing) return existing;
  const activities = (): AtlasFinalStageCalendarStageV5360[] => Array.isArray(input.demoData.activities) ? input.demoData.activities : [];
  const componentController = installAtlasFinalStageCalendarComponentControllerV5360({
    ViewLayer: input.ViewLayer as Parameters<typeof installAtlasFinalStageCalendarComponentControllerV5360>[0]['ViewLayer'],
    document: documentRef,
    window: windowRef,
    globalRef,
    renderCalendar: () => renderAtlasFinalStageCalendarV5360({ groups: projectAtlasFinalStageCalendarV5360(activities()), esc: input.esc }),
    onOpenActivity: activityKey => {
      const activity = activities().find(item => String(item.id || item.name || '') === activityKey);
      input.appStore.set({
        view: 'activities',
        selectedActivity: activity?.id || activity?.name || activityKey,
        activityDedicated: true,
        lastAction: `Abriu atividade ${activity?.name || activityKey}`,
      });
    },
  });
  let published = false;
  const install = (): boolean => {
    if (published) return true;
    const started = componentController.install();
    if (!started) return false;
    globalRef.__BELAVISTA_FINAL_WORKSPACES_V5360 = {
      version: '5.3.60',
      installedAt: new (input.DateCtor || globalThis.Date)().toISOString(),
      owner: 'typescript-final-after-deferred',
    };
    try { input.appStore.set({ lastAction: 'Workspaces finais v5.3.60 aplicados' }); } catch { /* Keep this visual extension independent of optional local status storage. */ }
    published = true;
    return true;
  };
  const controller: AtlasFinalWorkspacesControllerV5360 = Object.freeze({
    install,
    dispose(): void {
      delete globalRef.__BELAVISTA_FINAL_WORKSPACES_V5360;
      componentController.dispose();
      if (globalRef.installBelavistaFinalWorkspacesV5360 === install) delete globalRef.installBelavistaFinalWorkspacesV5360;
      atlasFinalWorkspacesControllersV5360.delete(prototype);
    },
  });
  globalRef.installBelavistaFinalWorkspacesV5360 = install;
  atlasFinalWorkspacesControllersV5360.set(prototype, controller);
  return controller;
}


